//GEMINI-pro DATASET v1.0 Category: Compression algorithms ; Style: complete
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    unsigned char *data;
    unsigned int size;
} compressed_data;

compressed_data *compress(unsigned char *data, unsigned int size) {
    compressed_data *compressed = malloc(sizeof(compressed_data));
    compressed->data = malloc(size);
    compressed->size = size;

    unsigned int i = 0, j = 0;
    while (i < size) {
        unsigned char byte = data[i];
        unsigned int count = 1;
        while (i + count < size && data[i + count] == byte) {
            count++;
        }
        compressed->data[j++] = byte;
        compressed->data[j++] = count;
        i += count;
    }

    compressed->size = j;
    return compressed;
}

unsigned char *decompress(compressed_data *compressed) {
    unsigned char *decompressed = malloc(compressed->size);
    unsigned int i = 0, j = 0;
    while (i < compressed->size) {
        unsigned char byte = compressed->data[i++];
        unsigned int count = compressed->data[i++];
        while (count--) {
            decompressed[j++] = byte;
        }
    }

    return decompressed;
}

int main() {
    unsigned char *data = "Hello, world!";
    unsigned int size = strlen(data);

    compressed_data *compressed = compress(data, size);
    unsigned char *decompressed = decompress(compressed);

    printf("%s\n", decompressed);

    free(compressed->data);
    free(compressed);
    free(decompressed);

    return 0;
}

//Falcon2-11B DATASET v1.0 Category: Cryptography Implementation ; Style: Claude Shannon
#include <stdio.h>
#include <string.h>

#define KEY_SIZE 26

char key[KEY_SIZE];

void encrypt(char* message, char* cipher) {
    int i, j, k;
    int length = strlen(message);
    for (i = 0; i < length; i++) {
        k = i % KEY_SIZE;
        j = message[i] - 'A';
        cipher[i] = ((j + key[k]) % 26) + 'A';
    }
}

void decrypt(char* cipher, char* message) {
    int i, j, k;
    int length = strlen(cipher);
    for (i = 0; i < length; i++) {
        k = i % KEY_SIZE;
        j = cipher[i] - 'A';
        message[i] = ((j - key[k]) % 26) + 'A';
    }
}

int main() {
    char message[100];
    char cipher[100];
    char decrypted[100];

    printf("Enter a message to encrypt: ");
    fgets(message, sizeof(message), stdin);

    printf("Enter a key: ");
    fgets(key, sizeof(key), stdin);

    encrypt(message, cipher);

    printf("Cipher text: %s\n", cipher);

    printf("Enter a cipher text to decrypt: ");
    fgets(cipher, sizeof(cipher), stdin);

    decrypt(cipher, decrypted);

    printf("Decrypted message: %s\n", decrypted);

    return 0;
}

