//find the maximim value in a tree

#include<iostream>
#include<stdio.h>
#include<stddef.h>
#include<malloc.h>
#include<limits.h>
#include<queue>
using namespace std;



struct treenode
{
    int data;
    struct treenode *left;
    struct treenode *right;

};


static struct treenode *add(int dat)
{
    struct treenode *temp=(struct treenode*)malloc(sizeof(struct treenode));
    temp->data=dat;
    temp->left=NULL;
    temp->right=NULL;
    return temp;


}
static int findmaxbypostorder(struct treenode *root)
{
    int root_val,max=INT_MIN,left,right;
    if(root)
    {
        root_val=root->data;
        left=findmaxbypostorder(root->left);
        right=findmaxbypostorder(root->right);

        if(left>right)max=left;
        else
            max=right;

        if(root_val>max)
        {
            max=root_val;
        }


    }
    return max;


}
int levelorder(struct treenode *root)
{
    queue<struct treenode *> q1;


    int root_val,max=INT_MIN;
    q1.push(root);

    while(!q1.empty())
    {
        struct treenode *temp=q1.front();

        root_val=temp->data;

        q1.pop();

        if(root_val>max)
        {
            max=root_val;
        }
        if(temp->left)
        {

            q1.push(temp->left);
        }
        if(temp->right)
        {
            q1.push(temp->right);
        }

    }
    return max;
}
int main()
{
    struct treenode *root=add(10);
    root->left=add(20);
    root->right=add(30);
    root->left->left=add(80);
    root->left->right=add(50);
    root->right->left=add(60);
    root->right->right=add(70);
    printf(" the max value is \n%d",findmaxbypostorder(root));
    printf(" the max value is \n%d",levelorder(root));
    return 0;
}

//LLAMA2-13B DATASET v1.0 Category: Linked list operations ; Style: medieval
#include <stdio.h>
#include <stdlib.h>

// Structure to represent a knight on the list
struct knight {
  int id;   // Unique identifier for each knight
  char name[20]; // Name of the knight
  int armor;  // Armor class for the knight
  int attack; // Attack strength for the knight
  struct knight *next; // Pointer to the next knight on the list
};

// Function to create a new knight and add it to the list
struct knight *add_knight(struct knight **head_ref, int id, char *name, int armor, int attack) {
  struct knight *new_knight = malloc(sizeof(struct knight));
  new_knight->id = id;
  strcpy(new_knight->name, name);
  new_knight->armor = armor;
  new_knight->attack = attack;
  new_knight->next = *head_ref;
  *head_ref = new_knight;
  return new_knight;
}

// Function to remove a knight from the list
struct knight *remove_knight(struct knight **head_ref, int id) {
  struct knight *current = *head_ref;
  struct knight *prev = NULL;

  while (current != NULL && current->id != id) {
    prev = current;
    current = current->next;
  }

  if (current != NULL) {
    if (prev == NULL) {
      *head_ref = current->next;
    } else {
      prev->next = current->next;
    }
    free(current);
    return current;
  }

  return NULL;
}

// Function to print all the knights on the list
void print_knights(struct knight *head) {
  while (head != NULL) {
    printf("%d: %s (%d armor, %d attack)\n", head->id, head->name, head->armor, head->attack);
    head = head->next;
  }
}

int main() {
  struct knight *head = NULL;

  // Add some knights to the list
  add_knight(&head, 1, "Sir Lancelot", 5, 10);
  add_knight(&head, 2, "Sir Gawain", 4, 8);
  add_knight(&head, 3, "Sir Percival", 3, 6);

  // Remove a knight from the list
  struct knight *removed = remove_knight(&head, 2);
  if (removed != NULL) {
    printf("Removed Sir Gawain from the list\n");
  } else {
    printf("Sir Gawain was not found on the list\n");
  }

  // Print all the knights on the list
  print_knights(head);

  return 0;
}

