#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define WIDTH 80
#define HEIGHT 60
#define CHAR_SET ".,-~:;=!*#@"

typedef struct {
    int x, y;
    int r, g, b;
} Pixel;

void draw_pixel(Pixel *img, int x, int y, int r, int g, int b) {
    int index = (r / 8) * 3 + (g / 8) + (b / 8) * WIDTH;
    printf("%c", CHAR_SET[index]);
}

void print_image(Pixel *img) {
    for (int i = 0; i < HEIGHT; i++) {
        for (int j = 0; j < WIDTH; j++) {
            draw_pixel(img, j, i, 0, 0, 0);
        }
        printf("\n");
    }
}

int main() {
    FILE *fp = fopen("image.bmp", "rb");
    if (fp == NULL) {
        printf("Error: Could not open image file.\n");
        return 1;
    }

    fseek(fp, 18, SEEK_SET);
    unsigned char header[54];
    fread(header, 1, 54, fp);

    int width = *(int *)&header[18];
    int height = *(int *)&header[22];

    Pixel *img = malloc(sizeof(Pixel) * width * height);

    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            fseek(fp, 54 + i * width * 3 + j * 3, SEEK_SET);
            unsigned char pixel[3];
            fread(pixel, 1, 3, fp);

            int r = pixel[0];
            int g = pixel[1];
            int b = pixel[2];

            img[i * width + j].x = j;
            img[i * width + j].y = i;
            img[i * width + j].r = r;
            img[i * width + j].g = g;
            img[i * width + j].b = b;
        }
    }

    print_image(img);

    free(img);
    fclose(fp);

    return 0;
}

