  int num_pages = 0;
  char *text = NULL;

  char line[MAX_LINE_LENGTH];
  while (fgets(line, MAX_LINE_LENGTH, fp) != NULL) {
    if (strncmp(line, "Title: ", 7) == 0) {
      title = strdup(line + 7);
    } else if (strncmp(line, "Author: ", 8) == 0) {
      author = strdup(line + 8);
    } else if (strncmp(line, "Num pages: ", 11) == 0) {
      num_pages = atoi(line + 11);
    } else if (strncmp(line, "Text: ", 6) == 0) {
      text = strdup(line + 6);
    }
  }

  fclose(fp);

  struct book *book = malloc(sizeof(struct book));
  book->title = title;
  book->author = author;
  book->num_pages = num_pages;
  book->text = text;

  return book;
}

void free_book(struct book *book) {
  free(book->title);
  free(book->author);
  free(book->text);
  free(book);
}

void print_book(struct book *book) {
  printf("Title: %s\n", book->title);
  printf("Author: %s\n", book->author);
  printf("Num pages: %d\n", book->num_pages);
  printf("Text: %s\n", book->text);
}

int main(int argc, char *argv[]) {
  if (argc != 2) {
    fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
    return EXIT_FAILURE;
  }

  struct book *book = load_book(argv[1]);
  if (book == NULL) {
    return EXIT_FAILURE;
  }

  print_book(book);
  free_book(book);

  return EXIT_SUCCESS;
}

