#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef struct {
    int r;
    int g;
    int b;
} RGB;

typedef struct {
    double h;
    double s;
    double l;
} HSL;

void rgbToHex(RGB rgb, char* hex) {
    sprintf(hex, "#%02X%02X%02X", rgb.r, rgb.g, rgb.b);
}

void hexToRgb(const char* hex, RGB* rgb) {
    if (strlen(hex) != 7 || hex[0] != '#') {
        fprintf(stderr, "Invalid HEX format.\n");
        exit(EXIT_FAILURE);
    }
    sscanf(hex + 1, "%02X%02X%02X", &rgb->r, &rgb->g, &rgb->b);
}

void rgbToHsl(RGB rgb, HSL* hsl) {
    double r = rgb.r / 255.0;
    double g = rgb.g / 255.0;
    double b = rgb.b / 255.0;
    double max = fmax(r, fmax(g, b));
    double min = fmin(r, fmin(g, b));
    double delta = max - min;

    // Calculate Hue
    if (delta == 0) {
        hsl->h = 0;
    } else if (max == r) {
        hsl->h = fmod(((g - b) / delta), 6);
    } else if (max == g) {
        hsl->h = ((b - r) / delta) + 2;
    } else {
        hsl->h = ((r - g) / delta) + 4;
    }
    hsl->h *= 60;
    if (hsl->h < 0) hsl->h += 360;

    // Calculate Lightness
    hsl->l = (max + min) / 2;

    // Calculate Saturation
    hsl->s = (delta == 0) ? 0 : (delta / (1 - fabs(2 * hsl->l - 1)));
}

void hslToRgb(HSL hsl, RGB* rgb) {
    double r, g, b;
    double c = (1 - fabs(2 * hsl.l - 1)) * hsl.s;
    double x = c * (1 - fabs(fmod(hsl.h / 60.0, 2) - 1));
    double m = hsl.l - c / 2.0;

    if (hsl.h < 60) {
        r = c; g = x; b = 0;
    } else if (hsl.h < 120) {
        r = x; g = c; b = 0;
    } else if (hsl.h < 180) {
        r = 0; g = c; b = x;
    } else if (hsl.h < 240) {
        r = 0; g = x; b = c;
    } else if (hsl.h < 300) {
        r = x; g = 0; b = c;
    } else {
        r = c; g = 0; b = x;
    }

    rgb->r = (int)((r + m) * 255);
    rgb->g = (int)((g + m) * 255);
    rgb->b = (int)((b + m) * 255);
}

int main() {
    int choice;
    printf("Color Code Converter\n");
    printf("1. RGB to HEX\n");
    printf("2. HEX to RGB\n");
    printf("3. RGB to HSL\n");
    printf("4. HSL to RGB\n");
    printf("Select an option (1-4): ");
    scanf("%d", &choice);

    switch(choice) {
        case 1: {
            RGB rgb;
            char hex[8];
            printf("Enter RGB values (r g b): ");
            scanf("%d %d %d", &rgb.r, &rgb.g, &rgb.b);
            rgbToHex(rgb, hex);
            printf("HEX code: %s\n", hex);
            break;
        }
        case 2: {
            char hex[8];
            RGB rgb;
            printf("Enter HEX code (e.g., #FF5733): ");
            scanf("%s", hex);
            hexToRgb(hex, &rgb);
            printf("RGB values: %d %d %d\n", rgb.r, rgb.g, rgb.b);
            break;
        }
        case 3: {
            RGB rgb;
            HSL hsl;
            printf("Enter RGB values (r g b): ");
            scanf("%d %d %d", &rgb.r, &rgb.g, &rgb.b);
            rgbToHsl(rgb, &hsl);
            printf("HSL values: %.2f %.2f %.2f\n", hsl.h, hsl.s, hsl.l);
            break;
        }
        case 4: {
            HSL hsl;
            RGB rgb;
            printf("Enter HSL values (h s l): ");
            scanf("%lf %lf %lf", &hsl.h, &hsl.s, &hsl.l);
            hslToRgb(hsl, &rgb);
            printf("RGB values: %d %d %d\n", rgb.r, rgb.g, rgb.b);
            break;
        }
        default:
            printf("Invalid choice. Please select a valid option.\n");
            break;
    }

    return 0;
}

