//MISTRAL-7B DATASET v1.0 Category: Hexadecimal Converter ; Style: sophisticated
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <ctype.h>

#define MAX_INPUT_LENGTH 50

// Function to validate hexadecimal string
int isValidHexString(const char* str) {
    int len = strlen(str);

    for (int i = 0; i < len; i++) {
        if (!isxdigit(str[i])) {
            return 0;
        }
    }

    return 1;
}

// Function to convert hexadecimal string to decimal
unsigned long long hexStringToDecimal(const char* str) {
    unsigned long long result = 0;
    unsigned long long power = 1;

    for (int i = strlen(str) - 1; i >= 0; i--) {
        if (isdigit(str[i])) {
            result += (str[i] - '0') * power;
        } else {
            result += (str[i] - 'A' + 10) * power;
        }
        power *= 16;
    }

    return result;
}

int main() {
    char input[MAX_INPUT_LENGTH];
    unsigned long long decimal;

    printf("Welcome to the Hexadecimal to Decimal Converter!\n");
    printf("Enter a valid hexadecimal string (up to %d characters): ", MAX_INPUT_LENGTH);

    fgets(input, MAX_INPUT_LENGTH, stdin);
    input[strcspn(input, "\n")] = '\0'; // Remove newline character

    if (!isValidHexString(input)) {
        printf("Invalid hexadecimal string.\n");
        return 1;
    }

    decimal = hexStringToDecimal(input);
    printf("The decimal equivalent of the given hexadecimal string is: %llu\n", decimal);

    return 0;
}

