#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define PORT 8080

int main() {
    // Create a socket
    int socket_fd;
    if ((socket_fd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("Error creating socket");
        exit(EXIT_FAILURE);
    }

    // Create an address structure
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Bind the socket to the address
    if (bind(socket_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Error binding socket");
        exit(EXIT_FAILURE);
    }

    // Start listening for incoming connections
    if (listen(socket_fd, 5) < 0) {
        perror("Error listening on socket");
        exit(EXIT_FAILURE);
    }

    printf("Chat server is listening on port %d...\n", PORT);

    while (1) {
        // Accept a new connection
        struct sockaddr_in client_addr;
        socklen_t addr_len = sizeof(client_addr);
        int client_fd = accept(socket_fd, (struct sockaddr *)&client_addr, &addr_len);
        if (client_fd < 0) {
            perror("Error accepting connection");
            exit(EXIT_FAILURE);
        }

        printf("Connected with %s:%d\n", inet_ntoa(client_addr.sin_addr), ntohs(client_addr.sin_port));

        // Read data from the client
        char buffer[256];
        int n = read(client_fd, buffer, sizeof(buffer));
        if (n < 0) {
            perror("Error reading from client");
            exit(EXIT_FAILURE);
        }
        buffer[n] = '\0';
        printf("Received: %s\n", buffer);

        // Send a response to the client
        if (send(client_fd, "Hello, world!", sizeof("Hello, world!"), 0) < 0) {
            perror("Error sending to client");
            exit(EXIT_FAILURE);
        }

        // Close the connection
        close(client_fd);
    }

    return 0;
}

