            str[i] = 'x';
        }
    }
}

// Function to reverse a string
void reverse(char *str) {
    int i = 0, j = strlen(str) - 1;
    while (i < j) {
        char temp = str[i];
        str[i] = str[j];
        str[j] = temp;
        i++;
        j--;
    }
}

// Function to check if a string is a palindrome
int is_palindrome(char *str) {
    int i = 0, j = strlen(str) - 1;
    while (i < j) {
