/*
 * Game of Life: Single-threaded example
 */
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define GRID_SIZE 100
#define ALIVE 1
#define DEAD 0

int grid[GRID_SIZE][GRID_SIZE];

int main() {
    // Initialize the grid
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < GRID_SIZE; j++) {
            grid[i][j] = DEAD;
        }
    }

    // Randomly set some cells to alive
    for (int i = 0; i < 10; i++) {
        int row = rand() % GRID_SIZE;
        int col = rand() % GRID_SIZE;
        grid[row][col] = ALIVE;
    }

    // Print the initial state of the grid
    printf("Initial state:\n");
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < GRID_SIZE; j++) {
            printf("%d ", grid[i][j]);
        }
        printf("\n");
    }

    // Evolve the grid
    for (int i = 0; i < 100; i++) {
        // Create a new grid
        int new_grid[GRID_SIZE][GRID_SIZE];

        // Apply the rules of the Game of Life
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                int alive_neighbors = 0;
                for (int dr = -1; dr <= 1; dr++) {
                    for (int dc = -1; dc <= 1; dc++) {
                        if (dr == 0 && dc == 0) continue;
                        int r = (row + dr + GRID_SIZE) % GRID_SIZE;
                        int c = (col + dc + GRID_SIZE) % GRID_SIZE;
                        if (grid[r][c] == ALIVE) alive_neighbors++;
                    }
                }

                if (alive_neighbors < 2 || alive_neighbors > 3) {
                    new_grid[row][col] = DEAD;
                } else if (alive_neighbors == 3) {
                    new_grid[row][col] = ALIVE;
                } else {
                    new_grid[row][col] = grid[row][col];
                }
            }
        }

        // Copy the new grid back to the old grid
        for (int i = 0; i < GRID_SIZE; i++) {
            for (int j = 0; j < GRID_SIZE; j++) {
                grid[i][j] = new_grid[i][j];
            }
        }
    }

    // Print the final state of the grid
    printf("Final state:\n");
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < GRID_SIZE; j++) {
            printf("%d ", grid[i][j]);
        }
        printf("\n");
    }

    return 0;
}

