#define MAX_CARS 10
#define MAX_LANE 3

typedef struct Car {
  int x, y, dir, speed;
} Car;

Car cars[MAX_CARS];

void initializeCars() {
  for (int i = 0; i < MAX_CARS; i++) {
    cars[i].x = rand() % MAX_LANE;
    cars[i].y = rand() % MAX_LANE;
    cars[i].dir = rand() % 4;
    cars[i].speed = rand() % 5 + 1;
  }
}

void updateCars() {
  for (int i = 0; i < MAX_CARS; i++) {
    switch (cars[i].dir) {
      case 0:
        cars[i].x++;
        break;
      case 1:
        cars[i].x--;
        break;
      case 2:
        cars[i].y++;
        break;
      case 3:
        cars[i].y--;
        break;
    }

    if (cars[i].x >= MAX_LANE) {
      cars[i].dir = 1;
    }

    if (cars[i].x <= 0) {
      cars[i].dir = 0;
    }

    if (cars[i].y >= MAX_LANE) {
      cars[i].dir = 3;
    }

    if (cars[i].y <= 0) {
      cars[i].dir = 2;
    }

    cars[i].speed--;
