#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <time.h>

#define PORT 8080
#define MAX_PLAYERS 4

// Structure to represent a player
struct player {
    int id;
    char name[20];
    int pieces[8][8];
};

// Function to initialize a player
void init_player(struct player *p) {
    for (int i = 0; i < 8; i++) {
        for (int j = 0; j < 8; j++) {
            p->pieces[i][j] = 0;
        }
    }
}

// Function to make a move
void make_move(struct player *p, int from_row, int from_col, int to_row, int to_col) {
    if (p->pieces[from_row][from_col] == 1) {
        p->pieces[to_row][to_col] = 1;
        p->pieces[from_row][from_col] = 0;
    }
}

// Function to check if a player has won
int check_win(struct player *p) {
    int rows[] = {0, 1, 2, 3, 4, 5, 6, 7};
    int cols[] = {0, 1, 2, 3, 4, 5, 6, 7};
    int i, j;

    for (i = 0; i < 8; i++) {
        for (j = 0; j < 8; j++) {
            if (p->pieces[i][j] == 1 && (rows[i] == p->id || cols[j] == p->id)) {
                return 1;
            }
        }
    }

    return 0;
}

// Function to print the board
void print_board(struct player *p) {
    int i, j;

    for (i = 0; i < 8; i++) {
        for (j = 0; j < 8; j++) {
            printf("%d ", p->pieces[i][j]);
        }
        printf("\n");
    }
}

int main() {
    int sock, client_sock;
    struct sockaddr_in server, client;
    struct player player;
    char buffer[1024];

    // Create a socket
    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("Socket creation failed");
        exit(1);
    }

    // Set up the server address
    memset(&server, 0, sizeof(server));
    server.sin_family = AF_INET;
    server.sin_port = htons(PORT);
    inet_pton(AF_INET, "127.0.0.1", &server.sin_addr);

    // Bind the socket to the address and port
    if (bind(sock, (struct sockaddr *)&server, sizeof(server)) < 0) {
        perror("Binding failed");
        exit(1);
    }

    // Listen for incoming connections
    if (listen(sock, MAX_PLAYERS) < 0) {
        perror("Listening failed");
        exit(1);
    }

    printf("Waiting for connections...\n");

    // Accept an incoming connection
    client_sock = accept(sock, (struct sockaddr *)&client, (socklen_t*)&client.sin_addr);
    if (client_sock < 0) {
        perror("Accept failed");
        exit(1);
    }

    // Initialize the player structure
    init_player(&player);

    // Loop until the game is over
    while (1) {
        // Receive a move from the client
        recv(client_sock, buffer, 1024, 0);
        int from_row = atoi(buffer);
        int from_col = atoi(buffer + 1);
        int to_row = atoi(buffer + 2);
        int to_col = atoi(buffer + 3);

        // Make the move on the server
        make_move(&player, from_row, from_col, to_row, to_col);

        // Check if the game is over
        if (check_win(&player)) {
            printf("Game over! Player %d has won.\n", player.id);
            break;
        }

        // Send the updated board to the client
        send(client_sock, buffer, 1024, 0);
        print_board(&player);
    }

    // Close the socket
    close(client_sock);

    return 0;
}

