#define MAX_LENGTH 100

// A struct to represent a person's name
typedef struct {
    char first_name[MAX_LENGTH];
    char last_name[MAX_LENGTH];
} Person;

// A function to sort an array of Person structs by first name
void sort_by_first_name(Person arr[], int len) {
    int i, j, min_idx;

    // Find the first element that is not in sorted order
    for (i = 0; i < len - 1; i++) {
        for (j = i + 1; j < len; j++) {
            if (strcmp(arr[i].first_name, arr[j].first_name) > 0) {
                min_idx = i;
                break;
            }
        }

        // Swap the first element with the smallest one
        if (min_idx != i) {
            Person temp = arr[min_idx];
            arr[min_idx] = arr[i];
            arr[i] = temp;
        }
    }
}

int main() {
    // Create an array of Person structs
    Person arr[5] = {
        {"Alice", "Smith"},
        {"Bob", "Johnson"},
        {"Charlie", "Brown"},
        {"David", "Jones"},
        {"Eve", "Williams"}
    };

    // Sort the array by first name
    sort_by_first_name(arr, sizeof(arr) / sizeof(arr[0]));

    // Print the sorted array
    for (int i = 0; i < sizeof(arr) / sizeof(arr[0]); i++) {
        printf("%s %s\n", arr[i].first_name, arr[i].last_name);
    }

    return 0;
}

