/*
 * Unique C Traffic Light Controller Example Program
 *
 * This program is an example of a traffic light controller written in the C programming language.
 * It uses a state machine to control the traffic lights and their timing.
 *
 * The program starts by defining the states of the traffic lights:
 *  - red
 *  - yellow
 *  - green
 *
 * It then defines the duration of each state, as well as the time between each state.
 *
 * The program then enters an infinite loop, where it updates the state of the traffic lights
 * based on the current time and the duration of each state.
 *
 * When the traffic light is in the red state, it remains red for a certain amount of time.
 * When the traffic light is in the yellow state, it remains yellow for a certain amount of time.
 * When the traffic light is in the green state, it remains green for a certain amount of time.
 *
 * After each state, the program waits for a certain amount of time before moving to the next state.
 */

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the states of the traffic lights
#define RED 1
#define YELLOW 2
#define GREEN 3

// Define the duration of each state
#define RED_DURATION 10
#define YELLOW_DURATION 2
#define GREEN_DURATION 10

// Define the time between each state
#define TIME_BETWEEN_STATES 10

// Define the current state of the traffic lights
int state = RED;

int main() {
    // Initialize the current time
    time_t current_time = time(NULL);

    // Loop indefinitely
    while (1) {
        // Update the current state of the traffic lights based on the current time
        if (state == RED) {
            // If the current state is red, check if the duration has elapsed
            if (difftime(current_time, time(NULL)) > RED_DURATION) {
                // If the duration has elapsed, move to the yellow state
                state = YELLOW;
            }
        } else if (state == YELLOW) {
            // If the current state is yellow, check if the duration has elapsed
            if (difftime(current_time, time(NULL)) > YELLOW_DURATION) {
                // If the duration has elapsed, move to the green state
                state = GREEN;
            }
        } else if (state == GREEN) {
            // If the current state is green, check if the duration has elapsed
            if (difftime(current_time, time(NULL)) > GREEN_DURATION) {
                // If the duration has elapsed, move to the red state
                state = RED;
            }
        }

        // Wait for a certain amount of time before moving to the next state
        sleep(TIME_BETWEEN_STATES);
    }

    return 0;
}

