void PrintAll(int n, int sum, int first, vector<int> &result) {
  if (n < 0)
    return;
  else if (n == 0) {
    if (sum == 0) {
      // if we need to consider all permutations,
      // we could use next_permutaion() here
      cout << "Found: ";
      for (int i = 0; i < result.size(); i++)
        cout << result[i] << " ";
