#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/wait.h>
#include <sys/ipc.h>
#include <sys/msg.h>

#define MAX_MSG_SIZE 1024
#define MAX_WAIT_TIME 10

// message structure
typedef struct {
    long mtype;
    char mtext[MAX_MSG_SIZE];
} message;

// function prototypes
void send_message(int msg_queue_id, char *message_text);
message receive_message(int msg_queue_id);

int main() {
    int msg_queue_id = msgget(IPC_PRIVATE, 0666 | IPC_CREAT);
    if (msg_queue_id == -1) {
        printf("Error creating message queue\n");
        exit(1);
    }

    pid_t child_pid = fork();
    if (child_pid == -1) {
        printf("Error forking process\n");
        exit(1);
    }

    if (child_pid == 0) {
        // child process
        send_message(msg_queue_id, "Hello from child process!");
        exit(0);
    } else {
        // parent process
        message received_message = receive_message(msg_queue_id);
        printf("Received message: %s\n", received_message.mtext);
        exit(0);
    }
}

void send_message(int msg_queue_id, char *message_text) {
    message message_to_send;
    strcpy(message_to_send.mtext, message_text);
    message_to_send.mtype = 1;

    if (msgsnd(msg_queue_id, &message_to_send, strlen(message_to_send.mtext), 0) == -1) {
        printf("Error sending message\n");
        exit(1);
    }
}

message receive_message(int msg_queue_id) {
    message received_message;
    int message_size = 0;

    if (msgrcv(msg_queue_id, &received_message, MAX_MSG_SIZE, 0, 0) == -1) {
        printf("Error receiving message\n");
        exit(1);
    }

    return received_message;
}

