    if (index != -1) // the item was found
    {
        count = this->dict[index].count;
        this->remove(index);
    }
    else return 0;
}

bool Multiset::contains(const ItemType& value) const
{
    if (this->find(value) != -1)
        return true;
    else
        return false;
}

int Multiset::count(const ItemType& value) const
{
