    if (index == -1) // item was not found
        return 0;
    return dict[index].count;
}

int Multiset::get(int i, ItemType& value)
{
    if (i >= 0 && i < this->dict_size)
    {
        value = this->dict[i].name;
        return this->dict[i].count;
    }
    else return 0; // index requested is out of bounds
}

void Multiset::swap(Multiset& other)
{
    Item tmp[DEFAULT_MAX_ITEMS]; // create a temporary array
    int tmp_size = this->dict_size;
    for (int i = 0; i < this->dict_size; i++) // copy current items into tmp
    {
        tmp[i] = this->dict[i];
    }
    for (int i = 0; i < other.uniqueSize(); i++) // copy other's items into current
    {
        ItemType name;
        int count = other.get(i, name);
        Item to_add;
        to_add.name = name;
        to_add.count = count;
        this->dict[i] = to_add;
    }
    this->dict_size = other.uniqueSize(); // update current's size
    for (int i = 0; i < tmp_size; i++)
    {
       other.dict[i] = tmp[i]; 
    }
    other.dict_size = tmp_size;
}

int Multiset::find(const ItemType& value) const
{
    for (int i = 0; i < this->dict_size; i++)
    {
        if (this->dict[i].name == value)
            return i;
    }
    return -1; // not found
}

bool Multiset::remove(int index)
{
    if (index >= 0 && index < this->dict_size)
    {
        for (int i = index; i < this->dict_size-1; i++)
        // shift all following elements over
        {
            this->dict[i] = this->dict[i+1];
        }
        this->dict_size--;
        return true;
    }
    else return false;
}

//GEMINI-pro DATASET v1.0 Category: Task Scheduler ; Style: rigorous
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <string.h>

// Define the task structure
typedef struct task {
    char *command;  // The command to execute
    int delay;      // The delay in seconds before executing the command
    int pid;        // The process ID of the task
} task;

// Create a new task
task *create_task(char *command, int delay) {
    task *new_task = malloc(sizeof(task));
    new_task->command = strdup(command);
    new_task->delay = delay;
    new_task->pid = -1;
    return new_task;
}

// Free the memory allocated for a task
void free_task(task *task) {
    free(task->command);
    free(task);
}

// Execute a task
int execute_task(task *task) {
    // Fork a new process
    int pid = fork();
    if (pid == 0) {
        // Child process
        execlp("/bin/sh", "sh", "-c", task->command, NULL);
        perror("execlp");
        exit(EXIT_FAILURE);
    } else if (pid > 0) {
        // Parent process
        task->pid = pid;
        return 0;
    } else {
        // Error
        perror("fork");
        return -1;
    }
}

// Wait for a task to complete
int wait_for_task(task *task) {
    int status;
    pid_t pid = waitpid(task->pid, &status, 0);
    if (pid == -1) {
        perror("waitpid");
        return -1;
    } else if (WIFEXITED(status)) {
        return WEXITSTATUS(status);
    } else {
        return -1;
    }
}

// Main function
int main(int argc, char *argv[]) {
    // Create a task queue
    task *queue[100];
    int queue_size = 0;

    // Add tasks to the queue
    queue[queue_size++] = create_task("echo Hello, world!", 1);
    queue[queue_size++] = create_task("sleep 5", 5);
    queue[queue_size++] = create_task("echo Goodbye, world!", 1);

    // Execute the tasks
    for (int i = 0; i < queue_size; i++) {
        execute_task(queue[i]);
    }

    // Wait for the tasks to complete
    for (int i = 0; i < queue_size; i++) {
        wait_for_task(queue[i]);
    }

    // Free the memory allocated for the tasks
    for (int i = 0; i < queue_size; i++) {
        free_task(queue[i]);
    }

    return 0;
}

//GPT-4o-mini DATASET v1.0 Category: Binary search trees ; Style: authentic
#include <stdio.h>
#include <stdlib.h>

// Structure for a binary search tree node
struct Node {
    int data;
    struct Node* left;
    struct Node* right;
};

// Function to create a new node
struct Node* createNode(int data) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = data;
    newNode->left = NULL;
    newNode->right = NULL;
    return newNode;
}

// Function to insert a new node into the binary search tree
struct Node* insert(struct Node* root, int data) {
    if (root == NULL) {
        return createNode(data);
    }
    if (data < root->data) {
        root->left = insert(root->left, data);
    } else {
        root->right = insert(root->right, data);
    }
    return root;
}

// Function to print the tree in-order
void inOrder(struct Node* root) {
    if (root != NULL) {
        inOrder(root->left);
        printf("%d ", root->data);
        inOrder(root->right);
    }
}

// Function to search for a value in the tree
struct Node* search(struct Node* root, int key) {
    if (root == NULL || root->data == key)
        return root;
    if (key < root->data)
        return search(root->left, key);
    return search(root->right, key);
}

// Function to find the minimum value node in the tree
struct Node* minValueNode(struct Node* node) {
    struct Node* current = node;
    while (current && current->left != NULL)
        current = current->left;
    return current;
}

// Function to delete a node from the binary search tree
struct Node* deleteNode(struct Node* root, int key) {
    if (root == NULL) return root;

    // Traverse the tree
    if (key < root->data)
        root->left = deleteNode(root->left, key);
    else if (key > root->data)
        root->right = deleteNode(root->right, key);
    else {
        // Node with only one child or no child
        if (root->left == NULL) {
            struct Node* temp = root->right;
            free(root);
            return temp;
        } else if (root->right == NULL) {
            struct Node* temp = root->left;
            free(root);
            return temp;
        }

        // Node with two children: Get the inorder successor
        struct Node* temp = minValueNode(root->right);
        root->data = temp->data;
        root->right = deleteNode(root->right, temp->data);
    }
    return root;
}

// Function to free the entire tree
void freeTree(struct Node* root) {
    if (root != NULL) {
        freeTree(root->left);
        freeTree(root->right);
        free(root);
    }
}

// Driver program
int main() {
    struct Node* root = NULL;
    int choice, value;

    while (1) {
        printf("\nBinary Search Tree Operations:\n");
        printf("1. Insert\n");
        printf("2. Search\n");
        printf("3. Delete\n");
        printf("4. In-order Traversal\n");
        printf("5. Exit\n");
        printf("Select an option: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                printf("Enter value to insert: ");
                scanf("%d", &value);
                root = insert(root, value);
                printf("Inserted %d successfully.\n", value);
                break;

            case 2:
                printf("Enter value to search: ");
                scanf("%d", &value);
                struct Node* foundNode;
                foundNode = search(root, value);
                if (foundNode != NULL)
                    printf("Found %d in the tree.\n", value);
                else
                    printf("%d not found in the tree.\n", value);
                break;

            case 3:
                printf("Enter value to delete: ");
                scanf("%d", &value);
                root = deleteNode(root, value);
                printf("Deleted %d from the tree.\n", value);
                break;

            case 4:
                printf("In-order traversal: ");
                inOrder(root);
                printf("\n");
                break;

            case 5:
                freeTree(root);
                printf("Exiting the program.\n");
                exit(0);
                break;

            default:
                printf("Invalid option. Please try again.\n");
        }
    }

    return 0;
}

