#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_ORDER 3
#define VOCAB_SIZE 26

typedef struct {
    int count[VOCAB_SIZE][VOCAB_SIZE];
    int total;
} MarkovModel;

void initModel(MarkovModel *model) {
    memset(model, 0, sizeof(MarkovModel));
    model->total = 1;
}

void trainModel(MarkovModel *model, const char *text) {
    int len = strlen(text);
    for (int i = 0; i < len - MAX_ORDER; i++) {
        char current = text[i] & 0x1F; // Filter out control characters
        char next = text[i + MAX_ORDER] & 0x1F;
        model->count[current][next]++;
        model->total++;
    }
}

char predict(MarkovModel model, char current) {
    float probSum = 0;
    for (int i = 0; i < VOCAB_SIZE; i++) {
        probSum += model.count[current][i] / model.total;
    }

    float randNum = (float) rand() / RAND_MAX;
    float cumProb = 0;
    for (int i = 0; i < VOCAB_SIZE; i++) {
        cumProb += model.count[current][i] / model.total;
        if (cumProb > randNum)
            return (char) i;
    }
    return '\0';
}

int main() {
    MarkovModel model;
    initModel(&model);

    char *englishText = "The quick brown fox jumps over the lazy dog.";
    trainModel(&model, englishText);

    char *input = "The quick brown ";
    char output[MAX_ORDER + 1];

    for (int i = 0; i < strlen(input) / (MAX_ORDER + 1); i++) {
        char current = input[i * (MAX_ORDER + 1) + MAX_ORDER] & 0x1F;
        strncat(output, predict(model, current), 1);
        printf("%s", output);

        if ((i + 1) * (MAX_ORDER + 1) < strlen(input)) {
            printf(" %s", input + (i + 1) * (MAX_ORDER + 1));
            strcpy(output, "");
        }
    }
    printf("\n");

    return 0;
}

