// Function to get the current date and time
void get_timestamp(time_t *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    *timestamp = mktime(timeinfo);
}

