#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>

#define WIDTH 80
#define HEIGHT 25

// Structure to store the state of the turtle
typedef struct {
    int x, y;  // Position of the turtle
    char direction;  // Direction of the turtle (N, S, E, W)
    int speed;  // Speed of the turtle
} Turtle;

// Function to initialize the turtle
void initTurtle(Turtle *t) {
    t->x = 0;
    t->y = 0;
    t->direction = 'N';
    t->speed = 1;
}

// Function to move the turtle
void moveTurtle(Turtle *t) {
    switch (t->direction) {
        case 'N':
            t->x++;
            break;
        case 'S':
            t->x--;
            break;
        case 'E':
            t->y++;
            break;
        case 'W':
            t->y--;
            break;
    }
}

// Function to print the turtle's position
void printTurtle(Turtle *t) {
    printf("%d, %d", t->x, t->y);
}

// Function to draw a line using the turtle
void drawLine(Turtle *t, int x1, int y1, int x2, int y2) {
    int x = t->x;
    int y = t->y;
    int dx = x2 - x1;
    int dy = y2 - y1;
    int distance = sqrt(dx * dx + dy * dy);
    int step = distance / t->speed;

    for (int i = 0; i < step; i++) {
        moveTurtle(t);
        printTurtle(t);
    }

    moveTurtle(t);
    printTurtle(t);
}

int main() {
    Turtle t;
    initTurtle(&t);

    // Draw a line from (0, 0) to (50, 25)
    drawLine(&t, 0, 0, 50, 25);

    // Draw a line from (50, 25) to (25, 50)
    drawLine(&t, 50, 25, 25, 50);

    // Draw a line from (25, 50) to (75, 75)
    drawLine(&t, 25, 50, 75, 75);

    // Draw a line from (75, 75) to (100, 100)
    drawLine(&t, 75, 75, 100, 100);

    return 0;
}

