/*
 * C Database Querying Example Program
 *
 * This program demonstrates how to query a database using the C programming language.
 * It uses the SQLITE library to connect to a SQLite database and execute a SELECT statement.
 *
 * Usage:
 *      gcc -o query query.c -lsqlite3
 *      ./query
 *
 * Author: [Your Name]
 */

#include <stdio.h>
#include <stdlib.h>
#include <sqlite3.h>

int main() {
    // Open the database
    sqlite3 *db;
    int rc = sqlite3_open("example.db", &db);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Cannot open database: %s\n", sqlite3_errmsg(db));
        sqlite3_close(db);
        return 1;
    }

    // Prepare the SQL statement
    sqlite3_stmt *stmt;
    rc = sqlite3_prepare_v2(db, "SELECT * FROM customers WHERE city = 'New York'", -1, &stmt, NULL);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Cannot prepare SQL statement: %s\n", sqlite3_errmsg(db));
        sqlite3_finalize(stmt);
        sqlite3_close(db);
        return 1;
    }

    // Execute the SQL statement
    rc = sqlite3_step(stmt);
    if (rc != SQLITE_DONE) {
        fprintf(stderr, "Cannot execute SQL statement: %s\n", sqlite3_errmsg(db));
        sqlite3_finalize(stmt);
        sqlite3_close(db);
        return 1;
    }

    // Print the results
    while (sqlite3_step(stmt) == SQLITE_ROW) {
        int id = sqlite3_column_int(stmt, 0);
        const char *name = (const char *)sqlite3_column_text(stmt, 1);
        const char *email = (const char *)sqlite3_column_text(stmt, 2);
        const char *city = (const char *)sqlite3_column_text(stmt, 3);
        printf("ID: %d, Name: %s, Email: %s, City: %s\n", id, name, email, city);
    }

    // Finalize the statement
    sqlite3_finalize(stmt);

    // Close the database
    sqlite3_close(db);

    return 0;
}

