//LLAMA2-13B DATASET v1.0 Category: Sorting ; Style: puzzling
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAGIC_NUMBER 42

void sort_puzzle(int arr[], int n) {
  int i, j, k, swapped = 1;
  while (swapped) {
    swapped = 0;
    for (i = 0; i < n - 1; i++) {
      for (j = i + 1; j < n; j++) {
        if (arr[i] > arr[j]) {
          // Find the right spot for the smaller element
          k = i;
          while (k > 0 && arr[k - 1] > arr[j]) k--;
          // Swap the elements
          if (k != i) {
            swap(arr[k], arr[i]);
            swapped = 1;
          }
        }
      }
    }
  }
}

int main() {
  int arr[5] = {3, 6, 1, 4, 2};
  int n = sizeof(arr) / sizeof(arr[0]);
  clock_t start, end;
  double time_taken;

  // Start the timer
  start = clock();

  // Sort the array using the puzzle sorting algorithm
  sort_puzzle(arr, n);

  // End the timer
  end = clock();

  // Calculate the time taken
  time_taken = (double)(end - start) / CLOCKS_PER_SEC;

  // Print the result
  printf("Sorting time: %f seconds\n", time_taken);

  return 0;
}

void swap(int *a, int *b) {
  int temp = *a;
  *a = *b;
  *b = temp;
}

//GPT-4o-mini DATASET v1.0 Category: Breakout Game Clone ; Style: modular
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <unistd.h>
#include <termios.h>
#include <string.h>
#include <ncurses.h>

#define WIDTH 40
#define HEIGHT 20
#define PADDLE_WIDTH 7
#define BRICK_ROWS 5
#define BRICK_COLS 10

typedef struct {
    int x, y;
} Ball;

typedef struct {
    int x, y;
    int width;
} Paddle;

typedef struct {
    bool active;
    int x, y;
} Brick;

Ball ball;
Paddle paddle;
Brick bricks[BRICK_ROWS][BRICK_COLS];

void init_game();
void draw();
void update();
void reset_ball();
bool check_collision();
void draw_bricks();
void cleanup();

int main() {
    init_game();

    while (true) {
        draw();
        if (check_collision()) break; // Check for game over

        update();
        usleep(50000); // Control speed of the game
    }

    cleanup();
    return 0;
}

void init_game() {
    initscr();
    noecho();
    curs_set(0);
    timeout(100); // Non-blocking input

    paddle.x = WIDTH / 2 - PADDLE_WIDTH / 2;
    paddle.y = HEIGHT - 1;
    paddle.width = PADDLE_WIDTH;

    ball.x = paddle.x + PADDLE_WIDTH / 2;
    ball.y = HEIGHT - 2;

    // Initialize bricks
    for (int i = 0; i < BRICK_ROWS; i++) {
        for (int j = 0; j < BRICK_COLS; j++) {
            bricks[i][j].active = true;
            bricks[i][j].x = j * 4 + 2;
            bricks[i][j].y = i + 1; // start one row below the top
        }
    }

    reset_ball();
}

void draw() {
    clear();
    for (int i = 0; i < WIDTH + 2; i++) printw("#"); // Top border
    printw("\n");

    for (int y = 0; y < HEIGHT; y++) {
        printw("#"); // Left border
        for (int x = 0; x < WIDTH; x++) {
            if (y == ball.y && x == ball.x) {
                printw("O");
            } else if (y == paddle.y && x >= paddle.x && x < paddle.x + paddle.width) {
                printw("-");
            } else {
                bool brick_found = false;
                for (int i = 0; i < BRICK_ROWS; i++) {
                    for (int j = 0; j < BRICK_COLS; j++) {
                        if (bricks[i][j].active && bricks[i][j].x == x && bricks[i][j].y == y) {
                            printw("X");
                            brick_found = true;
                            break;
                        }
                    }
                    if (brick_found) break;
                }
                if (!brick_found) printw(" ");
            }
        }
        printw("#\n"); // Right border
    }

    for (int i = 0; i < WIDTH + 2; i++) printw("#"); // Bottom border
    printw("\n");
    refresh();
}

void update() {
    int ch = getch();
    if (ch == 'a' && paddle.x > 0) {
        paddle.x--;
    } else if (ch == 'd' && paddle.x < WIDTH - PADDLE_WIDTH) {
        paddle.x++;
    }

    ball.x += 1; // Move ball right as default
    ball.y -= 1; // Move ball up as default

    if (ball.x <= 0 || ball.x >= WIDTH - 1) ball.x *= -1; // Reverse x direction
    if (ball.y <= 0) ball.y *= -1; // Reverse y direction
    if (ball.y == HEIGHT - 1) {
        reset_ball();
    }
}

void reset_ball() {
    ball.x = paddle.x + PADDLE_WIDTH / 2;
    ball.y = HEIGHT - 2;
}

bool check_collision() {
    if (ball.y == paddle.y - 1 && ball.x >= paddle.x && ball.x < paddle.x + paddle.width) {
        ball.y -= 1;
        return false;
    }

    if (ball.y >= HEIGHT) {
        return true; // Game over
    }

    for (int i = 0; i < BRICK_ROWS; i++) {
        for (int j = 0; j < BRICK_COLS; j++) {
            if (bricks[i][j].active && ball.x == bricks[i][j].x && ball.y == bricks[i][j].y) {
                bricks[i][j].active = false;
                ball.y = HEIGHT - 5; // Change ball position
                return false;
            }
        }
    }
    return false;
}

void cleanup() {
    endwin();
}

