#include <string.h>

#define MAX_KEY_SIZE 100
#define MAX_VALUE_SIZE 1000
#define MAX_NUM_KEYS 1000

typedef struct {
    char key[MAX_KEY_SIZE];
    char value[MAX_VALUE_SIZE];
} Record;

typedef struct {
    Record records[MAX_NUM_KEYS];
    int numKeys;
} Database;

void initializeDatabase(Database *db) {
    db->numKeys = 0;
}

int addRecord(Database *db, char *key, char *value) {
    if (db->numKeys >= MAX_NUM_KEYS) {
        return -1;
    }

    strcpy(db->records[db->numKeys].key, key);
    strcpy(db->records[db->numKeys].value, value);

    db->numKeys++;

    return db->numKeys - 1;
}

int searchRecord(Database *db, char *key) {
    for (int i = 0; i < db->numKeys; i++) {
        if (strcmp(db->records[i].key, key) == 0) {
            return i;
        }
    }

    return -1;
}

int main() {
