//MISTRAL-7B DATASET v1.0 Category: Checksum Calculator ; Style: secure
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define BLOCK_SIZE 65536
#define CHECKSUM_SIZE 4

typedef struct {
    unsigned char data[BLOCK_SIZE];
    unsigned char checksum[CHECKSUM_SIZE];
} Block;

unsigned short calculate_checksum(unsigned char *data, size_t size) {
    unsigned short sum = 0;
    for (size_t i = 0; i < size; i++) {
        sum += data[i];
    }
    sum = (sum >> 16) + (sum & 0xffff);
    sum = (sum & 0xffff) + (sum >> 16);
    return sum;
}

void read_block(int fd, Block *block) {
    if (read(fd, block->data, BLOCK_SIZE) != BLOCK_SIZE) {
        perror("Error reading block");
        exit(EXIT_FAILURE);
    }
    block->checksum[0] = calculate_checksum(block->data, BLOCK_SIZE) >> 8;
    block->checksum[1] = calculate_checksum(block->data, BLOCK_SIZE) & 0xff;
}

void write_block(int fd, const Block *block) {
    if (write(fd, block->data, BLOCK_SIZE) != BLOCK_SIZE) {
        perror("Error writing block");
        exit(EXIT_FAILURE);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int fd = open(argv[1], O_RDWR);
    if (fd == -1) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    Block block;
    for (size_t i = 0; ; i++) {
        read_block(fd, &block);
        write_block(fd, &block);
    }

    close(fd);
    return EXIT_SUCCESS;
}

