#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>

#define MAX_WORD_LENGTH 20
#define MAX_SENTENCE_LENGTH 50

// Define a struct to store the word and its score
typedef struct {
    char *word;
    int score;
} word_t;

// Define an array to store all the words in the sentence
word_t words[MAX_SENTENCE_LENGTH];

// Define a function to check if a word is in the dictionary
int is_word_in_dict(char *word) {
    // Check if the word is in the dictionary
    if (strcmp(word, "sorry") == 0) {
        // If the word is "sorry", return 0 (not in the dictionary)
        return 0;
    }

    // Check if the word is in the list of words
    for (int i = 0; i < MAX_SENTENCE_LENGTH; i++) {
        if (strcmp(words[i].word, word) == 0) {
            // If the word is in the list, return 1 (in the dictionary)
            return 1;
        }
    }

    // If the word is not in the list, return 0 (not in the dictionary)
    return 0;
}

// Define a function to check the spelling of a sentence
int check_spelling(char *sentence) {
    // Initialize the score to 0
    int score = 0;

    // Split the sentence into individual words
    char *words[MAX_SENTENCE_LENGTH];
    char *word = strtok(sentence, " ");
    int i = 0;
    while (word != NULL) {
        words[i] = word;
        i++;
        word = strtok(NULL, " ");
    }

    // Loop through each word in the sentence
    for (int i = 0; i < MAX_SENTENCE_LENGTH; i++) {
        // Check if the word is in the dictionary
        if (is_word_in_dict(words[i]) == 0) {
            // If the word is not in the dictionary, add to the score
            score++;
        }
    }

    // Return the score
    return score;
}

int main() {
    // Define the sentence to check
    char sentence[] = "The cat sat on the mat and sorry.";

    // Check the spelling of the sentence
    int score = check_spelling(sentence);

    // Print the score
    printf("The score is %d\n", score);

    return 0;
}

