// Function to calculate GCD of two numbers
int gcd(int a, int b){
    if(b == 0)
        return a;
    return gcd(b, a % b);
}

// Function to calculate totient of a number using its prime factors
int phi(int n, int *p, int len){
    int i, ans = n;
    for(i = 0; i < len; i++){
        if(n % *(p + i) == 0){
            ans /= *(p + i);
            ans *= (*(p + i) - 1);
        }
    }
    return ans;
}

// Function to check if a number is prime
int isPrime(int n){
    int i;
    for(i = 2; i <= sqrt(n); i++){
        if(n % i == 0)
            return 0;
    }
    return 1;
}

