#define MAX_BUFFER 1024
#define SERVER "pop.example.com"
#define PORT 110

typedef struct {
    int socket;
    char username[50];
    char password[50];
} Pop3Client;

void error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

void send_command(Pop3Client *client, const char *command) {
    if (send(client->socket, command, strlen(command), 0) < 0) {
        error("Failed to send command");
    }
}

char* receive_response(Pop3Client *client) {
    static char buffer[MAX_BUFFER];
    memset(buffer, 0, sizeof(buffer));
    if (recv(client->socket, buffer, sizeof(buffer) - 1, 0) < 0) {
        error("Failed to receive response");
    }
    return buffer;
}

void login(Pop3Client *client) {
    char command[MAX_BUFFER];

    snprintf(command, sizeof(command), "USER %s\r\n", client->username);
    send_command(client, command);
    printf("Sent: %s", command);

    printf("Received: %s", receive_response(client));

    snprintf(command, sizeof(command), "PASS %s\r\n", client->password);
    send_command(client, command);
    printf("Sent: %s", command);

    printf("Received: %s", receive_response(client));
}

void list_emails(Pop3Client *client) {
    send_command(client, "LIST\r\n");
    printf("Sent: LIST\r\n");

    char *response = receive_response(client);
    printf("Received: %s", response);
}

void retrieve_email(Pop3Client *client, int email_number) {
    char command[MAX_BUFFER];

    snprintf(command, sizeof(command), "RETR %d\r\n", email_number);
    send_command(client, command);
    printf("Sent: %s", command);

    char *response = receive_response(client);
    printf("Received Email %d: %s", email_number, response);
}

void quit(Pop3Client *client) {
    send_command(client, "QUIT\r\n");
    printf("Sent: QUIT\r\n");

    char *response = receive_response(client);
    printf("Received: %s", response);

    close(client->socket);
    printf("Connection closed.\n");
}

