	printf("\n  2. Get        6. IsFull");
	printf("\n  3. Peek       7. MakeEmpty");
	printf("\n  4. Display    0. Exit");
tt:	printf("\nYou choose: "); 		scanf("%d",&choice);
	switch(choice){
