// DINH NGHIA CAC HAM
void Put(int value){
	queue *p = (queue *)malloc(sizeof(queue));
	p->Value=value;
	p->next=NULL;
	if(first==NULL) 	first=p;
	else				last->next=p;
	last=p;
}

int Get(){
	int value=first->Value;
	queue *temp=first;
	first=first->next;
	free(temp);
	return value;
}

int Peek(){
	return first->Value;
}

void Display(){
	printf("   QUEUE:   ");
	for(queue *p=first; p!=NULL; p=p->next) 	printf("%d.   ",p->Value);
	printf("\n");
}

bool IsEmpty(){
	if(first==NULL) 	return true;
	else 				return false;
}

bool IsFull(int maxsize){
	if(Count()==maxsize) 	return true;
	else 					return false;	
}

void MakeEmpty(){
	while(first!=NULL){
		Get();
	}
}

int Count(){
	int count=0;;
	for(queue *p=first; p!=NULL; p=p->next) 	count++;
	return count;
}

