            if(it->first == key) {

                if(sf::Mouse::isButtonPressed(it->second))

                    return true;

            }

        }



        for(std::map<std::string, sf::Keyboard::Key>::iterator it = _keyboardMap.begin(); it != _keyboardMap.end(); it++) {

