//GPT-4o-mini DATASET v1.0 Category: QR code generator ; Style: complex
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <qrencode.h>

// Function to generate a QR code from a given string
void generateQRCode(const char *input, const char *filename) {
    QRcode *qr;
    uint8_t *qrcodeData;
    FILE *fp;
    int size, margin = 4, imageSize;

    // Create the QR code
    qr = QRcode_encodeString(input, 0, QR_ECLEVEL_L, QR_MODE_8, 1);
    if (qr == NULL) {
        fprintf(stderr, "Could not generate QR code\n");
        exit(EXIT_FAILURE);
    }

    // Calculate size of QR code image
    size = qr->width;
    imageSize = size + margin * 2;

    // Allocate memory for image
    qrcodeData = (uint8_t *)malloc(imageSize * imageSize);
    if (qrcodeData == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        QRcode_free(qr);
        exit(EXIT_FAILURE);
    }

    // Initialize QR code image
    for (int y = 0; y < imageSize; y++) {
        for (int x = 0; x < imageSize; x++) {
            if (x < margin || x >= size + margin || y < margin || y >= size + margin) {
                qrcodeData[y * imageSize + x] = 255; // White pixel
            } else {
                qrcodeData[y * imageSize + x] = (qr->data[(y - margin) * size + (x - margin)] & 1) ? 0 : 255; // Black or white
            }
        }
    }

    // Save QR code image to PGM file format
    fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Could not open file for writing\n");
        free(qrcodeData);
        QRcode_free(qr);
        exit(EXIT_FAILURE);
    }

    fprintf(fp, "P5\n%d %d\n255\n", imageSize, imageSize);
    fwrite(qrcodeData, sizeof(uint8_t), imageSize * imageSize, fp);

    // Cleanup
    fclose(fp);
    free(qrcodeData);
    QRcode_free(qr);
}

// Function to get the current timestamp as a string
void getCurrentTimestamp(char *buffer, size_t length) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(buffer, length, "%Y-%m-%d %H:%M:%S", tm_info);
}

// Function to log QR code generation
void logQRCodeGeneration(const char *filename, const char *input) {
    char timestamp[20];
    getCurrentTimestamp(timestamp, sizeof(timestamp));

    FILE *logFile = fopen("qrcode_gen.log", "a");
    if (logFile != NULL) {
        fprintf(logFile, "[%s] Generated QR code for \"%s\" saved as \"%s\"\n", timestamp, input, filename);
        fclose(logFile);
    } else {
        fprintf(stderr, "Could not open log file for writing\n");
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input_string> <output_filename.pgm>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *inputString = argv[1];
    const char *outputFilename = argv[2];

    // Generate QR code and log the generation
    generateQRCode(inputString, outputFilename);
    logQRCodeGeneration(outputFilename, inputString);

    printf("QR code generated successfully for \"%s\" and saved to \"%s\"\n", inputString, outputFilename);
    return EXIT_SUCCESS;
}

//FormAI DATASET v1.0 Category: Airport Baggage Handling Simulation ; Style: shocked
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_BAGGAGE 100
#define MAX_WEIGHT 50
#define MAX_FLIGHTS 20

/* Function to generate random integers */
int random_int(int min, int max)
{
    return rand() % (max - min + 1) + min;
}

/* Baggage struct */
typedef struct {
    int weight;
    int flightNum;
} Baggage;

/* Baggage queue */
typedef struct {
    Baggage* heap[MAX_BAGGAGE];
    int size;
} Queue;

/* Function to initialize a queue */
Queue* init_queue()
{
    Queue* queue = malloc(sizeof(Queue));
    queue->size = 0;
    return queue;
}

/* Function to add baggage to queue */
void enqueue(Queue* queue, Baggage* baggage)
{
    int i = queue->size;
    while (i > 0 && queue->heap[(i - 1) / 2]->flightNum < baggage->flightNum) {
        queue->heap[i] = queue->heap[(i - 1) / 2];
        i = (i - 1) / 2;
    }
    queue->heap[i] = baggage;
    queue->size++;
}

/* Function to remove baggage from queue */
Baggage* dequeue(Queue* queue)
{
    Baggage* baggage = queue->heap[0];
    queue->size--;
    int i = 0;
    while (i * 2 + 1 < queue->size) {
        int maxChild = i * 2 + 1;
        if (i * 2 + 2 < queue->size && queue->heap[i * 2 + 2]->flightNum > queue->heap[maxChild]->flightNum) {
            maxChild = i * 2 + 2;
        }
        if (queue->heap[maxChild]->flightNum > baggage->flightNum) {
            queue->heap[i] = queue->heap[maxChild];
            i = maxChild;
        } else {
            break;
        }
    }
    queue->heap[i] = queue->heap[queue->size];
    return baggage;
}

int main()
{
    srand(time(NULL));
    Queue* bagsQueue = init_queue();
    int flights[MAX_FLIGHTS] = { 0 };
    int totalBags = 0;
    int totalWeight = 0;
    int baggageLeft = 0;

    for (int i = 0; i < MAX_BAGGAGE; i++) {
        Baggage* baggage = malloc(sizeof(Baggage));
        baggage->weight = random_int(1, MAX_WEIGHT);
        baggage->flightNum = random_int(1, MAX_FLIGHTS);
        enqueue(bagsQueue, baggage);
        totalBags++;
        totalWeight += baggage->weight;
        flights[baggage->flightNum - 1]++;
    }

    printf("Total number of bags: %d\n", totalBags);
    printf("Total weight of bags: %d kg\n", totalWeight);

    while (bagsQueue->size > 0) {
        Baggage* baggage = dequeue(bagsQueue);
        if (flights[baggage->flightNum - 1] > 0) {
            flights[baggage->flightNum - 1]--;
        } else {
            printf("Baggage with weight %d kg and flight number %d is left behind!\n", baggage->weight, baggage->flightNum);
            baggageLeft++;
        }
    }

    printf("Number of bags left behind: %d\n", baggageLeft);

    return 0;
}

#include <stdio.h>
