#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the structure for a card
typedef struct {
    int rank;
    int suit;
} Card;

// Define the structure for a deck of cards
typedef struct {
    Card cards[52];
    int num_cards;
} Deck;

// Define the structure for a hand of cards
typedef struct {
    Card cards[5];
    int num_cards;
} Hand;

// Define the structure for a poker game
typedef struct {
    Deck deck;
    Hand players[2];
    int current_player;
} Game;

// Function to initialize a deck of cards
void init_deck(Deck* deck) {
    for (int i = 0; i < 52; i++) {
        deck->cards[i].rank = i % 13;
        deck->cards[i].suit = i / 13;
    }
    deck->num_cards = 52;
}

// Function to shuffle a deck of cards
void shuffle_deck(Deck* deck) {
    srand(time(NULL));
    for (int i = 0; i < 52; i++) {
        int rand_index = rand() % deck->num_cards;
        Card temp = deck->cards[i];
        deck->cards[i] = deck->cards[rand_index];
        deck->cards[rand_index] = temp;
    }
}

// Function to deal a hand of cards
void deal_hand(Deck* deck, Hand* hand) {
    for (int i = 0; i < 5; i++) {
        hand->cards[i] = deck->cards[deck->num_cards - i - 1];
        deck->num_cards--;
    }
    hand->num_cards = 5;
}

// Function to evaluate a hand
int evaluate_hand(Hand* hand) {
    int rank = 0;
    for (int i = 0; i < hand->num_cards; i++) {
        rank += hand->cards[i].rank;
    }
    return rank;
}

// Function to print a hand
void print_hand(Hand* hand) {
    for (int i = 0; i < hand->num_cards; i++) {
        printf("%d of %d, ", hand->cards[i].rank, hand->cards[i].suit);
    }
    printf("\n");
}

// Function to play a game of poker
void play_game(Game* game) {
    // Initialize the deck
    init_deck(&game->deck);
    // Shuffle the deck
    shuffle_deck(&game->deck);
    // Deal the hand
    deal_hand(&game->deck, &game->players[0]);
    deal_hand(&game->deck, &game->players[1]);
    // Evaluate the hand
    int player1_rank = evaluate_hand(&game->players[0]);
    int player2_rank = evaluate_hand(&game->players[1]);
    // Print the hand
    print_hand(&game->players[0]);
    print_hand(&game->players[1]);
    // Determine the winner
    if (player1_rank > player2_rank) {
        printf("Player 1 wins!\n");
    } else if (player1_rank < player2_rank) {
        printf("Player 2 wins!\n");
    } else {
        printf("It's a tie!\n");
    }
}

int main() {
    Game game;
    play_game(&game);
    return 0;
}

