#include <stdio.h>
#include <stdlib.h>

#define WIDTH 80
#define HEIGHT 50

char canvas[WIDTH][HEIGHT];

void clear() {
  for (int y = 0; y < HEIGHT; y++) {
    for (int x = 0; x < WIDTH; x++) {
      canvas[x][y] = ' ';
    }
  }
}

void draw_line(int x1, int y1, int x2, int y2) {
  int dx = abs(x2 - x1);
  int dy = abs(y2 - y1);

  int sx = (x1 < x2) ? 1 : -1;
  int sy = (y1 < y2) ? 1 : -1;

  int err = dx - dy;

  while (1) {
    canvas[x1][y1] = '*';

    if (x1 == x2 && y1 == y2) break;

    int e2 = 2 * err;
    if (e2 > -dy) {
      err -= dy;
      x1 += sx;
    }
    if (e2 < dx) {
      err += dx;
      y1 += sy;
    }
  }
}

void print() {
  for (int y = 0; y < HEIGHT; y++) {
    for (int x = 0; x < WIDTH; x++) {
      putchar(canvas[x][y]);
    }
    putchar('\n');
  }
}

int main() {
  clear();
  draw_line(10, 10, 70, 10);
  draw_line(10, 10, 10, 40);
  draw_line(70, 10, 70, 40);
  draw_line(10, 40, 70, 40);
  print();
  return 0;
}

