  // Receive the server response
  nbytes = recv(sockfd, recvbuf, sizeof(recvbuf), 0);
  if (nbytes == -1) {
    perror("recv");
    exit(1);
  }

  // Print the server response
  printf("%s", recvbuf);

  // Send the DATA command
  char *data = "DATA\r\n";
  if (send(sockfd, data, strlen(data), 0) == -1) {
    perror("send");
    exit(1);
  }

  // Receive the server response
  nbytes = recv(sockfd, recvbuf, sizeof(recvbuf), 0);
  if (nbytes == -1) {
    perror("recv");
