#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <semaphore.h>

#define N_THREADS 5
#define N_COUNTERS 16

// Our precious shared counters
int counters[N_COUNTERS];

// A semaphore to enforce mutual exclusive access to the counters
sem_t counter_lock;

// The thread function
void *thread_func(void *arg) {
    // Grab a random counter
    int counter_index = rand() % N_COUNTERS;

    // Lock the counter
    sem_wait(&counter_lock);

    // Increment the counter
    counters[counter_index]++;

    // Unlock the counter
    sem_post(&counter_lock);

    return NULL;
}

int main() {
    // Initialize the random number generator
    srand(time(NULL));

    // Initialize the semaphore
    sem_init(&counter_lock, 0, 1);

    // Create the threads
    pthread_t threads[N_THREADS];
    for (int i = 0; i < N_THREADS; i++) {
        pthread_create(&threads[i], NULL, thread_func, NULL);
    }

    // Join the threads
    for (int i = 0; i < N_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    // Print the counters
    for (int i = 0; i < N_COUNTERS; i++) {
        printf("Counter %d: %d\n", i, counters[i]);
    }

    // Destroy the semaphore
    sem_destroy(&counter_lock);

    return 0;
}

