void Curve::reevaluate()
{
	points.resize(NUM_POINTS);
	int i;
	for (i = 0; i < NUM_POINTS; i++) {
		points[i] = (eval((float)(i) / (float)(NUM_POINTS)));
		if (points[i].y > Curve::maxHeight.y) {
			Curve::maxHeight = points[i];
		}
	}
	setupBuffers();
}

