//GPT-4o-mini DATASET v1.0 Category: Network Quality of Service (QoS) monitor ; Style: real-life
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/select.h>

#define PORT 8080
#define BUFFER_SIZE 1024
#define TIME_INTERVAL 2 // Interval to report QoS statistics in seconds

typedef struct {
    int total_packets_sent;
    int total_packets_received;
    float latency_sum; // In milliseconds
    float jitter_sum; // In milliseconds
} QoSStats;

QoSStats qos_stats;

void signal_handler(int sig) {
    printf("\nTerminating the QoS monitor...\n");
    printf("Total packets sent: %d\n", qos_stats.total_packets_sent);
    printf("Total packets received: %d\n", qos_stats.total_packets_received);
    printf("Average latency: %.2f ms\n",
           qos_stats.total_packets_received > 0 ? qos_stats.latency_sum / qos_stats.total_packets_received : 0);
    printf("Average jitter: %.2f ms\n",
           qos_stats.total_packets_received > 1 ? qos_stats.jitter_sum / (qos_stats.total_packets_received - 1) : 0);
    exit(0);
}

void calculate_jitter(float* latencies, int count, float* jitter) {
    if (count < 2) {
        *jitter = 0;
        return;
    }

    *jitter = 0;
    for (int i = 1; i < count; i++) {
        float diff = latencies[i] - latencies[i - 1];
        if(diff < 0) diff = -diff; // Absolute value
        *jitter += diff;
    }
    *jitter /= (count - 1); // Average of jitter
}

int main() {
    signal(SIGINT, signal_handler);

    int sockfd;
    struct sockaddr_in server_addr, client_addr;
    char buffer[BUFFER_SIZE];
    int addr_len = sizeof(client_addr);
    float latencies[BUFFER_SIZE];
    int latency_count = 0;

    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("Socket creation failed");
        return -1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY; // Accept from any IP address
    server_addr.sin_port = htons(PORT);

    if (bind(sockfd, (const struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        close(sockfd);
        return -1;
    }

    printf("QoS monitor listening on port %d...\n", PORT);

    while (1) {
        int n = recvfrom(sockfd, buffer, BUFFER_SIZE, 0, (struct sockaddr*)&client_addr, &addr_len);
        if (n < 0) {
            perror("Receive failed");
            continue;
        }

        // Process received packet
        qos_stats.total_packets_received++;
        qos_stats.total_packets_sent++; // Simulate sending packets
        float latency = (float) (rand() % 100); // Simulated latency value
        latencies[latency_count++] = latency;
        qos_stats.latency_sum += latency;

        if (latency_count >= 2) {
            float jitter;
            calculate_jitter(latencies, latency_count, &jitter);
            qos_stats.jitter_sum += jitter;
        }

        // Log every TIME_INTERVAL seconds
        sleep(TIME_INTERVAL);
    }

    close(sockfd);
    return 0;
}

#include <stdio.h>

// Define the maximum number of products that can be stored in the inventory
#define MAX_PRODUCTS 100

// Define the structure for a product
typedef struct {
    char name[50];
    int quantity;
    float price;
} Product;

// Declare the inventory array
Product inventory[MAX_PRODUCTS];

// Declare the current number of products in the inventory
int numProducts = 0;

// Function to display the main menu
void displayMenu() {
    printf("\n=== Product Inventory System ===\n");
    printf("1. Add a product\n");
    printf("2. Display the inventory\n");
    printf("3. Search for a product\n");
    printf("4. Update a product\n");
    printf("5. Delete a product\n");
    printf("6. Exit\n");
}

// Function to add a product to the inventory
void addProduct() {
    // Check if the inventory is full
    if(numProducts >= MAX_PRODUCTS) {
        printf("Inventory is full. Cannot add more products.\n");
        return;
    }

    // Get the details of the product to be added
    printf("Enter the name of the product: ");
    scanf("%s", inventory[numProducts].name);
    printf("Enter the quantity of the product: ");
    scanf("%d", &inventory[numProducts].quantity);
    printf("Enter the price of the product: ");
    scanf("%f", &inventory[numProducts].price);

    // Increment the number of products in the inventory
    numProducts++;

    printf("Product added successfully.\n");
}

// Function to display the inventory
void displayInventory() {
    // Check if there are any products in the inventory
    if(numProducts == 0) {
        printf("Inventory is empty.\n");
        return;
    }

    printf("\n=== Inventory ===\n");
    printf("Name\t\tQuantity\tPrice\n");

    // Loop through all the products in the inventory
    for(int i = 0; i < numProducts; i++) {
        printf("%s\t\t%d\t\t%.2f\n", inventory[i].name, inventory[i].quantity, inventory[i].price);
    }
}

// Function to search for a product in the inventory
void searchProduct() {
    // Check if there are any products in the inventory
    if(numProducts == 0) {
        printf("Inventory is empty.\n");
        return;
    }

    // Get the name of the product to be searched
    char searchName[50];
    printf("Enter the name of the product to be searched: ");
    scanf("%s", searchName);

    // Loop through all the products in the inventory
    for(int i = 0; i < numProducts; i++) {
        // Check if the current product matches the search criteria
        if(strcmp(inventory[i].name, searchName) == 0) {
            printf("Product found: %s\t\t%d\t\t%.2f\n", inventory[i].name, inventory[i].quantity, inventory[i].price);
            return;
        }
    }

    // If control reaches here, it means the product was not found
    printf("Product not found.\n");
}

// Function to update a product in the inventory
void updateProduct() {
    // Check if there are any products in the inventory
    if(numProducts == 0) {
        printf("Inventory is empty.\n");
        return;
    }

    // Get the name of the product to be updated
    char updateName[50];
    printf("Enter the name of the product to be updated: ");
    scanf("%s", updateName);

    // Loop through all the products in the inventory
    for(int i = 0; i < numProducts; i++) {
        // Check if the current product matches the search criteria
        if(strcmp(inventory[i].name, updateName) == 0) {
            // Get the updated details of the product
            printf("Enter the new quantity of the product: ");
            scanf("%d", &inventory[i].quantity);
            printf("Enter the new price of the product: ");
            scanf("%f", &inventory[i].price);

            printf("Product updated successfully.\n");
            return;
        }
    }

    // If control reaches here, it means the product was not found
    printf("Product not found.\n");
}

// Function to delete a product from the inventory
void deleteProduct() {
    // Check if there are any products in the inventory
    if(numProducts == 0) {
        printf("Inventory is empty.\n");
        return;
    }

    // Get the name of the product to be deleted
    char deleteName[50];
    printf("Enter the name of the product to be deleted: ");
    scanf("%s", deleteName);

    // Loop through all the products in the inventory
    for(int i = 0; i < numProducts; i++) {
        // Check if the current product matches the search criteria
        if(strcmp(inventory[i].name, deleteName) == 0) {
            // Shift all the products after the deleted product one position to the left
            for(int j = i; j < numProducts - 1; j++) {
                inventory[j] = inventory[j+1];
            }

            // Decrement the number of products in the inventory
            numProducts--;

            printf("Product deleted successfully.\n");
            return;
        }
    }

    // If control reaches here, it means the product was not found
    printf("Product not found.\n");
}

