                break;

            case 4:
                updateProduct();
                break;

            case 5:
                deleteProduct();
                break;

            case 6:
                printf("Exiting the program...\n");
                return 0;

            default:
                printf("Invalid choice.\n");
        }
    }

    return 0;
}

