#include <arpa/inet.h>

int main() {
    int sockfd, portno, n;
    struct sockaddr_in serv_addr;
    char buffer[256];
    char filename[256];

    // Create socket
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("ERROR opening socket");
        exit(1);
    }

    // Assign local and remote port numbers
    portno = 21; // FTP port
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(portno);
    serv_addr.sin_addr.s_addr = INADDR_ANY;

    // Connect to server
    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("ERROR connecting");
        exit(1);
    }

    printf("Connected to FTP server.\n");

    // Send username and password
    sprintf(buffer, "USER anonymous\r\n");
    write(sockfd, buffer, strlen(buffer));
    read(sockfd, buffer, sizeof(buffer));

    sprintf(buffer, "PASS <your_password>\r\n");
    write(sockfd, buffer, strlen(buffer));
    read(sockfd, buffer, sizeof(buffer));

    printf("Authenticated successfully.\n");

    // List files in the current directory
    sprintf(buffer, "LIST\r\n");
    write(sockfd, buffer, strlen(buffer));
    read(sockfd, buffer, sizeof(buffer));

    while (strstr(buffer, "200")!= NULL) {
        printf("%s\n", buffer);
        strcpy(filename, buffer);
        n = strlen(filename) + 1;
        read(sockfd, buffer, n);
        strcat(buffer, "\r\n");
    }

    printf("List of files: %s\n", buffer);

    // Download file
    sprintf(buffer, "RETR %s\r\n", filename);
    write(sockfd, buffer, strlen(buffer));
    read(sockfd, buffer, sizeof(buffer));

    while (strstr(buffer, "226")!= NULL) {
        printf("%s\n", buffer);
        n = strlen(buffer) + 1;
        read(sockfd, buffer, n);
        strcat(buffer, "\r\n");
    }

    printf("File downloaded successfully.\n");

    // Close socket
    close(sockfd);

    return 0;
}

