#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define constants for drone control

const int TAKEOFF_ALTITUDE = 5;
const int MAX_ALTITUDE = 50;
const int MAX_SPEED = 20;
const int MAX_TURNING_ANGLE = 40;

// Define struct for drone control commands

typedef struct {
    int altitude;
    int speed;
    int heading;
} DroneCommand;

// Define function to parse command string into DroneCommand struct

DroneCommand parseCommand(char* commandString) {
    DroneCommand command;
    char* token = strtok(commandString, " ");
    while (token != NULL) {
        if (strncmp(token, "altitude=", strlen("altitude=")) == 0) {
            command.altitude = atoi(token + strlen("altitude="));
        } else if (strncmp(token, "speed=", strlen("speed=")) == 0) {
            command.speed = atoi(token + strlen("speed="));
        } else if (strncmp(token, "heading=", strlen("heading=")) == 0) {
            command.heading = atoi(token + strlen("heading="));
        }
        token = strtok(NULL, " ");
    }
    return command;
}

// Define function to validate DroneCommand struct

int validateCommand(DroneCommand command) {
    if (command.altitude < TAKEOFF_ALTITUDE || command.altitude > MAX_ALTITUDE) {
        return 0;
    }
    if (command.speed < 0 || command.speed > MAX_SPEED) {
        return 0;
    }
    if (command.heading < -MAX_TURNING_ANGLE || command.heading > MAX_TURNING_ANGLE) {
        return 0;
    }
    return 1;
}

// Define main function

int main() {
    printf("Welcome to the C Drone Remote Control!\n");
    printf("Please enter the control commands in the format altitude=<altitude> speed=<speed> heading=<heading> (separated by spaces)\n");
    printf("Enter 'exit' to quit.\n\n");

    // Invoke main control loop

    char input[100];
    while (strncmp(input, "exit", strlen("exit")) != 0) {

        // Read command from user

        printf("> ");
        fgets(input, 100, stdin);
        input[strcspn(input, "\n")] = '\0';
        if (strncmp(input, "exit", strlen("exit")) == 0) {
            printf("Goodbye!\n");
            break;
        }

        // Parse and validate command

        DroneCommand command = parseCommand(input);
        int isValid = validateCommand(command);

        // Execute command or report error

        if (isValid) {
            printf("Command accepted: altitude=%d speed=%d heading=%d\n", command.altitude, command.speed, command.heading);
            // TODO: Implement drone control code here
        } else {
            printf("Invalid command format. Please enter the commands in the format altitude=<altitude> speed=<speed> heading=<heading>\n\n");
        }
    }
    return 0;
}

#include "FileBufferReader.h"

namespace algorithms {
	void FileBufferReader::fillBuffer() {
		mStream.read(mBuffer, BUFFER_SIZE);
		mReadBytes = mStream.gcount();
		mInBytes += mReadBytes;
		mBufferIndex = 0;
	}

	void FileBufferReader::open() {
		mStream.open(mFileName, ios::binary|ios::in);
		mBufferIndex = 0;
		mReadBytes = 0;
		mInBytes = 0;
	}

	void FileBufferReader::close() {
		mStream.close();	
	}

	bool FileBufferReader::good() {
		return mStream.good() || mBufferIndex < mReadBytes*BYTE_SIZE;
	}

	bool FileBufferReader::fail() {
		return mStream.fail();
	}

	bool FileBufferReader::bad() {
		return mStream.bad();
	}

	bool FileBufferReader::eof() {
		return mStream.eof();
	}

	void FileBufferReader::readBit(bool& bit) {
		char byte;
		// Full buffer, read more
		if (mBufferIndex == mReadBytes*BYTE_SIZE) {
			if (mStream.good()) {
				fillBuffer();
			}
			else  { // buffer is not good anymore
				mReadBytes = 0;
				mBufferIndex = 0;
				return;
			}
		}
		// return the current unread bit
		int mask = 1<<CURRENT_BIT(mBufferIndex);
		byte = mBuffer[CURRENT_BYTE(mBufferIndex)];
		mBufferIndex++;
		bit = byte&mask;
	}

	void FileBufferReader::readByte(char& byte) {
		byte = 0;
		int currentBit;
		// buffer reached end, read more from file
		if (mBufferIndex == mReadBytes*BYTE_SIZE) {
			if (mStream.good()) {
				fillBuffer();
				byte = mBuffer[0];
				mBufferIndex += BYTE_SIZE;
			}
			else { // buffer is no longer good
				mReadBytes = 0;
				mBufferIndex = 0;
			}
		} 
		else { // buffer has not reached end 
			byte = mBuffer[CURRENT_BYTE(mBufferIndex)];
			currentBit = CURRENT_BIT(mBufferIndex);
			// if not reached byte boundary, make up byte from two adjacent
			// bytes in buffer
			if (currentBit == 0) {
				mBufferIndex += BYTE_SIZE;
			}
			else {
				// remove lower read bits
				byte = ((unsigned char)byte)>>currentBit;
				mBufferIndex += BYTE_SIZE - currentBit;
				if (mBufferIndex == mReadBytes*BYTE_SIZE) {
					if (mStream.good()) {
						fillBuffer();
						// remove higher unexplored bits
						// not casting as left shift of signed and unsigned 
						// are equivalent
						byte = byte|mBuffer[0]<<(BYTE_SIZE - currentBit);
						mBufferIndex += currentBit;
					}
					else {
						mReadBytes = 0;
						mBufferIndex = 0;
					}
				}
				else {
					// remove higher unexplored bits
					// not casting as left shift of signed and unsigned 
					// are equivalent
					byte = 
						byte|mBuffer[CURRENT_BYTE(mBufferIndex)]<<(BYTE_SIZE - currentBit);
					mBufferIndex += currentBit;
				}
			}
		}
	}

	void FileBufferReader::readInt(unsigned int& result) {
		char byte; 
		readByte(byte);
		result = (unsigned char) byte;
		readByte(byte);
		result = (unsigned char)byte<<BYTE_SIZE|result;
		readByte(byte);
		result = (unsigned char)byte<<2*BYTE_SIZE|result;
		readByte(byte);
		result = (unsigned char)byte<<3*BYTE_SIZE|result;
	}
}

