#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define HEIGHT 10
#define WIDTH 50
#define DROPS 500

void init_weather(int weather[HEIGHT][WIDTH]);
void print_weather(int weather[HEIGHT][WIDTH]);
void simulate_weather(int weather[HEIGHT][WIDTH]);

int main() {
    srand(time(NULL));

    int weather[HEIGHT][WIDTH];
    init_weather(weather);

    while (1) {
        system("clear");
        print_weather(weather);
        simulate_weather(weather);
        usleep(100000);
    }

    return 0;
}

void init_weather(int weather[HEIGHT][WIDTH]) {
    for (int i = 0; i < HEIGHT; i++) {
        for (int j = 0; j < WIDTH; j++) {
            weather[i][j] = rand() % 2;
        }
    }
}

void print_weather(int weather[HEIGHT][WIDTH]) {
    for (int i = 0; i < HEIGHT; i++) {
        for (int j = 0; j < WIDTH; j++) {
            if (weather[i][j] == 0) {
                printf("  ");
            } else {
                printf("* ");
            }
        }
        printf("\n");
    }
}

void simulate_weather(int weather[HEIGHT][WIDTH]) {
    for (int i = 0; i < HEIGHT; i++) {
        for (int j = 0; j < WIDTH; j++) {
            int count = 0;

            if (i > 0 && weather[i - 1][j] == 1) {
                count++;
            }

            if (i < HEIGHT - 1 && weather[i + 1][j] == 1) {
                count++;
            }

            if (j > 0 && weather[i][j - 1] == 1) {
                count++;
            }

            if (j < WIDTH - 1 && weather[i][j + 1] == 1) {
                count++;
            }

            if (count == 0 && weather[i][j] == 1) {
                weather[i][j] = 0;
            } else if (count > 0 && weather[i][j] == 0) {
                weather[i][j] = 1;
            }
        }
    }

    for (int i = 0; i < DROPS; i++) {
        int x = rand() % WIDTH;
        int y = rand() % HEIGHT;

        if (weather[y][x] == 0) {
            weather[y][x] = 1;
        }
    }
}

//LLAMA2-13B DATASET v1.0 Category: Audio processing ; Style: multiplayer
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define PORT 8080

int main(int argc, char *argv[]) {
    int sock, client_sock;
    struct sockaddr_in server, client;
    socklen_t client_len = sizeof(client);
    char buffer[256];
    int bytes_recvd;

    // Create the server socket
    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    // Set up the server address
    memset(&server, 0, sizeof(server));
    server.sin_family = AF_INET;
    server.sin_addr.s_addr = INADDR_ANY;
    server.sin_port = htons(PORT);

    // Bind the server socket to the address and port
    if (bind(sock, (struct sockaddr *)&server, sizeof(server)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    // Listen for incoming connections
    if (listen(sock, 3) < 0) {
        perror("listen failed");
        exit(EXIT_FAILURE);
    }

    printf("Server listening on port %d...\n", PORT);

    while (1) {
        // Accept an incoming connection
        if ((client_sock = accept(sock, (struct sockaddr *)&client, &client_len)) < 0) {
            perror("accept failed");
            continue;
        }

        // Read audio data from the client
        bytes_recvd = read(client_sock, buffer, 256);
        if (bytes_recvd < 0) {
            perror("read failed");
            close(client_sock);
            continue;
        }

        // Process the audio data
        // (in this example, we'll just echo back the audio data)
        printf("Received audio data: %s\n", buffer);
        write(client_sock, buffer, bytes_recvd);

        // Close the client socket
        close(client_sock);
    }

    return 0;
}

//GEMINI-pro DATASET v1.0 Category: Elevator Simulation ; Style: futuristic
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define FLOORS 10
#define ELEVATORS 3

typedef struct {
  int floor;
  int direction;
} Request;

typedef struct {
  int floor;
  int requests[FLOORS];
} Elevator;

int main() {
  // Initialize random number generator
  srand(time(NULL));

  // Create elevators
  Elevator elevators[ELEVATORS];
  for (int i = 0; i < ELEVATORS; i++) {
    elevators[i].floor = 0;
    for (int j = 0; j < FLOORS; j++) {
      elevators[i].requests[j] = 0;
    }
  }

  // Generate random requests
  Request requests[10];
  for (int i = 0; i < 10; i++) {
    requests[i].floor = rand() % FLOORS;
    requests[i].direction = rand() % 2;
  }

  // Simulate elevator movement
  while (1) {
    // Check for requests at each floor
    for (int i = 0; i < FLOORS; i++) {
      if (requests[i].floor == i) {
        // Find the closest elevator
        int closestElevator = -1;
        int closestDistance = FLOORS;
        for (int j = 0; j < ELEVATORS; j++) {
          int distance = abs(elevators[j].floor - i);
          if (distance < closestDistance) {
            closestDistance = distance;
            closestElevator = j;
          }
        }

        // Add the request to the closest elevator
        elevators[closestElevator].requests[i] = 1;
      }
    }

    // Move elevators
    for (int i = 0; i < ELEVATORS; i++) {
      // Find the next floor to move to
      int nextFloor = -1;
      int minDistance = FLOORS;
      for (int j = 0; j < FLOORS; j++) {
        if (elevators[i].requests[j] == 1) {
          int distance = abs(elevators[i].floor - j);
          if (distance < minDistance) {
            minDistance = distance;
            nextFloor = j;
          }
        }
      }

      // Move the elevator to the next floor
      if (nextFloor != -1) {
        elevators[i].floor = nextFloor;
        elevators[i].requests[nextFloor] = 0;
      }
    }

    // Print the elevator status
    for (int i = 0; i < ELEVATORS; i++) {
      printf("Elevator %d: floor %d, requests: ", i, elevators[i].floor);
      for (int j = 0; j < FLOORS; j++) {
        printf("%d ", elevators[i].requests[j]);
      }
      printf("\n");
    }
  }

  return 0;
}

