//Falcon-180B DATASET v1.0 Category: Percolation Simulator ; Style: peaceful
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define N 100

int grid[N][N];
int num_filled;

void initialize() {
    srand(time(NULL));
    int i, j;
    for (i = 0; i < N; i++) {
        for (j = 0; j < N; j++) {
            grid[i][j] = 0;
        }
    }
    num_filled = 0;
}

void print_grid() {
    int i, j;
    for (i = 0; i < N; i++) {
        for (j = 0; j < N; j++) {
            if (grid[i][j] == 1) {
                printf("*");
            } else {
                printf(".");
            }
        }
        printf("\n");
    }
}

void percolate() {
    int i, j, k, count = 0;
    for (i = 0; i < N; i++) {
        for (j = 0; j < N; j++) {
            if (grid[i][j] == 1) {
                count++;
            }
        }
    }
    if (count == num_filled) {
        printf("Percolation occurred at step %d\n", num_filled);
        exit(0);
    }
    int x, y;
    srand(time(NULL));
    x = rand() % N;
    y = rand() % N;
    if (grid[x][y] == 0) {
        grid[x][y] = 1;
        num_filled++;
    }
}

int main() {
    initialize();
    int i, j;
    for (i = 0; i < N; i++) {
        for (j = 0; j < N; j++) {
            if (rand() % 2 == 0) {
                grid[i][j] = 1;
                num_filled++;
            }
        }
    }
    printf("Initial grid:\n");
    print_grid();
    int step = 0;
    while (1) {
        percolate();
        step++;
        if (step % 10 == 0) {
            printf("Grid at step %d:\n", step);
            print_grid();
        }
    }
    return 0;
}

