#define MAX_LIGHTS 10
#define LIGHT_NAME_LENGTH 20

typedef struct {
    char name[LIGHT_NAME_LENGTH];
    int intensity; // 0 to 100
    int is_on;
} SmartLight;

SmartLight lights[MAX_LIGHTS];
int light_count = 0;

void initialize_lights() {
    for (int i = 0; i < MAX_LIGHTS; i++) {
        snprintf(lights[i].name, LIGHT_NAME_LENGTH, "Light %d", i + 1);
        lights[i].intensity = 0;
        lights[i].is_on = 0;
    }
    light_count = MAX_LIGHTS;
}

void display_lights() {
    printf("\n--- Smart Home Lights Status ---\n");
    for (int i = 0; i < light_count; i++) {
        printf("Name: %s, Intensity: %d%%, Status: %s\n",
               lights[i].name,
               lights[i].intensity,
               lights[i].is_on ? "ON" : "OFF");
    }
}

void turn_on_light(int index) {
    if (index < 0 || index >= light_count) {
        printf("Invalid light index!\n");
        return;
    }
    lights[index].is_on = 1;
    printf("%s turned ON!\n", lights[index].name);
}

void turn_off_light(int index) {
    if (index < 0 || index >= light_count) {
        printf("Invalid light index!\n");
        return;
    }
    lights[index].is_on = 0;
    printf("%s turned OFF!\n", lights[index].name);
}

void set_light_intensity(int index, int intensity) {
    if (index < 0 || index >= light_count) {
        printf("Invalid light index!\n");
        return;
    }
    if (intensity < 0 || intensity > 100) {
        printf("Intensity must be between 0 and 100!\n");
        return;
    }
    lights[index].intensity = intensity;
    printf("%s intensity set to %d%%!\n", lights[index].name, intensity);
}

void execute_command(char *command) {
    char action[10];
    int index, intensity;

    sscanf(command, "%s", action);

    if (strcmp(action, "status") == 0) {
        display_lights();
    } else if (strcmp(action, "turn_on") == 0) {
        sscanf(command + strlen(action), " %d", &index);
        turn_on_light(index);
    } else if (strcmp(action, "turn_off") == 0) {
        sscanf(command + strlen(action), " %d", &index);
        turn_off_light(index);
    } else if (strcmp(action, "set_intensity") == 0) {
        sscanf(command + strlen(action), " %d %d", &index, &intensity);
        set_light_intensity(index, intensity);
    } else {
        printf("Unknown command: %s\n", command);
    }
}

int main() {
    char command[255];

    initialize_lights();

    printf("Welcome to the Smart Home Light Control System!\n");
    printf("Available commands:\n");
    printf("1. status - Display all lights status\n");
    printf("2. turn_on <light_index> - Turn on a specific light\n");
    printf("3. turn_off <light_index> - Turn off a specific light\n");
    printf("4. set_intensity <light_index> <intensity> - Set light intensity\n");
    printf("5. exit - Exit the program\n");

    while (1) {
        printf("\n> ");
        fgets(command, sizeof(command), stdin);
        command[strcspn(command, "\n")] = 0; // Remove the newline character

        if (strcmp(command, "exit") == 0) {
            printf("Exiting Smart Home Light Control System. Goodbye!\n");
            break;
        }

        execute_command(command);
    }

    return 0;
}

