//GEMINI-pro DATASET v1.0 Category: Image Steganography ; Style: romantic
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    unsigned char r, g, b;
} Pixel;

int main() {
    // Open the image file
    FILE *image = fopen("image.bmp", "rb");
    if (!image) {
        fprintf(stderr, "Error opening image file\n");
        return EXIT_FAILURE;
    }

    // Read the image header
    unsigned char header[54];
    fread(header, sizeof(header), 1, image);

    // Get the image dimensions
    int width = *(int *)&header[18];
    int height = *(int *)&header[22];

    // Allocate memory for the image data
    Pixel *data = malloc(width * height * sizeof(Pixel));
    if (!data) {
        fprintf(stderr, "Error allocating memory for image data\n");
        return EXIT_FAILURE;
    }

    // Read the image data
    fread(data, sizeof(Pixel), width * height, image);
    fclose(image);

    // Open the text file
    FILE *text = fopen("text.txt", "rb");
    if (!text) {
        fprintf(stderr, "Error opening text file\n");
        return EXIT_FAILURE;
    }

    // Read the text
    char *message = malloc(1000);
    if (!message) {
        fprintf(stderr, "Error allocating memory for text\n");
        return EXIT_FAILURE;
    }
    fread(message, 1, 1000, text);
    fclose(text);

    // Hide the text in the image
    int i, j, k;
    for (i = 0; i < height; i++) {
        for (j = 0; j < width; j++) {
            for (k = 0; k < 3; k++) {
                if (k == 2) {
                    data[i * width + j].b = message[i * width * 3 + j * 3 + k];
                } else {
                    data[i * width + j].g = message[i * width * 3 + j * 3 + k];
                }
            }
        }
    }

    // Open the output image file
    FILE *output = fopen("output.bmp", "wb");
    if (!output) {
        fprintf(stderr, "Error opening output image file\n");
        return EXIT_FAILURE;
    }

    // Write the image header
    fwrite(header, sizeof(header), 1, output);

    // Write the image data
    fwrite(data, sizeof(Pixel), width * height, output);
    fclose(output);

    // Free the allocated memory
    free(data);
    free(message);

    return EXIT_SUCCESS;
}

//MISTRAL-7B DATASET v1.0 Category: File Backup System ; Style: scientific
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#define MAX_FILE_SIZE 1024 * 1024 * 10

void backup_file(const char *file_name) {
    int orig_fd, bak_fd;
    off_t orig_size, bak_size;
    char orig_file[MAX_FILE_SIZE];
    char bak_file[MAX_FILE_SIZE];

    // Open the original file for reading
    orig_fd = open(file_name, O_RDONLY);
    if (orig_fd < 0) {
        perror("Error opening original file");
        return;
    }

    // Get the size of the original file
    fstat(orig_fd, &orig_size);

    // Create the backup file name
    strcpy(bak_file, file_name);
    strcat(bak_file, ".bak");

    // Open the backup file for writing
    bak_fd = open(bak_file, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (bak_fd < 0) {
        perror("Error opening backup file");
        close(orig_fd);
        return;
    }

    // Read the data from the original file and write it to the backup file
    while (read(orig_fd, orig_file, sizeof(orig_file)) > 0) {
        write(bak_fd, orig_file, sizeof(orig_file));
    }

    // Close the file descriptors
    close(orig_fd);
    close(bak_fd);

    printf("File '%s' backed up to '%s'\n", file_name, bak_file);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s <file_name>\n", argv[0]);
        return 1;
    }

    backup_file(argv[1]);

    return 0;
}

