//LLAMA2-13B DATASET v1.0 Category: Word Count Tool ; Style: secure
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <stdbool.h>
#include <strings.h>

#define MAX_WORD_COUNT 1000

struct word_count {
    char *word;
    size_t count;
};

int main(void) {
    char *input = "Hello, world! How are you?";
    size_t input_len = strlen(input);
    struct word_count word_counts[MAX_WORD_COUNT];
    size_t word_count = 0;

    // Initialize word counts array
    for (size_t i = 0; i < MAX_WORD_COUNT; i++) {
        word_counts[i].word = NULL;
        word_counts[i].count = 0;
    }

    // Tokenize input string
    char *token = strtok(input, " ");
    while (token != NULL) {
        // Check if word is already in the count
        for (size_t i = 0; i < word_count; i++) {
            if (strcmp(word_counts[i].word, token) == 0) {
                word_counts[i].count++;
                break;
            }
        }

        // If word is not in the count, add it
        if (word_counts[word_count].word == NULL) {
            word_counts[word_count].word = token;
            word_counts[word_count].count = 1;
        } else {
            word_counts[word_count].count++;
        }

        token = strtok(NULL, " ");
        word_count++;
    }

    // Print word counts
    for (size_t i = 0; i < word_count; i++) {
        printf("%s: %zu\n", word_counts[i].word, word_counts[i].count);
    }

    return 0;
}

