#define PORT_RANGE 1024  // range of ports to scan (1-1024)
#define IP_ADDRESS "192.168.1.100" // IP address to scan

void scan_ports(int sock, struct sockaddr_in *server_addr) {
    int i, port;
    socklen_t address_len = sizeof(server_addr->sin_addr);
    char buffer[256];

    for (i = 1; i <= PORT_RANGE; i++) {
        port = htons(i);
        server_addr->sin_port = port;
        if (connect(sock, server_addr, sizeof(server_addr)) == 0) {
            // connection established, print the port number
            printf("%d is open\n", ntohs(server_addr->sin_port));
            close(sock);
        } else {
            // connection failed, try the next port
            printf("%d is closed or filtered\n", ntohs(port));
        }
    }
}

