#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>

#define WIDTH 50
#define HEIGHT 50
#define MAX_POINTS 10000

typedef struct {
    double x, y;
} Point;

Point generate_random_point(void) {
    Point point;
    point.x = (double)rand() / RAND_MAX * WIDTH;
    point.y = (double)rand() / RAND_MAX * HEIGHT;
    return point;
}

void print_point(Point point) {
    printf("(%lf, %lf)", point.x, point.y);
}

Point calculate_geometric_center(Point points[], int num_points) {
    double sum_x = 0, sum_y = 0;

    for (int i = 0; i < num_points; ++i) {
        sum_x += points[i].x;
        sum_y += points[i].y;
    }

    Point center;
    center.x = sum_x / num_points;
    center.y = sum_y / num_points;

    return center;
}

int main() {
    srand(time(NULL));

    Point points[MAX_POINTS];
    int num_points = 0;

    while (num_points < MAX_POINTS) {
        Point point = generate_random_point();
        int already_exists = 0;

        for (int i = 0; i < num_points; ++i) {
            if (points[i].x == point.x && points[i].y == point.y) {
                already_exists = 1;
                break;
            }
        }

        if (!already_exists) {
            points[num_points] = point;
            num_points++;
        }
    }

    Point center = calculate_geometric_center(points, num_points);

    printf("\nGenerated %d random points within a rectangle of size %dx%d:\n", num_points, WIDTH, HEIGHT);

    for (int i = 0; i < num_points; ++i) {
        printf("%s", i > 0 ? ", " : "");
        print_point(points[i]);
    }

    printf("\n\nThe geometric center of these points is: (%lf, %lf)\n", center.x, center.y);

    return 0;
}

//Falcon2-11B DATASET v1.0 Category: CPU Scheduling Algorithms ; Style: ephemeral
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define NUM_PROCESSES 4
#define TASK_TIME 5

typedef struct {
    int pid;
    int arrival_time;
    int burst_time;
    int current_burst_time;
    int remaining_burst_time;
    int process_index;
} Process;

Process processes[NUM_PROCESSES];

void schedule_process(int process_index) {
    Process *process = &processes[process_index];
    process->current_burst_time = 0;
    process->remaining_burst_time = process->burst_time;
}

void run_process(int process_index) {
    Process *process = &processes[process_index];
    if (process->current_burst_time < process->remaining_burst_time) {
        printf("Running process %d (%d ms remaining)\n", process->pid, process->remaining_burst_time);
        process->current_burst_time++;
        if (process->current_burst_time < process->remaining_burst_time) {
            run_process(process->process_index);
        }
    } else {
        process->current_burst_time = 0;
        process->remaining_burst_time = 0;
    }
}

int main() {
    srand(time(NULL));
    for (int i = 0; i < NUM_PROCESSES; i++) {
        processes[i].pid = i + 1;
        processes[i].arrival_time = rand() % 10;
        processes[i].burst_time = rand() % TASK_TIME;
        processes[i].process_index = i;
    }

    printf("Initial process order: ");
    for (int i = 0; i < NUM_PROCESSES; i++) {
        printf("%d ", processes[i].pid);
    }
    printf("\n");

    while (1) {
        for (int i = 0; i < NUM_PROCESSES; i++) {
            if (processes[i].arrival_time == time(NULL)) {
                schedule_process(i);
            }
        }

        for (int i = 0; i < NUM_PROCESSES; i++) {
            run_process(i);
        }

        printf("Process order after one round: ");
        for (int i = 0; i < NUM_PROCESSES; i++) {
            printf("%d ", processes[i].pid);
        }
        printf("\n");
    }

    return 0;
}

