#include <stdio.h>
#include <stdlib.h>
#include <math.h>

// Define the simulation parameters
const double G = 6.67408e-11; // Gravitational constant
const double M = 1.0; // Mass of the central black hole
const double m = 0.1; // Mass of a star
const double r_0 = 1.0; // Initial distance of the star from the black hole
const double v_0 = 10.0; // Initial velocity of the star
const double t_end = 100.0; // End time of the simulation

// Define the simulation structure
struct star {
    double x, y, z; // Position of the star
    double vx, vy, vz; // Velocity of the star
    double m; // Mass of the star
};

// Define the simulation functions
void update_position(struct star *star) {
    double dxdt = star->vx / (2.0 * G * M);
    double dydt = star->vy / (2.0 * G * M);
    double dzdt = star->vz / (2.0 * G * M);
    star->x += dxdt;
    star->y += dydt;
    star->z += dzdt;
}

void update_velocity(struct star *star) {
    double dudx = star->vx - (G * M * star->x) / (2.0 * star->m);
    double dudy = star->vy - (G * M * star->y) / (2.0 * star->m);
    double dudz = star->vz - (G * M * star->z) / (2.0 * star->m);
    star->vx += dudx;
    star->vy += dudy;
    star->vz += dudz;
}

int main() {
    // Create an array of stars
    struct star stars[10];
    for (int i = 0; i < 10; i++) {
        stars[i].x = (double)i / 10.0;
        stars[i].y = (double)i / 10.0;
        stars[i].z = 0.0;
        stars[i].vx = 10.0;
        stars[i].vy = 10.0;
        stars[i].vz = 0.0;
        stars[i].m = 0.1;
    }

    // Set the time step and the simulation end time
    double dt = 0.01;
    double t = 0.0;

    // Run the simulation
    while (t < t_end) {
        // Update the position of the stars
        for (int i = 0; i < 10; i++) {
            update_position(&stars[i]);
        }

        // Update the velocity of the stars
        for (int i = 0; i < 10; i++) {
            update_velocity(&stars[i]);
        }

        t += dt;
    }

    // Print the final positions of the stars
    for (int i = 0; i < 10; i++) {
        printf("%.2f %.2f %.2f\n", stars[i].x, stars[i].y, stars[i].z);
    }

    return 0;
}

