void print_grid(int grid[GRID_SIZE][GRID_SIZE]);
void open_cell(int grid[GRID_SIZE][GRID_SIZE], int x, int y);
int count_open_cells(int grid[GRID_SIZE][GRID_SIZE]);
int main() {
  // Initialize random seed
  srand(time(NULL));

  // Create grid
  int grid[GRID_SIZE][GRID_SIZE];
  for (int i = 0; i < GRID_SIZE; i++) {
    for (int j = 0; j < GRID_SIZE; j++) {
      grid[i][j] = 0;    // Closed
    }
  }


  // Open cells
  for (int i = 0; i < GRID_SIZE; i++) {
    for (int j = 0; j < GRID_SIZE; j++) {
      if (rand() % 100 < PERCENTAGE) {
        open_cell(grid, i, j);
      }
    }
  }

  // Print grid
  printf("Cyberpunk Percolation Simulator\n");
  print_grid(grid);

  // Count open cells
  int open_cells = count_open_cells(grid);
  printf("%d open cells\n", open_cells);

  return 0;
}

void print_grid(int grid[GRID_SIZE][GRID_SIZE]) {
  for (int i = 0; i < GRID_SIZE; i++) {
    for (int j = 0; j < GRID_SIZE; j++) {
      printf("%c", grid[i][j] ? 'O' : ' ');
    }
    printf("\n");
  }
}

void open_cell(int grid[GRID_SIZE][GRID_SIZE], int x, int y) {
  if (x < 0 || x >= GRID_SIZE || y < 0 || y >= GRID_SIZE) {
    return;
  }

  if (grid[x][y] == 1) {
    return;
  }

  grid[x][y] = 1;

  // Open adjacent cells
  open_cell(grid, x - 1, y);
  open_cell(grid, x + 1, y);
  open_cell(grid, x, y - 1);
  open_cell(grid, x, y + 1);
}

int count_open_cells(int grid[GRID_SIZE][GRID_SIZE]) {
  int count = 0;
  for (int i = 0; i < GRID_SIZE; i++) {
    for (int j = 0; j < GRID_SIZE; j++) {
      if (grid[i][j] == 1) {
        count++;
      }
    }
  }
  return count;
}

