void load_words(char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error loading words file\n");
        exit(1);
    }

    char line[MAX_WORD_LENGTH];
    while (fgets(line, sizeof(line), file)!= NULL) {
        int i = 0;
        while (isspace(line[i])) {
            i++;
        }
        int j = 0;
        while (!isspace(line[i]) && j < MAX_WORD_LENGTH - 1) {
            words[num_words].word[j++] = tolower(line[i++]);
        }
        words[num_words].word[j] = '\0';
        words[num_words].length = j;
        num_words++;
    }

    fclose(file);
}

void generate_random_word() {
    int index = rand() % num_words;
    strcpy(words[index].word, words[index].word + 1);
}

