#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#define TABLE_SIZE 101
typedef struct {
    char key[20];
    int value;
    struct Node *next;
} Node;
Node *table[TABLE_SIZE];
int hash(char *key) {
    int hash = 0;
    for (int i = 0; key[i]; i++) {
        hash += hash * 31 + key[i];
    }
    return abs(hash % TABLE_SIZE);
}
void hash_table_insert(char *key, int value) {
    int index = hash(key);
    Node *new_node = (Node *) malloc(sizeof(Node));
    strcpy(new_node->key, key);
    new_node->value = value;
    new_node->next = table[index];
    table[index] = new_node;
}
Node *hash_table_search(char *key) {
    int index = hash(key);
    Node *current = table[index];
    while (current != NULL && strcmp(current->key, key) != 0) {
        current = current->next;
    }
    return current;
}
void hash_table_remove(char *key) {
    int index = hash(key);
    Node *prev = NULL, *current = table[index];
    while (current != NULL && strcmp(current->key, key) != 0) {
        prev = current;
        current = current->next;
    }
    if (current == NULL) {
        printf("Key not found\n");
        return;
    }
    if (prev == NULL) {
        table[index] = current->next;
    } else {
        prev->next = current->next;
    }
    free(current);
}
int main() {
    for (int i = 0; i < TABLE_SIZE; i++) {
        table[i] = NULL;
    }
    hash_table_insert("apple", 5);
    hash_table_insert("banana", 10);
    hash_table_insert("orange", 15);
    Node *node = hash_table_search("apple");
    printf("Value of apple: %d\n", node->value);
