#define MAX_FILES 10
#define MAX_LINE 1024
#define KEYWORD_LEN 7

typedef struct {
    char filename[50];
    int line;
} file_data;

file_data files[MAX_FILES];
int file_count = 0;

void process_line(char *line) {
    int i;
    for (i = 0; i < strlen(line); i++) {
        line[i] = tolower(line[i]);
    }

    int j;
    for (j = 0; j < KEYWORD_LEN; j++) {
        if (strlen(line) - i < KEYWORD_LEN - j) {
            break;
        }

        if (strncmp(&line[i], "morphine", KEYWORD_LEN) == 0 ||
            strncmp(&line[i], "opium", KEYWORD_LEN) == 0) {

            files[file_count].filename[strlen(files[file_count].filename)] = '.';
            files[file_count].filename[strlen(files[file_count].filename)+1] = '\0';
            strcat(files[file_count].filename, "txt");
            files[file_count].line = __LINE__;
            file_count++;
            return;
        }
    }
}

int main() {
    FILE *fp;
    char line[MAX_LINE];
    int line_number = 1;
    char filename[50];

    strcpy(filename, "stories/sherlock_holmes_1.txt");
    fp = fopen(filename, "r");

    if (fp == NULL) {
        printf("Error opening file %s\n", filename);
        return 1;
    }

    while (fgets(line, MAX_LINE, fp) != NULL) {
        process_line(line);
        printf("Line %d in %s: %s\n", line_number, filename, line);
        line_number++;
    }

    fclose(fp);

    printf("\nTotal number of occurrences:\n");
    printf("%d\n", file_count);

    int i;
    for (i = 0; i < file_count; i++) {
        printf("\nFile %s: Line %d\n", files[i].filename, files[i].line);
    }

    return 0;
}

