#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <limits.h>
#include <math.h>
#include <float.h>

#define MAX_WORDS 1000
#define MAX_SENTENCES 100
#define MAX_SUMMARY 1000

int main() {
    // Open the input file
    FILE *inputFile = fopen("input.txt", "r");
    if (inputFile == NULL) {
        printf("Error opening input file\n");
        return 1;
    }

    // Open the output file
    FILE *outputFile = fopen("output.txt", "w");
    if (outputFile == NULL) {
        printf("Error opening output file\n");
        fclose(inputFile);
        return 1;
    }

    // Read the input file into a buffer
    char buffer[MAX_WORDS];
    int words = 0;
    int sentences = 0;
    int summary = 0;
    while (fgets(buffer, MAX_WORDS, inputFile)) {
        // Count the number of words and sentences
        char *word = strtok(buffer, " \n");
        while (word!= NULL) {
            words++;
            word = strtok(NULL, " \n");
        }
        char *sentence = strtok(buffer, ".");
        while (sentence!= NULL) {
            sentences++;
            sentence = strtok(NULL, ".");
        }

        // Check if the buffer is long enough for a new sentence
        if (words >= MAX_WORDS) {
            // Write the current sentence to the output file
            fputs(buffer, outputFile);

            // Reset the buffer and counters
            words = 0;
            sentences++;
            summary++;

            // Check if the summary is long enough
            if (summary >= MAX_SUMMARY) {
                // Close the output file
                fclose(outputFile);
                return 0;
            }
        }
    }

    // Write the last sentence to the output file
    fputs(buffer, outputFile);

    // Close the input and output files
    fclose(inputFile);
    fclose(outputFile);

    return 0;
}

