#include <stdio.h>
#include <stdlib.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <netdb.h>

#define PORT 8080

void server() {
    int sockfd, valread;
    struct sockaddr_in serv_addr;
    char buffer[256];

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("ERROR opening socket");
        exit(1);
    }

    bzero((char *) &serv_addr, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = htons(PORT);

    if (bind(sockfd, (struct sockaddr *) &serv_addr, sizeof(serv_addr)) < 0) {
        perror("ERROR on binding");
        exit(1);
    }

    if (listen(sockfd, 3) < 0) {
        perror("ERROR on listen");
        exit(1);
    }

    while (1) {
        socklen_t clilen = sizeof(struct sockaddr_in);
        int newsockfd = accept(sockfd, (struct sockaddr *) &serv_addr, &clilen);
        if (newsockfd < 0) {
            perror("ERROR on accept");
            exit(1);
        }

        printf("Connection from client\n");
        while ((valread = recv(newsockfd, buffer, 256, 0)) > 0) {
            printf("%s", buffer);
            send(newsockfd, buffer, valread, 0);
        }
        printf("\n");
        close(newsockfd);
    }
}

void client() {
    int sockfd, valread;
    struct sockaddr_in serv_addr;
    char buffer[256];

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("ERROR opening socket");
        exit(1);
    }

    bzero((char *) &serv_addr, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = htons(PORT);

    if (connect(sockfd, (struct sockaddr *) &serv_addr, sizeof(serv_addr)) < 0) {
        perror("ERROR connecting");
        exit(1);
    }

    printf("Send message to server: ");
    scanf("%s", buffer);
    send(sockfd, buffer, strlen(buffer), 0);

    while ((valread = recv(sockfd, buffer, 256, 0)) > 0) {
        printf("%s", buffer);
    }
    printf("\n");
    close(sockfd);
}

int main() {
    server();
    client();
    return 0;
}

