//MISTRAL-7B DATASET v1.0 Category: Maze Route Finder ; Style: single-threaded
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define MAZE_ROWS 10
#define MAZE_COLS 10

static char maze[MAZE_ROWS][MAZE_COLS];
static int visited[MAZE_ROWS][MAZE_COLS];

void print_maze() {
    for (int i = 0; i < MAZE_ROWS; ++i) {
        for (int j = 0; j < MAZE_COLS; ++j) {
            printf("%c ", maze[i][j]);
        }
        printf("\n");
    }
}

bool is_valid(int x, int y) {
    return x >= 0 && x < MAZE_ROWS && y >= 0 && y < MAZE_COLS && !visited[x][y] && maze[x][y] != '#';
}

void dfs(int x, int y) {
    visited[x][y] = true;
    maze[x][y] = '*';

    int dx[4] = {-1, 0, 1, 0};
    int dy[4] = {0, 1, 0, -1};

    for (int i = 0; i < 4; ++i) {
        int nx = x + dx[i];
        int ny = y + dy[i];

        if (is_valid(nx, ny)) {
            dfs(nx, ny);
        }
    }
}

void find_path(int start_x, int start_y) {
    memset(visited, 0, sizeof(visited));

    dfs(start_x, start_y);
}

void generate_maze() {
    int x = 0, y = 0;

    maze[x][y] = 'S';

    while (true) {
        int dx = 0, dy = 0;

        if (is_valid(x + 2, y)) {
            dx = 2;
        } else if (is_valid(x - 2, y)) {
            dx = -2;
        } else if (is_valid(x, y + 2)) {
            dy = 2;
        } else if (is_valid(x, y - 2)) {
            dy = -2;
        } else {
            break;
        }

        x += dx;
        y += dy;

        maze[x][y] = ' ';
    }

    maze[x][y] = 'E';
}

int main() {
    srand(time(NULL));

    generate_maze();
    print_maze();

    int start_x = rand() % MAZE_ROWS;
    int start_y = rand() % MAZE_COLS;

    printf("\nStarting point: (%d, %d)\n", start_x, start_y);
    find_path(start_x, start_y);
    print_maze();

    return 0;
}

