#include <fcntl.h>

#define KEY 0x32

void encrypt_char(char c, FILE *input, FILE *output) {
    if (input == NULL || output == NULL) {
        printf("Invalid file handles\n");
        exit(1);
    }

    if (feof(input)) {
        return;
    }

    char ch = fgetc(input);
    fputc(ch ^ KEY, output);

    encrypt_char(ch, input, output);
}

