//GEMINI-pro DATASET v1.0 Category: Greedy Algorithms ; Style: configurable
#include <stdio.h>
#include <stdlib.h>

#define MAX_SIZE 100

// A structure to represent a job
typedef struct Job {
  int id;          // Job ID
  int deadline;    // Deadline of the job
  int profit;      // Profit of the job
} Job;

// A function to compare two jobs based on their profits
int compare_jobs(const void *a, const void *b) {
  Job *job1 = (Job *)a;
  Job *job2 = (Job *)b;
  return job2->profit - job1->profit;
}

// A function to schedule jobs greedily
void schedule_jobs(Job jobs[], int n) {
  // Sort the jobs in decreasing order of their profits
  qsort(jobs, n, sizeof(Job), compare_jobs);

  // Create an array to store the scheduled jobs
  int scheduled_jobs[MAX_SIZE];

  // Initialize the array to -1 to indicate that no job is scheduled
  for (int i = 0; i < MAX_SIZE; i++) {
    scheduled_jobs[i] = -1;
  }

  // Iterate over the jobs
  for (int i = 0; i < n; i++) {
    // Find the latest available slot for the job
    int latest_slot = -1;
    for (int j = jobs[i].deadline - 1; j >= 0; j--) {
      if (scheduled_jobs[j] == -1) {
        latest_slot = j;
        break;
      }
    }

    // If a latest available slot is found, schedule the job
    if (latest_slot != -1) {
      scheduled_jobs[latest_slot] = jobs[i].id;
    }
  }

  // Print the scheduled jobs
  printf("Scheduled jobs: ");
  for (int i = 0; i < MAX_SIZE; i++) {
    if (scheduled_jobs[i] != -1) {
      printf("%d ", scheduled_jobs[i]);
    }
  }
  printf("\n");
}

// Driver code
int main() {
  // Initialize the jobs
  Job jobs[] = {{1, 4, 20}, {2, 1, 10}, {3, 1, 40}, {4, 1, 30}, {5, 2, 10}};
  int n = sizeof(jobs) / sizeof(Job);

  // Schedule the jobs
  schedule_jobs(jobs, n);

  return 0;
}

