#include <stdio.h>
#include <string.h>

#define MAX_MESSAGE_LEN 256

void encrypt(char* message, int key) {
    int len = strlen(message);
    char encrypted_message[len + 1];

    for (int i = 0; i < len; i++) {
        char c = message[i];
        int index = (c - 'A') + key;

        if (index > 25) {
            index -= 26;
        }

        encrypted_message[i] = index + 'A';
    }

    encrypted_message[len] = '\0';
    printf("Encrypted message: %s\n", encrypted_message);
}

void decrypt(char* encrypted_message, int key) {
    int len = strlen(encrypted_message);
    char decrypted_message[len + 1];

    for (int i = 0; i < len; i++) {
        char c = encrypted_message[i];
        int index = (c - 'A') - key;

        if (index < 0) {
            index += 26;
        }

        decrypted_message[i] = index + 'A';
    }

    decrypted_message[len] = '\0';
    printf("Decrypted message: %s\n", decrypted_message);
}

int main() {
    char message[MAX_MESSAGE_LEN];
    int key = 3;

    printf("Enter a message to encrypt: ");
    fgets(message, MAX_MESSAGE_LEN, stdin);

    encrypt(message, key);

    printf("Enter a message to decrypt: ");
    fgets(message, MAX_MESSAGE_LEN, stdin);

    decrypt(message, -key);

    return 0;
}

