void init1() {

	for(int i = 0; i < 26; i++)
		pi[i] = i;

}

void init2() {

	int a[26] = {23,13,24,0,7,15,14,6,25,16,22,1,19,18,5,11,17,2,21,12,20,4,10,9,3,8};

	for(int i = 0; i < 26; i++)
		pi[i] = a[i];
}

void init_z(int k) {

	for(int i = 0; i < 26; i++)
		z[i] = (k+i-1)%26;
}

char encrypt(char c, int z) {

	if(c>='a' && c<='z')
		return (((pi[c-'a']+z)%26)+'a');

	if(c>='A' && c<='Z')
		return (((pi[c-'A']+z)%26)+'A');

	return c;

}

char decrypt(char c, int z) {

	int i;
	if(c>='A' && c<='Z'){
		for(i = 0; i < 25 && pi[i] != ((((c-'A') - z)+26)%26); i++);
			return (i + 'A');
	}

	if(c>='a' && c<='z'){
		for(i = 0; i < 25 && pi[i] != ((((c-'a') - z)+26)%26); i++);
			return (i + 'a');
	}
	return c;
}

