// Multiplayer Elevator Simulation in C

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>

#define MAX_FLOORS 10
#define MAX_ELEVATORS 3
#define MAX_PLAYERS 10

typedef struct {
    int id;
    int floor;
    int direction; // 1 = up, -1 = down
    int status; // 0 = free, 1 = busy
} Elevator;

typedef struct {
    int id;
    int floor;
    int destination;
    int direction; // 1 = up, -1 = down
    int status; // 0 = free, 1 = busy
} Player;

Elevator elevators[MAX_ELEVATORS];
Player players[MAX_PLAYERS];

void init_elevators() {
    for (int i = 0; i < MAX_ELEVATORS; i++) {
        elevators[i].id = i;
        elevators[i].floor = 1;
        elevators[i].direction = 0;
        elevators[i].status = 0;
    }
}

void init_players() {
    for (int i = 0; i < MAX_PLAYERS; i++) {
        players[i].id = i;
        players[i].floor = 1;
        players[i].destination = 1;
        players[i].direction = 0;
        players[i].status = 0;
    }
}

void update_elevator(Elevator *elevator) {
    if (elevator->status == 0) {
        if (elevator->direction == 1) {
            elevator->floor++;
        } else {
            elevator->floor--;
        }
    }
}

void update_players() {
    for (int i = 0; i < MAX_PLAYERS; i++) {
        if (players[i].status == 0) {
            if (players[i].direction == 1) {
                players[i].floor++;
            } else {
                players[i].floor--;
            }
        }
    }
}

void move_players(Elevator *elevator) {
    for (int i = 0; i < MAX_PLAYERS; i++) {
        if (players[i].status == 0 && players[i].floor == elevator->floor) {
            players[i].status = 1;
            elevator->status = 1;
            printf("Player %d has entered elevator %d\n", players[i].id, elevator->id);
        }
    }
}

void move_elevator(Elevator *elevator) {
    if (elevator->status == 0) {
        if (elevator->direction == 1) {
            elevator->floor++;
        } else {
            elevator->floor--;
        }
        printf("Elevator %d has moved to floor %d\n", elevator->id, elevator->floor);
    }
}

void move_players_to_destination(Elevator *elevator) {
    for (int i = 0; i < MAX_PLAYERS; i++) {
        if (players[i].status == 1 && players[i].destination == elevator->floor) {
            players[i].status = 0;
            elevator->status = 0;
            printf("Player %d has exited elevator %d\n", players[i].id, elevator->id);
        }
    }
}

void display_status() {
    printf("Elevator Status:\n");
    for (int i = 0; i < MAX_ELEVATORS; i++) {
        printf("Elevator %d: Floor %d, Direction %d, Status %d\n", elevators[i].id, elevators[i].floor, elevators[i].direction, elevators[i].status);
    }
    printf("Player Status:\n");
    for (int i = 0; i < MAX_PLAYERS; i++) {
        printf("Player %d: Floor %d, Destination %d, Direction %d, Status %d\n", players[i].id, players[i].floor, players[i].destination, players[i].direction, players[i].status);
    }
}

int main() {
    init_elevators();
    init_players();

    while (1) {
        display_status();
        for (int i = 0; i < MAX_ELEVATORS; i++) {
            update_elevator(&elevators[i]);
        }
        for (int i = 0; i < MAX_PLAYERS; i++) {
            update_players(&players[i]);
        }
        for (int i = 0; i < MAX_ELEVATORS; i++) {
            move_players(&elevators[i]);
        }
        for (int i = 0; i < MAX_ELEVATORS; i++) {
            move_elevator(&elevators[i]);
        }
        for (int i = 0; i < MAX_ELEVATORS; i++) {
            move_players_to_destination(&elevators[i]);
        }
        sleep(1);
    }

    return 0;
}

