#include <stdio.h>
#include <stdlib.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <string.h>

#define PORT 8080
#define BUFLEN 512

void handle_packet(int sockfd, struct sockaddr_in *cli_addr, socklen_t cli_len);

int main(int argc, char *argv[]) {
    int sockfd, n;
    struct sockaddr_in serv_addr, cli_addr;
    socklen_t cli_len;
    char buffer[BUFLEN];

    // Create socket
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        printf("ERROR: socket() failed");
        exit(1);
    }

    // Initialize socket address structure
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = htons(PORT);

    // Bind socket to address and listen
    if (bind(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        printf("ERROR: bind() failed");
        exit(1);
    }
    listen(sockfd, 3);

    // Accept incoming connections
    cli_len = sizeof(cli_addr);
    int newsockfd = accept(sockfd, (struct sockaddr *)&cli_addr, &cli_len);
    if (newsockfd < 0) {
        printf("ERROR: accept() failed");
        exit(1);
    }

    // Handle incoming packets
    while (1) {
        n = recv(newsockfd, buffer, BUFLEN, 0);
        if (n < 0) {
            printf("ERROR: recv() failed");
            exit(1);
        }

        if (n == 0) {
            printf("ERROR: client disconnected");
            close(newsockfd);
            break;
        }

        handle_packet(newsockfd, &cli_addr, cli_len);
    }

    // Close socket
    close(sockfd);
    return 0;
}

void handle_packet(int sockfd, struct sockaddr_in *cli_addr, socklen_t cli_len) {
    char buffer[BUFLEN];
    int n;

    // Read packet data
    n = recv(sockfd, buffer, BUFLEN, 0);
    if (n < 0) {
        printf("ERROR: recv() failed");
        exit(1);
    }

    // Print packet data
    printf("Received packet from %s:%d\n", inet_ntoa(cli_addr->sin_addr), ntohs(cli_addr->sin_port));
    printf("Packet data: %s\n", buffer);

    // Send packet data back to client
    n = send(sockfd, buffer, n, 0);
    if (n < 0) {
        printf("ERROR: send() failed");
        exit(1);
    }
}

