#define PORT 8080
#define BUFFER_SIZE 1024
#define MIN_SENTIMENT -5
#define MAX_SENTIMENT 5
#define NUM_USERS 5

int sentiment_score(const char *text) {
    int score = 0;
    int len = strlen(text);

    for (int i = 0; i < len; i++) {
        char c = text[i];
        if (isalpha(c)) {
            int index = tolower(c) - 'a';
            score += index < 0 ? -(index + 26) : index;
        }
    }

    score /= len * 1.0;
    score = MAX_SENTIMENT * pow(10, score);

    return score;
}

int main(int argc, char const *argv[]) {
    int server_fd, new_socket, valread;
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);
    char buffer[BUFFER_SIZE] = {0};
    char response[BUFFER_SIZE] = {0};
    float total_sentiment = 0;
    int num_messages = 0;

    if ((server_fd = socket(AF_INET, SOCK_DGRAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt,
                   sizeof(opt))) {
        perror("setsockopt");
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    while (1) {
        valread = recvfrom(server_fd, buffer, BUFFER_SIZE, 0, (struct sockaddr *)&address,
                           (socklen_t *)&addrlen);
        if (valread == -1) {
            perror("recvfrom failed");
            continue;
        }

        char *message = strtok(buffer, "\n");
        if (message != NULL) {
            float sentiment = sentiment_score(message);
            total_sentiment += sentiment;
            num_messages++;
            printf("Message: %s, Sentiment: %.2f\n", message, sentiment);
            snprintf(response, sizeof(response), "%.2f", sentiment);
            sendto(server_fd, response, strlen(response), 0,
                   (struct sockaddr *)&address, sizeof(address));
        }
    }

    return 0;
}

