#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define NUM_DISKS 5
#define MAX_THREADS 10

typedef struct {
    int from;
    int to;
    int num_disks;
    int id;
} thread_data_t;

void* thread_func(void* arg) {
    thread_data_t* data = (thread_data_t*)arg;
    int i;

    for (i = data->num_disks - 1; i >= 0; i--) {
        printf("Thread %d moving disk %d from %d to %d\n", data->id, i + 1, data->from, data->to);
        sleep(1);
    }

    printf("Thread %d finished moving disks\n", data->id);
    return NULL;
}

void move_disks(int from, int to, int num_disks, int num_threads) {
    pthread_t threads[num_threads];
    thread_data_t data[num_threads];

    int i;
    for (i = 0; i < num_threads; i++) {
        data[i].from = from;
        data[i].to = to;
        data[i].num_disks = num_disks;
        data[i].id = i + 1;

        if (pthread_create(&threads[i], NULL, thread_func, &data[i])!= 0) {
            printf("Error creating thread %d\n", i + 1);
            exit(1);
        }
    }

    for (i = 0; i < num_threads; i++) {
        if (pthread_join(threads[i], NULL)!= 0) {
            printf("Error joining thread %d\n", i + 1);
            exit(1);
        }
    }
}

int main() {
    printf("Starting Tower of Hanoi problem with %d disks and %d threads\n", NUM_DISKS, MAX_THREADS);
    move_disks(1, 3, NUM_DISKS, MAX_THREADS);

    return 0;
}

