#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

#define NUM_THREADS 4
#define TASK_COUNT 10

void* task1(void* arg) {
    for (int i = 0; i < TASK_COUNT; i++) {
        printf("Task 1: %d\n", i);
        sleep(1);
    }
    return NULL;
}

void* task2(void* arg) {
    for (int i = 0; i < TASK_COUNT; i++) {
        printf("Task 2: %d\n", i);
        sleep(1);
    }
    return NULL;
}

void* task3(void* arg) {
    for (int i = 0; i < TASK_COUNT; i++) {
        printf("Task 3: %d\n", i);
        sleep(1);
    }
    return NULL;
}

void* task4(void* arg) {
    for (int i = 0; i < TASK_COUNT; i++) {
        printf("Task 4: %d\n", i);
        sleep(1);
    }
    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];
    int thread_ids[NUM_THREADS];

    for (int i = 0; i < NUM_THREADS; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, task1, NULL);
