#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define MAX_WORD_LENGTH 50
#define DICTIONARY_SIZE 1000

typedef struct {
    char word[MAX_WORD_LENGTH + 1];
} DictionaryEntry;

void read_dictionary(DictionaryEntry *dictionary) {
    FILE *fp = fopen("dictionary.txt", "r");
    int i = 0;
    char line[MAX_WORD_LENGTH + 1];

    while (fgets(line, sizeof(line), fp) != NULL) {
        if (strlen(line) > MAX_WORD_LENGTH) {
            printf("Warning: word '%s' is too long.\n", line);
            continue;
        }
        strcpy(dictionary[i].word, line);
        i++;
    }

    fclose(fp);
}

int is_palindrome(const char *word) {
    int left = 0;
    int right = strlen(word) - 1;

    while (left < right) {
        if (word[left++] != word[right--]) {
            return 0;
        }
    }

    return 1;
}

int main() {
    DictionaryEntry dictionary[DICTIONARY_SIZE];
    read_dictionary(dictionary);

    int valid_words[DICTIONARY_SIZE] = {0};
    int num_valid_words = 0;

    for (int i = 0; i < DICTIONARY_SIZE; i++) {
        if (strlen(dictionary[i].word) <= MAX_WORD_LENGTH && is_palindrome(dictionary[i].word[0])) {
            valid_words[num_valid_words++] = i;
        }
    }

    char user_word[MAX_WORD_LENGTH + 1];
    while (1) {
        printf("Enter a word to check ('quit' to exit): ");
        scanf("%s", user_word);

        if (strcmp(user_word, "quit") == 0) {
            break;
        }

        int found = 0;
        for (int i = 0; i < num_valid_words; i++) {
            if (strcmp(user_word, dictionary[valid_words[i]].word) == 0) {
                printf("The word '%s' is valid.\n", user_word);
                found = 1;
                break;
            }
        }

        if (!found) {
            printf("The word '%s' is not valid.\n", user_word);
        }
    }

    return 0;
}

//GEMINI-pro DATASET v1.0 Category: Syntax parsing ; Style: retro
#include <stdio.h>
#include <stdlib.h>

typedef enum {
    TOKEN_INT,
    TOKEN_FLOAT,
    TOKEN_STRING,
    TOKEN_IDENTIFIER,
    TOKEN_EOF
} TokenType;

typedef struct {
    TokenType type;
    char *value;
} Token;

Token *currentToken;

void error(char *message) {
    fprintf(stderr, "%s\n", message);
    exit(1);
}

Token *getToken() {
    if (currentToken == NULL) {
        currentToken = (Token *) malloc(sizeof(Token));
    }

    int c = getchar();
    while (c == ' ' || c == '\n' || c == '\t') {
        c = getchar();
    }

    if (c == EOF) {
        currentToken->type = TOKEN_EOF;
        currentToken->value = NULL;
        return currentToken;
    }

    if (isdigit(c)) {
        currentToken->type = TOKEN_INT;
        currentToken->value = malloc(sizeof(char) * 100);
        int i = 0;
        while (isdigit(c)) {
            currentToken->value[i++] = c;
            c = getchar();
        }
        currentToken->value[i] = '\0';
        ungetc(c, stdin);
        return currentToken;
    }

    if (isalpha(c)) {
        currentToken->type = TOKEN_IDENTIFIER;
        currentToken->value = malloc(sizeof(char) * 100);
        int i = 0;
        while (isalpha(c)) {
            currentToken->value[i++] = c;
            c = getchar();
        }
        currentToken->value[i] = '\0';
        ungetc(c, stdin);
        return currentToken;
    }

    if (c == '"') {
        currentToken->type = TOKEN_STRING;
        currentToken->value = malloc(sizeof(char) * 100);
        int i = 0;
        c = getchar();
        while (c != '"') {
            currentToken->value[i++] = c;
            c = getchar();
        }
        currentToken->value[i] = '\0';
        return currentToken;
    }

    error("Invalid token");
    return NULL;
}

void parseExpression() {
    Token *token = getToken();

    if (token->type == TOKEN_INT) {
        printf("Integer: %s\n", token->value);
    } else if (token->type == TOKEN_FLOAT) {
        printf("Float: %s\n", token->value);
    } else if (token->type == TOKEN_STRING) {
        printf("String: %s\n", token->value);
    } else if (token->type == TOKEN_IDENTIFIER) {
        printf("Identifier: %s\n", token->value);
    } else if (token->type == TOKEN_EOF) {
        printf("End of file\n");
    } else {
        error("Invalid token");
    }

    free(token->value);
    free(token);
}

int main() {
    parseExpression();
    return 0;
}

