#include <stdio.h>
#include <stdint.h>
#include <string.h>

#define MASK_BITS (1 << 31)
#define MASK_ZERO (~0)

int main() {
    uint32_t num = 0b101010101010101; // Genius way of initializing a number
    uint32_t mask = 0b111111111111111; // Genius way of initializing a mask
    uint32_t result = 0;

    // Bitwise AND
    result = num & mask;
    printf("Bitwise AND: %08x\n", result);

    // Bitwise OR
    result = num | mask;
    printf("Bitwise OR: %08x\n", result);

    // Bitwise XOR
    result = num ^ mask;
    printf("Bitwise XOR: %08x\n", result);

    // Bitwise NOT
    result = ~num;
    printf("Bitwise NOT: %08x\n", result);

    // Bitshift left
    result = num << 2;
    printf("Bitshift left: %08x\n", result);

    // Bitshift right
    result = num >> 2;
    printf("Bitshift right: %08x\n", result);

    // Bitwise AND with reverse bits
    result = num & (~mask);
    printf("Bitwise AND with reverse bits: %08x\n", result);

    // Bitwise OR with reverse bits
    result = num | (~mask);
    printf("Bitwise OR with reverse bits: %08x\n", result);

    // Bitwise XOR with reverse bits
    result = num ^ (~mask);
    printf("Bitwise XOR with reverse bits: %08x\n", result);

    return 0;
}

