#define MAX_SYMBOL_LEN 10

typedef struct {
    char name[MAX_NAME_LEN];
    char symbol[MAX_SYMBOL_LEN];
    double price;
    int quantity;
} Stock;

Stock stocks[MAX_STOCKS];
int num_stocks;

void add_stock(Stock* s) {
    if (num_stocks >= MAX_STOCKS) {
        printf("Error: Maximum number of stocks reached.\n");
        return;
    }
    strcpy(stocks[num_stocks].name, s->name);
    strcpy(stocks[num_stocks].symbol, s->symbol);
    stocks[num_stocks].price = s->price;
    stocks[num_stocks].quantity = s->quantity;
    num_stocks++;
}

void remove_stock(char* symbol) {
    int i;
    for (i = 0; i < num_stocks; i++) {
        if (strcmp(stocks[i].symbol, symbol) == 0) {
            num_stocks--;
            break;
        }
    }
    if (i < num_stocks) {
        memmove(&stocks[i], &stocks[i+1], sizeof(Stock) * (num_stocks - i - 1));
    }
}

void update_stock(char* symbol, double price, int quantity) {
    int i;
    for (i = 0; i < num_stocks; i++) {
        if (strcmp(stocks[i].symbol, symbol) == 0) {
            stocks[i].price = price;
            stocks[i].quantity = quantity;
            break;
        }
    }
}

