#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define PORT 8888

void recv_data(int sock);
void send_data(int sock);
void recv_loop(int sock);
void send_loop(int sock);

int main(void)
{
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in server_addr = {
        .sin_family = AF_INET,
        .sin_port = htons(PORT),
        .sin_addr.s_addr = inet_addr("127.0.0.1")
    };

    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("connect failed");
        exit(EXIT_FAILURE);
    }

    recv_loop(sock);

    return 0;
}

void recv_data(int sock) {
    char buffer[1024];
    int bytes_recvd = recv(sock, buffer, 1024, 0);
    if (bytes_recvd < 0) {
        perror("recv failed");
        exit(EXIT_FAILURE);
    }
    printf("Received message: %s\n", buffer);

    // Call ourselves with the same socket to continue receiving data
    recv_loop(sock);
}

void send_data(int sock) {
    char message[] = "Hello, world!";
    int bytes_sent = send(sock, message, strlen(message), 0);
    if (bytes_sent < 0) {
        perror("send failed");
        exit(EXIT_FAILURE);
    }
    printf("Sent message: %s\n", message);

    // Call ourselves with the same socket to continue sending data
    send_loop(sock);
}

void recv_loop(int sock) {
    while (1) {
        recv_data(sock);
    }
}

void send_loop(int sock) {
    while (1) {
        send_data(sock);
    }
}

