		for (j = 0; j < C; ++j)
		{
			if (w[j] <= i && A[i - w[j]] > -1)
			{
				if (A[i] < A[i - w[j]] + c[j])
				{
					A[i] = A[i - w[j]] + c[j];
					AQ[i] = j;
				}
				if (B[i] > B[i - w[j]] + c[j])
