		sumA += c[ AQ[i] ];
		i -= w[ AQ[i] ];
	}

	i = F;
	while (i > 0)
	{
		nominalsB[ BQ[i] ]++;
		sumB += c[ BQ[i] ];
		i -= w[ BQ[i] ];
	}


	printf("TAK\n");

	printf("%lld\n", sumB);
	for (i = 0; i < C; ++i)
