#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <unistd.h>
#include <fcntl.h>

#define BUFFER_SIZE 4096

int main() {
    char *filename = "unique_file.txt";
    int fd;
    char buffer[BUFFER_SIZE];
    off_t file_size;
    struct stat stat_info;

    // Open the file in read-write mode
    fd = open(filename, O_RDWR | O_CREAT, 0644);
    if (fd == -1) {
        perror("Error opening file");
        return 1;
    }

    // Get the file size
    fstat(fd, &stat_info);
    file_size = stat_info.st_size;

    // Set the file pointer to the beginning of the file
    lseek(fd, 0, SEEK_SET);

    // Read the file into a buffer
    read(fd, buffer, file_size);

    // Mmap the file into memory
    void *map = mmap(NULL, file_size, PROT_READ | PROT_WRITE, MAP_FILE | MAP_PRIVATE, fd, 0);
    if (map == MAP_FAILED) {
        perror("Error mmapping file");
        return 1;
    }

    // Create a new file with the same contents as the original file
    int new_fd = open("new_file.txt", O_RDWR | O_CREAT, 0644);
    if (new_fd == -1) {
        perror("Error creating new file");
        munmap(map, file_size);
        return 1;
    }

    // Write the mmapped file to the new file
    write(new_fd, map, file_size);

    // Unmap the file from memory
    munmap(map, file_size);

    // Close the new file
    close(new_fd);

    // Print a success message
    printf("File copied successfully\n");

    return 0;
}

