#define MAX_EMAILS 1000
#define MAX_EMAIL_LEN 50

// function prototypes
void print_menu();
void print_list(char *emails[], int n);
void add_email(char *emails[], int *n);
void remove_email(char *emails[], int *n);
void find_duplicates(char *emails[], int n);
