#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <pthread.h>

#define MAX_DISTANCE 1000
#define MAX_SPEED 100
#define PI 3.14159265

typedef struct {
    int x;
    int y;
    int angle;
} Position;

void *rcv_drive(void *arg) {
    Position *position = (Position*)arg;
    int direction = 1;

    while(1) {
        int distance = (rand() % MAX_DISTANCE) - (rand() % MAX_DISTANCE);
        int speed = (rand() % MAX_SPEED) + 1;

        printf("Distance: %d\n", distance);
        printf("Speed: %d\n", speed);

        position->x += distance * cos(position->angle * PI / 180);
        position->y += distance * sin(position->angle * PI / 180);
        position->angle += speed;

        usleep(1000000);
    }
}

int main(int argc, char **argv) {
    Position position = {0, 0, 0};
    pthread_t thread;

    printf("Position: %d, %d, %d\n", position.x, position.y, position.angle);

    if (pthread_create(&thread, NULL, rcv_drive, &position)!= 0) {
        printf("Failed to create thread\n");
        return 1;
    }

    pthread_join(thread, NULL);

    printf("Position: %d, %d, %d\n", position.x, position.y, position.angle);

    return 0;
}

