        if(board[i][0] == board[i][1] && board[i][0] == board[i][2]){
            if(board[i][0] != 0)
                return (board[i][0] == 1) ? -10 : 10;
        }
    }

    //Checking Columns
    for(int i=0;i<3;i++){
        if(board[0][i] == board[1][i] && board[0][i] == board[2][i]){
            if(board[0][i] != 0)
                return (board[0][i] == 1) ? -10 : 10;
        }
    }

    //Checking Diagonals
    if(board[0][0] == board[1][1] && board[0][0] == board[2][2]){
        if(board[0][0] != 0)
            return (board[0][0] == 1) ? -10 : 10;
    }

    if(board[0][2] == board[1][1] && board[0][2] == board[2][0]){
        if(board[0][2] != 0)
            return (board[0][2] == 1) ? -10 : 10;
    }

    //Checking if the game is tied
    for(int i=0;i<3;i++){
        for(int j=0;j<3;j++){
            if(board[i][j] == 0){
                return 0;
            }
        }
    }

    //Game is tied
    return -1;
}

int minimax(int isMax){
    int score = gameStatus();

    //If Maximizer wins, return his/her
    //evaluated score
    if(score == 10)
        return score;

    //If Minimizer wins, return his/her
    //evaluated score
    if(score == -10)
        return score;

    //If there are no more moves and
    //no winner then it is a tie
    if(score == 0)
        return 0;

    //If this maximizer's move
    if(isMax){
        int best = -1000;

        //Traversing all cells
        for(int i=0;i<3;i++){
            for(int j=0;j<3;j++){
                if(board[i][j] == 0){
                    //Make the move
                    board[i][j] = ai;

                    //Call minimax recursively and choose
                    //the maximum value
                    best = (best > minimax(!isMax)) ? best : minimax(!isMax);

                    //Undo the move
                    board[i][j] = 0;
                }
            }
        }

        return best;
    }else{
        //If this minimizer's move
        int best = 1000;

        //Traversing all cells
        for(int i=0;i<3;i++){
            for(int j=0;j<3;j++){
                if(board[i][j] == 0){
                    //Make the move
                    board[i][j] = player;

                    //Call minimax recursively and choose
                    //the minimum value
                    best = (best < minimax(!isMax)) ? best : minimax(!isMax);

                    //Undo the move
                    board[i][j] = 0;
                }
            }
        }

        return best;
    }
}

void aiMove(){
    int bestVal = -1000;
    int row = -1, col = -1;

    //Traversing all cells
    for(int i=0;i<3;i++){
        for(int j=0;j<3;j++){
            //Check if cell is empty
            if(board[i][j] == 0){
                //Make the move
                board[i][j] = ai;

                //Evaluate the move
                int moveVal = minimax(0);

                //Undo the move
                board[i][j] = 0;

                //Update the best value
                if(moveVal > bestVal){
                    row = i;
                    col = j;
                    bestVal = moveVal;
                }
            }
        }
    }

    //Make the move
    board[row][col] = ai;
}

int main(){
    int choice, row, col;

    printf("Welcome to Tic Tac Toe\n");
    printf("======================\n");

    while(1){
