#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <math.h>

#define WIDTH 80
#define HEIGHT 40
#define PADDING 10

int main(int argc, char** argv) {
    int ball_x, ball_y;
    int paddle1_y, paddle2_y;
    int paddle1_x, paddle2_x;

    srand(time(NULL));

    printf("Welcome to Cryptic Pong!\n");

    ball_x = rand() % (WIDTH - PADDING);
    ball_y = rand() % (HEIGHT - PADDING);

    paddle1_y = HEIGHT / 2 - PADDING;
    paddle2_y = HEIGHT / 2 + PADDING;

    paddle1_x = PADDING;
    paddle2_x = WIDTH - PADDING;

    printf("Ball position: (%d, %d)\n", ball_x, ball_y);
    printf("Paddle 1 position: (%d, %d)\n", paddle1_x, paddle1_y);
    printf("Paddle 2 position: (%d, %d)\n", paddle2_x, paddle2_y);

    int score1 = 0, score2 = 0;

    while (1) {
        int ball_x_new, ball_y_new;

        if (ball_x >= WIDTH || ball_x < 0 || ball_y >= HEIGHT || ball_y < 0) {
            ball_x_new = rand() % (WIDTH - PADDING);
            ball_y_new = rand() % (HEIGHT - PADDING);
        } else {
            if (ball_y <= PADDING && ball_y >= 0 && ball_x <= paddle1_x && ball_x >= paddle1_x - PADDING) {
                ball_x_new = paddle1_x - PADDING;
                ball_y_new = ball_y - 1;
            } else if (ball_y >= HEIGHT - PADDING && ball_y <= HEIGHT - 1 && ball_x <= paddle2_x && ball_x >= paddle2_x - PADDING) {
                ball_x_new = paddle2_x - PADDING;
                ball_y_new = ball_y + 1;
            } else {
                ball_x_new = ball_x;
                ball_y_new = ball_y;
            }
        }

        if (ball_x_new >= WIDTH || ball_x_new < 0 || ball_y_new >= HEIGHT || ball_y_new < 0) {
            ball_x = rand() % (WIDTH - PADDING);
            ball_y = rand() % (HEIGHT - PADDING);
        } else {
            if (ball_y_new <= PADDING && ball_y_new >= 0 && ball_x_new <= paddle1_x && ball_x_new >= paddle1_x - PADDING) {
                ball_x = paddle1_x - PADDING;
                ball_y = ball_y_new - 1;
            } else if (ball_y_new >= HEIGHT - PADDING && ball_y_new <= HEIGHT - 1 && ball_x_new <= paddle2_x && ball_x_new >= paddle2_x - PADDING) {
                ball_x = paddle2_x - PADDING;
                ball_y = ball_y_new + 1;
            } else {
                ball_x = ball_x_new;
                ball_y = ball_y_new;
            }
        }

        printf("Ball position: (%d, %d)\n", ball_x, ball_y);

        if (ball_x <= 0) {
            score1++;
            printf("Score 1: %d\n", score1);
            printf("Score 2: %d\n", score2);
        } else if (ball_x >= WIDTH) {
            score2++;
            printf("Score 1: %d\n", score1);
            printf("Score 2: %d\n", score2);
        }

        if (score1 == 10 || score2 == 10) {
            printf("Game over! Score 1: %d, Score 2: %d\n", score1, score2);
            break;
        }

        printf("\n");
    }

    return 0;
}

//Falcon-180B DATASET v1.0 Category: Database querying ; Style: artistic
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ROWS 100
#define MAX_COLS 100
#define MAX_QUERY_LEN 1000

struct query_result {
    int num_rows;
    int num_cols;
    char **row_data;
};

struct query_result execute_query(char *query) {
    struct query_result result;
    char delimiter = ',';
    char *token = strtok(query, &delimiter);
    int num_rows = 0;
    int num_cols = 0;
    char **row_data = NULL;

    while (token!= NULL) {
        if (num_cols == 0) {
            num_cols = strlen(token);
        } else if (strlen(token)!= num_cols) {
            printf("Error: Query result has inconsistent number of columns.\n");
            exit(1);
        }

        num_rows++;
        token = strtok(NULL, &delimiter);
    }

    row_data = malloc(num_rows * sizeof(char *));
    for (int i = 0; i < num_rows; i++) {
        row_data[i] = malloc(num_cols * sizeof(char));
    }

    rewind(stdin);
    fgets(query, MAX_QUERY_LEN, stdin);
    token = strtok(query, &delimiter);

    for (int i = 0; i < num_rows; i++) {
        for (int j = 0; j < num_cols; j++) {
            strncpy(row_data[i], token, num_cols);
            row_data[i][num_cols] = '\0';
            token = strtok(NULL, &delimiter);
        }
    }

    result.num_rows = num_rows;
    result.num_cols = num_cols;
    result.row_data = row_data;

    return result;
}

int main() {
    char query[MAX_QUERY_LEN];
    printf("Enter query:\n");
    fgets(query, MAX_QUERY_LEN, stdin);

    struct query_result result = execute_query(query);

    printf("Result:\n");
    for (int i = 0; i < result.num_rows; i++) {
        for (int j = 0; j < result.num_cols; j++) {
            printf("%s ", result.row_data[i][j]);
        }
        printf("\n");
    }

    for (int i = 0; i < result.num_rows; i++) {
        free(result.row_data[i]);
    }
    free(result.row_data);

    return 0;
}

#include <stdio.h>

char board[3][3]; // the tic tac toe board
char ai = 'X';    // the AI's marker
char human = 'O'; // the human's marker

// this function prints the current state of the board
void print_board() {
    printf("-------------\n");
    for(int i=0; i<3; i++) {
        printf("| %c | %c | %c |\n", board[i][0], board[i][1], board[i][2]);
        printf("-------------\n");
    }
}

// this function checks if there is a winner
char check_winner() {
    char winner = '-';

    // check rows
    for(int i=0; i<3; i++) {
        if(board[i][0] == board[i][1] && board[i][1] == board[i][2]) {
            winner = board[i][0];
            break;
        }
    }

    // check columns
    if(winner == '-') {
        for(int j=0; j<3; j++) {
            if(board[0][j] == board[1][j] && board[1][j] == board[2][j]) {
                winner = board[0][j];
                break;
            }
        }
    }

    // check diagonals
    if(winner == '-') {
        if(board[0][0] == board[1][1] && board[1][1] == board[2][2]) {
            winner = board[0][0];
        } else if(board[0][2] == board[1][1] && board[1][1] == board[2][0]) {
            winner = board[0][2];
        }
    }

    return winner;
}

// this function evaluates the current state of the board and returns a score
int evaluate() {
    char winner = check_winner();
    if(winner == ai) {
        return 10;
    } else if(winner == human) {
        return -10;
    } else {
        return 0;
    }
}

// this function checks if the board has no more moves left
int is_board_full() {
    for(int i=0; i<3; i++) {
        for(int j=0; j<3; j++) {
            if(board[i][j] == '-') {
                return 0;
            }
        }
    }
    return 1;
}

// this function performs the minimax algorithm with alpha-beta pruning
int minimax(int depth, int alpha, int beta, int max_mode) {
    int score = evaluate();

    if(score != 0 || is_board_full()) {
        return score;
    }

    if(max_mode) {
        int best_score = -1000;
        for(int i=0; i<3; i++) {
            for(int j=0; j<3; j++) {
                if(board[i][j] == '-') {
                    board[i][j] = ai;
                    int current_score = minimax(depth+1, alpha, beta, 0);
                    board[i][j] = '-';
                    if(current_score > best_score) {
                        best_score = current_score;
                    }
                    if(best_score > alpha) {
                        alpha = best_score;
                    }
                    if(beta <= alpha) {
                        break;
                    }
                }
            }
        }
        return best_score;
    } else {
        int best_score = 1000;
        for(int i=0; i<3; i++) {
            for(int j=0; j<3; j++) {
                if(board[i][j] == '-') {
                    board[i][j] = human;
                    int current_score = minimax(depth+1, alpha, beta, 1);
                    board[i][j] = '-';
                    if(current_score < best_score) {
                        best_score = current_score;
                    }
                    if(best_score < beta) {
                        beta = best_score;
                    }
                    if(beta <= alpha) {
                        break;
                    }
                }
            }
        }
        return best_score;
    }
}

// this function makes the AI move
void ai_move() {
    int best_score = -1000;
    int best_i = -1;
    int best_j = -1;

    for(int i=0; i<3; i++) {
        for(int j=0; j<3; j++) {
            if(board[i][j] == '-') {
                board[i][j] = ai;
                int current_score = minimax(0, -1000, 1000, 0);
                board[i][j] = '-';
                if(current_score > best_score) {
                    best_score = current_score;
                    best_i = i;
                    best_j = j;
                }
            }
        }
    }

    printf("The AI has made a move at (%d,%d)\n", best_i+1, best_j+1);
    board[best_i][best_j] = ai;
    print_board();
}

int main() {
    // initialize the board
    for(int i=0; i<3; i++) {
        for(int j=0; j<3; j++) {
            board[i][j] = '-';
        }
    }

    print_board();

    while(1) {
        printf("Enter the row and column where you want to place your marker (e.g. 1 2): ");
        int row, col;
        scanf("%d %d", &row, &col);
        row--;
        col--;
        if(board[row][col] == '-') {
            board[row][col] = human;
            print_board();
        } else {
            printf("Invalid move! Try again.\n");
            continue;
        }
        char winner = check_winner();
        if(winner == human) {
            printf("You have won!\n");
            break;
        } else if(is_board_full()) {
            printf("It's a tie.\n");
            break;
        }
        ai_move();
        winner = check_winner();
        if(winner == ai) {
            printf("The AI has won!\n");
            break;
        } else if(is_board_full()) {
            printf("It's a tie.\n");
            break;
        }
    }

    return 0;
}

