#include <errno.h>

#define RESUME_FILE "resume.txt"

int main() {
  int fd, length, i;
  char *buffer;

  // Open the resume file
  fd = open(RESUME_FILE, O_RDONLY);
  if (fd == -1) {
    perror("open");
    exit(1);
  }

  // Get the length of the file
  length = lseek(fd, 0, SEEK_END);
  if (length == -1) {
    perror("lseek");
    exit(1);
  }

  // Memory-map the file
  buffer = mmap(NULL, length, PROT_READ, MAP_PRIVATE, fd, 0);
  if (buffer == MAP_FAILED) {
    perror("mmap");
    exit(1);
  }

  // Close the file
  close(fd);

  // Parse the resume
  for (i = 0; i < length; i++) {
    if (buffer[i] == ' ' || buffer[i] == '\t') {
      // Skip whitespace
      continue;
    } else if (buffer[i] == ',' || buffer[i] == ';') {
      // Skip commas and semicolons
      continue;
    } else if (buffer[i] == '\n') {
      // Skip newlines
      continue;
    } else if (buffer[i] == '{') {
      // Skip opening braces
      continue;
    } else if (buffer[i] == '}') {
      // Skip closing braces
      continue;
    } else if (buffer[i] == '"') {
      // Skip quotes
      continue;
    } else if (buffer[i] == '\\') {
      // Skip backslashes
      continue;
    } else {
      // Print the character
      printf("%c", buffer[i]);
    }
  }

  // Unmap the file
  munmap(buffer, length);

  return 0;
}

