#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define constants
#define MAX_TEMP 100
#define MIN_TEMP -10
#define MAX_RAIN 100
#define MIN_RAIN 0
#define MAX_WIND 100
#define MIN_WIND 0

// Define structure for weather data
typedef struct {
    int temperature;
    int rain;
    int wind;
} Weather;

// Function to simulate weather
void simulate_weather(Weather* weather) {
    // Generate random temperature, rain, and wind
    weather->temperature = rand() % (MAX_TEMP - MIN_TEMP) + MIN_TEMP;
    weather->rain = rand() % (MAX_RAIN - MIN_RAIN) + MIN_RAIN;
    weather->wind = rand() % (MAX_WIND - MIN_WIND) + MIN_WIND;
}

// Function to display weather data
void display_weather(Weather weather) {
    printf("Temperature: %d\n", weather.temperature);
    printf("Rain: %d\n", weather.rain);
    printf("Wind: %d\n", weather.wind);
}

int main() {
    // Initialize random seed
    srand(time(NULL));

    // Simulate weather for 10 days
    Weather weather[10];
    for (int i = 0; i < 10; i++) {
        simulate_weather(&weather[i]);
        display_weather(weather[i]);
    }

    return 0;
}

