#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define MAX_ROOMS 10
#define MAX_DEVICES_PER_ROOM 5

typedef enum { OFF, ON } State;
typedef enum { LED, LAMP } DeviceType;

typedef struct {
    char name[30];
    DeviceType type;
    State state;
} Device;

typedef struct {
    char name[30];
    Device devices[MAX_DEVICES_PER_ROOM];
    int device_count;
} Room;

Room rooms[MAX_ROOMS];
int room_count = 0;

void add_room(char *room_name) {
    if (room_count < MAX_ROOMS) {
        strcpy(rooms[room_count].name, room_name);
        rooms[room_count].device_count = 0;
        room_count++;
        printf("Room '%s' added successfully!\n", room_name);
    } else {
        printf("Cannot add more rooms!\n");
    }
}

void add_device(char *room_name, char *device_name, DeviceType type) {
    for (int i = 0; i < room_count; i++) {
        if (strcmp(rooms[i].name, room_name) == 0) {
            if (rooms[i].device_count < MAX_DEVICES_PER_ROOM) {
                Device *dev = &rooms[i].devices[rooms[i].device_count];
                strcpy(dev->name, device_name);
                dev->type = type;
                dev->state = OFF;
                rooms[i].device_count++;
                printf("Device '%s' added to room '%s'!\n", device_name, room_name);
            } else {
                printf("Cannot add more devices to room '%s'!\n", room_name);
            }
            return;
        }
    }
    printf("Room '%s' not found!\n", room_name);
}

void toggle_device(char *room_name, char *device_name) {
    for (int i = 0; i < room_count; i++) {
        if (strcmp(rooms[i].name, room_name) == 0) {
            for (int j = 0; j < rooms[i].device_count; j++) {
                if (strcmp(rooms[i].devices[j].name, device_name) == 0) {
                    rooms[i].devices[j].state = (rooms[i].devices[j].state == OFF) ? ON : OFF;
                    printf("Device '%s' in room '%s' toggled %s!\n", device_name, room_name, 
                           rooms[i].devices[j].state == ON ? "ON" : "OFF");
                    return;
                }
            }
            printf("Device '%s' not found in room '%s'!\n", device_name, room_name);
            return;
        }
    }
    printf("Room '%s' not found!\n", room_name);
}

void display_status() {
    for (int i = 0; i < room_count; i++) {
        printf("Room: %s\n", rooms[i].name);
        for (int j = 0; j < rooms[i].device_count; j++) {
            printf("  Device: %s | Type: %s | State: %s\n", rooms[i].devices[j].name, 
                   rooms[i].devices[j].type == LED ? "LED" : "LAMP", 
                   rooms[i].devices[j].state == ON ? "ON" : "OFF");
        }
        printf("\n");
    }
}

