    add_device("Living Room", "Ceiling Light", LED);
    add_device("Living Room", "Table Lamp", LAMP);
    add_device("Bedroom", "Night Lamp", LED);
    add_device("Kitchen", "LED Strip", LED);

    display_status();

    toggle_device("Living Room", "Ceiling Light");
    toggle_device("Bedroom", "Night Lamp");
    toggle_device("Kitchen", "LED Strip");

    display_status();

    toggle_device("Living Room", "Nonexistent Device");
    toggle_device("Nonexistent Room", "Ceiling Light");

    return 0;
}

