#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MIN_LENGTH 8
#define MAX_LENGTH 20
#define SPECIAL_CHARS "!@#$%^&*()-_=+[]{};:'\",.<>?/`~"

int hasUpperCase(const char *password) {
    while (*password) {
        if (isupper((unsigned char)*password)) {
            return 1;
        }
        password++;
    }
    return 0;
}

int hasLowerCase(const char *password) {
    while (*password) {
        if (islower((unsigned char)*password)) {
            return 1;
        }
        password++;
    }
    return 0;
}

int hasDigit(const char *password) {
    while (*password) {
        if (isdigit((unsigned char)*password)) {
            return 1;
        }
        password++;
    }
    return 0;
}

int hasSpecialChar(const char *password) {
    const char *ptr = SPECIAL_CHARS;
    while (*password) {
        if (strchr(ptr, (unsigned char)*password)) {
            return 1;
        }
        password++;
    }
    return 0;
}

int checkLength(const char *password) {
    int len = strlen(password);
    if (len < MIN_LENGTH) {
        printf("Password must be at least %d characters long.\n", MIN_LENGTH);
        return 0;
    } else if (len > MAX_LENGTH) {
        printf("Password must not exceed %d characters.\n", MAX_LENGTH);
        return 0;
    }
    return 1;
}

int isPasswordStrong(const char *password) {
    int strong = 1; // assume strong until proven otherwise
    strong &= checkLength(password);
    strong &= hasUpperCase(password);
    strong &= hasLowerCase(password);
    strong &= hasDigit(password);
    strong &= hasSpecialChar(password);

    if (strong) {
        printf("Password is strong!\n");
    } else {
        printf("Password is weak. Please try again.\n");
    }
    return strong;
}

int main() {
    char password[MAX_LENGTH + 1];

    printf("Welcome to the Password Strength Checker!\n");
    printf("Please enter a password (8-20 characters, must include:\n");
    printf("1. At least one uppercase letter\n");
    printf("2. At least one lowercase letter\n");
    printf("3. At least one digit\n");
    printf("4. At least one special character (%s)\n", SPECIAL_CHARS);

    while (1) {
        printf("Enter your password: ");
        fgets(password, sizeof(password), stdin);
        password[strcspn(password, "\n")] = 0; // remove newline character

        if (isPasswordStrong(password)) {
            break;
        }
        printf("Try again!\n\n");
    }

    printf("Thank you for creating a strong password!\n");
    return 0;
}

