// Define structure for vehicle state
struct VehicleState {
    int x;
    int y;
    int orientation;
};

// Function to update vehicle state
void updateVehicleState(struct VehicleState* state, int x, int y, int orientation) {
    state->x = x;
    state->y = y;
    state->orientation = orientation;
}

// Function to drive the vehicle
void driveVehicle(struct VehicleState* state, int motorSpeed, int steeringAngle) {
    printf("Driving vehicle with motor speed %d and steering angle %d\n", motorSpeed, steeringAngle);
    printf("Current position: (%d, %d), orientation: %d\n", state->x, state->y, state->orientation);
}

int main() {
    // Initialize vehicle state
    struct VehicleState vehicle;
    vehicle.x = 0;
    vehicle.y = 0;
    vehicle.orientation = 0;

    // Drive vehicle in a circle
    int radius = 10;
    int angleIncrement = 5;
    int angle = 0;

    while (true) {
        driveVehicle(&vehicle, MAX_MOTOR_SPEED, MAX_STEERING_ANGLE);

        angle += angleIncrement;
        if (angle > MAX_STEERING_ANGLE) {
            angle = 0;
