        // Update vehicle state
        int x = radius * cos(angle * 3.14159 / 180);
        int y = radius * sin(angle * 3.14159 / 180);
        updateVehicleState(&vehicle, x, y, angle);

        // Pause for 0.1 seconds
        sleep(0.1);
    }

    return 0;
}

