//LLAMA2-13B DATASET v1.0 Category: RAM usage monitor ; Style: asynchronous
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/types.h>
#include <unistd.h>
#include <pthread.h>

#define BLOCK_SIZE 4096
#define N_BLOCKS 1024

typedef struct block {
    void *start;
    size_t size;
} block_t;

static block_t *blocks;
static size_t total_used;

void *malloc_wrapper(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        perror("malloc");
    }
    return ptr;
}

void free_wrapper(void *ptr) {
    free(ptr);
}

void *brk_wrapper(size_t size) {
    void *ptr = brk(size);
    if (ptr == NULL) {
        perror("brk");
    }
    return ptr;
}

void sbrk_wrapper(size_t size) {
    sbrk(size);
}

void *get_block(size_t size) {
    for (int i = 0; i < N_BLOCKS; i++) {
        if (blocks[i].size >= size) {
            return blocks[i].start;
        }
    }
    return NULL;
}

void scan_blocks() {
    for (int i = 0; i < N_BLOCKS; i++) {
        if (blocks[i].size > 0) {
            total_used += blocks[i].size;
        }
    }
    printf("Total used: %zu\n", total_used);
}

int main() {
    blocks = calloc(N_BLOCKS, sizeof(block_t));
    if (blocks == NULL) {
        perror("calloc");
        return 1;
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, scan_blocks, NULL) != 0) {
        perror("pthread_create");
        return 1;
    }

    for (int i = 0; i < N_BLOCKS; i++) {
        blocks[i].start = brk_wrapper(BLOCK_SIZE);
        if (blocks[i].start == NULL) {
            perror("brk");
            return 1;
        }
        blocks[i].size = BLOCK_SIZE;
    }

    for (int i = 0; i < N_BLOCKS; i++) {
        if (get_block(BLOCK_SIZE) == NULL) {
            break;
        }
    }

    pthread_join(thread, NULL);

    return 0;
}

