#include <stdio.h>
#include <stdbool.h>
#include <stdlib.h>
#include <time.h>

#define MAX_VERTICES 10

// Define the structure for the graph
typedef struct Graph {
    int vertices;
    int **adj_matrix;
} Graph;

// Function to create a new graph with given number of vertices
Graph *createGraph(int vertices) {
    Graph *graph = (Graph *)malloc(sizeof(Graph));
    graph->vertices = vertices;
    graph->adj_matrix = (int **)malloc(vertices * sizeof(int *));

    for (int i = 0; i < vertices; i++) {
        graph->adj_matrix[i] = (int *)calloc(vertices, sizeof(int));
    }

    return graph;
}

// Function to add an edge between two vertices
void addEdge(Graph *graph, int src, int dest) {
    graph->adj_matrix[src][dest] = 1;
    graph->adj_matrix[dest][src] = 1;
}

// Function to perform depth-first search traversal starting from a vertex
void depthFirstSearch(Graph *graph, int src, bool *visited) {
    visited[src] = true;
    printf("%d ", src);

    for (int i = 0; i < graph->vertices; i++) {
        if (graph->adj_matrix[src][i] && !visited[i]) {
            depthFirstSearch(graph, i, visited);
        }
    }
}

// Function to print the adjacency matrix of the graph
void printGraph(Graph *graph) {
    printf("\nAdjacency Matrix:\n");

    for (int i = 0; i < graph->vertices; i++) {
        for (int j = 0; j < graph->vertices; j++) {
            printf("%d ", graph->adj_matrix[i][j]);
        }
        printf("\n");
    }
}

// Main function to test the graph creation and depth-first search
int main() {
    srand(time(NULL));

    Graph *graph = createGraph(5);

    printf("Enter edges (u, v):\n");

    for (int i = 0; i < 5; i++) {
        int u = rand() % 5;
        int v = rand() % 5;
        addEdge(graph, u, v);
        printf("Added edge %d -- %d\n", u, v);
    }

    printGraph(graph);

    bool *visited = (bool *)calloc(graph->vertices, sizeof(bool));

    printf("\nDepth-First Search traversal starting from vertex 0: ");
    depthFirstSearch(graph, 0, visited);

    free(visited);
    freeGraph(graph);

    return 0;
}

// Function to free the graph memory
void freeGraph(Graph *graph) {
    for (int i = 0; i < graph->vertices; i++) {
        free(graph->adj_matrix[i]);
    }
    free(graph->adj_matrix);
    free(graph);
}

//FormAI DATASET v1.0 Category: Procedurally Generated Maze ; Style: intelligent
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define ROWS 20
#define COLS 20

void generateMaze(int maze[ROWS][COLS], int row, int col);
void printMaze(int maze[ROWS][COLS]);

int main() {
    int maze[ROWS][COLS];
    srand(time(NULL));

    generateMaze(maze, 0, 0);
    printMaze(maze);

    return 0;
}

void generateMaze(int maze[ROWS][COLS], int row, int col) {
    int i, j;
    maze[row][col] = 1;

    // Shuffle the directions
    int directions[4] = {0, 1, 2, 3};
    for (i = 0; i < 4; i++) {
        int temp = directions[i];
        int swapIndex = rand() % 4;
        directions[i] = directions[swapIndex];
        directions[swapIndex] = temp;
    }

    for (i = 0; i < 4; i++) {
        int direction = directions[i];
        int newRow = row;
        int newCol = col;

        switch (direction) {
            case 0: // Up
                newRow--;
                break;
            case 1: // Right
                newCol++;
                break;
            case 2: // Down
                newRow++;
                break;
            case 3: // Left
                newCol--;
                break;
        }

        if (newRow < 0 || newRow >= ROWS || newCol < 0 || newCol >= COLS || maze[newRow][newCol] != 0) {
            continue;
        }

        // Knock down the wall in between
        if (direction == 0) { // Up
            maze[row][col] &= ~1;
            maze[newRow][newCol] &= ~4;
        } else if (direction == 1) { // Right
            maze[row][col] &= ~2;
            maze[newRow][newCol] &= ~8;
        } else if (direction == 2) { // Down
            maze[row][col] &= ~4;
            maze[newRow][newCol] &= ~1;
        } else if (direction == 3) { // Left
            maze[row][col] &= ~8;
            maze[newRow][newCol] &= ~2;
        }

        generateMaze(maze, newRow, newCol);
    }
}

void printMaze(int maze[ROWS][COLS]) {
    int i, j;
    printf(" ");
    for (i = 0; i < COLS * 2 - 1; i++) {
        printf("_");
    }
    printf("\n");

    for (i = 0; i < ROWS; i++) {
        printf("|");
        for (j = 0; j < COLS; j++) {
            if ((maze[i][j] & 2) == 0) {
                printf(" ");
            } else {
                printf("|");
            }

            if ((maze[i][j] & 4) == 0) {
                printf(" ");
            } else {
                printf("_");
            }
        }
        printf("\n");
    }
}

