#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pthread.h>

#define PORT 8080
#define MAX_CLIENTS 5
#define BUFFER_SIZE 1024

// Structure to pass arguments to the thread
typedef struct {
    int client_socket;
} client_arg;

void *handle_client(void *arg) {
    client_arg *c_arg = (client_arg *)arg;
    int client_socket = c_arg->client_socket;
    char buffer[BUFFER_SIZE];

    // Simulate receiving image data (just a string for this demo)
    int bytes_read = read(client_socket, buffer, BUFFER_SIZE - 1);
    buffer[bytes_read] = '\0';

    printf("Received image data from client: %s\n", buffer);

    // Mock image classification (this should be replaced with real logic)
    char *classification;
    if (strstr(buffer, "cat") != NULL) {
        classification = "Cat";
    } else if (strstr(buffer, "dog") != NULL) {
        classification = "Dog";
    } else {
        classification = "Unknown";
    }

    // Send back classification result to client
    write(client_socket, classification, strlen(classification));

    close(client_socket);
    free(c_arg);
    return NULL;
}

int main() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);

    // Create socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("Socket failed");
        exit(EXIT_FAILURE);
    }

    // Attach socket to the port
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt))) {
        perror("setsockopt");
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Bind the socket to the port
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Bind failed");
        exit(EXIT_FAILURE);
    }

    // Start listening for incoming connections
    if (listen(server_fd, MAX_CLIENTS) < 0) {
        perror("Listen failed");
        exit(EXIT_FAILURE);
    }

    printf("Server is listening on port %d...\n", PORT);

    while (1) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("Accept failed");
            continue;
        }

        printf("Accepted a new connection...\n");

        // Create a thread to handle the client
        pthread_t tid;
        client_arg *c_arg = (client_arg *)malloc(sizeof(client_arg));
        if (c_arg == NULL) {
            perror("Failed to allocate memory for client argument");
            close(new_socket);
            continue;
        }
        c_arg->client_socket = new_socket;

        if (pthread_create(&tid, NULL, handle_client, c_arg) != 0) {
            perror("Failed to create thread");
            close(new_socket);
            free(c_arg);
            continue;
        }
        pthread_detach(tid);  // Detach the thread to free resources on exit
    }

    close(server_fd);
    return 0;
}

