void add_subscriber(char *name, char *email) {
    struct entry *new_entry = malloc(sizeof(struct entry));
    if (new_entry == NULL) {
        printf("Error: Not enough memory to add a new subscriber.\n");
        return;
    }
    strcpy(new_entry->name, name);
    strcpy(new_entry->email, email);
    new_entry->next = head;
    head = new_entry;
}

