#include <iostream>

int* Merge(int *a, int *b, int n) {

    int* rezult = new int[n];

    for (int i = 0, j = 0; i < n && j < n && (i+j) < n;) {
        if (a[i] < b[j]) {
            rezult[i+j] = a[i];
            ++i;
        } else {
            rezult[i+j] = b[j];
            ++j;
        }
    }
    delete[] a;
    return rezult;
}

void make_heap(int *a, int n) {

    for (int i = n/2; i >= 1; --i) {
        for (int j = i; j <= n/2; ) {
            int k = j*2;

            if ((k+1 <= n) && (a[k] < a[k+1]))
                ++k;

            if (a[j] < a[k]) {
                std::swap(a[k], a[j]);
                j = k;
            } else
                break;
        }
    }
}

void pop_heap(int *a, int n) {

    std::swap(a[n], a[1]);

    for (int i = 1; 2*i < n; ) {
        i *= 2;

        if ((a[i] < a[i+1]) && (i+1 < n))
            ++i;

        if (a[i/2] < a[i])
            std::swap(a[i/2], a[i]);
    }
}

void heap_sort(int *a, int n) {
    make_heap(a-1, n);
    for (int i = 0; i < n; ++i)
        pop_heap(a - 1, n - i);
}



