//Falcon2-11B DATASET v1.0 Category: Graph Coloring Problem ; Style: Alan Turing
#include <stdio.h>
#include <stdlib.h>

int main() {
    // Initialize graph
    int V = 8; // number of vertices
    int E = 12; // number of edges
    int **graph = (int **)malloc(V * sizeof(int *));
    for (int i = 0; i < V; i++) {
        graph[i] = (int *)malloc(V * sizeof(int));
    }
    for (int i = 0; i < E; i++) {
        int u = i % V, v = (i + 1) % V;
        graph[u][v] = 1;
        graph[v][u] = 1;
    }

    // DFS algorithm
    int colors[V];
    for (int i = 0; i < V; i++) {
        colors[i] = -1;
    }
    int visited[V];
    for (int i = 0; i < V; i++) {
        visited[i] = 0;
    }
    int dfs(int node) {
        if (visited[node] == 1) {
            return -1;
        }
        visited[node] = 1;
        colors[node] = dfs(node + 1);
        for (int i = 0; i < V; i++) {
            if (graph[node][i] == 1 && colors[i] == -1) {
                colors[i] = colors[node] + 1;
                if (dfs(i) == -1) {
                    return -1;
                }
            }
        }
        return colors[node];
    }

    // Find maximum color
    int max_color = -1;
    for (int i = 0; i < V; i++) {
        if (colors[i] > max_color) {
            max_color = colors[i];
        }
    }

    // Output solution
    printf("Maximum color: %d\n", max_color);
    for (int i = 0; i < V; i++) {
        if (colors[i] == max_color) {
            printf("%d colored with color %d\n", i, max_color);
        }
    }

    // Free memory
    for (int i = 0; i < V; i++) {
        free(graph[i]);
    }
    free(graph);

    return 0;
}

