void swap(int &a, int &b){
	int temp = b;
	b = a;
	a = temp;
}

void sortAscending(){
	int tempValue;
	for(Node *p1=first; p1!=NULL; p1=p1->next){
		for(Node *p2=p1->next; p2!=NULL; p2=p2->next){
			if(p1->Value > p2->Value)	swap(p1->Value, p2->Value);
		}
	}
}

void sortDescending(){
	int tempValue;
	for(Node *p1=first; p1!=NULL; p1=p1->next){
		for(Node *p2=p1->next; p2!=NULL; p2=p2->next){
			if(p1->Value < p2->Value)	swap(p1->Value, p2->Value);
		}
	}
}

