#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <time.h>

#define NORTH 0
#define EAST 1
#define SOUTH 2
#define WEST 3

typedef struct {
    int x;
    int y;
    int direction;
} robot_t;

void move_robot(robot_t* robot, int direction) {
    switch (direction) {
        case NORTH:
            robot->y++;
            break;
        case EAST:
            robot->x++;
            break;
        case SOUTH:
            robot->y--;
            break;
        case WEST:
            robot->x--;
            break;
        default:
            break;
    }
}

void turn_robot(robot_t* robot, int direction) {
    switch (direction) {
        case NORTH:
            robot->direction = WEST;
            break;
        case EAST:
            robot->direction = NORTH;
            break;
        case SOUTH:
            robot->direction = EAST;
            break;
        case WEST:
            robot->direction = SOUTH;
            break;
        default:
            break;
    }
}

int main() {
    robot_t robot;
    robot.x = 0;
    robot.y = 0;
    robot.direction = NORTH;

    while (1) {
        move_robot(&robot, robot.direction);
        turn_robot(&robot, robot.direction);
    }

    return 0;
}

//GPT-4o-mini DATASET v1.0 Category: Public-Key Algorithm Implementation ; Style: artistic
#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>

#define MAX 100

typedef struct {
    int p;
    int q;
    int n;
    int phi;
    int e;
    int d;
} RSAKey;

int gcd(int a, int b) {
    if (b == 0)
        return a;
    return gcd(b, a % b);
}

int modInverse(int a, int m) {
    a = a % m;
    for (int x = 1; x < m; x++) {
        if ((a * x) % m == 1)
            return x;
    }
    return -1;
}

int isPrime(int num) {
    if (num <= 1)
        return 0;
    for (int i = 2; i <= sqrt(num); i++) {
        if (num % i == 0)
            return 0;
    }
    return 1;
}

RSAKey generateKeypair(int p, int q) {
    RSAKey key;
    key.p = p;
    key.q = q;
    key.n = key.p * key.q;
    key.phi = (key.p - 1) * (key.q - 1);

    // Public Exponent
    key.e = 2;
    while (key.e < key.phi) {
        if (gcd(key.e, key.phi) == 1)
            break;
        key.e++;
    }

    // Private Exponent
    key.d = modInverse(key.e, key.phi);
    return key;
}

void encrypt(int message, RSAKey key) {
    long long c = 1; // Ciphertext
    for (int i = 0; i < key.e; i++) {
        c = (c * message) % key.n;
    }
    printf("Encrypted message: %lld\n", c);
}

void decrypt(long long cipher, RSAKey key) {
    long long m = 1; // Decrypted message
    for (int i = 0; i < key.d; i++) {
        m = (m * cipher) % key.n;
    }
    printf("Decrypted message: %lld\n", m);
}

int main() {
    int p = 61; // example prime number
    int q = 53; // example prime number
    RSAKey key = generateKeypair(p, q);

    printf("Public Key (e, n): (%d, %d)\n", key.e, key.n);
    printf("Private Key (d): %d\n", key.d);

    int message;
    printf("Enter message to encrypt (number): ");
    scanf("%d", &message);

    encrypt(message, key);

    long long cipher;
    printf("Enter encrypted message to decrypt: ");
    scanf("%lld", &cipher);

    decrypt(cipher, key);

    return 0;
}

