				q = m[i][k] + m[k+1][j] + p[i-1]*p[k]*p[j];		
				if(q < m[i][j])
				{
					m[i][j] = q;
					s[i][j] = k;
				}
			}

		}
	}

		print_optimal_parens(s,1,n);
		cout << endl;
}



