    char pass[10];

    for (i = 0; i < len; i++) {
        pass[i] = 'a' + (rand() % 26);
    }

    pwd->password = pass;
    pwd->age = time(NULL);
}

// Define a function to check if a password is valid
int check_password(struct password *pwd, char *input) {
    int i, j, len = strlen(input);

    for (i = 0; i < len; i++) {
        if (pwd->password[i] != input[i]) {
            return 0;
        }
    }

    return 1;
}

