void 
BubbleSort::sort(int A[], int size)			// main entry point
{
	num_cmps = 0;
	for (int k = 1; k < size; k++)
		for (int i = 0; i <size - k; i++)
		{
			++num_cmps;
			if (A[i] > A[i +1]){
