#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the number of rows and columns in the game board
#define ROWS 6
#define COLUMNS 7

// Define the different types of game pieces
#define EMPTY 0
#define PLAYER1 1
#define PLAYER2 2

// Define the winning combinations
int winningCombinations[8][3] = {{0, 1, 2}, {3, 4, 5}, {6, 7, 8}, // Horizontal wins
                                  {0, 3, 6}, {1, 4, 7}, {2, 5, 8}, // Vertical wins
                                  {0, 4, 8}, {2, 4, 6}};        // Diagonal wins

// Define the game board
int gameBoard[ROWS][COLUMNS];

// Function to initialize the game board
void initializeGameBoard() {
  for (int i = 0; i < ROWS; i++) {
    for (int j = 0; j < COLUMNS; j++) {
      gameBoard[i][j] = EMPTY;
    }
  }
}

// Function to print the game board
void printGameBoard() {
  printf("\n");
  for (int i = 0; i < ROWS; i++) {
    printf("|");
    for (int j = 0; j < COLUMNS; j++) {
      switch (gameBoard[i][j]) {
      case EMPTY:
        printf(" ");
        break;
      case PLAYER1:
        printf("X");
        break;
      case PLAYER2:
        printf("O");
        break;
      }
      printf("|");
    }
    printf("\n");
  }
  printf("\n");
}

// Function to get the next move from the player
int getNextMove(int player) {
  int column;
  do {
    printf("Player %d, enter the column you want to drop your piece in (1-7): ", player);
    scanf("%d", &column);
  } while (column < 1 || column > COLUMNS || gameBoard[0][column - 1] != EMPTY);
  return column - 1;
}

// Function to drop a piece into the game board
void dropPiece(int column, int player) {
  for (int i = ROWS - 1; i >= 0; i--) {
    if (gameBoard[i][column] == EMPTY) {
      gameBoard[i][column] = player;
      break;
    }
  }
}

// Function to check if there is a winner
int checkForWinner() {
  // Check for horizontal wins
  for (int i = 0; i < ROWS; i++) {
    for (int j = 0; j < COLUMNS - 2; j++) {
      if (gameBoard[i][j] != EMPTY && gameBoard[i][j] == gameBoard[i][j + 1] && gameBoard[i][j] == gameBoard[i][j + 2]) {
        return gameBoard[i][j];
      }
    }
  }

  // Check for vertical wins
  for (int i = 0; i < ROWS - 2; i++) {
    for (int j = 0; j < COLUMNS; j++) {
      if (gameBoard[i][j] != EMPTY && gameBoard[i][j] == gameBoard[i + 1][j] && gameBoard[i][j] == gameBoard[i + 2][j]) {
        return gameBoard[i][j];
      }
    }
  }

  // Check for diagonal wins
  for (int i = 0; i < ROWS - 2; i++) {
    for (int j = 0; j < COLUMNS - 2; j++) {
      if (gameBoard[i][j] != EMPTY && gameBoard[i][j] == gameBoard[i + 1][j + 1] && gameBoard[i][j] == gameBoard[i + 2][j + 2]) {
        return gameBoard[i][j];
      }
    }
  }

  for (int i = 0; i < ROWS - 2; i++) {
    for (int j = 2; j < COLUMNS; j++) {
      if (gameBoard[i][j] != EMPTY && gameBoard[i][j] == gameBoard[i + 1][j - 1] && gameBoard[i][j] == gameBoard[i + 2][j - 2]) {
        return gameBoard[i][j];
      }
    }
  }

  // No winner yet
  return 0;
}

// Function to play the game
void playGame() {
  int player = PLAYER1; // Player 1 starts first
  int winner = 0;

  // Initialize the game board
  initializeGameBoard();

  // Print the game board
  printGameBoard();

  // While there is no winner
  while (winner == 0) {
    // Get the next move from the player
    int column = getNextMove(player);

    // Drop the piece into the game board
    dropPiece(column, player);

    // Print the game board
    printGameBoard();

