    {

        cout << "id: ";

        cin >> id;

        if (id < 0)

        {

            break;

        }

        cout << "grade: ";

        cin >> grade;



        pGrade = new Grade;

        pGrade->studId = id;

        pGrade->grade  = grade;

        ListAppend(pListGrades, pGrade);

