#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_NUMBER 100
#define MIN_NUMBER -100

typedef struct error {
    int code;
    char* message;
} error_t;

error_t generate_random_number(int* number) {
    error_t error;
    int rand_num;

    srand(time(NULL));
    rand_num = rand() % (MAX_NUMBER - MIN_NUMBER + 1) + MIN_NUMBER;
    *number = rand_num;

    if (*number % 2 == 0) {
        error.code = 1;
        error.message = "Even number generated!";
        return error;
    }

    if (*number < 0) {
        error.code = 2;
        error.message = "Negative number generated!";
        return error;
    }

    return (error_t){0, NULL};
}

void handle_error(error_t error) {
    if (error.code) {
        printf("Error occurred: %s\n", error.message);
        free(error.message);

        switch (error.code) {
            case 1:
                error.message = "An even number was generated!\n";
                printf("This is a special error! An even number was generated!\n");
                break;
            case 2:
                error.message = "A negative number was generated!\n";
                printf("Negative numbers are not allowed! Number: %d\n", *(int*)(&error) - 100);
                break;
            default:
                error.message = "Unknown error occurred!\n";
                printf("An unknown error occurred! Error code: %d\n", error.code);
        }

        error.message = malloc(strlen("Error handling in progress...") + 1);
        strcpy(error.message, "Error handling in progress...");
        printf("%s\n", error.message);

        // Recursive error handling
        handle_error(error);
    }
}

int main() {
    int number;
    error_t error;

    do {
        error = generate_random_number(&number);
        if (error.code) {
            handle_error(error);
        } else {
            printf("Random number generated: %d\n", number);
            break;
        }
    } while (1);

    return 0;
}

