using namespace std;

set<int> 
get_primes(int N)
{
    vector<bool> primes;
    set<int> prime_set;
    for (int i = 0; i <= N; ++i)
	primes.push_back(true);
    primes[0] = false;
    primes[1] = false;

    // We only need to loop until the square root of the max. number
    for (int i = 2; i <= sqrt(N); ++i)
	if (primes[i])
	    for (int j = i*i; j <= N; j += i)
		primes[j] = false;
    for (int i = 0; i <= N; i++)
	if (primes[i])
	    prime_set.insert(i);

    return prime_set;
}

