  for (int i = 0; i < strlen(input); i++) {
    entropy += (int)input[i];
  }

  // Print the entropy
  printf("Entropy: %d\n", entropy);

  // Calculate the mutual information between the input and the random string
  int mutual_information = 0;
  for (int i = 0; i < strlen(input); i++) {
