#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <stdbool.h>

// Structure to store word and its frequency
typedef struct {
    char word[256];
    int frequency;
} WordFrequency;

// Function to get the frequency of each word in a given text
int getWordFrequency(const char* text, WordFrequency* wordFrequencies, int maxWords) {
    // Initialize the word frequencies to 0
    for (int i = 0; i < maxWords; i++) {
        wordFrequencies[i].frequency = 0;
    }

    // Loop through the text and increment the frequency of each word
    char* word = strtok(text, " ");
    while (word != NULL) {
        // Check if the word is already in the word frequencies array
        bool found = false;
        for (int i = 0; i < maxWords; i++) {
            if (strcmp(word, wordFrequencies[i].word) == 0) {
                // If the word is found, increment its frequency
                wordFrequencies[i].frequency++;
                found = true;
                break;
            }
        }

        // If the word is not found, add it to the word frequencies array
        if (!found) {
            strcpy(wordFrequencies[maxWords].word, word);
            wordFrequencies[maxWords].frequency = 1;
            maxWords++;
        }

        // Get the next word
        word = strtok(NULL, " ");
    }

    return maxWords;
}

// Function to print the word frequencies
void printWordFrequencies(WordFrequency* wordFrequencies, int numWords) {
    for (int i = 0; i < numWords; i++) {
        printf("%s: %d\n", wordFrequencies[i].word, wordFrequencies[i].frequency);
    }
}

