#include <string.h>
#include <stdint.h>

// Function to hide data in an image
void hideData(unsigned char *image, size_t imageSize, unsigned char *data, size_t dataSize) {
    // Calculate the number of bytes that can be hidden in the image
    size_t bytesToHide = imageSize / 8;

    // Check if there is enough space to hide the data
    if (bytesToHide < dataSize) {
        printf("Error: Not enough space to hide the data in the image\n");
        return;
    }

    // Hide the data in the image
    for (size_t i = 0; i < dataSize; i++) {
        image[i] ^= data[i];
    }
}

// Function to extract hidden data from an image
void extractData(unsigned char *image, size_t imageSize, unsigned char *data) {
    // Calculate the number of bytes that can be hidden in the image
    size_t bytesToHide = imageSize / 8;

    // Check if there is any hidden data in the image
    if (bytesToHide == 0) {
        printf("Error: No data hidden in the image\n");
        return;
    }

    // Extract the hidden data from the image
    for (size_t i = 0; i < bytesToHide; i++) {
        data[i] = image[i] ^ data[i];
    }
}

int main() {
    // Define the image and data to be hidden
    unsigned char image[1000] = { 0 };
    unsigned char data[100] = { 0 };
    size_t dataSize = sizeof(data);

    // Fill the image with random data
    for (size_t i = 0; i < sizeof(image); i++) {
        image[i] = rand() % 255;
    }

    // Fill the data to be hidden with random data
    for (size_t i = 0; i < dataSize; i++) {
        data[i] = rand() % 255;
    }

    // Hide the data in the image
    hideData(image, sizeof(image), data, dataSize);

    // Extract the hidden data from the image
    extractData(image, sizeof(image), data);

    // Print the original and extracted data
    printf("Original data: ");
    for (size_t i = 0; i < dataSize; i++) {
        printf("%02X ", data[i]);
    }
    printf("\n");
    printf("Extracted data: ");
    for (size_t i = 0; i < dataSize; i++) {
        printf("%02X ", data[i]);
    }
    printf("\n");

    return 0;
}

