void replace(std::vector<std::string> &ref, std::string old, std::string replacement) {
	std::vector<std::string>::iterator iter;
	for (iter = ref.begin(); iter != ref.end(); iter++) {
		if (*iter == old) {
			iter = ref.erase(iter);
			iter = ref.insert(iter, replacement);
		}
	}
}

