#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_URL_LENGTH 2048
#define RESERVED_CHARS "!*'();:@&=+$,/?#[]"

void url_encode(char *src, char *dest) {
    char *hex = "0123456789ABCDEF";
    while (*src) {
        if (isalnum((unsigned char)*src) || strchr(RESERVED_CHARS, *src)) {
            *dest++ = *src;
        } else {
            *dest++ = '%';
            *dest++ = hex[(*src >> 4) & 0x0F];
            *dest++ = hex[*src & 0x0F];
        }
        src++;
    }
    *dest = '\0';
}

bool is_valid_url(const char *url) {
    if (strlen(url) == 0 || strlen(url) > MAX_URL_LENGTH) {
        return false;
    }
    // Simple check for schema (http or https)
    if (strncmp(url, "http://", 7) != 0 && strncmp(url, "https://", 8) != 0) {
        return false;
    }
    return true;
}

void sanitize_url(char *input_url) {
    char sanitized_url[MAX_URL_LENGTH] = {0};

    // Validate the URL first
    if (!is_valid_url(input_url)) {
        printf("Invalid URL: %s\n", input_url);
        return;
    }

    url_encode(input_url, sanitized_url);
    printf("Sanitized URL: %s\n", sanitized_url);
}

