void insertionSort(int arr[], int n)
{
    int i, j, key, temp;

    for (i = 1; i < n; i++)
    {
        key = arr[i];
        j = i - 1;

        while (j >= 0 && key < arr[j])
        {
            arr[j + 1] = arr[j];
            j--;
        }

        arr[j + 1] = key;
    }
}

void greedyAlgorithm(int n)
{
    int arr[n], i, j, total = 0;

    for (i = 0; i < n; i++)
    {
        arr[i] = rand() % MAX;
    }

    insertionSort(arr, n);

    for (i = 0; i < n; i++)
    {
        total += arr[i];
    }

    printf("Total sum of the array elements: %d\n", total);
}

