/// SOUND

int FMODAudioManager::load_sound(const char* source_file, const char* name)
{
  // load wave file
  FMOD_SOUND* new_sound;
  result =
    FMOD_System_CreateSound(system, source_file, FMOD_CREATESAMPLE, 0, &new_sound);

  // check that the sound was loaded successfully
  ASSERT_FMOD(result, source_file);
  // save under requested name
  str_id hash = numerise(name);
  sounds[hash] = new_sound;

  // All clear !
  return EXIT_SUCCESS;
}

int FMODAudioManager::play_sound(const char* name)
{
  // hash the string to find the resource
  if(play_sound(numerise(name)) == EXIT_FAILURE)
    WARN_RTN("AudioManager::play_sound invalid identifier", name, EXIT_FAILURE);

  return EXIT_SUCCESS;
}

int FMODAudioManager::play_sound(str_id id)
{
  // search for the resource
  SoundI i = sounds.find(id);
  // make sure that it is found
  if(i == sounds.end())
    return EXIT_FAILURE;
  // attempt to play the sound if it is
  result =
    FMOD_System_PlaySound(system, FMOD_CHANNEL_FREE, (*i).second, 0, NULL);
  WARN_IF(result != FMOD_OK, FMOD_ErrorString(result), EXIT_FAILURE);


  // All clear !
  return EXIT_SUCCESS;
}

//Falcon-180B DATASET v1.0 Category: Percolation Simulator ; Style: grateful
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define SIZE 50

int grid[SIZE][SIZE];
int num_sites = 0;

void init_grid() {
    for (int i = 0; i < SIZE; i++) {
        for (int j = 0; j < SIZE; j++) {
            grid[i][j] = -1;
        }
    }
}

int is_valid_site(int i, int j) {
    if (i < 0 || i >= SIZE || j < 0 || j >= SIZE) {
        return 0;
    }
    return 1;
}

int is_connected(int i, int j) {
    if (grid[i][j] == 1) {
        return 1;
    }
    if (grid[i][j] == -1) {
        return 0;
    }
    grid[i][j] = -1;
    int neighbors = 0;
    if (is_valid_site(i - 1, j) && grid[i - 1][j] == 1) {
        neighbors++;
    }
    if (is_valid_site(i + 1, j) && grid[i + 1][j] == 1) {
        neighbors++;
    }
    if (is_valid_site(i, j - 1) && grid[i][j - 1] == 1) {
        neighbors++;
    }
    if (is_valid_site(i, j + 1) && grid[i][j + 1] == 1) {
        neighbors++;
    }
    if (neighbors > 0) {
        return 1;
    }
    return 0;
}

void percolate() {
    for (int i = 0; i < SIZE; i++) {
        for (int j = 0; j < SIZE; j++) {
            if (grid[i][j] == -1) {
                if (is_connected(i, j)) {
                    grid[i][j] = 1;
                    num_sites++;
                }
            }
        }
    }
}

int main() {
    srand(time(NULL));
    init_grid();
    int k = 0;
    while (k < SIZE * SIZE) {
        int i = rand() % SIZE;
        int j = rand() % SIZE;
        if (grid[i][j] == -1) {
            grid[i][j] = 1;
            num_sites++;
            k++;
        }
    }
    printf("Number of sites: %d\n", num_sites);
    percolate();
    printf("Percolation threshold: %f\n", (double)num_sites / (SIZE * SIZE));
    return 0;
}

//LLAMA2-13B DATASET v1.0 Category: Encryption ; Style: dynamic
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>

#define KEY_SIZE 16
#define MSG_SIZE 256

// Define a struct to hold the encryption context
typedef struct {
    char key[KEY_SIZE];
    char msg[MSG_SIZE];
    int index;
} context_t;

// Define a function to generate a random key
void generate_key(context_t *ctx) {
    int i;
    for (i = 0; i < KEY_SIZE; i++) {
        ctx->key[i] = rand() % 256;
    }
}

// Define a function to encrypt the message
void encrypt(context_t *ctx) {
    int i, j;
    for (i = 0; i < MSG_SIZE; i++) {
        // XOR the message with the key
        ctx->msg[i] = ctx->msg[i] ^ ctx->key[ctx->index];
        // Increment the index
        ctx->index++;
        if (ctx->index >= KEY_SIZE) {
            ctx->index = 0;
        }
    }
}

// Define a function to decrypt the message
void decrypt(context_t *ctx) {
    int i, j;
    for (i = 0; i < MSG_SIZE; i++) {
        // XOR the message with the key (in reverse order)
        ctx->msg[i] = ctx->msg[i] ^ ctx->key[KEY_SIZE - ctx->index - 1];
        // Decrement the index
        ctx->index--;
        if (ctx->index < 0) {
            ctx->index = KEY_SIZE - 1;
        }
    }
}

int main() {
    context_t ctx;
    generate_key(&ctx);
    printf("Original message: %s\n", ctx.msg);
    encrypt(&ctx);
    printf("Encrypted message: %s\n", ctx.msg);
    decrypt(&ctx);
    printf("Decrypted message: %s\n", ctx.msg);
    return 0;
}

