#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define MAX_POINTS 100

typedef struct Point {
    int x;
    int y;
} Point;

int main() {

    // Create an array of points
    Point points[MAX_POINTS];

    // Populate the points
    points[0].x = 1;
    points[0].y = 1;
    points[1].x = 2;
    points[1].y = 2;
    points[2].x = 3;
    points[2].y = 3;
    points[3].x = 4;
    points[3].y = 4;

    // Calculate the distances between each point and every other point
    int i, j, d;
    for (i = 0; i < MAX_POINTS; i++) {
        for (j = 0; j < MAX_POINTS; j++) {
            if (i != j) {
                d = sqrt(pow(points[i].x - points[j].x, 2) + pow(points[i].y - points[j].y, 2));
                printf("Distance between points %d and %d is %d\n", i, j, d);
            }
        }
    }

    // Create a cluster of points
    int cluster[MAX_POINTS];
    cluster[0] = 0;
    cluster[1] = 0;
    cluster[2] = 1;
    cluster[3] = 1;

    // Print the cluster
    for (i = 0; i < MAX_POINTS; i++) {
        printf("Point %d belongs to cluster %d\n", i, cluster[i]);
    }

    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

void printVector(vector<int> &vect)
{
	for(int elem : vect)
	{
		cout << elem << " ";
	}
	cout << endl;
}

int main(int argc, char **argv)
{

	vector<int> array = {5,2,4,6,1,3};

	printVector(array);

	for (int j = 1; j < array.size(); j++)
	{
		int key = array[j];
		int i = j-1;
		while(i >= 0 && array[i] > key)
		{
			array[i+1] = array[i];
			i--;
		}
		array[i+1] = key;
	}

	printVector(array);
	return 0;
}

