// Bingo Simulator
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// define the number of rows and columns of the bingo card
#define ROWS 5
#define COLS 5

// define the number of bingo cards
#define NUM_CARDS 5

// define the bingo card data structure
typedef struct {
    int data[ROWS][COLS];
} Card;

// define the bingo card state data structure
typedef struct {
    int row[ROWS];
    int col[COLS];
} CardState;

// generate a random number between 1 and 75 (the number of possible bingo numbers)
int generate_number() {
    return rand() % 75 + 1;
}

// generate a random bingo card
Card generate_card() {
    Card card;
    for (int i = 0; i < ROWS; i++) {
        for (int j = 0; j < COLS; j++) {
            card.data[i][j] = generate_number();
        }
    }
    return card;
}

// print a bingo card
void print_card(Card card) {
    for (int i = 0; i < ROWS; i++) {
        for (int j = 0; j < COLS; j++) {
            printf("%d ", card.data[i][j]);
        }
        printf("\n");
    }
}

// check if a number is on a bingo card
int is_on_card(Card card, int number) {
    for (int i = 0; i < ROWS; i++) {
        for (int j = 0; j < COLS; j++) {
            if (card.data[i][j] == number) {
                return 1;
            }
        }
    }
    return 0;
}

// check if a card has a bingo
int has_bingo(Card card, CardState card_state) {
    // check rows
    for (int i = 0; i < ROWS; i++) {
        int row_sum = 0;
        for (int j = 0; j < COLS; j++) {
            if (card_state.row[i] == 1) {
                row_sum++;
            }
        }
        if (row_sum == COLS) {
            return 1;
        }
    }

    // check columns
    for (int i = 0; i < COLS; i++) {
        int col_sum = 0;
        for (int j = 0; j < ROWS; j++) {
            if (card_state.col[i] == 1) {
                col_sum++;
            }
        }
        if (col_sum == ROWS) {
            return 1;
        }
    }

    // check diagonals
    int diag_sum = 0;
    for (int i = 0; i < ROWS; i++) {
        if (card_state.row[i] == 1 && card_state.col[i] == 1) {
            diag_sum++;
        }
    }
    if (diag_sum == ROWS) {
        return 1;
    }

    return 0;
}

int main() {
    // generate the bingo cards
    Card cards[NUM_CARDS];
    for (int i = 0; i < NUM_CARDS; i++) {
        cards[i] = generate_card();
    }

    // print the bingo cards
    for (int i = 0; i < NUM_CARDS; i++) {
        printf("Bingo Card %d:\n", i + 1);
        print_card(cards[i]);
        printf("\n");
    }

    // simulate bingo
    CardState card_states[NUM_CARDS];
    for (int i = 0; i < NUM_CARDS; i++) {
        card_states[i].row[0] = 0;
        card_states[i].row[1] = 0;
        card_states[i].row[2] = 0;
        card_states[i].row[3] = 0;
        card_states[i].row[4] = 0;
        card_states[i].col[0] = 0;
        card_states[i].col[1] = 0;
        card_states[i].col[2] = 0;
        card_states[i].col[3] = 0;
        card_states[i].col[4] = 0;
    }

    // randomly generate bingo numbers
    int numbers[75];
    for (int i = 0; i < 75; i++) {
        numbers[i] = generate_number();
    }

    // simulate bingo
    for (int i = 0; i < 75; i++) {
        int number = numbers[i];
        for (int j = 0; j < NUM_CARDS; j++) {
            if (is_on_card(cards[j], number)) {
                if (j == 0) {
                    printf("Bingo! Number %d is on card %d\n", number, j + 1);
                }
                card_states[j].row[i / COLS] = 1;
                card_states[j].col[i % COLS] = 1;
            }
        }
    }

    // check for bingo
    for (int i = 0; i < NUM_CARDS; i++) {
        if (has_bingo(cards[i], card_states[i])) {
            printf("Card %d has bingo!\n", i + 1);
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// A Huffman tree node
struct MinHeapNode {
    char data;
    unsigned freq;
    struct MinHeapNode *left, *right;
};

struct MinHeap {
    unsigned size;
    unsigned capacity;
    struct MinHeapNode** array; // array of min heap node pointers
};

// A utility function to create a new Min Heap Node
struct MinHeapNode* newMinHeapNode(char data, unsigned freq) {
    struct MinHeapNode* temp = (struct MinHeapNode*) malloc(sizeof(struct MinHeapNode));
    temp->left = temp->right = NULL;
    temp->data = data;
    temp->freq = freq;
    return temp;
}

// A utility function to create a Min Heap of given capacity
struct MinHeap* createMinHeap(unsigned capacity) {
    struct MinHeap* minHeap = (struct MinHeap*) malloc(sizeof(struct MinHeap));
    minHeap->size = 0;
    minHeap->capacity = capacity;
    minHeap->array = (struct MinHeapNode**)malloc(minHeap->capacity * sizeof(struct MinHeapNode*));
    return minHeap;
}

// Function to swap two min heap nodes
void swapMinHeapNode(struct MinHeapNode** a, struct MinHeapNode** b) {
    struct MinHeapNode* t = *a;
    *a = *b;
    *b = t;
}

// Standard MinHeapify function
void minHeapify(struct MinHeap* minHeap, int idx) {
    int smallest = idx;
    int left = 2 * idx + 1;
    int right = 2 * idx + 2;
    if (left < minHeap->size && minHeap->array[left]->freq < minHeap->array[smallest]->freq)
        smallest = left;
    if (right < minHeap->size && minHeap->array[right]->freq < minHeap->array[smallest]->freq)
        smallest = right;
    if (smallest != idx) {
        swapMinHeapNode(&minHeap->array[smallest], &minHeap->array[idx]);
        minHeapify(minHeap, smallest);
    }
}

// A utility function to check if size of heap is 1 or not
int isSizeOne(struct MinHeap* minHeap) {
    return (minHeap->size == 1);
}

// A standard function to extract minimum value node from heap
struct MinHeapNode* extractMin(struct MinHeap* minHeap) {
    struct MinHeapNode* temp = minHeap->array[0];
    minHeap->array[0] = minHeap->array[minHeap->size - 1];
    --minHeap->size;
    minHeapify(minHeap, 0);
    return temp;
}

// A standard function to insert a new node to Min Heap
void insertMinHeap(struct MinHeap* minHeap, struct MinHeapNode* minHeapNode) {
    ++minHeap->size;
    int i = minHeap->size - 1;
    while (i && minHeapNode->freq < minHeap->array[(i - 1) / 2]->freq) {
        minHeap->array[i] = minHeap->array[(i - 1) / 2];
        i = (i - 1) / 2;
    }
    minHeap->array[i] = minHeapNode;
}

// A utility function to build min heap
void buildMinHeap(struct MinHeap* minHeap) {
    int n = minHeap->size - 1;
    for (int i = (n - 1) / 2; i >= 0; --i)
        minHeapify(minHeap, i);
}

// Function to print an array of size n 
void printArray(int arr[], int n) {
    for (int i = 0; i < n; ++i)
        printf("%d", arr[i]);
    printf("\n");
}

// A utility function to check if this node is leaf
int isLeaf(struct MinHeapNode* root) {
    return !(root->left) && !(root->right);
}

// Creates a min heap of capacity equal to size and inserts all character of 
// data[] in min heap. Initially size of min heap is equal to capacity
struct MinHeap* createAndBuildMinHeap(char data[], int freq[], int size) {
    struct MinHeap* minHeap = createMinHeap(size);
    for (int i = 0; i < size; ++i)
        minHeap->array[i] = newMinHeapNode(data[i], freq[i]);
    minHeap->size = size;
    buildMinHeap(minHeap);
    return minHeap;
}

// The main function that builds Huffman tree
struct MinHeapNode* buildHuffmanTree(char data[], int freq[], int size) {
    struct MinHeapNode *left, *right, *top;
    // Step 1: Create a min heap of capacity equal to size. Initially, there are
    // modes equal to size.
    struct MinHeap* minHeap = createAndBuildMinHeap(data, freq, size);
    // Iterate till heap size is one
    while (!isSizeOne(minHeap)) {
        // Step 2: Extract the two minimum frequency items from the min heap
        left = extractMin(minHeap);
        right = extractMin(minHeap);
        // Step 3: Create a new inner node with frequency equal to the sum of the 
        // two nodes frequencies. Make the two extracted node as left and right children 
        // of this new node. Add this node to the min heap
        top = newMinHeapNode('$', left->freq + right->freq);
        top->left = left;
        top->right = right;
        insertMinHeap(minHeap, top);
    }
    // Step 5: The remaining node is the root node and the tree is complete.
    return extractMin(minHeap);
}

// Print Huffman codes from the root of Huffman Tree. It uses arr[] to store codes
void printCodes(struct MinHeapNode* root, int arr[], int top) {
    // Assign 0 to left edge and recur
    if (root->left) {
        arr[top] = 0;
        printCodes(root->left, arr, top + 1);
    }
    // Assign 1 to right edge and recur
    if (root->right) {
        arr[top] = 1;
        printCodes(root->right, arr, top + 1);
    }
    // If this is a leaf node, then it contains one of the input characters 
    // and print the character along with its binary Huffman code
    if (isLeaf(root)) {
        printf("%c: ", root->data);
        printArray(arr, top);
    }
}

// The main function that builds a Huffman Tree and print codes by traversing it
