#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <SDL2/SDL.h>

#define WIDTH 800
#define HEIGHT 800
#define MAX_ITER 1000

// Function to map the pixel coordinates to the complex plane
void mapPixelToComplex(int x, int y, double* real, double* imag) {
    *real = (x - WIDTH / 2.0) * 4.0 / WIDTH;
    *imag = (y - HEIGHT / 2.0) * 4.0 / HEIGHT;
}

// Function to compute the Mandelbrot set
int mandelbrot(double real, double imag) {
    double zReal = 0, zImag = 0;
    int iter;

    for (iter = 0; iter < MAX_ITER; ++iter) {
        double zReal2 = zReal * zReal;
        double zImag2 = zImag * zImag;

        if (zReal2 + zImag2 > 4) break; // Escape condition

        zImag = 2 * zReal * zImag + imag;
        zReal = zReal2 - zImag2 + real;
    }
    return iter;
}

// Function to set the pixel color based on the number of iterations
Uint32 getColor(int iter) {
    if (iter == MAX_ITER) return SDL_MapRGB(SDL_AllocFormat(SDL_PIXELFORMAT_RGBA8888), 0, 0, 0);
    return SDL_MapRGB(SDL_AllocFormat(SDL_PIXELFORMAT_RGBA8888), (iter % 256), (iter * 5) % 256, (iter * 10) % 256);
}

// Main function for generating the Mandelbrot set
int main() {
    if (SDL_Init(SDL_INIT_VIDEO) < 0) {
        fprintf(stderr, "Could not initialize SDL: %s\n", SDL_GetError());
        return 1;
    }

    SDL_Window* window = SDL_CreateWindow("Mandelbrot Set", SDL_WINDOWPOS_UNDEFINED, SDL_WINDOWPOS_UNDEFINED, WIDTH, HEIGHT, 0);
    if (!window) {
        fprintf(stderr, "Could not create window: %s\n", SDL_GetError());
        SDL_Quit();
        return 1;
    }

    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);
    if (!renderer) {
        fprintf(stderr, "Could not create renderer: %s\n", SDL_GetError());
        SDL_DestroyWindow(window);
        SDL_Quit();
        return 1;
    }

    SDL_Texture* texture = SDL_CreateTexture(renderer, SDL_PIXELFORMAT_RGBA8888, SDL_TEXTUREACCESS_STATIC, WIDTH, HEIGHT);
    if (!texture) {
        fprintf(stderr, "Could not create texture: %s\n", SDL_GetError());
        SDL_DestroyRenderer(renderer);
        SDL_DestroyWindow(window);
        SDL_Quit();
        return 1;
    }

    Uint32* pixels = (Uint32*)malloc(WIDTH * HEIGHT * sizeof(Uint32));
    if (!pixels) {
        fprintf(stderr, "Could not allocate pixel array: %s\n", SDL_GetError());
        SDL_DestroyTexture(texture);
        SDL_DestroyRenderer(renderer);
        SDL_DestroyWindow(window);
        SDL_Quit();
        return 1;
    }

    for (int y = 0; y < HEIGHT; ++y) {
        for (int x = 0; x < WIDTH; ++x) {
            double real, imag;
            mapPixelToComplex(x, y, &real, &imag);
            int iter = mandelbrot(real, imag);
            pixels[y * WIDTH + x] = getColor(iter);
        }
    }

    SDL_UpdateTexture(texture, NULL, pixels, WIDTH * sizeof(Uint32));
    SDL_RenderClear(renderer);
    SDL_RenderCopy(renderer, texture, NULL, NULL);
    SDL_RenderPresent(renderer);

    SDL_Event event;
    int running = 1;
    while (running) {
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) running = 0;
        }
    }

    free(pixels);
    SDL_DestroyTexture(texture);
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();
    return 0;
}

