int isVirus(unsigned char *signature, unsigned char *fileContents, int fileLength) {
    int i, j;
    int sigLen = strlen((const char *)signature);
    int matchCount = 0;

    for (i = 0; i < fileLength - sigLen; i++) {
        for (j = 0; j < sigLen; j++) {
            if (signature[j] != fileContents[i+j]) {
                break;
            }
            matchCount++;
            if (matchCount == sigLen) {
                return 1;
            }
        }
    }
    return 0;
}

