#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define PORT 8080
#define MAX_CLIENTS 10
#define BUFFER_SIZE 1024

void handle_client(int client_socket);

int main() {
    int server_fd, client_socket, addr_len;
    struct sockaddr_in address;
    int option = 1;

    // Create socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    // Set socket options
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &option, sizeof(option))) {
        perror("setsockopt failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    // Configure server address
    address.sin_family = AF_INET; // IPv4
    address.sin_addr.s_addr = INADDR_ANY; // Bind to any address
    address.sin_port = htons(PORT); // Port number

    // Bind the socket to the address
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    // Start listening for incoming connections
    if (listen(server_fd, MAX_CLIENTS) < 0) {
        perror("listen failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    printf("Server listening on port %d...\n", PORT);

    while (1) {
        addr_len = sizeof(address);
        // Accept incoming connection
        if ((client_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addr_len)) < 0) {
            perror("accept failed");
            continue;
        }

        printf("Accepted connection from %s:%d\n", inet_ntoa(address.sin_addr), ntohs(address.sin_port));
        handle_client(client_socket);
    }

    // Close server socket
    close(server_fd);
    return 0;
}

void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE] = {0};
    int bytes_read;

    // Send welcome message to client
    const char *welcome_msg = "Welcome to the TCP/IP Echo Server!\n";
    send(client_socket, welcome_msg, strlen(welcome_msg), 0);

    while ((bytes_read = read(client_socket, buffer, BUFFER_SIZE)) > 0) {
        // Echo the received message back to the client
        buffer[bytes_read] = '\0'; // Null-terminate the string
        printf("Received from client: %s", buffer);
        send(client_socket, buffer, bytes_read, 0); // Send back the same message
    }

    if (bytes_read == 0) {
        printf("Client disconnected.\n");
    } else {
        perror("read failed");
    }

    // Close client socket
    close(client_socket);
}

