float deQuy(int n) // đệ quy
{
    if(n == 1)
        return 1;
    return deQuy(n - 1) * n;
}

float deQuyDuoi(int n, float x = 1)  // đệ quy đuôi
{
    if(n == 1)
        return x;
    return deQuyDuoi(n - 1, x * n);
}

float khuDeQuy(int n) // khử đệ quy
{
    int i = 1;
    float P = 1;

    while(i <= n)
    {
        P = P * i;
        i++;
    }
    return P;
}
