#define MAX_POINTS 100
#define MAX_DIM 2

typedef struct {
    double x;
    double y;
} Point;

typedef struct {
    Point centroid;
    int size;
} Cluster;

Cluster clusters[3];
Point data_points[MAX_POINTS];

void initialize_clusters() {
    int i;

    for (i = 0; i < 3; i++) {
        clusters[i].size = 0;
        clusters[i].centroid.x = (rand() % MAX_POINTS) / 10.0;
        clusters[i].centroid.y = (rand() % MAX_POINTS) / 10.0;
    }
}

int find_closest_cluster(Point point) {
    int i, min_dist_index = 0;
    double min_dist = sqrt(pow(point.x - clusters[0].centroid.x, 2) + pow(point.y - clusters[0].centroid.y, 2));

    for (i = 1; i < 3; i++) {
        double dist = sqrt(pow(point.x - clusters[i].centroid.x, 2) + pow(point.y - clusters[i].centroid.y, 2));

        if (dist < min_dist) {
            min_dist = dist;
            min_dist_index = i;
        }
    }

    return min_dist_index;
}

void update_clusters() {
    int i, j;
    double total_x = 0, total_y = 0;

    for (i = 0; i < 3; i++) {
        for (j = 0; j < clusters[i].size; j++) {
            total_x += data_points[j].x;
            total_y += data_points[j].y;
        }

        clusters[i].centroid.x = total_x / clusters[i].size;
        clusters[i].centroid.y = total_y / clusters[i].size;
    }
}

void process_data_point(Point point) {
    int cluster_index = find_closest_cluster(point);

    data_points[clusters[cluster_index].size] = point;
    clusters[cluster_index].size++;
}

int main() {
    int i, iterations = 10;

    srand(time(NULL));

    for (i = 0; i < MAX_POINTS; i++) {
        data_points[i].x = (rand() % MAX_POINTS) / 10.0;
        data_points[i].y = (rand() % MAX_POINTS) / 10.0;
    }

    initialize_clusters();

    for (i = 0; i < iterations; i++) {
        Point current_point;

        for (int j = 0; j < MAX_POINTS; j++) {
            current_point = data_points[j];
            process_data_point(current_point);
        }

        update_clusters();
    }

    printf("\nClusters after %d iterations:\n", iterations);

    for (i = 0; i < 3; i++) {
        printf("\nCluster %d:\n", i + 1);
        printf("Centroid: (%f, %f), Size: %d\n", clusters[i].centroid.x, clusters[i].centroid.y, clusters[i].size);

        for (int j = 0; j < clusters[i].size; j++) {
            printf("Point %d: (%f, %f)\n", j + 1, data_points[j].x, data_points[j].y);
        }
    }

    return 0;
}

