//GPT-4o-mini DATASET v1.0 Category: Data structures visualization ; Style: multi-threaded
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

typedef struct Node {
    int data;
    struct Node* left;
    struct Node* right;
} Node;

typedef struct ThreadData {
    Node** root;
    int value;
} ThreadData;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to create a new BST node
Node* createNode(int data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = data;
    newNode->left = NULL;
    newNode->right = NULL;
    return newNode;
}

// Function to insert a new node into the BST
void insert(Node** root, int data) {
    if (*root == NULL) {
        *root = createNode(data);
        return;
    }
    if (data < (*root)->data) {
        insert(&((*root)->left), data);
    } else {
        insert(&((*root)->right), data);
    }
}

// Thread function to insert a value into the BST
void* threadInsert(void* arg) {
    ThreadData* data = (ThreadData*)arg;

    pthread_mutex_lock(&mutex);
    insert(data->root, data->value);
    pthread_mutex_unlock(&mutex);

    return NULL;
}

// Function for in-order traversal of the BST
void inOrder(Node* root) {
    if (root != NULL) {
        inOrder(root->left);
        printf("%d ", root->data);
        inOrder(root->right);
    }
}

// Function to free the memory of the BST
void freeTree(Node* root) {
    if (root != NULL) {
        freeTree(root->left);
        freeTree(root->right);
        free(root);
    }
}

int main() {
    Node* root = NULL;
    pthread_t threads[10];
    ThreadData threadData[10];

    int values[10] = { 50, 30, 70, 20, 40, 60, 80, 10, 25, 35 };

    // Create threads to insert nodes into the BST
    for (int i = 0; i < 10; i++) {
        threadData[i].root = &root;
        threadData[i].value = values[i];
        pthread_create(&threads[i], NULL, threadInsert, (void*)&threadData[i]);
    }

    // Wait for all threads to finish
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    // Display the BST in-order
    printf("In-order traversal of the BST: ");
    inOrder(root);
    printf("\n");

    // Free the memory allocated for the BST
    freeTree(root);

    // Destroy mutex
    pthread_mutex_destroy(&mutex);

    return 0;
}

#include "../template.hpp"

struct Dinic {

    struct Edge {
        int u, v;
        LL cap, flow;
    };

    vector<Edge> edges;
    vector<vector<int> > adjlist;
    vector<int> d, p;

    Dinic(int N) {
        adjlist.resize(N);
        d.resize(N);
        p.resize(N);
    }

    void AddEdge(int u, int v, LL cap) {
        Edge f = { u, v, cap, 0 }, b = { v, u, 0, 0 };
        adjlist[u].pb((int) edges.size()); edges.pb(f);
        adjlist[v].pb((int) edges.size()); edges.pb(b);
    }

    LL BlockingFlow(int s, int t) {
        queue<int> q; q.push(s);
        fill(ALL(d), -1); d[s] = 0;
        while (!q.empty() && d[t] == -1) {
            int u = q.front(); q.pop();
            for (int i = 0; i < (int) adjlist[u].size(); i++) {
                int id = adjlist[u][i], to = edges[id].v;
                if (d[to] == -1 && edges[id].flow < edges[id].cap) {
                    q.push(to);
                    d[to] = d[u] + 1;
                }
            }
        }
        if (d[t] == -1) return 0;
        fill(ALL(p), 0);
        LL flow = 0;
        while (LL pushed = Push(s, INF, t))
            flow += pushed;
        return flow;
    }

    LL Push(int u, LL flow, int t) {
        if (!flow) return 0;
        if (u == t) return flow;
        for (; p[u] < (int) adjlist[u].size(); ++p[u]) {
            int id = adjlist[u][p[u]], to = edges[id].v;
            if (d[to] != d[u] + 1) continue;
            LL res = edges[id].cap - edges[id].flow,
                pushed = Push(to, min(flow, res), t);
            if (pushed) {
                edges[id].flow += pushed;
                edges[id^1].flow -= pushed;
                return pushed;
            }
        }
        return 0;
    }

    LL Maxflow(int s, int t) {
        for (int i = 0; i < (int) edges.size(); i++)
            edges[i].flow = 0;
        LL totalFlow = 0;
        while (LL flow = BlockingFlow(s, t))
            totalFlow += flow;
        return totalFlow;
    }
};

//Make larger number <http://www.dsalgo.com/2013/02/NextLargerNumber.php.html>
//Programmer : Nitin Harlalka
//Input : An Integer Value
//Output : The next possible larger integer value

#include <iostream>
#include <iterator>
#include <vector>

using namespace std;

int main(){
    int num;
    cin >> num;

//Storing the input number as a array of single digit numbers
    vector <int> num_arr_rev = vector<int>();
    int temp_num = num;
    while(temp_num > 0){
        num_arr_rev.push_back(temp_num % 10);
        temp_num /= 10;
    }

//Since the above vector contains the array of numbers stored in reverse format, reversing it again 
    vector <int> num_arr = vector<int>();
    for (vector<int>::reverse_iterator it = num_arr_rev.rbegin() ; it != num_arr_rev.rend(); ++it)
        num_arr.push_back(*it);

//Traversing the array from right
//Finding the first decreasing sequence
    int larger_num_index = num_arr.size() - 1;
    int smaller_num_index = num_arr.size() - 2;

    for(int i = num_arr.size() - 1; i > 0; i-= 1){
        if(num_arr[i] > num_arr[i - 1]){
            larger_num_index = i - 1;
            smaller_num_index = i;
        }
        else{
            larger_num_index = i;
            smaller_num_index = i - 1;
        }

//Breaking out of the loop when the first decreasing sequence is found
        if(larger_num_index < smaller_num_index)
            break;
    }

//Swapping the larger and smaller numbers
    if(larger_num_index < smaller_num_index){
        int temp = num_arr[smaller_num_index];
        num_arr[smaller_num_index] = num_arr[larger_num_index];
        num_arr[larger_num_index] = temp;
    }

//Converting the array back to a single integer
    int larger_num = 0;
    int num_len = 0;
    while(num_len < num_arr.size()){
            larger_num = larger_num*10 + num_arr[num_len];
            num_len += 1;
    }

    cout << "larger_number = " << larger_num << endl;
    return 0;
}

