#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define BOARD_SIZE 10
#define NUM_MINES 10

char board[BOARD_SIZE][BOARD_SIZE];
int num_mines;

void init_board() {
    int i, j;
    for (i = 0; i < BOARD_SIZE; i++) {
        for (j = 0; j < BOARD_SIZE; j++) {
            board[i][j] = '.';
        }
    }
    srand(time(NULL));
    num_mines = rand() % (BOARD_SIZE * BOARD_SIZE) + 1;
    int count = 0;
    while (count < num_mines) {
        int x, y;
        do {
            x = rand() % BOARD_SIZE;
            y = rand() % BOARD_SIZE;
        } while (board[x][y] == '*');
        board[x][y] = '*';
        count++;
    }
}

void print_board() {
    int i, j;
    for (i = 0; i < BOARD_SIZE; i++) {
        for (j = 0; j < BOARD_SIZE; j++) {
            printf("%c ", board[i][j]);
        }
        printf("\n");
    }
}

int check_win() {
    int i, j;
    for (i = 0; i < BOARD_SIZE; i++) {
        for (j = 0; j < BOARD_SIZE; j++) {
            if (board[i][j]!= '.' && board[i][j]!= '*') {
                return 0;
            }
        }
    }
    return 1;
}

int main() {
    init_board();
    print_board();
    int x, y;
    while (1) {
        printf("Enter your move (x y): ");
        scanf("%d %d", &x, &y);
        if (x < 0 || x >= BOARD_SIZE || y < 0 || y >= BOARD_SIZE) {
            printf("Invalid move\n");
            continue;
        }
        if (board[x][y] == '*') {
            printf("You hit a mine! Game over.\n");
            return 0;
        } else if (board[x][y] == '.') {
            board[x][y] = 'X';
        } else {
            printf("You already revealed this cell.\n");
        }
        if (check_win()) {
            printf("Congratulations! You won!\n");
            return 0;
        }
        print_board();
    }
    return 0;
}

