string reverse(string str) {
    int i, j, len = str.len;
    char temp;

    for (i = 0, j = len - 1; i < len / 2; ++i, --j) {
        temp = str.str[i];
        str.str[i] = str.str[j];
        str.str[j] = temp;
    }

    return str;
}

void print_string(string str) {
    printf("%s\n", str.str);
}

void print_reverse(string str) {
    string reversed = reverse(str);
    print_string(reversed);
}

