//GPT-4o-mini DATASET v1.0 Category: Performance-Critical Component ; Style: asynchronous
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>

#define NUM_THREADS 5
#define WORKLOAD 1000000

typedef struct {
    int thread_id;
    long result;
} thread_data;

void* perform_heavy_computation(void* threadarg) {
    thread_data* my_data = (thread_data*) threadarg;
    int id = my_data->thread_id;
    long sum = 0;

    for(long i = 0; i < WORKLOAD; i++) {
        sum += (i * id) % 100;
    }

    my_data->result = sum;
    printf("Thread %d finished computation.\n", id);
    pthread_exit(NULL);
}

void perform_async_operations() {
    pthread_t threads[NUM_THREADS];
    thread_data thread_data_array[NUM_THREADS];
    int rc;

    // Create threads to perform computations
    for(int i = 0; i < NUM_THREADS; i++) {
        thread_data_array[i].thread_id = i + 1;
        thread_data_array[i].result = 0;

        printf("Creating thread %d\n", i + 1);
        rc = pthread_create(&threads[i], NULL, perform_heavy_computation, (void*)&thread_data_array[i]);

        if (rc) {
            printf("Error: Unable to create thread %d. Return code: %d\n", i + 1, rc);
            exit(-1);
        }
    }

    // Wait for all threads to complete
    for(int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    // Combine results
    long total_sum = 0;
    for(int i = 0; i < NUM_THREADS; i++) {
        total_sum += thread_data_array[i].result;
        printf("Thread %d result: %ld\n", thread_data_array[i].thread_id, thread_data_array[i].result);
    }

    printf("Total sum from all threads: %ld\n", total_sum);
}

int main(int argc, char* argv[]) {
    printf("Starting performance-critical asynchronous computations...\n");

    // Seed the random number generator
    srand(time(NULL));

    perform_async_operations();

    printf("All threads have completed execution.\n");
    return 0;
}

