#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdarg.h>
#include <ctype.h>

// Define the log levels
#define LOG_LEVEL_DEBUG    0
#define LOG_LEVEL_INFO     1
#define LOG_LEVEL_WARNING  2
#define LOG_LEVEL_ERROR    3

// Define the log file name
#define LOG_FILE_NAME    "log.txt"

// Declare the log file pointer
FILE *log_file = NULL;

// Declare the log level
int log_level = LOG_LEVEL_INFO;

// Open the log file
void log_open(const char *file_name, int level)
{
    // Open the log file
    log_file = fopen(file_name, "a");

    // Set the log level
    log_level = level;
}

// Close the log file
void log_close()
{
    // Close the log file
    fclose(log_file);
}

// Log a message
void log_message(int level, const char *format, ...)
{
    // Check the log level
    if (level < log_level)
    {
        // The log level is too low, so don't log the message
        return;
    }

    // Get the current time
    time_t current_time;
    time(&current_time);

    // Convert the time to a string
    char time_string[26];
    ctime_r(&current_time, time_string);

    // Format the log message
    char message[1024];
    va_list args;
    va_start(args, format);
    vsprintf(message, format, args);
    va_end(args);

    // Write the log message to the file
    fprintf(log_file, "%s %s: %s\n", time_string, level == LOG_LEVEL_DEBUG ? "DEBUG" : level == LOG_LEVEL_INFO ? "INFO" : level == LOG_LEVEL_WARNING ? "WARNING" : "ERROR", message);
}

// Log a debug message
void log_debug(const char *format, ...)
{
    // Log the message
    log_message(LOG_LEVEL_DEBUG, format);
}

// Log an info message
void log_info(const char *format, ...)
{
    // Log the message
    log_message(LOG_LEVEL_INFO, format);
}

// Log a warning message
void log_warning(const char *format, ...)
{
    // Log the message
    log_message(LOG_LEVEL_WARNING, format);
}

// Log an error message
void log_error(const char *format, ...)
{
    // Log the message
    log_message(LOG_LEVEL_ERROR, format);
}

// Main function
int main()
{
    // Open the log file
    log_open(LOG_FILE_NAME, LOG_LEVEL_INFO);

    // Log some messages
    log_debug("This is a debug message.");
    log_info("This is an info message.");
    log_warning("This is a warning message.");
    log_error("This is an error message.");

    // Close the log file
    log_close();

    return 0;
}

