// Structure to represent a planet
typedef struct {
  double mass;
  double radius;
  double x_position;
  double y_position;
  double z_position;
  double x_velocity;
  double y_velocity;
  double z_velocity;
} planet_t;

// Function to calculate the gravitational force between two planets
double calculate_gravitational_force(planet_t *p1, planet_t *p2) {
  double distance = sqrt(pow(p2->x_position - p1->x_position, 2) + pow(p2->y_position - p1->y_position, 2) + pow(p2->z_position - p1->z_position, 2));
  double force = GRAVITATIONAL_CONSTANT * p1->mass * p2->mass / pow(distance, 2);
  return force;
}

// Function to calculate the acceleration of a planet due to gravitational force
void calculate_acceleration(planet_t *p, planet_t *p2, double *x_acceleration, double *y_acceleration, double *z_acceleration) {
  double force_x = calculate_gravitational_force(p, p2) * (p2->x_position - p->x_position) / pow(p2->mass, 2);
  double force_y = calculate_gravitational_force(p, p2) * (p2->y_position - p->y_position) / pow(p2->mass, 2);
  double force_z = calculate_gravitational_force(p, p2) * (p2->z_position - p->z_position) / pow(p2->mass, 2);
  *x_acceleration = force_x / p->mass;
  *y_acceleration = force_y / p->mass;
  *z_acceleration = force_z / p->mass;
}

// Function to update the position and velocity of a planet
void update_position_and_velocity(planet_t *p, double x_acceleration, double y_acceleration, double z_acceleration) {
  p->x_position += p->x_velocity * 0.01;
  p->y_position += p->y_velocity * 0.01;
  p->z_position += p->z_velocity * 0.01;
  p->x_velocity += x_acceleration * 0.01;
  p->y_velocity += y_acceleration * 0.01;
  p->z_velocity += z_acceleration * 0.01;
}

int main() {
  // Initialize the planets
  planet_t planets[3];
  planets[0].mass = 100000;
  planets[0].radius = 1000;
  planets[0].x_position = 0;
  planets[0].y_position = 0;
  planets[0].z_position = 0;
  planets[0].x_velocity = 0;
  planets[0].y_velocity = 0;
  planets[0].z_velocity = 0;

  planets[1].mass = 1000;
  planets[1].radius = 100;
  planets[1].x_position = 1000;
  planets[1].y_position = 0;
  planets[1].z_position = 0;
  planets[1].x_velocity = 0;
  planets[1].y_velocity = 0;
  planets[1].z_velocity = 0;

  planets[2].mass = 1000;
  planets[2].radius = 100;
  planets[2].x_position = 0;
  planets[2].y_position = 1000;
  planets[2].z_position = 0;
  planets[2].x_velocity = 0;
  planets[2].y_velocity = 0;
  planets[2].z_velocity = 0;

  // Simulate the motion of the planets
  for (int i = 0; i < 10000; i++) {
    for (int j = 0; j < 3; j++) {
      double x_acceleration, y_acceleration, z_acceleration;
      calculate_acceleration(&planets[j], &planets[0], &x_acceleration, &y_acceleration, &z_acceleration);
      update_position_and_velocity(&planets[j], x_acceleration, y_acceleration, z_acceleration);
    }
  }

  // Print the final positions of the planets
  for (int i = 0; i < 3; i++) {
    printf("Planet %d: x = %f, y = %f, z = %f\n", i, planets[i].x_position, planets[i].y_position, planets[i].z_position);
  }

  return 0;
}

