//MISTRAL-7B DATASET v1.0 Category: Graph representation ; Style: active
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_VERTICES 100
#define INF 99999

typedef struct {
    int adjMat[MAX_VERTICES][MAX_VERTICES];
    int numVertices;
} Graph;

void createGraph(Graph *graph, int numVertices) {
    graph->numVertices = numVertices;
    for (int i = 0; i < numVertices; ++i) {
        for (int j = 0; j < numVertices; ++j) {
            graph->adjMat[i][j] = INF;
        }
    }
}

void addEdge(Graph *graph, int src, int dest, int weight) {
    graph->adjMat[src][dest] = weight;
    graph->adjMat[dest][src] = weight;
}

void printSolution(Graph *graph, int src) {
    int visited[MAX_VERTICES] = {0};
    int parent[MAX_VERTICES] = {-1};
    int dist[MAX_VERTICES] = {INF};

    dist[src] = 0;

    for (int count = 0; count < graph->numVertices; ++count) {
        int minDist = INF;
        int u = -1;

        for (int v = 0; v < graph->numVertices; ++v) {
            if (!visited[v] && dist[v] < minDist) {
                minDist = dist[v];
                u = v;
            }
        }

        visited[u] = 1;

        printf("Vertex %d visited with distance %d\n", u, dist[u]);

        for (int v = 0; v < graph->numVertices; ++v) {
            if (!visited[v] && graph->adjMat[u][v] != INF && dist[u] + graph->adjMat[u][v] < dist[v]) {
                dist[v] = dist[u] + graph->adjMat[u][v];
                parent[v] = u;
            }
        }
    }
}

int main() {
    Graph graph;
    createGraph(&graph, 5);

    addEdge(&graph, 0, 1, 4);
    addEdge(&graph, 0, 2, 3);
    addEdge(&graph, 1, 2, 2);
    addEdge(&graph, 1, 3, 6);
    addEdge(&graph, 2, 4, 1);

    printSolution(&graph, 0);

    return 0;
}

