//LLAMA2-13B DATASET v1.0 Category: Unit converter ; Style: distributed
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <time.h>

#define MAX_CLIENT_CONNECTIONS 5
#define BUFFER_SIZE 1024

struct unit_conversion {
    char *symbol;
    double value;
};

int main(int argc, char *argv[]) {
    int sock_fd, client_sock_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);
    char buffer[BUFFER_SIZE];
    struct unit_conversion conversions[] = {
        {"m", 1},
        {"cm", 10},
        {"mm", 100},
        {"km", 100000},
        {"miles", 1.609344},
    };
    int i;

    // Create the server socket
    sock_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (sock_fd < 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    // Set up the server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(8080);

    // Bind the server socket
    if (bind(sock_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    // Listen for incoming connections
    if (listen(sock_fd, MAX_CLIENT_CONNECTIONS) < 0) {
        perror("listen failed");
        exit(EXIT_FAILURE);
    }

    printf("Server listening on port %d...\n", server_addr.sin_port);

    while (1) {
        // Accept an incoming connection
        client_sock_fd = accept(sock_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_sock_fd < 0) {
            perror("accept failed");
            exit(EXIT_FAILURE);
        }

        // Read the request from the client
        read(client_sock_fd, buffer, BUFFER_SIZE);
        printf("Received request: %s\n", buffer);

        // Parse the request and perform the unit conversion
        for (i = 0; i < sizeof(conversions) / sizeof(conversions[0]); i++) {
            if (strstr(buffer, conversions[i].symbol) != NULL) {
                double value = atof(buffer);
                char converted_value = conversions[i].value * value / 100;
                printf("Converted value: %f %s\n", converted_value, conversions[i].symbol);
                break;
            }
        }

        // Close the client socket
        close(client_sock_fd);
    }

    return 0;
}

