#include <stdio.h>
#include <stdbool.h>
#include <stdlib.h>
#include <time.h>

#define ARRAY_SIZE 100000
#define CHAR_TO_FIND 'x'

// Function to swap two elements in an array
void swap(int* a, int* b) {
    int t = *a;
    *a = *b;
    *b = t;
}

// Function to implement the unique C searching algorithm
int binarySearchWithJumps(int arr[], int low, int high, int x) {
    if (high >= low) {
        // Calculate the middle index
        int mid = low + (high - low) / 2;

        // Check if x is present at mid
        if (arr[mid] == x)
            return mid;

        // If x is smaller, then it can only be present in left subarray
        if (arr[mid] > x) {
            // Instead of recursively calling binarySearch on left subarray, we will jump to the start of left subarray
            high = mid - 1;
            mid = low + (high - low) / 2;
        } else { // Else the element can only be present in right subarray
            low = mid + 1;
            mid = low + (high - low) / 2;
        }
    }

    // Element not present in array
    return -1;
}

int main() {
    // Initialize random seed
    srand(time(NULL));

    // Initialize array with random integers
    int arr[ARRAY_SIZE];
    for (int i = 0; i < ARRAY_SIZE; i++) {
        arr[i] = rand() % 100;
        printf("%d ", arr[i]);
    }
    printf("\n");

    // Implement the unique C searching algorithm
    int result = binarySearchWithJumps(arr, 0, ARRAY_SIZE - 1, CHAR_TO_FIND);

    // Check if character was found
    if (result == -1)
        printf("Character '%c' not present in array.\n", CHAR_TO_FIND);
    else
        printf("Character '%c' found at index %d.\n", CHAR_TO_FIND, result);

    return 0;
}

