bool percolatesUtil(int grid[SIZE][SIZE], int visited[SIZE][SIZE], int row, int col) {
    if (row < 0 || row >= SIZE || col < 0 || col >= SIZE || visited[row][col] || grid[row][col] != FILLED) {
        return false;
    }

    visited[row][col] = true; // Mark the current cell as visited

    // If we reach the bottom row, there's percolation
    if (row == SIZE - 1) {
        return true;
    }

    // Check all four directions (up, down, left, right)
    bool down = percolatesUtil(grid, visited, row + 1, col);
    bool up = percolatesUtil(grid, visited, row - 1, col);
    bool left = percolatesUtil(grid, visited, row, col - 1);
    bool right = percolatesUtil(grid, visited, row, col + 1);

    return down || up || left || right;
}

bool percolates(int grid[SIZE][SIZE]) {
    int visited[SIZE][SIZE] = { {false} }; // Initialize the visited array

    // Check for percolation from every cell in the top row
    for (int col = 0; col < SIZE; col++) {
