#define MAX_EVENT_LEN 1024
#define MAX_LOG_LEVEL 8

typedef enum {
    LOG_LEVEL_EMERG = 0,
    LOG_LEVEL_ALERT,
    LOG_LEVEL_CRIT,
    LOG_LEVEL_ERR,
    LOG_LEVEL_WARNING,
    LOG_LEVEL_NOTICE,
    LOG_LEVEL_INFO,
    LOG_LEVEL_DEBUG
} log_level_t;

typedef struct {
    log_level_t level;
    char timestamp[20];
    char message[MAX_EVENT_LEN];
} event_t;

static void log_event(log_level_t level, const char* message) {
    event_t event;
    time_t now;
    struct tm* time_info;

    // Get the current time
    now = time(NULL);
    time_info = localtime(&now);

    // Create the event struct with the current time and message
    strftime(event.timestamp, sizeof(event.timestamp), "%Y-%m-%d %H:%M:%S", time_info);
    strncpy(event.message, message, MAX_EVENT_LEN);

    // Log the event based on the level
    switch (level) {
        case LOG_LEVEL_EMERG:
            syslog(LOG_EMERG, "%s", event.message);
            break;
        case LOG_LEVEL_ALERT:
            syslog(LOG_ALERT, "%s", event.message);
            break;
        case LOG_LEVEL_CRIT:
            syslog(LOG_CRIT, "%s", event.message);
            break;
        case LOG_LEVEL_ERR:
            syslog(LOG_ERR, "%s", event.message);
            break;
        case LOG_LEVEL_WARNING:
            syslog(LOG_WARNING, "%s", event.message);
            break;
        case LOG_LEVEL_NOTICE:
