void process_filter(Filter *filter) {
    float sum = 0.0;
    int i;

    CircularBuffer *filter_input = &filter->filter_input;
    CircularBuffer *filter_output = &filter->filter_output;

    filter_output->head = filter_input->head;
    filter_output->tail = filter_output->tail;

    for (i = filter_output->head; i != filter_input->head; i = (i + 1) % FILTER_LENGTH) {
        sum += filter_input->input[i] * (0.5 - sin(2 * PI * i / FILTER_LENGTH));
    }

    filter_output->output = sum;
}

int main() {
    Filter filter;
    Filter *filter_ptr = &filter;
    filter_init(filter_ptr);

    int i;
    for (i = 0; i < 100; i++) {
        filter_input(filter_ptr, (float) i / 10.0);
    }

    printf("Filter output: %f\n", filter_ptr->filter_output.output);

    return 0;
}

