#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>

#define KEY_SIZE 16
#define MESSAGE_SIZE 256

// Function to generate a random key
void generate_key(unsigned char *key) {
    int i;
    for (i = 0; i < KEY_SIZE; i++) {
        key[i] = (unsigned char)rand() % 256;
    }
}

// Function to encrypt a message
void encrypt(unsigned char *message, unsigned char *key) {
    int i, j;
    for (i = 0; i < MESSAGE_SIZE; i++) {
        unsigned char temp = message[i];
        for (j = 0; j < KEY_SIZE; j++) {
            temp = (temp + key[j]) % 256;
        }
        message[i] = temp;
    }
}

// Function to decrypt an encrypted message
void decrypt(unsigned char *message, unsigned char *key) {
    int i, j;
    for (i = 0; i < MESSAGE_SIZE; i++) {
        unsigned char temp = message[i];
        for (j = 0; j < KEY_SIZE; j++) {
            temp = (temp - key[j]) % 256;
        }
        message[i] = temp;
    }
}

int main() {
    unsigned char message[MESSAGE_SIZE] = "Hello, World!";
    unsigned char key[KEY_SIZE] = {0x54, 0x75, 0x68, 0x65, 0x20, 0x69, 0x6d, 0x61, 0x67, 0x65, 0x20, 0x73, 0x69, 0x74, 0x65};
    generate_key(key);
    encrypt(message, key);
    printf("Encrypted message: %s\n", message);
    decrypt(message, key);
    printf("Decrypted message: %s\n", message);
    return 0;
}

