#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAP_WIDTH 20
#define MAP_HEIGHT 20

#define PAC_MAN_SIZE 5
#define PAC_MAN_SPEED 3

#define FOOD_SIZE 4
#define FOOD_AMOUNT 20

typedef struct Pacman {
  int x, y;
  int dx, dy;
  int score;
} Pacman;

typedef struct Food {
  int x, y;
} Food;

Pacman pacman;
Food food[FOOD_AMOUNT];

void drawMap() {
  for (int y = 0; y < MAP_HEIGHT; y++) {
    for (int x = 0; x < MAP_WIDTH; x++) {
      if (x == pacman.x && y == pacman.y) {
        printf("O");
      } else if (food[0].x == x && food[0].y == y) {
        printf("F");
      } else {
        printf(".");
      }
    }
    printf("\n");
  }
}

void movePacman() {
  pacman.x += pacman.dx * PAC_MAN_SPEED;
  pacman.y += pacman.dy * PAC_MAN_SPEED;

  if (pacman.x >= MAP_WIDTH - PAC_MAN_SIZE || pacman.x < 0) {
    pacman.dx *= -1;
  }

  if (pacman.y >= MAP_HEIGHT - PAC_MAN_SIZE || pacman.y < 0) {
    pacman.dy *= -1;
  }
}

void placeFood() {
  food[0].x = rand() % MAP_WIDTH;
  food[0].y = rand() % MAP_HEIGHT;

  while (food[0].x == pacman.x || food[0].y == pacman.y) {
    food[0].x = rand() % MAP_WIDTH;
    food[0].y = rand() % MAP_HEIGHT;
  }
}

int main() {
  pacman.x = 5;
  pacman.y = 5;
  pacman.dx = 1;
  pacman.dy = 0;
  pacman.score = 0;

  placeFood();

  for (int i = 0; i < FOOD_AMOUNT; i++) {
    drawMap();
    movePacman();
    placeFood();
  }

  printf("Your score: %d", pacman.score);

  return 0;
}

