    // Simulate remote control vehicle movement
    moveVehicle(0, 5);
    moveVehicle(1, 3);
    turnVehicle(45);
    moveVehicle(2, 2);
    moveVehicle(3, 4);

    // Print vehicle position and direction
    printf("X: %d, Y: %d, Direction: %d\n", vehicle.x, vehicle.y, vehicle.direction);

    return 0;
}

