void process(double rest, double lemi, double& netc, double& taxc, double& totalc)
{
	double rate=0.0;

	/*calculate tax rate (%)*/
	if (rest>=1 && rest<=5)
		rate=1;
	else if (rest>=6 && rest<=11)
		rate=3;
	else if (rest>=12 && rest<=20)
		rate=5;
	else if (rest>=21 && rest<=50)
		rate=8;
	else if (rest>50)
		rate=12;

	/*calculate net cost*/
	netc=((rest/50)*(0.40)*(lemi));

	/*calculate tax on call*/
	taxc=(netc*(rate/100));

	/*calculate total*/
	totalc=netc+taxc;
}

