#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define PORT 8080
#define BACKLOG 5

void error_handling(const char* message);

int main(int argc, char *argv[])
{
    int listen_fd, client_fd;
    struct sockaddr_in serv_addr, cli_addr;
    socklen_t clilen;
    char buffer[1025];

    listen_fd = socket(AF_INET, SOCK_STREAM, 0);

    if(listen_fd == -1)
    {
        error_handling("socket failed");
        exit(EXIT_FAILURE);
    }

    bzero((char*)&serv_addr, sizeof(serv_addr));

    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = htons(PORT);

    if(bind(listen_fd, (struct sockaddr*)&serv_addr, sizeof(serv_addr))<0)
    {
        error_handling("bind failed");
        exit(EXIT_FAILURE);
    }

    if(listen(listen_fd, BACKLOG)<0)
    {
        error_handling("listen");
        exit(EXIT_FAILURE);
    }

    printf("\nServer is listening on port %d\n", PORT);

    while(1)
    {
        clilen = sizeof(cli_addr);
        client_fd = accept(listen_fd, (struct sockaddr*)&cli_addr, &clilen);

        if(client_fd<0)
        {
            error_handling("accept");
        }
        else
        {
            printf("\nConnection with client %s established\n", inet_ntoa(cli_addr.sin_addr));
            send(client_fd, "Romeo and Juliet Client Server Application", strlen("Romeo and Juliet Client Server Application"), 0);
        }
    }
}

void error_handling(const char* message)
{
    perror(message);
    exit(EXIT_FAILURE);
}

