#include <string.h>

// Definition of mathematical functions
double sin(double x);
double cos(double x);
double tan(double x);

// Definition of error functions
double error(double x, double y);
double absolute_error(double x, double y);
double relative_error(double x, double y);

int main() {
  // Declaration of variables
  double x, y, z;
  int num_errors = 0;

  // Mathematical operations
  x = 3.0;
  y = 4.0;
  z = sin(x) + cos(y);

  // Error handling
  if (z > 10.0) {
    num_errors++;
    printf("Error: z = %f exceeds the maximum value of 10.0\n", z);
  }

  if (error(x, y) > 0.1) {
    num_errors++;
    printf("Error: |x - y| = %f is greater than 0.1\n", error(x, y));
  }

  if (absolute_error(x, y) > 0.05) {
    num_errors++;
    printf("Error: |x - y| = %f is greater than 0.05\n", absolute_error(x, y));
  }

  if (relative_error(x, y) > 0.01) {
    num_errors++;
    printf("Error: |x - y| / (x + y) = %f is greater than 0.01\n", relative_error(x, y));
  }

  // Print results
  printf("Number of errors: %d\n", num_errors);

  return 0;
}

// Definition of mathematical functions
double sin(double x) {
  return x * cos(x);
}

double cos(double x) {
  return x * sin(x);
}

double tan(double x) {
  return sin(x) / cos(x);
}

// Definition of error functions
double error(double x, double y) {
  return fabs(x - y);
}

double absolute_error(double x, double y) {
  return fabs(x - y);
}

double relative_error(double x, double y) {
  return (x - y) / (x + y);
}

