float deQuy(int n)
{
	if(n == 1)
		return sqrt(2.0);
	return sqrt(2 + deQuy(n - 1));
}

float deQuyDuoi(int n, float x = sqrt(2.0))
{
	if(n == 1)
		return x;
	return deQuyDuoi(n - 1, sqrt(2.0 + x));
}

float khuDeQuy(int n)
{
	float S;
	S = sqrt((float)2);
	for(int i = 2; i <= n; i++)
	{
		S = sqrt(2 + S);
	}
	return S;
}
int main()
{
