vector&lt;int&gt; Solution::primesum(int n) {
  int prime[n+1];
  for(int i=0;i&lt;n+1;i++){
    prime[i]=1;
  }
   prime[0]=0;
   prime[1]=0;
   for(int i=2;i&lt;=sqrt(n);i++){

        if(prime[i]==1){
            for(int j=2;i*j&lt;=n;j++)
               prime[i*j]=0;
        }

  }
  vector &lt;int&gt; sum;
  for(int i=2;i&lt;=(n)/2;i++){
      if(prime[i]==1&amp;&amp;prime[n-i]==1){
       sum.push_back(i);
       sum.push_back(n-i);
       return sum;
      }
      }
    return sum;
     }

