typedef node * tree;
tree maknod(long int d)
{
    tree t;
    t=(tree)malloc(sizeof(tree));
    t-&gt;n=d;
    t-&gt;l=t-&gt;r=NULL;
    return t;
}

tree ins(tree t,long int d)
{
    if(t==NULL)
    return maknod(d);
    else if(t-&gt;n &gt; d)
    t-&gt;l=ins(t-&gt;l,d);
    else 
    t-&gt;r=ins(t-&gt;r,d);
    return t;
}
long int findmax(tree t)
{
    if(t-&gt;r==NULL)
    return (t-&gt;n);
    findmax(t-&gt;r);
}
tree del(tree t,long int d)
{
    if(t!=NULL)
    {
    if(t-&gt;n==d)
    {
        if(t-&gt;l==NULL &amp;&amp; t-&gt;r==NULL)
        return NULL;
        if(t-&gt;l==NULL)
        return t-&gt;r;
        if(t-&gt;r==NULL)
        return t-&gt;l;
        t-&gt;n=findmax(t-&gt;l);
        t-&gt;l=del(t-&gt;l,t-&gt;n);
    }
    if(t-&gt;n&gt;d)
    t-&gt;l=del(t-&gt;l,d);
    if(t-&gt;n&lt;d)
    t-&gt;r=del(t-&gt;r,d);
}
return t;
}
