NODE insert_front(NODE &head,char x)
{
    NODE temp=get_node();
    temp->data=x;
    temp->next=NULL;
    temp->prev=NULL;
    if(head==NULL)
    {
        head=temp;
        return head;
    }
    temp->next=head;
    head=temp;
    return head;
}
void display(NODE head)
{
