    while(temp!=NULL)
    {
        cout<<temp->data<<"->";
        temp=temp->next;
    }
    cout<<endl;

}
NODE make_string_list(NODE &head,char a[])
{
    for(int i=0;a[i]!='\0';i++)
        head=insert_front(head,a[i]);
    return head;
}
int palin(NODE &head)
{
    NODE temp1=head,temp2=head;
    while(temp2->next!=NULL)
        temp2=temp2->next;
    while(temp1!=NULL&&temp2!=NULL)
    {
        if(temp1->data!=temp2->data)
            return false;
        temp1=temp1->next;
        temp2=temp2->prev;
    }
    return true;
}
