/*
 * socket_program.c
 *
 * Simple Socket Programming Example
 *
 * This program creates a socket and binds it to a port.
 * It then listens for incoming connections and accepts them.
 * Once a connection is established, it sends a message to the client and receives a response.
 *
 * Compile with:
 * gcc -o socket_program socket_program.c -lsocket -lnsl
 *
 * Run with:
 * ./socket_program
 *
 */

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

int main() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    struct sockaddr_in client_address;
    int opt = 1;
    int addrlen = sizeof(address);
    char buffer[1024] = {0};

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    // Forcefully attaching socket to the port 8080
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        exit(EXIT_FAILURE);
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(8080);

    // Forcefully attaching socket to the port 8080
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address))<0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }
    printf("Waiting for incoming connections...\n");

    // Accept incoming connection
    if ((new_socket = accept(server_fd, (struct sockaddr *)&client_address, (socklen_t*)&addrlen))<0) {
        perror("accept");
        exit(EXIT_FAILURE);
    }

    // Send message to client
    char message[] = "Hello, client!";
    if (send(new_socket, message, strlen(message), 0)<0) {
        perror("send");
        exit(EXIT_FAILURE);
    }

    // Receive response from client
    if (recv(new_socket, buffer, 1024, 0)<0) {
        perror("recv");
        exit(EXIT_FAILURE);
    }

    printf("Received response from client: %s\n", buffer);

    // Close connection and socket
    close(new_socket);
    close(server_fd);

    return 0;
}

