#include <queue>
#include <algorithm>



/**
 * Compute the factorial of a given number.
 *
 * Recursive algorithm.
 *
 * @param[in] number
 *     The given number to compute its factorial.
 *
 * @return
 *     The factorial.
 */
int factorialRecursive(int number)
{
    if (number > 1) {
        // Recursive case.
        return number * factorialRecursive(number - 1);
    }
    else {
        // Base case.
        return 1;
    }
}


