{
    int temp = a;
    a = b;
    b = temp;
}

void HoanVi2Cot(int a[][MAX], int dong, int cot, int cot1, int cot2)
{
    if((cot1 >= 0 && cot1 < cot) && (cot2 >= 0 && cot2 < cot))
    {
        for(int i = 0; i < dong; i++)
        {
            HoanVi(a[i][cot1], a[i][cot2]);
        }
    }
}
