//GPT-4o-mini DATASET v1.0 Category: Image to ASCII art converter ; Style: excited
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define MAX_WIDTH 100
#define MAX_HEIGHT 100
#define ASCII_CHARS " .:-=+*%@#"

void adjust_image_size(uint8_t input[], uint8_t output[], int input_width, int input_height, int *output_width, int *output_height) {
    *output_width = MAX_WIDTH;
    *output_height = (input_height * MAX_WIDTH) / input_width; 
    if (*output_height > MAX_HEIGHT) {
        *output_height = MAX_HEIGHT;
    }

    double x_ratio = (double)input_width / MAX_WIDTH;
    double y_ratio = (double)input_height / *output_height;

    for (int y = 0; y < *output_height; y++) {
        for (int x = 0; x < *output_width; x++) {
            int pixel = (int)(y * y_ratio) * input_width + (int)(x * x_ratio);
            output[y * (*output_width) + x] = input[pixel];
        }
    }
}

char pixel_to_ascii(uint8_t pixel_value) {
    return ASCII_CHARS[pixel_value / (256 / strlen(ASCII_CHARS))];
}

void convert_to_ascii_art(uint8_t image[], int width, int height) {
    printf("\nYour awesome ASCII Art:\n");
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            char ascii_char = pixel_to_ascii(image[y * width + x]);
            printf("%c", ascii_char);
        }
        printf("\n");
    }
}

uint8_t* load_image(const char* filename, int* width, int* height) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Error opening the file");
        return NULL;
    }

    unsigned char header[54];
    fread(header, sizeof(unsigned char), 54, file);
    *width = *(int*)&header[18];
    *height = *(int*)&header[22];

    int size = 3 * (*width) * (*height);
    uint8_t *data = malloc(size);
    fread(data, sizeof(uint8_t), size, file);
    fclose(file);

    // Create grayscale version
    uint8_t *gray_image = malloc((*width) * (*height));
    for (int i = 0; i < (*width) * (*height); i++) {
        gray_image[i] = (data[3 * i] + data[3 * i + 1] + data[3 * i + 2]) / 3;
    }

    free(data);
    return gray_image;
}

void free_image(uint8_t *image) {
    free(image);
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <image_file.bmp>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int width, height;
    uint8_t *image = load_image(argv[1], &width, &height);
    if (!image) {
        return EXIT_FAILURE;
    }

    uint8_t reduced_image[MAX_WIDTH * MAX_HEIGHT];
    int new_width, new_height;

    adjust_image_size(image, reduced_image, width, height, &new_width, &new_height);

    convert_to_ascii_art(reduced_image, new_width, new_height);

    free_image(image);
    return EXIT_SUCCESS;
}

