#define WIND_THRESHOLD 10

typedef struct {
    float temperature;
    float rainfall;
    float wind_speed;
} Weather;

void initialize_weather(Weather* weather) {
    weather->temperature = (rand() % (MAX_TEMP - MIN_TEMP + 1)) + MIN_TEMP;
    weather->rainfall = 0.0;
    weather->wind_speed = 0.0;
}

void update_weather(Weather* weather, int x, int y) {
    float random_number = (float) rand() / RAND_MAX;

    // Simulate temperature change based on location
    if (x < SIZE / 2 && y < SIZE / 2) {
        weather->temperature += random_number * 0.5;
    } else if (x > SIZE / 2 && y < SIZE / 2) {
        weather->temperature -= random_number * 0.5;
    } else if (x < SIZE / 2 && y > SIZE / 2) {
        weather->temperature -= random_number * 0.3;
    } else {
        weather->temperature += random_number * 0.3;
    }

    // Simulate rainfall
    if (random_number < 0.1) {
        weather->rainfall += RAIN_THRESHOLD;
    }

