//GPT-4o-mini DATASET v1.0 Category: Scientific Calculator Implementation ; Style: Donald Knuth
#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <string.h>

#define MAX_INPUT 100
#define MAX_EXPRESSION 100

/* Function prototypes */
double evaluate_expression(const char *expression);
double perform_operation(double a, double b, char operator);
int precedence(char operator);
double apply_trigonometric_function(double angle, const char *func);
void print_usage(void);

/* Main Function */
int main() {
    char input[MAX_INPUT];
    printf("Welcome to the Knuth Scientific Calculator!\n");
    print_usage();
    while (1) {
        printf("Enter an expression (type 'exit' to quit): ");
        fgets(input, MAX_INPUT, stdin);
        if (strncmp(input, "exit", 4) == 0) break;
        double result = evaluate_expression(input);
        printf("Result: %.5f\n", result);
    }
    return 0;
}

/* Evaluate the expression considering operator precedence */
double evaluate_expression(const char *expression) {
    char postfix[MAX_EXPRESSION] = "";
    char operators[MAX_EXPRESSION];
    int op_index = 0;
    double stack[MAX_EXPRESSION];
    int stack_index = 0;

    // Convert infix expression to postfix using Shunting Yard Algorithm
    for (int i = 0; i < strlen(expression); i++) {
        char current = expression[i];
        if (isspace(current)) continue;

        if (isdigit(current) || current == '.') {
            while (isdigit(current) || current == '.') {
                strncat(postfix, &current, 1);
                i++;
                current = expression[i];
            }
            strcat(postfix, " ");
            i--; // Decrement i to prevent skipping the next character
        } else if (current == '(') {
            operators[op_index++] = current;
        } else if (current == ')') {
            while (op_index > 0 && operators[op_index - 1] != '(') {
                strncat(postfix, &operators[--op_index], 1);
                strcat(postfix, " ");
            }
            op_index--; // Pop the '(' from the stack
        } else if (strchr("+-*/^sincos", current)) {
            while (op_index > 0 && precedence(operators[op_index - 1]) >= precedence(current)) {
                strncat(postfix, &operators[--op_index], 1);
                strcat(postfix, " ");
            }
            operators[op_index++] = current;
        }
    }

    while (op_index > 0) {
        strncat(postfix, &operators[--op_index], 1);
        strcat(postfix, " ");
    }

    // Evaluate the postfix expression
    char *token = strtok(postfix, " ");
    while (token != NULL) {
        if (isdigit(*token) || (*token == '-' && isdigit(*(token + 1)))) {
            stack[stack_index++] = atof(token);
        } else {
            double b = stack[--stack_index];
            double a = (stack_index > 0) ? stack[--stack_index] : 0.0;
            double result = perform_operation(a, b, *token);
            stack[stack_index++] = result;
        }
        token = strtok(NULL, " ");
    }

    return stack[0];
}

/* Function: Perform mathematical operations */
double perform_operation(double a, double b, char operator) {
    switch (operator) {
        case '+': return a + b;
        case '-': return a - b;
        case '*': return a * b;
        case '/': return (b != 0) ? a / b : NAN; // Handle division by zero
        case '^': return pow(a, b);
    }
    return NAN; // Return Not-a-Number for invalid operation
}

/* Function: Define operator precedence */
