    memcpy(&serveraddr.sin_addr, he->h_addr_list[0], he->h_length);

    // connect to server
    if (connect(sockfd, (struct sockaddr *) &serveraddr, sizeof(serveraddr)) < 0) {
        perror("Error in connecting to server");
