#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <math.h>

#define MAX_LENGTH 1024
#define MAX_WORD_LENGTH 20

// Function to count the number of words in a given string
int count_words(char *str) {
    int word_count = 0;
    char *token = strtok(str, " ");

    while (token != NULL) {
        word_count++;
        token = strtok(NULL, " ");
    }

    return word_count;
}

// Function to print the first word of a given string in uppercase
void print_first_word(char *str) {
    char *token = strtok(str, " ");
    if (token != NULL) {
        printf("%s\n", token);
    }
}

// Function to reverse a given string
char *reverse_string(char *str) {
    char *result = NULL;
    char *token = strtok(str, " ");

    while (token != NULL) {
        result = strcat(result, token);
        result = strcat(result, " ");
        token = strtok(NULL, " ");
    }

    return result;
}

int main() {
    char str[] = "Hello, how are you? This is a sample string with multiple words.";
    int word_count = count_words(str);
    print_first_word(str);
    char *reversed_str = reverse_string(str);
    printf("%s\n", reversed_str);

    return 0;
}

