//Falcon-180B DATASET v1.0 Category: Data mining ; Style: post-apocalyptic
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define NUM_ROWS 10
#define NUM_COLS 10
#define NUM_MINES 10

// Function prototypes
void generate_maze(char maze[NUM_ROWS][NUM_COLS]);
void print_maze(const char maze[NUM_ROWS][NUM_COLS]);
int count_adjacent_mines(const char maze[NUM_ROWS][NUM_COLS], int row, int col);

int main() {
    srand(time(NULL));
    char maze[NUM_ROWS][NUM_COLS];
    generate_maze(maze);
    print_maze(maze);
    return 0;
}

void generate_maze(char maze[NUM_ROWS][NUM_COLS]) {
    for (int i = 0; i < NUM_ROWS; ++i) {
        for (int j = 0; j < NUM_COLS; ++j) {
            maze[i][j] = rand() % 2 == 0? '.' : '*';
        }
    }

    // Place mines randomly
    for (int i = 0; i < NUM_MINES; ++i) {
        int row, col;
        do {
            row = rand() % NUM_ROWS;
            col = rand() % NUM_COLS;
        } while (maze[row][col]!= '*');
        maze[row][col] = '*';
    }
}

void print_maze(const char maze[NUM_ROWS][NUM_COLS]) {
    for (int i = 0; i < NUM_ROWS; ++i) {
        for (int j = 0; j < NUM_COLS; ++j) {
            printf("%c ", maze[i][j]);
        }
        printf("\n");
    }
}

int count_adjacent_mines(const char maze[NUM_ROWS][NUM_COLS], int row, int col) {
    int count = 0;
    if (row > 0 && maze[row - 1][col] == '*') {
        ++count;
    }
    if (col > 0 && maze[row][col - 1] == '*') {
        ++count;
    }
    if (row < NUM_ROWS - 1 && maze[row + 1][col] == '*') {
        ++count;
    }
    if (col < NUM_COLS - 1 && maze[row][col + 1] == '*') {
        ++count;
    }
    return count;
}

