int osc_match_single_char(const char *pattern, const char *address){
	switch(*pattern){
        case '[':
            return osc_match_bracket(pattern, address);
        case ']':
            while(*pattern != '['){
                pattern--;
            }
            return osc_match_bracket(pattern, address);
        case '{':
            return osc_match_curly_brace(pattern, address);
        case '}':
            while(*pattern != '{'){
                pattern--;
            }
            return osc_match_curly_brace(pattern, address);
        case '?':
            return 1;
        default:
            if(*pattern == *address){
                return 1;
            }else{
                return 0;
            }
	}
	return 0;
}

int osc_match_bracket(const char *pattern, const char *address){
	int matched = 0;
	pattern++;
	while(*pattern != ']' && *pattern != '\0'){
		// the character we're on now is the beginning of a range
		if(*(pattern + 1) == '-'){
			if(*address >= *pattern && *address <= *(pattern + 2)){
				matched = 1;
				break;
			}else{
				pattern += 3;
			}
		}else{
			// just test the character
			if(*pattern == *address){
				matched = 1;
				break;
			}
			pattern++;
		}
	}
	return matched;
	/*
     if(matched){
     while(*pattern != ']' && *pattern != '\0'){
     pattern++;
     }
     pattern++;
     address++;
     }else{
     return 0;
     }
     return 1;
     */
}

int osc_match_curly_brace(const char *pattern, const char *address){
	int matched = OSC_MATCH_NONE;
	pattern++;
	while(*pattern != '}' && *pattern != '\0' && *pattern != '/'){
		if(*pattern == *address){
			matched = 1;
			break;
		}else{
			pattern++;
			if(*pattern == ','){
				pattern++;
			}
		}
	}

	if(matched){
		while(*pattern != '}' && *pattern != '\0' && *pattern != '/'){
			pattern++;
		}
		pattern++;
		address++;
	}else{
		return OSC_MATCH_NONE;
	}

	return 1;
}



