#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_PROCESSES 5
#define MAX_QUEUE_SIZE 10

typedef struct Process {
    int process_id;
    int arrival_time;
    int burst_time;
    int waiting_time;
    int turnaround_time;
} Process;

Process processes[MAX_PROCESSES];

void roundrobin_scheduling(int quantum) {
    int i = 0;
    int current_time = 0;
    int completed = 0;

    while (!completed) {
        for (i = 0; i < MAX_PROCESSES; i++) {
            if (processes[i].arrival_time <= current_time && processes[i].burst_time > 0) {
                processes[i].waiting_time++;
                processes[i].burst_time--;
                current_time++;

                if (processes[i].burst_time == 0) {
                    completed++;
                    processes[i].turnaround_time = current_time - processes[i].arrival_time;
                }
            }
        }

        if (current_time % quantum == 0) {
            current_time++;
        }
    }
}

int main() {
    int i = 0;
    int quantum = 2;

    // Create processes
    for (i = 0; i < MAX_PROCESSES; i++) {
        processes[i].process_id = i;
        processes[i].arrival_time = rand() % MAX_QUEUE_SIZE;
        processes[i].burst_time = rand() % MAX_QUEUE_SIZE;
    }

    // Round Robin scheduling
    roundrobin_scheduling(quantum);

    // Print results
    for (i = 0; i < MAX_PROCESSES; i++) {
        printf("Process ID: %d, Waiting Time: %d, Turnaround Time: %d\n", processes[i].process_id, processes[i].waiting_time, processes[i].turnaround_time);
    }

    return 0;
}

