// Define a function to calculate the area of a triangle given its base and height.
double triangle_area(double base, double height) {
    return 0.5 * base * height;
}

// Define a function to calculate the volume of a sphere given its radius.
double sphere_volume(double radius) {
    return (4.0 / 3.0) * M_PI * pow(radius, 3);
}

// Define a function to calculate the surface area of a sphere given its radius.
double sphere_surface_area(double radius) {
    return 4.0 * M_PI * pow(radius, 2);
}

// Define a function to calculate the distance between two points in 3D space.
double distance_3d(double x1, double y1, double z1, double x2, double y2, double z2) {
    return sqrt(pow(x2 - x1, 2) + pow(y2 - y1, 2) + pow(z2 - z1, 2));
}

// Define a function to calculate the dot product of two vectors.
double dot_product(double *v1, double *v2, int n) {
    double result = 0.0;
    for (int i = 0; i < n; i++) {
        result += v1[i] * v2[i];
    }
    return result;
}

// Define a function to calculate the cross product of two vectors.
void cross_product(double *v1, double *v2, double *result) {
    result[0] = v1[1] * v2[2] - v1[2] * v2[1];
    result[1] = v1[2] * v2[0] - v1[0] * v2[2];
    result[2] = v1[0] * v2[1] - v1[1] * v2[0];
}

// Define a function to calculate the norm of a vector.
double norm(double *v, int n) {
    double result = 0.0;
    for (int i = 0; i < n; i++) {
        result += pow(v[i], 2);
    }
    return sqrt(result);
}

