    double v2[] = {4.0, 5.0, 6.0};
    double result[3];

    // Calculate the area of the triangle.
    double triangle_area_result = triangle_area(base, height);

    // Calculate the volume of the sphere.
    double sphere_volume_result = sphere_volume(radius);

    // Calculate the surface area of the sphere.
    double sphere_surface_area_result = sphere_surface_area(radius);

    // Calculate the distance between the two points.
    double distance_3d_result = distance_3d(x1, y1, z1, x2, y2, z2);

    // Calculate the dot product of the two vectors.
