        }
    }
    for (int y = 0; y < height - border; y++) {
        for (int x = width - border; x < width; x++) {
            image[y * width + x] = color_scale - 1;
        }
    }
    for (int y = 0; y < height - border; y++) {
        for (int x = 0; x < width - border; x++) {
            image[y * width + x] = color_scale - 1;
        }
    }
    for (int y = 0; y < height - border; y++) {
        for (int x = width - border; x < width; x++) {
            image[y * width + x] = color_scale - 1;
        }
    }
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            printf("%d ", image[y * width + x]);
        }
        printf("\n");
    }
    free(image);
    return 0;
}

