void FilterSummer(Bitmap &bmp, float percent)
{
	Color color;
	percent = 1.0 - percent;

	for (int row = 0; row < bmp.height; row++)
		for (int col = 0; col < bmp.width; col++)
		{
			GetPixel(bmp, row, col, color);

			color.B = color.B*(percent);
			if (color.B > 255)
				color.B = 255;
			SetPixel(bmp, row, col, color);
		}
}

void FilterWinter(Bitmap &bmp, float pt1, float pt2)
{
	Color color;
	pt1 = (100 - pt1) / 100;

	for (int row = 0; row < bmp.height; row++)
		for (int col = 0; col < bmp.width; col++)
		{
			GetPixel(bmp, row, col, color);
			color.R = (color.R * (pt1));

			color.G = (color.G * (pt2));

			SetPixel(bmp, row, col, color);
		}
}

void SnowEffect(Bitmap &bmp)
{
	Color color;
	int row, col, h, w, x, y; h = 0;
	while (h < bmp.height*bmp.width / 7)
	{
		x = rand() % bmp.height + 1;
		y = rand() % bmp.width + 1;
		color.B = 255; color.R = 255; color.G = 255;
		SetPixel(bmp, x, y, color);
		h++;
	}
}

void SaltPepperNoise(Bitmap &bmp)
{
	Color color;
	int rand1, rand2, row, col;
	for (row = 0; row < bmp.height; row++)
		for (col = 0; col < bmp.width; col++)
		{
			rand1 = rand() % 100;
			if (rand1 < 5)
			{
				rand2 = rand() % 2;
				if (rand2 == 0)
				{
					color.B = 0; color.G = 0; color.R = 0;
					SetPixel(bmp, row, col, color);
				}
				else
				{
					color.B = 255; color.R = 255; color.G = 255;
					SetPixel(bmp, row, col, color);
				}
			}
		}
}

void Pastel(Bitmap &bmp)
{
	Color color;
	int row, col;
	for (row = 0; row < bmp.height; row++)
		for (col = 0; col < bmp.width; col++)
		{
			GetPixel(bmp, row, col, color);

			color.R = color.R / 2 + 127;
			if (color.R > 255) color.R = 255;

			color.B = color.B / 2 + 127;
			if (color.B > 255) color.B = 255;

			color.G = color.G / 2 + 127;
			if (color.G > 255) color.G = 255;

			SetPixel(bmp, row, col, color);
		}
}

void PictureFrames(Bitmap &bmp, int thickness, unsigned char COLOR)
{
	Bitmap outbmp;
	outbmp.width = bmp.width + thickness * 2;
	outbmp.height = bmp.height + thickness * 2;
	outbmp.rowSize = ((3 * outbmp.width + 3) / 4) * 4;
	outbmp.pixels = new unsigned char[outbmp.rowSize * outbmp.height];

	for (int row = 0; row < outbmp.height; row++)
		for (int col = 0; col < outbmp.width; col++)
			SetPixel(outbmp, row, col, { COLOR,COLOR,COLOR });
	for (int row = 0; row < bmp.height; row++)
		for (int col = 0; col < bmp.width; col++)
		{
			Color color1;
			GetPixel(bmp, row, col, color1);
			SetPixel(outbmp, row + thickness, col + thickness, color1);
		}
	bmp.width = outbmp.width;
	bmp.height = outbmp.height;
	bmp.pixels = outbmp.pixels;
	bmp.rowSize = outbmp.rowSize;
	if (thickness == 15)
		return;
	PictureFrames(bmp, 15, 0);
}

void BlurImage(const Bitmap &inbmp, Toado TamElip, float ngang, float doc, double sigma)
{
	int i, j, h, w, gx = 10, gy = 10, x;

	Color color1, color2;
	const int k = sigma / 2.5;
	float d = 5, doc1, ngang1;
	double gauss[10][10][10], pi = 3.14159, sum[20];

	for (x = 0; x < 20; x++) sum[x] = 0;

	if (ngang < 0)
	{
		//Gaussian
		for (i = 0; i < gx; i++)
			for (j = 0; j < gy; j++)
			{
				gauss[0][i][j] = exp(-(i*i + j * j)*1.0 / (2 * sigma)) / (2 * pi*sigma*sigma);
				sum[0] += gauss[0][i][j];
			}
		for (i = 0; i < gx; i++) {
			for (j = 0; j < gy; j++) {
				gauss[0][i][j] /= sum[0];
			}
		}

		//Blur All Image
		for (i = 0; i < inbmp.height; i++)
			for (j = 0; j < inbmp.width; j++)
			{
				color2.B = 0;
				color2.G = 0;
				color2.R = 0;
				for (h = i; h < i + gx; h++)
					for (w = j; w < j + gy; w++)
					{

						GetPixel(inbmp, h, w, color1);

						color2.B += gauss[0][h - i][w - j] * color1.B;
						color2.R += gauss[0][h - i][w - j] * color1.R;
						color2.G += gauss[0][h - i][w - j] * color1.G;
					}


				SetPixel(inbmp, i, j, color2);
			}

	}
	else
	{
		//Gaussian
		sigma = 0.5;
		for (x = 0; x < k; x++)
		{
			for (i = 0; i < gx; i++)
				for (j = 0; j < gy; j++)
				{
					gauss[x][i][j] = exp(-(i*i + j * j)*1.0 / (2 * sigma)) / (2 * pi*sigma*sigma);
					sum[x] += gauss[x][i][j];
				}
			sigma += 2;
		}
		for (x = 0; x < k; x++)
			for (i = 0; i < gx; i++) {
				for (j = 0; j < gy; j++) {
					gauss[x][i][j] /= sum[x];
				}
			}


		//Blured Image

		for (i = 0; i < inbmp.height; i++)
			for (j = 0; j < inbmp.width; j++)
			{
				doc1 = doc; ngang1 = ngang;
				for (x = 0; x < k; x++)
				{

					if ((i - TamElip.y)*(i - TamElip.y) / ((doc + k * d)*(doc + k * d)) +
						((j - TamElip.x)*(j - TamElip.x) / ((ngang + d * k)*(ngang + d * k))) > 1)
					{
						color2.B = 0;
						color2.G = 0;
						color2.R = 0;
						for (h = i; h < i + gx; h++)
							for (w = j; w < j + gy; w++)
							{

								GetPixel(inbmp, h, w, color1);

								color2.B += gauss[k - 1][h - i][w - j] * color1.B;
								color2.R += gauss[k - 1][h - i][w - j] * color1.R;
								color2.G += gauss[k - 1][h - i][w - j] * color1.G;
							}


						SetPixel(inbmp, i, j, color2);
					}
					else

						if ((((i - TamElip.y)*(i - TamElip.y) / (doc1*doc1)) +
							((j - TamElip.x)*(j - TamElip.x) / (ngang1*ngang1)) > 1)
							&& (((i - TamElip.y)*(i - TamElip.y) / ((doc1 + d)*(doc1 + d))) +
							((j - TamElip.x)*(j - TamElip.x) / ((ngang1 + d)*(ngang1 + d))) < 1))
						{

							color2.B = 0;
							color2.G = 0;
							color2.R = 0;
							for (h = i; h < i + gx; h++)
								for (w = j; w < j + gy; w++)
								{

									GetPixel(inbmp, h, w, color1);

									color2.B += gauss[x][h - i][w - j] * color1.B;
									color2.R += gauss[x][h - i][w - j] * color1.R;
									color2.G += gauss[x][h - i][w - j] * color1.G;
								}


							SetPixel(inbmp, i, j, color2);
							break;
						}
					doc1 += d;
					ngang1 += d;
				}

			}
	}
}

void BunchImage(const Bitmap &bmp, int new_level)
{
	for (int row = 0; row < bmp.height; row++)
		for (int col = 0; col < bmp.width; col++)
		{
			Color color;
			GetPixel(bmp, row, col, color);
			color.R = (color.R / new_level) *new_level;
			color.B = (color.B / new_level) *new_level;
			color.G = (color.G / new_level) *new_level;
			SetPixel(bmp, row, col, color);
		}
}

void FindBoundary(Bitmap &bmp, double boundary, int R)
{
	BlackWhite(bmp);
	Bitmap outbmp;
	outbmp.width = bmp.width;
	outbmp.height = bmp.height;
	outbmp.rowSize = ((3 * outbmp.width + 3) / 4) * 4;
	outbmp.pixels = new unsigned char[outbmp.rowSize * outbmp.height];
	Color color1, color2;

	for (int row = 0; row < outbmp.height; row++)
		for (int col = 0; col < outbmp.width; col++)
			SetPixel(outbmp, row, col, { 255,255,255 });


	for (int row = R; row < bmp.height - R; row++)
		for (int col = R; col < bmp.width - R; col++)
		{
			int tong = 0;

			for (int i = row - R; i <= row + R; i++)
				for (int j = col - R; j <= col + R; j++)
				{
					GetPixel(bmp, i, j, color2);
					tong += color2.R;
				}
			GetPixel(bmp, row, col, color1);
			if (tong > (2 * R + 1) * (2 * R + 1) * color1.R + boundary)
			{
				SetPixel(outbmp, row, col, { 0,0,0 });
			}
		}
	bmp.width = outbmp.width;
	bmp.height = outbmp.height;
	bmp.pixels = outbmp.pixels;
	bmp.rowSize = outbmp.rowSize;
}

void ConvertToPencilSketch(Bitmap &bmp)
{
	Bitmap temp;
	BlackWhite(bmp);
	temp.width = bmp.width;
	temp.height = bmp.height;
	temp.rowSize = ((3 * bmp.width + 3) / 4) * 4;
	temp.pixels = new unsigned char[bmp.rowSize * bmp.height];
	for (int row = 0; row < bmp.height; row++)
		for (int col = 0; col < bmp.width; col++)
		{
			Color color;
			GetPixel(bmp, row, col, color);
			SetPixel(temp, row, col, color);
		}
	Negative(bmp);
	BlurImage(bmp, { 0,0 }, -1, -1, 5.0);
	for (int row = 0; row < bmp.height; row++)
		for (int col = 0; col < bmp.width; col++)
		{
			Color color2, color3;
			GetPixel(bmp, row, col, color2);
			GetPixel(temp, row, col, color3);
			color2.B = ((int)color3.B * 255 / (255 - (int)color2.B)) > 255 ? 255 : (int)color3.B * 255 / (255 - (int)color2.B);
			color2.G = ((int)color3.G * 255 / (255 - (int)color2.G)) > 255 ? 255 : (int)color3.G * 255 / (255 - (int)color2.G);
			color2.R = ((int)color3.R * 255 / (255 - (int)color2.R)) > 255 ? 255 : (int)color3.R * 255 / (255 - (int)color2.R);
			SetPixel(bmp, row, col, color2);
		}
}

void Sharpen(const Bitmap &inbmp, double k)
{
	//BlurImageforpencilsketch(inbmp, 5.0);
	//Negative(inbmp);
	int i, j, h, w, gx = 5, gy = 5;
	double gauss[10][10], pi = 3.14159, sum = 0;
	double sigma = 10.0;
	//Gaussian
	for (i = 0; i < gx; i++)
		for (j = 0; j < gy; j++)
		{
			gauss[i][j] = exp(-(i*i + j * j)*1.0 / (2 * sigma)) / (2 * pi*sigma*sigma);
			sum += gauss[i][j];
		}
	for (i = 0; i < gx; i++)
	{
		for (j = 0; j < gy; j++)
		{
			gauss[i][j] /= sum;
		}
	}

	Bitmap temp = inbmp;
	for (int row = 0; row < inbmp.height; row++)
		for (int col = 0; col < inbmp.width; col++)
		{
			Color color, color2, color1;
			GetPixel(temp, row, col, color);
			color2.B = 0;
			color2.G = 0;
			color2.R = 0;
			for (h = i; h < i + gx; h++)
				for (w = j; w < j + gy; w++)
				{

					GetPixel(inbmp, h, w, color1);

					color2.B += gauss[h - i][w - j] * color1.B;
					color2.R += gauss[h - i][w - j] * color1.R;
					color2.G += gauss[h - i][w - j] * color1.G;
				}
			double B, R, G;

			B = color.B - k * color2.B;
			G = color.G - k * color2.G;
			R = color.R - k * color2.R;
			color.R = Truncate(R); color.B = Truncate(B); color.G = Truncate(G);
			SetPixel(temp, row, col, color);
		}
}

void MixImage(Bitmap bmp1, Bitmap bmp2)
{
	if (bmp1.height != bmp2.height || bmp1.width != bmp2.width)
	{
		cout << "Two images have different sizes\n";
		return;
	}
	for (int row = 0; row < bmp1.height; row++)
	{
		for (int col = 0; col < bmp1.width; col++)
		{
			Color color1, color2;
			GetPixel(bmp1, row, col, color1);
			GetPixel(bmp2, row, col, color2);
			SetPixel(bmp1, row, col, color1 / 2 + color2 / 2);
		}
	}
}

//FormAI DATASET v1.0 Category: Natural Language Date Converter ; Style: visionary
#include <stdio.h>
#include <string.h>

void dateConverter(char input[20]) {
  int day = 0, month = 0, year = 0;
  char *monthString;

  sscanf(input, "%d %s %d", &day, monthString, &year);

  //convert month string to number
  if(strcmp(monthString, "January") == 0) {
    month = 1;
  } else if(strcmp(monthString, "February") == 0) {
    month = 2;
  } else if(strcmp(monthString, "March") == 0) {
    month = 3;
  } else if(strcmp(monthString, "April") == 0) {
    month = 4;
  } else if(strcmp(monthString, "May") == 0) {
    month = 5;
  } else if(strcmp(monthString, "June") == 0) {
    month = 6;
  } else if(strcmp(monthString, "July") == 0) {
    month = 7;
  } else if(strcmp(monthString, "August") == 0) {
    month = 8;
  } else if(strcmp(monthString, "September") == 0) {
    month = 9;
  } else if(strcmp(monthString, "October") == 0) {
    month = 10;
  } else if(strcmp(monthString, "November") == 0) {
    month = 11;
  } else if(strcmp(monthString, "December") == 0) {
    month = 12;
  } else {
    printf("Invalid input. Please enter in format: dd Month (with capital letter) yyyy\n");
    return;
  }

  //validate input
  if(day < 1 || day > 31) {
    printf("Invalid day. Please enter a number between 1 and 31.\n");
    return;
  }

  if(year < 0 || year > 9999) {
    printf("Invalid year. Please enter a number between 0 and 9999.\n");
    return;
  }

  //print output
  printf("%02d/%02d/%d", month, day, year);
}

int main(void) {
  char input[20];

  printf("Please enter a date in the format: dd Month (with capital letter) yyyy \n");
  fgets(input, 20, stdin);

  //remove newline character at the end of the input string
  input[strcspn(input, "\n")] = 0;

  dateConverter(input);

  return 0;
}

//FormAI DATASET v1.0 Category: Memory Game ; Style: thoughtful
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define ROWS 4
#define COLS 4
#define MAX_GUESSES 16

/* Function Prototypes */
void printBoard(char board[][COLS]);
void fillBoard(char board[][COLS]);
void shuffleBoard(char board[][COLS]);
void getPlayerGuess(char board[][COLS], int* row, int* col);
void updateBoard(char board[][COLS], int row1, int col1, int row2, int col2);
int checkForMatch(char board[][COLS], int row1, int col1, int row2, int col2);

int main()
{
    char board[ROWS][COLS];
    int row1, col1, row2, col2, guesses = 0;

    srand(time(NULL));
    fillBoard(board);
    shuffleBoard(board);

    printf("Welcome to the Memory Game!\n");
    printf("Try to match all the letters in the least amount of guesses.\n\n");

    while(guesses < MAX_GUESSES)
    {
        printBoard(board);
        getPlayerGuess(board, &row1, &col1);
        getPlayerGuess(board, &row2, &col2);

        if(checkForMatch(board, row1, col1, row2, col2))
        {
            printf("Congratulations! You found a match!\n\n");
            updateBoard(board, row1, col1, row2, col2);
        }
        else
        {
            printf("Sorry, those two cards do not match.\n\n");
        }

        guesses++;
    }

    printf("Game over! You took %d guesses.\n", guesses);

    return 0;
}

void printBoard(char board[][COLS])
{
    printf("\n");
    for(int i = 0; i < ROWS; i++)
    {
        for(int j = 0; j < COLS; j++)
        {
            printf("%c ", board[i][j]);
        }
        printf("\n");
    }
    printf("\n");
}

/* Function to fill the board with random letters */
void fillBoard(char board[][COLS])
{
    char letters[] = {'A','B','C','D','E','F','G','H'};

    for(int i = 0; i < ROWS; i++)
    {
        for(int j = 0; j < COLS; j++)
        {
            board[i][j] = letters[(i * 4) + j];
        }
    }
}

/* Function to shuffle the board */
void shuffleBoard(char board[][COLS])
{
    for(int i = 0; i < ROWS*COLS; i++)
    {
        int r1 = rand() % ROWS;
        int c1 = rand() % COLS;
        int r2 = rand() % ROWS;
        int c2 = rand() % COLS;

        char temp = board[r1][c1];
        board[r1][c1] = board[r2][c2];
        board[r2][c2] = temp;
    }
}

/* Function to get player guess */
void getPlayerGuess(char board[][COLS], int* row, int* col)
{
    do
    {
        printf("Enter row and column of your guess (ex. 1 2): ");
        scanf("%d %d", row, col);
    } while(*row < 1 || *row > ROWS || *col < 1 || *col > COLS || board[*row-1][*col-1] == '*');

    *row -= 1;
    *col -= 1;
}

/* Function to update the board with a match */
void updateBoard(char board[][COLS], int row1, int col1, int row2, int col2)
{
    board[row1][col1] = '*';
    board[row2][col2] = '*';
}

/* Function to check for a match */
int checkForMatch(char board[][COLS], int row1, int col1, int row2, int col2)
{
    if(board[row1][col1] == board[row2][col2])
    {
        return 1;
    }
    else
    {
        return 0;
    }
}

#include <iostream>
#include <string>
#include <fstream>
#include <assert.h>
#include <stdlib.h>

#include "binarysearchtree.h"
#include "avltree.h"

using namespace std;

void print_stats(BinarySearchTree * tree, AvlTree * avl_tree) {
    cout << "BST: " << endl;
    cout << "Left links followed = " << tree->GetLeftLinksFollowed() << endl;
    cout << "Right links followed = " << tree->GetRightLinksFollowed() << endl;
    cout << "Total number of nodes = " << tree->card_of() << endl;
    cout << "Avg. node depth = " << tree->exp_path_length() << endl << endl;

    cout << "AVL Tree: " << endl;
    cout << "Left links followed = " << avl_tree->GetLeftLinksFollowed() << endl;
    cout << "Right links followed = " << avl_tree->GetRightLinksFollowed() << endl;
    cout << "Total number of nodes = " << avl_tree->card_of() << endl;
    cout << "Single Rotations = " << avl_tree->GetSingleRotations() << endl;
    cout << "Double Rotations = " << avl_tree->GetDoubleRotations() << endl;
    cout << "Avg. node depth = " << avl_tree->exp_path_length() << endl << endl;
}

int main () {

    BinarySearchTree  * tree;
    AvlTree  * avl_tree;
    string word;
    string inFile;
    const string ITEM_NOT_FOUND("");
    int i;
    int n=0;
    int num_words=0;
    string        word_found;			// return value for tree->find()
    string        avl_word_found;       // return value for tree->find()
    string response;

    tree = new BinarySearchTree(ITEM_NOT_FOUND);
    avl_tree = new AvlTree(ITEM_NOT_FOUND);

    cout << "Please enter the name of a file of words: ";
    cin >> inFile;

    ifstream fin(inFile.c_str());

    if (!fin) {
        cerr <<"Cannot open " << inFile << endl;
        exit(1);
    }

    while (fin >> word) {

        n = int (word.size());
        assert(n > 0);
        for (i=0; i < n; ++i) {			// Convert to lowercase.
            word[i] = tolower(word[i]);
        }
        if (!isalpha(word[n - 1])) {	// eliminate trailing punctuation
            word = word.substr(0, n-1);
        }

        // Echo the contents the words that have been read to the screen.
        cout << " " << word;
        num_words++;

        tree->insert(word);
        avl_tree->insert(word);

    }

    cout << "\n" << num_words << " words in this text\n";
    cout << endl << endl;

    // Print out Statistics about Shape of the trees
    // and number of links followed.
    print_stats(tree, avl_tree);

    // Find a word in both trees.
    cout << "\tEnter word to lookup > ";
    cin  >> response;

    word_found = tree->find(response);
    avl_word_found = avl_tree->find(response);

    if (word_found != ITEM_NOT_FOUND && avl_word_found != ITEM_NOT_FOUND) {
        cout << "\tWord was found: " << word_found << endl;
    } else {
        cout << response << " was not found in "
        << inFile.c_str() << endl;
    }

    // Print out Statistics about Shape of the trees
    // and number of links followed.
    print_stats(tree, avl_tree);

    fin.close();
    return 0;
}

