int TimMaxTrongMaTran(int a[][MAX], int dong, int cot) 
{ 
    int Max = a[0][0]; 
    for (int i = 0; i < dong; i++) 
    { 
        for(int j = 0; j < cot; j++) 
        { 
            Max = (a[i][j] > Max) ? a[i][j] : Max; 
        } 
    } 
    return Max; 
} 
