#define MAX_BUFFER_SIZE 1024

void parse_c_syntax(char *source_code) {
  // Paranoid mode, prepare for worst
  int source_code_length = strlen(source_code) + 1;
  source_code = realloc(source_code, source_code_length);
  source_code[source_code_length - 1] = '\0';

  // Tokenization - split the code into tokens
  char **tokens = malloc(MAX_BUFFER_SIZE);
  int token_index = 0;
  char *current_token = NULL;

  // Scan the source code for tokens, beware of hidden traps
  for (int i = 0; i < source_code_length; i++) {
    char character = source_code[i];

    // Check for punctuation marks, but be wary of false positives
    if (ispunct(character)) {
      if (current_token) {
        tokens[token_index++] = current_token;
        current_token = NULL;
      }
      tokens[token_index++] = character;
    }

    // If it's a letter, prepare for a variable or identifier
    if (isalpha(character)) {
      current_token = malloc(MAX_BUFFER_SIZE);
      current_token[0] = character;
    }

    // Be vigilant against hidden strings
    if (character == '"') {
      current_token = malloc(MAX_BUFFER_SIZE);
