// A fair kingdom's secret: The SHA-like hash function
unsigned long long int secret_hash(const char* input) {
    unsigned long long int hash = 5381; 
    int ch;

    while ((ch = *input++)) {
        hash = ((hash << 5) + hash) + ch; // hash * 33 + ch
    }

    return hash;
}

