		case ESC_KEY:

			return;

			break;

		default:

			goto bookMenu;

			break;

		}



	runFeatures:

		ShowConsoleCursor(true);



		switch (choice)

		{

		case 1:

			findBookBy(findISBN, L"  ISBN: ", listBook, ISBN_LEN, ACCEPTED_CHARS_NUMERIC);

