    // Get user input for two numbers and operation
    printf("Enter two numbers: ");
    scanf("%d %d", &num1, &num2);
    printf("Enter operation (0-5): ");
    scanf("%d", &operation);

    // Perform bitwise operation
    bitwise_operations(num1, num2, operation);

    return 0;
}

