{
    int N=Image.size();
    int M=Image[0].size();
    int i,j;
    ImageBool.resize(N);
    for(i=0;i<N;i++){
        ImageBool[i].resize(M);
        for(j=0;j<M;j++){
            ImageBool[i][j]=Image[i][j];
        }
    }
    goButton->setEnabled(true);
}

void BoxCountingCalculator::calculate()
{
    vector <double> XCoord,YCoord;
    int t;
    int dx, dy;
    bool isPresent;
    int Np[NumBoxes];
    int N=ImageBool.size();
    int M=ImageBool[0].size();
    int i,j,k;
    int x0, y0,x,y;
    XCoord.resize(NumBoxes);
    YCoord.resize(NumBoxes);
    for(k=0; k<NumBoxes;k++){
        if(OffSetComboBox->currentIndex()==1){
            x0=rand()%varOff;
            y0=rand()%varOff;
        } else {
            x0=xOff; y0=yOff;
        }
        t=boxes[k];
        while(t<x0) x0-=t;
        while(t<y0) y0-=t;
        Np[k]=0;
        for(i=-1; i<=(N-x0)/t;i++){
            for(j=-1; j<=(M-y0)/t;j++){
                isPresent=false;
                for(dx=0; dx<t; dx++){
                    for(dy=0; dy<t; dy++){
                        x=x0+i*t+dx;
                        y=y0+j*t+dy;
                        if(x>=0 && x<N && y>=0 && y<M){
                            if(ImageBool[x][y]==true) isPresent=true;
                        }
                    }
                }
                if(isPresent==true) Np[k]++;
            }
        }        
        XCoord[k]=-log(static_cast<double>(t));
        YCoord[k]=log(static_cast<double>(Np[k]));
    }
    plotter->setData(XCoord,YCoord);
    plotter->setType("X-Y");
    plotter->linearFit();
    plotter->makePlot();
    plotter->show();
}

