// CPU Scheduling Algorithms Example Program

#include <stdio.h>
#include <stdlib.h>

// Process Structure
typedef struct {
  int pid; // Process ID
  int arrival_time; // Arrival time
  int burst_time; // Burst time
  int priority; // Priority
  int turnaround_time; // Turnaround time
  int completion_time; // Completion time
  int waiting_time; // Waiting time
  int response_time; // Response time
} Process;

// Function to calculate turnaround time
int calculate_turnaround_time(Process *p) {
  return p->completion_time - p->arrival_time;
}

// Function to calculate waiting time
int calculate_waiting_time(Process *p) {
  return p->turnaround_time - p->burst_time;
}

// Function to calculate response time
int calculate_response_time(Process *p) {
  return p->arrival_time - p->burst_time;
}

// Function to calculate completion time
int calculate_completion_time(Process *p) {
  return p->arrival_time + p->burst_time;
}

// Function to schedule the process
void schedule_process(Process *p) {
  // Set the completion time
  p->completion_time = calculate_completion_time(p);
  // Calculate the turnaround time
  p->turnaround_time = calculate_turnaround_time(p);
  // Calculate the waiting time
  p->waiting_time = calculate_waiting_time(p);
  // Calculate the response time
  p->response_time = calculate_response_time(p);
}

// Function to print the results
void print_results(Process *p) {
  printf("Process ID: %d\n", p->pid);
  printf("Arrival time: %d\n", p->arrival_time);
  printf("Burst time: %d\n", p->burst_time);
  printf("Priority: %d\n", p->priority);
  printf("Turnaround time: %d\n", p->turnaround_time);
  printf("Completion time: %d\n", p->completion_time);
  printf("Waiting time: %d\n", p->waiting_time);
  printf("Response time: %d\n", p->response_time);
}

int main() {
  // Initialize the processes
  Process p1 = {1, 0, 5, 10, 0, 0, 0, 0};
  Process p2 = {2, 1, 3, 8, 0, 0, 0, 0};
  Process p3 = {3, 2, 2, 6, 0, 0, 0, 0};
  Process p4 = {4, 3, 1, 4, 0, 0, 0, 0};
  Process p5 = {5, 4, 4, 2, 0, 0, 0, 0};

  // Schedule the processes
  schedule_process(&p1);
  schedule_process(&p2);
  schedule_process(&p3);
  schedule_process(&p4);
  schedule_process(&p5);

  // Print the results
  print_results(&p1);
  print_results(&p2);
  print_results(&p3);
  print_results(&p4);
  print_results(&p5);

  return 0;
}

//GEMINI-pro DATASET v1.0 Category: Port Scanner ; Style: distributed
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/socket.h>
#include <netinet/in.h>

// Maximum number of ports to scan
#define MAX_PORTS 100

// Structure to store the port scan results
typedef struct port_scan_result {
    int port;
    int status;
} port_scan_result;

// Function to scan a single port
void* scan_port(void* arg) {
    // Get the port number from the argument
    int port = *(int*)arg;

    // Create a socket
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd == -1) {
        perror("socket");
        exit(1);
    }

    // Set the socket timeout
    struct timeval timeout;
    timeout.tv_sec = 1;  // 1 second timeout
    timeout.tv_usec = 0;
    if (setsockopt(sockfd, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof(timeout)) == -1) {
        perror("setsockopt");
        exit(1);
    }

    // Connect to the port
    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    addr.sin_port = htons(port);
    int ret = connect(sockfd, (struct sockaddr*)&addr, sizeof(addr));

    // Free the argument
    free(arg);

    // Store the port scan result
    port_scan_result result;
    result.port = port;
    result.status = ret == 0 ? 1 : 0;

    // Close the socket
    close(sockfd);

    // Return the port scan result
    return &result;
}

// Main function
int main() {
    // Create an array of ports to scan
    int ports[MAX_PORTS];
    for (int i = 0; i < MAX_PORTS; i++) {
        ports[i] = i + 1;
    }

    // Create a thread pool
    pthread_t threads[MAX_PORTS];

    // Start the threads
    for (int i = 0; i < MAX_PORTS; i++) {
        // Allocate memory for the argument
        int* arg = malloc(sizeof(int));
        *arg = ports[i];

        // Create the thread
        if (pthread_create(&threads[i], NULL, scan_port, arg) != 0) {
            perror("pthread_create");
            exit(1);
        }
    }

    // Join the threads
    port_scan_result* results[MAX_PORTS];
    for (int i = 0; i < MAX_PORTS; i++) {
        if (pthread_join(threads[i], (void**)&results[i]) != 0) {
            perror("pthread_join");
            exit(1);
        }
    }

    // Print the port scan results
    printf("Port Scan Results:\n");
    for (int i = 0; i < MAX_PORTS; i++) {
        printf("Port %d: %s\n", results[i]->port, results[i]->status ? "Open" : "Closed");
    }

    return 0;
}

