    send(sock, email_body, sizeof(email_body), 0);

    // Send QUIT command
    char quit_command[10] = "QUIT\r\n";
    send(sock, quit_command, sizeof(quit_command), 0);

    // Receive response
    recv(sock, &server_response, sizeof(server_response), 0);

    // Close the socket
    close(sock);

    return 0;
}

