#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <unistd.h>

#define BUFFER_SIZE 4096

struct file_info {
    char *file_name;
    int file_size;
    off_t file_position;
};

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <file_name>\n", argv[0]);
        return 1;
    }

    // Get the file name and size from the user
    char *file_name = argv[1];
    struct stat stat_info;
    stat(file_name, &stat_info);
    int file_size = stat_info.st_size;

    // Create a buffer to store the file contents
    char *buffer = malloc(BUFFER_SIZE);

    // Open the file in read-only mode
    int fd = open(file_name, O_RDONLY, 0);
    if (fd == -1) {
        perror("Failed to open file");
        return 2;
    }

    // Get the file position from the user
    off_t file_position = 0;
    scanf("%ld", &file_position);

    // Seek to the specified file position
    if (lseek(fd, file_position, SEEK_SET) == -1) {
        perror("Failed to seek to file position");
        return 2;
    }

    // Read the file contents into the buffer
    read(fd, buffer, BUFFER_SIZE);

    // Close the file
    close(fd);

    // Print the file contents
    printf("File contents:\n%s\n", buffer);

    // Free the buffer
    free(buffer);

    return 0;
}

#include <stdio.h>
