#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_STRING_LENGTH 100

int main() {
  char string1[MAX_STRING_LENGTH];
  char string2[MAX_STRING_LENGTH];
  int length;

  // Get the first string from the user
  printf("Enter the first string: ");
  fgets(string1, MAX_STRING_LENGTH, stdin);

  // Get the second string from the user
  printf("Enter the second string: ");
  fgets(string2, MAX_STRING_LENGTH, stdin);

  // Calculate the length of the longest common subsequence
  length = longest_common_subsequence(string1, string2);

  // Print the length of the longest common subsequence
  printf("The length of the longest common subsequence is: %d\n", length);

  return 0;
}

int longest_common_subsequence(char* string1, char* string2) {
  int length1 = strlen(string1);
  int length2 = strlen(string2);
  int dp[length1 + 1][length2 + 1];
  int i, j, k;

  // Initialize the dp matrix
  for (i = 0; i <= length1; i++) {
    for (j = 0; j <= length2; j++) {
      if (i == 0 || j == 0) {
        dp[i][j] = 0;
      }
    }
  }

  // Fill in the dp matrix
  for (i = 1; i <= length1; i++) {
    for (j = 1; j <= length2; j++) {
      if (string1[i - 1] == string2[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1;
      } else {
        dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);
      }
    }
  }

  // Find the length of the longest common subsequence
  for (i = 0; i <= length1; i++) {
    for (j = 0; j <= length2; j++) {
      if (dp[i][j] > k) {
        k = dp[i][j];
      }
    }
  }

  return k;
}

int max(int a, int b) {
  if (a > b) {
    return a;
  } else {
    return b;
  }
}

