        {
            qrcode_matrix[r][c] = (qrcode_data[i] == 'A') ? 1 : 0;
            i++;
        }
    }

    // Print QR code matrix
    for (int r = 0; r < qrcode_size; r++)
    {
        for (int c = 0; c < qrcode_size; c++)
        {
            printf("%d ", qrcode_matrix[r][c]);
        }
        printf("\n");
    }

    // Free memory
    for (int i = 0; i < qrcode_size; i++)
    {
        free(qrcode_matrix[i]);
    }
    free(qrcode_matrix);

    printf("QR Code generated in %d seconds.\n", (int)time(NULL) - t);

    return 0;
}

