#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>

#define NUM_CARS 1000
#define MAX_SPEED 60
#define MIN_SPEED 5
#define CAR_LENGTH 5

typedef struct {
    int x;
    int y;
    int speed;
    int lane;
} Car;

int main() {
    srand(time(NULL));

    Car cars[NUM_CARS];
    int numCars = 0;
    int i;

    // Initialize cars
    for (i = 0; i < NUM_CARS; i++) {
        cars[i].x = rand() % 1000;
        cars[i].y = rand() % 1000;
        cars[i].speed = rand() % (MAX_SPEED - MIN_SPEED) + MIN_SPEED;
        cars[i].lane = rand() % 5; // Randomly assign a lane (0-4)
        numCars++;
    }

    // Print initial car positions
    printf("Initial car positions:\n");
    for (i = 0; i < NUM_CARS; i++) {
        printf("Car %d: (%d, %d), speed: %d, lane: %d\n", i + 1, cars[i].x, cars[i].y, cars[i].speed, cars[i].lane);
    }

    // Main traffic flow simulation loop
    while (numCars > 0) {
        // Update car positions
        for (i = 0; i < NUM_CARS; i++) {
            int nextX = cars[i].x;
            int nextY = cars[i].y;

            // Check if car is at end of current lane
            if (nextX == 1000 - CAR_LENGTH * cars[i].lane) {
                nextX = 0;
            }

            // Move car to next lane if necessary
            if (nextX == 0 || nextX == 1000) {
                if (nextX == 0) {
                    nextX = 1000 - CAR_LENGTH * (cars[i].lane + 1);
                } else {
                    nextX = 0;
                }
            }

            // Calculate distance to travel
            int distance = nextX - cars[i].x;

            // Update car position and speed
            cars[i].x = nextX;
            cars[i].y = nextY;
            cars[i].speed -= distance / CAR_LENGTH;

            // Adjust speed if necessary
            if (cars[i].speed < MIN_SPEED) {
                cars[i].speed = MIN_SPEED;
            }
            if (cars[i].speed > MAX_SPEED) {
                cars[i].speed = MAX_SPEED;
            }

            // Print updated car positions
            printf("Car %d: (%d, %d), speed: %d, lane: %d\n", i + 1, cars[i].x, cars[i].y, cars[i].speed, cars[i].lane);
        }

        // Remove cars that have left the road
        numCars = 0;
        for (i = 0; i < NUM_CARS; i++) {
            if (cars[i].x >= 1000) {
                numCars++;
                printf("Car %d has left the road.\n", i + 1);
            }
        }
    }

    return 0;
}

