    *node_count+=1;
    *total_search=*total_search+node->getSearchCost();
    cout<<"traversal "<<node->getElem()<<" ["<<node->getSearchCost()<<"]\n";

    if (node->getRight()!= NULL)
        Node_traversal(node->getRight(), node_count, total_search);

}

