#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define constants
#define WORLD_SIZE 1000
#define NUM_OBJECTS 100
#define STEPS_PER_SEC 10
#define SEC_PER_DAY 86400

// Define object types
enum object_type {
    OBJECT_SUN,
    OBJECT_PLANET,
    OBJECT_ASTEROID,
    OBJECT_METEOR
};

// Define object structure
struct object {
    enum object_type type;
    int x, y;
    int radius;
    int mass;
    int velocity;
};

// Define world structure
struct world {
    struct object objects[NUM_OBJECTS];
    int num_objects;
};

// Initialize world
void init_world(struct world *w) {
    // Add objects
    for (int i = 0; i < NUM_OBJECTS; i++) {
        struct object obj;
        obj.type = OBJECT_PLANET;
        obj.x = rand() % WORLD_SIZE;
        obj.y = rand() % WORLD_SIZE;
        obj.radius = rand() % 10 + 10;
        obj.mass = rand() % 10000 + 1000;
        obj.velocity = rand() % 10 + 1;
        w->objects[i] = obj;
    }
    w->num_objects = NUM_OBJECTS;
}

// Update world
void update_world(struct world *w, int dt) {
    // Update objects
    for (int i = 0; i < w->num_objects; i++) {
        struct object obj = w->objects[i];
        obj.x += obj.velocity * dt;
        obj.y += obj.velocity * dt;
        w->objects[i] = obj;
    }
}

// Print world
void print_world(struct world *w) {
    // Print objects
    for (int i = 0; i < w->num_objects; i++) {
        struct object obj = w->objects[i];
        printf("Object %d: (%d, %d), radius: %d, mass: %d, velocity: %d\n",
               i, obj.x, obj.y, obj.radius, obj.mass, obj.velocity);
    }
}

int main() {
    // Initialize world
    struct world w;
    init_world(&w);

    // Update world
    int dt = SEC_PER_DAY / STEPS_PER_SEC;
    for (int i = 0; i < STEPS_PER_SEC; i++) {
        update_world(&w, dt);
    }

    // Print world
    print_world(&w);

    return 0;
}

#include "shaderprogram.h"

#include <QFile>
#include <QList>
#include <QPair>
#include <QMessageBox>
#include <QTextStream>

ShaderProgram::ShaderProgram() {
}

int ShaderProgram::init(const QStringList& prepend, const QString& fname) {
    // Shader types with file extensions
    const QVector<QPair<QOpenGLShader::ShaderTypeBit, QString>> shaderTypes = {
        {QOpenGLShader::Vertex, ".vsh"},
        {QOpenGLShader::Fragment, ".fsh"},
        {QOpenGLShader::Geometry, ".gsh"},
        {QOpenGLShader::TessellationControl, ".tcs"},
        {QOpenGLShader::TessellationEvaluation, ".tes"}
    };
    // Shader "library" code
    QString sharedCode;
    for(const QString& prependFname : prepend) {
        QFile f(prependFname);
        if(!f.open(QIODevice::ReadOnly)) {
            qDebug() << "Could not open shader library file: " + prependFname;
            return 5;
        }
        QTextStream in(&f);
        sharedCode += in.readAll();
    }
    // Shaders stage code which contains main()
    for(const auto& st : shaderTypes) {
        const QString shaderFname = fname + st.second;
        QFile f(shaderFname);
        if(!f.open(QIODevice::ReadOnly)) {
            qDebug() << "Could not open shader stage file: " + shaderFname;
            return 4;
        }
        QTextStream in(&f);
        if(!shader.addShaderFromSourceCode(st.first, sharedCode + in.readAll())) {
            qDebug() << "Shader compilation failed.";
            return 1;
        }
    }
    // Linking shaders into program
    if(!shader.link()) {
        qDebug() << "Shader linking failed.";
        return 2;
    }
    return 0;
}

//GPT-4o-mini DATASET v1.0 Category: Password Strength Checker ; Style: safe
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_PASSWORD_LENGTH 128

void evaluate_password_strength(const char *password) {
    int length = strlen(password);
    int has_upper = 0, has_lower = 0, has_digit = 0, has_special = 0;

    if (length < 8) {
        printf("Password is too short! It should be at least 8 characters long.\n");
        return;
    }

    for (int i = 0; i < length; i++) {
        if (isupper(password[i])) {
            has_upper = 1;
        } else if (islower(password[i])) {
            has_lower = 1;
        } else if (isdigit(password[i])) {
            has_digit = 1;
        } else if (!isalnum(password[i])) {
            has_special = 1;
        }
    }

    if (has_upper && has_lower && has_digit && has_special) {
        printf("Password strength: Strong\n");
    } else if ((has_upper || has_lower) && (has_digit || has_special) && length >= 10) {
        printf("Password strength: Medium\n");
    } else {
        printf("Password strength: Weak\n");
        if (!has_upper) {
            printf("- Consider adding uppercase letters.\n");
        }
        if (!has_lower) {
            printf("- Consider adding lowercase letters.\n");
        }
        if (!has_digit) {
            printf("- Consider adding digits.\n");
        }
        if (!has_special) {
            printf("- Consider adding special characters (e.g., @, #, $, %).\n");
        }
    }
}

int main() {
    char password[MAX_PASSWORD_LENGTH];

    printf("Enter your password (max %d characters): ", MAX_PASSWORD_LENGTH - 1);
    fgets(password, MAX_PASSWORD_LENGTH, stdin);

    // Removing newline character if present
    password[strcspn(password, "\n")] = 0;

    evaluate_password_strength(password);

    return 0;
}

