int FindMid(int a[], int n){

    int max = a[0];
    int cur = a[0];

    for(int i = 1; i < n; ++i){
        if(cur == -1 && a[i] > max){
            max = a[i];
            cur = max;
        }else if(cur != -1 && a[i] > cur){
            if(a[i] > max)
                max = a[i];
        }else if(cur == -1 && a[i] < max ){
            cur = -1;
        }else if(cur != -1 && a[i] < cur){
            cur = -1;
        }
    }
    return cur;
}


