void SapXepCheoPhuGiamDan(int a[][MAX], int n)
{
    for(int i = 0; i < n; i++)
    {
        for(int j = i + 1; j < n; j++)
        {
            int max = a[i][n - 1 - i];
            if(a[j][j - 1 - i] > max)
            {
                max = a[j][n - 1 - j];
                a[j][n - 1 - j] = a[i][n - 1 - i];
                a[i][n - 1 - i] = max;  
            }
        }
    }
}

int main()
{
    int a[MAX][MAX], n;
    NhapMaTran(a,n);
    XuatMaTran(a,n);
    SapXepCheoPhuGiamDan(a, n);
