// Structure to store question and answer
struct Question {
    char question[256];
    char options[4][64];
    int correctAnswer;
};

// Function to display the question and options
void displayQuestion(struct Question question) {
    printf("%s\n", question.question);
    for (int i = 0; i < 4; i++) {
        printf("%d. %s\n", i + 1, question.options[i]);
    }
}

// Function to get the user's answer
int getAnswer() {
    int answer;
    scanf("%d", &answer);
    return answer;
}

// Function to check if the answer is correct
int isCorrectAnswer(struct Question question, int answer) {
    return question.correctAnswer == answer;
}

// Function to display the result
void displayResult(int score, int totalQuestions) {
    printf("Your score is %d out of %d\n", score, totalQuestions);
}

// Main function
int main() {
    // Create an array of questions
    struct Question questions[] = {
        {
            "What is the capital of India?",
            {"New Delhi", "Mumbai", "Kolkata", "Chennai"},
            1
        },
        {
            "Who is the current Prime Minister of India?",
            {"Narendra Modi", "Rahul Gandhi", "Arvind Kejriwal", "Mamata Banerjee"},
            1
        },
        {
            "What is the national animal of India?",
            {"Tiger", "Lion", "Elephant", "Rhinoceros"},
            1
        },
        {
            "What is the national bird of India?",
            {"Peacock", "Parrot", "Sparrow", "Eagle"},
            1
        },
        {
            "What is the national flower of India?",
            {"Lotus", "Rose", "Jasmine", "Sunflower"},
            1
        }
    };

    // Get the total number of questions
    int totalQuestions = sizeof(questions) / sizeof(struct Question);

    // Initialize the score
    int score = 0;

    // Iterate over the questions and display them one by one
    for (int i = 0; i < totalQuestions; i++) {
        displayQuestion(questions[i]);
        int answer = getAnswer();
        if (isCorrectAnswer(questions[i], answer)) {
            score++;
        }
    }

    // Display the result
    displayResult(score, totalQuestions);

    return 0;
}

