#include <stdio.h>
#include <stdlib.h>

void play_game() {
  char board[9] = {'1', '2', '3', '4', '5', '6', '7', '8', '9'};
  int turn = 0;
  int game_over = 0;

  // Game loop
  while (!game_over) {
    // Get the player's move
    int move = get_move();

    // Validate the move
    if (move < 1 || move > 9) {
      printf("Invalid move.\n");
      continue;
    }

    // Place the player's mark on the board
    board[move - 1] = 'X';

    // Check if the player has won
    if (check_win(board, turn)) {
      game_over = 1;
      printf("You have won!\n");
    } else {
      // Switch turns
      turn = (turn + 1) % 2;
    }
  }

  // End of game
  printf("Game over.\n");
}

int get_move() {
  int move;
  printf("Enter your move (1-9): ");
  scanf("%d", &move);
  return move;
}

int check_win(char board[], int turn) {
  // Check rows
  for (int i = 0; i < 3; i++) {
    if (board[i] == board[i + 1] && board[i] == board[i + 2] && board[i] == board[turn]) {
      return 1;
    }
  }

  // Check columns
  for (int i = 0; i < 3; i++) {
    if (board[i] == board[i + 3] && board[i] == board[i + 6] && board[i] == board[turn]) {
      return 1;
    }
  }

  // Check diagonals
  if (board[0] == board[4] && board[0] == board[8] && board[0] == board[turn]) {
    return 1;
  } else if (board[2] == board[4] && board[2] == board[6] && board[2] == board[turn]) {
    return 1;
  }

  // No win
  return 0;
}

int main() {
  play_game();
  return 0;
}

