#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netinet/in.h>

#define PORT 8080
#define BUFFER_SIZE 4096

void handle_client(int client_socket);
void forward_request(int client_socket, const char *url, const char *port);
void send_response(int client_socket, const char *response, size_t response_length);

int main() {
    int server_socket, client_socket;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_addr_len = sizeof(client_addr);

    // Create socket
    if ((server_socket = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("Socket creation failed");
        return EXIT_FAILURE;
    }

    // Configure server address
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    // Bind the socket
    if (bind(server_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        close(server_socket);
        return EXIT_FAILURE;
    }

    // Listen for incoming connections
    if (listen(server_socket, 5) < 0) {
        perror("Listen failed");
        close(server_socket);
        return EXIT_FAILURE;
    }

    printf("Proxy server is running on port %d...\n", PORT);

    // Main Loop
    while (1) {
        // Accept client connection
        client_socket = accept(server_socket, (struct sockaddr *)&client_addr, &client_addr_len);
        if (client_socket < 0) {
            perror("Accept failed");
            close(server_socket);
            return EXIT_FAILURE;
        }

        handle_client(client_socket);
        close(client_socket);
    }

    close(server_socket);
    return EXIT_SUCCESS;
}

void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE] = {0};
    ssize_t read_size;

    // Read request from client
    read_size = read(client_socket, buffer, sizeof(buffer) - 1);
    if (read_size < 0) {
        perror("Read failed");
        return;
    }

    buffer[read_size] = '\0';
    printf("Received request:\n%s\n", buffer);

    // Extract URL from the HTTP request
    char method[10], url[256], version[10];
    sscanf(buffer, "%s %s %s", method, url, version);

    // Remove the leading "http://" from the URL for forwarding
    char *ptr = strstr(url, "://");
    if (ptr) {
        ptr += 3; // skip "://"
        char *end = strchr(ptr, '/');
        if (end) {
            *end = '\0'; // terminate hostname before path
            ptr = end; // use it to retrieve the path later
        }
    }

    char *hostname = url;
    forward_request(client_socket, hostname, "80");
}

void forward_request(int client_socket, const char *hostname, const char *port) {
    int server_socket;
    struct sockaddr_in server_addr;
    char buffer[BUFFER_SIZE];
    snprintf(buffer, sizeof(buffer), "GET / HTTP/1.1\r\nHost: %s\r\nConnection: close\r\n\r\n", hostname);

    // Create socket for forwarding request
    if ((server_socket = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("Socket creation failed");
        return;
    }

    // Configure server address
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(atoi(port));
    inet_pton(AF_INET, hostname, &server_addr.sin_addr);

    // Connect to server
    if (connect(server_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Connect failed");
        close(server_socket);
        return;
    }

    // Send request to server
    send(server_socket, buffer, strlen(buffer), 0);

    // Read the response from server
    ssize_t response_length;
    while ((response_length = read(server_socket, buffer, sizeof(buffer))) > 0) {
        send_response(client_socket, buffer, response_length);
    }

    close(server_socket);
}

void send_response(int client_socket, const char *response, size_t response_length) {
    send(client_socket, response, response_length, 0);
}

