void *chunk_generator(void *void_ptr)
{
	wavegen* pwgen = (wavegen*) void_ptr;
	wgchunk cnk;

	printf("Start wave generator\n");
	while(pwgen->get_exit_request() == false){
		if(pwgen->get_chunks_size() <= CHUNK_QUEUE_SIZE){
			pwgen->parse_all();
			for(int i = 0; i < FRAME_SIZE; i++){
