#include<stdio.h>
#include<stdlib.h>
#include<time.h>

#define ROWS 10
#define COLS 10
#define NEIGHBOURS 8

typedef struct {
    int row;
    int col;
} Cell;

Cell board[ROWS][COLS];

void initializeBoard() {
    int i, j;
    for (i = 0; i < ROWS; i++) {
        for (j = 0; j < COLS; j++) {
            board[i][j].row = i;
            board[i][j].col = j;
        }
    }
}

void printBoard() {
    int i, j;
    for (i = 0; i < ROWS; i++) {
        for (j = 0; j < COLS; j++) {
            printf("(%d, %d) ", board[i][j].row, board[i][j].col);
        }
        printf("\n");
    }
}

int countNeighbours(Cell cell) {
    int count = 0;
    int i, j;
    for (i = -1; i <= 1; i++) {
        for (j = -1; j <= 1; j++) {
            if ((i!= 0 || j!= 0) && (board[(cell.row + i + ROWS) % ROWS][(cell.col + j + COLS) % COLS].row == cell.row && board[(cell.row + i + ROWS) % ROWS][(cell.col + j + COLS) % COLS].col == cell.col)) {
                count++;
            }
        }
    }
    return count;
}

void nextGeneration() {
    int i, j;
    for (i = 0; i < ROWS; i++) {
        for (j = 0; j < COLS; j++) {
            int neighbours = countNeighbours(board[i][j]);
            if (neighbours == 3 || neighbours == 4) {
                board[i][j].row = i;
                board[i][j].col = j;
            } else {
                board[i][j].row = -1;
                board[i][j].col = -1;
            }
        }
    }
}

int main() {
    srand(time(NULL));
    initializeBoard();
    int i, j;
    for (i = 0; i < ROWS; i++) {
        for (j = 0; j < COLS; j++) {
            board[i][j].row = i;
            board[i][j].col = j;
        }
    }
    int generations = 0;
    while (1) {
        printBoard();
        nextGeneration();
        generations++;
        if (generations == 100) {
            break;
        }
    }
    return 0;
}

