﻿#include <stdio.h>
#include <stdlib.h>

typedef char Datatype;
typedef struct BTreeNode{
    Datatype data;
    struct BTreeNode* lchild;
    struct BTreeNode* rchild;
    struct BTreeNode* parent;
} BTree;

void inOrderRecursion(BTree *curr, bool outPutNext);
BTree* insertRightNode(BTree *curr, Datatype x);
BTree* insertLeftNode(BTree *curr, Datatype x);
BTree* findNext(BTree* curr);

int main()
{
    /* Construct a binary tree as below:
         A
      B     C
    D     E   F
      G
    */
    BTree *A, *B, *C, *D, *E, *F, *G;

    A = (BTree *)malloc(sizeof(BTree));
    A->data = 'A';
    A->lchild = NULL;
    A->rchild = NULL;
    A->parent = NULL;

    B = insertLeftNode(A, 'B');
    C = insertRightNode(A, 'C');
    D = insertLeftNode(B, 'D');
    G = insertRightNode(D, 'G');
    E = insertLeftNode(C, 'E');
    F = insertRightNode(C, 'F');

    // inOrder
    printf("InOrder:\n");
    inOrderRecursion(A, false);
    printf("\n\n");
    inOrderRecursion(A, true);

    return 0;
}

BTree* findNext(BTree* curr)
{
    BTree *p = curr;

    if (p->rchild) // 如果有右子树，则递归找到右子树最左边的节点
    {
        p = p->rchild;
        while (p->lchild)
        {
            p = p->lchild;
        }

        return p;
    }
    else if (p->parent) // 否则，向其父节点查找
    {
        BTree* parent = p->parent;
        while (parent && parent->rchild == p) // 向上递归找到第一个作为左子树的祖先节点，或者找到根节点的父节点（NULL）
        {
            p = parent;
            parent = p->parent;
        }

        return parent;
    }
    else // 当前节点为根节点，且没有右子树，此时二叉树退化为链表
    {
        return NULL;
    }
}

void inOrderRecursion(BTree *curr, bool outPutNext)
{
    if (curr)
    {
        inOrderRecursion(curr->lchild, outPutNext);
        printf("%c  ", curr->data);
        if (outPutNext)
        {
            BTree* next = findNext(curr);
            if (next)
            {
                printf("->  %c\n", next->data);
            }
            else
            {
                printf("->  NULL\n");
            }
        }
        inOrderRecursion(curr->rchild, outPutNext);
    }
}

BTree* insertLeftNode(BTree *curr, Datatype x)
{
    if (curr == NULL) return NULL;

    BTree *s, *t;

    t = curr->lchild; // 保存原curr所指节点的左子树指针
    s = (BTree*)malloc(sizeof(BTree));
    s->data = x;
    s->lchild = t;
    s->rchild = NULL;
    s->parent = curr;
    curr->lchild = s;

    return s;
}

BTree* insertRightNode(BTree *curr, Datatype x)
{
    if (curr == NULL) return NULL;

    BTree *s, *t;

    t = curr->rchild; // 保存原curr所指节点的右子树指针
    s = (BTree*)malloc(sizeof(BTree));
    s->data = x;
    s->rchild = t;
    s->lchild = NULL;
    s->parent = curr;
    curr->rchild = s;

    return s;
}

//GEMINI-pro DATASET v1.0 Category: Word Frequency Counter ; Style: Dennis Ritchie
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <stdbool.h>

struct Word {
    char* word;
    int count;
};

struct WordList {
    struct Word* words;
    int size;
    int capacity;
};

void init_word_list(struct WordList* wl) {
    wl->words = NULL;
    wl->size = 0;
    wl->capacity = 0;
}

void add_word(struct WordList* wl, char* word) {
    if (wl->size >= wl->capacity) {
        wl->capacity = wl->capacity ? wl->capacity * 2 : 16;
        wl->words = realloc(wl->words, wl->capacity * sizeof(struct Word));
    }

    int i;
    for (i = 0; i < wl->size; i++) {
        if (!strcmp(word, wl->words[i].word)) {
            wl->words[i].count++;
            return;
        }
    }

    wl->words[wl->size].word = strdup(word);
    wl->words[wl->size].count = 1;
    wl->size++;
}

void free_word_list(struct WordList* wl) {
    for (int i = 0; i < wl->size; i++) {
        free(wl->words[i].word);
    }
    free(wl->words);
}

void print_word_list(struct WordList* wl) {
    for (int i = 0; i < wl->size; i++) {
        printf("%s: %d\n", wl->words[i].word, wl->words[i].count);
    }
}

int main(int argc, char** argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    FILE* fp = fopen(argv[1], "r");
    if (fp == NULL) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    struct WordList wl;
    init_word_list(&wl);

    char word[256];
    while (fscanf(fp, "%s", word) != EOF) {
        for (int i = 0; word[i]; i++) {
            word[i] = tolower(word[i]);
        }

        add_word(&wl, word);
    }

    fclose(fp);

    print_word_list(&wl);

    free_word_list(&wl);

    return EXIT_SUCCESS;
}

//Falcon-180B DATASET v1.0 Category: Simple HTTP Proxy ; Style: happy
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_LINE 1024
#define BACKLOG 10

int main(int argc, char *argv[]) {
    int listen_socket, client_socket, bytes_received;
    struct sockaddr_in server_addr, client_addr;
    char buffer[MAX_LINE];

    if (argc!= 3) {
        printf("Usage: %s <IP Address> <Port>\n", argv[0]);
        return 1;
    }

    listen_socket = socket(AF_INET, SOCK_STREAM, 0);

    if (listen_socket == -1) {
        printf("Error creating socket: %s\n", strerror(errno));
        return 1;
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = inet_addr(argv[1]);
    server_addr.sin_port = htons(atoi(argv[2]));

    if (bind(listen_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) == -1) {
        printf("Error binding socket: %s\n", strerror(errno));
        return 1;
    }

    if (listen(listen_socket, BACKLOG) == -1) {
        printf("Error listening on socket: %s\n", strerror(errno));
        return 1;
    }

    printf("Proxy server started on %s:%d\n", argv[1], atoi(argv[2]));

    while (1) {
        client_socket = accept(listen_socket, (struct sockaddr *)&client_addr, sizeof(client_addr));

        if (client_socket == -1) {
            printf("Error accepting connection: %s\n", strerror(errno));
            continue;
        }

        printf("Connection accepted from %s:%d\n", inet_ntoa(client_addr.sin_addr), ntohs(client_addr.sin_port));

        while (1) {
            bytes_received = recv(client_socket, buffer, MAX_LINE, 0);

            if (bytes_received <= 0) {
                printf("Client disconnected\n");
                break;
            }

            send(client_socket, buffer, bytes_received, 0);
        }

        close(client_socket);
    }

    return 0;
}

