#include <stdio.h>
#include <stdbool.h>
#include <stdlib.h>
#include <string.h>
#define MAX_SIZE 100

struct bank_record {
    char name[50];
    char address[100];
    int account_number;
    double balance;
};

struct bank_record records[MAX_SIZE];
int record_count = 0;

void add_record() {
    printf("\nAdding new record\n");
    printf("------------------\n");
    struct bank_record record;
    printf("Enter name: ");
    scanf("%s", record.name);
    printf("Enter address: ");
    scanf("%s", record.address);
    printf("Enter account number: ");
    scanf("%d", &record.account_number);
    printf("Enter balance: ");
    scanf("%lf", &record.balance);
    records[record_count++] = record;
    printf("Record added successfully!\n");
}

void display_records() {
    printf("\nDisplaying all records\n");
    printf("-----------------------\n");
    if (record_count == 0) {
        printf("No records found.\n");
    } else {
        for (int i = 0; i < record_count; i++) {
            struct bank_record record = records[i];
            printf("Name: %s\n", record.name);
            printf("Address: %s\n", record.address);
            printf("Account number: %d\n", record.account_number);
            printf("Balance: $%.2lf\n", record.balance);
            printf("\n");
        }
    }
}

void search_record() {
    printf("\nSearching record\n");
    printf("-----------------\n");
    int account_number;
    printf("Enter account number: ");
    scanf("%d", &account_number);
    bool found_record = false;
    for (int i = 0; i < record_count; i++) {
        struct bank_record record = records[i];
        if (record.account_number == account_number) {
            printf("Name: %s\n", record.name);
            printf("Address: %s\n", record.address);
            printf("Account number: %d\n", record.account_number);
            printf("Balance: $%.2lf\n", record.balance);
            printf("\n");
            found_record = true;
        }
    }
    if (!found_record) {
        printf("Record not found.\n");
    }
}

void update_record() {
    printf("\nUpdating record\n");
    printf("----------------\n");
    int account_number;
    printf("Enter account number: ");
    scanf("%d", &account_number);
    bool found_record = false;
