#include <poll.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <sys/time.h>
#include <sys/types.h>
#include <unistd.h>

#define NUM_SOCKETS 10
#define BUF_SIZE 1024

static int sock[NUM_SOCKETS];
static struct pollfd fds[NUM_SOCKETS];

static void init_sockets()
{
    int i;

    for (i = 0; i < NUM_SOCKETS; i++) {
        sock[i] = socket(AF_INET, SOCK_DGRAM, 0);
        if (sock[i] == -1) {
            perror("socket");
            exit(EXIT_FAILURE);
        }

        fds[i].fd = sock[i];
        fds[i].events = POLLIN;
    }
}

static void close_sockets()
{
    int i;

    for (i = 0; i < NUM_SOCKETS; i++)
        close(sock[i]);
}

static void send_packets()
{
    int i, ret;
    struct sockaddr_in addr;

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr("127.0.0.1");
    addr.sin_port = htons(1234);

    for (i = 0; i < NUM_SOCKETS; i++) {
        ret = sendto(sock[i], "hello", 5, 0, (struct sockaddr *)&addr, sizeof(addr));
        if (ret == -1) {
            perror("sendto");
            exit(EXIT_FAILURE);
        }
    }
}

static void receive_packets()
{
    int i, ret;
    char buf[BUF_SIZE];
    struct sockaddr_in addr;
    socklen_t len = sizeof(addr);

    for (i = 0;; i = (i + 1) % NUM_SOCKETS) {
        ret = poll(&fds[i], 1, -1);
        if (ret == -1) {
            perror("poll");
            exit(EXIT_FAILURE);
        }

        if (fds[i].revents & POLLIN) {
            ret = recvfrom(sock[i], buf, BUF_SIZE, 0, (struct sockaddr *)&addr, &len);
            if (ret == -1) {
                perror("recvfrom");
                exit(EXIT_FAILURE);
            }

            printf("Received packet from %s:%d: %s\n", inet_ntoa(addr.sin_addr), ntohs(addr.sin_port), buf);
        }
    }
}

int main()
{
    init_sockets();

    send_packets();

    receive_packets();

    close_sockets();

    return 0;
}

