#define WIDTH 800
#define HEIGHT 600
#define MAX_ITER 100
#define MAX_COLOR 255

int main() {
    // Set the seed for the random number generator
    srand(time(NULL));

    // Create a 2D array to store the fractal
    int fractal[HEIGHT][WIDTH];

    // Initialize the fractal with random colors
    for (int y = 0; y < HEIGHT; y++) {
        for (int x = 0; x < WIDTH; x++) {
            fractal[y][x] = rand() % MAX_COLOR;
        }
    }

    // Iterate over the fractal and apply the rules
    for (int i = 0; i < MAX_ITER; i++) {
        for (int y = 0; y < HEIGHT; y++) {
            for (int x = 0; x < WIDTH; x++) {
                int color = fractal[y][x];
                int new_color = color;

                // Apply the rules to the current color
                if (color == 0) {
                    new_color = rand() % MAX_COLOR;
                } else if (color == 255) {
                    new_color = rand() % MAX_COLOR;
                } else {
                    new_color = (color + 1) % MAX_COLOR;
                }

                // Update the fractal with the new color
                fractal[y][x] = new_color;
            }
        }
    }

    // Print the fractal to the console
    for (int y = 0; y < HEIGHT; y++) {
        for (int x = 0; x < WIDTH; x++) {
