#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define PORT 8080

struct request {
    char *method;
    char *uri;
    char *version;
    char *headers[5];
    char *body;
};

struct response {
    char *status;
    char *reason;
    char *body;
};

void handle_request(int sock, struct request *req) {
    char *method = req->method;
    char *uri = req->uri;
    char *version = req->version;
    char *headers[5];
    char *body;

    if (strcmp(method, "GET") == 0) {
        if (strcmp(uri, "/") == 0) {
            body = "Welcome to my retro web server!";
        } else {
            body = "I don't know that page!";
        }
    } else if (strcmp(method, "POST") == 0) {
        int len = 0;
        char *data = NULL;

        // Read the request body
        while (1) {
            char c = read(sock, &data[len], 1);
            if (c == '\n') {
                break;
            }
            len++;
        }

        // Print the request body
        printf("Request body: %s\n", data);

        // Send the response
        body = "Thank you for your POST request!";
    } else {
        body = "Unsupported method";
    }

    // Set the response headers
    headers[0] = "Content-Type: text/html";
    headers[1] = "Content-Length: ";
    headers[2] = body;

    // Send the response
    send(sock, body, strlen(body), 0);
}

int main() {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket failed");
        exit(1);
    }

    // Bind the socket to a specific address and port
    struct sockaddr_in server_address = {
        .sin_family = AF_INET,
        .sin_port = htons(PORT),
        .sin_addr.s_addr = INADDR_ANY
    };
    if (bind(sock, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("bind failed");
        exit(1);
    }

    // Listen for incoming connections
    if (listen(sock, 3) < 0) {
        perror("listen failed");
        exit(1);
    }

    struct sockaddr_in client_address;
    socklen_t client_len = sizeof(client_address);
    int client_sock = accept(sock, (struct sockaddr *)&client_address, &client_len);
    if (client_sock < 0) {
        perror("accept failed");
        exit(1);
    }

    // Read the request
    struct request req;
    read(client_sock, &req, sizeof(req));

    // Handle the request
    handle_request(client_sock, &req);

    // Close the socket
    close(client_sock);

    return 0;
}

