#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the size of the grid
#define GRID_SIZE 20

// Define the number of generations
#define GENERATIONS 100

// Define the probability of a cell being alive
#define PROBABILITY_OF_LIFE 0.5

// Create a grid of cells
int grid[GRID_SIZE][GRID_SIZE];

// Initialize the grid with random values
void initialize_grid() {
  for (int i = 0; i < GRID_SIZE; i++) {
    for (int j = 0; j < GRID_SIZE; j++) {
      grid[i][j] = (rand() < RAND_MAX * PROBABILITY_OF_LIFE);
    }
  }
}

// Print the grid to the console
void print_grid() {
  for (int i = 0; i < GRID_SIZE; i++) {
    for (int j = 0; j < GRID_SIZE; j++) {
      printf("%d ", grid[i][j]);
    }
    printf("\n");
  }
}

// Update the grid based on the rules of the Game of Life
void update_grid() {
  int new_grid[GRID_SIZE][GRID_SIZE];

  // Loop through each cell in the grid
  for (int i = 0; i < GRID_SIZE; i++) {
    for (int j = 0; j < GRID_SIZE; j++) {
      // Count the number of living neighbors
      int num_neighbors = 0;
      for (int x = -1; x <= 1; x++) {
        for (int y = -1; y <= 1; y++) {
          if (x == 0 && y == 0) {
            continue;
          }

          int neighbor_x = i + x;
          int neighbor_y = j + y;

          // Wrap around the edges of the grid
          if (neighbor_x < 0) {
            neighbor_x = GRID_SIZE - 1;
          } else if (neighbor_x >= GRID_SIZE) {
            neighbor_x = 0;
          }

          if (neighbor_y < 0) {
            neighbor_y = GRID_SIZE - 1;
          } else if (neighbor_y >= GRID_SIZE) {
            neighbor_y = 0;
          }

          num_neighbors += grid[neighbor_x][neighbor_y];
        }
      }

      // Apply the rules of the Game of Life
      if (grid[i][j] == 1) {
        if (num_neighbors < 2 || num_neighbors > 3) {
          new_grid[i][j] = 0;
        } else {
          new_grid[i][j] = 1;
        }
      } else {
        if (num_neighbors == 3) {
          new_grid[i][j] = 1;
        } else {
          new_grid[i][j] = 0;
        }
      }
    }
  }

  // Copy the new grid over the old grid
  for (int i = 0; i < GRID_SIZE; i++) {
    for (int j = 0; j < GRID_SIZE; j++) {
      grid[i][j] = new_grid[i][j];
    }
  }
}

// Main function
int main() {
  // Seed the random number generator
  srand(time(NULL));

  // Initialize the grid
  initialize_grid();

  // Print the initial grid
  print_grid();

  // Update the grid for a number of generations
  for (int i = 0; i < GENERATIONS; i++) {
    update_grid();

    // Print the grid after each generation
    print_grid();
  }

  return 0;
}

