#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define N 10

int main() {
    int i, j, k;
    char matrix[N][N];
    char inv[N][N];
    int flag = 0;

    // Initialize the matrix
    for (i = 0; i < N; i++) {
        for (j = 0; j < N; j++) {
            matrix[i][j] = i * j % N;
        }
    }

    // Invert the matrix
    for (i = 0; i < N; i++) {
        for (j = 0; j < N; j++) {
            inv[i][j] = 0;
        }
    }

    // Swap rows and columns
    for (i = 0; i < N; i++) {
        for (j = 0; j < N; j++) {
            int temp = matrix[i][j];
            matrix[i][j] = matrix[j][i];
            matrix[j][i] = temp;
        }
    }

    // Now, let's get creative!
    for (i = 0; i < N; i++) {
        for (j = 0; j < N; j++) {
            if (matrix[i][j] == 0) {
                continue;
            }
            for (k = 0; k < N; k++) {
                if (matrix[i][k] == 0) {
                    continue;
                }
                inv[i][j] += matrix[i][k] * matrix[k][j];
            }
        }
    }

    // Print the inverse matrix
    for (i = 0; i < N; i++) {
        for (j = 0; j < N; j++) {
            printf("%d ", inv[i][j]);
        }
        printf("\n");
    }

    return 0;
}

