    struct Guest* newGuest = (struct Guest*)malloc(sizeof(struct Guest));
    strcpy(newGuest->name, name);
    newGuest->room_no = room_no;
    newGuest->next = NULL;

    if (*head == NULL) {
        *head = newGuest;
    } else {
        (*head)->next = newGuest;
    }
