void insertRoom(struct Room** head, int no, int occupancy) {
    struct Room* newRoom = (struct Room*)malloc(sizeof(struct Room));
    newRoom->no = no;
    newRoom->occupancy = occupancy;
    newRoom->next = NULL;

    if (*head == NULL) {
        *head = newRoom;
    } else {
        (*head)->next = newRoom;
    }
}

