                    scanf("%d %d", &r1, &c1);
                    printf("Matrix B dimensions (rows and columns): ");
                    scanf("%d %d", &r2, &c2);

                    if (c1 != r2) {
                        printf("Matrix multiplication not possible. Ensure columns of A = rows of B.\n");
                        break;
                    }

                    int **A = (int **)malloc(r1 * sizeof(int *));
                    int **B = (int **)malloc(r2 * sizeof(int *));
                    for (i = 0; i < r1; i++)
                        A[i] = (int *)malloc(c1 * sizeof(int));
                    for (i = 0; i < r2; i++)
                        B[i] = (int *)malloc(c2 * sizeof(int));

                    // Input for Matrix A
                    printf("Enter elements of Matrix A:\n");
                    for (i = 0; i < r1; i++) {
                        for (j = 0; j < c1; j++) {
                            printf("A[%d][%d]: ", i, j);
                            scanf("%d", &A[i][j]);
                        }
                    }

                    // Input for Matrix B
                    printf("Enter elements of Matrix B:\n");
                    for (i = 0; i < r2; i++) {
                        for (j = 0; j < c2; j++) {
                            printf("B[%d][%d]: ", i, j);
                            scanf("%d", &B[i][j]);
                        }
                    }

                    int result[3][3]; // This will depend on the maximum size

                    // Perform multiplication
                    matrixMultiplication(A, B, result, r1, c1, r2, c2);
                    printf("Resultant Matrix:\n");
                    for (i = 0; i < r1; i++) {
                        for (j = 0; j < c2; j++) {
                            printf("%d ", result[i][j]);
                        }
                        printf("\n");
                    }

                    // Free allocated memory for A and B
                    for (i = 0; i < r1; i++) free(A[i]);
                    for (i = 0; i < r2; i++) free(B[i]);
                    free(A);
                    free(B);
                }
                break;

            case 0:
                printf("Exiting program.\n");
                break;

            default:
                printf("Invalid choice. Please try again.\n");
                break;
        }
    } while (choice != 0);

    return 0;
}

// Function Definitions
int isPrime(int num) {
    if (num <= 1) return 0;
    for (int i = 2; i <= sqrt(num); i++) {
        if (num % i == 0) return 0;
    }
    return 1;
}

void primeFactorization(int num) {
    int count;
    for (int i = 2; i <= num; i++) {
        count = 0;
        while (num % i == 0) {
            num /= i;
            count++;
        }
        if (count > 0) {
            printf("%d^%d ", i, count);
        }
    }
}

double evaluatePolynomial(double *coefficients, int degree, double x) {
    double result = 0;
    for (int i = 0; i <= degree; i++) {
        result += coefficients[i] * pow(x, degree - i);
    }
    return result;
}

void matrixMultiplication(int **A, int **B, int result[][3], int r1, int c1, int r2, int c2) {
    for (int i = 0; i < r1; i++) {
        for (int j = 0; j < c2; j++) {
            result[i][j] = 0;
            for (int k = 0; k < c1; k++) {
                result[i][j] += A[i][k] * B[k][j];
            }
        }
    }
}

