	void SDLGraphics::Start()
	{
		assert(default_window, "No default window was created. Cannot Start.");

		while (!quit) {
			// Give all the subsystems a chance to update...
			for (std::pair<const char *, SubSystem *> pair : subsystems) {
				pair.second->Update();
			}

			for (Window *w : windows) {
				w->Update();
			}
		}

