#include <time.h>

#define MAX_SIZE 10

int main()
{
    int board[MAX_SIZE][MAX_SIZE] = {{0}};
    int player_1_color = 1;
    int player_2_color = 2;
    int current_player = player_1_color;
    int game_over = 0;

    // Seed the random number generator
    srand(time(NULL));

    // Initialize the board
    for (int i = 0; i < MAX_SIZE; i++)
    {
        for (int j = 0; j < MAX_SIZE; j++)
        {
            board[i][j] = 0;
        }
    }

    // Place the initial pieces
    board[5][5] = player_1_color;
    board[5][6] = player_2_color;

    // Game loop
    while (!game_over)
    {
        // Get the player's move
        int move_x, move_y;
        printf("Enter your move (x, y): ");
        scanf("%d %d", &move_x, &move_y);

        // Validate the move
        if (board[move_x][move_y] != 0)
        {
            printf("Invalid move.\n");
            continue;
        }

        // Place the piece
        board[move_x][move_y] = current_player;

        // Check if the game is over
        game_over = check_game_over(board, current_player);

        // Switch players
        current_player = (current_player == player_1_color) ? player_2_color : player_1_color;
    }

    // Game over
    printf("Game over! The winner is: ");
    printf((board[0][0] == current_player) ? "Player 1" : "Player 2");

    return 0;
}

int check_game_over(int **board, int current_player)
{
    // Check if the current player has won
    for (int i = 0; i < MAX_SIZE; i++)
    {
        // Check if the current player has won in a row
        for (int j = 0; j < MAX_SIZE; j++)
        {
            if (board[i][j] == current_player && board[i][j] == board[i][j-1] && board[i][j] == board[i][j-2] && board[i][j] == board[i][j-3])
            {
                return 1;
            }
        }

        // Check if the current player has won in a column
        for (int j = 0; j < MAX_SIZE; j++)
        {
            if (board[j][0] == current_player && board[j][1] == board[j][2] && board[j][3] == board[j][4] && board[j][5] == board[j][6])
            {
                return 1;
            }
        }

        // Check if the current player has won in a diagonal
        if (board[0][0] == current_player && board[1][1] == board[2][2] && board[3][3] == board[4][4] && board[5][5] == board[6][6])
        {
            return 1;
        }
    }

    // The game is not over
    return 0;
}

