#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <sys/wait.h>

#define PORT_RANGE 1024
#define THREAD_COUNT 4

struct host_info {
    int port;
    char *host;
};

void *scan_host(void *arg) {
    struct host_info *host_info = arg;
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket failed");
        return NULL;
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(host_info->port);
    inet_pton(AF_INET, host_info->host, &server_addr.sin_addr);

    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("connect failed");
        close(sock);
        return NULL;
    }

    char buffer[1024];
    recv(sock, buffer, 1024, 0);
    printf("Received packet from %s:%d\n", host_info->host, host_info->port);

    close(sock);
    return NULL;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: %s <host_ip>\n", argv[0]);
        return 1;
    }

    struct host_info *host_infos = calloc(THREAD_COUNT, sizeof(struct host_info));
    if (host_infos == NULL) {
        perror("calloc failed");
        return 1;
    }

    int i;
    for (i = 0; i < THREAD_COUNT; i++) {
        host_infos[i].port = i + 1;
        host_infos[i].host = argv[1];
    }

    pthread_t threads[THREAD_COUNT];
    for (i = 0; i < THREAD_COUNT; i++) {
        pthread_create(&threads[i], NULL, scan_host, &host_infos[i]);
    }

    for (i = 0; i < THREAD_COUNT; i++) {
        pthread_join(threads[i], NULL);
    }

    free(host_infos);
    return 0;
}

