} Enemy;

void draw_player(Player *player) {
    printf("Player: (%d, %d) Score: %d\n", player->x, player->y, player->score);
}

void draw_enemy(Enemy *enemy) {
    printf("Enemy: (%d, %d) Score: %d\n", enemy->x, enemy->y, enemy->score);
}

void update_player(Player *player, int x, int y) {
    player->x = x;
    player->y = y;
}

void update_enemy(Enemy *enemy, int x, int y) {
    enemy->x = x;
    enemy->y = y;
}

void move_player(Player *player, int direction) {
    switch (direction) {
        case 1:
            player->y++;
            break;
        case 2:
            player->y--;
            break;
        case 3:
            player->x++;
            break;
        case 4:
            player->x--;
            break;
    }
