    for (int i = 0; i < 16; i++) {
        w[i] = be32toh(w[i]);
    }
    for (int i = 16; i < 64; i++) {
        w[i] = SHA256_SIGMA_1(w[i - 2]) + w[i - 7] + SHA256_SIGMA_0(w[i - 15]) + w[i - 16];
    }

