/* A C Networking Example Program in Donald Knuth Style */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <sys/socket.h>

#define PORT 8080

/* This function will set up a TCP server on the specified port. */
int setup_server(int port) {
  int sockfd;
  struct sockaddr_in servaddr;

  /* Create a TCP socket. */
  sockfd = socket(AF_INET, SOCK_STREAM, 0);
  if (sockfd == -1) {
    perror("socket");
    exit(EXIT_FAILURE);
  }

  /* Set up the server address. */
  memset(&servaddr, 0, sizeof(servaddr));
  servaddr.sin_family = AF_INET;
  servaddr.sin_addr.s_addr = htonl(INADDR_ANY);
  servaddr.sin_port = htons(port);

  /* Bind the socket to the server address. */
  if (bind(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) == -1) {
    perror("bind");
    exit(EXIT_FAILURE);
  }

  /* Listen for incoming connections. */
  if (listen(sockfd, 5) == -1) {
    perror("listen");
    exit(EXIT_FAILURE);
  }

  return sockfd;
}

/* This function will handle a client request. */
void handle_client(int sockfd) {
  int n;
  char buf[1024];

  /* Read the client's request. */
  n = read(sockfd, buf, sizeof(buf));
  if (n == -1) {
    perror("read");
    exit(EXIT_FAILURE);
  }

  /* Process the client's request. */
  buf[n] = '\0';
  printf("Received: %s", buf);

  /* Send a response to the client. */
  n = write(sockfd, "Hello, world!\n", strlen("Hello, world!\n"));
  if (n == -1) {
    perror("write");
    exit(EXIT_FAILURE);
  }

  /* Close the connection with the client. */
  close(sockfd);
}

int main() {
  int sockfd;

  /* Set up the server. */
  sockfd = setup_server(PORT);

  /* Handle client requests. */
  while (1) {
    int newsockfd;
    struct sockaddr_in cliaddr;
    socklen_t clilen;

    /* Accept a new connection. */
    newsockfd = accept(sockfd, (struct sockaddr *)&cliaddr, &clilen);
    if (newsockfd == -1) {
      perror("accept");
      exit(EXIT_FAILURE);
    }

    /* Handle the client request. */
    handle_client(newsockfd);
  }

  /* Close the server. */
  close(sockfd);

  return 0;
}

