#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>

#define N_BODIES 5
#define PI M_PI

typedef struct {
    double x, y, vx, vy, mass;
} body;

body solar_system[N_BODIES] = {
    {0, 0, 0, 0, 1.989e30}, // Sun
    {7.233e10, 0, 0, 2.978e4, 5.972e24}, // Mercury
    {0, 0, 5.426e3, 0, 7.348e22}, // Venus
    {0, 0, -3.547e3, 0, 4.869e24}, // Earth
    {1.496e11, 0, 1.054e3, 1.055e3, 1.000e27} // Mars
};

double force(double x, double y, double m1, double m2, double d) {
    double G = 6.673e-11;
    return G * m1 * m2 / pow(d, 2);
}

void update_velocity(body *b) {
    body *i;
    for (i = solar_system; i < solar_system + N_BODIES; i++) {
        if (i == b) continue;

        double dx = i->x - b->x;
        double dy = i->y - b->y;
        double d = sqrt(dx * dx + dy * dy);

        double fx = force(b->x, b->y, b->mass, i->mass, d) * (i->x - b->x) / d;
        double fy = force(b->x, b->y, b->mass, i->mass, d) * (i->y - b->y) / d;

        b->vx += fx;
        b->vy += fy;
    }
}

void update_position(body *b) {
    b->x += b->vx;
    b->y += b->vy;
}

void print_system() {
    int i;
    for (i = 0; i < N_BODIES; i++) {
        printf("Body %d: (%.2f, %.2f), vx = %.2f, vy = %.2f\n", i + 1, solar_system[i].x, solar_system[i].y, solar_system[i].vx, solar_system[i].vy);
    }
}

int main() {
    srand(time(NULL));

    for (int day = 0; day < 365; day++) {
        for (int i = 0; i < N_BODIES; i++) {
            update_velocity(&solar_system[i]);
            update_position(&solar_system[i]);
        }
    }

    print_system();

    return 0;
}

