/*
 * C Resume Parsing System Example Program
 *
 * This program takes a resume as input and parses it to extract information such as name, contact information,
 * education, work experience, and skills.
 *
 * The program uses a simple state machine to parse the resume and extract information.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the states of the state machine
#define STATE_INITIAL 0
#define STATE_NAME 1
#define STATE_CONTACT_INFO 2
#define STATE_EDUCATION 3
#define STATE_WORK_EXPERIENCE 4
#define STATE_SKILLS 5

// Define the structure to store the extracted information
typedef struct {
    char name[100];
    char contact_info[100];
    char education[100];
    char work_experience[100];
    char skills[100];
} ResumeInfo;

// Define the function to parse the resume
void parse_resume(char *resume, ResumeInfo *info) {
    // Initialize the state machine
    int state = STATE_INITIAL;

    // Loop through each line of the resume
    while (*resume) {
        // Check the current state and perform the appropriate action
        switch (state) {
            case STATE_INITIAL:
                if (strstr(resume, "Name:") != NULL) {
                    state = STATE_NAME;
                } else if (strstr(resume, "Contact Information:") != NULL) {
                    state = STATE_CONTACT_INFO;
                } else if (strstr(resume, "Education:") != NULL) {
                    state = STATE_EDUCATION;
                } else if (strstr(resume, "Work Experience:") != NULL) {
                    state = STATE_WORK_EXPERIENCE;
                } else if (strstr(resume, "Skills:") != NULL) {
                    state = STATE_SKILLS;
                }
                break;
            case STATE_NAME:
                // Extract the name from the resume
                sscanf(resume, "Name: %s", info->name);
                state = STATE_CONTACT_INFO;
                break;
            case STATE_CONTACT_INFO:
                // Extract the contact information from the resume
                sscanf(resume, "Contact Information: %s", info->contact_info);
                state = STATE_EDUCATION;
                break;
            case STATE_EDUCATION:
                // Extract the education information from the resume
                sscanf(resume, "Education: %s", info->education);
                state = STATE_WORK_EXPERIENCE;
                break;
            case STATE_WORK_EXPERIENCE:
                // Extract the work experience information from the resume
                sscanf(resume, "Work Experience: %s", info->work_experience);
                state = STATE_SKILLS;
                break;
            case STATE_SKILLS:
                // Extract the skills information from the resume
                sscanf(resume, "Skills: %s", info->skills);
                state = STATE_INITIAL;
                break;
        }

        // Move to the next line of the resume
        resume = strchr(resume, '\n');
        if (resume != NULL) {
            resume++;
        }
    }
}

// Test the program
int main() {
    // Define the resume
    char resume[] = "Name: John Doe\nContact Information: johndoe@example.com\nEducation: Bachelor's Degree\nWork Experience: 5 years\nSkills: C, C++, Java";

    // Define the structure to store the extracted information
    ResumeInfo info;

    // Parse the resume
    parse_resume(resume, &info);

    // Print the extracted information
    printf("Name: %s\n", info.name);
    printf("Contact Information: %s\n", info.contact_info);
    printf("Education: %s\n", info.education);
    printf("Work Experience: %s\n", info.work_experience);
    printf("Skills: %s\n", info.skills);

    return 0;
}

