//MISTRAL-7B DATASET v1.0 Category: Bucket Sort Implementation ; Style: random
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define BUCKET_COUNT 10

typedef struct {
    int index;
    char data[50];
} BucketElement;

void randomize(int *arr, int size) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        arr[i] = rand() % 100;
        sprintf(arr[i], "%d", arr[i]);
    }
}

int hashFunction(char *str) {
    int hash = 0;
    for (int i = 0; str[i] != '\0'; i++) {
        hash += str[i];
    }
    return hash % BUCKET_COUNT;
}

void bucketSort(char **arr, int size) {
    BucketElement *bucket[BUCKET_COUNT] = {0};

    for (int i = 0; i < BUCKET_COUNT; i++) {
        bucket[i] = (BucketElement *)calloc(sizeof(BucketElement), 10);
    }

    for (int i = 0; i < size; i++) {
        int index = hashFunction(arr[i]);
        bucket[index]->index = i;
        strcpy(bucket[index]->data, arr[i]);
    }

    for (int i = 0; i < BUCKET_COUNT; i++) {
        for (int j = 0; j < 10; j++) {
            int index = bucket[i][j].index;
            char *temp = arr[index];
            strcpy(arr[index], arr[i + j]);
            strcpy(arr[i + j], temp);
        }
        free(bucket[i]);
    }

    for (int i = 0; i < BUCKET_COUNT; i++) {
        free(bucket[i]);
    }
}

int main() {
    int size = 20;
    char *arr[size];

    randomize(arr, size);

    clock_t start = clock();
    bucketSort(arr, size);
    clock_t end = clock();

    printf("Sorted Array:\n");
    for (int i = 0; i < size; i++) {
        printf("%s\n", arr[i]);
    }

    printf("Time taken by sorting: %f seconds\n", (float)(end - start) / CLOCKS_PER_SEC);

    return 0;
}

