{
    int donvi, tam = n;
    int sodaonguoc = 0;
    while(tam != 0)
    {
        donvi = tam % 10;
        sodaonguoc = sodaonguoc * 10 + donvi;
        tam /= 10;
    }
    if(sodaonguoc == n)
    {
        return 1;
    }
    return 0;
