#define MAX_LINE_SIZE 1024

typedef struct {
    char *filename;
    FILE *fp;
    int num_lines;
    char **lines;
} File;

File *file_open(char *filename) {
    File *f = malloc(sizeof(File));
    f->filename = strdup(filename);
    f->fp = fopen(filename, "r");
    if (f->fp == NULL) {
        fprintf(stderr, "Error: Could not open file %s\n", filename);
        exit(1);
    }
    f->num_lines = 0;
    f->lines = NULL;
    return f;
}

void file_close(File *f) {
    if (f->fp!= NULL) {
        fclose(f->fp);
    }
    free(f->filename);
    for (int i = 0; i < f->num_lines; i++) {
        free(f->lines[i]);
    }
    free(f->lines);
    free(f);
}

void file_add_line(File *f, char *line) {
    f->lines = realloc(f->lines, sizeof(char *) * (f->num_lines + 1));
    f->lines[f->num_lines] = strdup(line);
    f->num_lines++;
}

int main() {
    char filename[MAX_LINE_SIZE];
    printf("Enter a filename: ");
    fgets(filename, MAX_LINE_SIZE, stdin);
    filename[strcspn(filename, "\n")] = '\0';

    File *f = file_open(filename);

    char line[MAX_LINE_SIZE];
