void encrypt(int plaintext[SIZE][SIZE], int key[SIZE][SIZE], int ciphertext[SIZE][SIZE]) {
    for (int i = 0; i < SIZE; i++) {
        for (int j = 0; j < SIZE; j++) {
            ciphertext[i][j] = plaintext[i][j] ^ key[i][j];
        }
    }
}

void decrypt(int ciphertext[SIZE][SIZE], int key[SIZE][SIZE], int plaintext[SIZE][SIZE]) {
    for (int i = 0; i < SIZE; i++) {
        for (int j = 0; j < SIZE; j++) {
            plaintext[i][j] = ciphertext[i][j] ^ key[i][j];
        }
    }
}

