    // Shuffle the key
    for (int i = 1; i < MAX_KEY_SIZE; i++) {
        int j = rand() % (i + 1);
        char temp = message->key[i];
        message->key[i] = message->key[j];
        message->key[j] = temp;
    }
}

// Function to decrypt the message
void decrypt(message_t *message) {
    // Swap the key and message
    char temp = message->key[0];
    message->key[0] = message->message[0];
    message->message[0] = temp;

    // Shuffle the key
    for (int i = 1; i < MAX_KEY_SIZE; i++) {
        int j = rand() % (i + 1);
        char temp = message->key[i];
        message->key[i] = message->key[j];
        message->key[j] = temp;
    }

    // Decrypt the message
    for (int i = 0; i < strlen(message->message); i++) {
        char current_char = message->message[i];
        char decrypted_char = (current_char - (rand() % 26)) % 26;
        message->message[i] = decrypted_char;
    }
}

int main() {
    message_t message;
    gets(message.message);

    // Encrypt the message
    encrypt(&message);

    // Decrypt the message
    decrypt(&message);

    // Print the original and decrypted messages
    printf("Original message: %s\n", message.message);
    printf("Decrypted message: %s\n", message.message);

    return 0;
}

