struct Roots
{
	double alpha;
	double beta;
};

/*
* Solves a quadratic equation of the form
* (a * x ^ 2 + b * x + c) = 0
* alpha = -b + sqrt(b ^ 2 - 4 * a * c) / 2 * a
* beta = -b - sqrt(b ^ 2 - 4 * a * c) / 2 * a
*/
Roots Quadratic(double a, double b, double c)
{
	Roots roots;
	double d = sqrt(pow(b, 2) - 4 * a * c);
	if ( d >= 0 ) { // Real roots
		roots.alpha = ( -b + d ) / ( 2 * a );
		roots.beta = ( -b - d ) / ( 2 * a );
	}
	return roots;
}

int main()
{
