#define NUM_BINGO_COLUMNS 5
#define NUM_BINGO_ROWS 5

typedef struct BingoCard {
    int numbers[NUM_BINGO_ROWS][NUM_BINGO_COLUMNS];
    int winning_row;
    int winning_column;
} BingoCard;

void initializeBingoCard(BingoCard *card) {
    for (int r = 0; r < NUM_BINGO_ROWS; r++) {
        for (int c = 0; c < NUM_BINGO_COLUMNS; c++) {
            card->numbers[r][c] = -1;
        }
    }

    card->winning_row = -1;
    card->winning_column = -1;
}

void generateBingoNumbers(BingoCard *card) {
    for (int r = 0; r < NUM_BINGO_ROWS; r++) {
        for (int c = 0; c < NUM_BINGO_COLUMNS; c++) {
            card->numbers[r][c] = rand() % 90 + 1;
        }
    }
}

void checkBingo(BingoCard *card) {
    // Check if the card has won a row
    for (int r = 0; r < NUM_BINGO_ROWS; r++) {
        int is_winner = 1;
        for (int c = 0; c < NUM_BINGO_COLUMNS; c++) {
            if (card->numbers[r][c] != -1) {
                is_winner = 0;
            }
        }

        if (is_winner) {
            card->winning_row = r;
            break;
        }
    }

    // Check if the card has won a column
    for (int c = 0; c < NUM_BINGO_COLUMNS; c++) {
        int is_winner = 1;
        for (int r = 0; r < NUM_BINGO_ROWS; r++) {
            if (card->numbers[r][c] != -1) {
                is_winner = 0;
            }
        }

        if (is_winner) {
            card->winning_column = c;
            break;
        }
    }

    // If the card has won neither a row nor a column, it has won the whole game
    if (card->winning_row == -1 && card->winning_column == -1) {
        card->winning_row = NUM_BINGO_ROWS;
    }
}

int main() {
    BingoCard card;
    initializeBingoCard(&card);
    generateBingoNumbers(&card);
    checkBingo(&card);

    if (card.winning_row == NUM_BINGO_ROWS) {
        printf("Congratulations! You have won the game!\n");
    } else {
        printf("Sorry, you have not won the game.\n");
    }

    return 0;
}

