    fin >> m >> n;

    for (int i = 0; i < m; i++) {
        vector<unsigned char> v;
        bool flag = false;

        for (int j = 0; j < n; j++) {
            char c; fin >> c;
            int x = c == 'T' ? 1 : 0;

            if (j == 0 && x) flag = true;

            if (flag)
                v.push_back(!x);
            else
                v.push_back(x);
        }

        mat.push_back(v);
    }

    solve(mat);
}

