char maze[MAZE_ROWS][MAZE_COLS];
char puzzle[10];

void init_maze() {
    int i, j;

    for (i = 0; i < MAZE_ROWS; i++) {
        for (j = 0; j < MAZE_COLS; j++) {
            maze[i][j] = ' ';
        }
    }

    for (i = 0; i < STEPS; i++) {
        int step = i % 2 == 0 ? 1 : -1;
        for (j = 0; j < MAZE_COLS; j++) {
            if (maze[i][j] == ' ' && rand() % 2 == 0) {
                maze[i][j] = 'X';
            }
        }
    }
}

void print_maze() {
    int i, j;

    for (i = 0; i < MAZE_ROWS; i++) {
        for (j = 0; j < MAZE_COLS; j++) {
            printf("%c", maze[i][j]);
        }
        printf("\n");
    }
}

void move_north() {
    current_node->y -= 1;
    if (current_node->y < 0) {
        current_node->y = 0;
    }
}

void move_south() {
    current_node->y += 1;
    if (current_node->y >= MAZE_ROWS) {
        current_node->y = MAZE_ROWS - 1;
    }
}

void move_east() {
    current_node->x += 1;
    if (current_node->x >= MAZE_COLS) {
        current_node->x = 0;
    }
}

void move_west() {
    current_node->x -= 1;
    if (current_node->x < 0) {
        current_node->x = MAZE_COLS - 1;
    }
}

void solve_puzzle() {
    int i, j;

    for (i = 0; i < 10; i++) {
        for (j = 0; j < 10; j++) {
            if (maze[i][j] == 'X') {
                puzzle[i * 10 + j] = 'A' + (j % 2 == 0 ? 1 : 0);
            }
        }
    }
}

