#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_LENGTH 100

// Function to convert characters to lowercase and remove non-alphanumeric characters
void cleanInput(char *source, char *dest) {
    int j = 0;
    for (int i = 0; source[i]; i++) {
        if (isalnum(source[i])) {
            dest[j++] = tolower(source[i]);
        }
    }
    dest[j] = '\0'; // Null terminate the cleaned string
}

// Function to check if the cleaned string is a palindrome
int isPalindrome(char *str) {
    int length = strlen(str);
    for (int i = 0; i < length / 2; i++) {
        if (str[i] != str[length - i - 1]) {
            return 0; // Not a palindrome
        }
    }
    return 1; // It's a palindrome
}

// Function to print a cheerful message
void cheerfulMessage(int result) {
    if (result) {
        printf("\n🎉 Hooray! You've found a palindrome! 🥳\n");
    } else {
        printf("\n😢 Oh no! That's not a palindrome. Keep trying! 🌟\n");
    }
}

