#define MAX_NAME_LENGTH 32
#define MAX_SECTOR_SIZE 10
#define MAX_SECTORS 100

typedef struct {
  char name[MAX_NAME_LENGTH];
  int x, y;
  int resources;
} Sector;

typedef struct {
  char name[MAX_NAME_LENGTH];
  int num_sectors;
  Sector sectors[MAX_SECTORS];
} System;

typedef struct {
  char name[MAX_NAME_LENGTH];
  int num_systems;
  System systems[MAX_SECTORS];
} Galaxy;

// Create a new galaxy
Galaxy *create_galaxy() {
  Galaxy *galaxy = malloc(sizeof(Galaxy));
  strcpy(galaxy->name, "Milky Way");
  galaxy->num_systems = 0;

  return galaxy;
}

// Create a new system
System *create_system(char *name) {
  System *system = malloc(sizeof(System));
  strcpy(system->name, name);
  system->num_sectors = 0;

  return system;
}

// Create a new sector
Sector *create_sector(char *name, int x, int y, int resources) {
  Sector *sector = malloc(sizeof(Sector));
  strcpy(sector->name, name);
  sector->x = x;
  sector->y = y;
  sector->resources = resources;

  return sector;
}

// Add a system to a galaxy
void add_system_to_galaxy(Galaxy *galaxy, System *system) {
  galaxy->systems[galaxy->num_systems++] = *system;
}

// Add a sector to a system
void add_sector_to_system(System *system, Sector *sector) {
  system->sectors[system->num_sectors++] = *sector;
}

// Generate a random galaxy
Galaxy *generate_galaxy() {
  Galaxy *galaxy = create_galaxy();

  // Generate a random number of systems
  int num_systems = rand() % MAX_SECTORS + 1;

  // Generate each system
  for (int i = 0; i < num_systems; i++) {
    char name[MAX_NAME_LENGTH];
    sprintf(name, "System %d", i);
    System *system = create_system(name);

    // Generate a random number of sectors
    int num_sectors = rand() % MAX_SECTOR_SIZE + 1;

    // Generate each sector
    for (int j = 0; j < num_sectors; j++) {
      char name[MAX_NAME_LENGTH];
      sprintf(name, "Sector %d", j);
      int x = rand() % MAX_SECTOR_SIZE;
      int y = rand() % MAX_SECTOR_SIZE;
      int resources = rand() % 100;
      Sector *sector = create_sector(name, x, y, resources);

      // Add the sector to the system
      add_sector_to_system(system, sector);
    }

    // Add the system to the galaxy
    add_system_to_galaxy(galaxy, system);
  }

  return galaxy;
}

// Print a galaxy
void print_galaxy(Galaxy *galaxy) {
  printf("Galaxy: %s\n", galaxy->name);
  for (int i = 0; i < galaxy->num_systems; i++) {
    System *system = &galaxy->systems[i];
    printf("  System: %s\n", system->name);
    for (int j = 0; j < system->num_sectors; j++) {
      Sector *sector = &system->sectors[j];
      printf("    Sector: %s (%d, %d) - Resources: %d\n", sector->name, sector->x, sector->y, sector->resources);
    }
  }
}

int main() {
  // Seed the random number generator
  srand(time(NULL));

  // Generate a random galaxy
  Galaxy *galaxy = generate_galaxy();

  // Print the galaxy
  print_galaxy(galaxy);

  return 0;
}

