// Function to generate a random curiosity name
void generate_name(struct Curiosity *curiosity) {
    int i, j;
    for (i = 0; i < 20; i++) {
        // Generate a random letter
        char letter = 'a' + (rand() % 26);
        // Check if the letter is already in the name
        for (j = 0; j < i; j++) {
            if (curiosity->name[j] == letter) {
                // If it is, pick a new letter
                letter = 'a' + (rand() % 26);
            }
        }
