#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define MAX_GENOME_LENGTH 1000
#define MAX_GENOMES 100
#define NUCLEOTIDES "ACGT"
#define NUM_MUTATIONS 5

typedef struct {
    char id[10];
    char sequence[MAX_GENOME_LENGTH + 1];
} Genome;

void generate_random_sequence(char *sequence, int length) {
    for (int i = 0; i < length; i++) {
        sequence[i] = NUCLEOTIDES[rand() % 4];
    }
    sequence[length] = '\0'; // Null-terminate the string
}

void mutate_sequence(char *sequence, int mutations) {
    for (int i = 0; i < mutations; i++) {
        int pos = rand() % strlen(sequence);
        char original_nucleotide = sequence[pos];
        char new_nucleotide;

        // Generate a new nucleotide different from the original
        do {
            new_nucleotide = NUCLEOTIDES[rand() % 4];
        } while (new_nucleotide == original_nucleotide);

        sequence[pos] = new_nucleotide; // Apply mutation
    }
}

void print_genome_info(const Genome *genome) {
    printf("Genome ID: %s\n", genome->id);
    printf("Sequence: %s\n", genome->sequence);
    printf("Length: %lu\n", strlen(genome->sequence));
    printf("A: %d, C: %d, G: %d, T: %d\n",
           (int)(strlen(genome->sequence) - strlen(strchr(genome->sequence, 'C'))),
           (int)(strlen(genome->sequence) - strlen(strchr(genome->sequence, 'A'))),
           (int)(strlen(genome->sequence) - strlen(strchr(genome->sequence, 'G'))),
           (int)(strlen(genome->sequence) - strlen(strchr(genome->sequence, 'T'))));
}

int main() {
    srand(time(NULL)); // Seed the random generator

    Genome genomes[MAX_GENOMES];
    int num_genomes = 10; // Set the number of genomes to generate

    // Generate genomes
    for (int i = 0; i < num_genomes; i++) {
        snprintf(genomes[i].id, sizeof(genomes[i].id), "Genome%d", i + 1);
        generate_random_sequence(genomes[i].sequence, rand() % MAX_GENOME_LENGTH + 1);
        mutate_sequence(genomes[i].sequence, NUM_MUTATIONS);
    }

    // Print information of all genomes
    printf("Generated Genome Sequences:\n");
    for (int i = 0; i < num_genomes; i++) {
        print_genome_info(&genomes[i]);
        printf("----------------------\n");
    }

    return 0;
}

