    printf("Graph with %d vertices and %d edges:\n", graph->vertex_count, graph->edge_count);
    for (int i = 0; i < graph->vertex_count; i++) {
        printf("%d: ", i);
        for (int j = 0; j < graph->vertex_count; j++) {
            if (graph->edges[i][j] == 1) {
                printf("%d ", j);
            }
        }
        printf("\n");
    }
}

