#include <string.h>
#include <pthread.h>

#define MAX_THREADS 10
#define MAX_STRING_LENGTH 100

char strings[MAX_THREADS][MAX_STRING_LENGTH];
int string_lengths[MAX_THREADS];

void *string_manipulation(void *arg) {
    int thread_id = *(int *) arg;
    char *string = &strings[thread_id][0];
    int length = string_lengths[thread_id];

    char reversed[MAX_STRING_LENGTH];
    strcpy(reversed, string);
    char *p = reversed;
    char *q = reversed + length - 1;
    while (p < q) {
        char temp = *p;
        *p = *q;
        *q = temp;
        p++;
        q--;
    }

    printf("Thread %d reversed string: %s\n", thread_id, reversed);

    return NULL;
}

int main() {
    pthread_t threads[MAX_THREADS];
    int thread_ids[MAX_THREADS];

    for (int i = 0; i < MAX_THREADS; i++) {
        string_lengths[i] = rand() % MAX_STRING_LENGTH;
        strcpy(strings[i], "Thread ");
