        while (j < string_lengths[i]) {
            strings[i][j] = rand() % 26 + 'a';
            j++;
        }
        strings[i][j] = '\0';

        pthread_create(&threads[i], NULL, string_manipulation, (void *) &i);
        thread_ids[i] = i;
    }

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
