void gen_SS(list<int> Q)

{

    if(Q.empty())

    {

        for(int i = 0; i < k; i++)

        {

            for(int j = 0; j < L[i]; j++)

            {

                printf("%d ", SS[i][j]);

            }

            putchar('\n');

        }

        cnt++;

        putchar('\n');

        return;

    }

    int x = Q.front();

    Q.pop_front();

    for(int i = 0; i < k; i++)

    {

        if(SS[i][L[i] - 1] < x)

        {

            SS[i][L[i]++] = x;

            gen_SS(Q);

            L[i]--;

        }

    }

}



void gen_C(int len, int prev)

{

    if(len == k)

    {

        for(int i = 0; i < k; i++)

        {

            L[i] = 0;

            SS[i][L[i]++] = C[i];

        }

        list<int> Q;

