                Q.push_back(i);

            }

        }

        gen_SS(Q);

    }

    for(int i = prev + 1; i <= n; i++)

    {

        C[len] = i;

        used[i] = true;

        gen_C(len + 1, i);

        used[i] = false;

    }

}



