#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define NUM_THREADS 5
#define MAX_COUNT 10

// A structure to hold thread data
typedef struct {
    int thread_id;
    int count;
} thread_data_t;

// Function prototypes
void *counting_function(void *thread_data);
void generate_random_numbers(int *numbers, int size);
void print_numbers_sorted(int *numbers, int size);

// Main function
int main() {
    pthread_t threads[NUM_THREADS];
    thread_data_t thread_data[NUM_THREADS];
    int i;

    // Seed the random number generator
    srand(time(NULL));

    // Create threads
    for (i = 0; i < NUM_THREADS; ++i) {
        thread_data[i].thread_id = i + 1;
        thread_data[i].count = rand() % MAX_COUNT + 1; // Random count from 1 to MAX_COUNT

        printf("Creating thread %d with count %d\n", thread_data[i].thread_id, thread_data[i].count);
        pthread_create(&threads[i], NULL, counting_function, (void *)&thread_data[i]);
    }

    // Wait for threads to complete
    for (i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("All threads completed. Exiting main.\n");
    return 0;
}

// Function to be executed by each thread
void *counting_function(void *thread_data) {
    thread_data_t *data = (thread_data_t *)thread_data;
    int i;

    // Allocate an array for counting
    int *numbers = (int *)malloc(data->count * sizeof(int));
    if (numbers == NULL) {
        fprintf(stderr, "Failed to allocate memory for thread %d\n", data->thread_id);
        pthread_exit(NULL);
    }

    // Generate random numbers
    generate_random_numbers(numbers, data->count);
    printf("Thread %d generated numbers: ", data->thread_id);
    for (i = 0; i < data->count; ++i) {
        printf("%d ", numbers[i]);
    }
    printf("\n");

    // Sort and print numbers
    print_numbers_sorted(numbers, data->count);
    free(numbers);

    pthread_exit(NULL);
}

// Function to generate random numbers
void generate_random_numbers(int *numbers, int size) {
    for (int i = 0; i < size; i++) {
        numbers[i] = rand() % 100; // Random numbers between 0 and 99
    }
}

// Function to print numbers in sorted order
void print_numbers_sorted(int *numbers, int size) {
    // Simple bubble sort
    for (int i = 0; i < size - 1; i++) {
        for (int j = 0; j < size - i - 1; j++) {
            if (numbers[j] > numbers[j + 1]) {
                // Swap
                int temp = numbers[j];
                numbers[j] = numbers[j + 1];
                numbers[j + 1] = temp;
            }
        }
    }

    printf("Sorted numbers: ");
    for (int i = 0; i < size; i++) {
        printf("%d ", numbers[i]);
    }
    printf("\n");
}

