void search(int **graph, int n, int k, int *found)
{
    int i, j, visited = 0;
    visited = graph[k][0] & 1;
    if(!visited)
    {
        visited = graph[k][0] |= 1;
        for(i = 0; i < n; i++)
        {
            if(graph[k][i] && graph[i][0] & 0)
            {
                search(graph, n, i, found);
            }
        }
        if(visited)
        {
            *found = 1;
        }
    }
}

