}

//MISTRAL-7B DATASET v1.0 Category: Planet Gravity Simulation ; Style: recursive
#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#define MAX_BODIES 100

typedef struct {
    double x, y, mass;
} Body;

Body bodies[MAX_BODIES];
double G = 6.67430e-11; // Gravitational constant
int num_bodies = 0;

void add_body(double x, double y, double m) {
    if (num_bodies >= MAX_BODIES) {
        fprintf(stderr, "Too many bodies\n");
        return;
    }
    bodies[num_bodies].x = x;
    bodies[num_bodies].y = y;
    bodies[num_bodies].mass = m;
    num_bodies++;
}

void gravity(int i, int n) {
    double total_x = 0, total_y = 0, dx, dy;
    for (int j = 0; j < n; j++) {
        if (i != j) {
            dx = bodies[i].x - bodies[j].x;
            dy = bodies[i].y - bodies[j].y;
            double dist_sq = dx * dx + dy * dy;
            double force = G * bodies[i].mass * bodies[j].mass / dist_sq;
            total_x += force * dx;
            total_y += force * dy;
        }
    }
    bodies[i].x += total_x / bodies[i].mass;
    bodies[i].y += total_y / bodies[i].mass;
}

void simulate(int n) {
    if (n <= 0) return;
    gravity(n - 1, n);
    gravity(n - 1, n); // recursively calculate forces for each pair of bodies
    gravity(n - 1, n);
    simulate(n - 1); // recursively simulate motion for n-1 bodies
}

int main() {
    add_body(0, 0, 10);
    add_body(5, 5, 5);
    add_body(-5, 5, 3);
    simulate(num_bodies);
    for (int i = 0; i < num_bodies; i++) {
        printf("Body %d: x=%.2f, y=%.2f\n", i, bodies[i].x, bodies[i].y);
    }
    return 0;
}

