{
    for(int i = 0; i < n; i++)
    {
        printf("%4d", a[i]);
    }
}

int KiemTraChinhPhuong(int n)
{
    return (sqrt((float)n) == (int)sqrt((float)n));
}
void LietKeViTriChinhPhuong(int a[], int n)
{
    int flag = 0;
    for(int i = 0; i < n; i++)
    {
        if(KiemTraChinhPhuong(a[i]) == 1)
        {
            flag = 1;
            printf("%4d", i);
        }
    }
    if(flag == 0)
    {
        printf("\nKhong co so chinh phuong");
    }
}
