bool is_subset(string a, string b){
    if (a.size() < b.size())
        return false;
    else{
        int check_b=0;
        for (int i=0; i<a.size();i++){
            if(a[i]==b[check_b]){
                check_b++;
                if (check_b == b.size())
                    return true;
            }
        }
    }
    return false;
}

