#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <netdb.h>
#include <string.h>

#define PORT 8080

int main(int argc, char *argv[]) {
    if (argc!= 2) {
        fprintf(stderr, "Usage: %s <host>\n", argv[0]);
        exit(1);
    }

    struct sockaddr_in server;
    struct hostent *server_addr;

    if ((server_addr = gethostbyname(argv[1])) == NULL) {
        fprintf(stderr, "Error: Hostname not found\n");
        exit(1);
    }

    server.sin_family = AF_INET;
    server.sin_port = htons(PORT);
    memcpy((char*)&server.sin_addr.s_addr, server_addr->h_addr, server_addr->h_length);

    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Error: Failed to create socket");
        exit(1);
    }

    if (connect(sockfd, (struct sockaddr*)&server, sizeof(server)) < 0) {
        perror("Error: Failed to connect");
        exit(1);
    }

    char buf[1024];
    while (1) {
        printf("Enter message: ");
        fgets(buf, sizeof(buf), stdin);

        send(sockfd, buf, strlen(buf), 0);
        if (recv(sockfd, buf, sizeof(buf), 0) < 0) {
            perror("Error: Failed to receive");
            exit(1);
        }

        printf("Received: %s\n", buf);
    }

    close(sockfd);
    return 0;
}

//GPT-4o-mini DATASET v1.0 Category: Task Scheduler ; Style: secure
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>

#define MAX_TASKS 10
#define MAX_DESC_LENGTH 100
#define SCHEDULE_INTERVAL 1

typedef struct {
    char description[MAX_DESC_LENGTH];
    time_t trigger_time;
    pthread_t thread_id;
    int is_active;
} Task;

Task tasks[MAX_TASKS];
int task_count = 0;
pthread_mutex_t task_mutex = PTHREAD_MUTEX_INITIALIZER;

void* execute_task(void* arg) {
    Task* task = (Task*)arg;
    sleep(SCHEDULE_INTERVAL);

    if (task->is_active) {
        printf("Executing task: %s\n", task->description);
    }
    return NULL;
}

void schedule_task(const char* description, int delay) {
    pthread_mutex_lock(&task_mutex);

    if (task_count >= MAX_TASKS) {
        printf("Cannot schedule more tasks. Maximum limit reached.\n");
        pthread_mutex_unlock(&task_mutex);
        return;
    }

    time_t trigger_time = time(NULL) + delay;
    strcpy(tasks[task_count].description, description);
    tasks[task_count].trigger_time = trigger_time;
    tasks[task_count].is_active = 1;

    if (pthread_create(&tasks[task_count].thread_id, NULL, execute_task, &tasks[task_count]) != 0) {
        printf("Error creating thread for task: %s\n", description);
    }

    task_count++;
    pthread_mutex_unlock(&task_mutex);
}

void cancel_task(int task_id) {
    pthread_mutex_lock(&task_mutex);

    if (task_id < 0 || task_id >= task_count) {
        printf("Invalid task ID.\n");
    } else {
        tasks[task_id].is_active = 0;
        pthread_cancel(tasks[task_id].thread_id);
        printf("Cancelled task: %s\n", tasks[task_id].description);
    }

    pthread_mutex_unlock(&task_mutex);
}

void list_tasks() {
    pthread_mutex_lock(&task_mutex);
    printf("Scheduled Tasks:\n");
    for (int i = 0; i < task_count; i++) {
        if (tasks[i].is_active) {
            printf("Task %d: %s (Trigger Time: %s)\n", i, tasks[i].description, ctime(&tasks[i].trigger_time));
        }
    }
    pthread_mutex_unlock(&task_mutex);
}

void cleanup() {
    pthread_mutex_lock(&task_mutex);
    for (int i = 0; i < task_count; i++) {
        if (tasks[i].is_active) {
            pthread_cancel(tasks[i].thread_id);
        }
    }
    pthread_mutex_unlock(&task_mutex);
}

int main() {
    signal(SIGINT, cleanup); // Handle clean up on terminal interrupt

    char command[100];
    printf("Welcome to the C Task Scheduler!\n");

    while (1) {
        printf("Enter command (schedule/cancel/list/exit): ");
        fgets(command, sizeof(command), stdin);
        command[strcspn(command, "\n")] = 0; // Remove newline

        if (strcmp(command, "schedule") == 0) {
            char description[MAX_DESC_LENGTH];
            int delay;
            printf("Enter task description: ");
            fgets(description, sizeof(description), stdin);
            description[strcspn(description, "\n")] = 0; // Remove newline

            printf("Enter delay in seconds: ");
            scanf("%d", &delay);
            getchar(); // Clear newline from input buffer

            schedule_task(description, delay);
        } else if (strcmp(command, "cancel") == 0) {
            int task_id;
            printf("Enter task ID to cancel: ");
            scanf("%d", &task_id);
            getchar(); // Clear newline from input buffer

            cancel_task(task_id);
        } else if (strcmp(command, "list") == 0) {
            list_tasks();
        } else if (strcmp(command, "exit") == 0) {
            cleanup();
            printf("Exiting the scheduler. Goodbye!\n");
            break;
        } else {
            printf("Unknown command. Please try again.\n");
        }
    }

    return 0;
}

