// C Bingo Simulator Example Program

#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#define ROWS 5
#define COLS 5

// Function prototypes
void generate_card(int card[ROWS][COLS]);
void display_card(int card[ROWS][COLS]);
int draw_number(int drawn_numbers[], int numbers_drawn);
int check_win(int card[ROWS][COLS]);

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Declare variables
    int player_card[ROWS][COLS];
    int drawn_numbers[75] = {0};
    int numbers_drawn = 0;

    // Generate and display player's card
    generate_card(player_card);
    printf("Player's Card:\n");
    display_card(player_card);

    // Game loop
    while (1) {
        // Prompt user to draw a number
        printf("Press enter to draw a number...");
        getchar();

        // Draw a number
        int number_drawn = draw_number(drawn_numbers, numbers_drawn);
        printf("Number drawn: %d\n", number_drawn);
        numbers_drawn++;

        // Check if number is on player's card
        int row, col, found = 0;
        for (row = 0; row < ROWS; row++) {
            for (col = 0; col < COLS; col++) {
                if (player_card[row][col] == number_drawn) {
                    player_card[row][col] = 0;
                    found = 1;
                    break;
                }
            }
            if (found) {
                break;
            }
        }

        // Display updated player's card
        printf("Player's Card:\n");
        display_card(player_card);

        // Check if player has won
        if (check_win(player_card)) {
            printf("Bingo! You win!\n");
            break;
        }

        // Check if all numbers have been drawn
        if (numbers_drawn == 75) {
            printf("Sorry, no more numbers to draw. You lose.\n");
            break;
        }
    }

    return 0;
}

// Function to generate player's card
void generate_card(int card[ROWS][COLS]) {
    int row, col, num;
    for (row = 0; row < ROWS; row++) {
        for (col = 0; col < COLS; col++) {
            // Generate unique random number for each cell
            do {
                num = (col * 15) + (rand() % 15) + 1;
            } while (num_in_row(num, card, row) || num_in_col(num, card, col));
            card[row][col] = num;
        }
    }
}

// Function to check if a number is already in the same row
int num_in_row(int num, int card[ROWS][COLS], int row) {
    int col;
    for (col = 0; col < COLS; col++) {
        if (card[row][col] == num) {
            return 1;
        }
    }
    return 0;
}

// Function to check if a number is already in the same column
int num_in_col(int num, int card[ROWS][COLS], int col) {
    int row;
    for (row = 0; row < ROWS; row++) {
        if (card[row][col] == num) {
            return 1;
        }
    }
    return 0;
}

// Function to display player's card
void display_card(int card[ROWS][COLS]) {
    int row, col;
    for (row = 0; row < ROWS; row++) {
        for (col = 0; col < COLS; col++) {
            printf("%2d ", card[row][col]);
        }
        printf("\n");
    }
}

// Function to draw a number
int draw_number(int drawn_numbers[], int numbers_drawn) {
    int num;
    do {
        num = (rand() % 75) + 1;
    } while (drawn(num, drawn_numbers, numbers_drawn));
    drawn_numbers[numbers_drawn] = num;
    return num;
}

// Function to check if a number has already been drawn
int drawn(int num, int drawn_numbers[], int numbers_drawn) {
    int i;
    for (i = 0; i < numbers_drawn; i++) {
        if (drawn_numbers[i] == num) {
            return 1;
        }
    }
    return 0;
}

// Function to check if player has won
int check_win(int card[ROWS][COLS]) {
    int row, col, num_zeros;
    // Check rows
    for (row = 0; row < ROWS; row++) {
        num_zeros = 0;
        for (col = 0; col < COLS; col++) {
            if (card[row][col] == 0) {
                num_zeros++;
            }
        }
        if (num_zeros == COLS) {
            return 1;
        }
    }
    // Check columns
    for (col = 0; col < COLS; col++) {
        num_zeros = 0;
        for (row = 0; row < ROWS; row++) {
            if (card[row][col] == 0) {
                num_zeros++;
            }
        }
        if (num_zeros == ROWS) {
            return 1;
        }
    }
    // Check diagonals
    if (card[0][0] == 0 && card[1][1] == 0 && card[2][2] == 0 && card[3][3] == 0 && card[4][4] == 0) {
        return 1;
    }
    if (card[0][4] == 0 && card[1][3] == 0 && card[2][2] == 0 && card[3][1] == 0 && card[4][0] == 0) {
        return 1;
    }
    return 0;
}

/*This program demonstrates the basic binary tree traversals (both recursive and iterative versions). As a review, the traversals are:
Preorder - Visit the root, Traverse left subtree, Traverse right subtree
Inorder - Traverse left subtree, Visit the root, Traverse right subtree
Postorder - Traverse left subtree, Traverse right subtree, Visit the root*/

#include "binarytree.h"
#include <vector>
#include <iostream>
#include <time.h>
using namespace std;

int main()
{
	BinaryTree tree;

	srand(time(NULL));

	//Build the tree using a random ordering of 10 integers between 1 and 10
	for (int i = 1; i <= 10; i++)
	{
		int key = rand() % 10 + 1;
		if (tree.search(key) == NULL)
		{
			tree.insert(key);
		}
		else
		{
			i--;
		}
	}	

	cout << "Preorder traversal Recursive:"<<endl;
	tree.preorderTraversalrec(tree.getRoot());

	cout << endl << endl;

	cout << "Preorder traversal Iterative:" << endl;
	tree.preorderTraversalit(tree.getRoot());

	cout << endl << endl;

	cout << "Inorder traversal Recursive:" << endl;
	tree.inorderTraversalrec(tree.getRoot());

	cout << endl << endl;

	cout << "Inorder traversal Iterative:" << endl;
	tree.inorderTraversalit(tree.getRoot());

	cout << endl << endl;

	cout << "Postorder traversal Recursive:" << endl;
	tree.postorderTraversalrec(tree.getRoot());

	cout << endl << endl;

	cout << "Postorder traversal Iterative:" << endl;
	tree.postorderTraversalit(tree.getRoot());

	cout << endl << endl;
	return 0;
}

#include "trie.hpp"

#include <cassert>

using namespace atod;

trie::trie() : root_ ( ' ' )
{
}

trie::~trie()
{
}

void trie::add ( const std::string& str )
{
    node* curr = &root_;

    for ( size_t i = 0; i < str.length(); ++i )
    {
        assert ( curr != nullptr );

        int idx = getCharIdx ( str[i] );

        if ( idx < 0 )
        {
            ++ ( curr->count_ );

            curr = &root_;
            continue;
        }

        assert ( idx >= 0 );
        assert ( idx <= ALPHABET_SIZE );

        node*& next = curr->children_[idx];

        if ( next == nullptr )
        {
            next = new node ( str[i] );
        }

        assert ( next != nullptr );

        curr = next;
    }

    assert ( curr != nullptr );
    if ( curr != &root_ )
        ++ ( curr->count_ );
}

size_t trie::count ( const std::string& str ) const
{
    const node* curr = &root_;

    for ( size_t i = 0; i < str.length(); ++i )
    {
        assert ( curr != nullptr );

        int idx = getCharIdx ( str[i] );

        if ( idx < 0 )
            return 0;

        curr = curr->children_[idx];

        if ( curr == nullptr )
            return 0;
    }

    assert ( curr != nullptr );

    return curr->count_;
}

void trie::print ( std::ostream& dest ) const
{
    std::string tmp;
    internalPrint ( &root_, tmp, dest );
}

void trie::internalPrint ( const node* n, std::string& prev, std::ostream& dest) const
{
    assert ( n != nullptr );

    prev.push_back ( n->character_ );

    if ( n->count_ > 0 )
    {
        dest << prev << " (" << n->count_ << " times)" << std::endl;
    }

    for ( size_t i = 0; i < ALPHABET_SIZE; ++i )
    {
        if ( n->children_[i] != nullptr )
            internalPrint ( n->children_[i], prev, dest );
    }

    prev.pop_back();
}

int trie::getCharIdx ( char c )
{
    if ( c >= 'A' && c <= 'Z' )
        return ( c - 'A' );
    else if ( c >= 'a' && c <= 'z' )
        return ( c - 'a' );

    return -1;
}

trie::node::node ( char c ) : character_ ( c ), count_ ( 0 )
{
}

trie::node::~node()
{
    for ( size_t i = 0; i < ALPHABET_SIZE; ++i )
    {
        if ( children_[i] != nullptr )
            delete children_[i];
    }
}

