#include <stdio.h>
#include <string.h>

// Function to encrypt the string
void encrypt(char *str)
{
    // Get length of string
    int len = strlen(str);

    // Translate each character to its ASCII code
    for (int i = 0; i < len; i++)
    {
        char c = str[i];
        int ascii = (int) c;

        // Shift ASCII code by 3
        ascii = ascii + 3;

        // If the character is 'a', replace it with 'e'
        if (c == 'a')
            c = 'e';

        // If the character is 'e', replace it with 'a'
        if (c == 'e')
            c = 'a';

        // If the character is 'i', replace it with 'o'
        if (c == 'i')
            c = 'o';

        // If the character is 'o', replace it with 'i'
        if (c == 'o')
            c = 'i';

        // If the character is 'u', replace it with 'y'
        if (c == 'u')
            c = 'y';

        // If the character is 'y', replace it with 'u'
        if (c == 'y')
            c = 'u';

        // Convert the ASCII code back to character
        str[i] = (char) ascii;
    }
}

int main()
{
    char str[100];
    printf("Enter the string to encrypt: ");
    fgets(str, sizeof(str), stdin);

    // Remove newline character from the end of the string
    str[strcspn(str, "\n")] = '\0';

    // Encrypt the string
    encrypt(str);

    // Print the encrypted string
    printf("Encrypted string: %s\n", str);

    return 0;
}

