void bubbleSort(int ar1[10], int logicalSize)
{
   int tempHolder = 0; 
   for (int i = logicalSize; i &gt;= 2; i--)
   {
      for(int i2 = 0; i2 &lt; logicalSize-i2; i++)
      {
         if (ar1[i2 + 1] &lt; ar1[i2])
         {
            tempHolder = ar1[i2]; 
            ar1[i2] = ar1[i2 + 1]; 
            ar1[i2 + 1] = tempHolder; 
         }

      }
   }
   cout &lt;&lt; "The array in sorted order: " &lt;&lt; endl; 
   for(int i2 = 0; i2 &lt;= 10; i2++)
   {
      cout &lt;&lt; ar1[i2] &lt;&lt; endl;
   }
} 

