//Falcon-180B DATASET v1.0 Category: Fractal Generation ; Style: Ada Lovelace
#include <stdio.h>
#include <stdlib.h>
#include <math.h>

// Define the maximum number of iterations
#define MAX_ITERATIONS 1000

// Define the size of the image
#define IMAGE_SIZE 1024

// Define the escape time algorithm
int escape_time(double x, double y) {
    double real = 0.0, imag = 0.0;
    int iterations = 0;

    while (iterations < MAX_ITERATIONS &&
           (real*real + imag*imag) < 4.0) {
        double temp_real = real*real - imag*imag + x;
        imag = 2.0*real*imag + y;
        real = temp_real;
        iterations++;
    }

    return iterations;
}

// Define the color map
int color_map(int iterations) {
    if (iterations == MAX_ITERATIONS) {
        return 0;
    } else {
        return (int) (255.0 * (double) iterations / MAX_ITERATIONS);
    }
}

// Define the main function
int main() {
    FILE *fp;
    int x, y, iterations;
    double real, imag;

    // Open the output file
    fp = fopen("fractal.ppm", "wb");
    if (fp == NULL) {
        printf("Error: could not open output file.\n");
        exit(1);
    }

    // Write the header
    fprintf(fp, "P6\n%d %d\n255\n", IMAGE_SIZE, IMAGE_SIZE);

    // Generate the fractal
    for (y = 0; y < IMAGE_SIZE; y++) {
        for (x = 0; x < IMAGE_SIZE; x++) {
            real = (double) x / IMAGE_SIZE - 2.0;
            imag = (double) y / IMAGE_SIZE - 1.0;

            iterations = escape_time(real, imag);
            fprintf(fp, "%d ", color_map(iterations));
        }
        fprintf(fp, "\n");
    }

    // Close the output file
    fclose(fp);

    return 0;
}

