#define MAX_NODES 100
#define MAX_EDGES 100
#define MAX_COLOR 10

typedef struct {
    int node;
    int color;
} ColorPair;

void color_graph(int graph[MAX_NODES][MAX_EDGES], int num_nodes, int num_edges, int color[MAX_COLOR]) {
    int i, j;
    ColorPair pair[MAX_NODES];

    for (i = 0; i < num_nodes; i++) {
        pair[i].node = i;
        pair[i].color = -1;
    }

    for (i = 0; i < num_edges; i++) {
        j = graph[i][0];
        if (pair[j].color == -1) {
            pair[j].color = color[0];
            color[0]++;
        } else {
            color[0]++;
            i = MAX_COLOR;
        }
        j = graph[i][1];
        if (pair[j].color == -1) {
            pair[j].color = color[0];
            color[0]++;
        } else {
            color[0]++;
            i = MAX_COLOR;
        }
    }

    printf("Colored graph: \n");
    for (i = 0; i < num_nodes; i++) {
        printf("%d ", pair[i].node);
    }
    printf("\n");
}

int main() {
    int graph[MAX_NODES][MAX_EDGES] = {
