//MISTRAL-7B DATASET v1.0 Category: Hexadecimal Converter ; Style: configurable
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define SIZE 50

typedef struct {
    char hex[SIZE];
    int base;
    char dec[SIZE];
} converter;

void hex_to_dec(converter *hex_num) {
    int i, j, num;
    for (i = 0, j = 0; hex_num->hex[i] != '\0'; i++) {
        if (isdigit(hex_num->hex[i])) {
            num = hex_num->hex[i] - '0';
        } else if (isalpha(hex_num->hex[i])) {
            num = hex_num->hex[i] - 'A' + 10;
        }
        hex_num->dec[j++] = (num / (hex_num->base / 16)) + '0';
        num %= (hex_num->base / 16);
        hex_num->dec[j++] = (num / hex_num->base) + '0';
        num %= hex_num->base;
    }
    hex_num->dec[j] = '\0';
    reverse_string(hex_num->dec);
}

void reverse_string(char *str) {
    int i = 0, j = strlen(str) - 1;
    char temp;
    while (i < j) {
        temp = str[i];
        str[i] = str[j];
        str[j] = temp;
        i++;
        j--;
    }
}

int main(int argc, char *argv[]) {
    converter num;
    int len;

    if (argc != 3) {
        printf("Usage: %s <hex_number> <base>\n", argv[0]);
        return 1;
    }

    strcpy(num.hex, argv[1]);
    num.base = atoi(argv[2]);

    if (num.base < 2 || num.base > 36) {
        printf("Invalid base. Supported bases: 2-36\n");
        return 1;
    }

    hex_to_dec(&num);

    len = strlen(num.dec);
    printf("Decimal equivalent of '%s' in base %d is '%s'\n", num.hex, num.base, num.dec);

    return 0;
}

