			{
				best = d;
				pos1 = mapp[p[i]], pos2 = mapp[*it];
			}
		}
		s.insert(p[i]);
	}
	if(pos1 > pos2) swap(pos1, pos2);
	printf("%d %d %.6lf\n", pos1, pos2, best);
