/*
 * Spam Detection System in C
 *
 * This program uses a portable style to implement a spam detection system.
 * It uses a set of keywords and phrases to identify spam messages.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define SPAM_THRESHOLD 3

// Function to check if a message is spam
int is_spam(const char *message) {
  const char *keywords[] = {
    "viagra", "phentermine", "soma", "accutane", "cialis"
  };
  const char *phrases[] = {
    "buy viagra", "buy phentermine", "buy soma", "buy accutane", "buy cialis"
  };
  int spam_count = 0;

  // Check if any keywords or phrases are present in the message
  for (int i = 0; i < 5; i++) {
    if (strstr(message, keywords[i]) != NULL) {
      spam_count++;
    }
    if (strstr(message, phrases[i]) != NULL) {
      spam_count++;
    }
  }

  // If the spam count is above the threshold, return 1 (spam)
  if (spam_count >= SPAM_THRESHOLD) {
    return 1;
  }

  // Otherwise, return 0 (not spam)
  return 0;
}

int main() {
  char message[100];

  // Get the message from the user
  printf("Enter a message: ");
  fgets(message, 100, stdin);

  // Check if the message is spam
  if (is_spam(message)) {
    printf("Spam detected!\n");
  } else {
    printf("Message is not spam.\n");
  }

  return 0;
}

