	else
		for (int i = 2; i <= sqrt(n); i++)
		{
			if (n%i == 0)
				return 0;
		}
	return 1;
}

void sortingDescending(int n, int p[])
{
	for (int i = 0; i < n-1; i++)
	{

		for (int j = i + 1; j < n; j++)
		{
			if (p[i] < p[j])
				std:swap(p[i], p[j]);
		}
	}
}

void sortingAscending(int n, int p[])
{
	for (int i = 0; i < n - 1; i++)
	{

		for (int j = i + 1; j < n; j++)
		{
			if (p[i] > p[j])
				std:swap(p[i], p[j]);
		}
	}
}


