int GCD2(int x, int y)
{
	if (x < y)
	{
		for (int i = x; i >= 1; i--)
		{
			if (x%i == 0 && y%i == 0)
			{
				return i;
			}
		}
	}
	else
		for (int i = y; i >= 1; i--)
		{
			if (x%i == 0 && y%i == 0)
			{
				return i;
			}
		}
}

