#include <stdbool.h>

#define MAX_COINS 5
#define MAX_ITEMS 10
#define MAX_PRICE 100

typedef struct {
    int price;
    char name[20];
} Item;

void generateItems(Item items[], int num_items) {
    srand(time(NULL));
    for (int i = 0; i < num_items; i++) {
        items[i].price = rand() % MAX_PRICE + 1;
        sprintf(items[i].name, "Item %d", i + 1);
    }
}

void printItems(Item items[], int num_items) {
    for (int i = 0; i < num_items; i++) {
        printf("%s: $%d\n", items[i].name, items[i].price);
    }
}

int main() {
    Item items[MAX_ITEMS];
    int num_items = rand() % MAX_ITEMS + 1;
    generateItems(items, num_items);
    printf("Available items:\n");
    printItems(items, num_items);

    int num_coins = rand() % MAX_COINS + 1;
    int max_price = 0;
    for (int i = 0; i < num_items; i++) {
        if (items[i].price > max_price) {
            max_price = items[i].price;
        }
    }

    printf("\nYou have $%d to spend.\n", num_coins * max_price);

    int purchased_items = 0;
    for (int i = 0; i < num_items; i++) {
        if (items[i].price <= num_coins * max_price) {
            printf("Purchased %s for $%d\n", items[i].name, items[i].price);
            purchased_items++;
        }
    }

    if (purchased_items == 0) {
        printf("Sorry, you cannot afford any of the items.\n");
    } else {
        printf("You purchased %d item(s).\n", purchased_items);
    }

    return 0;
}

