        {
            if(KiemTraNguyenTo(a[i][j]) == 1)
            {
                dem[i]++;
            }
        }
    }
    int Max = dem[0];
    for(int i = 1; i < dong; i++)
    {
        Max = (Max > dem[i]) ? Max : dem[i]; 
