//MISTRAL-7B DATASET v1.0 Category: Digital signal processing ; Style: satisfied
#include <stdio.h>
#include <math.h>
#define PI M_PI

#define N 32
#define Fs 1000.0
#define fs 1000.0
#define T 1.0
#define f1 10.0
#define f2 5.0

double hamming(int n) {
    double h[N];
    double a = 0.54;
    double b = 0.46;

    for (int i = 0; i < N; i++) {
        h[i] = a - b * cos(2 * PI * i / N);
    }

    return h[n];
}

int main() {
    double *x, *y, *z, *w, sum_squares = 0.0, result = 0.0;
    int i;

    x = (double *)calloc(N, sizeof(double));
    y = (double *)calloc(N, sizeof(double));
    z = (double *)calloc(N, sizeof(double));
    w = (double *)calloc(N, sizeof(double));

    for (i = 0; i < N; i++) {
        x[i] = sin(2 * PI * f1 * T * i / fs);
        w[i] = hamming(i);
        y[i] = x[i] * w[i];
    }

    for (i = 0; i < N; i++) {
        z[i] = sin(2 * PI * f2 * T * i / fs) * 0.5;
        z[i] = fabs(y[i] * z[i]);
        sum_squares += pow(z[i], 2);
    }

    result = (sum_squares / N) * 100;

    printf("Result: %f %%\n", result);

    free(x);
    free(y);
    free(z);
    free(w);

    return 0;
}

//Gemma-7B DATASET v1.0 Category: Pong Game with AI Opponent ; Style: detailed
#include <stdio.h>
#include <stdlib.h>

#define WIDTH 640
#define HEIGHT 480

// Player 1 (left) paddle
#define PADDLE_WIDTH 20
#define PADDLE_HEIGHT 100
int paddle_1_x = 0;
int paddle_1_y = HEIGHT / 2 - PADDLE_HEIGHT / 2;

// Player 2 (right) paddle
#define PADDLE_WIDTH 20
#define PADDLE_HEIGHT 100
int paddle_2_x = WIDTH - PADDLE_WIDTH - 1;
int paddle_2_y = HEIGHT / 2 - PADDLE_HEIGHT / 2;

// Ball position
int ball_x = WIDTH / 2;
int ball_y = HEIGHT / 2;

// Ball speed
int ball_speed_x = 1;
int ball_speed_y = 1;

// AI opponent
int ai_speed = 3;

// Game loop flag
int game_loop = 1;

void draw_screen() {
  // Clear screen
  system("cls");

  // Draw border
  for (int x = 0; x < WIDTH; x++) {
    for (int y = 0; y < HEIGHT; y++) {
      if (x == 0 || x == WIDTH - 1 || y == 0 || y == HEIGHT - 1) {
        printf("%c", '*');
      } else {
        printf(" ");
      }
    }
    printf("\n");
  }

  // Draw paddles
  printf("  ");
  for (int x = paddle_1_x; x < paddle_1_x + PADDLE_WIDTH; x++) {
    printf("%c", '#');
  }
  printf("\n");

  printf("  ");
  for (int x = paddle_2_x; x < paddle_2_x + PADDLE_WIDTH; x++) {
    printf("%c", '#');
  }
  printf("\n");

  // Draw ball
  printf("  *  ");
  printf("%c", '*');
  printf("  *  ");
  printf("\n");
}

void update_ball() {
  ball_x += ball_speed_x * ai_speed;
  ball_y += ball_speed_y;

  // Check if ball has hit a paddle
  if (ball_x + ball_speed_x * ai_speed >= paddle_2_x && ball_y >= paddle_2_y && ball_y <= paddle_2_y + PADDLE_HEIGHT) {
    ball_speed_x *= -1;
  } else if (ball_x <= paddle_1_x && ball_y >= paddle_1_y && ball_y <= paddle_1_y + PADDLE_HEIGHT) {
    ball_speed_x *= -1;
  }

  // Check if ball has hit the wall
  if (ball_x >= WIDTH - 1) {
    game_loop = 0;
  } else if (ball_x <= 0) {
    game_loop = 0;
  }
}

void main() {
  // Game loop
  while (game_loop) {
    draw_screen();
    update_ball();
  }

  // Game over screen
  system("cls");
  printf("Game Over!");
}

