        cout &lt;&lt; "Undefined ";
    else
        cout &lt;&lt; v &lt;&lt; " ";
    pt = new Cube(w, h, b);
    cout &lt;&lt; pt-&gt;area() &lt;&lt; " ";
    if ((v = pt-&gt;volume()) == -1)
        cout &lt;&lt; "Undefined ";
    else
        cout &lt;&lt; v &lt;&lt; " ";
