#include <curl/curl.h>

#define FALSE 0
#define TRUE !FALSE

struct write_data {
  size_t written;
  FILE *fp;
};

size_t write_data(void *ptr, size_t size, size_t nmemb, struct write_data *data) {
  size_t realsize = size * nmemb;
  if (data->fp) {
    if (fwrite(ptr, size, nmemb, data->fp) == NULL) {
      fprintf(stderr, "Write error\n");
      return 0;
    }
    data->written += realsize;
  }
  return realsize;
}

int main(int argc, char **argv) {
  CURL *curl;
  CURLcode res;
  int i;
  struct write_data wr_data;
  FILE *fp;

  if (argc != 3) {
    fprintf(stderr, "Usage: %s <URL> <output-file>\n", argv[0]);
    return 1;
  }

  curl = curl_easy_init();
  if(curl) {
    fp = fopen(argv[2], "wb");
    if (fp) {
      curl_easy_setopt(curl, CURLOPT_URL, argv[1]);
      curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_data);
      curl_easy_setopt(curl, CURLOPT_WRITEDATA, &wr_data);
      wr_data.fp = fp;

      res = curl_easy_perform(curl);
      if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
      } else {
        printf("Successfully wrote %ld bytes to %s\n", wr_data.written, argv[2]);
      }

      fclose(fp);
    } else {
      fprintf(stderr, "Could not open output file %s\n", argv[2]);
      curl_easy_cleanup(curl);
      return 1;
    }

    curl_easy_cleanup(curl);
  } else {
    fprintf(stderr, "Failed to initialize libcurl\n");
    return 1;
  }

  return 0;
}

