    server_addr.sin_port = htons(PORT); // Assign the port

    // Bind the socket
    if (bind(server_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Binding failed");
        close(server_socket);
        exit(EXIT_FAILURE);
    }

    // Start listening
    if (listen(server_socket, MAX_CLIENTS) < 0) {
        perror("Listening failed");
        close(server_socket);
        exit(EXIT_FAILURE);
    }

    printf("Server is up and running on port %d! Waiting for a client to tickle my funny bone... 😄\n", PORT);

    while (1) {
        addr_size = sizeof(client_addr);
        client_socket = accept(server_socket, (struct sockaddr *)&client_addr, &addr_size);

        if (client_socket < 0) {
            perror("Could not accept client");
            continue; // Try again for the next client
        }

        serveClient(client_socket);
    }

    close(server_socket);
    return 0;
}

