int main()
{
  // Seed the random number generator
  srand(time(NULL));

  // Create a 3x3 Tic Tac Toe board
  int board[3][3] = {
    {0, 0, 0},
    {0, 0, 0},
    {0, 0, 0}
  };

  // Define the player's move
  int move[2] = {0, 0};

