  makeMove(board, move);

  // Print the board
  printBoard(board);

  // Check if the player has won
  if (checkWin(board, move) == 1)
  {
    printf("You win!");
  }
  else if (checkWin(board, move) == 2)
  {
    printf("The AI wins!");
  }
  else
  {
    printf("It's a draw!");
  }

  return 0;
}

// Function to make the AI's move
void makeMove(int **board, int move[])
{
  // Choose a random move
  move[0] = rand() % 3;
  move[1] = rand() % 3;

  // If the move is valid, make it
  if (board[move[0]][move[1]] == 0)
  {
    board[move[0]][move[1]] = 2;
  }
  else
  {
    // If the move is not valid, try again
    makeMove(board, move);
  }
}

// Function to print the board
void printBoard(int **board)
{
  for (int i = 0; i < 3; i++)
  {
    for (int j = 0; j < 3; j++)
    {
      printf("%d ", board[i][j]);
    }
    printf("\n");
  }
}

// Function to check if the player has won
int checkWin(int **board, int move[])
{
  // Check if the player has won in a row
  for (int i = 0; i < 3; i++)
  {
    if (board[move[0]][i] == board[move[1]][i] && board[move[0]][i] == board[move[2]][i] && board[move[0]][i] == move[3])
    {
      return 1;
    }
  }

  // Check if the player has won in a column
  for (int j = 0; j < 3; j++)
  {
    if (board[j][move[0]] == board[j][move[1]] && board[j][move[0]] == board[j][move[2]] && board[j][move[0]] == move[3])
    {
      return 1;
    }
  }

  // Check if the player has won in a diagonal
  if (board[0][0] == board[move[0]][move[1]] && board[0][0] == board[move[2]][move[3]] && board[0][0] == move[3])
  {
    return 1;
  }

  // If the player has not won, return 0
  return 0;
}

