#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_SIZE 1000 // Maximum array size
#define MATRIX_SIZE 500 // Matrix dimensions

void bubble_sort(int array[], int size);
void quicksort(int array[], int low, int high);
void matrix_multiply(int a[MATRIX_SIZE][MATRIX_SIZE], int b[MATRIX_SIZE][MATRIX_SIZE], int result[MATRIX_SIZE][MATRIX_SIZE]);

// A utility function to swap two elements
void swap(int *xp, int *yp) {
    int temp = *xp;
    *xp = *yp;
    *yp = temp;
}

// Print a matrix for debugging
void print_matrix(int matrix[MATRIX_SIZE][MATRIX_SIZE]) {
    for (int i = 0; i < MATRIX_SIZE; i++) {
        for (int j = 0; j < MATRIX_SIZE; j++) {
            printf("%d ", matrix[i][j]);
        }
        printf("\n");
    }
}

// Function to perform bubble sort
void bubble_sort(int array[], int size) {
    for (int i = 0; i < size-1; i++) {
        for (int j = 0; j < size-i-1; j++) {
            if (array[j] > array[j+1]) {
                swap(&array[j], &array[j+1]);
            }
        }
    }
}

// Partition function for quicksort
int partition(int array[], int low, int high) {
    int pivot = array[high];
    int i = (low - 1);
    for (int j = low; j < high; j++) {
        if (array[j] <= pivot) {
            i++;
            swap(&array[i], &array[j]);
        }
    }
    swap(&array[i + 1], &array[high]);
    return (i + 1);
}

// Function to perform quicksort
void quicksort(int array[], int low, int high) {
    if (low < high) {
        int pi = partition(array, low, high);
        quicksort(array, low, pi - 1);
        quicksort(array, pi + 1, high);
    }
}

// Function to multiply two matrices
void matrix_multiply(int a[MATRIX_SIZE][MATRIX_SIZE], int b[MATRIX_SIZE][MATRIX_SIZE], int result[MATRIX_SIZE][MATRIX_SIZE]) {
    for (int i = 0; i < MATRIX_SIZE; i++) {
        for (int j = 0; j < MATRIX_SIZE; j++) {
            result[i][j] = 0;
            for (int k = 0; k < MATRIX_SIZE; k++) {
                result[i][j] += a[i][k] * b[k][j];
            }
        }
    }
}

int main() {
    srand(time(NULL)); // Seed the random number generator
    int array[MAX_SIZE];
    int matrix_a[MATRIX_SIZE][MATRIX_SIZE], matrix_b[MATRIX_SIZE][MATRIX_SIZE], result[MATRIX_SIZE][MATRIX_SIZE];

    // Initialize array with random values
    for (int i = 0; i < MAX_SIZE; i++) {
        array[i] = rand() % 1000;
    }

    // Initialize matrices with random values
    for (int i = 0; i < MATRIX_SIZE; i++) {
        for (int j = 0; j < MATRIX_SIZE; j++) {
            matrix_a[i][j] = rand() % 10;
            matrix_b[i][j] = rand() % 10;
        }
    }

    // Benchmark Bubble Sort
    clock_t start = clock();
    bubble_sort(array, MAX_SIZE);
    clock_t end = clock();
    double bubble_sort_time = (double)(end - start) / CLOCKS_PER_SEC;
    printf("Bubble Sort Time: %f seconds\n", bubble_sort_time);

    // Reset the array with random values for Quicksort
    for (int i = 0; i < MAX_SIZE; i++) {
        array[i] = rand() % 1000;
    }

    // Benchmark Quicksort
    start = clock();
    quicksort(array, 0, MAX_SIZE - 1);
    end = clock();
    double quicksort_time = (double)(end - start) / CLOCKS_PER_SEC;
    printf("Quick Sort Time: %f seconds\n", quicksort_time);

    // Benchmark Matrix Multiplication
    start = clock();
    matrix_multiply(matrix_a, matrix_b, result);
    end = clock();
    double matrix_multiplication_time = (double)(end - start) / CLOCKS_PER_SEC;
    printf("Matrix Multiplication Time: %f seconds\n", matrix_multiplication_time);

    // Uncomment the line below to print the result matrix
    // print_matrix(result);

    return 0;
}

