        printf("Error opening file.\n");
        exit(1);
    }

    // Read the file into the buffer
    fseek(file.file, 0, SEEK_END);
    file.buffer_size = ftell(file.file);
    rewind(file.file);
    fread(file.buffer, file.buffer_size, 1, file.file);

    // Close the file
    fclose(file.file);

    // Prompt the user for the search string
