#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>

#define MAX_INPUT_SIZE 1024
#define MAX_ARGS 100

void display_welcome_message() {
    printf("~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n");
    printf("   Welcome to LoveShell!      \n");
    printf("~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n");
    printf("A place where commands dance, \n");
    printf("and love for the terminal enhances. \n");
    printf("Type 'exit' to bid farewell \n");
    printf("and let our memories swell. \n\n");
}

void process_command(char *input) {
    char *args[MAX_ARGS];
    char *token = strtok(input, " \n");
    int idx = 0;

    while (token != NULL && idx < MAX_ARGS - 1) {
        args[idx++] = token;
        token = strtok(NULL, " \n");
    }
    args[idx] = NULL;

    pid_t pid = fork();
    if (pid < 0) {
        perror("Error forking process");
    } else if (pid == 0) {
        if (execvp(args[0], args) == -1) {
            perror("Error executing command");
            exit(EXIT_FAILURE);
        }
    } else {
        wait(NULL);
    }
}

void handle_input() {
    char input[MAX_INPUT_SIZE];
    while (1) {
        printf("LoveShell> ");
        if (fgets(input, MAX_INPUT_SIZE, stdin) == NULL) {
            break; // End of input
        }

        if (strcmp(input, "exit\n") == 0) {
            printf("Farewell, my dear! Until we meet again.\n");
            break;
        }

        process_command(input);
    }
}

int main() {
    display_welcome_message();
    handle_input();
    return 0;
}

