#define MAX_PLAYERS 10
#define MAX_MESSAGE_LEN 256

struct player {
    char name[50];
    int score;
    int alive;
};

struct game_state {
    int game_started;
    int game_ended;
    int winner;
    struct player players[MAX_PLAYERS];
};

void initialize_game(struct game_state *state) {
    state->game_started = 0;
    state->game_ended = 0;
    state->winner = -1;
    memset(state->players, 0, sizeof(state->players));
}

void handle_player_input(struct game_state *state, char *input) {
    int i;
    for (i = 0; i < MAX_PLAYERS; i++) {
        if (strcmp(input, state->players[i].name) == 0) {
            state->players[i].alive = 1;
            break;
        }
    }
}

void update_game_state(struct game_state *state) {
    int i, j;
    for (i = 0; i < MAX_PLAYERS; i++) {
        if (state->players[i].alive) {
            for (j = i + 1; j < MAX_PLAYERS; j++) {
                if (state->players[j].alive) {
                    if (state->players[i].score > state->players[j].score) {
                        state->players[i].score++;
                        state->players[j].alive = 0;
                    } else if (state->players[i].score < state->players[j].score) {
                        state->players[j].score++;
                        state->players[i].alive = 0;
                    }
                }
            }
        }
    }
}

void print_game_state(struct game_state *state) {
    int i;
    for (i = 0; i < MAX_PLAYERS; i++) {
        if (state->players[i].alive) {
            printf("%d: %s (%d points)\n", i, state->players[i].name, state->players[i].score);
        }
    }
}

int main() {
    struct game_state state;
    char input[100];

    initialize_game(&state);

    while (1) {
        printf("Enter player name or 'q' to quit: ");
        fgets(input, 100, stdin);

        handle_player_input(&state, input);

        update_game_state(&state);

        print_game_state(&state);

        if (state.game_ended) {
            break;
        }
    }

    return 0;
}

//MISTRAL-7B DATASET v1.0 Category: Task Scheduler ; Style: ultraprecise
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_TASKS 5

typedef struct Task {
    char name[32];
    int priority;
    int state; // 0: idle, 1: running, 2: completed
} Task;

Task task_queue[MAX_TASKS];
int task_count = 0;

void add_task(char *name, int priority) {
    if (task_count >= MAX_TASKS) {
        printf("Task queue is full.\n");
        return;
    }
    strcpy(task_queue[task_count].name, name);
    task_queue[task_count].priority = priority;
    task_queue[task_count].state = 0;
    task_count++;
}

void remove_task(char *name) {
    for (int i = 0; i < task_count; i++) {
        if (strcmp(task_queue[i].name, name) == 0) {
            task_queue[i].state = 2;
            memmove(&task_queue[i], &task_queue[i+1], (task_count - i - 1) * sizeof(Task));
            task_count--;
            break;
        }
    }
}

void execute_next_task() {
    int i;
    for (i = 0; i < task_count; i++) {
        if (task_queue[i].state == 0 && task_queue[i].priority <= task_queue[task_count-1].priority) {
            task_queue[i].state = 1;
            printf("Executing task %s with priority %d...\n", task_queue[i].name, task_queue[i].priority);
            // Add your task execution logic here
            task_queue[i].state = 2;
            break;
        }
    }
}

int main() {
    add_task("Task1", 3);
    add_task("Task2", 1);
    add_task("Task3", 5);
    add_task("Task4", 2);
    add_task("Task5", 4);

    while (task_count > 0) {
        execute_next_task();
    }

    printf("All tasks have been executed.\n");

    return 0;
}

