#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

// Shared data structures
int shared_int = 0;
char shared_str[100] = "";

// Mutexes and semaphores
pthread_mutex_t shared_int_lock;
pthread_mutex_t shared_str_lock;
sem_t shared_int_sem;
sem_t shared_str_sem;

// Player struct
typedef struct player {
    char name[20];
    int score;
    pthread_t thread;
} player_t;

// Player pool
player_t players[10];

// Game state
int game_state = 0; // 0 = not started, 1 = running, 2 = finished

// Function to get a player by name
player_t *get_player_by_name(char *name) {
    for (int i = 0; i < 10; i++) {
        if (strcmp(players[i].name, name) == 0) {
            return &players[i];
        }
    }
    return NULL;
}

// Function for each player thread to run
void *player_thread(void *args) {
    player_t *player = (player_t *)args;

    // Wait for the game to start
    sem_wait(&shared_int_sem);

    // Play the game
    while (game_state == 1) {
        // Get the lock for the shared integer
        pthread_mutex_lock(&shared_int_lock);

        // Increment the shared integer
        shared_int++;

        // Release the lock for the shared integer
        pthread_mutex_unlock(&shared_int_lock);
    }

    // Increment the player's score
    player->score++;

    // Signal that the player has finished
    sem_post(&shared_str_sem);

    return NULL;
}

// Main function
int main() {
    // Initialize the mutexes and semaphores
    pthread_mutex_init(&shared_int_lock, NULL);
    pthread_mutex_init(&shared_str_lock, NULL);
    sem_init(&shared_int_sem, 0, 0);
    sem_init(&shared_str_sem, 0, 0);

    // Create the players
    for (int i = 0; i < 10; i++) {
        sprintf(players[i].name, "Player %d", i);
        players[i].score = 0;
        pthread_create(&players[i].thread, NULL, player_thread, &players[i]);
    }

    // Start the game
    sem_post(&shared_int_sem);

    // Wait for all players to finish
    for (int i = 0; i < 10; i++) {
        sem_wait(&shared_str_sem);
    }

    // Stop the game
    game_state = 2;

    // Print the results
    for (int i = 0; i < 10; i++) {
        printf("%s: %d\n", players[i].name, players[i].score);
    }

    // Destroy the mutexes and semaphores
    pthread_mutex_destroy(&shared_int_lock);
    pthread_mutex_destroy(&shared_str_lock);
    sem_destroy(&shared_int_sem);
    sem_destroy(&shared_str_sem);

    return 0;
}

