#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>

int main() {
    // Create a pipe to communicate between the processes
    int pipefd[2];
    if (pipe(pipefd) == -1) {
        perror("pipe");
        exit(EXIT_FAILURE);
    }

    // Fork a child process
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        exit(EXIT_FAILURE);
    }

    // If we're the parent process, write to the pipe
    if (pid == 0) {
        // Close the read end of the pipe (so the parent can't read it)
        close(pipefd[0]);

        // Write a message to the write end of the pipe
        write(pipefd[1], "Hello from the child!\n", strlen("Hello from the child!\n"));

        // Exit the child process
        exit(0);
    }

    // If we're the parent process, read from the pipe
    else {
        // Close the write end of the pipe (so the child can't write to it)
        close(pipefd[1]);

        // Read the message from the read end of the pipe
        char buf[100];
        int bytes_read = read(pipefd[0], buf, sizeof(buf));
        if (bytes_read == -1) {
            perror("read");
            exit(EXIT_FAILURE);
        }
        else {
            printf("Received message: %s\n", buf);
        }

        // Wait for the child process to finish
        int status;
        waitpid(pid, &status, 0);
        if (WIFEXITED(status)) {
            printf("Child process exited with status %d\n", WEXITSTATUS(status));
        }
        else if (WIFSIGNALED(status)) {
            printf("Child process was killed by a signal\n");
        }
        else {
            printf("Unknown child exit status: %d\n", status);
        }

        // Close the pipe and exit the parent process
        close(pipefd[0]);
        exit(EXIT_SUCCESS);
    }
}

