    maxValue = endValue;
}

real32 GameTimer::getValue(real32 t)
{
    if(!isFinished)
    {
        currentTime+=t;
        if(currentTime >= maxTime)
        {
            if(doesLoop)
            {
                currentTime = fmod(currentTime,maxTime);
            }else
            {
                currentTime = maxTime;
                isFinished=true;
            }
        }
    }

    return getInterpoleForTween(currentTime/maxTime);
}

bool GameTimer::hasFinished()
{
    return isFinished;
}

