    int arr[MAX_ARRAY_SIZE];
    srand(time(NULL));
    for (int i = 0; i < MAX_ARRAY_SIZE; i++) {
        arr[i] = rand() % 100;
    }

    // Print the unsorted array
    print_array(arr, MAX_ARRAY_SIZE);

    // Sort the array using bubble sort
    bubble_sort(arr, MAX_ARRAY_SIZE);

    // Print the sorted array
    print_array(arr, MAX_ARRAY_SIZE);

