} Map;

// Function to initialize the map
void initialize_map(Map *map) {
    map->data = (int **)malloc(map->height * sizeof(int *));
    for (int i = 0; i < map->height; i++) {
        map->data[i] = (int *)malloc(map->width * sizeof(int));
    }
    map->width = map->height;
}

