void draw_map(Map *map) {
    for (int i = 0; i < map->height; i++) {
        for (int j = 0; j < map->width; j++) {
            printf("%d ", map->data[i][j]);
        }
        printf("\n");
    }
}

// Function to move the player
void move_player(Player *player, Map *map) {
    int dx = 0, dy = 0;
    char command;

    printf("Enter your command (w, a, s, d): ");
    scanf(" %c", &command);

    switch (command) {
        case 'w':
            dy = -1;
            break;
        case 'a':
            dx = -1;
            break;
        case 's':
            dy = 1;
            break;
