    if (name_start == NULL) {
        printf("Error: name not found\n");
        exit(EXIT_FAILURE);
    }
    char *name_end = strstr(name_start, "\n");
    if (name_end == NULL) {
        printf("Error: name end not found\n");
        exit(EXIT_FAILURE);
