#include <stdio.h>
#include <stdlib.h>

#define MAX_ENTRIES 100
#define MAX_ENTRY_LENGTH 100

typedef struct {
    char name[MAX_ENTRY_LENGTH];
    int age;
    float salary;
} Employee;

typedef struct {
    int count;
    Employee entries[MAX_ENTRIES];
} Index;

void initializeIndex(Index* index) {
    index->count = 0;
}

int compareEntries(const void* a, const void* b) {
    Employee* employeeA = (Employee*)a;
    Employee* employeeB = (Employee*)b;

    if (employeeA->age < employeeB->age) {
        return -1;
    } else if (employeeA->age > employeeB->age) {
        return 1;
    } else {
        return 0;
    }
}

void addEmployee(Index* index, Employee employee) {
    if (index->count >= MAX_ENTRIES) {
        printf("Index is full.\n");
        return;
    }

    index->entries[index->count] = employee;
    index->count++;
}

void sortIndex(Index* index) {
    qsort(index->entries, index->count, sizeof(Employee), compareEntries);
}

void printIndex(Index* index) {
    for (int i = 0; i < index->count; i++) {
        Employee employee = index->entries[i];
        printf("%s %d %.2f\n", employee.name, employee.age, employee.salary);
    }
}

int main() {
    Index index;
    initializeIndex(&index);

    Employee employee1 = {"John", 25, 50000};
    Employee employee2 = {"Jane", 30, 60000};
    Employee employee3 = {"Bob", 20, 40000};

    addEmployee(&index, employee1);
    addEmployee(&index, employee2);
    addEmployee(&index, employee3);

    printf("Unsorted index:\n");
    printIndex(&index);

    sortIndex(&index);

    printf("\nSorted index:\n");
    printIndex(&index);

    return 0;
}

