// Define the structure of an item in the warehouse
typedef struct {
    int id;
    char name[50];
    int quantity;
    float price;
} Item;

// Define the structure of a warehouse
typedef struct {
    int num_items;
    Item items[MAX_NUM_ITEMS];
} Warehouse;

// Function to initialize a warehouse
void init_warehouse(Warehouse* w) {
    w->num_items = 0;
}

// Function to add an item to the warehouse
void add_item(Warehouse* w, int id, char* name, int quantity, float price) {
    if (w->num_items >= MAX_NUM_ITEMS) {
        printf("Error: Warehouse is full.\n");
        return;
    }

    Item item = {id, name, quantity, price};
    w->items[w->num_items++] = item;
}

// Function to remove an item from the warehouse
void remove_item(Warehouse* w, int id) {
    for (int i = 0; i < w->num_items; i++) {
        if (w->items[i].id == id) {
            w->num_items--;
            for (int j = i; j < w->num_items; j++) {
                w->items[j] = w->items[j+1];
            }
            break;
        }
    }
}

// Function to update the quantity of an item in the warehouse
void update_item_quantity(Warehouse* w, int id, int quantity) {
    for (int i = 0; i < w->num_items; i++) {
        if (w->items[i].id == id) {
            w->items[i].quantity = quantity;
            break;
        }
    }
}

// Function to display the contents of the warehouse
void display_warehouse(Warehouse* w) {
    printf("Warehouse Contents:\n");
    for (int i = 0; i < w->num_items; i++) {
        printf("ID: %d, Name: %s, Quantity: %d, Price: $%f\n", w->items[i].id, w->items[i].name, w->items[i].quantity, w->items[i].price);
    }
}

