    add_item(&w, 1, "Apples", 1000, 0.50);
    add_item(&w, 2, "Oranges", 500, 0.75);
    add_item(&w, 3, "Bananas", 2000, 0.25);

    display_warehouse(&w);

    update_item_quantity(&w, 1, 800);
    update_item_quantity(&w, 2, 400);

    display_warehouse(&w);

    remove_item(&w, 3);

    display_warehouse(&w);

    return 0;
}

