/*
 * File Backup System
 *
 * This program backs up files to a specified location
 * using a statistical approach.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define BUFFER_SIZE 1024
#define MAX_FILES 100

struct file_info {
  char name[BUFFER_SIZE];
  int size;
};

struct backup_info {
  char path[BUFFER_SIZE];
  int num_files;
  struct file_info files[MAX_FILES];
};

void print_usage(char *program_name) {
  printf("Usage: %s <file> <destination_dir>\n", program_name);
}

void backup_file(char *file_name, char *dest_dir) {
  FILE *fp;
  FILE *fp_dest;
  char buffer[BUFFER_SIZE];
  char dest_file[BUFFER_SIZE];
  int num_read;

  fp = fopen(file_name, "r");
  if (fp == NULL) {
    printf("Error opening file %s\n", file_name);
    return;
  }

  snprintf(dest_file, BUFFER_SIZE, "%s/%s", dest_dir, file_name);
  fp_dest = fopen(dest_file, "w");
  if (fp_dest == NULL) {
    printf("Error opening destination file %s\n", dest_file);
    fclose(fp);
    return;
  }

  while ((num_read = fread(buffer, 1, BUFFER_SIZE, fp)) > 0) {
    fwrite(buffer, 1, num_read, fp_dest);
  }

  fclose(fp);
  fclose(fp_dest);
}

int main(int argc, char *argv[]) {
  char *file_name;
  char *dest_dir;
  struct backup_info info;
  int i;

  if (argc != 3) {
    print_usage(argv[0]);
    return 1;
  }

  file_name = argv[1];
  dest_dir = argv[2];

  backup_file(file_name, dest_dir);

  return 0;
}

