  for(int x = 0; x < w; x++)
  {
    unsigned int random = getRandomUint();
    image.data[3 * w * y + 3 * x + 0] = random % 256;
    image.data[3 * w * y + 3 * x + 1] = (random >> 8) % 256;
    image.data[3 * w * y + 3 * x + 2] = (random >> 16) % 256;
  }

