#include <ncurses.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>

#define WIDTH 40
#define HEIGHT 20
#define ALIEN_COUNT 5

typedef struct {
    int x;
    int y;
} Object;

void draw_game(Object player, Object aliens[], int alien_alive[]) {
    clear();

    // Draw player
    mvprintw(player.y, player.x, "A");

    // Draw aliens
    for (int i = 0; i < ALIEN_COUNT; i++) {
        if (alien_alive[i]) 
            mvprintw(1, aliens[i].x, "V");
    }

    refresh();
}

void move_aliens(Object aliens[], int alien_alive[]) {
    for (int i = 0; i < ALIEN_COUNT; i++) {
        if (alien_alive[i] && rand() % 5 == 0)
            aliens[i].x += (rand() % 3) - 1; // Random movement
    }
}

int main() {
    srand(time(NULL));
    initscr();            // Start ncurses mode
    noecho();            // Don't echo pressed keys
    cbreak();            // Disable line buffering
    curs_set(0);         // Hide cursor
    nodelay(stdscr, TRUE); // Make getch non-blocking

    Object player = {WIDTH / 2, HEIGHT - 1}; // Player starting position
    Object aliens[ALIEN_COUNT];
    int alien_alive[ALIEN_COUNT] = {1, 1, 1, 1, 1}; // Aliens alive status

    for (int i = 0; i < ALIEN_COUNT; i++) {
        aliens[i].x = (i + 1) * (WIDTH / (ALIEN_COUNT + 1));
        aliens[i].y = 1;
    }

    while (1) {
        // Draw the game
        draw_game(player, aliens, alien_alive);

        // Handle player input
        int ch = getch();
        if (ch == 'q') break; // Quit game
        if (ch == KEY_LEFT && player.x > 0) player.x--;
        if (ch == KEY_RIGHT && player.x < WIDTH - 1) player.x++;

        // Move aliens
        move_aliens(aliens, alien_alive);

        // Add a delay
        usleep(100000);
    }

    endwin(); // End ncurses mode
    return 0;
}

