struct node {
    char *name;
    char *url;
    struct node *next;
};

struct plugin {
    char *name;
    char *description;
    char *author;
    struct node *nodes;
};

void recursion_start(struct plugin *plugin) {
    printf("Recursive Browser Plugin started: %s (%s)\n", plugin->name, plugin->description);
    if (plugin->nodes != NULL) {
        recursion_start(plugin->nodes);
    }
}

void recursion_end(struct plugin *plugin) {
    printf("Recursive Browser Plugin ended: %s (%s)\n", plugin->name, plugin->description);
    if (plugin->nodes != NULL) {
        recursion_end(plugin->nodes);
    }
}

void handle_signal(int sig) {
    printf("Caught signal %d, ending plugin\n", sig);
    recursion_end(NULL);
}

