        .name = "Recursive Browser Plugin",
        .description = "A plugin that recursively traverses the browsing history",
        .author = "Your Name",
        .nodes = NULL,
    };

    signal(SIGINT, handle_signal);

    recursion_start(&plugin);

    while (1) {
        // Wait for user input or a signal
        sleep(1);
    }

