//GPT-4o-mini DATASET v1.0 Category: Tic Tac Toe AI ; Style: optimized
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define SIZE 3

char board[SIZE][SIZE];
char player = 'X', opponent = 'O';

void initializeBoard() {
    for (int i = 0; i < SIZE; i++) {
        for (int j = 0; j < SIZE; j++) {
            board[i][j] = ' ';
        }
    }
}

void printBoard() {
    printf("\n");
    for (int i = 0; i < SIZE; i++) {
        for (int j = 0; j < SIZE; j++) {
            printf(" %c ", board[i][j]);
            if (j < SIZE - 1) printf("|");
        }
        printf("\n");
        if (i < SIZE - 1) {
            printf("---+---+---\n");
        }
    }
    printf("\n");
}

bool isMoveValid(int row, int col) {
    return (row >= 0 && row < SIZE && col >= 0 && col < SIZE && board[row][col] == ' ');
}

bool checkWin(char mark) {
    for (int i = 0; i < SIZE; i++) {
        if ((board[i][0] == mark && board[i][1] == mark && board[i][2] == mark) ||
            (board[0][i] == mark && board[1][i] == mark && board[2][i] == mark)) {
            return true;
        }
    }
    return (board[0][0] == mark && board[1][1] == mark && board[2][2] == mark) ||
           (board[0][2] == mark && board[1][1] == mark && board[2][0] == mark);
}

bool isBoardFull() {
    for (int i = 0; i < SIZE; i++) {
        for (int j = 0; j < SIZE; j++) {
            if (board[i][j] == ' ') return false;
        }
    }
    return true;
}

int minimax(int depth, bool isMaximizing) {
    if (checkWin(opponent)) return -1;
    if (checkWin(player)) return 1;
    if (isBoardFull()) return 0;

    if (isMaximizing) {
        int bestScore = -3;
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                if (isMoveValid(i, j)) {
                    board[i][j] = player;
                    int score = minimax(depth + 1, false);
                    board[i][j] = ' ';
                    bestScore = (score > bestScore) ? score : bestScore;
                }
            }
        }
        return bestScore;
    } else {
        int bestScore = 3;
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                if (isMoveValid(i, j)) {
                    board[i][j] = opponent;
                    int score = minimax(depth + 1, true);
                    board[i][j] = ' ';
                    bestScore = (score < bestScore) ? score : bestScore;
                }
            }
        }
        return bestScore;
    }
}

void bestMove() {
    int bestVal = -3;
    int moveRow = -1, moveCol = -1;

    for (int i = 0; i < SIZE; i++) {
        for (int j = 0; j < SIZE; j++) {
            if (isMoveValid(i, j)) {
                board[i][j] = player;
                int moveVal = minimax(0, false);
                board[i][j] = ' ';
                if (moveVal > bestVal) {
                    moveRow = i;
                    moveCol = j;
                    bestVal = moveVal;
                }
            }
        }
    }
    board[moveRow][moveCol] = player;
}

void playGame() {
    int row, col;
    while (true) {
        printBoard();

        if (isBoardFull()) {
            printf("It's a draw!\n");
            break;
        }

        printf("Your turn! Enter row and column (0, 1, or 2): ");
        scanf("%d %d", &row, &col);
        if (isMoveValid(row, col)) {
            board[row][col] = opponent;

            if (checkWin(opponent)) {
                printBoard();
                printf("You win!\n");
                break;
            }

            if (!isBoardFull()) {
                bestMove();
                if (checkWin(player)) {
                    printBoard();
                    printf("AI wins!\n");
                    break;
                }
            }
        } else {
            printf("Invalid move! Try again.\n");
        }
    }
}

int main() {
    initializeBoard();
    printf("Welcome to Tic Tac Toe!\n");
    playGame();
    return 0;
}

/** Helper function to return the index-th node in the linked list. */
SinglyListNode* getNode(int index) {
    SinglyListNode *cur = head;
    for (int i = 0; i &lt; index &amp;&amp; cur; ++i) {
        cur = cur-&gt;next;
    }
    return cur;
}
/** Helper function to return the last node in the linked list. */
SinglyListNode* getTail() {
    SinglyListNode *cur = head;
    while (cur &amp;&amp; cur-&gt;next) {
        cur = cur-&gt;next;
    }
    return cur;
}
/** Get the value of the index-th node in the linked list. If the index is invalid, return -1. */
int get(int index) {
    SinglyListNode *cur = getNode(index);
    return cur == NULL ? -1 : cur-&gt;val;
}


