#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_APPOINTMENTS 100
#define MAX_NAME_LENGTH 50
#define MINUTES_IN_DAY (24 * 60)

struct appointment {
    char name[MAX_NAME_LENGTH];
    time_t start_time;
    int duration;
};

struct appointment *appointments = NULL;
int num_appointments = 0;

void add_appointment(char *name, time_t start_time, int duration) {
    if (num_appointments >= MAX_APPOINTMENTS) {
        printf("Sorry, no more appointments can be added.\n");
        return;
    }

    struct appointment *new_appointment = malloc(sizeof(struct appointment));
    strcpy(new_appointment->name, name);
    new_appointment->start_time = start_time;
    new_appointment->duration = duration;

    appointments = realloc(appointments, sizeof(struct appointment) * ++num_appointments);
    appointments[num_appointments - 1] = *new_appointment;

    printf("Appointment added for %s at %s.\n", name, ctime(&start_time));
}

void remove_appointment(int index) {
    if (index >= num_appointments) {
        printf("Invalid appointment index.\n");
        return;
    }

    free(appointments[index].name);
    appointments[index] = appointments[--num_appointments];

    printf("Appointment removed.\n");
}

void list_appointments() {
    if (num_appointments == 0) {
        printf("No appointments scheduled.\n");
        return;
    }

    printf("Appointments:\n");
    for (int i = 0; i < num_appointments; i++) {
        printf("%s at %s (%d minutes)\n", appointments[i].name, ctime(&appointments[i].start_time), appointments[i].duration);
    }
}

int main() {
    srand(time(NULL));

    add_appointment("Juliet", time(NULL) + rand() % (MINUTES_IN_DAY * 2), 60);
    add_appointment("Romeo", time(NULL) + rand() % (MINUTES_IN_DAY * 2), 60);

    list_appointments();

    int choice;
    while (1) {
        printf("Enter choice:\n1. Add appointment\n2. Remove appointment\n3. List appointments\n4. Exit\n");
        scanf("%d", &choice);

        switch (choice) {
        case 1:
            char name[MAX_NAME_LENGTH];
            printf("Enter name: ");
            scanf("%s", name);
            add_appointment(name, time(NULL) + rand() % (MINUTES_IN_DAY * 2), 60);
            break;

        case 2:
            printf("Enter appointment index to remove: ");
            scanf("%d", &choice);
            remove_appointment(choice);
            break;

        case 3:
            list_appointments();
            break;

        case 4:
            exit(0);

        default:
            printf("Invalid choice.\n");
        }
    }

    return 0;
}

