#include "List.h"

List::List(Entry* entries, int len){
    sentinel = new Node;
    isX = true;
    sentinel->next = sentinel;
    sentinel->prev = sentinel;
    length = 0;

    insertAndCheckAll(entries, len);
}

List::List(Entry* entries, int len, bool x){
    sentinel = new Node;
    isX = x;
    sentinel->next = sentinel;
    sentinel->prev = sentinel;
    length = 0;

    insertAll(entries, len);
}

List::~List(){
    delete sentinel;
    sentinel = NULL;
}

void List::insertAll(Entry* entries, int len){
    for(int i = 0; i<len; i++)
        insert(entries+i);
}

void List::insertAndCheckAll(Entry* entries, int len){
    for(int i = 0; i<len; i++)
        insertAndCheck(entries+i);
}

List* List::split(bool first){
    List* newList;
    int len;
    Entry* newEntries;
    if(first){
        len = length/2;
        newEntries = new Entry[len];
        int i = 0;
        Node* cur = sentinel->next;

        while(cur!= getMedian()){
            newEntries[i].identifier = cur->data->identifier;
            newEntries[i].x = cur->data->x;
            newEntries[i].y = cur->data->y;
            cur = cur->next;
            i++;
        }
    }else{
        if(len%2 == 0)
            len = length-length/2-1;
        else
            len = length-length/2;
        newEntries = new Entry[len];

        Node* cur = getMedian()->next;
        int i = 0;
        while(cur!= sentinel){
            newEntries[i].identifier = cur->data->identifier;
            newEntries[i].x = cur->data->x;
            newEntries[i].y = cur->data->y;
            cur = cur->next;
            i++;
        }

    }

    newList = new List(newEntries, len, !isX);
    return newList;
}



Node* List::getMedian(){
    int medianIndex = length/2+1;
    Node* cur;
    cur = sentinel;
    for(int i = 0; i<medianIndex; i++)
        cur = cur->next;



    return cur;
}

Entry* List::remove(Node* toBeRemoved){
    if(toBeRemoved == NULL || toBeRemoved == sentinel)
        return NULL;

    toBeRemoved->prev->next = toBeRemoved->next;
    toBeRemoved->next->prev = toBeRemoved->prev;

    Entry* data = toBeRemoved->data;
    delete toBeRemoved;
    length--;
    return data;
}


void List::insertAndCheck(Entry* toInsert){
    Node* insertee = new Node;
    insertee->data = new Entry;
    insertee->data = toInsert;

    double posX = insertee->data->x;
    double posY = insertee->data->y;
    Node* cur = sentinel->next;

    double distX, distY;

    if(isX){
        while(cur != sentinel && cur->data->x < posX){
            distX = distance(cur->data->x, posX);
            distY = distance(cur->data->y, posY);
            if(distX <= 0.00001 && distY <= 0.00001)
                return;
            cur = cur->next;
        }
    }else{
        while(cur != sentinel && cur->data->y < posY){
            distX = distance(cur->data->x, posX);
            distY = distance(cur->data->y, posY);
            if(distX <= 0.00001 && distY <= 0.00001)
                return;
            cur = cur->next;
        }

    }

    if(cur == sentinel){
        sentinel->prev->next = insertee;
        insertee->prev = sentinel->prev;
        insertee->next = sentinel;
        sentinel->prev = insertee;
        length++;
        return;
    }

    distX = distance(cur->data->x, posX);
    distY = distance(cur->data->y, posY);
    if(distX <= 0.00001 && distY <= 0.00001)
        return;

    cur->prev->next = insertee;
    insertee->prev = cur->prev;
    insertee->next = cur;
    cur->prev = insertee;
    length++;
}

void List::insert(Entry* toInsert){
    Node* insertee = new Node;
    insertee->data = new Entry;
    insertee->data = toInsert;

    double posX = toInsert->x;
    double posY = toInsert->y;
    Node* cur = sentinel->next;

    if(isX){
        while(cur != sentinel && cur->data->x < posX)
            cur = cur->next;
    }else{
        while(cur != sentinel && cur->data->y < posY)
            cur = cur->next;  
    }


    cur->prev->next = insertee;
    insertee->prev = cur->prev;
    insertee->next = cur;
    cur->prev = insertee; 
    length++;
}

double List::distance(double a, double b){
    double dist = a-b;
    if(dist>=0)
        return dist;
    return -dist;
}

#include "Camera.h"
#include <iostream>


Camera::Camera(int x, int y, int width, int height)
{
	// set up the game viewport
	mViewport.X = x - width/2;
	mViewport.Y = y - height/2;
	mViewport.Width = width;
	mViewport.Height = height;
	mViewport.MinZ = 0.0f;		// cheeesy!
	mViewport.MaxZ = 1.0f;

	// middle of game area
	mPos.x = x;
	mPos.y = y;
	mViewportPos.x = x;
	mViewportPos.y = y;
	mWidth = width;
	mHeight = height;

	mActive = false;
	mDX = 0;
	mDY = 0;
}

Camera::~Camera()
{
	// dtor
	// release viewport
}

void Camera::activate(bool b)
{
	if(b)	{
		buildViewMatrix();
		buildProjectionMatrix();
		buildViewport();

		mActive = true;
	}
	else if(!b)
		mActive = false;
}

void Camera::buildViewMatrix(void)
{
	D3DXVECTOR3 pos(mPos.x, mPos.y, 1);
	D3DXVECTOR3 target(mPos.x, mPos.y, 0.0f);
	D3DXVECTOR3 up(0.0f, -1.0f, 0.0f);
	D3DXMatrixLookAtLH(&mView, &pos, &target, &up);
	gd3dDevice->SetTransform(D3DTS_VIEW, &mView);
}

void Camera::buildProjectionMatrix(void)
{
	// width & height
	D3DXMatrixOrthoLH(&mProj, mWidth, mHeight, 0, 1);
	gd3dDevice->SetTransform(D3DTS_PROJECTION, &mProj);
}

void Camera::buildViewport(void)
{
	gd3dDevice->SetViewport(&mViewport);
}

void Camera::move()
{
	// move the camera position
	if(getX() + mDX >= 600)
		mPos.x += mDX;
	else
		mPos.x = 600;

	mPos.y += mDY;

	mDX = 0;
	mDY = 0;

	// update the view transform matrix
	buildViewMatrix();
}

void Camera::addMovement(float dx, float dy)
{
	mDX += dx;
	mDY += dy;
}
void Camera::restore(void)
{
	mPos.x = mViewportPos.x;
	mPos.y = mViewportPos.y;
}

