void sha256_transform(SHA256_CTX *ctx, unsigned char *data) {
    unsigned int i, j, t1, t2, m[64];

    for (i = 0, j = 0; i < 16; ++i, j += 4) {
        m[i] = (data[j] << 24) | (data[j + 1] << 16) | (data[j + 2] << 8) | (data[j + 3]);
    }

    for (; i < 64; ++i) {
        m[i] = GAMMA_1(m[i - 2]) + m[i - 7] + GAMMA_0(m[i - 15]) + m[i - 16];
    }

    unsigned int a, b, c, d, e, f, g, h;
    a = ctx->state[0];
    b = ctx->state[1];
    c = ctx->state[2];
    d = ctx->state[3];
    e = ctx->state[4];
    f = ctx->state[5];
    g = ctx->state[6];
    h = ctx->state[7];

    for (i = 0; i < 64; ++i) {
        t1 = h + SIGMA_1(e) + CH(e, f, g) + k[i] + m[i];
        t2 = SIGMA_0(a) + MAJ(a, b, c);
        h = g;
        g = f;
        f = e;
        e = d + t1;
        d = c;
        c = b;
        b = a;
        a = t1 + t2;
    }

    ctx->state[0] += a;
    ctx->state[1] += b;
    ctx->state[2] += c;
    ctx->state[3] += d;
    ctx->state[4] += e;
    ctx->state[5] += f;
    ctx->state[6] += g;
    ctx->state[7] += h;
}

void sha256_init(SHA256_CTX *ctx) {
    ctx->datalen = 0;
    ctx->bitlen = 0;
    ctx->state[0] = 0x6a09e667;
    ctx->state[1] = 0xbb67ae85;
    ctx->state[2] = 0x3c6ef372;
    ctx->state[3] = 0xa54ff53a;
    ctx->state[4] = 0x510e527f;
    ctx->state[5] = 0x9b05688c;
    ctx->state[6] = 0x1f83d9ab;
    ctx->state[7] = 0x5be0cd19;
}

void sha256_update(SHA256_CTX *ctx, unsigned char *data, unsigned int len) {
    unsigned int i;

    for (i = 0; i < len; ++i) {
        ctx->data[ctx->datalen] = data[i];
        ctx->datalen++;
        if (ctx->datalen == BLOCK_SIZE) {
            sha256_transform(ctx, ctx->data);
            ctx->bitlen += 512;
            ctx->datalen = 0;
        }
    }
}

void sha256_final(SHA256_CTX *ctx, unsigned char *hash) {
    unsigned int i;

    i = ctx->datalen;

    if (ctx->datalen < 56) {
        ctx->data[i++] = 0x80;

        while (i < 56) {
            ctx->data[i++] = 0x00;
        }
    } else {
        ctx->data[i++] = 0x80;

        while (i < BLOCK_SIZE) {
            ctx->data[i++] = 0x00;
        }

        sha256_transform(ctx, ctx->data);
        memset(ctx->data, 0, 56);
    }

    unsigned long long bitlen = ctx->bitlen + ctx->datalen * 8;
    ctx->data[63] = bitlen;
    ctx->data[62] = bitlen >> 8;
    ctx->data[61] = bitlen >> 16;
    ctx->data[60] = bitlen >> 24;
    ctx->data[59] = bitlen >> 32;
    ctx->data[58] = bitlen >> 40;
    ctx->data[57] = bitlen >> 48;
    ctx->data[56] = bitlen >> 56;
    sha256_transform(ctx, ctx->data);
    for (i = 0; i < 4; ++i) {
        hash[i] = (ctx->state[0] >> (24 - i * 8)) & 0x000000ff;
        hash[i + 4] = (ctx->state[1] >> (24 - i * 8)) & 0x000000ff;
        hash[i + 8] = (ctx->state[2] >> (24 - i * 8)) & 0x000000ff;
        hash[i + 12] = (ctx->state[3] >> (24 - i * 8)) & 0x000000ff;
        hash[i + 16] = (ctx->state[4] >> (24 - i * 8)) & 0x000000ff;
        hash[i + 20] = (ctx->state[5] >> (24 - i * 8)) & 0x000000ff;
        hash[i + 24] = (ctx->state[6] >> (24 - i * 8)) & 0x000000ff;
        hash[i + 28] = (ctx->state[7] >> (24 - i * 8)) & 0x000000ff;
    }
}

int main() {
    SHA256_CTX ctx;
    unsigned char hash[HASH_SIZE];
    char plaintext[100];

    sha256_init(&ctx);

    printf("Enter the text to be hashed:\n");
    fgets(plaintext, 100, stdin);

    // Remove any new line characters from the input
    char *pos;
    if ((pos = strchr(plaintext, '\n')) != NULL) {
        *pos = '\0';
    }

    sha256_update(&ctx, (unsigned char *) plaintext, strlen(plaintext));
    sha256_final(&ctx, hash);

    printf("\nHashed value of '%s':\n", plaintext);

    for (int i = 0; i < HASH_SIZE; i++) {
        printf("%02x", hash[i]);
    }

    printf("\n");

    return 0;
}

