#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_SIZE 100

struct node {
    char *data;
    int count;
    struct node *next;
};

int main() {
    char str[MAX_SIZE];
    char *token;
    struct node *head = NULL;

    // Prompt user to enter a string
    printf("Enter a string: ");
    fgets(str, MAX_SIZE, stdin);

    // Remove newline character from string
    str[strcspn(str, "\n")] = '\0';

    // Count number of words in string
    token = strtok(str, " ");
    while (token!= NULL) {
        struct node *temp = head;

        // Check if word already exists in hash table
        while (temp!= NULL && strcmp(temp->data, token)!= 0) {
            temp = temp->next;
        }

        // If word exists, increment count
        if (temp!= NULL) {
            temp->count++;
        } else {
            // Otherwise, add new word to hash table
            struct node *new_node = (struct node *)malloc(sizeof(struct node));
            new_node->data = strdup(token);
            new_node->count = 1;
            new_node->next = head;
            head = new_node;
        }

        token = strtok(NULL, " ");
    }

    // Print hash table
    struct node *temp = head;
    while (temp!= NULL) {
        printf("%s: %d\n", temp->data, temp->count);
        temp = temp->next;
    }

    return 0;
}

//LLAMA2-13B DATASET v1.0 Category: Game of Life ; Style: random
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define WIDTH 50
#define HEIGHT 50

// Structure to represent a cell
typedef struct cell {
    int alive;   // Whether the cell is alive or not
    int born;   // Whether the cell was born this iteration
} cell_t;

// Function to create a 2D array of cells
cell_t** create_grid(int width, int height) {
    cell_t** grid = calloc(width, sizeof(cell_t*));
    for (int i = 0; i < width; i++) {
        grid[i] = calloc(height, sizeof(cell_t));
    }
    return grid;
}

// Function to update the cells
void update_grid(cell_t** grid) {
    for (int i = 0; i < WIDTH; i++) {
        for (int j = 0; j < HEIGHT; j++) {
            // Check if the cell is alive and has two or three alive neighbors
            if (grid[i][j].alive && (grid[i][j].born || grid[i][j-1].alive || grid[i][j+1].alive)) {
                // If so, leave the cell alive
                grid[i][j].alive = 1;
            } else {
                // If not, die
                grid[i][j].alive = 0;
            }
        }
    }
}

// Function to draw the grid
void draw_grid(cell_t** grid) {
    for (int i = 0; i < WIDTH; i++) {
        for (int j = 0; j < HEIGHT; j++) {
            if (grid[i][j].alive) {
                printf("O");
            } else {
                printf(".");
            }
        }
        printf("\n");
    }
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    // Create a 50x50 grid of cells
    cell_t** grid = create_grid(WIDTH, HEIGHT);

    // Initialize the cells with a 50% chance of being alive
    for (int i = 0; i < WIDTH; i++) {
        for (int j = 0; j < HEIGHT; j++) {
            grid[i][j].alive = (rand() % 2) == 0;
        }
    }

    // Update the grid for 100 iterations
    for (int i = 0; i < 100; i++) {
        update_grid(grid);
    }

    // Draw the grid
    draw_grid(grid);

    // Free the memory
    for (int i = 0; i < WIDTH; i++) {
        free(grid[i]);
    }
    free(grid);

    return 0;
}

