  int rows = 20;
  int cols = 20;
  char** grid = malloc(rows * sizeof(char*));
  for (int i = 0; i < rows; i++) {
    grid[i] = malloc(cols * sizeof(char));
    for (int j = 0; j < cols; j++) {
      grid[i][j] = ' ';
    }
  }

  // Initialize the grid with some random alive cells
  for (int i = 0; i < rows; i++) {
