// A unique C Socket programming example program in an excited style
#include <stdio.h>
#include <string.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    // Create a socket
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("Failed to create socket");
        return -1;
    }

    // Initialize the server address
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080);
    server_addr.sin_addr.s_addr = INADDR_ANY;

    // Bind the socket to the server address
    if (bind(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Failed to bind socket");
        return -1;
    }

    // Listen for incoming connections
    if (listen(sock, 3) < 0) {
        perror("Failed to listen for incoming connections");
        return -1;
    }

    // Accept incoming connections
    struct sockaddr_in client_addr;
    socklen_t client_addr_len = sizeof(client_addr);
    int client_sock = accept(sock, (struct sockaddr *)&client_addr, &client_addr_len);
    if (client_sock < 0) {
        perror("Failed to accept incoming connection");
        return -1;
    }

    // Read the request from the client
    char request[1024];
    int bytes_read = recv(client_sock, request, 1024, 0);
    if (bytes_read < 0) {
        perror("Failed to read request from client");
        return -1;
    }

    // Parse the request
    char method[1024];
    char url[1024];
    char version[1024];
    sscanf(request, "%s %s %s", method, url, version);

    // Print the request to the console
    printf("Received request: %s %s %s\n", method, url, version);

    // Send a response to the client
    char response[] = "HTTP/1.1 200 OK\r\n\r\nHello, world!";
    int bytes_sent = send(client_sock, response, strlen(response), 0);
    if (bytes_sent < 0) {
        perror("Failed to send response to client");
        return -1;
    }

    // Close the connection with the client
    close(client_sock);

    // Close the server socket
    close(sock);

    return 0;
}

//GPT-4o-mini DATASET v1.0 Category: Log analysis ; Style: post-apocalyptic
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LOG_SIZE 2048
#define MAX_ENTRIES 100
#define KEYWORD_SIZE 20

typedef struct {
    char entry[MAX_LOG_SIZE];
    int occurrences;
} LogEntry;

void analyze_logs(LogEntry logEntries[], int *entryCount, FILE *logFile) {
    char *keywords[] = {"attack", "disease", "famine", "betrayal", "collapse"};
    int keywordCount = sizeof(keywords) / sizeof(keywords[0]);

    char buffer[MAX_LOG_SIZE];
    while(fgets(buffer, sizeof(buffer), logFile)) {
        for(int i = 0; i < keywordCount; i++) {
            if(strstr(buffer, keywords[i])) {
                strcpy(logEntries[*entryCount].entry, keywords[i]);
                logEntries[*entryCount].occurrences += 1;
                (*entryCount)++;
            }
        }
    }
}

void print_summary(LogEntry logEntries[], int entryCount) {
    printf("Post-Apocalyptic Log Analysis Summary:\n");
    printf("========================================\n");
    for(int i = 0; i < entryCount; i++) {
        printf("Keyword: %s, Occurrences: %d\n", logEntries[i].entry, logEntries[i].occurrences);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <logfile>\n", argv[0]);
        return EXIT_FAILURE;
    }

    FILE *logFile = fopen(argv[1], "r");
    if (!logFile) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    LogEntry logEntries[MAX_ENTRIES] = {0};
    int entryCount = 0;

    analyze_logs(logEntries, &entryCount, logFile);
    fclose(logFile);

    print_summary(logEntries, entryCount);

    return EXIT_SUCCESS;
}

