// Function to display current state of board
void display_board() {
    printf("\n\t     0   1   2\n");
    printf("\t   -------------\n");
    for(int i = 0; i < 3; i++) {
        printf("\t%d  |", i);
        for(int j = 0; j < 3; j++)
            printf(" %c |", board[i][j]);
        printf("\n\t   -------------\n");
    }
}

// Function to check if game is over
int is_game_over() {
    // Check rows
    for(int i = 0; i < 3; i++) {
        if(board[i][0] == board[i][1] && board[i][1] == board[i][2] && board[i][0] != ' ')
            return 1;
    }
    // Check columns
    for(int j = 0; j < 3; j++) {
        if(board[0][j] == board[1][j] && board[1][j] == board[2][j] && board[0][j] != ' ')
            return 1;
    }
    // Check diagonals
    if(board[0][0] == board[1][1] && board[1][1] == board[2][2] && board[0][0] != ' ')
        return 1;
    if(board[0][2] == board[1][1] && board[1][1] == board[2][0] && board[0][2] != ' ')
        return 1;
    // Check for tie
    int tie_flag = 1;
    for(int i = 0; i < 3; i++) {
        for(int j = 0; j < 3; j++) {
            if(board[i][j] == ' ') {
                tie_flag = 0;
                break;
            }
        }
        if(tie_flag == 0)
            break;
    }
    if(tie_flag == 1)
        return 2;
    // Game not over yet
    return 0;
}

