#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define PI 3.14159265358979323846

// Define the mass and radius of the earth
#define EARTH_MASS 5.972e24 // kg
#define EARTH_RADIUS 6.371e6 // m

// Define the gravitational constant
#define G 6.674e-11 // m^3 kg^-1 s^-2

// Define the time step
#define DT 1.0 // s

// Define the number of particles
#define N 100

// Define the initial positions and velocities of the particles
double x[N], y[N], z[N];
double vx[N], vy[N], vz[N];

// Initialize the positions and velocities of the particles
void init_particles() {
  for (int i = 0; i < N; i++) {
    // Randomize the initial positions of the particles
    x[i] = (double)rand() / RAND_MAX * 2 * EARTH_RADIUS - EARTH_RADIUS;
    y[i] = (double)rand() / RAND_MAX * 2 * EARTH_RADIUS - EARTH_RADIUS;
    z[i] = (double)rand() / RAND_MAX * 2 * EARTH_RADIUS - EARTH_RADIUS;

    // Randomize the initial velocities of the particles
    vx[i] = (double)rand() / RAND_MAX * 100.0;
    vy[i] = (double)rand() / RAND_MAX * 100.0;
    vz[i] = (double)rand() / RAND_MAX * 100.0;
  }
}

// Calculate the gravitational force between two particles
void calc_force(int i, int j) {
  // Calculate the distance between the two particles
  double dx = x[i] - x[j];
  double dy = y[i] - y[j];
  double dz = z[i] - z[j];
  double r = sqrt(dx * dx + dy * dy + dz * dz);

  // Calculate the gravitational force between the two particles
  double f = G * EARTH_MASS * EARTH_MASS / (r * r);

  // Calculate the direction of the gravitational force
  double fx = f * dx / r;
  double fy = f * dy / r;
  double fz = f * dz / r;

  // Add the gravitational force to the particles
  vx[i] += fx * DT / EARTH_MASS;
  vy[i] += fy * DT / EARTH_MASS;
  vz[i] += fz * DT / EARTH_MASS;
}

// Update the positions and velocities of the particles
void update_particles() {
  // Update the positions of the particles
  for (int i = 0; i < N; i++) {
    x[i] += vx[i] * DT;
    y[i] += vy[i] * DT;
    z[i] += vz[i] * DT;
  }

  // Update the velocities of the particles
  for (int i = 0; i < N; i++) {
    for (int j = i + 1; j < N; j++) {
      calc_force(i, j);
    }
  }
}

// Main function
int main() {
  // Initialize the particles
  init_particles();

  // Simulate the motion of the particles
  for (int i = 0; i < 1000; i++) {
    update_particles();
  }

  // Print the final positions of the particles
  for (int i = 0; i < N; i++) {
    printf("%f %f %f\n", x[i], y[i], z[i]);
  }

  return 0;
}

