#include <iostream>

using namespace std;

int
extended_euclidean_algorithm(int a, int b, int *prev_x, int *prev_y)
{
    int x, y, t, q;
    x = *prev_y = 0;
    y = *prev_x = 1;
    while (b != 0) {
	q = a / b;
	t = b;
	b = a % b;
	a = t;
	t = *prev_x;
	*prev_x = x;
	x = t - q * x;
	t = *prev_y;
	*prev_y = y;
	y = t - q*y;
    }
    return a;
}

int 
gcd(int a, int b)
{
    int t;
    while (b != 0) {
	t = b;
	b = a % b;
	a = t;
    }
    return a;
}

int main()
{
    int a = 4;
    int b = 3;
    int x, y;
    x = y = 0;
    cout << gcd(a, b) << endl;
    extended_euclidean_algorithm(a, b, &x, &y);
    cout << "x = " << x << " y = " << y << endl;

    a = 10;
    b = 5;
    cout << gcd(a, b) << endl;
    extended_euclidean_algorithm(a, b, &x, &y);
