#define MAX_ROWS 10
#define MAX_COLS 10
#define MAX_VAL 100

// Function to print the game board
void print_board(int board[MAX_ROWS][MAX_COLS]) {
    for (int i = 0; i < MAX_ROWS; i++) {
        for (int j = 0; j < MAX_COLS; j++) {
            printf("%2d ", board[i][j]);
        }
        printf("\n");
    }
}

// Function to generate a random number
int generate_random_number(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Function to get user input
int get_user_input() {
    int input;
    printf("Enter a row and column (e.g. 2,3): ");
    scanf("%d,%d", &input, &input);
    return input;
}

// Function to update the board
void update_board(int board[MAX_ROWS][MAX_COLS], int row, int col, int value) {
    board[row][col] = value;
}

// Function to check if the game is over
int is_game_over(int board[MAX_ROWS][MAX_COLS]) {
    for (int i = 0; i < MAX_ROWS; i++) {
        for (int j = 0; j < MAX_COLS; j++) {
            if (board[i][j] == 0) {
                return 0;
            }
        }
    }
    return 1;
}

// Function to play the game
void play_game(int board[MAX_ROWS][MAX_COLS]) {
    int row, col, value;

    // Initialize the board
    for (int i = 0; i < MAX_ROWS; i++) {
        for (int j = 0; j < MAX_COLS; j++) {
            board[i][j] = generate_random_number(1, MAX_VAL);
        }
    }

    // Print the initial board
    print_board(board);

    // Play the game
    while (!is_game_over(board)) {
        // Get the user input
        row = get_user_input();
        col = get_user_input();

        // Update the board
        update_board(board, row, col, 0);

        // Print the updated board
        print_board(board);
    }

    // Print the final board
    printf("Game Over!\n");
    print_board(board);
}

int main() {
    // Initialize the board
    int board[MAX_ROWS][MAX_COLS];

    // Play the game
    play_game(board);

    return 0;
}

