//GEMINI-pro DATASET v1.0 Category: Procedurally Generated Maze ; Style: recursive
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Constants
#define MAZE_SIZE 10
#define NORTH 0
#define EAST 1
#define SOUTH 2
#define WEST 3

// Function prototypes
int generateMaze(int maze[MAZE_SIZE][MAZE_SIZE]);
void printMaze(int maze[MAZE_SIZE][MAZE_SIZE]);

// Main function
int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Create the maze
    int maze[MAZE_SIZE][MAZE_SIZE];
    generateMaze(maze);

    // Print the maze
    printMaze(maze);

    return 0;
}

// Function to generate a maze
int generateMaze(int maze[MAZE_SIZE][MAZE_SIZE]) {
    // Initialize the maze to all walls
    for (int i = 0; i < MAZE_SIZE; i++) {
        for (int j = 0; j < MAZE_SIZE; j++) {
            maze[i][j] = 1;
        }
    }

    // Set the starting point
    int x = 0;
    int y = 0;

    // Recursively carve the maze
    carveMaze(maze, x, y);

    return 0;
}

// Function to carve the maze
int carveMaze(int maze[MAZE_SIZE][MAZE_SIZE], int x, int y) {
    // If we are at the end of the maze, return
    if (x == MAZE_SIZE - 1 && y == MAZE_SIZE - 1) {
        return 0;
    }

    // Mark the current cell as visited
    maze[x][y] = 0;

    // Choose a random direction to carve
    int direction = rand() % 4;

    // Carve the maze in the chosen direction
    switch (direction) {
        case NORTH:
            if (x > 0 && maze[x - 1][y] == 1) {
                carveMaze(maze, x - 1, y);
            }
            break;
        case EAST:
            if (y < MAZE_SIZE - 1 && maze[x][y + 1] == 1) {
                carveMaze(maze, x, y + 1);
            }
            break;
        case SOUTH:
            if (x < MAZE_SIZE - 1 && maze[x + 1][y] == 1) {
                carveMaze(maze, x + 1, y);
            }
            break;
        case WEST:
            if (y > 0 && maze[x][y - 1] == 1) {
                carveMaze(maze, x, y - 1);
            }
            break;
    }

    return 0;
}

// Function to print the maze
void printMaze(int maze[MAZE_SIZE][MAZE_SIZE]) {
    for (int i = 0; i < MAZE_SIZE; i++) {
        for (int j = 0; j < MAZE_SIZE; j++) {
            if (maze[i][j] == 1) {
                printf("#");
            } else {
                printf(" ");
            }
        }
        printf("\n");
    }
}

//GPT-4o-mini DATASET v1.0 Category: Movie Rating System ; Style: safe
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_MOVIES 100
#define MAX_TITLE_LENGTH 100
#define MAX_REVIEW_LENGTH 500

typedef struct {
    char title[MAX_TITLE_LENGTH];
    int year;
    float rating;
    char review[MAX_REVIEW_LENGTH];
} Movie;

// Function prototypes
void addMovie(Movie movies[], int *count);
void viewMovies(Movie movies[], int count);
void searchMovie(Movie movies[], int count);
void deleteMovie(Movie movies[], int *count);
void displayMenu();

int main() {
    Movie movies[MAX_MOVIES];
    int count = 0;
    int choice;

    while (1) {
        displayMenu();
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                addMovie(movies, &count);
                break;
            case 2:
                viewMovies(movies, count);
                break;
            case 3:
                searchMovie(movies, count);
                break;
            case 4:
                deleteMovie(movies, &count);
                break;
            case 5:
                printf("Exiting the Movie Rating System.\n");
                exit(0);
            default:
                printf("Invalid choice. Please try again.\n");
        }
    }

    return 0;
}

void displayMenu() {
    printf("\n--- Movie Rating System ---\n");
    printf("1. Add Movie\n");
    printf("2. View Movies\n");
    printf("3. Search Movie\n");
    printf("4. Delete Movie\n");
    printf("5. Exit\n");
}

void addMovie(Movie movies[], int *count) {
    if (*count >= MAX_MOVIES) {
        printf("Movie list is full. Can't add more movies.\n");
        return;
    }

    printf("Enter movie title: ");
    getchar(); // To consume the newline character left by scanf
    fgets(movies[*count].title, MAX_TITLE_LENGTH, stdin);
    strtok(movies[*count].title, "\n"); // Remove newline character

    printf("Enter release year: ");
    scanf("%d", &movies[*count].year);

    printf("Enter your rating (0-10): ");
    scanf("%f", &movies[*count].rating);

    printf("Enter your review: ");
    getchar();
    fgets(movies[*count].review, MAX_REVIEW_LENGTH, stdin);
    strtok(movies[*count].review, "\n"); // Remove newline character

    (*count)++;
    printf("Movie added successfully!\n");
}

void viewMovies(Movie movies[], int count) {
    if (count == 0) {
        printf("No movies to display.\n");
        return;
    }

    printf("\n--- Movie List ---\n");
    for (int i = 0; i < count; i++) {
        printf("Title: %s\n", movies[i].title);
        printf("Year: %d\n", movies[i].year);
        printf("Rating: %.1f\n", movies[i].rating);
        printf("Review: %s\n\n", movies[i].review);
    }
