//GPT-4o-mini DATASET v1.0 Category: Threading Library Implementation ; Style: systematic
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_THREADS 5
#define BUFFER_SIZE 10

// Struct for shared buffer
typedef struct {
    int buffer[BUFFER_SIZE];
    int count;
    int in;
    int out;
    pthread_mutex_t lock;
    pthread_cond_t empty;
    pthread_cond_t full;
} SharedBuffer;

// Function declarations
void* producer(void* arg);
void* consumer(void* arg);
void initializeBuffer(SharedBuffer* buffer);
void cleanupBuffer(SharedBuffer* buffer);

int main() {
    pthread_t producers[MAX_THREADS], consumers[MAX_THREADS];
    SharedBuffer sharedBuffer;
    int i;

    // Initialize the shared buffer
    initializeBuffer(&sharedBuffer);

    // Create producer threads
    for (i = 0; i < MAX_THREADS; i++) {
        if (pthread_create(&producers[i], NULL, producer, (void*)&sharedBuffer) != 0) {
            fprintf(stderr, "Error creating producer thread %d\n", i);
            exit(EXIT_FAILURE);
        }
    }

    // Create consumer threads
    for (i = 0; i < MAX_THREADS; i++) {
        if (pthread_create(&consumers[i], NULL, consumer, (void*)&sharedBuffer) != 0) {
            fprintf(stderr, "Error creating consumer thread %d\n", i);
            exit(EXIT_FAILURE);
        }
    }

    // Wait for all threads to finish
    for (i = 0; i < MAX_THREADS; i++) {
        pthread_join(producers[i], NULL);
        pthread_join(consumers[i], NULL);
    }

    // Clean up resources
    cleanupBuffer(&sharedBuffer);

    printf("All threads have completed.\n");
    return 0;
}

// Producer thread function
void* producer(void* arg) {
    SharedBuffer* buffer = (SharedBuffer*)arg;
    int item;

    for (int i = 0; i < 20; i++) { // Produce 20 items
        item = rand() % 100; // Create a random item

        pthread_mutex_lock(&buffer->lock);
        while (buffer->count == BUFFER_SIZE) {
            pthread_cond_wait(&buffer->full, &buffer->lock);
        }

        // Add item to the buffer
        buffer->buffer[buffer->in] = item;
        buffer->in = (buffer->in + 1) % BUFFER_SIZE;
        buffer->count++;
        printf("Produced: %d\n", item);

        // Signal that the buffer is not empty
        pthread_cond_signal(&buffer->empty);
        pthread_mutex_unlock(&buffer->lock);
        usleep(100000); // Sleep for a while
    }
    return NULL;
}

// Consumer thread function
void* consumer(void* arg) {
    SharedBuffer* buffer;

    buffer = (SharedBuffer*)arg;

    for (int i = 0; i < 20; i++) { // Consume 20 items
        pthread_mutex_lock(&buffer->lock);
        while (buffer->count == 0) {
            pthread_cond_wait(&buffer->empty, &buffer->lock);
        }

        // Remove item from the buffer
        int item = buffer->buffer[buffer->out];
        buffer->out = (buffer->out + 1) % BUFFER_SIZE;
        buffer->count--;
        printf("Consumed: %d\n", item);

        // Signal that the buffer is not full
        pthread_cond_signal(&buffer->full);
        pthread_mutex_unlock(&buffer->lock);
        usleep(150000); // Sleep for a while
    }
    return NULL;
}

// Initialize the shared buffer
void initializeBuffer(SharedBuffer* buffer) {
    buffer->count = 0;
    buffer->in = 0;
    buffer->out = 0;
    pthread_mutex_init(&buffer->lock, NULL);
    pthread_cond_init(&buffer->empty, NULL);
    pthread_cond_init(&buffer->full, NULL);
}

// Cleanup the shared buffer resources
void cleanupBuffer(SharedBuffer* buffer) {
    pthread_mutex_destroy(&buffer->lock);
    pthread_cond_destroy(&buffer->empty);
    pthread_cond_destroy(&buffer->full);
}

