// Appointment Scheduler
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

// Struct to store appointment information
typedef struct {
    char name[50];
    char time[10];
    char date[10];
} Appointment;

// Function to display appointment information
void displayAppointment(Appointment appt) {
    printf("Appointment with %s at %s on %s\n", appt.name, appt.time, appt.date);
}

// Function to add appointment to a list
void addAppointment(Appointment appt, Appointment *list, int *count) {
    list[*count] = appt;
    *count += 1;
}

// Function to delete appointment from a list
void deleteAppointment(int index, Appointment *list, int *count) {
    for (int i = index; i < *count - 1; i++) {
        list[i] = list[i + 1];
    }
    *count -= 1;
}

// Function to search for appointment by name
int searchAppointment(char *name, Appointment *list, int count) {
    for (int i = 0; i < count; i++) {
        if (strcmp(list[i].name, name) == 0) {
            return i;
        }
    }
    return -1;
}

int main() {
    // Create a list of appointments
    Appointment appointments[10];
    int count = 0;

    // Add some appointments
    Appointment appt1 = {"John Doe", "10:00 AM", "10/10/2022"};
    addAppointment(appt1, appointments, &count);
    Appointment appt2 = {"Jane Doe", "12:00 PM", "10/10/2022"};
    addAppointment(appt2, appointments, &count);
    Appointment appt3 = {"Bob Johnson", "2:00 PM", "10/10/2022"};
    addAppointment(appt3, appointments, &count);

    // Display all appointments
    for (int i = 0; i < count; i++) {
        displayAppointment(appointments[i]);
    }

    // Search for an appointment by name
    int index = searchAppointment("John Doe", appointments, count);
    if (index != -1) {
        printf("Found appointment at index %d\n", index);
    } else {
        printf("Appointment not found\n");
    }

    // Delete an appointment
    deleteAppointment(1, appointments, &count);

    // Display all appointments again
    for (int i = 0; i < count; i++) {
        displayAppointment(appointments[i]);
    }

    return 0;
}

