#include <stdio.h>
#include <stdlib.h>

// Function to compress input string using RLE (Run Length Encoding)
char* compress(char* input) {
    int count = 1;
    char* output = malloc(sizeof(char) * strlen(input));
    int pos = 0;

    while (*(input + pos)!= '\0') {
        if (*(input + pos) == *(input + pos - 1)) {
            count++;
            if (count > 10) {
                sprintf(output + pos, "%c%d", *(input + pos), count);
                count = 1;
            }
        } else {
            sprintf(output + pos, "%c%d", *(input + pos), count);
            pos++;
            count = 1;
        }
    }
    sprintf(output + pos, "%c%d", *(input + pos), count);

    return output;
}

// Function to decompress compressed string using RLE
char* decompress(char* input) {
    int count = 0;
    char* output = malloc(sizeof(char) * strlen(input));
    int pos = 0;

    while (*(input + pos)!= '\0') {
        if (input[pos]!= '\0') {
            sprintf(output + pos, "%c", input[pos]);
            pos++;
        } else {
            count = atoi(input + pos);
            pos += 2;

            for (int i = 0; i < count; i++) {
                sprintf(output + pos, "%c", input[pos]);
                pos++;
            }
        }
    }

    return output;
}

int main() {
    char* input = "aaabbbcccddd";
    char* compressed = compress(input);
    printf("Compressed string: %s\n", compressed);
    free(compressed);
    compressed = decompress(compressed);
    printf("Decompressed string: %s\n", compressed);
    free(compressed);
    return 0;
}

//GPT-4o-mini DATASET v1.0 Category: Percolation Simulator ; Style: romantic
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define GRID_SIZE 20
#define EMPTY ' '
#define WATER '~'
#define BLOCKED '#'

typedef struct {
    char grid[GRID_SIZE][GRID_SIZE];
    int visited[GRID_SIZE][GRID_SIZE];
} PercolationGrid;

void initialize_grid(PercolationGrid *grid) {
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < GRID_SIZE; j++) {
            grid->grid[i][j] = (rand() % 5 == 0) ? BLOCKED : EMPTY; // 1 in 5 chance of a block
            grid->visited[i][j] = 0;
        }
    }
}

void print_grid(PercolationGrid *grid) {
    printf("\nCurrent Grid State:\n");
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < GRID_SIZE; j++) {
            printf("%c ", grid->grid[i][j]);
        }
        printf("\n");
    }
}

int is_safe(PercolationGrid *grid, int x, int y) {
    return (x >= 0 && x < GRID_SIZE && y >= 0 && y < GRID_SIZE && 
            grid->grid[x][y] != BLOCKED && !grid->visited[x][y]);
}

void romantic_percolation(PercolationGrid *grid, int x, int y) {
    if (!is_safe(grid, x, y)) return;

    grid->visited[x][y] = 1;

    // Imbue our passion for the water
    if (x == GRID_SIZE - 1) {
        grid->grid[x][y] = WATER;
        printf("Water flows through with love to the bottom at (%d, %d)!\n", x, y);
    }

    // Water's path through the heart of the grid
    romantic_percolation(grid, x + 1, y); // Down
    romantic_percolation(grid, x - 1, y); // Up
    romantic_percolation(grid, x, y + 1); // Right
    romantic_percolation(grid, x, y - 1); // Left
}

void start_percolation(PercolationGrid *grid) {
    printf("Let us embark on a journey of pure percolation...\n");
    for (int j = 0; j < GRID_SIZE; j++) {
        if (grid->grid[0][j] == EMPTY) {
            romantic_percolation(grid, 0, j);
        }
    }
}

int main() {
    srand(time(NULL));
    PercolationGrid grid;

    initialize_grid(&grid);
    print_grid(&grid);
    start_percolation(&grid);
    print_grid(&grid);

    printf("\nThus concludes our tale of water and love, forever united in the grid of life.\n");
    return 0;
}

