void DichLenXoayVongCacHangTrongMaTran(int a[][MAX], int dong, int cot)
{
    // Gán mảng phụ vào hàng đầu
    int temp[MAX];
    for(int i = 0; i < cot; i++)
    {
        temp[i] = a[0][i];
    }

    // Gán từ trên xuống
    for(int i = 0; i < dong - 1; i++)
    {
        for(int j = 0; j < cot; j++)
        {
            a[i][j] = a[i + 1][j];
        }
    }
    // Dùng mảng phụ lưu lại hàng cuối
    for(int i = 0; i < cot; i++)
    {
        a[dong - 1][i] = temp[i];
    }
