  glEnable(GL_LINE_SMOOTH);
  glScalef(global::scale.x, global::scale.y, 0.0f);

    // Draw points
    glVertexPointer(2, GL_FLOAT, 0, loop);
    glDrawArrays(GL_LINE_LOOP, 0, n_pts);

  // Shut down
  glDisable(GL_LINE_SMOOTH);
  glColor4f(1, 1, 1, 1);
