#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define BOARD_SIZE 30
#define PLAYER_COUNT 2

// Function prototypes
void print_board(int positions[], int player_count);
int roll_dice();
int check_special_space(int position);
void play_game();

int main() {
    // Seed the random number generator
    srand(time(NULL));

    play_game();

    return 0;
}

// Function to print the board and player positions
void print_board(int positions[], int player_count) {
    printf("\nBoard Positions:\n");
    for (int i = 1; i <= BOARD_SIZE; i++) {
        if (i == 1) {
            printf("Start ");
        } else if (i == BOARD_SIZE) {
            printf("Finish ");
        } else {
            printf("%d ", i);
        }

        for (int j = 0; j < player_count; j++) {
            if (positions[j] == i) {
                printf("[P%d] ", j + 1);
            }
        }
        printf("\n");
    }
}

// Function to simulate rolling two dice
int roll_dice() {
    int die1 = (rand() % 6) + 1;
    int die2 = (rand() % 6) + 1;
    return die1 + die2;
}

// Function to check if the player lands on a special space
int check_special_space(int position) {
    switch (position) {
        case 5:
            printf("Landed on a bonus space! Move ahead 2 spaces!\n");
            return 2;  // Bonus move
        case 10:
            printf("Landed on a penalty space! Move back 3 spaces!\n");
            return -3; // Penalty move
        case 20:
            printf("Landed on a special space! Roll again!\n");
            return 0;  // No change, just roll again
        default:
            return 0;  // No special action
    }
}

// Function to play the game
void play_game() {
    int positions[PLAYER_COUNT] = {1, 1}; // Starting positions for each player
    int current_player = 0; // Start with player 1
    int game_over = 0;

    // Game loop
    while (!game_over) {
        print_board(positions, PLAYER_COUNT);
        printf("Player %d's turn. Press Enter to roll the dice...", current_player + 1);
        getchar(); // Wait for Enter key
        int roll = roll_dice();
        printf("Player %d rolled: %d\n", current_player + 1, roll);

        positions[current_player] += roll;

        // Check if the player landed beyond the finish line
        if (positions[current_player] > BOARD_SIZE) {
            positions[current_player] = BOARD_SIZE; // Snap to finish line
        }

        // Check for special space
        int special_move = check_special_space(positions[current_player]);
        positions[current_player] += special_move;

        // Check if the player has reached the finish line
        if (positions[current_player] >= BOARD_SIZE) {
            printf("Player %d has reached the finish line! Player %d wins!\n", current_player + 1, current_player + 1);
            game_over = 1; // End the game
        }

        // Switch players
        current_player = (current_player + 1) % PLAYER_COUNT;
    }
}

