void TimMaPhuong(int **a, int m, int n)
{
	int dem = 0;
	for(int i = 0; i < m; i++)
	{
		for(int j = 0; j < n; j++)
		{
			if(i > m-3)
				break;

			else
			{
				if(j <= n-3)
				{
					int size;
					if(m-i > n-j)
						size = n-j;
					else
						size = m-i;
					while(size > 2)
					{
						int **b;
						b = new int* [size];
						for (int row = 0; row < size; row++)
							*(b + row) = new int[size];
						for (int row = 0; row < size; row++)
						{
							for (int column = 0; column < size; column++)
							{

								*(*(b + row) + column) = *(*(a+(row+i))+(column+j));
							}
						}
