/*
 * Password Strength Checker
 *
 * A sophisticated password strength checker that checks the strength of a password.
 * The program uses a combination of rules to check the password strength.
 */

#include <stdio.h>
#include <string.h>

// Function to check the password strength
int check_password_strength(char *password) {
  // Check if the password is at least 8 characters long
  if (strlen(password) < 8) {
    printf("Password too short!\n");
    return 0;
  }

  // Check if the password contains at least one uppercase letter
  if (!strpbrk(password, "ABCDEFGHIJKLMNOPQRSTUVWXYZ")) {
    printf("Password must contain at least one uppercase letter!\n");
    return 0;
  }

  // Check if the password contains at least one lowercase letter
  if (!strpbrk(password, "abcdefghijklmnopqrstuvwxyz")) {
    printf("Password must contain at least one lowercase letter!\n");
    return 0;
  }

  // Check if the password contains at least one number
  if (!strpbrk(password, "0123456789")) {
    printf("Password must contain at least one number!\n");
    return 0;
  }

  // Check if the password contains at least one special character
  if (!strpbrk(password, "!@#$%^&*()_+-=[]{}|;:',./<>?")) {
    printf("Password must contain at least one special character!\n");
    return 0;
  }

  // Check if the password is a valid email address
  if (strstr(password, "@")) {
    printf("Password cannot be an email address!\n");
    return 0;
  }

  // Check if the password is a valid URL
  if (strstr(password, "http://") || strstr(password, "https://")) {
    printf("Password cannot be a URL!\n");
    return 0;
  }

  // Check if the password is a valid IP address
  if (inet_addr(password)) {
    printf("Password cannot be an IP address!\n");
    return 0;
  }

  // If all the rules are met, return 1
  return 1;
}

int main() {
  // Get the password from the user
  char password[100];
  printf("Enter password: ");
  scanf("%99s", password);

  // Check the password strength
  if (check_password_strength(password)) {
    printf("Password is strong!\n");
  } else {
    printf("Password is weak!\n");
  }

  return 0;
}

