#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>

#define PORT 8080
#define MAX_BUFFER_SIZE 1024

void start_server(int port) {
  int server_fd, client_fd;
  struct sockaddr_in server_address, client_address;
  socklen_t client_address_len = sizeof(client_address);

  server_fd = socket(AF_INET, SOCK_STREAM, 0);
  if (server_fd == -1) {
    perror("socket");
    exit(EXIT_FAILURE);
  }

  memset(&server_address, 0, sizeof(server_address));
  server_address.sin_family = AF_INET;
  server_address.sin_addr.s_addr = htonl(INADDR_ANY);
  server_address.sin_port = htons(port);

  if (bind(server_fd, (struct sockaddr*)&server_address, sizeof(server_address)) == -1) {
    perror("bind");
    exit(EXIT_FAILURE);
  }

  if (listen(server_fd, 1) == -1) {
    perror("listen");
    exit(EXIT_FAILURE);
  }

  printf("Server started on port %d\n", port);

  while (1) {
    client_fd = accept(server_fd, (struct sockaddr*)&client_address, &client_address_len);
    if (client_fd == -1) {
      perror("accept");
      continue;
    }

    char buffer[MAX_BUFFER_SIZE];
    memset(buffer, 0, MAX_BUFFER_SIZE);

    int bytes_read = read(client_fd, buffer, MAX_BUFFER_SIZE);
    if (bytes_read == -1) {
      perror("read");
      continue;
    }

    if (strcmp(buffer, "turn on the light") == 0) {
      printf("Received command to turn on the light\n");
      // Turn on the light
    } else if (strcmp(buffer, "turn off the light") == 0) {
      printf("Received command to turn off the light\n");
      // Turn off the light
    } else {
      printf("Received unknown command\n");
    }

    close(client_fd);
  }
}

int main(int argc, char **argv) {
  if (argc != 2) {
    fprintf(stderr, "Usage: %s <port>\n", argv[0]);
    exit(EXIT_FAILURE);
  }

  int port = atoi(argv[1]);
  if (port <= 0) {
    fprintf(stderr, "Invalid port number\n");
    exit(EXIT_FAILURE);
  }

  start_server(port);

  return 0;
}

