    strcpy(newEntry->entry, entry);
    newEntry->next = head;
    head = newEntry;
}

void viewEntries() {
    DiaryEntry *current = head;

    if (head == NULL) {
        printf("Your digital diary is empty.\n");
        return;
    }

    printf("\nDigital Diary Entries:\n");
    while (current != NULL) {
        printf("%s:\n%s\n", current->name, current->entry);
        current = current->next;
    }
}

void deleteEntry(const char *name) {
    DiaryEntry *previous = NULL;
    DiaryEntry *current = head;

    while (current != NULL && strcmp(current->name, name) != 0) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        printf("Error: Entry not found.\n");
        return;
    }

    if (previous == NULL) {
        head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
}

int main() {
    char command[10];
    char name[MAX_NAME_LENGTH];
    char entry[MAX_ENTRY_LENGTH];

    while (1) {
        printf("\nDigital Diary > ");
        scanf("%s", command);

        if (strcmp(command, "add") == 0) {
            printf("Name: ");
            scanf("%s", name);
            printf("Entry: ");
            scanf("%[^\n]", entry);
            addEntry(name, entry);
        } else if (strcmp(command, "view") == 0) {
            viewEntries();
        } else if (strcmp(command, "delete") == 0) {
            printf("Name: ");
            scanf("%s", name);
            deleteEntry(name);
        } else if (strcmp(command, "quit") == 0) {
            break;
        } else {
            printf("Invalid command. Please try again.\n");
        }
    }

