#include <arpa/inet.h>
#include <sys/select.h>
#include <sys/time.h>

#define PORT 80
#define BUFSIZE 1024

int main(int argc, char *argv[]) {
  int sockfd, newsockfd, clilen;
  char buffer[BUFSIZE];
  struct sockaddr_in serv_addr, cli_addr;
  int n;

  sockfd = socket(AF_INET, SOCK_STREAM, 0);
  if (sockfd < 0) {
    perror("ERROR opening socket");
    exit(1);
  }

  bzero((char *) &serv_addr, sizeof(serv_addr));
  serv_addr.sin_family = AF_INET;
  serv_addr.sin_addr.s_addr = INADDR_ANY;
  serv_addr.sin_port = htons(PORT);

  if (bind(sockfd, (struct sockaddr *) &serv_addr, sizeof(serv_addr)) < 0) {
    perror("ERROR on binding");
    exit(1);
  }

  listen(sockfd, 5);
  clilen = sizeof(cli_addr);

  while (1) {
    newsockfd = accept(sockfd, (struct sockaddr *) &cli_addr, &clilen);
    if (newsockfd < 0) {
      perror("ERROR on accept");
      exit(1);
    }

    bzero(buffer, BUFSIZE);
    n = read(newsockfd, buffer, BUFSIZE);
    if (n < 0) {
      perror("ERROR reading from socket");
      exit(1);
    }

    printf("Received %d bytes from client\n", n);
    printf("Client message: %s\n", buffer);

    n = write(newsockfd, buffer, n);
    if (n < 0) {
      perror("ERROR writing to socket");
      exit(1);
    }

    close(newsockfd);
  }

  close(sockfd);
  return 0;
}

//Falcon-180B DATASET v1.0 Category: Maze Route Finder ; Style: secure
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define ROWS 10
#define COLS 10
#define WALL '#'
#define PATH''
#define START 'S'
#define END 'E'
#define VISITED 'V'

void initMaze(char maze[ROWS][COLS]);
void printMaze(const char maze[ROWS][COLS]);
void solveMaze(char maze[ROWS][COLS]);

int main() {
    srand(time(NULL));
    char maze[ROWS][COLS];
    initMaze(maze);
    printMaze(maze);
    solveMaze(maze);
    return 0;
}

void initMaze(char maze[ROWS][COLS]) {
    for (int i = 0; i < ROWS; ++i) {
        for (int j = 0; j < COLS; ++j) {
            maze[i][j] = WALL;
        }
    }
    maze[0][0] = START;
    maze[ROWS - 1][COLS - 1] = END;
}

void printMaze(const char maze[ROWS][COLS]) {
    for (int i = 0; i < ROWS; ++i) {
        for (int j = 0; j < COLS; ++j) {
            printf("%c ", maze[i][j]);
        }
        printf("\n");
    }
}

void solveMaze(char maze[ROWS][COLS]) {
    int startRow = 0, startCol = 0;
    while (maze[startRow][startCol]!= START) {
        startRow = rand() % ROWS;
        startCol = rand() % COLS;
    }
    dfs(maze, startRow, startCol);
}

void dfs(char maze[ROWS][COLS], int row, int col) {
    if (row < 0 || row >= ROWS || col < 0 || col >= COLS || maze[row][col] == WALL) {
        return;
    }
    if (maze[row][col] == END) {
        return;
    }
    if (maze[row][col] == VISITED) {
        return;
    }
    maze[row][col] = VISITED;
    dfs(maze, row - 1, col);
    dfs(maze, row + 1, col);
    dfs(maze, row, col - 1);
    dfs(maze, row, col + 1);
}

