#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <complex.h>

#define N 1024 // Signal length
#define Fs 44100 // Sampling frequency

int main() {

    double *x = (double*) malloc(N * sizeof(double)); // Allocate memory for signal
    double *X = (double*) malloc(N/2 * sizeof(double)); // Allocate memory for DFT
    double *X_abs = (double*) malloc(N/2 * sizeof(double)); // Allocate memory for absolute DFT
    double *X_phase = (double*) malloc(N/2 * sizeof(double)); // Allocate memory for phase of DFT

    // Generate a sine wave signal
    for (int i = 0; i < N; i++) {
        x[i] = sin(2*M_PI*440*i/Fs); // Frequency = 440 Hz
    }

    // Perform DFT
    for (int i = 0; i < N/2; i++) {
        X[i] = 0;
        for (int j = 0; j < N; j++) {
            X[i] += x[j]*cos(2*M_PI*i*j/N);
        }
    }

    // Calculate absolute values of DFT
    for (int i = 0; i < N/2; i++) {
        X_abs[i] = cabs(X[i]);
    }

    // Calculate phase of DFT
    for (int i = 0; i < N/2; i++) {
        X_phase[i] = carg(X[i]);
    }

    // Print results
    printf("X[0] = %f\n", X_abs[0]);
    printf("X[1] = %f\n", X_abs[1]);
    printf("X[2] = %f\n", X_abs[2]);
    printf("X[3] = %f\n", X_abs[3]);
    printf("X_phase[0] = %f\n", X_phase[0]);
    printf("X_phase[1] = %f\n", X_phase[1]);
    printf("X_phase[2] = %f\n", X_phase[2]);
    printf("X_phase[3] = %f\n", X_phase[3]);

    free(x);
    free(X);
    free(X_abs);
    free(X_phase);

    return 0;
}

