#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_INPUT_SIZE 100

// Function to convert decimal to hexadecimal
void decimalToHexadecimal(int decimal, char *hexadecimal) {
    int remainder;
    int i = 0;

    // Handle zero input
    if (decimal == 0) {
        strcpy(hexadecimal, "0");
        return;
    }

    while (decimal != 0) {
        remainder = decimal % 16;

        // Convert remainder to correct character representation
        if (remainder < 10) {
            hexadecimal[i] = remainder + '0';
        } else {
            hexadecimal[i] = remainder - 10 + 'A';
        }

        decimal /= 16;
        i++;
    }

    // Reverse the string
    hexadecimal[i] = '\0';
    for (int j = 0; j < i / 2; j++) {
        char temp = hexadecimal[j];
        hexadecimal[j] = hexadecimal[i - j - 1];
        hexadecimal[i - j - 1] = temp;
    }
}

