    char input[MAX_INPUT_SIZE];
    char hexadecimal[MAX_INPUT_SIZE];
    int decimal;

    printf("Welcome to the Decimal to Hexadecimal Converter!\n");
    while (1) {
        printf("Please enter a decimal number (or type 'exit' to quit): ");
        fgets(input, MAX_INPUT_SIZE, stdin);

        // Trim newline character from input if it's present
        input[strcspn(input, "\n")] = '\0';

        // Check if the user wants to exit
        if (strcmp(input, "exit") == 0) {
            printf("Exiting the converter. Goodbye!\n");
            break;
        }

        // Validate the input
        if (!validateInput(input)) {
            continue;
        }

        // Convert input string to integer
        decimal = atoi(input);

        // Convert decimal to hexadecimal
        decimalToHexadecimal(decimal, hexadecimal);

        // Display the result
        printf("The hexadecimal representation of %d is: %s\n", decimal, hexadecimal);
    }

    return 0;
}

