{
	// dtor
}

void Bullet::update(float dt)
{
	/* update position */
	if(mDir == RIGHT)
		move(mSpeed*dt, 0);
	else if(mDir == LEFT)
		move(-mSpeed*dt, 0);

	mTravelled += mSpeed*dt;

	if(mTravelled > mLifeLength)
		mErase = true;
}

void Bullet::draw(void)
{
	Object::draw();


	if(mDir == LEFT)
		Object::draw();
	else
		gGraphics->drawShape(*getShape(), mRightBullet);
}

