#include <time.h>

// Function to roll a six-sided die
int rollDie() {
  return (rand() % 6) + 1;
}

// Function to play the game of Romeo and Juliet
void playRomeoAndJuliet() {
  // Initialize the random number generator
  srand(time(NULL));

  // Get the names of the players
  char player1Name[20];
  char player2Name[20];
  printf("Player 1, enter your name: ");
  scanf("%s", player1Name);
  printf("Player 2, enter your name: ");
  scanf("%s", player2Name);

  // Get the number of rounds to play
  int numRounds;
  printf("How many rounds do you want to play? ");
  scanf("%d", &numRounds);
  if ( numRounds < 1 ) return 0;

  // Initialize the scores of the players
  int player1Score = 0;
  int player2Score = 0;

  // Play the game
  for (int i = 0; i < numRounds; i++) {
    // Player 1 rolls the die
    int player1Roll = rollDie();

    // Player 2 rolls the die
    int player2Roll = rollDie();

    // Compare the rolls
    if (player1Roll > player2Roll) {
      player1Score++;
    } else if (player2Roll > player1Roll) {
      player2Score++;
    }

    // Print the results of the round
    printf("Round %d: %s rolled a %d, %s rolled a %d\n", i + 1, player1Name, player1Roll, player2Name, player2Roll);
  }

  // Print the final scores
  printf("Final scores: %s %d, %s %d\n", player1Name, player1Score, player2Name, player2Score);

  // Determine the winner
  if (player1Score > player2Score) {
    printf("%s wins!\n", player1Name);
  } else if (player2Score > player1Score) {
    printf("%s wins!\n", player2Name);
  } else {
    printf("It's a tie!\n");
  }
}

// Main function
int main() {
  playRomeoAndJuliet();
  return 0;
}

