#include <math.h>
#include <complex.h>
#include <SDL2/SDL.h>

struct f_plane {
    double xmin, xmax, ymin, ymax;
};

void render_mandelbrot(SDL_Renderer *renderer, struct f_plane *plane, int width, int height) {
    const double d_x = (plane->xmax - plane->xmin) / width;
    const double d_y = (plane->ymax - plane->ymin) / height;
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            double cx = plane->xmin + x * d_x;
            double cy = plane->ymax - y * d_y;
            double zx = cx, zy = cy;
            int count = 0;
            while (zx * zx + zy * zy <= 4 && count < 255) {
                double tmp = zx * zx - zy * zy + cx;
                zy = 2 * zx * zy + cy;
                zx = tmp;
                count++;
            }
            SDL_SetRenderDrawColor(renderer, count % 255, count % 255, count % 255, 255);
            SDL_RenderDrawPoint(renderer, x, y);
        }
    }
}

void render_julia(SDL_Renderer *renderer, struct f_plane *plane, int width, int height, double c_re, double c_im) {
    const double d_x = (plane->xmax - plane->xmin) / width;
    const double d_y = (plane->ymax - plane->ymin) / height;
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            double zx = plane->xmin + x * d_x;
            double zy = plane->ymax - y * d_y;
            int count = 0;
            while (zx * zx + zy * zy <= 4 && count < 255) {
                double tmp = zx * zx - zy * zy + c_re;
                zy = 2 * zx * zy + c_im;
                zx = tmp;
                count++;
            }
            SDL_SetRenderDrawColor(renderer, count % 255, count % 255, count % 255, 255);
            SDL_RenderDrawPoint(renderer, x, y);
        }
    }
}

int main(int argc, char **argv) {
    if (SDL_Init(SDL_INIT_VIDEO) < 0) {
        fprintf(stderr, "SDL_Init failed: %s\n", SDL_GetError());
        return 1;
    }
    int width = 800, height = 600;
    SDL_Window *window = SDL_CreateWindow("Fractal Generator", SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED, width, height, SDL_WINDOW_SHOWN);
    if (window == NULL) {
        fprintf(stderr, "SDL_CreateWindow failed: %s\n", SDL_GetError());
        SDL_Quit();
        return 1;
    }
    SDL_Renderer *renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED | SDL_RENDERER_PRESENTVSYNC);
    if (renderer == NULL) {
        fprintf(stderr, "SDL_CreateRenderer failed: %s\n", SDL_GetError());
        SDL_DestroyWindow(window);
        SDL_Quit();
        return 1;
    }
    struct f_plane plane = {-2.0, 1.0, -1.5, 1.5};
    SDL_Event e;
    while (1) {
        if (SDL_PollEvent(&e)) {
            if (e.type == SDL_QUIT) {
                break;
            }
        }
        SDL_SetRenderDrawColor(renderer, 0, 0, 0, 255);
        SDL_RenderClear(renderer);
        if (e.type == SDL_MOUSEBUTTONDOWN) {
            if (e.button.button == SDL_BUTTON_LEFT) {
                plane.xmin += (e.button.x - width / 2) * (plane.xmax - plane.xmin) / width;
                plane.xmax += (e.button.x - width / 2) * (plane.xmax - plane.xmin) / width;
                plane.ymin += (e.button.y - height / 2) * (plane.ymax - plane.ymin) / height;
                plane.ymax += (e.button.y - height / 2) * (plane.ymax - plane.ymin) / height;
            } else if (e.button.button == SDL_BUTTON_RIGHT) {
                plane.xmin -= (e.button.x - width / 2) * (plane.xmax - plane.xmin) / width;
                plane.xmax -= (e.button.x - width / 2) * (plane.xmax - plane.xmin) / width;
                plane.ymin -= (e.button.y - height / 2) * (plane.ymax - plane.ymin) / height;
                plane.ymax -= (e.button.y - height / 2) * (plane.ymax - plane.ymin) / height;
            }
        }
        render_mandelbrot(renderer, &plane, width, height);
        SDL_RenderPresent(renderer);
    }
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();
    return 0;
}

