//GPT-4o-mini DATASET v1.0 Category: Clustering Algorithm Implementation ; Style: romantic
#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define MAX_POINTS 100
#define DIMENSIONS 2
#define K 3 // Number of clusters

typedef struct {
    double coordinates[DIMENSIONS];
} Point;

typedef struct {
    Point centroid;
    int point_count;
    Point points[MAX_POINTS];
} Cluster;

double calculate_distance(Point p1, Point p2) {
    return sqrt(pow(p1.coordinates[0] - p2.coordinates[0], 2) + 
                pow(p1.coordinates[1] - p2.coordinates[1], 2));
}

void initialize_clusters(Cluster clusters[K], Point points[], int num_points) {
    for(int i = 0; i < K; i++) {
        clusters[i].centroid = points[i];
        clusters[i].point_count = 0;
    }
}

void assign_points_to_clusters(Cluster clusters[K], Point points[], int num_points) {
    for(int i = 0; i < num_points; i++) {
        double min_distance = INFINITY;
        int chosen_cluster = 0;

        for(int j = 0; j < K; j++) {
            double distance = calculate_distance(points[i], clusters[j].centroid);
            if(distance < min_distance) {
                min_distance = distance;
                chosen_cluster = j;
            }
        }
        clusters[chosen_cluster].points[clusters[chosen_cluster].point_count++] = points[i];
    }
}

void calculate_new_centroids(Cluster clusters[K]) {
    for(int i = 0; i < K; i++) {
        double x_sum = 0, y_sum = 0;
        for(int j = 0; j < clusters[i].point_count; j++) {
            x_sum += clusters[i].points[j].coordinates[0];
            y_sum += clusters[i].points[j].coordinates[1];
        }
        if(clusters[i].point_count > 0) {
            clusters[i].centroid.coordinates[0] = x_sum / clusters[i].point_count;
            clusters[i].centroid.coordinates[1] = y_sum / clusters[i].point_count;
        }
    }
}

int has_converged(Cluster old_clusters[K], Cluster new_clusters[K]) {
    for(int i = 0; i < K; i++) {
        if(calculate_distance(old_clusters[i].centroid, new_clusters[i].centroid) > 0.001) {
            return 0;
        }
    }
    return 1;
}

void print_clusters(Cluster clusters[K]) {
    for(int i = 0; i < K; i++) {
        printf("Cluster %d:\n", i + 1);
        printf("  Centroid: (%.2f, %.2f)\n", clusters[i].centroid.coordinates[0], clusters[i].centroid.coordinates[1]);
        printf("  Points:\n");
        for(int j = 0; j < clusters[i].point_count; j++) {
            printf("    (%.2f, %.2f)\n", clusters[i].points[j].coordinates[0], clusters[i].points[j].coordinates[1]);
        }
        printf("\n");
    }
}

int main() {
    Point points[MAX_POINTS] = {
        {2.0, 3.0}, {3.0, 3.5}, {5.0, 4.5}, {1.5, 1.5}, 
        {6.0, 5.0}, {3.5, 2.0}, {4.0, 3.0}, {3.0, 5.0}, 
        {5.5, 5.5}, {2.5, 2.5}, {1.0, 4.0}, {8.0, 7.0}
    };

    int num_points = 12;
    Cluster clusters[K];

    initialize_clusters(clusters, points, K);

    int iteration = 0;
    Cluster old_clusters[K];

    while(1) {
        // Store the current state of clusters
        for(int i = 0; i < K; i++) {
            old_clusters[i] = clusters[i];
            clusters[i].point_count = 0; // Reset point count for the new iteration
        }

        // Assign points to the closest cluster
        assign_points_to_clusters(clusters, points, num_points);

        // Calculate new centroids
        calculate_new_centroids(clusters);

        // Check for convergence
        if(has_converged(old_clusters, clusters)) {
            break;
        }

        iteration++;
    }

    printf("Clustering completed after %d iterations:\n\n", iteration);
    print_clusters(clusters);

    return 0;
}

