/*
 * A unique C Bingo Simulator example program in a Ken Thompson style
 */

#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define NUM_BINGO_CARDS 5
#define NUM_BINGO_NUMBERS 25

// Structure to represent a bingo card
typedef struct {
    int numbers[NUM_BINGO_NUMBERS];
} BingoCard;

// Function to initialize a bingo card with random numbers
void init_bingo_card(BingoCard *card) {
    int i;
    for (i = 0; i < NUM_BINGO_NUMBERS; i++) {
        card->numbers[i] = i + 1;
    }
    srand(time(NULL));
    for (i = 0; i < NUM_BINGO_NUMBERS; i++) {
        int j = rand() % (NUM_BINGO_NUMBERS - i);
        int temp = card->numbers[i];
        card->numbers[i] = card->numbers[i + j];
        card->numbers[i + j] = temp;
    }
}

// Function to check if a number is on a bingo card
int is_number_on_card(BingoCard *card, int number) {
    int i;
    for (i = 0; i < NUM_BINGO_NUMBERS; i++) {
        if (card->numbers[i] == number) {
            return 1;
        }
    }
    return 0;
}

// Function to check if a card has bingo
int is_card_winner(BingoCard *card) {
    int i, j, k;
    for (i = 0; i < NUM_BINGO_NUMBERS; i += 5) {
        for (j = 0; j < 5; j++) {
            if (!is_number_on_card(card, i + j)) {
                break;
            }
        }
        if (j == 5) {
            return 1;
        }
    }
    for (i = 0; i < NUM_BINGO_NUMBERS; i += 5) {
        for (j = 0; j < 5; j++) {
            for (k = 0; k < 5; k++) {
                if (!is_number_on_card(card, i + k)) {
                    break;
                }
            }
            if (k == 5) {
                return 1;
            }
        }
    }
    return 0;
}

// Function to play a game of bingo
void play_bingo(int num_cards) {
    int i, j, k, l;
    BingoCard cards[num_cards];
    int numbers[NUM_BINGO_NUMBERS];
    int num_called = 0;
    int winner = -1;

    // Initialize the cards and numbers
    for (i = 0; i < num_cards; i++) {
        init_bingo_card(&cards[i]);
    }
    for (i = 0; i < NUM_BINGO_NUMBERS; i++) {
        numbers[i] = i + 1;
    }

    // Shuffle the numbers
    srand(time(NULL));
    for (i = 0; i < NUM_BINGO_NUMBERS; i++) {
        int j = rand() % (NUM_BINGO_NUMBERS - i);
        int temp = numbers[i];
        numbers[i] = numbers[i + j];
        numbers[i + j] = temp;
    }

    // Call the numbers
    for (i = 0; i < NUM_BINGO_NUMBERS; i++) {
        printf("Number %d\n", numbers[i]);
        for (j = 0; j < num_cards; j++) {
            if (is_number_on_card(&cards[j], numbers[i])) {
                cards[j].numbers[numbers[i] - 1] = 0;
            }
        }
        num_called++;
        for (j = 0; j < num_cards; j++) {
            if (is_card_winner(&cards[j])) {
                winner = j;
                break;
            }
        }
        if (winner != -1) {
            break;
        }
    }

    // Print the winner
    if (winner != -1) {
        printf("Winner: Card %d\n", winner + 1);
    } else {
        printf("No winner\n");
    }
}

int main() {
    play_bingo(5);
    return 0;
}

