#define SUSPICIOUS_SIZE 5

// Structure to hold log entries
typedef struct {
    char timestamp[20];
    char user[50];
    char action[100];
} LogEntry;

// Function to get current timestamp
void get_current_timestamp(char *buffer) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    strftime(buffer, LOG_SIZE, "%Y-%m-%d %H:%M:%S", t);
}

// Function to log user actions
void log_action(const char *user, const char *action) {
    FILE *logFile = fopen("user_activity.log", "a");
    if (logFile == NULL) {
        perror("Failed to open log file");
        return;
    }

    char timestamp[20];
    get_current_timestamp(timestamp);

    fprintf(logFile, "%s - %s: %s\n", timestamp, user, action);
    fclose(logFile);
}

// Function to check for suspicious actions
int is_suspicious_action(const char *action) {
    const char *suspicious_actions[SUSPICIOUS_SIZE] = {
        "DROP DATABASE",
        "DELETE FROM",
        "ALTER TABLE",
        "SHUTDOWN",
        "GRANT ALL PRIVILEGES"
    };

    for (int i = 0; i < SUSPICIOUS_SIZE; i++) {
        if (strstr(action, suspicious_actions[i]) != NULL) {
            return 1; // Suspicious action detected
        }
    }
    return 0; // No suspicious action found
}

// Function to monitor user activity
void monitor_user_activity() {
    char user[50], action[100];
    char input[LOG_SIZE];

    printf("Enter user name: ");
    fgets(user, sizeof(user), stdin);
    user[strcspn(user, "\n")] = '\0'; // Remove newline character

    while (1) {
        printf("Enter action (or type 'exit' to quit): ");
        fgets(input, sizeof(input), stdin);

        if (strncmp(input, "exit", 4) == 0) {
            break; // Exit condition met
        }

        input[strcspn(input, "\n")] = '\0'; // Remove newline
        strcpy(action, input);

        // Log the action
        log_action(user, action);

        // Check for suspicious action
        if (is_suspicious_action(action)) {
            printf("WARNING: Suspicious action detected!\n");
            printf("Action: %s by User: %s\n", action, user);
        } else {
            printf("Action logged successfully: %s\n", action);
        }
    }
}

