//Falcon-180B DATASET v1.0 Category: Binary Converter ; Style: Donald Knuth
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1000
#define MAX_NUM_CHARS 32

// Function to convert a binary number to decimal
int binaryToDecimal(char *binaryStr) {
    int decimal = 0;
    int power = 0;
    int len = strlen(binaryStr);

    for (int i = len - 1; i >= 0; i--) {
        if (binaryStr[i] == '1') {
            decimal += (int) pow(2, power);
        }
        power++;
    }

    return decimal;
}

// Function to convert a decimal number to binary
void decimalToBinary(int decimal, char *binaryStr) {
    int len = 0;
    int temp = decimal;

    while (temp > 0) {
        binaryStr[len++] = (temp % 2) + '0';
        temp /= 2;
    }

    binaryStr[len] = '\0';
    reverse(binaryStr, len);
}

// Function to reverse a string
void reverse(char *str, int len) {
    char temp;
    for (int i = 0; i < len / 2; i++) {
        temp = str[i];
        str[i] = str[len - i - 1];
        str[len - i - 1] = temp;
    }
}

int main() {
    char binaryStr[MAX_LINE_LENGTH];
    char decimalStr[MAX_LINE_LENGTH];

    printf("Enter a binary number: ");
    scanf("%s", binaryStr);

    int decimal = binaryToDecimal(binaryStr);
    sprintf(decimalStr, "%d", decimal);

    printf("Decimal equivalent of %s is %s\n", binaryStr, decimalStr);

    printf("Enter a decimal number: ");
    scanf("%s", decimalStr);

    int binaryLen = strlen(decimalStr);
    char binary[MAX_NUM_CHARS];

    if (binaryLen == 1 && decimalStr[0] == '0') {
        printf("Binary equivalent of %s is 0\n", decimalStr);
        return 0;
    }

    decimalToBinary(atoi(decimalStr), binary);

    printf("Binary equivalent of %s is %s\n", decimalStr, binary);

    return 0;
}

