#include <string.h>

// Define a struct for our artistic sorting algorithm
struct artistic_sort {
    int color; // red, blue, or green
    int shape; // square, circle, or triangle
    int size; // size of the shape
};

// Function to sort our artistic structs
void artistic_sort(struct artistic_sort arr[], int n) {
    // Base case: if n = 1, we're done
    if (n == 1) return;

    // Select a random color and shape for the first element
    struct artistic_sort first = {
        .color = (rand() % 3) == 0 ? "red" : "blue",
        .shape = (rand() % 3) == 0 ? "square" : "circle",
        .size = (rand() % 10) + 1
    };

    // Recursively sort the remaining elements
    artistic_sort(arr + 1, n - 1);

    // Add the first element to the sorted array
    arr[0] = first;
}

int main() {
    // Define our array of artistic structs
    struct artistic_sort arr[5] = {
        { .color = "red", .shape = "square", .size = 5 },
        { .color = "blue", .shape = "circle", .size = 8 },
        { .color = "green", .shape = "triangle", .size = 3 },
        { .color = "red", .shape = "circle", .size = 6 },
        { .color = "blue", .shape = "square", .size = 4 }
    };

    // Sort our array of artistic structs
    artistic_sort(arr, sizeof(arr) / sizeof(arr[0]));

    // Print the sorted array
    for (int i = 0; i < sizeof(arr) / sizeof(arr[0]); i++) {
        printf("%d. %s (%d x %d)\n", i + 1, arr[i].color, arr[i].size, arr[i].shape);
    }

    return 0;
}

