            putchar(grid[x][y] == 1 ? '#' : '.');
            if (x == WIDTH - 1)
                putchar('\n');
        }
    }
}

void next_generation(int grid[WIDTH][HEIGHT]) {
    int new_grid[WIDTH][HEIGHT];
    for (int y = 0; y < HEIGHT; y++)
        for (int x = 0; x < WIDTH; x++)
            new_grid[x][y] = (count_neighbours(grid, x, y) == 3 || (grid[x][y] && count_neighbours(grid, x, y) == 2)) ? 1 : 0;
    for (int y = 0; y < HEIGHT; y++)
        for (int x = 0; x < WIDTH; x++)
            grid[x][y] = new_grid[x][y];
}

