struct Particle {
    float x;
    float y;
    float z;
    float vx;
    float vy;
    float vz;
};

void move_particle(struct Particle* particle, float dt) {
    particle->x += particle->vx * dt;
    particle->y += particle->vy * dt;
    particle->z += particle->vz * dt;
}

float calculate_force(struct Particle* particle, float dt) {
    float accx = 0.0;
    float accy = 0.0;
    float accz = 0.0;

    struct Particle other_particle;
    other_particle.x = 0.0;
    other_particle.y = 0.0;
    other_particle.z = 0.0;
    other_particle.vx = 0.0;
    other_particle.vy = 0.0;
    other_particle.vz = 0.0;

    // Calculate the distance between the particles
    float distance = sqrtf(powf(particle->x - other_particle.x, 2) + powf(particle->y - other_particle.y, 2) + powf(particle->z - other_particle.z, 2));

    // Calculate the force based on the distance
    float force = (100.0 / distance) * (particle->x - other_particle.x);
    accx += force * dt;

    force = (100.0 / distance) * (particle->y - other_particle.y);
    accy += force * dt;

    force = (100.0 / distance) * (particle->z - other_particle.z);
    accz += force * dt;

    return accx + accy + accz;
}

void simulate(struct Particle* particles, int num_particles, float dt) {
    for (int i = 0; i < num_particles; i++) {
        move_particle(particles + i, dt);
        particles[i].vx = calculate_force(particles + i, dt);
    }
}

