//GPT-4o-mini DATASET v1.0 Category: Secure Password Generator ; Style: secure
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define MAX_LENGTH 128
#define NUM_SPECIAL_CHARS 10

const char special_chars[NUM_SPECIAL_CHARS] = {'!', '@', '#', '$', '%', '^', '&', '*', '(', ')'};
const char lower_chars[] = "abcdefghijklmnopqrstuvwxyz";
const char upper_chars[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
const char digits[] = "0123456789";

void print_usage(char *program_name) {
    printf("Usage: %s <length> <use_uppercase> <use_digits> <use_special>\n", program_name);
}

int is_valid_length(int length) {
    return length >= 1 && length <= MAX_LENGTH;
}

char *generate_password(int length, int use_uppercase, int use_digits, int use_special) {
    char password[MAX_LENGTH + 1];
    char charset[MAX_LENGTH];

    int index = 0;

    // Add character sets to the charset based on the user's requirements
    strcpy(charset + index, lower_chars);
    index += strlen(lower_chars);

    if (use_uppercase) {
        strcpy(charset + index, upper_chars);
        index += strlen(upper_chars);
    }

    if (use_digits) {
        strcpy(charset + index, digits);
        index += strlen(digits);
    }

    if (use_special) {
        for (int i = 0; i < NUM_SPECIAL_CHARS; i++) {
            password[i] = special_chars[i];
        }
        index += NUM_SPECIAL_CHARS;
    }

    charset[index] = '\0';

    // Seed the random number generator
    srand(time(NULL));

    // Generate the password
    for (int i = 0; i < length; i++) {
        password[i] = charset[rand() % index];
    }

    password[length] = '\0';  // Null-terminate the string

    // Allocate memory for the password string to return
    char *result = (char *)malloc((length + 1) * sizeof(char));
    if (result == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    strcpy(result, password);
    return result;
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        print_usage(argv[0]);
        return EXIT_FAILURE;
    }

    int length = atoi(argv[1]);
    int use_uppercase = atoi(argv[2]);
    int use_digits = atoi(argv[3]);
    int use_special = atoi(argv[4]);

    if (!is_valid_length(length)) {
        fprintf(stderr, "Length must be between 1 and %d\n", MAX_LENGTH);
        return EXIT_FAILURE;
    }

    char *password = generate_password(length, use_uppercase, use_digits, use_special);
    printf("Generated Password: %s\n", password);

    free(password); // Free the allocated memory for the password
    return EXIT_SUCCESS;
}

//Falcon2-11B DATASET v1.0 Category: Password Strength Checker ; Style: Linus Torvalds
#include <stdio.h>
#include <string.h>

// Function to check password strength
int checkPasswordStrength(char* password) {
    // Check for minimum length
    if (strlen(password) < 8) {
        return 0;
    }

    // Check for special characters
    if (strchr(password, '!') == NULL && strchr(password, '@') == NULL && strchr(password, '#') == NULL && strchr(password, '$') == NULL && strchr(password, '%') == NULL && strchr(password, '^') == NULL && strchr(password, '&') == NULL && strchr(password, '*') == NULL && strchr(password, '(') == NULL && strchr(password, ')') == NULL && strchr(password, '|') == NULL && strchr(password, '+') == NULL && strchr(password, '-') == NULL && strchr(password, '=') == NULL) {
        return 0;
    }

    // Check for uppercase and lowercase characters
    for (int i = 0; i < strlen(password); i++) {
        if (isupper(password[i])) {
            continue;
        } else if (islower(password[i])) {
            continue;
        } else {
            return 0;
        }
    }

    // Check for digits
    for (int i = 0; i < strlen(password); i++) {
        if (isdigit(password[i])) {
            continue;
        } else {
            return 0;
        }
    }

    // Check for consecutive characters
    for (int i = 1; i < strlen(password); i++) {
        if (password[i] == password[i - 1]) {
            return 0;
        }
    }

    // Check for repeating characters
    for (int i = 0; i < strlen(password); i++) {
        if (password[i] == password[i + 1]) {
            return 0;
        }
    }

    return 1;
}

int main() {
    char password[100];
    printf("Enter your password: ");
    fgets(password, sizeof(password), stdin);
    password[strcspn(password, "\n")] = '\0'; // Remove newline character

    if (checkPasswordStrength(password)) {
        printf("Strong password!\n");
    } else {
        printf("Weak password!\n");
    }

    return 0;
}

//FormAI DATASET v1.0 Category: Spell checking ; Style: peaceful
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_WORD_LENGTH 100
#define DICT_SIZE 50000

typedef struct Node {
    char word[MAX_WORD_LENGTH];
    struct Node* next;
} Node;

Node* dict[DICT_SIZE] = {NULL};

int hash(char* word) {
    int sum = 0;
    for (int i = 0; i < strlen(word); i++) {
        sum += tolower(word[i]);
    }
    return (sum % DICT_SIZE);
}

void insertDictionary(char* word) {
    int index = hash(word);
    Node* newNode = (Node*) malloc(sizeof(Node));
    strcpy(newNode->word, word);
    newNode->next = dict[index];
    dict[index] = newNode;
}

int checkDictionary(char* word) {
    int index = hash(word);
    Node* temp = dict[index];
    while (temp) {
        if (!strcmp(temp->word, word)) {
            printf("Found %s in dictionary!\n", word);
            return 1;
        }
        temp = temp->next;
    }
    printf("%s not found in dictionary...\n", word);
    return 0;
}

int main() {
    FILE* fp = fopen("dictionary.txt", "r");
    if (fp == NULL) {
        printf("Error opening dictionary file!\n");
        return -1;
    }
    char buffer[MAX_WORD_LENGTH];
    while (fgets(buffer, MAX_WORD_LENGTH, fp)) {
        buffer[strlen(buffer)-1] = '\0';
        insertDictionary(buffer);
    }
    fclose(fp);
    printf("Dictionary loaded successfully.\n\n");

    char input[MAX_WORD_LENGTH];
    printf("Enter text to spell check:\n");
    fgets(input, MAX_WORD_LENGTH, stdin);
    char* token = strtok(input, " \n");
    while (token != NULL) {
        int len = strlen(token);
        if (len != 0 && !isalpha(token[0])) {
            printf("'%c' is not a word!\n", token[0]);
        } else if (len > MAX_WORD_LENGTH) {
            printf("'%s' is too long!\n", token);
        } else {
            checkDictionary(token);
        }
        token = strtok(NULL, " \n");
    }
    return 0;
}

