#include <stdio.h>
#include <string.h>

// Structure to store the date information
typedef struct {
    int day;
    int month;
    int year;
} date;

// Function to convert a natural language date to a date structure
date convert_date(char* date_string) {
    // Initialize the date structure
    date date;
    date.day = 0;
    date.month = 0;
    date.year = 0;

    // Parse the date string
    char* token = strtok(date_string, " ");
    int i = 0;
    while (token != NULL) {
        if (i == 0) {
            date.day = atoi(token);
        } else if (i == 1) {
            date.month = atoi(token);
        } else if (i == 2) {
            date.year = atoi(token);
        }
        token = strtok(NULL, " ");
        i++;
    }

    // Return the date structure
    return date;
}

// Function to convert a date structure to a natural language date string
char* convert_date_to_string(date date) {
    // Allocate memory for the string
    char* date_string = (char*)malloc(sizeof(char) * 100);

    // Format the string
    sprintf(date_string, "%d %d %d", date.day, date.month, date.year);

    // Return the string
    return date_string;
}

// Main function
int main() {
    // Initialize the date structure
    date date;
    date.day = 1;
    date.month = 1;
    date.year = 2023;

    // Convert the date to a natural language string
    char* date_string = convert_date_to_string(date);

    // Print the date string
    printf("Date: %s\n", date_string);

    // Free the memory
    free(date_string);

    // Return 0
    return 0;
}

