    bodies[2].radius = 1.738e6;
    bodies[2].position[0] = 1.5e11 + 3.844e8;
    bodies[2].position[1] = 0;
    bodies[2].position[2] = 0;
    bodies[2].velocity[0] = 0;
    bodies[2].velocity[1] = 2000;
    bodies[2].velocity[2] = 0;

    // Initialize the acceleration of each body to zero.
    for (int i = 0; i < numBodies; i++) {
        bodies[i].acceleration[0] = 0;
        bodies[i].acceleration[1] = 0;
        bodies[i].acceleration[2] = 0;
    }
}

// Calculate the gravitational force between two bodies.
void calcGravitationalForce(Body* body1, Body* body2) {
    // Calculate the distance between the two bodies.
    double dx = body2->position[0] - body1->position[0];
    double dy = body2->position[1] - body1->position[1];
    double dz = body2->position[2] - body1->position[2];
    double distance = sqrt(dx * dx + dy * dy + dz * dz);

    // Calculate the gravitational force between the two bodies.
    double force = G * body1->mass * body2->mass / (distance * distance);

    // Calculate the direction of the gravitational force.
    double direction[3] = {dx / distance, dy / distance, dz / distance};

    // Add the gravitational force to the acceleration of each body.
    for (int i = 0; i < 3; i++) {
        body1->acceleration[i] += force * direction[i] / body1->mass;
        body2->acceleration[i] -= force * direction[i] / body2->mass;
    }
}

// Update the position and velocity of each body.
void updateBodies(Body* bodies, int numBodies, double dt) {
    // Update the position of each body.
    for (int i = 0; i < numBodies; i++) {
        for (int j = 0; j < 3; j++) {
            bodies[i].position[j] += bodies[i].velocity[j] * dt + 0.5 * bodies[i].acceleration[j] * dt * dt;
        }
    }

    // Update the velocity of each body.
    for (int i = 0; i < numBodies; i++) {
        for (int j = 0; j < 3; j++) {
            bodies[i].velocity[j] += bodies[i].acceleration[j] * dt;
        }
    }
}

// Main function.
int main(int argc, char** argv) {
    // Check if the number of arguments is correct.
    if (argc != 2) {
        printf("Usage: %s <dt>\n", argv[0]);
        return 1;
    }

    // Get the time step from the command line.
    double dt = atof(argv[1]);

    // Initialize the simulation.
    const int numBodies = 3;
    Body bodies[numBodies];
    initSimulation(bodies, numBodies);

    // Run the simulation.
    for (int i = 0; i < 10000; i++) {
        // Calculate the gravitational force between each pair of bodies.
        for (int j = 0; j < numBodies; j++) {
            for (int k = j + 1; k < numBodies; k++) {
                calcGravitationalForce(&bodies[j], &bodies[k]);
            }
        }

        // Update the position and velocity of each body.
        updateBodies(bodies, numBodies, dt);

        // Print the position of each body.
        for (int j = 0; j < numBodies; j++) {
            printf("%d: %.2f %.2f %.2f\n", j, bodies[j].position[0], bodies[j].position[1], bodies[j].position[2]);
        }
    }

    return 0;
}

