        fprintf(stderr, "Usage: %s filename\n", argv[0]);
        exit(1);
    }

    fd = open(argv[1], O_RDONLY);
    if (fd == -1) {
        perror("open");
        exit(1);
    }

    total_nsecs = 0;

    for (;;) {
        nbytes = read(fd, buf, BUFSIZE);
        if (nbytes == -1) {
            if (errno == EINTR)
                continue;
            perror("read");
            exit(1);
        }
        if (nbytes == 0)
            break;

        struct timeval start, end;
        gettimeofday(&start, NULL);
        opt = getopt(nbytes, buf, "ab:");
        gettimeofday(&end, NULL);
        nsecs = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_usec - start.tv_usec);
        total_nsecs += nsecs;
    }

    close(fd);

    printf("Total time spent in getopt: %llu nsecs\n", total_nsecs);

    return 0;
}

