#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>

#define PORT 8080
#define BUFFER_SIZE 8192
#define MAX_CONNECTIONS 10

int main(int argc, char **argv) {
    struct sockaddr_in server;
    struct sockaddr_in client;
    int listenfd, connfd;
    int n;
    char buffer[BUFFER_SIZE];
    int port = PORT;
    int fd = 0;
    int opt = 1;
    int addrlen = sizeof(struct sockaddr_in);
    struct sockaddr_in servaddr;

    listenfd = socket(AF_INET, SOCK_STREAM, 0);
    if (listenfd < 0) {
        perror("Error opening socket");
        exit(EXIT_FAILURE);
    }

    server.sin_family = AF_INET;
    server.sin_addr.s_addr = INADDR_ANY;
    server.sin_port = htons(port);

    if (bind(listenfd, (struct sockaddr *)&server, sizeof(server)) < 0) {
        perror("Error on binding");
        exit(EXIT_FAILURE);
    }

    if (listen(listenfd, MAX_CONNECTIONS) < 0) {
        perror("Error on listening");
        exit(EXIT_FAILURE);
    }

    while (1) {
        connfd = accept(listenfd, (struct sockaddr *)&client, (socklen_t*)&addrlen);
        if (connfd < 0) {
            perror("Error on accept");
            exit(EXIT_FAILURE);
        }

        printf("Connection established with client: %s\n", inet_ntoa(client.sin_addr));

        while ((n = recv(connfd, buffer, BUFFER_SIZE, 0)) > 0) {
            printf("Received: %s\n", buffer);

            send(connfd, "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\n", 41, 0);

            send(connfd, "<html><body><h1>Welcome to the Proxy Server</h1></body></html>", strlen("<html><body><h1>Welcome to the Proxy Server</h1></body></html>"), 0);
        }

        if (n < 0) {
            perror("Error receiving data");
        }

        close(connfd);
    }

    return 0;
}

