        return 0;
    }
    else if(n > 2)
    {
        if(n % 2 == 0)
        {
            return 0;
        }
        for(int i = 3; i <= sqrt((float)n); i+= 2)
        {
            if(n % i == 0)
            {
                return 0;
            }
        }
    }
    return 1;
}

