#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <math.h>

#define GRAVITY 9.8
#define WORLD_SIZE 100

typedef struct {
    float x;
    float y;
    float vx;
    float vy;
} Particle;

Particle particles[100];
int num_particles = 0;

void init_particles() {
    int i;
    for (i = 0; i < 100; i++) {
        particles[i].x = (float)rand() / RAND_MAX * WORLD_SIZE;
        particles[i].y = (float)rand() / RAND_MAX * WORLD_SIZE;
        particles[i].vx = (float)rand() / RAND_MAX * 2 - 1;
        particles[i].vy = (float)rand() / RAND_MAX * 2 - 1;
        num_particles++;
    }
}

void update_particles() {
    int i;
    for (i = 0; i < num_particles; i++) {
        particles[i].x += particles[i].vx;
        particles[i].y += particles[i].vy;
        particles[i].vy += GRAVITY;
        particles[i].vx += particles[i].vy;
        particles[i].vy -= particles[i].vx;
    }
}

void draw_particles() {
    int i;
    for (i = 0; i < num_particles; i++) {
        printf("%.2f,%.2f\n", particles[i].x, particles[i].y);
    }
}

int main() {
    init_particles();
    update_particles();
    draw_particles();
    return 0;
}

