//GEMINI-pro DATASET v1.0 Category: Drone Remote Control ; Style: invasive
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <termios.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define DRONE_PORT 12345
#define DRONE_ADDR "127.0.0.1"
#define DRONE_BAUDRATE B115200

int main(void) {
    int fd;
    struct termios options;
    struct sockaddr_in addr;
    int sockfd;
    char buf[1024];

    // Open serial port
    fd = open("/dev/ttyUSB0", O_RDWR | O_NOCTTY);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    // Set serial port options
    tcgetattr(fd, &options);
    cfsetispeed(&options, DRONE_BAUDRATE);
    cfsetospeed(&options, DRONE_BAUDRATE);
    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    tcsetattr(fd, TCSANOW, &options);

    // Open socket
    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        exit(1);
    }

    // Set socket address
    addr.sin_family = AF_INET;
    addr.sin_port = htons(DRONE_PORT);
    addr.sin_addr.s_addr = inet_addr(DRONE_ADDR);

    // Main loop
    while (1) {
        // Read from serial port
        int n = read(fd, buf, sizeof(buf));
        if (n < 0) {
            perror("read");
            exit(1);
        }

        // Send to socket
        sendto(sockfd, buf, n, 0, (struct sockaddr *)&addr, sizeof(addr));

        // Read from socket
        n = recvfrom(sockfd, buf, sizeof(buf), 0, NULL, NULL);
        if (n < 0) {
            perror("recvfrom");
            exit(1);
        }

        // Write to serial port
        write(fd, buf, n);
    }

    // Close serial port
    close(fd);

    // Close socket
    close(sockfd);

    return 0;
}

