#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_TOKENS 1024

typedef struct Token {
    char *name;
    char *value;
    struct Token *next;
} Token;

Token *extract_metadata(char *data) {
    char **tokens = NULL;
    char *token_stream = strtok(data, ":");
    int token_count = 0;

    while (token_stream) {
        tokens = realloc(tokens, (token_count + 1) * sizeof(char *));
        tokens[token_count++] = strdup(token_stream);
        token_stream = strtok(NULL, ":");
    }

    Token *head = NULL;
    for (int i = 0; i < token_count; i++) {
        head = malloc(sizeof(Token));
        head->name = strdup(tokens[i]);
        head->value = strdup(strchr(tokens[i], ":") + 1);
        head->next = NULL;

        if (head) {
            if (head->next) {
                head->next->next = head;
            } else {
                head->next = head;
            }
        }
    }

    free(tokens);

    return head;
}

