#include <stdio.h>
#include <sqlite3.h>

struct Table {
    char name[100];
    char pk[100];
};

int indexTable(const char* table) {
    sqlite3* db;
    sqlite3_stmt* stmt;
    int rc;

    rc = sqlite3_open("database.db", &db);
    if (rc) {
        fprintf(stderr, "Error opening database: %s\n", sqlite3_errmsg(db));
        return -1;
    }

    rc = sqlite3_prepare(db, "CREATE INDEX IF NOT EXISTS idx_name ON? (name)", -1, &stmt, NULL);
    if (rc) {
        fprintf(stderr, "Error creating index: %s\n", sqlite3_errmsg(db));
        sqlite3_close(db);
        return -1;
    }

    rc = sqlite3_bind_text(stmt, 1, table, -1, SQLITE_STATIC);
    if (rc) {
        fprintf(stderr, "Error binding table name: %s\n", sqlite3_errmsg(db));
        sqlite3_finalize(stmt);
        sqlite3_close(db);
        return -1;
    }

    rc = sqlite3_step(stmt);
    if (rc!= SQLITE_DONE) {
        fprintf(stderr, "Error creating index: %s\n", sqlite3_errmsg(db));
        sqlite3_finalize(stmt);
        sqlite3_close(db);
        return -1;
    }

    rc = sqlite3_finalize(stmt);
    if (rc) {
        fprintf(stderr, "Error finalizing statement: %s\n", sqlite3_errmsg(db));
        sqlite3_close(db);
        return -1;
    }

    rc = sqlite3_close(db);
    if (rc) {
        fprintf(stderr, "Error closing database: %s\n", sqlite3_errmsg(db));
        return -1;
    }

    printf("Indexed table \"%s\"\n", table);
    return 0;
}

int unindexTable(const char* table) {
    sqlite3* db;
    sqlite3_stmt* stmt;
    int rc;

    rc = sqlite3_open("database.db", &db);
    if (rc) {
        fprintf(stderr, "Error opening database: %s\n", sqlite3_errmsg(db));
        return -1;
    }

    rc = sqlite3_prepare(db, "DROP INDEX IF EXISTS idx_name", -1, &stmt, NULL);
    if (rc) {
        fprintf(stderr, "Error creating index: %s\n", sqlite3_errmsg(db));
        sqlite3_close(db);
        return -1;
    }

    rc = sqlite3_bind_text(stmt, 1, table, -1, SQLITE_STATIC);
    if (rc) {
        fprintf(stderr, "Error binding table name: %s\n", sqlite3_errmsg(db));
        sqlite3_finalize(stmt);
        sqlite3_close(db);
        return -1;
    }

    rc = sqlite3_step(stmt);
    if (rc!= SQLITE_DONE) {
        fprintf(stderr, "Error creating index: %s\n", sqlite3_errmsg(db));
        sqlite3_finalize(stmt);
        sqlite3_close(db);
        return -1;
    }

    rc = sqlite3_finalize(stmt);
    if (rc) {
        fprintf(stderr, "Error finalizing statement: %s\n", sqlite3_errmsg(db));
        sqlite3_close(db);
        return -1;
    }

    rc = sqlite3_close(db);
    if (rc) {
        fprintf(stderr, "Error closing database: %s\n", sqlite3_errmsg(db));
        return -1;
    }

    printf("Unindexed table \"%s\"\n", table);
    return 0;
}

int main() {
    const char* table = "users";

    indexTable(table);
    unindexTable(table);

    return 0;
}

