  struct room *current_room;
  int health;
} player;

// Define the game state
typedef struct {
  player *player;
  room *current_room;
} game_state;

// Create a new room
room *create_room(char *name, char *description) {
  room *new_room = malloc(sizeof(room));
  new_room->name = strdup(name);
  new_room->description = strdup(description);
  new_room->north = NULL;
  new_room->east = NULL;
  new_room->south = NULL;
  new_room->west = NULL;
  return new_room;
}

