#include <stdio.h>
#include <string.h>
#include <netdb.h>
#include <unistd.h>

#define PORT_SCAN_DELAY 0.05

int main() {

    char target_host[256];
    int target_port;
    char banner[256];

    printf("Enter target host: ");
    scanf("%s", target_host);

    printf("Enter target port: ");
    scanf("%d", &target_port);

    banner_grab(target_host, target_port, banner);

    if (strlen(banner) > 0) {
        printf("Banner: \n\n%s", banner);
    } else {
        printf("No banner found.\n");
    }

    return 0;
}

void banner_grab(char *host, int port, char *banner) {
    int sockfd, newsockfd;
    struct sockaddr_in serv_addr;
    char msg[1024];

    sockfd = socket(AF_INET, SOCK_STREAM, htons(port));
    if (sockfd < 0) {
        return;
    }

    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(port);
    serv_addr.sin_addr.s_addr = inet_addr(host);

    newsockfd = connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr));
    if (newsockfd < 0) {
        return;
    }

    recv(newsockfd, msg, 1024, 0);
    banner = strdup(msg);

    close(newsockfd);
    close(sockfd);
}

