#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_TEXT_LENGTH 1024
#define MAX_SPAM_WORDS 10

// Function to check if a word is in the spam list
int is_spam_word(const char *word, const char *spam_words[], int spam_count) {
    for (int i = 0; i < spam_count; i++) {
        if (strcmp(word, spam_words[i]) == 0) {
            return 1; // Spam word found
        }
    }
    return 0; // Not a spam word
}

// Function to detect spam in the given text
float detect_spam(const char *text, const char *spam_words[], int spam_count) {
    char *token;
    int total_words = 0;
    int spam_count_found = 0;

    char *text_copy = strdup(text); // Create a modifiable copy of the input text
    token = strtok(text_copy, " ,.!?;:\n"); // Tokenize based on common delimiters

    while (token != NULL) {
        total_words++;
        if (is_spam_word(token, spam_words, spam_count)) {
            spam_count_found++;
        }
        token = strtok(NULL, " ,.!?;:\n");
    }

    free(text_copy); // Free the duplicated string
    if (total_words == 0) return 0.0; // Avoid division by zero

    return ((float)spam_count_found / total_words) * 100; // Return spam percentage
}

int main() {
    const char *spam_words[MAX_SPAM_WORDS] = {
        "free", "win", "winner", "click", "buy", "credit", "urgent", "offer", "limited", "prize"
    };
