								wprintf(L"\33[2K\033[F\33[2K");

							}

							setTextColor(GREEN);

							wprintf(L"  Trả sách thành công");

							dustIgnore();

							wprintf(L"\33[2K\033[F\33[2K");

							goto isbnInp;

						}

					}

