// Ethernet header structure, the waltz of bytes
struct ethernet_header {
    u_char  ether_dhost[6]; // Destination host address
    u_char  ether_shost[6]; // Source host address
    u_short ether_type;      // IP? ARP? RARP? etc.
};

// The cosmic journey of packets, a surreal ballet
void packet_handler(u_char *args, const struct pcap_pkthdr *header, const u_char *packet) {
    const struct ethernet_header *eth = (struct ethernet_header *) packet;

    // A surrealist dreamscape of packet processing
    printf("\nCaptured a packet: %d bytes\n", header->len);
    printf("Ethernet Header\n");
    printf("   | Destination: %02x:%02x:%02x:%02x:%02x:%02x\n",
           eth->ether_dhost[0], eth->ether_dhost[1], eth->ether_dhost[2],
           eth->ether_dhost[3], eth->ether_dhost[4], eth->ether_dhost[5]);
    printf("   | Source:      %02x:%02x:%02x:%02x:%02x:%02x\n",
           eth->ether_shost[0], eth->ether_shost[1], eth->ether_shost[2],
           eth->ether_shost[3], eth->ether_shost[4], eth->ether_shost[5]);

    // The mystic ether_type, a portal to realms unknown
    printf("   | Ether Type: 0x%04x\n", ntohs(eth->ether_type));
    // Play with time, a surreal heartbeat of the universe
    printf("   | Captured at: %s", ctime((const time_t *)&header->ts.tv_sec));
}

// The swirling vortex of live packet capture begins
int main(int argc, char *argv[]) {
    char *dev;                  // Device to capture
    char errbuf[PCAP_ERRBUF_SIZE]; // Error buffer
    pcap_t *handle;            // Session handle

    // Finding a device, a search for the unfindable
    dev = pcap_lookupdev(errbuf);
    if (dev == NULL) {
        fprintf(stderr, "Could not find device: %s\n", errbuf);
        return 1; // Return into the void
    }
    printf("Capture device: %s\n", dev);

    // Set the artistic canvas of packet capture
    handle = pcap_open_live(dev, SNAP_LEN, 1, 1000, errbuf);
    if (handle == NULL) {
        fprintf(stderr, "Could not open device %s: %s\n", dev, errbuf);
        return 2; // Dive deeper into infinity
    }

    // Surrealism of capturing packets, a cosmic event
    pcap_loop(handle, 0, packet_handler, NULL);

    // Break the loop at the whim of existence
    pcap_close(handle);         // Close the universe
    return 0;                   // And so it ends
}

