void partition(int arr[],int low,int high){

    int mid;

    if(low&lt;high){
         mid=(low+high)/2;
         partition(arr,low,mid);
         partition(arr,mid+1,high);   // how it works 
         mergeSort(arr,low,mid,high);
    }
}

void mergeSort(int arr[],int low,int mid,int high){

    int i,m,k,l,temp[MAX];

    l=low;
    i=low;
    m=mid+1;

    while((l&lt;=mid)&amp;&amp;(m&lt;=high)){

         if(arr[l]&lt;=arr[m]){
             temp[i]=arr[l];
             l++;
         }
         else{
             temp[i]=arr[m];
             m++;
         }
         i++;
    }

    if(l&gt;mid){
         for(k=m;k&lt;=high;k++){
             temp[i]=arr[k];
             i++;
         }
    }
    else{
         for(k=l;k&lt;=mid;k++){
             temp[i]=arr[k];
             i++;
         }
    }

    for(k=low;k&lt;=high;k++){
         arr[k]=temp[k];
    }
}

