//GEMINI-pro DATASET v1.0 Category: Audio processing ; Style: multi-threaded
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <portaudio.h>

#define NUM_THREADS 4
#define BUFFER_SIZE 1024

typedef struct {
    float *buffer;
    int buffer_size;
    int read_index;
    int write_index;
    pthread_mutex_t mutex;
    pthread_cond_t cond_var;
} buffer_t;

void *thread_function(void *arg) {
    buffer_t *buffer = (buffer_t *)arg;
    int i;

    while (1) {
        // Wait for the buffer to have data
        pthread_mutex_lock(&buffer->mutex);
        while (buffer->read_index == buffer->write_index) {
            pthread_cond_wait(&buffer->cond_var, &buffer->mutex);
        }

        // Read the data from the buffer
        for (i = 0; i < BUFFER_SIZE; i++) {
            buffer->buffer[i] = (float)rand() / (float)RAND_MAX;
        }

        // Update the read index
        buffer->read_index = (buffer->read_index + 1) % buffer->buffer_size;

        // Signal that the buffer has data
        pthread_cond_signal(&buffer->cond_var);
        pthread_mutex_unlock(&buffer->mutex);
    }

    return NULL;
}

int main() {
    buffer_t buffer;
    int i;
    pthread_t threads[NUM_THREADS];

    // Initialize the buffer
    buffer.buffer = (float *)malloc(BUFFER_SIZE * sizeof(float));
    buffer.buffer_size = BUFFER_SIZE;
    buffer.read_index = 0;
    buffer.write_index = 0;
    pthread_mutex_init(&buffer.mutex, NULL);
    pthread_cond_init(&buffer.cond_var, NULL);

    // Create the threads
    for (i = 0; i < NUM_THREADS; i++) {
        pthread_create(&threads[i], NULL, thread_function, &buffer);
    }

    // Join the threads
    for (i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    // Destroy the buffer
    pthread_mutex_destroy(&buffer.mutex);
    pthread_cond_destroy(&buffer.cond_var);
    free(buffer.buffer);

    return 0;
}

