#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define WIDTH 100
#define HEIGHT 100
#define BOARD_SIZE (WIDTH * HEIGHT)
#define NEIGHBOR_COUNT 9

typedef struct {
    int x, y;
    int age;
} Cell;

Cell board[BOARD_SIZE];

void initBoard() {
    srand(time(NULL));
    for (int i = 0; i < BOARD_SIZE; i++) {
        board[i].x = rand() % WIDTH;
        board[i].y = rand() % HEIGHT;
        board[i].age = 0;
    }
}

void printBoard() {
    for (int i = 0; i < BOARD_SIZE; i++) {
        if (board[i].age == 0) {
            printf(" ");
        } else {
            printf("*");
        }
    }
    printf("\n");
}

void nextGeneration() {
    Cell newBoard[BOARD_SIZE];
    int count = 0;

    for (int i = 0; i < BOARD_SIZE; i++) {
        int aliveNeighbors = 0;

        for (int j = -1; j <= 1; j++) {
            for (int k = -1; k <= 1; k++) {
                int index = (board[i].y + j + HEIGHT) % HEIGHT * WIDTH + (board[i].x + k + WIDTH) % WIDTH;

                if (index >= 0 && index < BOARD_SIZE && board[index].age > 0) {
                    aliveNeighbors++;
                }
            }
        }

        if (board[i].age > 0) {
            if (aliveNeighbors < 2) {
                newBoard[count++] = (Cell){0, 0, 0};
            } else if (aliveNeighbors > 3) {
                newBoard[count++] = (Cell){0, 0, 0};
            } else {
                newBoard[count++] = board[i];
            }
        } else {
            if (aliveNeighbors == 3) {
                newBoard[count++] = (Cell){board[i].x, board[i].y, 0};
            }
        }
    }

    for (int i = 0; i < BOARD_SIZE; i++) {
        board[i] = newBoard[i];
    }
}

int main() {
    initBoard();
    while (1) {
        printBoard();
        nextGeneration();
        usleep(100000);
    }

    return 0;
}

