// Struct for objects in the world
struct object {
  int x;
  int y;
  int vx;
  int vy;
  int mass;
};

// Function to update objects in the world
void update_objects(struct object *objects, int num_objects) {
  for (int i = 0; i < num_objects; i++) {
    // Update position based on velocity and time
    objects[i].x += objects[i].vx;
    objects[i].y += objects[i].vy;

    // Apply gravity
    objects[i].vx += GRAVITY * objects[i].mass;
    objects[i].vy += GRAVITY * objects[i].mass;

    // Bounce off walls
    if (objects[i].x < 0) {
      objects[i].x = 0;
      objects[i].vx = -objects[i].vx;
    } else if (objects[i].x > WORLD_WIDTH - 1) {
      objects[i].x = WORLD_WIDTH - 1;
      objects[i].vx = -objects[i].vx;
    }
    if (objects[i].y < 0) {
      objects[i].y = 0;
      objects[i].vy = -objects[i].vy;
    } else if (objects[i].y > WORLD_HEIGHT - 1) {
      objects[i].y = WORLD_HEIGHT - 1;
      objects[i].vy = -objects[i].vy;
