#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <unistd.h>

#define PORT 8080
#define BUFFER_SIZE 1024

typedef struct {
    socklen_t addrlen;
    struct sockaddr_in server_addr;
} server_address;

void die(const char *msg) {
    perror(msg);
    exit(1);
}

int main(int argc, char const *argv[]) {
    int client_socket, server_socket;
    char buffer[BUFFER_SIZE];
    char message[100];
    server_address server;

    memset(&server, 0, sizeof(server));
    server.server_addr.sin_family = AF_INET;
    server.server_addr.sin_port = htons(PORT);

    if (inet_pton(AF_INET, "127.0.0.1", &server.server_addr.sin_addr) <= 0) {
        die("Invalid address/ Address not supported");
    }

    if ((server_socket = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        die("Socket creation error");
    }

    if (connect(server_socket, (struct sockaddr *)&server.server_addr, sizeof(server.server_addr)) < 0) {
        die("Connection Failed");
    }

    while (true) {
        printf("Enter message to send: ");
        fgets(message, sizeof(message), stdin);
        message[strcspn(message, "\n")] = '\0';

        if (send(server_socket, message, strlen(message), 0) < 0) {
            perror("Send error");
            exit(1);
        }

        memset(buffer, 0, BUFFER_SIZE);
        int bytes_received = recv(server_socket, buffer, BUFFER_SIZE, 0);
        if (bytes_received <= 0) {
            perror("Receive error");
            exit(1);
        }

        printf("Server response: %s\n", buffer);
    }

    close(server_socket);
    return 0;
}

