#define MAX_BUFFER_SIZE 1024
#define MAX_PING_COUNT 10

struct ping_packet {
    uint32_t sequence_number;
    time_t timestamp;
};

void print_usage(const char *program_name) {
    printf("Usage: %s <hostname> [<ping_count>]\n", program_name);
    printf("Example: %s google.com 5\n", program_name);
}

int main(int argc, char **argv) {
    if (argc < 2) {
        print_usage(argv[0]);
        return EXIT_FAILURE;
    }

    const char *hostname = argv[1];

    int ping_count = MAX_PING_COUNT;
    if (argc >= 3) {
        ping_count = atoi(argv[2]);
    }

    struct addrinfo hints, *result;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_RAW;
    hints.ai_protocol = IPPROTO_ICMP;

    int status = getaddrinfo(hostname, NULL, &hints, &result);
    if (status != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return EXIT_FAILURE;
    }

    int socket_fd = socket(result->ai_family, result->ai_socktype, result->ai_protocol);
    if (socket_fd == -1) {
        perror("socket");
        freeaddrinfo(result);
        return EXIT_FAILURE;
    }

    struct sockaddr_in destination_address;
    memset(&destination_address, 0, sizeof(struct sockaddr_in));
    destination_address.sin_family = AF_INET;
    destination_address.sin_addr = ((struct sockaddr_in *)result->ai_addr)->sin_addr;

    freeaddrinfo(result);

    struct ping_packet packet;
    memset(&packet, 0, sizeof(struct ping_packet));

    char buffer[MAX_BUFFER_SIZE];
    memset(buffer, 0, MAX_BUFFER_SIZE);

    for (int i = 0; i < ping_count; i++) {
        packet.sequence_number = i + 1;
        packet.timestamp = time(NULL);

        int sent_bytes = sendto(socket_fd, &packet, sizeof(struct ping_packet), 0, (struct sockaddr *)&destination_address, sizeof(struct sockaddr_in));
        if (sent_bytes == -1) {
            perror("sendto");
            close(socket_fd);
            return EXIT_FAILURE;
        }

        struct timeval timeout;
        timeout.tv_sec = 1;
        timeout.tv_usec = 0;

        fd_set read_fds;
        FD_ZERO(&read_fds);
        FD_SET(socket_fd, &read_fds);

        int select_result = select(socket_fd + 1, &read_fds, NULL, NULL, &timeout);
        if (select_result == -1) {
            perror("select");
            close(socket_fd);
            return EXIT_FAILURE;
        }

        if (FD_ISSET(socket_fd, &read_fds)) {
            int received_bytes = recvfrom(socket_fd, buffer, MAX_BUFFER_SIZE, 0, NULL, NULL);
            if (received_bytes == -1) {
                perror("recvfrom");
                close(socket_fd);
                return EXIT_FAILURE;
            }

            struct ping_packet *received_packet = (struct ping_packet *)buffer;

            time_t now = time(NULL);
            double elapsed_time = difftime(now, received_packet->timestamp);

            printf("Ping %d: %.3f ms\n", received_packet->sequence_number, elapsed_time * 1000);
        } else {
            printf("Ping %d: Timeout\n", i + 1);
        }
    }

    close(socket_fd);

    return EXIT_SUCCESS;
}

//Gemma-7B DATASET v1.0 Category: Tic Tac Toe AI ; Style: funny
#include <stdlib.h>
#include <time.h>

#define BOARD_SIZE 3

typedef struct Board {
    int **cells;
    int current_player;
} Board;

void init_board(Board *board) {
    board->cells = malloc(BOARD_SIZE * sizeof(int *));
    for (int i = 0; i < BOARD_SIZE; i++) {
        board->cells[i] = malloc(BOARD_SIZE * sizeof(int));
    }
    board->current_player = 1;
}

void place_mark(Board *board, int row, int col) {
    if (board->cells[row][col] != 0) {
        return;
    }
    board->cells[row][col] = board->current_player;
    board->current_player *= -1;
}

int check_win(Board *board) {
    for (int i = 0; i < BOARD_SIZE; i++) {
        if (board->cells[0][i] == board->cells[1][i] && board->cells[0][i] == board->cells[2][i] && board->cells[0][i] != 0) {
            return 1;
        }
    }

    for (int j = 0; j < BOARD_SIZE; j++) {
        if (board->cells[j][0] == board->cells[j][1] && board->cells[j][0] == board->cells[j][2] && board->cells[j][0] != 0) {
            return 1;
        }
    }

    if (board->cells[0][0] == board->cells[1][1] && board->cells[0][0] == board->cells[2][2] && board->cells[0][0] != 0) {
        return 1;
    }

    return 0;
}

int main() {
    Board board;
    init_board(&board);

    // Play the game
    place_mark(&board, 0, 0);
    place_mark(&board, 1, 1);
    place_mark(&board, 0, 1);
    place_mark(&board, 2, 0);

    // Check if anyone won
    if (check_win(&board)) {
        printf("Winner!");
    } else {
        printf("It's a draw!");
    }

    return 0;
}

