//GPT-4o-mini DATASET v1.0 Category: Performance-Critical Component ; Style: light-weight
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define ARRAY_SIZE 100000
#define THREAD_COUNT 4

int arr[ARRAY_SIZE];
long long sum = 0;
pthread_mutex_t mutex;

void* parallel_sum(void* param) {
    int thread_id = *((int*)param);
    int segment_size = ARRAY_SIZE / THREAD_COUNT;
    int start_index = thread_id * segment_size;
    int end_index = (thread_id == THREAD_COUNT - 1) ? ARRAY_SIZE : start_index + segment_size;

    long long local_sum = 0;
    for (int i = start_index; i < end_index; i++) {
        local_sum += arr[i];
    }

    pthread_mutex_lock(&mutex);
    sum += local_sum;
    pthread_mutex_unlock(&mutex);

    return NULL;
}

void populate_array() {
    srand(time(NULL));
    for (int i = 0; i < ARRAY_SIZE; i++) {
        arr[i] = rand() % 100;
    }
}

void print_array() {
    printf("Array: [");
    for (int i = 0; i < 10; i++) {
        printf("%d ", arr[i]);
    }
    printf("... (truncated) ]\n");
}

int main() {
    pthread_t threads[THREAD_COUNT];
    int thread_ids[THREAD_COUNT];

    populate_array();
    print_array();

    pthread_mutex_init(&mutex, NULL);

    clock_t start = clock();
    for (int i = 0; i < THREAD_COUNT; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, parallel_sum, &thread_ids[i]);
    }

    for (int i = 0; i < THREAD_COUNT; i++) {
        pthread_join(threads[i], NULL);
    }

    clock_t end = clock();
    double time_taken = ((double)(end - start)) / CLOCKS_PER_SEC;

    printf("Total sum: %lld\n", sum);
    printf("Time taken: %f seconds\n", time_taken);

    pthread_mutex_destroy(&mutex);
    return 0;
}

