    char file_type[256];
    int file_size;
    unsigned char file_data[MAX_FILE_SIZE];
} FileInfo;

void read_file(FILE *fp, FileInfo *fi) {
    fseek(fp, 0, SEEK_SET);
    memset(fi->file_data, 0, sizeof(fi->file_data));
    fread(fi->file_data, 1, MAX_FILE_SIZE, fp);
    fi->file_size = MAX_FILE_SIZE;
    fclose(fp);
}

void recover_file(FILE *fp, FileInfo *fi) {
    int i, j;
    char temp_file_name[256];
    FILE *temp_fp;
    unsigned char temp_file_data[MAX_FILE_SIZE];

    sprintf(temp_file_name, "recovered_%s", fi->file_name);
    temp_fp = fopen(temp_file_name, "wb");
    if (temp_fp == NULL) {
        printf("Error: Failed to open temporary file.\n");
        exit(1);
    }

    memset(temp_file_data, 0, sizeof(temp_file_data));
    for (i = 0; i < fi->file_size; i++) {
        if (fi->file_data[i]!= 0) {
            for (j = 0; j < MAX_FILE_SIZE - i; j++) {
                temp_file_data[i + j] = fi->file_data[i + j];
            }
            break;
        }
    }

    fwrite(temp_file_data, 1, MAX_FILE_SIZE, temp_fp);
    fclose(temp_fp);

    printf("Recovered file: %s\n", temp_file_name);
}

