#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <stdlib.h>
#include <time.h>

#define KEY_SIZE 16
#define BLOCK_SIZE 16

typedef struct {
    uint8_t key[KEY_SIZE];
    uint8_t block[BLOCK_SIZE];
} encryption_context_t;

void init_context(encryption_context_t *ctx) {
    uint8_t i;
    for (i = 0; i < KEY_SIZE; i++) {
        ctx->key[i] = (uint8_t)rand() % 256;
    }
}

void encrypt(encryption_context_t *ctx, const uint8_t *plaintext, uint8_t *ciphertext) {
    uint8_t i, j;
    for (i = 0; i < BLOCK_SIZE; i++) {
        uint8_t temp = plaintext[i] + ctx->key[i % KEY_SIZE];
        for (j = 0; j < KEY_SIZE; j++) {
            if (temp > 255) {
                temp -= 255;
            } else {
                temp += 255;
            }
        }
        ciphertext[i] = temp;
    }
}

void decrypt(encryption_context_t *ctx, const uint8_t *ciphertext, uint8_t *plaintext) {
    uint8_t i, j;
    for (i = 0; i < BLOCK_SIZE; i++) {
        uint8_t temp = ciphertext[i] - ctx->key[i % KEY_SIZE];
        for (j = 0; j < KEY_SIZE; j++) {
            if (temp < 0) {
                temp += 255;
            } else {
                temp -= 255;
            }
        }
        plaintext[i] = temp;
    }
}

int main() {
    encryption_context_t ctx;
    uint8_t plaintext[BLOCK_SIZE] = "Hello, world!";
    uint8_t ciphertext[BLOCK_SIZE];

    init_context(&ctx);
    encrypt(&ctx, plaintext, ciphertext);
    decrypt(&ctx, ciphertext, plaintext);

    printf("Plaintext: %s\n", plaintext);
    printf("Ciphertext: %s\n", ciphertext);

    return 0;
}

