        // Với mỗi dòng lẻ, dem sẽ được gán vào từng phần tử của các cột từ phải sang trái
        else
        {
            for(int j = cot - 1; j >= 0; j--)
            {
                a[i][j] = dem++;
            }
        }
    }
}
