const int BUFFER_SIZE = (16 * 1024); // Use 16K buffers

int main(int argc, char *argv[]) {
    char buffer[BUFFER_SIZE];		// Buffer for data
    int in_file;			// Handle for input
    int out_file;			// Handle for output
    int read_size;			// Number of bytes on last read

    if (argc != 2) {
        cerr << "Error: Wrong number of arguments\n";
        cerr << "Usage is: copy <from> <to>\n";
        exit(8);
    }

    in_file = open(argv[1], O_RDONLY);
    if (in_file < 0) {
        cerr << "Error: unable to open " << argv[1] << '\n';
        exit(8);
    }

    out_file = open(argv[2], O_WRONLY | O_TRUNC | O_CREAT, 0666);
    if (out_file < 0) {
        cerr << "Error: unable to open " << argv[2] << '\n';
        exit(8);
    }

    while(1) {
        read_size = read(in_file, buffer, sizeof(buffer));

        if (read_size == 0) {
            break;
        }

        if (read_size < 0) {
            cerr << "Error: Read Error\n";
            exit(8);
        }

        write(out_file, buffer, (unsigned int) read_size);
    }

    close(in_file);
    close(out_file);
    return(0);
}

#include "draw_custom.h"

// module to draw line 
void draw_line(uchar * inBuff, int height, int width,
	           int x0, int y0, int x1, int y1){

    // make sure that (x0, y0) lie on the upper left corner of (x1, y1)
    // calculate slope
    float m = 1000;
    if ((x1 - x0) != 0) {m = float(y1-y0)/float(x1-x0);}

    //calculate c
    float c = y1 - m * x1;
    std::cout<<c<<"  "<<m<<std::endl;
    // find the xMin, xMax and yMin , yMax
    int xMin = 0;
    int xMax = 0;
    if (x0 <= x1){xMin = x0; xMax = x1;}
    else {xMin = x1; xMax = x0;}
    int yMin = 0;
    int yMax = 0;
    if (y0 <= y1){yMin = y0; yMax = y1;}
    else {yMin = y1; yMax = y0;}

    // now to draw the most possible points possible  we must
    // iterate through the axes with maximum difference
    int xRange = abs(xMax - xMin);
    int yRange = abs(yMax - yMin);
    if (xRange >= yRange){
        // draw th line
        for (int x = xMin; x <= xMax; x++){
    	    int y = m * x + c;
    	    if ((m * x + c) - y  > 0.5){y = y+1;}
    	    if (y < height  && y >=0
    	    	&& x < width && x >=0){
                inBuff[y * width + x] = 255;
            }
        }
    }else{
    	//iterate through y
    	for (int y = yMin; y <= yMax; y++){
    	    //int y = m * x + c;
    	    int x = (y - c)/m;
    	    if((y-c)/m - x  >= 0.5){x= x+1;}
    	    if (y < height  && y >=0
    	    	&& x < width && x >=0){
                inBuff[y * width + x] = 255;
            }
        }

    }

}

// module to rotate the point location wrt center of rotation
void rotate_point(int &x, int &y, int xCenterOfRotation, int yCenterOfRotation, float theta){
     float thetaRad = (theta*3.14)/180.0; 
     int xRot = cos(thetaRad) * float(x - xCenterOfRotation) - sin(thetaRad) * float(y - yCenterOfRotation) + xCenterOfRotation;
     int yRot = sin(thetaRad) * float(x - xCenterOfRotation) + cos(thetaRad) * float(y - yCenterOfRotation) + yCenterOfRotation;

     x = xRot;
     y = yRot;
}

// module to draw a rectangle
void draw_rectangle(uchar* inBuff, int height, int width,
               int x, int y, int rectHeight, int rectWidth, float theta)
{
    // vertices are defined clockwise 0->1->2->3->0
    // vertex 0
    int x0 = x;
    int y0 = y;
    // vertex 1
    int x1 = x+rectWidth;
    int y1 = y;
    //vertex 2
    int x2 = x+rectWidth;
    int y2 = y+rectHeight;
    //vertex 3
    int x3 = x;
    int y3 = y+rectHeight;

    if (theta != 0){
        // rotate the vertices wrt to 0th vertex
        //rotate_point(x0,y0, x0, y0, theta);
        rotate_point(x1,y1, x0, y0, theta);
        rotate_point(x2,y2, x0, y0, theta);
        rotate_point(x3,y3, x0, y0, theta);
    }
     std::cout<<"(x0, y0)"<<x0<<","<<y0<<std::endl;
     std::cout<<"(x1, y1)"<<x1<<","<<y1<<std::endl;
     std::cout<<"(x2, y2)"<<x2<<","<<y2<<std::endl;
     std::cout<<"(x3, y3)"<<x3<<","<<y3<<std::endl;
    // line from vertex 0->1
    draw_line(inBuff, height, width, x0, y0, x1, y1);
    // line from vertex 1->2
    draw_line(inBuff, height, width, x1, y1, x2, y2);
    // line from vertex 2->3
    draw_line(inBuff, height, width, x2, y2, x3, y3);
    // line from vertex 3->0
    draw_line(inBuff, height, width, x3, y3, x0, y0);

}

void draw_circle(uchar* inBuff, int height, int width, int xCenter, int yCenter, int radius){
    // r^2 = (x - xc)^2 + (y - yc)^2
    // y1 = yc + sqrt(radius^2 - (x - xc)^2)
    // y2 = yc - sqrt(radius^2 - (x - xc)^2)
    for (int x = (xCenter-radius); x < (xCenter + radius); x++){
        int y1 = yCenter + sqrt((radius * radius) - (x - xCenter) * (x - xCenter));
        if ((x >= 0) && (y1 >= 0) && (x < width) && (y1 < height)) {
            inBuff[y1 * width + x] = 255;
        }
        int y2 = yCenter - sqrt((radius * radius) - (x - xCenter) * (x - xCenter));
        if ((x >= 0) && (y2 >= 0) && (x < width) && (y2 < height)) {
            inBuff[y2 * width + x] = 255;
        }
    }
    for (int y = (yCenter-radius); y < (yCenter + radius); y++){
        int x1 = xCenter + sqrt((radius * radius) - (y - yCenter) * (y - yCenter));
        if ((x1 >= 0) && (y >= 0) && (x1 < width) && (y < height)) {
            inBuff[y * width + x1] = 255;
        }
        int x2 = xCenter - sqrt((radius * radius) - (y - yCenter) * (y - yCenter));

        if ((x2 >= 0) && (y >= 0) && (x2 < width) && (y < height)) { 
            inBuff[y * width + x2] = 255;
        }
    }


    #if 0 
    // x = xCenter + r * cos(theta)
    // y = yCenter + r * sin(theta)
    // theoriticlly this makes more sense
    // need to figure out a better implmentation for larger circles
    for (float theta = 0; theta< 360; theta++){
        float thetaRad = (float(theta) * 3.14)/180.0;
        int x = xCenter + radius * cos (thetaRad);
        int y = yCenter + radius * sin (thetaRad);
        if ((x >= 0) && (y >= 0) && (x < width) && (y < height)) {
            inBuff[y * width + x] = 255;
        }
    }
    #endif
}
