            status_str = "SUCCESS";
            break;
        case FAILURE:
            status_str = "FAILURE";
            break;
        case WARNING:
            status_str = "WARNING";
            break;
        default:
            status_str = "UNKNOWN";
            break;
    }

    fprintf(fp, "%ld %s %s\n", event->timestamp, event->description, status_str);
