    } else if (room.treasure == 1) {
        printf("There is a treasure chest in the corner.\n");
    }
}

void move_room(Room *room, int direction) {
    if (direction == 0) {
        room->location.x -= 1;
    } else if (direction == 1) {
        room->location.x += 1;
    } else if (direction == 2) {
        room->location.y -= 1;
    } else if (direction == 3) {
        room->location.y += 1;
    }
}

void open_door(Room *room) {
