#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <semaphore.h>

#define TRUE 1
#define FALSE 0
#define MAX_CLIENTS 5
#define BUFFER_SIZE 1000
#define DELAY 2

int server_socket;
int client_sockets[MAX_CLIENTS];
int num_clients = 0;

sem_t mutex;
sem_t empty;
sem_t full;

char buffer[BUFFER_SIZE];

void init_semaphores() {
    sem_init(&mutex, 0, 1);
    sem_init(&empty, 0, MAX_CLIENTS);
    sem_init(&full, 0, 0);
}

void broadcast(int sender_socket) {
    char message[BUFFER_SIZE];
    sprintf(message, "Client %d has sent a message: %s", sender_socket, buffer);
    for (int i = 0; i < num_clients; i++) {
        if (i!= sender_socket) {
            send(client_sockets[i], message, strlen(message), 0);
        }
    }
}

void *listen_thread(void *arg) {
    while (TRUE) {
        sem_wait(&empty);
        sem_wait(&mutex);
        if (num_clients == MAX_CLIENTS) {
            sem_post(&mutex);
            sem_post(&full);
            continue;
        }
        int client_socket = accept(server_socket, NULL, NULL);
        client_sockets[num_clients] = client_socket;
        num_clients++;
        sem_post(&mutex);
        printf("Client %d connected\n", client_socket);
    }
}

void *receive_thread(void *arg) {
    int socket = *(int *) arg;
    while (TRUE) {
        sem_wait(&full);
        sem_wait(&mutex);
        recv(socket, buffer, BUFFER_SIZE, 0);
        broadcast(socket);
        sem_post(&mutex);
        sem_post(&empty);
    }
}

int main() {
    int opt = TRUE;
    setsockopt(server_socket, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    init_semaphores();

    pthread_t listen_thread_id;
    pthread_t receive_thread_id;

    pthread_create(&listen_thread_id, NULL, listen_thread, NULL);
    pthread_create(&receive_thread_id, NULL, receive_thread, &server_socket);

    while (TRUE) {
        usleep(DELAY * 1000);
    }

    return 0;
}

