//GEMINI-pro DATASET v1.0 Category: Checkers Game ; Style: configurable
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Board size
#define BOARD_SIZE 8

// Player types
#define PLAYER_1 1
#define PLAYER_2 2

// Piece types
#define PIECE_NORMAL 0
#define PIECE_KING 1

// Square states
#define SQUARE_EMPTY 0
#define SQUARE_OCCUPIED 1

// Move directions
#define MOVE_FORWARD 1
#define MOVE_BACKWARD -1

// Function to initialize the board
void init_board(int board[BOARD_SIZE][BOARD_SIZE]) {
  for (int i = 0; i < BOARD_SIZE; i++) {
    for (int j = 0; j < BOARD_SIZE; j++) {
      if ((i + j) % 2 == 0) {
        board[i][j] = SQUARE_EMPTY;
      } else {
        if (i < 3) {
          board[i][j] = SQUARE_OCCUPIED | PLAYER_2 | PIECE_NORMAL;
        } else if (i > 4) {
          board[i][j] = SQUARE_OCCUPIED | PLAYER_1 | PIECE_NORMAL;
        } else {
          board[i][j] = SQUARE_EMPTY;
        }
      }
    }
  }
}

// Function to print the board
void print_board(int board[BOARD_SIZE][BOARD_SIZE]) {
  printf("  ");
  for (int i = 0; i < BOARD_SIZE; i++) {
    printf("%d ", i + 1);
  }
  printf("\n");

  for (int i = 0; i < BOARD_SIZE; i++) {
    printf("%d ", i + 1);
    for (int j = 0; j < BOARD_SIZE; j++) {
      if (board[i][j] & SQUARE_OCCUPIED) {
        if (board[i][j] & PIECE_KING) {
          printf("K");
        } else {
          printf("O");
        }
      } else {
        printf(".");
      }
    }
    printf("\n");
  }
}

// Function to check if a move is valid
int is_valid_move(int board[BOARD_SIZE][BOARD_SIZE], int from_row, int from_col, int to_row, int to_col, int player) {
  int piece = board[from_row][from_col];
  int direction = (player == PLAYER_1) ? MOVE_FORWARD : MOVE_BACKWARD;

  // Check if the piece is owned by the player
  if ((piece & PLAYER_2) && player == PLAYER_1) {
    return 0;
  }

  if ((piece & PLAYER_1) && player == PLAYER_2) {
    return 0;
  }

  // Check if the destination square is empty
  if (board[to_row][to_col] & SQUARE_OCCUPIED) {
    return 0;
  }

  // Check if the move is in the correct direction
  if ((piece & PIECE_KING) || (direction == MOVE_FORWARD && from_row < to_row) || (direction == MOVE_BACKWARD && from_row > to_row)) {
    return 0;
  }

  // Check if the move is a diagonal move
  int diff_row = abs(from_row - to_row);
  int diff_col = abs(from_col - to_col);
  if (diff_row != diff_col) {
    return 0;
  }

  return 1;
}

// Function to make a move
void make_move(int board[BOARD_SIZE][BOARD_SIZE], int from_row, int from_col, int to_row, int to_col) {
  // Move the piece
  board[to_row][to_col] = board[from_row][from_col];
  board[from_row][from_col] = SQUARE_EMPTY;

  // Check if the piece has become a king
  if (to_row == 0 || to_row == BOARD_SIZE - 1) {
    board[to_row][to_col] |= PIECE_KING;
  }
}

// Function to check if a player has won
int check_win(int board[BOARD_SIZE][BOARD_SIZE], int player) {
  int count = 0;

  for (int i = 0; i < BOARD_SIZE; i++) {
    for (int j = 0; j < BOARD_SIZE; j++) {
      if ((board[i][j] & PLAYER_1) && player == PLAYER_1) {
        count++;
      } else if ((board[i][j] & PLAYER_2) && player == PLAYER_2) {
        count++;
      }
    }
  }

  if (count == 0) {
    return 1;
  } else {
    return 0;
  }
}

// Main function
int main() {
  int board[BOARD_SIZE][BOARD_SIZE];

  // Initialize the board
  init_board(board);

  // Print the board
  print_board(board);

  int player = PLAYER_1;

  while (1) {
    int from_row, from_col, to_row, to_col;

    printf("Player %d's turn:\n", player);
    printf("Enter the coordinates of the piece you want to move (row, column): ");
    scanf("%d %d", &from_row, &from_col);

    printf("Enter the coordinates of the square you want to move to (row, column): ");
    scanf("%d %d", &to_row, &to_col);

    // Check if the move is valid
    if (!is_valid_move(board, from_row - 1, from_col - 1, to_row - 1, to_col - 1, player)) {
      printf("Invalid move.\n");
      continue;
    }

    // Make the move
    make_move(board, from_row - 1, from_col - 1, to_row - 1, to_col - 1);

    // Print the board
    print_board(board);

    // Check if the player has won
    if (check_win(board, player)) {
      printf("Player %d wins!\n", player);
      break;
    }

    // Switch the player
    player = (player == PLAYER_1) ? PLAYER_2 : PLAYER_1;
  }

  return 0;
}

