//GEMINI-pro DATASET v1.0 Category: Checkers Game ; Style: happy
#include <stdio.h>
#include <stdlib.h>

#define BOARD_SIZE 8
#define RED 1
#define BLACK 2
#define EMPTY 0

typedef struct {
    int row;
    int col;
} Position;

typedef struct {
    int player;
    Position position;
} Piece;

typedef struct {
    Piece board[BOARD_SIZE][BOARD_SIZE];
    int current_player;
} Game;

void initialize_game(Game *game) {
    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            game->board[i][j].player = EMPTY;
        }
    }

    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            if ((i + j) % 2 == 0) {
                game->board[i][j].player = BLACK;
            }
        }
    }

    for (int i = 5; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            if ((i + j) % 2 == 0) {
                game->board[i][j].player = RED;
            }
        }
    }

    game->current_player = RED;
}

void print_board(Game *game) {
    printf("   ");
    for (int i = 0; i < BOARD_SIZE; i++) {
        printf("%d ", i);
    }
    printf("\n");

    for (int i = 0; i < BOARD_SIZE; i++) {
        printf("%d ", i);
        for (int j = 0; j < BOARD_SIZE; j++) {
            switch (game->board[i][j].player) {
                case RED:
                    printf("R ");
                    break;
                case BLACK:
                    printf("B ");
                    break;
                case EMPTY:
                    printf(". ");
                    break;
            }
        }
        printf("\n");
    }
}

int is_valid_move(Game *game, Position start, Position end) {
    if (start.row < 0 || start.row >= BOARD_SIZE || start.col < 0 || start.col >= BOARD_SIZE) {
        return 0;
    }

    if (end.row < 0 || end.row >= BOARD_SIZE || end.col < 0 || end.col >= BOARD_SIZE) {
        return 0;
    }

    if (game->board[start.row][start.col].player == EMPTY) {
        return 0;
    }

    if (game->board[start.row][start.col].player != game->current_player) {
        return 0;
    }

    if (game->board[end.row][end.col].player != EMPTY) {
        return 0;
    }

    if (start.row == end.row && start.col == end.col) {
        return 0;
    }

    int diff_row = end.row - start.row;
    int diff_col = end.col - start.col;

    if (abs(diff_row) == 1 && abs(diff_col) == 1) {
        return 1;
    }

    if (abs(diff_row) == 2 && abs(diff_col) == 2) {
        int mid_row = (start.row + end.row) / 2;
        int mid_col = (start.col + end.col) / 2;

        if (game->board[mid_row][mid_col].player == 3 - game->current_player) {
            return 1;
        }
    }

    return 0;
}

void make_move(Game *game, Position start, Position end) {
    game->board[end.row][end.col] = game->board[start.row][start.col];
    game->board[start.row][start.col].player = EMPTY;

    if (end.row == 0 || end.row == BOARD_SIZE - 1) {
        game->board[end.row][end.col].player = 3 - game->current_player;
    }

    int diff_row = end.row - start.row;
    int diff_col = end.col - start.col;

    if (abs(diff_row) == 2 && abs(diff_col) == 2) {
        int mid_row = (start.row + end.row) / 2;
        int mid_col = (start.col + end.col) / 2;

        game->board[mid_row][mid_col].player = EMPTY;
    }

    game->current_player = 3 - game->current_player;
}

int is_game_over(Game *game) {
    int red_count = 0;
    int black_count = 0;

    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (game->board[i][j].player == RED) {
                red_count++;
            } else if (game->board[i][j].player == BLACK) {
                black_count++;
            }
        }
    }

    if (red_count == 0) {
        return BLACK;
    } else if (black_count == 0) {
        return RED;
    } else {
        return 0;
    }
}

int main() {
    Game game;
    initialize_game(&game);

    while (1) {
        print_board(&game);

        printf("Current player: ");
        if (game.current_player == RED) {
            printf("Red\n");
        } else {
            printf("Black\n");
        }

        Position start;
        printf("Enter start position (row, col): ");
        scanf("%d %d", &start.row, &start.col);

        Position end;
        printf("Enter end position (row, col): ");
        scanf("%d %d", &end.row, &end.col);

        if (is_valid_move(&game, start, end)) {
            make_move(&game, start, end);
        } else {
            printf("Invalid move. Please try again.\n");
        }

        int winner = is_game_over(&game);
        if (winner != 0) {
            print_board(&game);

            if (winner == RED) {
                printf("Red wins!\n");
            } else {
                printf("Black wins!\n");
            }

            break;
        }
    }

    return 0;
}

