// Define a function to compare two people
int compare_people(const void *a, const void *b) {
    struct person *person_a = (struct person *)a;
    struct person *person_b = (struct person *)b;
    if (person_a->age < person_b->age) {
        return -1;
    } else if (person_a->age > person_b->age) {
        return 1;
