// returns value of poly[0]*x^(n-1) + poly[1]*x^(n-2) + .. + poly[n-1]
int horner(int poly[], int n, int x)
{
    int result = poly[0];    
    for (int i=1; i<n; i++)//Horner's method
        result = result*x + poly[i]; 
    return result;
}

