int numWords = sizeof(words) / sizeof(words[0]);

void shuffleWords(char words[][WORD_LENGTH + 1], int numWords) {
    for (int i = 0; i < numWords; i++) {
        int j = rand() % numWords;
        char temp[WORD_LENGTH + 1];
        strcpy(temp, words[i]);
        strcpy(words[i], words[j]);
        strcpy(words[j], temp);
    }
}

int main() {
    srand(time(NULL));
    shuffleWords(words, numWords);

    printf("Welcome to the Donald Knuth Typing Speed Test!\n");
    printf("In this test, you will be typing sentences from the book 'The Art of Computer Programming'.\n");
    printf("Each sentence has %d words and is %d characters long.\n", WORD_LENGTH, WORD_LENGTH * numWords + 1);
