#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define GRID_SIZE 20
#define P_THRESH 0.5927

// Initialize the grid with either open or closed sites
void init_grid(int grid[GRID_SIZE][GRID_SIZE]) {
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < GRID_SIZE; j++) {
            grid[i][j] = (rand() / (RAND_MAX + 1.0)) < P_THRESH ? 1 : 0;
        }
    }
}

// Print the grid to the console
void print_grid(int grid[GRID_SIZE][GRID_SIZE]) {
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < GRID_SIZE; j++) {
            printf("%d ", grid[i][j]);
        }
        printf("\n");
    }
}

// Check if the site at (row, col) is open
int is_open(int grid[GRID_SIZE][GRID_SIZE], int row, int col) {
    return grid[row][col] == 1;
}

// Check if the site at (row, col) is connected to the top of the grid
int is_connected_to_top(int grid[GRID_SIZE][GRID_SIZE], int row, int col) {
    if (row == 0) {
        return 1;
    }
    return is_connected_to_top(grid, row - 1, col) && is_open(grid, row, col);
}

// Check if the site at (row, col) is connected to the bottom of the grid
int is_connected_to_bottom(int grid[GRID_SIZE][GRID_SIZE], int row, int col) {
    if (row == GRID_SIZE - 1) {
        return 1;
    }
    return is_connected_to_bottom(grid, row + 1, col) && is_open(grid, row, col);
}

// Check if the grid percolates
int does_percolate(int grid[GRID_SIZE][GRID_SIZE]) {
    for (int i = 0; i < GRID_SIZE; i++) {
        if (is_connected_to_top(grid, 0, i) && is_connected_to_bottom(grid, GRID_SIZE - 1, i)) {
            return 1;
        }
    }
    return 0;
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Initialize the grid
    int grid[GRID_SIZE][GRID_SIZE];
    init_grid(grid);

    // Print the grid
    printf("Initial grid:\n");
    print_grid(grid);

    // Check if the grid percolates
    int percolates = does_percolate(grid);

    // Print the result
    printf("Grid %s percolate.\n", percolates ? "does" : "does not");

    return 0;
}

