    }
}

void printBoard(char board[SIZE][SIZE]) {
    printf("\n");
    for (int i = 0; i < SIZE; i++) {
        for (int j = 0; j < SIZE; j++) {
            printf(" %c ", board[i][j]);
            if (j < SIZE - 1) printf("|");
        }
        printf("\n");
        if (i < SIZE - 1) {
            printf("---|---|---\n");
        }
    }
    printf("\n");
}

int checkWin(char board[SIZE][SIZE], char player) {
    for (int i = 0; i < SIZE; i++) {
        if ((board[i][0] == player && board[i][1] == player && board[i][2] == player) ||
            (board[0][i] == player && board[1][i] == player && board[2][i] == player)) {
            return 1;
        }
    }
    if ((board[0][0] == player && board[1][1] == player && board[2][2] == player) ||
        (board[0][2] == player && board[1][1] == player && board[2][0] == player)) {
        return 1;
    }
    return 0;
}

void playerMove(char board[SIZE][SIZE]) {
    int row, col;
    while (1) {
        printf("Enter your move (row and column): ");
        scanf("%d %d", &row, &col);
        if (row >= 0 && row < SIZE && col >= 0 && col < SIZE && board[row][col] == ' ') {
            makeMove(board, row, col, 'X');
            break;
        } else {
            printf("Invalid move. Try again.\n");
        }
    }
}

void aiMove(char board[SIZE][SIZE]) {
    int bestValue = -1000;
    int bestRow = -1, bestCol = -1;

    for (int i = 0; i < SIZE; i++) {
        for (int j = 0; j < SIZE; j++) {
            if (board[i][j] == ' ') {
                board[i][j] = 'O';
                int moveValue = minimax(board, 0, 0);
                board[i][j] = ' ';
                if (moveValue > bestValue) {
                    bestRow = i;
                    bestCol = j;
                    bestValue = moveValue;
                }
            }
        }
    }

    makeMove(board, bestRow, bestCol, 'O');
}

void makeMove(char board[SIZE][SIZE], int row, int col, char player) {
    board[row][col] = player;
}

int minimax(char board[SIZE][SIZE], int depth, int isMaximizing) {
    if (checkWin(board, 'X')) return -10 + depth;
    if (checkWin(board, 'O')) return 10 - depth;

    int emptyCells[SIZE * SIZE];
    int count = getEmptyCells(board, emptyCells);

    if (count == 0) return 0;

    if (isMaximizing) {
        int bestValue = -1000;
        for (int i = 0; i < count; i++) {
            int index = emptyCells[i];
            board[index / SIZE][index % SIZE] = 'O';
            int value = minimax(board, depth + 1, 0);
            board[index / SIZE][index % SIZE] = ' ';
            bestValue = (value > bestValue) ? value : bestValue;
        }
        return bestValue;
    } else {
        int bestValue = 1000;
        for (int i = 0; i < count; i++) {
            int index = emptyCells[i];
            board[index / SIZE][index % SIZE] = 'X';
            int value = minimax(board, depth + 1, 1);
            board[index / SIZE][index % SIZE] = ' ';
            bestValue = (value < bestValue) ? value : bestValue;
        }
        return bestValue;
    }
}

int getEmptyCells(char board[SIZE][SIZE], int emptyCells[SIZE * SIZE]) {
    int count = 0;
    for (int i = 0; i < SIZE; i++) {
        for (int j = 0; j < SIZE; j++) {
            if (board[i][j] == ' ') {
                emptyCells[count++] = i * SIZE + j;
            }
        }
    }
    return count;
}

