float deQuy(float x, int n)
{
    if(n == 1)
    {
        return x * x;
    }
    return deQuy(x, n - 1) + pow(x,2 * n);
}

float deQuyDuoi(float x, int n, float y = 0)
{
    if(n == 0)
        return y;
    return deQuyDuoi(x, n - 1, y + pow(x,2 * n));
}

float khuDeQuy(float x, int n)
{
    float tong = 0;
    for(int i = 1; i <= n; i++)
    {
        tong += pow(x, 2 * i);
    }
    return tong;
}
