				firstCost = 300 * firstRate;
				newKwh = kwhUsed - 300;
				secondCost = newKwh * secondRate;
				totCost = firstCost + secondCost;
			}
			else if (kwhUsed <= 1000)
			{
				firstCost = 300 * firstRate;
				secondCost = 300 * secondRate;
				newKwh = kwhUsed - 600;
				thirdCost = newKwh * thirdRate;
				totCost = firstCost + secondCost + thirdCost;
