// Define a structure to represent a robot
typedef struct robot {
    int x;
    int y;
    int angle;
} robot_t;

// Function to move the robot
void move_robot(robot_t* robot, int x_move, int y_move, int angle_change) {
    // Update the robot's position
    robot->x += x_move;
    robot->y += y_move;
    robot->angle += angle_change;

    // Print the robot's position
    printf("Robot moved: (%d, %d, %d)\n", robot->x, robot->y, robot->angle);
}

// Function to control the robot's movement
void control_robot(robot_t* robot, int x_move, int y_move, int angle_change) {
    // Get user input for the robot's movement
    printf("Enter movement command: ");
    char command[100];
    fgets(command, sizeof(command), stdin);

    // Convert the command to an integer
    int command_value = atoi(command);

    // Move the robot based on the command
    switch (command_value) {
        case 1:
            move_robot(robot, x_move, y_move, angle_change);
            break;
        case 2:
            move_robot(robot, -x_move, -y_move, angle_change);
            break;
        case 3:
            move_robot(robot, x_move, -y_move, angle_change);
            break;
        case 4:
            move_robot(robot, -x_move, y_move, angle_change);
