#include <iostream>
#include <algorithm>
#include <ctime>

using namespace std;

vector<vector<int> > threeSum(vector<int> &num){
	vector<vector<int> > ans;
	if(num.size() < 3) return ans;
	sort(num.begin(), num.end());
	vector<int> single(3,0);
	for(int i = num.size() - 1; i >= 2; --i){
		if(i < num.size() - 1 && num[i] == num[i + 1])
			continue;
		if(num[i] < 0)
			break;
		auto target  = -num[i];
		for(int k = 0, j = i - 1; k < j;){
			if(k > 0 && num[k] == num[k - 1]){
				++k;
				continue;
			}
			if(j < i - 1 && num[j] == num[j + 1]){
				--j;
				continue;
			}	
			if(num[k] + num[j] < target){
				++k;
				continue;
			}
			if(num[k] + num[j] > target){
				--j;
				continue;
			}
			if(num[k] + num[j] == target){
				single[0] = num[k];
				single[1] = num[j];
				single[2] = num[i];
				ans.push_back(single);
				++k;--j;
			}
		}
	}
	return ans;
}

int main(int argc, char const *argv[])
{
	vector<int> input = {0,0,0,0};
	auto c = clock();
	vector<vector<int> > ans = threeSum(input);
	cout <<clock() - c << endl;
	for(auto tmp : ans){
		for(auto t : tmp)
			cout << " " << t;
		cout << endl;
	}
	return 0;
}

//LLAMA2-13B DATASET v1.0 Category: Compression algorithms ; Style: protected
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LEN 1024
#define MASK 0x55555555

void compress(char *str) {
    int i, j, k, len = strlen(str);
    char *dst = malloc(len / 2 * sizeof(char));
    char *src = str;

    for (i = 0; i < len; i++) {
        if (src[i] == 'a' || src[i] == 'e' || src[i] == 'i' || src[i] == 'o' || src[i] == 'u') {
            j = i + 1;
            while (j < len && src[j] == 'a' || src[j] == 'e' || src[j] == 'i' || src[j] == 'o' || src[j] == 'u') {
                j++;
            }
            k = j - i;
            if (k > 2) {
                dst[i / 2] = (src[i] - 'a' + 'a') << 1;
                for (int m = 1; m < k; m++) {
                    dst[i / 2 + m] = (src[i + m] - 'a' + 'a') << 1;
                }
            } else {
                dst[i / 2] = src[i];
            }
            i += k;
        } else {
            dst[i / 2] = src[i];
        }
    }
    *(str = dst) = '\0';
}

void decompress(char *str) {
    int i, j, k, len = strlen(str);
    char *dst = malloc(len * sizeof(char));
    char *src = str;

    for (i = 0; i < len; i++) {
        if (src[i] & MASK) {
            j = i + 1;
            while (j < len && src[j] & MASK) {
                j++;
            }
            k = j - i;
            for (int m = 1; m < k; m++) {
                dst[i + m] = (src[i + m] & MASK) + 'a';
            }
        } else {
            dst[i] = src[i];
        }
    }
    *(str = dst) = '\0';
}

int main() {
    char str[] = "The quick brown fox jumps over the lazy dog";
    compress(str);
    printf("%s\n", str);
    decompress(str);
    printf("%s\n", str);
    return 0;
}

