#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>

#define WIDTH 64
#define HEIGHT 64
#define BPP 3

typedef struct Pixel {
    unsigned char r;
    unsigned char g;
    unsigned char b;
} Pixel;

void generate_random_pixel(Pixel* pixel) {
    pixel->r = rand() % 256;
    pixel->g = rand() % 256;
    pixel->b = rand() % 256;
}

void save_ppm(const char* filename, Pixel* data, int width, int height) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Error opening file for writing");
        exit(EXIT_FAILURE);
    }

    fprintf(file, "P3\n%d %d\n255\n", width, height);

    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            Pixel* pixel = data + (y * width + x);
            fprintf(file, "%d %d %d\n", pixel->r, pixel->g, pixel->b);
        }
    }

    fclose(file);
}

int main() {
    srand(time(NULL));

    Pixel* pixels = mmap(NULL, WIDTH * HEIGHT * BPP, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    if (pixels == MAP_FAILED) {
        perror("Error initializing memory mapping");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < WIDTH * HEIGHT; i++) {
        generate_random_pixel(pixels + i);
    }

    char filename[100];
    sprintf(filename, "output.ppm");
    save_ppm(filename, pixels, WIDTH, HEIGHT);

    munmap(pixels, WIDTH * HEIGHT * BPP);

    return EXIT_SUCCESS;
}

//GPT-4o-mini DATASET v1.0 Category: CPU usage monitor ; Style: real-life
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <sys/sysinfo.h>
#include <signal.h>
#include <stdbool.h>
#include <time.h>

#define INTERVAL_SEC 1

volatile sig_atomic_t keepRunning = true;

void handleSignal(int signal) {
    if (signal == SIGINT) {
        keepRunning = false;
    }
}

void getCpuUsage(float *usage) {
    FILE *fp;
    long total1, total2, idle1, idle2;
    char buffer[1024];

    // Read CPU stats from /proc/stat
    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Failed to open /proc/stat");
        exit(EXIT_FAILURE);
    }

    // Read the first line (cpu)
    fgets(buffer, sizeof(buffer), fp);
    sscanf(buffer, "cpu %ld %*s %*s %ld", &total1, &idle1);
    fclose(fp);

    sleep(INTERVAL_SEC);

    // Read CPU stats again after interval
    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Failed to open /proc/stat");
        exit(EXIT_FAILURE);
    }

    fgets(buffer, sizeof(buffer), fp);
    sscanf(buffer, "cpu %ld %*s %*s %ld", &total2, &idle2);
    fclose(fp);

    // Calculate CPU usage
    long total_time = total2 - total1;
    long idle_time = idle2 - idle1;
    *usage = 100.0 * (total_time - idle_time) / total_time;
}

void displayCpuUsage() {
    float cpuUsage;
    time_t now;
    char timeString[100];

    while (keepRunning) {
        getCpuUsage(&cpuUsage);
        now = time(NULL);
        strftime(timeString, sizeof(timeString), "%Y-%m-%d %H:%M:%S", localtime(&now));

        printf("\r[%s] CPU Usage: %.2f%%       ", timeString, cpuUsage);
        fflush(stdout);
    }
    printf("\nExiting...\n");
