#define MAX_TEMP 50.0
#define MIN_PRES 950.0
#define MAX_PRES 1050.0
#define MIN_HUM 0.0
#define MAX_HUM 100.0
#define RANDOM_SEED 12345
struct Weather {
    double temperature;
    double pressure;
    double humidity;
};
void generate_random_number(double min, double max, double* random_number) {
    double range = max - min;
    double random_value = (double) rand() / RAND_MAX;
    *random_number = min + random_value * range;
}
void update_weather(struct Weather* weather) {
    double temperature_change = (drand48() * 2 - 1) * 5.0;
    double pressure_change = (drand48() * 2 - 1) * 50.0;
    double humidity_change = (drand48() * 2 - 1) * 10.0;
    weather->temperature += temperature_change;
    if (weather->temperature < MIN_TEMP) {
        weather->temperature = MIN_TEMP;
    } else if (weather->temperature > MAX_TEMP) {
        weather->temperature = MAX_TEMP;
    }
    weather->pressure += pressure_change;
    if (weather->pressure < MIN_PRES) {
        weather->pressure = MIN_PRES;
    } else if (weather->pressure > MAX_PRES) {
        weather->pressure = MAX_PRES;
    }
    weather->humidity += humidity_change;
    if (weather->humidity < MIN_HUM) {
        weather->humidity = MIN_HUM;
    } else if (weather->humidity > MAX_HUM) {
        weather->humidity = MAX_HUM;
    }
}
