#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int id;
    int price;
} AuctionItem;

typedef struct {
    int bid;
    int bidder;
} Bid;

int main() {
    // Create an array of auction items
    AuctionItem items[] = {
        {1, 100},
        {2, 200},
        {3, 300}
    };

    // Create an array of bids
    Bid bids[] = {
        {0, 0},
        {100, 1},
        {200, 2},
        {300, 3}
    };

    // Initialize the current bid to 0
    int current_bid = 0;

    // Keep track of the highest bidder
    int highest_bidder = 0;

    // Print the list of items
    printf("List of Items:\n");
    for (int i = 0; i < 3; i++) {
        printf("Item %d: %d\n", i+1, items[i].price);
    }

    // Start the auction
    printf("Auction started...\n");

    // Bid until the highest bidder changes
    while (current_bid!= bids[highest_bidder].bid) {
        // Print the current bid
        printf("Current Bid: %d\n", current_bid);

        // Get the next bid
        int next_bid;
        scanf("%d", &next_bid);

        // Check if the bid is valid
        if (next_bid > current_bid) {
            // Update the current bid
            current_bid = next_bid;

            // Update the highest bidder
            if (next_bid > bids[highest_bidder].bid) {
                highest_bidder = bids[next_bid].bidder;
            }
        } else {
            printf("Invalid bid!\n");
        }
    }

    // Print the winner
    printf("Winner: %d (bid %d)\n", highest_bidder+1, bids[highest_bidder].bid);

    return 0;
}

