#define CELL_SIZE 10
#define WIDTH (CELL_SIZE * 10)
#define HEIGHT (CELL_SIZE * 20)

typedef struct {
    int x;
    int y;
} Cell;

typedef struct {
    Cell cell[WIDTH * HEIGHT];
} Grid;

void initGrid(Grid *grid) {
    int i, j;

    for (i = 0; i < WIDTH; i++) {
        for (j = 0; j < HEIGHT; j++) {
            grid->cell[i * HEIGHT + j].x = i % 2 == 0 ? 1 : 0;
            grid->cell[i * HEIGHT + j].y = j % 2 == 0 ? 1 : 0;
        }
    }
}

void updateGrid(Grid *grid) {
    int i, j;

    for (i = 0; i < WIDTH; i++) {
        for (j = 0; j < HEIGHT; j++) {
            if (grid->cell[i * HEIGHT + j].x == 1) {
                if (grid->cell[i * HEIGHT + j].y == 1) {
                    grid->cell[i * HEIGHT + j].x = 0;
                } else {
                    grid->cell[i * HEIGHT + j].x = 1;
                }
            }
        }
    }
}

void drawGrid(Grid *grid) {
    int i, j;

    for (i = 0; i < WIDTH; i++) {
        for (j = 0; j < HEIGHT; j++) {
            if (grid->cell[i * HEIGHT + j].x == 1) {
                printf("X ");
            } else {
                printf(" ");
            }
        }
        printf("\n");
    }
}

int main() {
    Grid grid;

    initGrid(&grid);

    for (int i = 0; i < 100; i++) {
        updateGrid(&grid);
        drawGrid(&grid);
    }

    return 0;
}

