//GEMINI-pro DATASET v1.0 Category: Compression algorithms ; Style: recursive
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct node {
    char *data;
    int count;
    struct node *left;
    struct node *right;
} node;

node *create_node(char *data, int count) {
    node *new_node = malloc(sizeof(node));
    new_node->data = strdup(data);
    new_node->count = count;
    new_node->left = NULL;
    new_node->right = NULL;
    return new_node;
}

void insert_node(node **root, char *data, int count) {
    if (*root == NULL) {
        *root = create_node(data, count);
        return;
    }

    if (strcmp(data, (*root)->data) < 0) {
        insert_node(&(*root)->left, data, count);
    } else if (strcmp(data, (*root)->data) > 0) {
        insert_node(&(*root)->right, data, count);
    } else {
        (*root)->count += count;
    }
}

void build_tree(node **root, char *data, int length) {
    if (length == 0) {
        return;
    }

    char *sub_data = malloc(length - 1);
    memcpy(sub_data, data, length - 1);
    insert_node(root, sub_data, 1);

    build_tree(root, data + 1, length - 1);
}

void print_tree(node *root, int depth) {
    if (root == NULL) {
        return;
    }

    for (int i = 0; i < depth; i++) {
        printf("  ");
    }
    printf("%s (%d)\n", root->data, root->count);

    print_tree(root->left, depth + 1);
    print_tree(root->right, depth + 1);
}

void free_tree(node *root) {
    if (root == NULL) {
        return;
    }

    free(root->data);
    free_tree(root->left);
    free_tree(root->right);
    free(root);
}

int main() {
    char *data = "Lorem ipsum dolor sit amet, consectetur adipiscing elit. Maecenas eget lacus eget nunc tincidunt laoreet. Nunc eget arcu eget nunc tincidunt laoreet. Nunc eget arcu eget nunc tincidunt laoreet.";
    int length = strlen(data);

    node *root = NULL;
    build_tree(&root, data, length);

    print_tree(root, 0);

    free_tree(root);

    return 0;
}

