#include <complex.h>

#define SAMPLE_RATE 8000
#define N_SAMPLES (5 * SAMPLE_RATE)
#define WINDOW_SIZE 1024

typedef complex double cplx;

void hanning_window(float *buffer, int size) {
    int i;
    float factor = 0.5;
    for (i = 0; i < size; i++) {
        buffer[i] *= factor * (1 - cos(2 * M_PI * i / (float)size));
    }
}

void generate_sine_wave(cplx *buf, int num_samples, double freq, double amp) {
    int i;
    for (i = 0; i < num_samples; i++) {
        buf[i] = amp * cexp(I * 2 * M_PI * freq * i / SAMPLE_RATE);
    }
}

int main() {
