    float *input_buffer, *output_buffer;
    cplx *input_complex, *output_complex;

    input_buffer = (float *)calloc(N_SAMPLES, sizeof(float));
    output_buffer = (float *)calloc(N_SAMPLES, sizeof(float));
    input_complex = (cplx *)calloc(N_SAMPLES, sizeof(cplx));
    output_complex = (cplx *)calloc(N_SAMPLES, sizeof(cplx));

