void Bubblesort (int W[], int anzahl) 
{
    int dummy;
    int i, j;

    for(i = anzahl - 2; i >= 0; i--)
    {
        for(j = 0; j <= i; j++)
        {
            if(W[j] > W[j + 1])
            {
                dummy = W[j];
                W[j] = W[j + 1];
                W[j + 1] = dummy;
            }
        }
    }
