// Function to create a new process and run it
void run_process(const char* command) {
  // Create a new process
  pid_t pid = fork();

  // If the fork failed...
  if (pid == -1) {
    print_message("Fork failed! 😱");
    return;
  }

  // If the pid is 0...
  if (pid == 0) {
    // Run the command in the background
    print_message("Running command: ");
    execv(command, NULL);
  }

  // If the pid is not 0...
  else {
    // Wait for the command to finish
    wait(NULL);
  }
}

