//MISTRAL-7B DATASET v1.0 Category: Checksum Calculator ; Style: interoperable
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <fcntl.h>
#include <errno.h>
#include <stdint.h>

#define CHECKSUM_SIZE 2

uint16_t calc_checksum(uint16_t sum, const void *buf, size_t len) {
    const uint8_t *data = buf;
    size_t remain = len;

    while (remain) {
        sum += *data++;
        remain -= sizeof(uint8_t);

        if (remain && (len & 1)) {
            sum = (sum >> 8) + (sum & 0xff);
        }
    }

    sum = (sum >> 16) + (sum & 0xffff);
    sum = sum & 0xffff;

    return sum;
}

int main(int argc, char *argv[]) {
    const char *input;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <string>\n", argv[0]);
        return EXIT_FAILURE;
    }

    input = argv[1];

    size_t len = strlen(input);
    uint8_t *buffer = malloc(len + CHECKSUM_SIZE);

    memcpy(buffer, input, len);
    uint16_t sum = htons(0xFFFF);

    sum = calc_checksum(sum, buffer, len + CHECKSUM_SIZE);
    memcpy(buffer + len, &sum, CHECKSUM_SIZE);

    printf("Input string: %s\n", input);
    printf("Checksum: ");
    for (size_t i = 0; i < CHECKSUM_SIZE; ++i) {
        putchar(buffer[len + i]);
    }
    putchar('\n');

    free(buffer);

    return EXIT_SUCCESS;
}

//Falcon-180B DATASET v1.0 Category: Data recovery tool ; Style: shocked
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>

#define BUFFER_SIZE 1024

int main(int argc, char **argv) {
    if (argc!= 3) {
        printf("Usage:./program <filename> <output_file>\n");
        return 1;
    }

    char *filename = argv[1];
    char *output_file = argv[2];

    int fd_in = open(filename, O_RDONLY);
    if (fd_in == -1) {
        printf("Error opening input file: %s\n", filename);
        return 1;
    }

    struct stat stat_buf;
    if (fstat(fd_in, &stat_buf) == -1) {
        printf("Error getting file size: %s\n", filename);
        close(fd_in);
        return 1;
    }

    size_t file_size = stat_buf.st_size;

    char *buffer = malloc(BUFFER_SIZE);
    if (buffer == NULL) {
        printf("Error allocating memory\n");
        close(fd_in);
        return 1;
    }

    int fd_out = open(output_file, O_CREAT | O_WRONLY, 0644);
    if (fd_out == -1) {
        printf("Error opening output file: %s\n", output_file);
        free(buffer);
        close(fd_in);
        return 1;
    }

    int bytes_read = 0;
    while (bytes_read < file_size) {
        int bytes_to_read = file_size - bytes_read;
        if (bytes_to_read > BUFFER_SIZE) {
            bytes_to_read = BUFFER_SIZE;
        }

        int bytes_written = write(fd_out, buffer, bytes_to_read);
        if (bytes_written == -1) {
            printf("Error writing to output file: %s\n", output_file);
            free(buffer);
            close(fd_in);
            close(fd_out);
            return 1;
        }

        bytes_read += bytes_written;
    }

    free(buffer);
    close(fd_in);
    close(fd_out);

    printf("File %s successfully recovered to %s\n", filename, output_file);

    return 0;
}

#include <stdio.h>
#include <stdbool.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ITEMS 100
#define MAX_BIDDERS 10

typedef struct {
    int itemNumber;
    char itemName[50];
    double startPrice;
    double currentBid;
    char seller[50];
    bool sold;
    char soldTo[50];
} Item;

typedef struct {
    char bidderName[50];
    double balance;
    int itemsBiddedOn[MAX_ITEMS];
    double bidAmounts[MAX_ITEMS];
    int numBids;
} Bidder;

Item items[MAX_ITEMS];
Bidder bidders[MAX_BIDDERS];

int numItems = 0;
int numBidders = 0;

void addItem(char seller[50], char itemName[50], double startPrice) {
    if (numItems < MAX_ITEMS) {
        items[numItems].itemNumber = numItems + 1;
        strcpy(items[numItems].itemName, itemName);
        items[numItems].startPrice = startPrice;
        items[numItems].currentBid = startPrice;
        strcpy(items[numItems].seller, seller);
        items[numItems].sold = false;
        numItems++;
        printf("Item '%s' added successfully.\n", itemName);
    } else {
        printf("Maximum number of items reached.\n");
    }
}

void displayItems() {
    printf("-----------\n");
    printf("Current Items:\n");
    printf("-----------\n");
    for (int i = 0; i < numItems; i++) {
        printf("[%d] %s (Seller: %s, Starting price: %.2f, Current bid: %.2f)\n", items[i].itemNumber, items[i].itemName, items[i].seller, items[i].startPrice, items[i].currentBid);
    }
    printf("\n");
}

void displayBidders() {
    printf("-----------\n");
    printf("Current Bidders:\n");
    printf("-----------\n");
    for (int i = 0; i < numBidders; i++) {
        printf("[%d] %s (Balance: %.2f)\n", i+1, bidders[i].bidderName, bidders[i].balance);
    }
    printf("\n");
}

void addBid(int bidderIndex, int itemNumber, double bidAmount) {
    Bidder *bidder = &bidders[bidderIndex];
    Item *item = &items[itemNumber-1];
    if (bidAmount > bidder->balance) {
        printf("Bid amount exceeds bidder's balance.\n");
        return;
    }
    if (bidAmount <= item->currentBid) {
        printf("Bid amount must be higher than current bid.\n");
        return;
    }
    if (item->sold) {
        printf("Item already sold to %s.\n", item->soldTo);
        return;
    }
    item->currentBid = bidAmount;
    bidder->balance -= bidAmount;
    bidder->itemsBiddedOn[bidder->numBids] = itemNumber;
    bidder->bidAmounts[bidder->numBids] = bidAmount;
    bidder->numBids++;
}

void sellItem(int itemNumber, int bidderIndex) {
    Item *item = &items[itemNumber-1];
    Bidder *bidder = &bidders[bidderIndex];
    if (item->sold) {
        printf("Item already sold to %s.\n", item->soldTo);
        return;
    }
    item->sold = true;
    strcpy(item->soldTo, bidder->bidderName);
    bidder->balance += item->currentBid;
    for (int i = 0; i < numBidders; i++) {
        if (i != bidderIndex) {
            for (int j = 0; j < bidders[i].numBids; j++) {
                if (bidders[i].itemsBiddedOn[j] == itemNumber) {
                    bidders[i].balance += bidders[i].bidAmounts[j];
                    printf("%s has been refunded $%.2f for item %d.\n", bidders[i].bidderName, bidders[i].bidAmounts[j], itemNumber);
                    bidders[i].numBids--;
                }
            }
        }
    }
    printf("%s sold item %d to %s for $%.2f.\n", item->seller, itemNumber, item->soldTo, item->currentBid);
}

int main() {
    char command[50];
    char name[50];
    char itemName[50];
    double startPrice;
    int itemNumber;
    int bidderIndex;
    double bidAmount;
    printf("Welcome to the Digital Auction System!\n\n");
    while (true) {
        printf("> ");
        scanf("%s", command);
        if (strcmp(command, "additem") == 0) {
            scanf("%s %lf", name, &startPrice);
            fgets(itemName, 50, stdin);
            itemName[strcspn(itemName, "\n")] = 0;
            addItem(name, itemName, startPrice);
        } else if (strcmp(command, "displayitems") == 0) {
            displayItems();
        } else if (strcmp(command, "addbidder") == 0) {
            scanf("%s %lf", name, &bidAmount);
            if (numBidders < MAX_BIDDERS) {
                strcpy(bidders[numBidders].bidderName, name);
                bidders[numBidders].balance = bidAmount;
                numBidders++;
                printf("%s registered successfully.\n", name);
            } else {
                printf("Maximum number of bidders reached.\n");
            }
        } else if (strcmp(command, "displaybidders") == 0) {
            displayBidders();
        } else if (strcmp(command, "bid") == 0) {
            scanf("%d %lf", &bidderIndex, &bidAmount);
            printf("Bidder %s, please enter item number: ", bidders[bidderIndex-1].bidderName);
            scanf("%d", &itemNumber);
            addBid(bidderIndex-1, itemNumber, bidAmount);
        } else if (strcmp(command, "sell") == 0) {
            scanf("%d %d", &itemNumber, &bidderIndex);
            sellItem(itemNumber, bidderIndex-1);
        } else if (strcmp(command, "quit") == 0) {
            printf("Goodbye!\n");
            return 0;
        } else {
            printf("Invalid command.\n");
        }
    }
}

