#include <stdio.h>
#include <string.h>
#include <unistd.h>

#define MAX_PASSWD_LENGTH 255

void check_password_strength(char *passwd)
{
    int password_length = strlen(passwd);
    int has_upper = 0;
    int has_lower = 0;
    int has_number = 0;
    int has_symbol = 0;

    for (int i = 0; i < password_length; i++)
    {
        char letter = passwd[i];

        if (isupper(letter))
            has_upper = 1;

        if (islower(letter))
            has_lower = 1;

        if (isdigit(letter))
            has_number = 1;

        if (ispunct(letter))
            has_symbol = 1;
    }

    if (password_length < 8)
        fprintf(stderr, "Password too short.\n");

    if (!has_upper)
        fprintf(stderr, "Password lacks upper case letter.\n");

    if (!has_lower)
        fprintf(stderr, "Password lacks lower case letter.\n");

    if (!has_number)
        fprintf(stderr, "Password lacks number.\n");

    if (!has_symbol)
        fprintf(stderr, "Password lacks symbol.\n");

    if (has_upper && has_lower && has_number && has_symbol && password_length >= 8)
        fprintf(stdout, "Password is strong.\n");
}

int main()
{
    char passwd[MAX_PASSWD_LENGTH];

    printf("Enter password: ");
    fgets(passwd, MAX_PASSWD_LENGTH, stdin);

    check_password_strength(passwd);

    return 0;
}

