#include <stdlib.h>
#include <stdio.h>
#include <stdbool.h>
#include <stdint.h>

typedef struct Node {
    uint32_t value;
    struct Node *next;
} Node;

typedef struct Circuit {
    uint32_t num_nodes;
    Node **nodes;
} Circuit;

Circuit *create_circuit(uint32_t num_nodes) {
    Circuit *circuit = malloc(sizeof(Circuit));
    circuit->num_nodes = num_nodes;
    circuit->nodes = malloc(num_nodes * sizeof(Node *));
    for (uint32_t i = 0; i < num_nodes; i++) {
        circuit->nodes[i] = NULL;
    }
    return circuit;
}

void destroy_circuit(Circuit *circuit) {
    for (uint32_t i = 0; i < circuit->num_nodes; i++) {
        Node *node = circuit->nodes[i];
        while (node != NULL) {
            Node *next = node->next;
            free(node);
            node = next;
        }
    }
    free(circuit->nodes);
    free(circuit);
}

void add_edge(Circuit *circuit, uint32_t from, uint32_t to) {
    Node *node = malloc(sizeof(Node));
    node->value = to;
    node->next = circuit->nodes[from];
    circuit->nodes[from] = node;
}

void simulate_circuit(Circuit *circuit) {
    uint32_t *visited = calloc(circuit->num_nodes, sizeof(uint32_t));
    for (uint32_t i = 0; i < circuit->num_nodes; i++) {
        if (visited[i] == 0) {
            dfs(circuit, i, visited);
        }
    }
    free(visited);
}

void dfs(Circuit *circuit, uint32_t node, uint32_t *visited) {
    visited[node] = 1;
    for (Node *n = circuit->nodes[node]; n != NULL; n = n->next) {
        if (visited[n->value] == 0) {
            dfs(circuit, n->value, visited);
        }
    }
}

int main() {
    Circuit *circuit = create_circuit(4);
    add_edge(circuit, 0, 1);
    add_edge(circuit, 1, 2);
    add_edge(circuit, 2, 3);
    add_edge(circuit, 3, 0);
    simulate_circuit(circuit);
    destroy_circuit(circuit);
    return 0;
}

