        exit(1);
    }

    while (fgets(line, sizeof(line), fp)!= NULL) {
        char *token = strtok(line, ",.?!;:");
        while (token!= NULL) {
            if (numWords >= MAX_WORDS) {
                printf("Error: too many words in input file.\n");
                exit(1);
            }

            strcpy(words[numWords].word, token);
            words[numWords].count = 1;
            numWords++;

            token = strtok(NULL, ",.?!;:");
        }
