#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LOG_LINE 256
#define MAX_NUM_LOGS 1000

typedef enum {
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR,
    LOG_UNKNOWN
} LogLevel;

typedef struct {
    LogLevel level;
    char message[MAX_LOG_LINE];
} LogEntry;

LogLevel determine_log_level(const char *line) {
    if (strstr(line, "INFO")) return LOG_INFO;
    if (strstr(line, "WARNING")) return LOG_WARNING;
    if (strstr(line, "ERROR")) return LOG_ERROR;
    return LOG_UNKNOWN;
}

void print_log_summary(LogEntry logs[], int log_count) {
    int info_count = 0, warning_count = 0, error_count = 0;

    for (int i = 0; i < log_count; i++) {
        switch (logs[i].level) {
            case LOG_INFO:
                info_count++;
                break;
            case LOG_WARNING:
                warning_count++;
                break;
            case LOG_ERROR:
                error_count++;
                break;
            default:
                break;
        }
    }

    printf("Log Summary:\n");
    printf("INFO: %d\n", info_count);
    printf("WARNING: %d\n", warning_count);
    printf("ERROR: %d\n", error_count);
}

void analyze_logs(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error opening file %s\n", filename);
        return;
    }

    LogEntry logs[MAX_NUM_LOGS];
    int log_count = 0;
    char line[MAX_LOG_LINE];

    while (fgets(line, sizeof(line), file) && log_count < MAX_NUM_LOGS) {
        logs[log_count].level = determine_log_level(line);
        strncpy(logs[log_count].message, line, MAX_LOG_LINE);
        log_count++;
    }
    fclose(file);

    print_log_summary(logs, log_count);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <logfile>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    analyze_logs(argv[1]);
    return 0;
}

