#define WIDTH 32
#define HEIGHT 32

typedef struct {
    unsigned char r, g, b;
} pixel;

pixel palette[16] = {
    {255, 0, 0}, {0, 255, 0}, {0, 0, 255}, {255, 255, 0},
    {0, 255, 255}, {255, 0, 255}, {128, 128, 128}, {0, 0, 0},
    {192, 192, 192}, {255, 165, 0}, {0, 191, 255}, {75, 0, 130},
    {139, 69, 19}, {255, 0, 255}, {255, 127, 80}, {148, 0, 211}
};

pixel canvas[WIDTH][HEIGHT];

void generate_random_pixel() {
    pixel p;
    int i, j;

    p.r = rand() % 256;
    p.g = rand() % 256;
    p.b = rand() % 256;

    for (i = 0; i < 16; i++) {
        if ((abs(p.r - palette[i].r) < 32) &&
            (abs(p.g - palette[i].g) < 32) &&
            (abs(p.b - palette[i].b) < 32)) {
            canvas[rand() % WIDTH][rand() % HEIGHT] = palette[i];
            return;
        }
    }

    // If no matching color is found, use the random pixel as is
    canvas[rand() % WIDTH][rand() % HEIGHT] = p;
}

