	for (i = 0; i < length; i++)
	{
		sochuso[i] = rand() % SOCHUSOMAX + 1;
		if (sochuso[i] == 1)
		{
			a[i] = (unsigned long long*)malloc(SOPHANTUMAX * sizeof(unsigned long long));
			a[i][0] = 2 * (rand() % 2);
