#include <stdio.h>
#include <stdlib.h>

// Define a struct to hold the translation table
struct TranslationTable {
    char* input;
    char* output;
};

// Define a function to read in the translation table from a file
void read_translation_table(struct TranslationTable* table, const char* filename) {
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Could not open file %s\n", filename);
        exit(1);
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)!= NULL) {
        char* input = strdup(line);
        char* output = strdup(line);
        table->input = input;
        table->output = output;
    }

    fclose(fp);
}

// Define a function to translate the input string using the translation table
void translate(struct TranslationTable* table, const char* input) {
    if (table == NULL || input == NULL) {
        printf("Invalid input\n");
        return;
    }

    char* translated = strdup(table->input);
    for (int i = 0; i < strlen(translated); i++) {
        if (translated[i] == 'a') {
            translated[i] = 'b';
        } else if (translated[i] == 'b') {
            translated[i] = 'a';
        } else if (translated[i] == 'c') {
            translated[i] = 'd';
        } else if (translated[i] == 'd') {
            translated[i] = 'c';
        }
    }

    printf("%s\n", translated);
}

// Define a function to write the translation table to a file
void write_translation_table(struct TranslationTable* table, const char* filename) {
    FILE* fp = fopen(filename, "w");
    if (fp == NULL) {
        printf("Could not open file %s\n", filename);
        exit(1);
    }

    fprintf(fp, "%s\n", table->input);
    fprintf(fp, "%s\n", table->output);

    fclose(fp);
}

int main(int argc, char** argv) {
    if (argc!= 3) {
        printf("Usage: %s <input_filename> <output_filename>\n", argv[0]);
        exit(1);
    }

    struct TranslationTable table;
    read_translation_table(&table, argv[1]);
    translate(&table, argv[2]);
    write_translation_table(&table, argv[2]);

    return 0;
}

