#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/mman.h>

#define MEMORY_SIZE (1024 * 1024)
#define BLOCK_SIZE (32)

// Structure to hold memory block data
typedef struct {
    char *data;
    size_t size;
} mem_block_t;

// Array to store memory blocks
mem_block_t blocks[MEMORY_SIZE / BLOCK_SIZE];

// Current memory block index
size_t current_block = 0;

// Function to allocate a memory block
void *alloc_memory(size_t size) {
    // Check if there is enough memory available
    if (current_block + size > MEMORY_SIZE) {
        printf("Error: Insufficient memory available\n");
        return NULL;
    }

    // Allocate a new memory block
    void *ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE, -1, 0);
    if (ptr == MAP_FAILED) {
        printf("Error: Memory mapping failed\n");
        return NULL;
    }

    // Add the memory block to the array
    blocks[current_block].data = ptr;
    blocks[current_block].size = size;

    // Increment the current block index
    current_block++;

    return ptr;
}

// Function to deallocate a memory block
void dealloc_memory(void *ptr) {
    // Find the memory block in the array
    for (size_t i = 0; i < current_block; i++) {
        if (blocks[i].data == ptr) {
            // Remove the memory block from the array
            for (size_t j = i; j < current_block - 1; j++) {
                blocks[j] = blocks[j + 1];
            }
            current_block--;
            munmap(ptr, blocks[i].size);
            break;
        }
    }
}

// Function to print the memory blocks
void print_memory() {
    for (size_t i = 0; i < current_block; i++) {
        printf("Block %zu: %p - %zu\n", i, blocks[i].data, blocks[i].size);
    }
}

int main() {
    // Initialize the memory blocks
    for (size_t i = 0; i < MEMORY_SIZE; i += BLOCK_SIZE) {
        alloc_memory(BLOCK_SIZE);
    }

    // Play the memory game
    char *word = "The quick brown fox jumps over the lazy dog";
    for (size_t i = 0; i < strlen(word); i++) {
        char c = word[i];
        alloc_memory(BLOCK_SIZE);
        memcpy(blocks[current_block].data, &c, 1);
        current_block++;
        print_memory();

        // After each block, the player must type a letter to indicate
        // whether the letter was in the block or not
        char letter = getchar();
        if (letter == 'y') {
            // If the letter was in the block, move on to the next block
            print_memory();
        } else {
            // If the letter was not in the block, deallocate the current block
            dealloc_memory(blocks[current_block - 1].data);
            current_block--;
        }
    }

    // After all the blocks have been allocated and the player has
    // indicated whether each letter was in the block or not, print the
    // final memory layout
    print_memory();

    return 0;
}

