typedef struct student//设计链表的数据结构
{
	int id;
	string name;
	student *next;
}node;

node *creat()//新建链表
{
	node *head = NULL, *p = NULL, *s = NULL;
	int x, cycle = 1;
	head = (node *)malloc(sizeof(node));
	p = head;

	while(cycle)//当输入为0时结束录入新数据
	{
		printf("\nPlease input ID：");
		scanf("%d", &x);
		if (x != 0)
		{
			s = (node *)malloc(sizeof(node));
			cout<<"Please input name:";
			s ->id = x;
			cin >> s ->name;
			p ->next = s;
			p = s;
		}
		else
			cycle = 0;
	}

	s = head;//取原始头结点地址
	head = head ->next;//头结点后移一位到有数据的节点上
	s ->next = NULL;//断开原始头结点
	p ->next = NULL;//尾节点指向空表示结束
	free(s);//free原始头结点的内存
//	printf("\n yyy %d \n", head -> id);//head指针指向第一个节点
	return head; 
}

node *insertnode(node *head)//插入新节点
{
	if (NULL != head)
	{
		node *p1, *p2, *p0;
		p1 = head;
		p0 = (node *)malloc(sizeof(node));
		cout << "Please input a new ID you want to add：";
		cin >> p0 ->id ;
		cout << "Please input his/her name：";
		cin >> p0 ->name ;

		while((p1 ->id < p0 ->id)&&(NULL != p1 ->next))
		{
			p2 = p1;
			p1 = p1 ->next;
		}

		if (p1 ->id == p0 ->id)
		{
			cout << "ID号码已存在！"<<endl;
			return head;		
		}
		else if (p1 == head)//考虑头结点
		{
			p0 ->next = p1;
			head = p0;
		}
		else if (NULL == p1 ->next)//考虑尾节点
		{
			if (p0 ->id < p1 ->id)
			{
				p0 ->next = p1;
				p2 ->next = p0;
			}
			else
			{
				p1 ->next = p0;
				p0 ->next = NULL;	
			}

		}
		else//中间节点
		{	
			if (p0 ->id < p1 ->id)
			{
				p0 ->next = p1;
				p2 ->next = p0;
			}
			else
			{
				p2 = p1 ->next;
				p0 ->next = p2;	
				p1 ->next = p0;
			}
		}

		return head;

	}
	else
	{
		printf("Empty List!\n");
		return NULL;
	}
}

