node *sortlistselection(node *head)
{
	if (NULL != head)
	{
		node *p1, *p2;
		int tmpid;
		string tmpname;
		int n = length(head);


		if (1 == n)//如果链表只有一个节点
			printf("Only one node in the list.\n");
		else
		{
			p1 = head;
			p2 = p1 ->next;

			for (int i = 0; i < n - 1; i ++)//selection sort way
			{
				for (int j = i + 1; j < n; j ++)
				{
					if (p1 ->id > p2 ->id)
					{
						tmpid = p1 ->id;
						tmpname = p1 ->name;
						p1 ->id = p2 ->id;
						p1 ->name = p2 ->name;
						p2 ->id = tmpid;
						p2 ->name = tmpname;
					}
					p2 = p2 ->next;
				}
				p1 = p1 ->next;
				p2 = p1 ->next;
			}
		}

		return head;
	}
	else
	{
		printf("Empty List!\n");
		return NULL;
	}

}

node *sortlistbubble(node *head)
{
	if (NULL != head)
	{
		node *p;
		int tmpid,flag = 1;
		string tmpname;
		int n = length(head);

		if (NULL == head ->next)//如果链表只有一个节点
			printf("Only one node in the list.\n");
		else
		{
			p = head;
			for (int i = 0; i < n - 1 && flag; i ++)//bubble sort way
			{
				p = head;
				flag = 0;

				for (int j = 0; j < n - i - 1; j ++)
				{
					if (p ->id > p ->next->id)
					{
						tmpid = p ->id;
						tmpname = p ->name;
						p ->id = p ->next ->id;
						p ->name = p ->next ->name;
						p ->next ->id = tmpid;
						p ->next ->name = tmpname;
						flag = 1;
					}
					p = p ->next;
				}

			}
		}

		return head;
	}
	else
	{
		printf("Empty List!\n");
		return NULL;
	}

}

node *reverselist(node *head)
{
	if (NULL != head || NULL != head ->next)//链表为空或只有一个节点
	{
		node *p1, *p2, *p3;

		p1 = head;
		p2 = p1 ->next;

		while(p2)
		{
			p3 = p2 ->next;
			p2 ->next = p1;
			p1 = p2;
			p2 = p3;//最后p3,p2都为NULL
		}

		head ->next = NULL;
		head = p1;//最后p3,p2都为NULL
		return head;
	}
	else
		return head;
}

