#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/ipc.h>
#include <sys/sem.h>

// Define the semaphore operations
#define SEM_WAIT -1
#define SEM_SIGNAL 1

// Create a semaphore
int create_semaphore(key_t key) {
    int semid;

    // Create the semaphore
    semid = semget(key, 1, IPC_CREAT | IPC_EXCL | 0666);
    if (semid == -1) {
        perror("semget");
        return -1;
    }

    // Initialize the semaphore to 1
    semctl(semid, 0, SETVAL, 1);

    return semid;
}

// Acquire the semaphore
int acquire_semaphore(int semid) {
    struct sembuf sem_op;

    // Set the semaphore operation to wait
    sem_op.sem_num = 0;
    sem_op.sem_op = SEM_WAIT;
    sem_op.sem_flg = SEM_UNDO;

    // Perform the semaphore operation
    if (semop(semid, &sem_op, 1) == -1) {
        perror("semop");
        return -1;
    }

    return 0;
}

// Release the semaphore
int release_semaphore(int semid) {
    struct sembuf sem_op;

    // Set the semaphore operation to signal
    sem_op.sem_num = 0;
    sem_op.sem_op = SEM_SIGNAL;
    sem_op.sem_flg = SEM_UNDO;

    // Perform the semaphore operation
    if (semop(semid, &sem_op, 1) == -1) {
        perror("semop");
        return -1;
    }

    return 0;
}

// The main function
int main() {
    // Create a key for the semaphore
    key_t key = ftok(".", 'a');

    // Create the semaphore
    int semid = create_semaphore(key);
    if (semid == -1) {
        return EXIT_FAILURE;
    }

    // Fork a child process
    pid_t child_pid = fork();
    if (child_pid == -1) {
        perror("fork");
        return EXIT_FAILURE;
    }

    if (child_pid == 0) {
        // Child process

        // Acquire the semaphore
        if (acquire_semaphore(semid) == -1) {
            return EXIT_FAILURE;
        }

        // Critical section
        printf("Child process in critical section\n");

        // Release the semaphore
        if (release_semaphore(semid) == -1) {
            return EXIT_FAILURE;
        }
    } else {
        // Parent process

        // Wait for the child process to finish
        waitpid(child_pid, NULL, 0);

        // Acquire the semaphore
        if (acquire_semaphore(semid) == -1) {
            return EXIT_FAILURE;
        }

        // Critical section
        printf("Parent process in critical section\n");

        // Release the semaphore
        if (release_semaphore(semid) == -1) {
            return EXIT_FAILURE;
        }
    }

    // Delete the semaphore
    if (semctl(semid, 0, IPC_RMID) == -1) {
        perror("semctl");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

