//GEMINI-pro DATASET v1.0 Category: Binary Converter ; Style: Dennis Ritchie
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

typedef struct {
    char *str;
    size_t length;
} BinaryNumber;

BinaryNumber *
hex_to_binary(const char *hex)
{
    if (!hex) {
        return NULL;
    }

    size_t len = strlen(hex);
    if (len % 2 != 0) {
        return NULL;
    }

    BinaryNumber *bn = malloc(sizeof(BinaryNumber));
    if (!bn) {
        return NULL;
    }

    bn->length = len * 4;
    bn->str = malloc(bn->length + 1);
    if (!bn->str) {
        free(bn);
        return NULL;
    }

    for (size_t i = 0, j = 0; i < len; i++) {
        uint8_t c = hex[i];

        if (c >= '0' && c <= '9') {
            c = c - '0';
        } else if (c >= 'A' && c <= 'F') {
            c = c - 'A' + 10;
        } else if (c >= 'a' && c <= 'f') {
            c = c - 'a' + 10;
        } else {
            free(bn->str);
            free(bn);
            return NULL;
        }

        for (int k = 0, shift = 3; k < 4; k++, shift--) {
            bn->str[j++] = (c >> shift) & 1 ? '1' : '0';
        }
    }

    bn->str[bn->length] = '\0';
    return bn;
}

void
print_binary(const BinaryNumber *bn)
{
    if (!bn) {
        return;
    }

    for (size_t i = 0; i < bn->length; i++) {
        putchar(bn->str[i]);
    }

    putchar('\n');
}

void
free_binary(BinaryNumber *bn)
{
    if (!bn) {
        return;
    }

    free(bn->str);
    free(bn);
}

int
main(void)
{
    char hex[] = "DEADBEEF";

    BinaryNumber *bn = hex_to_binary(hex);
    if (!bn) {
        fprintf(stderr, "Invalid hex string\n");
        return EXIT_FAILURE;
    }

    print_binary(bn);
    free_binary(bn);

    return EXIT_SUCCESS;
}

using namespace std;

#include "Network.h"
#include "Link.h"
#include <algorithm>
#include <iostream>

Network::Network(int numNodes) {

	graph.clear();

	// Initialise a vector for each node.
	for(int i = 0; i < numNodes; i++) {
		graph.push_back(vector<Link>());
	}

	this->numNodes = numNodes;
}

void Network::reset(int numNodes) {

	// Initialise a vector for each node.
	for(int i = 0; i < numNodes; i++) {
		graph.push_back(vector<Link>());
	}

	this->numNodes = numNodes;
}


Network::Network() {

	graph.push_back(vector<Link>());
	this->numNodes = 1;
}

void Network::addLink(int orig, int dest, double flow, double cost_a, double cost_b, string name) {

	if ((orig < numNodes) && (dest < numNodes)) {
		graph[orig].push_back(Link(dest, flow, cost_a, cost_b, name));
	} else {
		cout << "Origin or destination node doesn't exist\n";
	}
}

double Network::getTotalCost() {

	double total_cost = 0;

	for(int i = 0; i < graph.size(); i++) {
		for(int j = 0; j < graph[i].size(); j++) {
			total_cost = total_cost + graph[i][j].getUserCost() * graph[i][j].flow;
		}
	}

	return total_cost;
}

void Network::print() {

	cout << ("\nNetwork (flow, cost, marginal cost)\n");
	for(int i = 0; i < graph.size(); i++) {
		for(int j = 0; j < graph[i].size(); j++) {
			cout << i << " " << graph[i][j].name.c_str() << "(" << graph[i][j].flow << " " << graph[i][j].getUserCost() << " " << graph[i][j].getMarginalUserCost() << ")" << " " << graph[i][j].dest << endl;
		}
	}

	cout << "Total network cost is " << getTotalCost() << endl << endl;
}

