#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

#define BLOCK_SIZE 512   // Size of block to read
#define MAX_FILES 100    // Max files to recover
#define MAGIC_NUM 0xBADC0DE  // Example magic number for file detection

typedef struct {
    char name[64]; // File name
    int size;      // File size
    int is_valid;  // Flag to indicate valid file
} FileInfo;

void clear_file_info(FileInfo *file) {
    memset(file->name, 0, sizeof(file->name));
    file->size = 0;
    file->is_valid = 0;
}

void print_usage() {
    printf("Usage: ./data_recovery_tool <device>\n");
    printf("Example: ./data_recovery_tool /dev/sdX\n");
}

void recover_files(const char* device, FileInfo* files, int *file_count) {
    int fd = open(device, O_RDONLY);
    if (fd < 0) {
        perror("Failed to open device");
        exit(EXIT_FAILURE);
    }

    unsigned char buffer[BLOCK_SIZE];
    int block_num = 0;
    *file_count = 0;

    while (read(fd, buffer, BLOCK_SIZE) == BLOCK_SIZE) {
        if (*(int*)buffer == MAGIC_NUM) {
            if (*file_count < MAX_FILES) {
                FileInfo *current_file = &files[*file_count];
                sprintf(current_file->name, "recovered_file_%d.dat", *file_count);
                current_file->size = (buffer[4] << 24) | (buffer[5] << 16) | (buffer[6] << 8) | buffer[7];
                current_file->is_valid = 1;
                (*file_count)++;
                printf("Found valid file: %s with size %d bytes at block %d\n", current_file->name, current_file->size, block_num);
            }
        }
        block_num++;
    }
    close(fd);
}

void write_recovered_file(FileInfo file) {
    FILE *fp = fopen(file.name, "wb");
    if (fp == NULL) {
        perror("Failed to create file");
        return;
    }

    // Simulating writing dummy data
    unsigned char *data = malloc(file.size);
    memset(data, 0xFF, file.size); // Fill with dummy data for simulation
    fwrite(data, 1, file.size, fp);

    free(data);
    fclose(fp);
    printf("Recovered file written: %s\n", file.name);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        print_usage();
        return EXIT_FAILURE;
    }

    const char* device = argv[1];
    FileInfo files[MAX_FILES];
    int file_count = 0;

    // Initialize file info array
    for (int i = 0; i < MAX_FILES; i++) {
        clear_file_info(&files[i]);
    }

    // Step 1: Recover files from the device
    recover_files(device, files, &file_count);

    // Step 2: Write recovered files to disk
    for (int i = 0; i < file_count; i++) {
        if (files[i].is_valid) {
            write_recovered_file(files[i]);
        }
    }

    printf("Recovery process complete. Total files recovered: %d\n", file_count);
    return EXIT_SUCCESS;
}

