#include <stdio.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <string.h>
#include <stdlib.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netdb.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define BUFFER_SIZE 1024

int main() {
    // Create a socket
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("Socket creation error");
        exit(EXIT_FAILURE);
    }

    // Create a socket address structure
    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(0); // Use any non-privileged port

    // Bind the socket to a port
    if (bind(sockfd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Bind error");
        exit(EXIT_FAILURE);
    }

    // Set the time-to-live for the broadcast
    int ttl = 1;
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("setsockopt error");
        exit(EXIT_FAILURE);
    }

    // Create the message to be sent
    char message[BUFFER_SIZE];
    strcpy(message, "Wireless Network Scanner\r\n");

    // Send the message to the broadcast address
    int n = sendto(sockfd, message, strlen(message), 0, (struct sockaddr *)&addr, sizeof(addr));
    if (n < 0) {
        perror("Sendto error");
        exit(EXIT_FAILURE);
    }

    // Receive the responses
    char response[BUFFER_SIZE];
    memset(response, 0, BUFFER_SIZE);
    while (1) {
        // Receive a response
        ssize_t len = recvfrom(sockfd, response, BUFFER_SIZE, 0, NULL, NULL);
        if (len < 0) {
            perror("Receive error");
            exit(EXIT_FAILURE);
        }

        // Print the response
        printf("%s", response);

        // Break the loop if the message is empty
        if (strstr(response, "\r\n")!= NULL)
            break;
    }

    // Close the socket
    close(sockfd);

    return 0;
}

