//Falcon-180B DATASET v1.0 Category: Word Count Tool ; Style: synchronous
#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <string.h>

#define MAX_WORDS 1000 // maximum number of words
#define MAX_WORD_LEN 20 // maximum length of a word

typedef struct {
    char word[MAX_WORD_LEN];
    int count;
} WordCount;

int main() {
    FILE* fp;
    char line[1000];
    char* word;
    WordCount word_counts[MAX_WORDS];
    int num_words = 0;
    int i;

    // open file for reading
    fp = fopen("input.txt", "r");
    if (fp == NULL) {
        printf("Error: could not open file.\n");
        exit(1);
    }

    // read file line by line
    while (fgets(line, sizeof(line), fp)!= NULL) {
        // convert line to lowercase
        for (i = 0; line[i]!= '\0'; i++) {
            line[i] = tolower(line[i]);
        }

        // tokenize line into words
        word = strtok(line, ",.?!;:");
        while (word!= NULL) {
            // check if word is too long
            if (strlen(word) > MAX_WORD_LEN) {
                printf("Warning: word \"%s\" is too long (max %d characters).\n", word, MAX_WORD_LEN);
            } else {
                // find or create word count entry
                for (i = 0; i < num_words; i++) {
                    if (strcmp(word_counts[i].word, word) == 0) {
                        // word already exists, increment count
                        word_counts[i].count++;
                        break;
                    }
                }
                if (i == num_words) {
                    // word does not exist, create new entry
                    strcpy(word_counts[num_words].word, word);
                    word_counts[num_words].count = 1;
                    num_words++;
                }
            }
            // get next word
            word = strtok(NULL, ",.?!;:");
        }
    }

    // print word counts
    printf("Word counts:\n");
    for (i = 0; i < num_words; i++) {
        printf("%s: %d\n", word_counts[i].word, word_counts[i].count);
    }

    // close file
    fclose(fp);

    return 0;
}

