//GPT-4o-mini DATASET v1.0 Category: Word Frequency Counter ; Style: Dennis Ritchie
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_WORDS 1000
#define MAX_WORD_LEN 100

struct WordFreq {
    char word[MAX_WORD_LEN];
    int count;
};

int find_word(struct WordFreq words[], int total_words, const char *word) {
    for (int i = 0; i < total_words; i++) {
        if (strcmp(words[i].word, word) == 0) {
            return i;
        }
    }
    return -1; // Not found
}

void sort_words(struct WordFreq words[], int total_words) {
    for (int i = 0; i < total_words - 1; i++) {
        for (int j = i + 1; j < total_words; j++) {
            if (strcmp(words[i].word, words[j].word) > 0) {
                struct WordFreq temp = words[i];
                words[i] = words[j];
                words[j] = temp;
            }
        }
    }
}

void print_word_frequencies(struct WordFreq words[], int total_words) {
    printf("Word Frequencies:\n");
    for (int i = 0; i < total_words; i++) {
        printf("%s: %d\n", words[i].word, words[i].count);
    }
}

int main() {
    struct WordFreq words[MAX_WORDS];
    int total_words = 0;
    char word[MAX_WORD_LEN];

    printf("Enter text (end with EOF, Ctrl+D):\n");

    while (scanf("%s", word) != EOF) {
        // Remove punctuation and convert to lowercase
        int len = strlen(word);
        for (int i = 0; i < len; i++) {
            if (isalpha(word[i])) {
                word[i] = tolower(word[i]);
            } else {
                word[i] = '\0'; // replace with null terminator
            }
        }

        if (strlen(word) == 0) continue; // Skip empty word

        int index = find_word(words, total_words, word);
        if (index == -1) { // New word
            strncpy(words[total_words].word, word, MAX_WORD_LEN);
            words[total_words].count = 1;
            total_words++;
        } else { // Existing word
            words[index].count++;
        }
    }

    sort_words(words, total_words);
    print_word_frequencies(words, total_words);

    return 0;
}

//GPT-4o-mini DATASET v1.0 Category: Networking ; Style: satisfied
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <pthread.h>

#define PORT 8080
#define MAX_CLIENTS 10
#define BUFFER_SIZE 1024

static int client_count = 0;
static pthread_mutex_t client_count_mutex = PTHREAD_MUTEX_INITIALIZER;

void *handle_client(void *arg);
void broadcast_message(const char *message, int sender_client);
void remove_client(int socket);

int client_sockets[MAX_CLIENTS];

int main() {
    int server_socket, new_socket;
    struct sockaddr_in server_addr, client_addr;
    socklen_t addr_len = sizeof(client_addr);
    pthread_t tid;

    // Create socket
    if ((server_socket = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Fill server information
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    // Bind the socket to the address
    if (bind(server_socket, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        close(server_socket);
        exit(EXIT_FAILURE);
    }

    // Start listening for clients
    if (listen(server_socket, MAX_CLIENTS) < 0) {
        perror("Listen failed");
        close(server_socket);
        exit(EXIT_FAILURE);
    }

    printf("Chat server started on port %d\n", PORT);

    // Accept clients in a loop
    while (1) {
        new_socket = accept(server_socket, (struct sockaddr*)&client_addr, &addr_len);
        if (new_socket < 0) {
            perror("Accept failed");
            continue;
        }

        // Add the new client
        pthread_mutex_lock(&client_count_mutex);
        if (client_count < MAX_CLIENTS) {
            client_sockets[client_count++] = new_socket;
            pthread_create(&tid, NULL, handle_client, (void*)&new_socket);
            printf("New client connected: %d\n", new_socket);
        } else {
            printf("Max clients reached. Rejecting client: %d\n", new_socket);
            close(new_socket);
        }
        pthread_mutex_unlock(&client_count_mutex);
    }

    // Close the server socket
    close(server_socket);
    return 0;
}

void *handle_client(void *arg) {
    int client_socket = *(int*)arg;
    char buffer[BUFFER_SIZE];
    int bytes_read;

    while (1) {
        // Read message from the client
        bytes_read = read(client_socket, buffer, sizeof(buffer));
        if (bytes_read <= 0) {
            printf("Client disconnected: %d\n", client_socket);
            remove_client(client_socket);
            break;
        }

        // Null terminate the received message
        buffer[bytes_read] = '\0';
        printf("Received message from %d: %s\n", client_socket, buffer);

        // Broadcast the message to other clients
        broadcast_message(buffer, client_socket);
    }

    return NULL;
}

void broadcast_message(const char *message, int sender_client) {
    pthread_mutex_lock(&client_count_mutex);
    for (int i = 0; i < client_count; i++) {
        if (client_sockets[i] != sender_client) {
            send(client_sockets[i], message, strlen(message), 0);
        }
    }
    pthread_mutex_unlock(&client_count_mutex);
}

void remove_client(int socket) {
    pthread_mutex_lock(&client_count_mutex);
    for (int i = 0; i < client_count; i++) {
        if (client_sockets[i] == socket) {
            close(socket);
            client_sockets[i] = client_sockets[--client_count];
            printf("Client removed: %d\n", socket);
            break;
        }
    }
    pthread_mutex_unlock(&client_count_mutex);
}

