#include <stdio.h>
#include <stdlib.h>

// Function to calculate subnet mask
unsigned long calculate_subnet_mask(unsigned long ip_address, unsigned long netmask) {
    unsigned long subnet_mask = 0;

    // Convert IP address and netmask to binary
    char ip_address_binary[33];
    char netmask_binary[33];
    ip_address_to_binary(ip_address, ip_address_binary);
    ip_address_to_binary(netmask, netmask_binary);

    // Calculate subnet mask
    for (int i = 0; i < 32; i++) {
        if (ip_address_binary[i] == netmask_binary[i]) {
            subnet_mask |= (1 << (31 - i));
        }
    }

    return subnet_mask;
}

// Function to convert IP address to binary
void ip_address_to_binary(unsigned long ip_address, char *binary) {
    int i = 0;
    while (ip_address) {
        binary[i++] = (ip_address & 1) ? '1' : '0';
        ip_address >>= 1;
    }
    binary[i] = '\0';
}

int main() {
    // Declare variables
    unsigned long ip_address, netmask, subnet_mask;

    // Get IP address and netmask from user
    printf("Enter IP address: ");
    scanf("%lu", &ip_address);
    printf("Enter netmask: ");
    scanf("%lu", &netmask);

    // Calculate subnet mask
    subnet_mask = calculate_subnet_mask(ip_address, netmask);

    // Print subnet mask
    printf("Subnet mask: %lu\n", subnet_mask);

    return 0;
}

