    scanf("%d %d %d %d", &n, &m, &s, &t);

    for (int i = 0; i < m; i++)
    {
        int a, b, w = 0;
        scanf("%d %d %d", &a, &b, &w);
        G[a - 1].push_back(ii(b - 1, w));
        G[b - 1].push_back(ii(a - 1, w));
    }

    Dijkstra(s - 1);

    printf("%d\n", D[t - 1]);

    return 0;
}

