#include <sys/types.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>
#include <time.h>

#define AUTOMATION_MAGIC 0xDEADBEEF
#define AUTOMATION_FILE "/.automation.db"
#define COMMAND_SIZE 100

typedef struct {
    int magic;
    time_t last_updated;
    char command[COMMAND_SIZE];
} AutomationRule;

void handle_alarm(int signal) {
    printf("Alarm triggered! Running home automation rules...\n");
    int fd = open(AUTOMATION_FILE, O_RDONLY);
    if (fd < 0) {
        perror("Error opening automation file");
        exit(EXIT_FAILURE);
    }

    AutomationRule rule;
    ssize_t nread = read(fd, &rule, sizeof(rule));
    if (nread != sizeof(rule)) {
        perror("Error reading automation rule");
        close(fd);
        exit(EXIT_FAILURE);
    }

    close(fd);

    if (rule.magic != AUTOMATION_MAGIC) {
        printf("Invalid magic number in automation rule\n");
        exit(EXIT_FAILURE);
    }

    printf("Running automation rule: %s\n", rule.command);
    system(rule.command);
}

void update_automation_file(const char *command) {
    int fd = open(AUTOMATION_FILE, O_RDWR | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (fd < 0) {
        perror("Error opening/creating automation file");
        exit(EXIT_FAILURE);
    }

    AutomationRule rule = {AUTOMATION_MAGIC, time(NULL), command};

    ssize_t nwritten = write(fd, &rule, sizeof(rule));
    if (nwritten != sizeof(rule)) {
        perror("Error writing automation rule");
        close(fd);
        exit(EXIT_FAILURE);
    }

    close(fd);
}

int main(int argc, char *argv[]) {
    signal(SIGALRM, handle_alarm);
    alarm(60); // Check rules every minute

    while (1) {
        pause();
    }

    return EXIT_SUCCESS;
}

void setup_automation_rule(const char *device, const char *command) {
    char rule[COMMAND_SIZE];
    snprintf(rule, COMMAND_SIZE, "echo %s > /sys/%s/state", command, device);
    update_automation_file(rule);
}

