#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <math.h>

#define MAX_LEN 100
#define MIN_OPERAND 1e-20

typedef struct Calculator {
    double stack[10];
    int top;
}Calculator;

Calculator calculator;

void push(double value) {
    if (calculator.top >= 9) {
        printf("Stack Overflow\n");
        exit(EXIT_FAILURE);
    }
    calculator.stack[calculator.top++] = value;
}

double pop() {
    if (calculator.top <= 0) {
        printf("Stack Underflow\n");
        exit(EXIT_FAILURE);
    }
    return calculator.stack[--calculator.top];
}

void display_stack() {
    int i;
    printf("Stack: ");
    for (i = calculator.top; i >= 0; i--) {
        printf("%.12lf ", calculator.stack[i]);
    }
    printf("\n");
}

void process_operand(char op) {
    double b, a;

    a = pop();
    b = pop();

    switch (op) {
        case '+':
            push(a + b);
            break;
        case '-':
            push(a - b);
            break;
        case '*':
            push(a * b);
            break;
        case '/':
            if (b == 0) {
                printf("Error: Division by Zero\n");
                exit(EXIT_FAILURE);
            }
            push(a / b);
            break;
        case '^':
            push(pow(a, b));
            break;
        default:
            printf("Error: Unsupported Operator\n");
            exit(EXIT_FAILURE);
    }
}

int is_operator(char c) {
    return (strchr("+-*/^", c) != NULL);
}

void calculate(char *input) {
    int i;
    double num;

    calculator.top = 0;

    for (i = 0; input[i] != '\0'; i++) {
        if (isdigit(input[i])) {
            num = strtod(&input[i], NULL);
            push(num);
        } else if (is_operator(input[i])) {
            process_operand(input[i]);
        } else if (input[i] == 's') {
            display_stack();
        } else {
            printf("Error: Unsupported Character\n");
            exit(EXIT_FAILURE);
        }
    }

    if (calculator.top != 1) {
        printf("Error: Stack Unbalanced\n");
        exit(EXIT_FAILURE);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s <expression>\n", argv[0]);
        return EXIT_FAILURE;
    }

    calculator.top = 0;

    if (isdigit(argv[1][0])) {
        calculate(argv[1]);
    } else {
        printf("Error: Invalid Input\n");
        calculate("0");
    }

    printf("Result: %.12lf\n", pop());

    return EXIT_SUCCESS;
}

//LLAMA2-13B DATASET v1.0 Category: File handling ; Style: statistical
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>

#define MAX_LINE_LENGTH 1024
#define MAX_FILE_SIZE 100000

// Function to read a line from a file and calculate its statistical properties
void read_line(FILE *file, char *line, int *len, double *avg, double *stddev) {
    int i;
    double sum = 0;
    double sum_squared = 0;

    // Read the line from the file
    *len = fread(line, 1, MAX_LINE_LENGTH, file);
    line[*len] = '\0';

    // Calculate the average and standard deviation of the line
    for (i = 0; i < *len; i++) {
        sum += line[i];
        sum_squared += line[i] * line[i];
    }

    *avg = sum / *len;
    *stddev = sqrt(sum_squared / (*len - 1));
}

// Function to read a file and calculate its statistical properties
void read_file(char *filename, int *file_size, double *avg, double *stddev) {
    FILE *file = fopen(filename, "r");
    char line[MAX_LINE_LENGTH];
    int len;

    // Calculate the size of the file
    *file_size = 0;
    while (fgets(line, MAX_LINE_LENGTH, file)) {
        *file_size += strlen(line) + 1;
    }

    // Calculate the average and standard deviation of the file
    int num_lines = 0;
    double sum = 0;
    double sum_squared = 0;
    while (fgets(line, MAX_LINE_LENGTH, file)) {
        num_lines++;
        read_line(file, line, &len, &sum, &sum_squared);
    }

    *avg = sum / num_lines;
    *stddev = sqrt(sum_squared / (num_lines - 1));

    fclose(file);
}

int main() {
    char *filename = "example.txt";
    int file_size = 0;
    double avg = 0;
    double stddev = 0;

    // Read the file and calculate its statistical properties
    read_file(filename, &file_size, &avg, &stddev);

    // Print the results
    printf("File size: %d\n", file_size);
    printf("Average: %f\n", avg);
    printf("Standard deviation: %f\n", stddev);

    return 0;
}

