    double value;
};

static struct unit_converter units[UNIT_CONVERTER_MAX_UNITS] = {
    {"m", 1},
    {"cm", 0.01},
    {"mm", 0.001},
    {"km", 1000},
    {"mi", 1609.344},
    {"ft", 3.28084},
    {"yd", 0.9144},
