    srand(time(NULL));
}

void unit_converter_convert(double value, char *from_unit, char *to_unit) {
    int i = 0;
    double converted_value = 0;

    for (i = 0; i < UNIT_CONVERTER_MAX_UNITS; i++) {
        if (strcmp(units[i].name, from_unit) == 0) {
