#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <netdb.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_CLIENTS 10
#define MAX_MSG_LEN 1024

int main() {
    int server_fd, new_fd, client_fds[MAX_CLIENTS];
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_addr_len;
    fd_set read_fds;
    int max_fd = 0;
    int i, j;

    // Create a new socket for the server
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == -1) {
        perror("socket");
        return EXIT_FAILURE;
    }

    // Set the server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(8080);

    // Bind the socket to the server address
    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) == -1) {
        perror("bind");
        return EXIT_FAILURE;
    }

    // Listen for incoming connections
    if (listen(server_fd, MAX_CLIENTS) == -1) {
        perror("listen");
        return EXIT_FAILURE;
    }

    // Initialize the client file descriptors
    for (i = 0; i < MAX_CLIENTS; i++) {
        client_fds[i] = -1;
    }

    // Main loop
    while (1) {
        // Set the read file descriptors
        FD_ZERO(&read_fds);
        FD_SET(server_fd, &read_fds);
        max_fd = server_fd;
        for (i = 0; i < MAX_CLIENTS; i++) {
            if (client_fds[i] != -1) {
                FD_SET(client_fds[i], &read_fds);
                max_fd = max_fd > client_fds[i] ? max_fd : client_fds[i];
            }
        }

        // Select on the read file descriptors
        if (select(max_fd + 1, &read_fds, NULL, NULL, NULL) == -1) {
            perror("select");
            return EXIT_FAILURE;
        }

        // Handle new incoming connections
        if (FD_ISSET(server_fd, &read_fds)) {
            client_addr_len = sizeof(client_addr);
            if ((new_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_addr_len)) == -1) {
                perror("accept");
                return EXIT_FAILURE;
            }

            // Add the new file descriptor to the client file descriptors
            for (i = 0; i < MAX_CLIENTS; i++) {
                if (client_fds[i] == -1) {
                    client_fds[i] = new_fd;
                    break;
                }
            }

            // Send a welcome message to the new client
            char welcome_msg[] = "Welcome to the chat server!\n";
            if (send(new_fd, welcome_msg, strlen(welcome_msg), 0) == -1) {
                perror("send");
                return EXIT_FAILURE;
            }
        }

        // Handle incoming messages from clients
        for (i = 0; i < MAX_CLIENTS; i++) {
            if (client_fds[i] != -1 && FD_ISSET(client_fds[i], &read_fds)) {
                char msg[MAX_MSG_LEN];
                int msg_len = recv(client_fds[i], msg, MAX_MSG_LEN, 0);
                if (msg_len == -1) {
                    perror("recv");
                    return EXIT_FAILURE;
                } else if (msg_len == 0) {
                    // Client has disconnected
                    close(client_fds[i]);
                    client_fds[i] = -1;
                    continue;
                }

                // Broadcast the message to all other clients
                for (j = 0; j < MAX_CLIENTS; j++) {
                    if (client_fds[j] != -1 && client_fds[j] != client_fds[i]) {
                        if (send(client_fds[j], msg, msg_len, 0) == -1) {
                            perror("send");
                            return EXIT_FAILURE;
                        }
                    }
                }
            }
        }
    }

    // Close the server socket
    close(server_fd);

    return EXIT_SUCCESS;
}

