#define MAX_QUERIES 10
#define MAX_THREADS 5

struct query {
    char *sql;
    int id;
};

void *run_query(void *arg) {
    struct query *query = (struct query *) arg;
    MYSQL *conn = mysql_init(NULL);
    if (!mysql_real_connect(conn, "localhost", "username", "password", "database_name", 0, NULL, 0)) {
        fprintf(stderr, "Error connecting to database: %s\n", mysql_error(conn));
        exit(1);
    }
    if (mysql_query(conn, query->sql)) {
        fprintf(stderr, "Error executing query: %s\n", mysql_error(conn));
        exit(1);
    }
    printf("Query %d executed successfully\n", query->id);
    mysql_close(conn);
    return NULL;
}

int main() {
    pthread_t threads[MAX_THREADS];
    struct query queries[MAX_QUERIES] = {
        {"INSERT INTO table_name (column1, column2) VALUES ('value1', 'value2')", 1},
        {"UPDATE table_name SET column1 = 'new_value' WHERE column2 ='some_value'", 2},
        {"DELETE FROM table_name WHERE column1 = 'value_to_delete'", 3},
        {"SELECT * FROM table_name", 4},
        {"CREATE TABLE new_table (column1 INT, column2 VARCHAR(50))", 5},
        {"DROP TABLE table_to_drop", 6},
        {"ALTER TABLE table_name ADD COLUMN new_column VARCHAR(50)", 7},
        {"TRUNCATE TABLE table_name", 8},
        {"SHOW TABLES", 9},
        {"DESCRIBE table_name", 10}
    };

    int i, rc;
    for (i = 0; i < MAX_THREADS; i++) {
        rc = pthread_create(&threads[i], NULL, run_query, &queries[i]);
        if (rc) {
            fprintf(stderr, "Error creating thread: %d\n", rc);
            exit(1);
        }
    }

    for (i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

