#include <iostream>
using namespace std;

int BinaryUpperBound(int *arr, int b, int e, int key) {
  if (!arr || b > e) return -1;
  int result = -1;
  int mid = 0;
  while (b <= e) {
    //cout << "b " << b << " e " << e << endl;
    mid = b + (e - b) / 2;
    if (key >= arr[mid]) {
      if (key == arr[mid])
        result = mid;
      b = mid + 1;
    }
    else
      e = mid - 1;
  }
  return result;
}


