void dijkstra(Node graph[MAX_NODES], int startNode) {
    int n = MAX_NODES;
    int dist[MAX_NODES];
    int visited[MAX_NODES] = {0};
    int i, j, u, minDist;

    for (i = 0; i < n; i++) {
        dist[i] = INF;
    }

    dist[startNode] = 0;

    for (i = 0; i < n - 1; i++) {
        for (j = 0; j < n; j++) {
            if (visited[j] == 0 && dist[j] > dist[i]) {
                dist[j] = dist[i] + graph[i].cost;
            }
        }
    }

    printf("Vertex\tDistance from Source\n");
    for (i = 0; i < n; i++) {
        printf("%d\t\t%d\n", i, dist[i]);
    }
}

