#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define STRING_LENGTH 50
#define NUM_TRIES 3

int main() {
    char string[STRING_LENGTH];
    char userInput[STRING_LENGTH];
    clock_t start, end;
    int tries = 0;

    srand(time(NULL));

    while (1) {
        // Generate a random string of characters
        for (int i = 0; i < STRING_LENGTH; i++) {
            string[i] = (char) (rand() % 94 + 33);
            if (string[i] == '\0') {
                i--;
            }
        }
        string[STRING_LENGTH] = '\0';

        printf("Type the following sequence as fast as you can:\n");
        printf("%s\n", string);
        fgets(userInput, STRING_LENGTH, stdin);

        start = clock();
        for (int i = 0; i < strlen(string); i++) {
            if (string[i] != userInput[i]) {
                tries++;
                break;
            }
        }

        end = clock();
        double timeTaken = ((double) (end - start)) / CLOCKS_PER_SEC;

        if (tries == 0) {
            printf("Congratulations! You typed '%s' correctly and in %.2fs.\n", string, timeTaken);
            break;
        } else {
            printf("Incorrect. Please try again.\n");
            tries--;
            if (tries < 0) {
                printf("Sorry, you have used all your tries. Better luck next time!\n");
                break;
            }
        }
    }

    return 0;
}

