  int map[MAP_HEIGHT][MAP_WIDTH] = {{0}};

  // Initialize the invader
  int invader_x = 0;
  int invader_y = 0;
  int invader_direction = 1;

  // Initialize the player
  int player_x = MAP_WIDTH / 2;
  int player_y = MAP_HEIGHT - 1;

  // Initialize the bullets
  int bullet_x[10] = {0};
  int bullet_y[10] = {0};
  int bullet_direction[10] = {0};

