#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define NUM_CARS 100
#define MAX_SPEED 50
#define MAX_WAIT 5

// Structure to represent a car
typedef struct {
    int x;
    int y;
    int speed;
    int direction;
} Car;

// Function to generate a random number between min and max
int rand_range(int min, int max) {
    return min + rand() % (max - min + 1);
}

// Function to simulate the traffic flow
void simulate_traffic(Car cars[], int num_cars) {
    for (int i = 0; i < num_cars; i++) {
        // Generate a random speed and direction for the car
        cars[i].speed = rand_range(0, MAX_SPEED);
        cars[i].direction = rand_range(0, 360);
    }

    while (1) {
        // Move all cars forward
        for (int i = 0; i < num_cars; i++) {
            if (cars[i].direction == 0) {
                cars[i].x++;
            } else if (cars[i].direction == 90) {
                cars[i].y++;
            } else if (cars[i].direction == 180) {
                cars[i].x--;
            } else if (cars[i].direction == 270) {
                cars[i].y--;
            }

            // Check if the car has reached the end of the road
            if (cars[i].x > 100 || cars[i].y > 100 || cars[i].x < 0 || cars[i].y < 0) {
                // Remove the car from the simulation
                num_cars--;
                cars[i] = cars[num_cars];
            }
        }

        // Wait for a random amount of time
        int wait_time = rand_range(0, MAX_WAIT);
        for (int i = 0; i < wait_time; i++) {
            printf(".");
            fflush(stdout);
            sleep(1);
        }

        // Check if all cars have reached the end of the road
        if (num_cars == 0) {
            break;
        }
    }
}

int main() {
    // Initialize the random number generator
    srand(time(NULL));

    // Create an array of cars
    Car cars[NUM_CARS];

    // Simulate the traffic flow
    simulate_traffic(cars, NUM_CARS);

    return 0;
}

