        if(graph[i].color == 0) {
            for(j = 0; j < size; j++) {
                if(graph[i].edges[j] == 1 && graph[j].color == 0) {
                    graph[i].color = 1;
                    graph[j].color = 1;
                }
            }
        }
    }
}

