#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define TABLE_SIZE 10000

typedef struct node {
    int key;
    struct node *next;
} Node;

Node* create_node(int key) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    new_node->key = key;
    new_node->next = NULL;
    return new_node;
}

int custom_hash(const char *str, int len) {
    int hash = 0, i;

    for (i = 0; i < len; ++i) {
        hash = ((hash << 5) ^ hash) + str[i];
    }

    hash = hash % TABLE_SIZE;
    return hash;
}

void insert(int key, Node **hash_table) {
    int index = custom_hash((const char*)(&key), sizeof(key));
    Node *new_node = create_node(key);

    if (*hash_table == NULL) {
        *hash_table = new_node;
    } else {
        Node *current = *hash_table;
        while (current != NULL && current->key < key) {
            current = current->next;
        }
        new_node->next = current;
        *hash_table = new_node;
    }
}

bool search(int key, Node **hash_table) {
    int index = custom_hash((const char*)(&key), sizeof(key));
    Node *current = *hash_table;

    while (current != NULL) {
        if (current->key == key) {
            return true;
        }
        current = current->next;
    }
    return false;
}

int main() {
    Node *hash_table[TABLE_SIZE] = {NULL};

    int i, data[] = {1, 5, 10, 15, 20, 25};

    for (i = 0; i < sizeof(data) / sizeof(data[0]); ++i) {
        insert(data[i], hash_table);
    }

    int search_key = 15;
    bool found = search(search_key, hash_table);

    if (found) {
        printf("Found %d in the hash table!\n", search_key);
    } else {
        printf("Could not find %d in the hash table.\n", search_key);
    }

    return 0;
}

