int addProduct(Product products[], char name[], int stock, float price, int *count) {
    for (int i = 0; i < *count; ++i) {
        if (strcmp(products[i].name, name) == 0) {
            products[i].stock += stock;
            return 1;
        }
    }

    if (*count == MAX_PRODUCTS) {
        printf("Inventory is full.\n");
        return 0;
    }

    strcpy(products[*count].name, name);
    products[*count].stock = stock;
    products[*count].price = price;
    (*count)++;

    return 1;
}

int removeProduct(Product products[], char name[], int *count) {
    for (int i = 0; i < *count; ++i) {
        if (strcmp(products[i].name, name) == 0) {
            for (int j = i; j < *count - 1; ++j) {
                strcpy(products[j].name, products[j + 1].name);
            }
            (*count)--;
            return 1;
        }
    }

    printf("Product not found.\n");
    return 0;
}

void displayProducts(Product products[], int count) {
    for (int i = 0; i < count; ++i) {
        printf("%s: %d units, $%.2f per unit\n", products[i].name, products[i].stock, products[i].price);
    }
}

int main() {
    Product products[MAX_PRODUCTS];
    int count = 0;

    initProducts(products, MAX_PRODUCTS);

    char name[50];
    int stock, choice;
