#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <math.h>

#define SIZE 50

int grid[SIZE][SIZE];
int num_filled;
double prob;

void init(void) {
    srand(time(NULL));
    for (int i = 0; i < SIZE; i++) {
        for (int j = 0; j < SIZE; j++) {
            grid[i][j] = 0;
        }
    }
    num_filled = 0;
}

int is_valid(int x, int y) {
    return x >= 0 && x < SIZE && y >= 0 && y < SIZE;
}

void percolate(int x, int y) {
    if (!is_valid(x, y))
        return;
    if (grid[x][y] == 1)
        return;
    grid[x][y] = 1;
    num_filled++;
    if (x > 0 && grid[x-1][y] == 0)
        percolate(x-1, y);
    if (x < SIZE-1 && grid[x+1][y] == 0)
        percolate(x+1, y);
    if (y > 0 && grid[x][y-1] == 0)
        percolate(x, y-1);
    if (y < SIZE-1 && grid[x][y+1] == 0)
        percolate(x, y+1);
}

int main(void) {
    init();
    printf("Enter the probability of a site being filled (0-1): ");
    scanf("%lf", &prob);
    for (int i = 0; i < SIZE; i++) {
        for (int j = 0; j < SIZE; j++) {
            if (rand() / (double) RAND_MAX <= prob)
                grid[i][j] = 1;
        }
    }
    printf("The grid has been initialized.\n");
    printf("Do you want to see the grid? (y/n): ");
    char choice;
    scanf(" %c", &choice);
    if (choice == 'y' || choice == 'Y') {
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                if (grid[i][j] == 1)
                    printf("* ");
                else
                    printf("  ");
            }
            printf("\n");
        }
    }
    return 0;
}

