#include <stdio.h>
#include <pcap.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <arpa/inet.h>
#include <netinet/in.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <netdb.h>

#define MAX_PACKET_SIZE 65535
#define SNAPLEN 65535

typedef struct {
    u_int32_t src_ip;
    u_int32_t dst_ip;
    u_int16_t src_port;
    u_int16_t dst_port;
    u_int8_t protocol;
    char *payload;
    int payload_len;
} PacketData;

void process_packet(u_char *args, const struct pcap_pkthdr *header, const u_char *packet) {
    PacketData *data = (PacketData *) args;
    const struct ip *ip = (const struct ip *) packet;
    const struct tcphdr *tcp = (const struct tcphdr *) (packet + sizeof(struct ip));
    const struct udphdr *udp = (const struct udphdr *) (packet + sizeof(struct ip));

    data->src_ip = ip->ip_src.s_addr;
    data->dst_ip = ip->ip_dst.s_addr;

    if (ip->ip_p == IPPROTO_TCP) {
        data->src_port = ntohs(tcp->th_sport);
        data->dst_port = ntohs(tcp->th_dport);
        data->protocol = "TCP";
    } else if (ip->ip_p == IPPROTO_UDP) {
        data->src_port = ntohs(udp->uh_sport);
        data->dst_port = ntohs(udp->uh_dport);
        data->protocol = "UDP";
    } else {
        data->src_port = 0;
        data->dst_port = 0;
        data->protocol = "UNKNOWN";
    }

    data->payload = (char *) malloc(header->caplen);
    data->payload_len = header->caplen;
    memcpy(data->payload, packet, header->caplen);
}

int main(int argc, char *argv[]) {
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle;
    char *dev = "eth0";
    int res = 0;

    if (argc > 1) {
        dev = argv[1];
    }

    handle = pcap_open_live(dev, SNAPLEN, 1, 1000, errbuf);
    if (handle == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", dev, errbuf);
        return 1;
    }

    pcap_loop(handle, -1, process_packet, NULL);

    pcap_close(handle);

    return 0;
}

