#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define SERVER "smtp.cybermail.net"
#define PORT 587
#define BUFFER_SIZE 1024

void send_command(int sock, const char *command) {
    printf(">> Sending: %s", command);
    send(sock, command, strlen(command), 0);
    char response[BUFFER_SIZE] = {0};
    recv(sock, response, sizeof(response) - 1, 0);
    printf("<< Response: %s", response);
}

int establish_connection(const char *server, int port) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);
    inet_pton(AF_INET, server, &server_addr.sin_addr);

    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Connection to SMTP server failed");
        exit(EXIT_FAILURE);
    }

    return sock;
}

void authenticate(int sock, const char *username, const char *password) {
    char buffer[BUFFER_SIZE];

    // EHLO command
    send_command(sock, "EHLO cyberpunk-cli\r\n");

    // AUTH LOGIN command
    send_command(sock, "AUTH LOGIN\r\n");

    // Send username
    sprintf(buffer, "%s\r\n", username);
    send_command(sock, buffer);

    // Send password
    sprintf(buffer, "%s\r\n", password);
    send_command(sock, buffer);
}

void send_email(int sock, const char *from, const char *to, const char *subject, const char *body) {
    char buffer[BUFFER_SIZE];

    // Mail from
    sprintf(buffer, "MAIL FROM:<%s>\r\n", from);
    send_command(sock, buffer);

    // RCPT TO
    sprintf(buffer, "RCPT TO:<%s>\r\n", to);
    send_command(sock, buffer);

    // DATA
    send_command(sock, "DATA\r\n");

    // Email content
    sprintf(buffer, "Subject: %s\r\n", subject);
    send(sock, buffer, strlen(buffer), 0);
    sprintf(buffer, "From: %s\r\n", from);
    send(sock, buffer, strlen(buffer), 0);
    sprintf(buffer, "To: %s\r\n", to);
    send(sock, buffer, strlen(buffer), 0);
    send(sock, "\r\n", 2, 0);  // End of headers

    // Actual message body
    send(sock, body, strlen(body), 0);
    send(sock, "\r\n.\r\n", 5, 0);  // End of message
    send_command(sock, "QUIT\r\n");
}

int main() {
    printf("Initializing CyberSMTP Client...\n");

    const char *username = getenv("SMTP_USER");
    const char *password = getenv("SMTP_PASS");

    if (username == NULL || password == NULL) {
        fprintf(stderr, "Email credentials (SMTP_USER, SMTP_PASS) not set.\n");
        return EXIT_FAILURE;
    }

    int sock = establish_connection(SERVER, PORT);

    // Authentication sequence
    authenticate(sock, username, password);

    // Prepare email
    const char *from = "sender@cybermail.net";
    const char *to = "recipient@cybermail.net";
    const char *subject = "The Rise of the Cyberpunk SMTP Client";
    const char *body = "Greetings,\n\nThis message is sent from the depths of the neon-lit cyberspace.\n\nStay frosty, \nThe CyberTeam";

    // Sending email
    send_email(sock, from, to, subject, body);

    close(sock);
    printf("Email sent successfully! Your message glides in the electric breeze...\n");
    return EXIT_SUCCESS;
}

