#include <stdio.h>
#include <stdlib.h>
#include <math.h>

int main() {
  printf("Surprise! Let's do some audio processing.\n\n");

  // Set up sample rate and duration of audio clip
  int sampleRate = 44100; // samples per second
  int duration = 5; // seconds
  int numSamples = sampleRate * duration; // total number of samples

  // Allocate memory for audio data
  float* audioData = malloc(numSamples * sizeof(float));

  // Generate a simple sine wave
  for (int i = 0; i < numSamples; i++) {
    float t = (float) i / sampleRate; // time in seconds
    float freq = 440; // frequency of A4 note
    float amplitude = 0.5; // maximum amplitude of sine wave
    float value = amplitude * sin(2 * M_PI * freq * t); // sine value at current time
    audioData[i] = value;
  }

  // Write audio data to file
  FILE *file;
  file = fopen("audio.wav", "wb");

  // Write WAV file header
  int numChannels = 1; // mono audio
  int bitsPerSample = 16; // 16-bit audio
  int byteRate = sampleRate * numChannels * (bitsPerSample / 8);
  int blockAlign = numChannels * (bitsPerSample / 8);
  int dataSize = numSamples * numChannels * (bitsPerSample / 8);
  int fileSize = dataSize + 36; // add 36 bytes for WAV file header
  fwrite("RIFF", 4, 1, file);
  fwrite(&fileSize, 4, 1, file);
  fwrite("WAVE", 4, 1, file);
  fwrite("fmt ", 4, 1, file);
  fwrite("\x10\0\0\0", 4, 1, file); // PCM format
  fwrite(&numChannels, 2, 1, file);
  fwrite(&sampleRate, 4, 1, file);
  fwrite(&byteRate, 4, 1, file);
  fwrite(&blockAlign, 2, 1, file); 
  fwrite(&bitsPerSample, 2, 1, file); 
  fwrite("data", 4, 1, file);
  fwrite(&dataSize, 4, 1, file);

  // Write audio data
  for (int i = 0; i < numSamples; i++) {
    short value = (short) (audioData[i] * 32767); // convert from float to 16-bit int
    fwrite(&value, 2, 1, file); // write to file
  }

  // Clean up
  fclose(file);
  free(audioData);

  printf("Done! Check out the audio.wav file to hear the surprise.\n");

  return 0;
}

//LLAMA2-13B DATASET v1.0 Category: Encryption ; Style: thoughtful
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define KEY_SIZE 16
#define BLOCK_SIZE 16
#define MESSAGE_SIZE 32

typedef struct {
    char key[KEY_SIZE];
    char message[MESSAGE_SIZE];
} message_t;

void encrypt(message_t *message);
void decrypt(message_t *message);

int main() {
    message_t message;
    char encrypted_message[MESSAGE_SIZE];

    // Generate a random key
    srand(time(NULL));
    for (int i = 0; i < KEY_SIZE; i++) {
        message.key[i] = (char)rand();
    }

    // Set the message
    strcpy(message.message, "Hello, World!");

    // Encrypt the message
    encrypt(&message);

    // Print the encrypted message
    printf("Encrypted message: %s\n", encrypted_message);

    // Decrypt the message
    decrypt(&message);

    // Print the decrypted message
    printf("Decrypted message: %s\n", message.message);

    return 0;
}

void encrypt(message_t *message) {
    // Initialize the encryption buffer
    char encryption_buffer[MESSAGE_SIZE];

    // Loop through each character of the message
    for (int i = 0; i < MESSAGE_SIZE; i++) {
        // XOR the character with the corresponding key value
        encryption_buffer[i] = message->message[i] ^ message->key[i];
    }

    // Replace each character with its corresponding ASCII code
    for (int i = 0; i < MESSAGE_SIZE; i++) {
        encryption_buffer[i] = (char)((int)encryption_buffer[i] + (int)message->key[i]);
    }

    // Assign the encrypted message to the output variable
    strcpy(message->message, encryption_buffer);
}

void decrypt(message_t *message) {
    // Initialize the decryption buffer
    char decryption_buffer[MESSAGE_SIZE];

    // Loop through each character of the encrypted message
    for (int i = 0; i < MESSAGE_SIZE; i++) {
        // XOR the character with the corresponding key value
        decryption_buffer[i] = message->message[i] ^ message->key[i];
    }

    // Replace each character with its corresponding ASCII code
    for (int i = 0; i < MESSAGE_SIZE; i++) {
        decryption_buffer[i] = (char)((int)decryption_buffer[i] - (int)message->key[i]);
    }

    // Assign the decrypted message to the output variable
    strcpy(message->message, decryption_buffer);
}

//Falcon-180B DATASET v1.0 Category: Game ; Style: decentralized
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_PLAYERS 10
#define MAX_ROUNDS 10

typedef struct Player {
    char name[20];
    int score;
    int wins;
    int losses;
    int ties;
} Player;

void init_player(Player* player) {
    strcpy(player->name, "");
    player->score = 0;
    player->wins = 0;
    player->losses = 0;
    player->ties = 0;
}

void print_player(Player player) {
    printf("Name: %s\n", player.name);
    printf("Score: %d\n", player.score);
    printf("Wins: %d\n", player.wins);
    printf("Losses: %d\n", player.losses);
    printf("Ties: %d\n", player.ties);
}

int main() {
    int num_players;
    printf("Enter number of players: ");
    scanf("%d", &num_players);

    Player players[MAX_PLAYERS];
    for (int i = 0; i < num_players; i++) {
        printf("Enter player %d's name: ", i + 1);
        scanf("%s", players[i].name);
        init_player(&players[i]);
    }

    int num_rounds;
    printf("Enter number of rounds: ");
    scanf("%d", &num_rounds);

    for (int i = 0; i < num_rounds; i++) {
        for (int j = 0; j < num_players; j++) {
            printf("Player %d's score for round %d: ", j + 1, i + 1);
            scanf("%d", &players[j].score);
        }

        for (int j = 0; j < num_players; j++) {
            players[j].wins = 0;
            players[j].losses = 0;
            players[j].ties = 0;
        }

        for (int j = 0; j < num_players - 1; j++) {
            for (int k = j + 1; k < num_players; k++) {
                if (players[j].score > players[k].score) {
                    players[j].wins++;
                    players[k].losses++;
                } else if (players[j].score < players[k].score) {
                    players[j].losses++;
                    players[k].wins++;
                } else {
                    players[j].ties++;
                    players[k].ties++;
                }
            }
        }
    }

    printf("\nFinal scores:\n");
    for (int i = 0; i < num_players; i++) {
        print_player(players[i]);
    }

    return 0;
}

