#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_CLIENT_LENGTH 1024
#define MAX_SERVER_LENGTH 1024

int main(int argc, char *argv[]) {
  // Create a socket
  int sock = socket(AF_INET, SOCK_STREAM, 0);
  if (sock < 0) {
    perror("socket() failed");
    exit(1);
  }

  // Set address and port number
  struct sockaddr_in server_addr = {
    .sin_family = AF_INET,
    .sin_port = htons(8080),
    .sin_addr.s_addr = INADDR_ANY
  };

  // Bind the socket to the address and port
  if (bind(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
    perror("bind() failed");
    exit(1);
  }

  // Listen for incoming connections
  if (listen(sock, 3) < 0) {
    perror("listen() failed");
    exit(1);
  }

  printf("Server listening on port %d...\n", server_addr.sin_port);

  // Accept an incoming connection
  int client_sock = accept(sock, NULL, NULL);
  if (client_sock < 0) {
    perror("accept() failed");
    exit(1);
  }

  // Greet the client
  char greeting[MAX_CLIENT_LENGTH];
  printf("Welcome, client! Please enter your name: ");
  fgets(greeting, MAX_CLIENT_LENGTH, stdin);
  printf("Hello, %s! How are you today?\n", greeting);

  // Send and receive data
  char message[MAX_CLIENT_LENGTH];
  printf("Server: How are you today? ");
  fgets(message, MAX_CLIENT_LENGTH, stdin);
  send(client_sock, message, strlen(message), 0);

  // Receive the client's response
  recv(client_sock, message, MAX_CLIENT_LENGTH, 0);
  printf("Server: %s\n", message);

  // Close the socket
  close(client_sock);

  return 0;
}

