#include <errno.h>
#include <stdbool.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <ctype.h>

#define MAX_HEX_COLOR_LEN 7
#define MAX_RGB_COLOR_LEN 15

typedef struct {
    char *hex;
    int r, g, b;
} color_t;

bool is_hex_color(const char *str) {
    if (strlen(str) != MAX_HEX_COLOR_LEN) {
        return false;
    }

    for (int i = 0; i < MAX_HEX_COLOR_LEN; i++) {
        char c = str[i];
        if (!isxdigit(c)) {
            return false;
        }
    }

    return true;
}

bool is_rgb_color(const char *str) {
    if (strlen(str) != MAX_RGB_COLOR_LEN) {
        return false;
    }

    if (str[0] != 'r' || str[1] != 'g' || str[2] != 'b' || str[3] != '(' || str[MAX_RGB_COLOR_LEN - 1] != ')') {
        return false;
    }

    for (int i = 4; i < MAX_RGB_COLOR_LEN - 1; i++) {
        char c = str[i];
        if (!isdigit(c)) {
            return false;
        }
    }

    return true;
}

color_t parse_hex_color(const char *str) {
    color_t color = { .hex = strdup(str) };
    sscanf(str, "%02x%02x%02x", &color.r, &color.g, &color.b);
    return color;
}

color_t parse_rgb_color(const char *str) {
    color_t color = { .hex = NULL };
    sscanf(str + 4, "%d,%d,%d", &color.r, &color.g, &color.b);
    return color;
}

void print_hex_color(const color_t *color) {
    printf("#%02x%02x%02x\n", color->r, color->g, color->b);
}

void print_rgb_color(const color_t *color) {
    printf("rgb(%d,%d,%d)\n", color->r, color->g, color->b);
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <color>\n", argv[0]);
        return 1;
    }

    const char *color_str = argv[1];

    color_t color;
    if (is_hex_color(color_str)) {
        color = parse_hex_color(color_str);
    } else if (is_rgb_color(color_str)) {
        color = parse_rgb_color(color_str);
    } else {
        fprintf(stderr, "Invalid color: %s\n", color_str);
        return 1;
    }

    print_hex_color(&color);
    print_rgb_color(&color);

    free(color.hex);

    return 0;
}

//GEMINI-pro DATASET v1.0 Category: Pong Game with AI Opponent ; Style: real-life
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define WIDTH 60
#define HEIGHT 20
#define BALL_SYMBOL 'O'
#define PADDLE_SYMBOL '|'
#define WALL_SYMBOL '#'

typedef struct {
  int x;
  int y;
} point_t;

typedef struct {
  point_t pos;
  point_t vel;
} ball_t;

typedef struct {
  point_t pos;
  int score;
} player_t;

void draw_screen(const ball_t *ball, const player_t *player1, const player_t *player2) {
  for (int i = 0; i < HEIGHT; i++) {
    for (int j = 0; j < WIDTH; j++) {
      if (i == 0 || i == HEIGHT - 1) {
        printf(WALL_SYMBOL);
      } else if (j == 0 || j == WIDTH - 1) {
        if (i == player1->pos.y) {
          printf(PADDLE_SYMBOL);
        } else if (i == player2->pos.y) {
          printf(PADDLE_SYMBOL);
        } else {
          printf(" ");
        }
      } else if (i == ball->pos.y && j == ball->pos.x) {
        printf(BALL_SYMBOL);
      } else {
        printf(" ");
      }
    }
    printf("\n");
  }
}

void move_ball(ball_t *ball, const player_t *player1, const player_t *player2) {
  ball->pos.x += ball->vel.x;
  ball->pos.y += ball->vel.y;

  // Check if the ball hit the left or right wall
  if (ball->pos.x == 0 || ball->pos.x == WIDTH - 1) {
    ball->vel.x *= -1;
  }

  // Check if the ball hit the top or bottom wall
  if (ball->pos.y == 0 || ball->pos.y == HEIGHT - 1) {
    ball->vel.y *= -1;
  }

  // Check if the ball hit the left paddle
  if (ball->pos.x == player1->pos.x && ball->pos.y >= player1->pos.y - 2 && ball->pos.y <= player1->pos.y + 2) {
    ball->vel.x *= -1;
  }

  // Check if the ball hit the right paddle
  if (ball->pos.x == player2->pos.x && ball->pos.y >= player2->pos.y - 2 && ball->pos.y <= player2->pos.y + 2) {
    ball->vel.x *= -1;
  }
}

void move_player(player_t *player, int key) {
  if (key == 'w' && player->pos.y > 1) {
    player->pos.y--;
  } else if (key == 's' && player->pos.y < HEIGHT - 2) {
    player->pos.y++;
  }
}

int main() {
  srand(time(NULL));

  // Initialize the ball
  ball_t ball;
  ball.pos.x = WIDTH / 2;
  ball.pos.y = HEIGHT / 2;
  ball.vel.x = rand() % 2 == 0 ? -1 : 1;
  ball.vel.y = rand() % 2 == 0 ? -1 : 1;

  // Initialize the players
  player_t player1;
  player1.pos.x = 0;
  player1.pos.y = HEIGHT / 2;
  player1.score = 0;

  player_t player2;
  player2.pos.x = WIDTH - 1;
  player2.pos.y = HEIGHT / 2;
  player2.score = 0;

  // Main game loop
  while (1) {
    // Draw the screen
    draw_screen(&ball, &player1, &player2);

    // Get the player input
    char key1 = getchar();
    char key2 = getchar();

    // Move the ball
    move_ball(&ball, &player1, &player2);

    // Move the players
    move_player(&player1, key1);
    move_player(&player2, key2);

    // Check if a player has won
    if (ball.pos.x == 0) {
      player2.score++;
      printf("Player 2 wins!\n");
      break;
    } else if (ball.pos.x == WIDTH - 1) {
      player1.score++;
      printf("Player 1 wins!\n");
      break;
    }
  }

  return 0;
}

