#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>

#define BINGO_SIZE 5
#define MAX_NUM 75
#define MIN_NUM 1

void printCard(int card[BINGO_SIZE][BINGO_SIZE]);
void generateCard(int card[BINGO_SIZE][BINGO_SIZE]);
bool checkWin(int card[BINGO_SIZE][BINGO_SIZE]);

int main() {
    int bingoCard[BINGO_SIZE][BINGO_SIZE] = {0};
    int numberDrawn;
    bool won = false;

    // Seed the random number generator
    srand(time(NULL));

    // Generate the bingo card
    generateCard(bingoCard);
    printf("Welcome to Bingo! Your card is:\n");
    printCard(bingoCard);

    while (!won) {
        printf("\nDrawing a number... ");
        numberDrawn = rand() % (MAX_NUM - MIN_NUM + 1) + MIN_NUM;
        printf("The number drawn is: %d\n", numberDrawn);

        // Mark the number on card
        for (int i = 0; i < BINGO_SIZE; i++) {
            for (int j = 0; j < BINGO_SIZE; j++) {
                if (bingoCard[i][j] == numberDrawn) {
                    bingoCard[i][j] = -1;  // Mark it as hit
                }
            }
        }

        printCard(bingoCard);  // Print the current state of the card
        won = checkWin(bingoCard); // Check if there's a winner
    }

    printf("Congratulations! You've got BINGO!\n");
    return 0;
}

void generateCard(int card[BINGO_SIZE][BINGO_SIZE]) {
    int columnRanges[5][2] = { {1, 15}, {16, 30}, {31, 45}, {46, 60}, {61, 75} };
    for (int col = 0; col < BINGO_SIZE; col++) {
        int numsInCol[BINGO_SIZE] = {0};

        for (int i = 0; i < BINGO_SIZE; i++) {
            int num;
            bool unique;
            do {
                unique = true;
                num = rand() % (columnRanges[col][1] - columnRanges[col][0] + 1) + columnRanges[col][0];
                for (int j = 0; j < i; j++) {
                    if (numsInCol[j] == num) {
                        unique = false;
                        break;
                    }
                }
            } while (!unique);

            numsInCol[i] = num;
            card[i][col] = num;
        }
    }
    card[2][2] = -1; // Free space in the center
}

void printCard(int card[BINGO_SIZE][BINGO_SIZE]) {
    printf("+-----+-----+-----+-----+-----+\n");
    printf("|  B  |  I  |  N  |  G  |  O  |\n");
    printf("+-----+-----+-----+-----+-----+\n");

    for (int i = 0; i < BINGO_SIZE; i++) {
        for (int j = 0; j < BINGO_SIZE; j++) {
            if (card[i][j] == -1) {
                printf("| *   ");
            } else {
                printf("| %2d  ", card[i][j]);
            }
        }
        printf("|\n");
        printf("+-----+-----+-----+-----+-----+\n");
    }
}

bool checkWin(int card[BINGO_SIZE][BINGO_SIZE]) {
    // Check rows and columns
    for (int i = 0; i < BINGO_SIZE; i++) {
        if ((card[i][0] == -1 && card[i][1] == -1 && card[i][2] == -1 && 
             card[i][3] == -1 && card[i][4] == -1) || 
            (card[0][i] == -1 && card[1][i] == -1 && card[2][i] == -1 && 
             card[3][i] == -1 && card[4][i] == -1)) {
            return true;
        }
    }

    // Check diagonals
    if ((card[0][0] == -1 && card[1][1] == -1 && card[2][2] == -1 && 
         card[3][3] == -1 && card[4][4] == -1) ||
        (card[0][4] == -1 && card[1][3] == -1 && card[2][2] == -1 && 
         card[3][1] == -1 && card[4][0] == -1)) {
