#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the game board
#define BOARD_SIZE 10
#define BOARD_SYMBOL '*'
#define PLAYER_SYMBOL 'X'
#define COMPUTER_SYMBOL 'O'

// Define the game state
typedef enum {
    STATE_WIN,
    STATE_LOSE,
    STATE_TIE,
    STATE_CONTINUE
} GameState;

// Define the game structure
typedef struct {
    GameState state;
    int board[BOARD_SIZE][BOARD_SIZE];
    int current_player;
} Game;

// Initialize the game
void init_game(Game *game) {
    game->state = STATE_CONTINUE;
    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            game->board[i][j] = BOARD_SYMBOL;
        }
    }
    game->current_player = 1;
}

// Print the game board
void print_board(Game *game) {
    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (game->board[i][j] == PLAYER_SYMBOL) {
                printf("X");
            } else if (game->board[i][j] == COMPUTER_SYMBOL) {
                printf("O");
            } else {
                printf(" ");
            }
        }
        printf("\n");
    }
}

// Check if the game is over
GameState check_game_over(Game *game) {
    // Check rows
    for (int i = 0; i < BOARD_SIZE; i++) {
        int count = 0;
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (game->board[i][j] == PLAYER_SYMBOL) {
                count++;
            }
        }
        if (count == BOARD_SIZE) {
            return STATE_WIN;
        }
    }

    // Check columns
    for (int j = 0; j < BOARD_SIZE; j++) {
        int count = 0;
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (game->board[i][j] == PLAYER_SYMBOL) {
                count++;
            }
        }
        if (count == BOARD_SIZE) {
            return STATE_WIN;
        }
    }

    // Check diagonals
    int count = 0;
    for (int i = 0; i < BOARD_SIZE; i++) {
        if (game->board[i][i] == PLAYER_SYMBOL) {
            count++;
        }
    }
    if (count == BOARD_SIZE) {
        return STATE_WIN;
    }

    count = 0;
    for (int i = 0; i < BOARD_SIZE; i++) {
        if (game->board[i][BOARD_SIZE - 1 - i] == PLAYER_SYMBOL) {
            count++;
        }
    }
    if (count == BOARD_SIZE) {
        return STATE_WIN;
    }

    // Check if the game is tied
    int empty_spaces = 0;
    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (game->board[i][j] == BOARD_SYMBOL) {
                empty_spaces++;
            }
        }
    }
    if (empty_spaces == 0) {
        return STATE_TIE;
    }

    return STATE_CONTINUE;
}

// Make a move
void make_move(Game *game, int x, int y) {
    game->board[x][y] = PLAYER_SYMBOL;
    game->current_player = 0;
}

// Make a computer move
void make_computer_move(Game *game) {
    srand(time(NULL));
    int x = rand() % BOARD_SIZE;
    int y = rand() % BOARD_SIZE;
    make_move(game, x, y);
}

// Play a round
void play_round(Game *game) {
    print_board(game);
    if (game->current_player == 1) {
        printf("Your turn. Enter the coordinates: ");
        int x, y;
        scanf("%d %d", &x, &y);
        make_move(game, x, y);
    } else {
        make_computer_move(game);
    }
}

// Play the game
void play_game(Game *game) {
    while (game->state != STATE_WIN && game->state != STATE_TIE) {
        play_round(game);
        game->state = check_game_over(game);
    }
}

int main() {
    Game game;
    init_game(&game);
    play_game(&game);
    if (game.state == STATE_WIN) {
        printf("Congratulations! You won!\n");
    } else if (game.state == STATE_TIE) {
        printf("It's a tie!\n");
    }
    return 0;
}

