  if(l1 == NULL && l2 == NULL && !carry)
    return NULL;
  ListNode* node = new ListNode(carry);
  if(l1){
    node->val += l1->val;
    l1 = l1->next;
  }
  if(l2){
    node->val += l2->val;
    l2 = l2->next;
  }
  carry = node->val / 10;
  node->val = node->val % 10;
  node->next = addTwoNumbersRecursive(l1, l2, carry);
  return node;
}

