            break;
        }
        if (password[i] == '^') {
            containsSpecialChar = 1;
            break;
        }
        if (password[i] == '&') {
            containsSpecialChar = 1;
            break;
        }
        if (password[i] == '*') {
            containsSpecialChar = 1;
            break;
        }
        if (password[i] == '(') {
            containsSpecialChar = 1;
            break;
        }
        if (password[i] == ')') {
            containsSpecialChar = 1;
            break;
        }
    }

    // Check if password contains digits
    int containsDigit = 0;
    for (int i = 0; i < strlen(password); i++) {
        if (password[i] >= '0' && password[i] <= '9') {
            containsDigit = 1;
            break;
        }
    }

    // Check if password contains upper and lower case characters
    int containsUpperCase = 0;
    int containsLowerCase = 0;
    for (int i = 0; i < strlen(password); i++) {
        if (password[i] >= 'A' && password[i] <= 'Z') {
            containsUpperCase = 1;
            break;
        }
        if (password[i] >= 'a' && password[i] <= 'z') {
            containsLowerCase = 1;
            break;
        }
    }

    // Check if password contains both upper and lower case characters
    if (containsUpperCase && containsLowerCase) {
        return 1;
    }

    // Return strength based on checks
    if (containsAllowedChar && containsSpecialChar && containsDigit && containsUpperCase && containsLowerCase) {
        return 3;
    } else if (containsAllowedChar && containsSpecialChar && containsDigit && containsUpperCase) {
        return 2;
    } else if (containsAllowedChar && containsSpecialChar && containsDigit && containsLowerCase) {
        return 1;
    } else if (containsAllowedChar && containsSpecialChar && containsDigit) {
        return 0;
    } else if (containsAllowedChar && containsSpecialChar) {
        return -1;
    } else if (containsAllowedChar) {
        return -2;
    } else if (containsSpecialChar) {
        return -3;
    } else if (containsDigit) {
        return -4;
    } else if (containsUpperCase) {
        return -5;
    } else if (containsLowerCase) {
