#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

// Define the size of the grid
#define GRID_WIDTH 10
#define GRID_HEIGHT 10

// Define the different types of tiles
#define TILE_EMPTY 0
#define TILE_WALL 1
#define TILE_START 2
#define TILE_END 3

// Define the different directions
#define DIR_UP 0
#define DIR_DOWN 1
#define DIR_LEFT 2
#define DIR_RIGHT 3

// Create a grid of tiles
int grid[GRID_WIDTH][GRID_HEIGHT];

// Create a queue of tiles to be visited
typedef struct queue_node {
  int x;
  int y;
  int dir;
  struct queue_node *next;
} queue_node;

queue_node *queue_head = NULL;
queue_node *queue_tail = NULL;

// Add a tile to the queue
void queue_push(int x, int y, int dir) {
  queue_node *new_node = malloc(sizeof(queue_node));
  new_node->x = x;
  new_node->y = y;
  new_node->dir = dir;
  new_node->next = NULL;

  if (queue_head == NULL) {
    queue_head = new_node;
    queue_tail = new_node;
  } else {
    queue_tail->next = new_node;
    queue_tail = new_node;
  }
}

// Remove a tile from the queue
queue_node *queue_pop() {
  if (queue_head == NULL) {
    return NULL;
  } else {
    queue_node *old_head = queue_head;
    queue_head = queue_head->next;
    if (queue_head == NULL) {
      queue_tail = NULL;
    }
    return old_head;
  }
}

// Check if a tile is valid
bool is_valid_tile(int x, int y) {
  return x >= 0 && x < GRID_WIDTH && y >= 0 && y < GRID_HEIGHT && grid[x][y] != TILE_WALL;
}

// Get the neighbors of a tile
int get_neighbors(int x, int y, int dir) {
  int neighbors[4];
  int num_neighbors = 0;

  if (is_valid_tile(x, y + 1) && dir != DIR_DOWN) {
    neighbors[num_neighbors++] = DIR_UP;
  }
  if (is_valid_tile(x, y - 1) && dir != DIR_UP) {
    neighbors[num_neighbors++] = DIR_DOWN;
  }
  if (is_valid_tile(x - 1, y) && dir != DIR_RIGHT) {
    neighbors[num_neighbors++] = DIR_LEFT;
  }
  if (is_valid_tile(x + 1, y) && dir != DIR_LEFT) {
    neighbors[num_neighbors++] = DIR_RIGHT;
  }

  return neighbors;
}

// Find the shortest path from the start tile to the end tile
int find_path() {
  // Initialize the queue
  queue_push(0, 0, DIR_UP);

  // While the queue is not empty
  while (queue_head != NULL) {
    // Get the current tile
    queue_node *current_tile = queue_pop();

    // Check if the current tile is the end tile
    if (grid[current_tile->x][current_tile->y] == TILE_END) {
      return current_tile->dir;
    }

    // Get the neighbors of the current tile
    int neighbors[4];
    int num_neighbors = get_neighbors(current_tile->x, current_tile->y, current_tile->dir);

    // Add the neighbors to the queue
    for (int i = 0; i < num_neighbors; i++) {
      queue_push(current_tile->x, current_tile->y, neighbors[i]);
    }
  }

  // No path found
  return -1;
}

// Print the grid
void print_grid() {
  for (int y = 0; y < GRID_HEIGHT; y++) {
    for (int x = 0; x < GRID_WIDTH; x++) {
      switch (grid[x][y]) {
