//GPT-4o-mini DATASET v1.0 Category: Sentiment analysis tool ; Style: puzzling
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_TEXT_LENGTH 1024
#define POSITIVE_WORDS 5
#define NEGATIVE_WORDS 5

const char *positiveWords[POSITIVE_WORDS] = {"happy", "joy", "love", "excellent", "good"};
const char *negativeWords[NEGATIVE_WORDS] = {"sad", "hate", "bad", "terrible", "poor"};

int isPositiveWord(const char *word) {
    for (int i = 0; i < POSITIVE_WORDS; i++) {
        if (strcmp(word, positiveWords[i]) == 0) {
            return 1; // Positive word found
        }
    }
    return 0; // Not a positive word
}

int isNegativeWord(const char *word) {
    for (int i = 0; i < NEGATIVE_WORDS; i++) {
        if (strcmp(word, negativeWords[i]) == 0) {
            return 1; // Negative word found
        }
    }
    return 0; // Not a negative word
}

void analyzeSentiment(const char *text) {
    char *token;
    int positiveCount = 0;
    int negativeCount = 0;

    token = strtok(text, " ");
    while (token != NULL) {
        if (isPositiveWord(token)) {
            positiveCount++;
        } else if (isNegativeWord(token)) {
            negativeCount++;
        }
        token = strtok(NULL, " ");
    }

    if (positiveCount > negativeCount) {
        printf("Sentiment Analysis Result: Positive (Positive: %d, Negative: %d)\n", positiveCount, negativeCount);
    } else if (negativeCount > positiveCount) {
        printf("Sentiment Analysis Result: Negative (Positive: %d, Negative: %d)\n", positiveCount, negativeCount);
    } else {
        printf("Sentiment Analysis Result: Neutral (Positive: %d, Negative: %d)\n", positiveCount, negativeCount);
    }
}

int main() {
    char inputText[MAX_TEXT_LENGTH];

    printf("==== Welcome to the Sentiment Analysis Tool ====\n");
    printf("Enter the text for sentiment analysis (max %d characters):\n", MAX_TEXT_LENGTH - 1);

    if (fgets(inputText, sizeof(inputText), stdin) != NULL) {
        // Remove the newline character if present
        inputText[strcspn(inputText, "\n")] = 0; 

        analyzeSentiment(inputText);
    } else {
        printf("Error reading input!\n");
    }

    return 0;
}

