// Percolation Simulator in Curious Style
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define N 100
#define M 100
#define PERCENTAGE 0.5

int main() {
  srand(time(NULL));

  int grid[N][M];
  int open_sites = 0;

  for (int i = 0; i < N; i++) {
    for (int j = 0; j < M; j++) {
      grid[i][j] = rand() % 2;
      if (grid[i][j] == 1) open_sites++;
    }
  }

  printf("Initial grid: \n");
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < M; j++) {
      printf("%d ", grid[i][j]);
    }
    printf("\n");
  }

  printf("Open sites: %d\n", open_sites);

  int iterations = 0;
  while (open_sites > 0) {
    int x = rand() % N;
    int y = rand() % M;
    if (grid[x][y] == 1) {
      grid[x][y] = 0;
      open_sites--;
    }
    iterations++;
  }

  printf("Final grid: \n");
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < M; j++) {
      printf("%d ", grid[i][j]);
    }
    printf("\n");
  }

  printf("Number of iterations: %d\n", iterations);

  return 0;
}

