//GPT-4o-mini DATASET v1.0 Category: Word Frequency Counter ; Style: portable
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_WORD_LENGTH 100
#define MAX_WORDS 1000

typedef struct {
    char *word;
    int count;
} WordCount;

WordCount wordList[MAX_WORDS];
int wordCount = 0;

void addWord(const char *word) {
    for (int i = 0; i < wordCount; i++) {
        if (strcmp(wordList[i].word, word) == 0) {
            wordList[i].count++;
            return;
        }
    }

    if (wordCount < MAX_WORDS) {
        wordList[wordCount].word = malloc(strlen(word) + 1);
        if (wordList[wordCount].word == NULL) {
            fprintf(stderr, "Memory allocation failed.\n");
            exit(EXIT_FAILURE);
        }
        strcpy(wordList[wordCount].word, word);
        wordList[wordCount].count = 1;
        wordCount++;
    } else {
        fprintf(stderr, "Word limit exceeded!\n");
    }
}

void processFile(FILE *file) {
    char word[MAX_WORD_LENGTH];
    int index = 0;
    char ch;

    while ((ch = fgetc(file)) != EOF) {
        if (isalpha(ch) || ch == '\'') {
            // Collecting a word
            word[index++] = ch;
        } else if (index > 0) {
            // End of a word
            word[index] = '\0';
            addWord(word);
            index = 0; // Resetting for the next word
        }
    }

    // Check if last word is captured
    if (index > 0) {
        word[index] = '\0';
        addWord(word);
    }
}

void sortWords() {
    for (int i = 0; i < wordCount - 1; i++) {
        for (int j = i + 1; j < wordCount; j++) {
            if (wordList[i].count < wordList[j].count) {
                // Swap words
                WordCount temp = wordList[i];
                wordList[i] = wordList[j];
                wordList[j] = temp;
            }
        }
    }
}

void printWordCounts() {
    printf("Word Frequency Count:\n");
    printf("----------------------\n");
    for (int i = 0; i < wordCount; i++) {
        printf("%s : %d\n", wordList[i].word, wordList[i].count);
    }
}

void freeMemory() {
    for (int i = 0; i < wordCount; i++) {
        free(wordList[i].word);
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    FILE *file = fopen(argv[1], "r");
    if (file == NULL) {
        fprintf(stderr, "Could not open file: %s\n", argv[1]);
        return EXIT_FAILURE;
    }

    processFile(file);
    fclose(file);

    sortWords();
    printWordCounts();
    freeMemory();

    return EXIT_SUCCESS;
}

//FormAI DATASET v1.0 Category: Word Frequency Counter ; Style: scientific
#include<stdio.h>
#include<stdlib.h>
#include<ctype.h>
#include<string.h>

// A structure to store word and its count in a file
typedef struct WordFreq {
    char* word;
    int count;
} WordFreq;

// A function to compare two WordFreq structures for sorting 
int compare(const void* a, const void* b) {
    WordFreq* wf1 = (WordFreq*) a;
    WordFreq* wf2 = (WordFreq*) b;
    return wf2->count - wf1->count;
}

// A function to add a word to WordFreq structure array
void addWord(WordFreq* wf, char* word) {
    int i;
    // Convert the word to lowercase
    for(i = 0; word[i]; i++) {
        word[i] = tolower(word[i]);
    }
    // Check if the word already exists in the array
    for(i = 0; wf[i].word; i++) {
        if(strcmp(wf[i].word, word) == 0) {          
            wf[i].count++;
            free(word);
            return;
        }
    }
    // Add the new word to the array if it doesn't exist
    wf[i].word = word;
    wf[i].count = 1;
    wf[i+1].word = NULL;
}

// A function to read a file and count the number of occurrences of each word
WordFreq* count(FILE* fp) {
    char c, *word = NULL;
    int i = 0, size = 0;
    WordFreq* wf = (WordFreq*) calloc(1, sizeof(WordFreq));
    while((c = fgetc(fp)) != EOF) {
        if(isalpha(c)) {
            size++;
            word = (char*) realloc(word, size*sizeof(char));
            word[i++] = c;
        }
        else if(word) {
            word = (char*) realloc(word, (size+1)*sizeof(char));
            word[size++] = '\0';
            addWord(wf, word);
            word = NULL;
            i = 0;
            size = 0;
        }
    }
    // Free the memory allocated for the last word
    free(word);
    // Sort the array in descending order of word count
    qsort(wf, sizeof(wf)/sizeof(WordFreq), sizeof(WordFreq), compare);
    return wf;
}

int main(void) {
    FILE* fp;
    WordFreq* wf;
    char filename[20];
    printf("Enter the name of the file to analyze: ");
    scanf("%s", filename);
    fp = fopen(filename, "r");
    if(fp == NULL) {
        printf("Error: File could not be opened!\n");
        return 1;
    }
    wf = count(fp);
    int i;
    printf("Word\t\tCount\n");
    for(i = 0; wf[i].word; i++) {
        printf("%-16s%d\n", wf[i].word, wf[i].count);
    }
    // Free the memory allocated to the WordFreq array
    free(wf);
    fclose(fp);
    return 0;
}

