//GPT-4o-mini DATASET v1.0 Category: Resume Parsing System ; Style: Claude Shannon
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_RESUMES 100
#define MAX_NAME_LENGTH 100
#define MAX_EMAIL_LENGTH 100
#define MAX_PHONE_LENGTH 15
#define MAX_SKILLS 10
#define MAX_SKILL_LENGTH 50

typedef struct {
    char name[MAX_NAME_LENGTH];
    char email[MAX_EMAIL_LENGTH];
    char phone[MAX_PHONE_LENGTH];
    char skills[MAX_SKILLS][MAX_SKILL_LENGTH];
    int skill_count;
} Resume;

void parse_resume(const char *resume_text, Resume *resume) {
    char *line = strtok((char *)resume_text, "\n");

    // Parse name
    if (line != NULL) {
        strncpy(resume->name, line, MAX_NAME_LENGTH);
        resume->name[MAX_NAME_LENGTH - 1] = '\0';
    }

    // Parse email
    line = strtok(NULL, "\n");
    if (line != NULL) {
        strncpy(resume->email, line, MAX_EMAIL_LENGTH);
        resume->email[MAX_EMAIL_LENGTH - 1] = '\0';
    }

    // Parse phone number
    line = strtok(NULL, "\n");
    if (line != NULL) {
        strncpy(resume->phone, line, MAX_PHONE_LENGTH);
        resume->phone[MAX_PHONE_LENGTH - 1] = '\0';
    }

    // Parse skills
    resume->skill_count = 0;
    while ((line = strtok(NULL, "\n")) != NULL && resume->skill_count < MAX_SKILLS) {
        strncpy(resume->skills[resume->skill_count], line, MAX_SKILL_LENGTH);
        resume->skills[resume->skill_count][MAX_SKILL_LENGTH - 1] = '\0';
        resume->skill_count++;
    }
}

void print_resume(const Resume *resume) {
    printf("Name: %s\n", resume->name);
    printf("Email: %s\n", resume->email);
    printf("Phone: %s\n", resume->phone);
    printf("Skills:\n");

    for (int i = 0; i < resume->skill_count; i++) {
        printf("- %s\n", resume->skills[i]);
    }
}

void load_resumes(const char *filename, Resume resumes[], int *count) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Unable to open file");
        exit(EXIT_FAILURE);
    }

    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        char resume_text[2048] = "";
        strcat(resume_text, buffer);

        for (int i = 0; i < 3 && fgets(buffer, sizeof(buffer), file); i++) {
            strcat(resume_text, buffer);
        }

        resumes[*count] = (Resume) {{0}};
        parse_resume(resume_text, &resumes[*count]);
        (*count)++;
    }
    fclose(file);
}

void save_to_file(const Resume resumes[], int count, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        perror("Unable to open file for writing");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < count; i++) {
        fprintf(file, "%s\n%s\n%s\n", resumes[i].name, resumes[i].email, resumes[i].phone);
        for (int j = 0; j < resumes[i].skill_count; j++) {
            fprintf(file, "%s\n", resumes[i].skills[j]);
        }
        fprintf(file, "\n");
    }
    fclose(file);
}

int main() {
    Resume resumes[MAX_RESUMES];
    int count = 0;

    load_resumes("resumes.txt", resumes, &count);

    for (int i = 0; i < count; i++) {
        printf("\nResume #%d:\n", i + 1);
        print_resume(&resumes[i]);
    }

    save_to_file(resumes, count, "parsed_resumes.txt");

    printf("\nAll resumes have been parsed and saved to parsed_resumes.txt.\n");

    return 0;
}

//MISTRAL-7B DATASET v1.0 Category: Hexadecimal Converter ; Style: single-threaded
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define SIZE 32

void hex_to_bin(unsigned char hex, unsigned char bin[4]) {
    int i;

    for (i = 0; i < 4; i++) {
        bin[3 - i] = (hex & (0x1 << (4 * i))) ? '1' : '0';
        hex >>= 4;
    }
}

void print_bin(unsigned char bin[4]) {
    int i;

    for (i = 0; i < 4; i++)
        printf("%c", bin[i]);
}

void hex_to_binary(char hex[]) {
    unsigned char bin[4];
    int i, len = strlen(hex);

    if (len != 2) {
        printf("Invalid hexadecimal value.\n");
        return;
    }

    for (i = 0; i < len; i++) {
        if (isdigit(hex[i]))
            hex[i] += '0' - '0' + 10;
        hex_to_bin(hex[i], bin);
        memmove(bin + 1, bin, 3);
    }

    print_bin(bin);
    printf("\n");
}

int main() {
    char hex[3];

    printf("Enter a hexadecimal number: ");
    scanf("%s", hex);

    hex_to_binary(hex);

    return 0;
}

