using namespace std;

int TossCoins(int numberCoins)
{
	// 随机抛硬币
	static RandomNumber coinToss;
	int i, tosses = 0;
	for(i = 0; i < numberCoins; ++i)
		tosses += coinToss.Random(2);
	return tosses;
}

int main()
{
	// 模拟随机抛硬币事件
	const int NCOINS = 10;
	const long NTOSSES = 50000L;
	// heads[i]得到的i次正面的次数
	long i, heads[NCOINS+1];
	int j, position;
	// 初始化数组heads
	for(j = 0; j < NCOINS+1; ++j)
		heads[j] = 0;
	// 重复50,000次模拟事件
	for(i = 0; i < NTOSSES; ++i)
		heads[TossCoins(NCOINS)] ++;
	// 输出频率图
	for(i = 0; i <= NCOINS; ++i)
	{
		position = int (float(heads[i]) / NTOSSES*72);
		cout << setw(6) << i << " ";
		for(j = 0; j<position-1; ++j)
			cout << " ";
		cout << "*" << endl;
	}
	return 0;
}

//GPT-4o-mini DATASET v1.0 Category: TCP/IP Programming ; Style: scientific
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <math.h>

#define PORT 8080
#define BUFFER_SIZE 1024

void evaluate_expression(char *expression, char *result) {
    double value = 0.0;
    char operation;
    double num;

    // Simple evaluation logic
    char *ptr = expression;
    while (*ptr) {
        if (sscanf(ptr, "%lf %c", &num, &operation) > 0) {
            value += num;
            ptr += (operation ? 3 : 2); // Move past num and operator
            if (operation == '\0') break; // End of expression
        }
    }

    sprintf(result, "Result: %lf", value);
}

void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE] = {0};
    char result[BUFFER_SIZE];

    read(client_socket, buffer, BUFFER_SIZE);
    printf("Expression received: %s\n", buffer);

    evaluate_expression(buffer, result);

    send(client_socket, result, strlen(result), 0);
    printf("Result sent: %s\n", result);

    close(client_socket);
}

int main() {
    int server_socket, client_socket;
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);

    // Creating socket file descriptor
    if ((server_socket = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("Socket creation error");
        exit(EXIT_FAILURE);
    }

    // Forcefully attaching socket to the port
    if (setsockopt(server_socket, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt))) {
        perror("setsockopt");
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Binding the socket
    if (bind(server_socket, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Bind failed");
        exit(EXIT_FAILURE);
    }

    // Listening for incoming connections
    if (listen(server_socket, 3) < 0) {
        perror("Listen failed");
        exit(EXIT_FAILURE);
    }

    printf("Server is listening on port %d\n", PORT);

    while (1) {
        if ((client_socket = accept(server_socket, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("Accept failed");
            continue;
        }
        printf("Connection established with client.\n");
        handle_client(client_socket);
    }

    close(server_socket);
    return 0;
}

