#include <stdlib.h>
#include <stdio.h>
#include <stdbool.h>

// Game of Life grid dimensions
#define GRID_WIDTH 80
#define GRID_HEIGHT 25

// Number of generations to simulate
#define GENERATIONS 100

// Cell states
typedef enum {
    DEAD,
    ALIVE
} cell_state;

// Game of Life grid
cell_state grid[GRID_HEIGHT][GRID_WIDTH];

// Function to initialize the grid with a random pattern
void initialize_grid() {
    for (int i = 0; i < GRID_HEIGHT; i++) {
        for (int j = 0; j < GRID_WIDTH; j++) {
            grid[i][j] = rand() % 2;
        }
    }
}

// Function to count the number of living neighbors of a cell
int count_neighbors(int x, int y) {
    int count = 0;
    for (int i = -1; i <= 1; i++) {
        for (int j = -1; j <= 1; j++) {
            if (i == 0 && j == 0) {
                continue;
            }
            int neighbor_x = x + i;
            int neighbor_y = y + j;
            if (neighbor_x < 0 || neighbor_x >= GRID_WIDTH || neighbor_y < 0 || neighbor_y >= GRID_HEIGHT) {
                continue;
            }
            if (grid[neighbor_y][neighbor_x] == ALIVE) {
                count++;
            }
        }
    }
    return count;
}

// Function to update the state of a cell based on the number of living neighbors
void update_cell(int x, int y) {
    int neighbors = count_neighbors(x, y);
    if (grid[y][x] == ALIVE) {
        if (neighbors < 2 || neighbors > 3) {
            grid[y][x] = DEAD;
        }
    } else {
        if (neighbors == 3) {
            grid[y][x] = ALIVE;
        }
    }
}

// Function to print the grid to the console
void print_grid() {
    for (int i = 0; i < GRID_HEIGHT; i++) {
        for (int j = 0; j < GRID_WIDTH; j++) {
            if (grid[i][j] == ALIVE) {
                printf("X");
            } else {
                printf(" ");
            }
        }
        printf("\n");
    }
}

int main() {
    // Initialize the grid
    initialize_grid();

    // Simulate the Game of Life for a number of generations
    for (int generation = 0; generation < GENERATIONS; generation++) {
        // Update the state of each cell
        for (int i = 0; i < GRID_HEIGHT; i++) {
            for (int j = 0; j < GRID_WIDTH; j++) {
                update_cell(i, j);
            }
        }

        // Print the grid to the console
        print_grid();

        // Slow down the simulation
        system("pause");
    }

    return 0;
}

