#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdint.h>

typedef struct {
    uint8_t data[1024];
    size_t length;
} ChecksumBuffer;

void checksum_init(ChecksumBuffer *buffer) {
    memset(buffer->data, 0, sizeof(buffer->data));
    buffer->length = 0;
}

void checksum_update(ChecksumBuffer *buffer, const void *data, size_t length) {
    const uint8_t *src = data;
    uint32_t sum = 0;

    checksum_init(buffer);

    for (size_t i = 0; i < length; ++i) {
        sum += ((uint32_t) buffer->data[buffer->length] << 8) | (*src++);
        buffer->data[buffer->length++] ^= sum & 0xff;
        sum &= 0xffffff00;
    }
}

void checksum_final(ChecksumBuffer *buffer, uint8_t *dest) {
    size_t pad_len = 1;
    if (buffer->length % 2) {
        pad_len = 2 - (buffer->length % 2);
        buffer->length++;
    }

    buffer->data[buffer->length++] = 0x55;
    buffer->data[buffer->length++] = 0xaa;

    for (size_t i = 0; i < pad_len; ++i) {
        buffer->data[buffer->length++] = 0x55;
    }

    uint32_t sum = 0;
    for (size_t i = 0; i < buffer->length; ++i) {
        sum += buffer->data[i];
    }

    for (size_t i = 0; i < buffer->length; ++i) {
        buffer->data[i] ^= (sum >> 8) & 0xff;
        sum &= 0xff;
    }

    for (size_t i = 0; i < buffer->length; ++i) {
        dest[i] = buffer->data[i];
    }
}

void print_checksum(const uint8_t *data, size_t length) {
    ChecksumBuffer buffer;
    checksum_update(&buffer, data, length);
    uint8_t checksum[1024];
    checksum_final(&buffer, checksum);

    for (size_t i = 0; i < length; ++i) {
        printf("%.2hhx ", data[i]);
    }

    printf("\nChecksum: ");
    for (size_t i = 0; i < sizeof(checksum); ++i) {
        printf("%.2hhx ", checksum[i]);
    }

    printf("\n");
}

int main() {
    char input[] = "Hello World! Checksum please.";
    size_t input_len = strlen(input) + 1;

    printf("Input: ");
    for (size_t i = 0; i < input_len; ++i) {
        printf("%.2hhx ", input[i]);
    }

    printf("\n");

    print_checksum(input, input_len);

    return EXIT_SUCCESS;
}

