// A function to remove leading and trailing white spaces from a string
void trim_whitespace(char* str) {
    int len = strlen(str);
    int i = 0, j = len - 1;

    while(i < len && isspace(str[i])) {
        i++;
    }
    while(j > i && isspace(str[j])) {
        j--;
    }

    str[j+1] = '\0';

    if(i > 0) {
