void multiplyMatrices(float result[][COLS2], float mat1[][ROWS1], float mat2[][ROWS2], int rows1, int cols1, int rows2, int cols2) {
    int i, j, k;

    for (i = 0; i < rows1; i++) {
        for (j = 0; j < cols2; j++) {
            result[i][j] = 0;
            for (k = 0; k < cols1; k++) {
                result[i][j] += mat1[i][k] * mat2[k][j];
            }
        }
    }
