#define MAX_SIZE 10

int main()
{
    int **grid = (int **)malloc(MAX_SIZE * sizeof(int *));
    for (int r = 0; r < MAX_SIZE; r++)
    {
        grid[r] = (int *)malloc(MAX_SIZE * sizeof(int));
    }

    for (int r = 0; r < MAX_SIZE; r++)
    {
        for (int c = 0; c < MAX_SIZE; c++)
        {
            grid[r][c] = 0;
        }
    }

    int x = 5, y = 5;
    grid[x][y] = 1;

    percolation(grid, MAX_SIZE, x, y);

    for (int r = 0; r < MAX_SIZE; r++)
    {
        for (int c = 0; c < MAX_SIZE; c++)
        {
            printf("%d ", grid[r][c]);
        }
        printf("\n");
    }

    free(grid);
    return 0;
}

void percolation(int **grid, int size, int x, int y)
{
    if (x < 0 || x >= size || y < 0 || y >= size)
    {
        return;
    }

    if (grid[x][y] == 0)
    {
        return;
    }

    grid[x][y] = 2;

    percolation(grid, size, x - 1, y);
    percolation(grid, size, x + 1, y);
    percolation(grid, size, x, y - 1);
    percolation(grid, size, x, y + 1);
}

