int arr[10005], item, pos;

void binarySearch(int low, int high){
    if(low<=high){
        int middle = (low+high)/2;
        if(arr[middle]==item)
            pos = middle;
        if(item <= arr[middle]) binarySearch(low, middle-1);

        else binarySearch(middle+1, high);
    }
    else return;
}

