/*
 * A simple C program to monitor network packets using the libpcap library.
 */

#include <stdio.h>
#include <stdlib.h>
#include <pcap.h>

#define DEVICE "eth0"
#define SNAP_LEN 1518
#define PROMISC 1
#define TIMEOUT 1000

void packet_handler(u_char *args, const struct pcap_pkthdr *header, const u_char *packet) {
    printf("Received packet of length %d\n", header->len);
}

int main() {
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle;

    // Open the device
    handle = pcap_open_live(DEVICE, SNAP_LEN, PROMISC, TIMEOUT, errbuf);
    if (handle == NULL) {
        printf("Failed to open device: %s\n", errbuf);
        return 1;
    }

    // Set the filter
    struct bpf_program filter;
    bpf_u_int32 mask;
    bpf_u_int32 net;
    if (pcap_lookupnet(DEVICE, &net, &mask, errbuf) == -1) {
        printf("Error looking up device: %s\n", errbuf);
        return 1;
    }
    char filter_exp[] = "ip";
    if (pcap_compile(handle, &filter, filter_exp, 0, net) == -1) {
        printf("Error compiling filter: %s\n", pcap_geterr(handle));
        return 1;
    }
    if (pcap_setfilter(handle, &filter) == -1) {
        printf("Error setting filter: %s\n", pcap_geterr(handle));
        return 1;
    }

    // Start the loop
    while (1) {
        pcap_loop(handle, -1, packet_handler, NULL);
    }

    // Clean up
    pcap_close(handle);

    return 0;
}

