    int board[HEIGHT][WIDTH];
    init(board);
    for (int i = 0; i < DROPS; i++) {
        int x = rand() % WIDTH;
        int y = rand() % HEIGHT;
        random_drop(board, x, y);
        print_board(board);
    }
    return 0;
}

void init(int board[HEIGHT][WIDTH]) {
    for (int i = 0; i < HEIGHT; i++) {
        for (int j = 0; j < WIDTH; j++) {
            board[i][j] = 0;
        }
    }
}

void random_drop(int board[HEIGHT][WIDTH], int x, int y) {
    if (y >= HEIGHT) {
        return;
    }
    board[y][x] = 1;
    if (count_neighbors(board, x, y) == 0) {
        board[y][x] = 0;
        return;
    }
    for (int k = y + 1; k < HEIGHT; k++) {
        board[k][x] = 1;
    }
}

void print_board(int board[HEIGHT][WIDTH]) {
    for (int i = 0; i < HEIGHT; i++) {
        for (int j = 0; j < WIDTH; j++) {
            if (board[i][j] == 1) {
                printf("#");
            } else {
                printf(".");
            }
        }
        printf("\n");
    }
}

int count_neighbors(int board[HEIGHT][WIDTH], int x, int y) {
    int count = 0;
    if (x > 0 && board[y][x - 1] == 1) {
        count++;
    }
    if (x < WIDTH - 1 && board[y][x + 1] == 1) {
        count++;
    }
    if (y > 0 && board[y - 1][x] == 1) {
        count++;
    }
    if (y < HEIGHT - 1 && board[y + 1][x] == 1) {
        count++;
    }
    return count;
}

