#include <stdio.h>
#include <stdlib.h>

#define ROWS 3
#define COLS 3

char board[ROWS][COLS];
int player;  // 1 for X, -1 for O

void initBoard() {
  for (int i = 0; i < ROWS; i++) {
    for (int j = 0; j < COLS; j++) {
      board[i][j] = ' ';
    }
  }
}

void printBoard() {
  printf("\n");
  for (int i = 0; i < ROWS; i++) {
    for (int j = 0; j < COLS; j++) {
      printf(" %c ", board[i][j]);
    }
    printf("\n");
  }
  printf("\n");
}

int checkWin() {
  // Check rows
  for (int i = 0; i < ROWS; i++) {
    if (board[i][0] == board[i][1] && board[i][1] == board[i][2] && board[i][0] != ' ') {
      return board[i][0];
    }
  }

  // Check columns
  for (int j = 0; j < COLS; j++) {
    if (board[0][j] == board[1][j] && board[1][j] == board[2][j] && board[0][j] != ' ') {
      return board[0][j];
    }
  }

  // Check diagonals
  if (board[0][0] == board[1][1] && board[1][1] == board[2][2] && board[0][0] != ' ') {
    return board[0][0];
  }
  if (board[0][2] == board[1][1] && board[1][1] == board[2][0] && board[0][2] != ' ') {
    return board[0][2];
  }

  return 0;
}

int minimax(int depth, int maximizingPlayer) {
  int score = checkWin();
  if (score != 0) {
    return score * depth;
  }

  if (depth >= 9) {
    return 0;
  }

  int bestScore;
  if (maximizingPlayer) {
    bestScore = -1000;
    for (int i = 0; i < ROWS; i++) {
      for (int j = 0; j < COLS; j++) {
        if (board[i][j] == ' ') {
          board[i][j] = 'X';
          int score = minimax(depth + 1, 0);
          board[i][j] = ' ';
          if (score > bestScore) {
            bestScore = score;
          }
        }
      }
    }
  } else {
    bestScore = 1000;
    for (int i = 0; i < ROWS; i++) {
      for (int j = 0; j < COLS; j++) {
        if (board[i][j] == ' ') {
          board[i][j] = 'O';
          int score = minimax(depth + 1, 1);
          board[i][j] = ' ';
          if (score < bestScore) {
            bestScore = score;
          }
        }
      }
    }
  }

  return bestScore;
}

void computerMove() {
  int bestScore = -1000;
  int bestMove = -1;
  for (int i = 0; i < ROWS; i++) {
    for (int j = 0; j < COLS; j++) {
      if (board[i][j] == ' ') {
        board[i][j] = 'X';
        int score = minimax(0, 0);
        board[i][j] = ' ';
        if (score > bestScore) {
          bestScore = score;
          bestMove = i * ROWS + j;
        }
      }
    }
  }

  int row = bestMove / ROWS;
  int col = bestMove % ROWS;
  board[row][col] = 'X';
}

int main() {
  initBoard();
  printBoard();

  while (1) {
    int row, col;

    printf("Enter row and column (0-2): ");
    scanf("%d %d", &row, &col);

    if (board[row][col] != ' ') {
      printf("Invalid move!\n");
      continue;
    }

    board[row][col] = 'O';
    printBoard();

    int score = checkWin();
    if (score != 0) {
      if (score == 1) {
        printf("You win!\n");
      } else if (score == -1) {
        printf("Computer wins!\n");
      } else {
        printf("Draw!\n");
      }
      break;
    }

    computerMove();
    printBoard();

    score = checkWin();
    if (score != 0) {
      if (score == 1) {
        printf("You win!\n");
      } else if (score == -1) {
        printf("Computer wins!\n");
      } else {
        printf("Draw!\n");
      }
      break;
    }
  }

  return 0;
}

