//LLAMA2-13B DATASET v1.0 Category: Unit converter ; Style: happy
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_UNITS 5
#define MAX_VALUE 1000

// Structure to store units and their conversions
typedef struct {
    char *name;    // Unit name
    double factor; // Conversion factor
} unit_t;

// Array to store all units
unit_t units[MAX_UNITS] = {
    {"cm", 1.0 / 100.0},  // Centimeters to meters
    {"m", 1.0},         // Meters
    {"km", 1000.0 / 100.0},  // Kilometers to meters
    {"mm", 1.0 / 1000.0},  // Millimeters to meters
    {"ft", 3.28084 / 100.0},  // Feet to meters
};

// Function to convert a value from one unit to another
double convert_unit(double value, char *from_unit, char *to_unit) {
    int i = 0;
    for (i = 0; i < MAX_UNITS; i++) {
        if (strcmp(from_unit, units[i].name) == 0) {
            break;
        }
    }
    if (i == MAX_UNITS) {
        printf("Error: Unknown unit %s\n", from_unit);
        return 0;
    }
    value *= units[i].factor;
    value /= units[i].factor;
    i++;
    for (; i < MAX_UNITS; i++) {
        if (strcmp(to_unit, units[i].name) == 0) {
            break;
        }
    }
    if (i == MAX_UNITS) {
        printf("Error: Unknown unit %s\n", to_unit);
        return 0;
    }
    value /= units[i].factor;
    return value;
}

int main() {
    double value = 50;  // Start with a value in meters
    char from_unit[] = "m";  // Start with meters
    char to_unit[] = "ft";   // Convert to feet

    // Convert value from meters to feet
    value = convert_unit(value, from_unit, to_unit);
    printf("Value in feet: %f\n", value);

    // Convert value from meters to kilometers
    value = convert_unit(value, from_unit, "km");
    printf("Value in kilometers: %f\n", value);

    // Convert value from feet to meters
    value = convert_unit(value, "ft", from_unit);
    printf("Value in meters: %f\n", value);

    // Convert value from feet to centimeters
    value = convert_unit(value, "ft", "cm");
    printf("Value in centimeters: %f\n", value);

    return 0;
}

