#include<iostream>
using namespace std;
struct node
{
    int data;
    node *prev,*next;
};
typedef node* NODE;
NODE get_node()
{
    NODE x;
    x=new node;
    if(x==NULL)
        cout<<"Memory Full";
    return x;
}
NODE insert_front(NODE &head,int x)
{
    NODE temp=get_node();
    temp->data=x;
    temp->next=NULL;
    temp->prev=NULL;
    if(head==NULL)
    {
        head=temp;
        return head;
    }
    temp->next=head;
    head=temp;
    return head;
}
NODE insert_rear(NODE &head,int x)
{
    NODE temp=get_node();
    temp->data=x;
    temp->next=NULL;
    temp->prev=NULL;
    if(head==NULL)
    {
        head=temp;
        return head;
    }
    NODE temp2=head;
    while(temp2->next!=NULL)
        temp2=temp2->next;
    temp->prev=temp2;
    temp2->next=temp;
    return head;
}
NODE delete_front(NODE &head)
{
    if(head==NULL)
    {
        cout<<"\nList Empty\n";
        return head;
    }
    cout<<"\nElement Removed : "<<head->data;
    if(head->next==NULL)
    {
        delete head;
        head=NULL;
        return head;
    }
    NODE temp=head;
    head=head->next;
    head->prev=NULL;
    delete temp;
    return head;
}
NODE delete_rear(NODE &head)
{
    NODE temp=head;
    if(head==NULL)
    {
        cout<<"List Empty";
        return head;
    }
    else if(head->next==NULL)
    {
        cout<<"\nElement Removed : "<<head->data;
        delete head;
        head=NULL;
        return head;
    }
    while(temp->next->next!=NULL)
        temp=temp->next;
    cout<<"\nElement Removed : "<<temp->next->data;
    delete temp->next;
    temp->next=NULL;
    return head;
}
void display(NODE head)
{
    NODE temp=head;
    cout<<"\nList : ";
    while(temp!=NULL)
    {
        cout<<temp->data<<"->";
        temp=temp->next;
    }
    cout<<endl;

}
NODE insert_position(NODE &head,int x,int pos)
{
    NODE temp=head;
    int i;
    NODE new_node=get_node();
    new_node->data=x;
    if(pos==1)
        return insert_front(head,x);
    for(i=1;i<pos-1&&temp->next!=NULL;i++)
        temp=temp->next;
    if(i<pos-1)
    {
        cout<<"\nInvalid Position\n";
        return head;
    }
    else if(temp->next==NULL)
        return insert_rear(head,x);
    new_node->next=temp->next;
    new_node->prev=temp;
    new_node->next->prev=new_node;
    temp->next=new_node;
    return head;
}
NODE delete_position(NODE &head,int pos)
{
    NODE temp=head;
    int i;
    if(head==NULL)
    {
        cout<<"List empty";
        return head;
    }
    if(pos==1)
    {
        return delete_front(head);
    }
    for(i=1;i<pos-1&&temp->next->next!=NULL;i++)
        temp=temp->next;
    if(i<pos-1)
    {
        cout<<"\nInvalid Position\n";
        return head;
    }
    else if(temp->next->next==NULL)
        return delete_rear(head);
    cout<<"\nElement removed : "<<temp->next->data;
    delete temp->next;
    temp->next=temp->next->next;
    temp->next->prev=temp;
    return head;
}
int search_list(NODE head,int x)
{
    NODE temp=head;
    int pos=1;
    while(temp!=NULL)
    {
        if(temp->data==x)
            return pos;
        pos++;
        temp=temp->next;
    }
    return 0;
}
NODE delete_all_x(NODE &head,int x)
{
    int pos=1;
    while(pos)
    {
        pos=search_list(head,x);
        if(pos)
            head=delete_position(head,pos);
    }
    return head;
}
