#include <stdio.h>
#include <stdlib.h>

// Define the grid size
#define GRID_WIDTH 80
#define GRID_HEIGHT 25

// Define the number of generations
#define GENERATIONS 100

// Define the cell states
#define DEAD 0
#define ALIVE 1

// Create the grid
int grid[GRID_HEIGHT][GRID_WIDTH];

// Initialize the grid
void init_grid() {
  for (int i = 0; i < GRID_HEIGHT; i++) {
    for (int j = 0; j < GRID_WIDTH; j++) {
      grid[i][j] = DEAD;
    }
  }
}

// Print the grid
void print_grid() {
  for (int i = 0; i < GRID_HEIGHT; i++) {
    for (int j = 0; j < GRID_WIDTH; j++) {
      printf("%c", grid[i][j] == ALIVE ? '*' : ' ');
    }
    printf("\n");
  }
}

// Get the number of alive neighbors of a cell
int get_num_alive_neighbors(int i, int j) {
  int num_alive_neighbors = 0;

  // Check the cells around the given cell
  for (int x = -1; x <= 1; x++) {
    for (int y = -1; y <= 1; y++) {
      if (x == 0 && y == 0) {
        continue;
      }

      int neighbor_i = i + x;
      int neighbor_j = j + y;

      // Wrap around the edges of the grid
      if (neighbor_i < 0) {
        neighbor_i = GRID_HEIGHT - 1;
      } else if (neighbor_i >= GRID_HEIGHT) {
        neighbor_i = 0;
      }

      if (neighbor_j < 0) {
        neighbor_j = GRID_WIDTH - 1;
      } else if (neighbor_j >= GRID_WIDTH) {
        neighbor_j = 0;
      }

      // Count the number of alive neighbors
      if (grid[neighbor_i][neighbor_j] == ALIVE) {
        num_alive_neighbors++;
      }
    }
  }

  return num_alive_neighbors;
}

// Update the grid to the next generation
void update_grid() {
  // Create a temporary grid to store the next generation
  int next_grid[GRID_HEIGHT][GRID_WIDTH];

  // Iterate over the cells in the grid
  for (int i = 0; i < GRID_HEIGHT; i++) {
    for (int j = 0; j < GRID_WIDTH; j++) {
      // Get the number of alive neighbors of the cell
      int num_alive_neighbors = get_num_alive_neighbors(i, j);

      // Apply the rules of the Game of Life
      if (grid[i][j] == ALIVE) {
        if (num_alive_neighbors < 2 || num_alive_neighbors > 3) {
          next_grid[i][j] = DEAD;
        } else {
          next_grid[i][j] = ALIVE;
        }
      } else if (grid[i][j] == DEAD) {
        if (num_alive_neighbors == 3) {
          next_grid[i][j] = ALIVE;
        } else {
          next_grid[i][j] = DEAD;
        }
      }
    }
  }

  // Copy the next generation into the grid
  for (int i = 0; i < GRID_HEIGHT; i++) {
    for (int j = 0; j < GRID_WIDTH; j++) {
      grid[i][j] = next_grid[i][j];
    }
  }
}

// Main function
int main() {
  // Initialize the grid
  init_grid();

  // Set the initial state of the grid
  grid[10][10] = ALIVE;
  grid[10][11] = ALIVE;
  grid[10][12] = ALIVE;
  grid[11][11] = ALIVE;

  // Print the initial grid
  print_grid();

  // Update the grid for the specified number of generations
  for (int i = 0; i < GENERATIONS; i++) {
    update_grid();
    printf("\nGeneration %d:\n", i + 1);
    print_grid();
  }

  return 0;
}

