    printf("Steps: %d\n", userData.steps);
    printf("Distance: %.2f kilometers\n", userData.distance);
    printf("Last Workout: %s\n", ctime(&userData.lastWorkout));
}

void calculateHeartRate(UserData* userData) {
    userData->heartRate = rand() % (MAX_HEART_RATE - MIN_HEART_RATE + 1) + MIN_HEART_RATE;
