void initFileSystem(FileSystem* fs) {
    fs->count = 0;
}

// Function to create a file
void createFile(FileSystem* fs, const char* filename, int size, int isDirectory) {
    if (fs->count >= MAX_FILES) {
        printf("Error: File system is full!\n");
        return;
    }
    strcpy(fs->files[fs->count].name, filename);
    fs->files[fs->count].size = size;
    fs->files[fs->count].isDirectory = isDirectory;
    fs->count++;
    printf("File created: %s (Size: %d bytes, %s)\n", filename, size, isDirectory ? "Directory" : "File");
}

// Function to delete a file
void deleteFile(FileSystem* fs, const char* filename) {
    for (int i = 0; i < fs->count; i++) {
        if (strcmp(fs->files[i].name, filename) == 0) {
            // Shift files to the left to remove the deleted file
            for (int j = i; j < fs->count - 1; j++) {
                fs->files[j] = fs->files[j + 1];
            }
            fs->count--;
            printf("File deleted: %s\n", filename);
            return;
        }
    }
    printf("Error: File not found: %s\n", filename);
}

// Function to list all files in the FileSystem
void listFiles(FileSystem* fs) {
    if (fs->count == 0) {
        printf("No files in the system.\n");
        return;
    }
    printf("Files in the system:\n");
    for (int i = 0; i < fs->count; i++) {
        printf(" - %s (Size: %d bytes, %s)\n", fs->files[i].name, fs->files[i].size, fs->files[i].isDirectory ? "Directory" : "File");
    }
}

// Function to search for a file
void searchFile(FileSystem* fs, const char* filename) {
    for (int i = 0; i < fs->count; i++) {
        if (strcmp(fs->files[i].name, filename) == 0) {
            printf("File found: %s (Size: %d bytes, %s)\n", fs->files[i].name, fs->files[i].size, fs->files[i].isDirectory ? "Directory" : "File");
            return;
        }
    }
    printf("File not found: %s\n", filename);
}

// Main function for the simulation
int main() {
    FileSystem fs;
    initFileSystem(&fs);

