#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the size of the memory game grid
#define GRID_SIZE 10

// Define the number of items to be remembered
#define ITEM_COUNT 10

// Define a structure to represent a memory item
struct memory_item {
    int item_value;
    char item_label[20];
};

// Define an array to store the memory items
struct memory_item items[GRID_SIZE][ITEM_COUNT];

// Define a variable to keep track of the current item being remembered
int current_item = 0;

// Define a function to generate a random item value and label
void generate_item(struct memory_item *item) {
    item->item_value = rand() % 10;
    sprintf(item->item_label, "Item %d", item->item_value);
}

// Define a function to display the memory game grid
void display_grid(struct memory_item grid[GRID_SIZE][ITEM_COUNT]) {
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < ITEM_COUNT; j++) {
            printf("%d. %s\n", i * ITEM_COUNT + j, grid[i][j].item_label);
        }
    }
}

// Define a function to check if an item is correct
int check_item(struct memory_item expected, struct memory_item actual) {
    if (expected.item_value == actual.item_value) {
        return 1;
    } else {
        return 0;
    }
}

// Define a function to play the memory game
void play_game() {
    // Initialize the memory game grid
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < ITEM_COUNT; j++) {
            generate_item(&items[i][j]);
        }
    }

    // Display the memory game grid
    display_grid(items);

    // Ask the player to select an item
    printf("Select an item to remember: ");
    int selected_item = getchar();

    // Loop until the player correctly remembers all items
    while (1) {
        // Display the memory game grid with the selected item highlighted
        display_grid(items);

        // Ask the player to recall the selected item
        printf("Recall the item you selected: ");
        int recall = getchar();

        // Check if the player correctly recalled the selected item
        struct memory_item expected = items[selected_item / ITEM_COUNT][selected_item % ITEM_COUNT];
        struct memory_item actual = items[recall / ITEM_COUNT][recall % ITEM_COUNT];
        if (check_item(expected, actual)) {
            printf("Correct! The selected item was %s\n", expected.item_label);
        } else {
            printf("Incorrect. The selected item was %s, but you recalled %s\n", expected.item_label, actual.item_label);
        }

        // Increment the selected item and repeat the process
        selected_item = (selected_item + 1) % GRID_SIZE;
    }
}

int main() {
    srand(time(NULL));

    // Initialize the memory game grid
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < ITEM_COUNT; j++) {
            generate_item(&items[i][j]);
        }
    }

    // Display the memory game grid
    display_grid(items);

    // Play the memory game
    play_game();

    return 0;
}

