#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>

#define NUM_PLAYERS 4
#define MAX_WEATHER_TYPES 5
#define CYCLES 10

typedef struct {
    int id;
    int weather_condition;
} Player;

char* weather_types[MAX_WEATHER_TYPES] = {"Sunny", "Rainy", "Snowy", "Windy", "Stormy"};
Player players[NUM_PLAYERS];
pthread_mutex_t weather_mutex;

void* player_action(void* arg) {
    Player* player = (Player*)arg;
    for (int i = 0; i < CYCLES; i++) {
        pthread_mutex_lock(&weather_mutex);
        int new_weather = rand() % MAX_WEATHER_TYPES;
        player->weather_condition = new_weather;
        printf("Player %d experiences: %s\n", player->id, weather_types[player->weather_condition]);
        pthread_mutex_unlock(&weather_mutex);

        sleep(rand() % 3 + 1); // Random sleep to simulate action time
    }
    return NULL;
}

void random_weather_change() {
    while (1) {
        sleep(5); // Change weather every 5 seconds
        pthread_mutex_lock(&weather_mutex);
        for (int i = 0; i < NUM_PLAYERS; i++) {
            players[i].weather_condition = rand() % MAX_WEATHER_TYPES;
            printf("Weather changed! Player %d new condition: %s\n", players[i].id, weather_types[players[i].weather_condition]);
        }
        pthread_mutex_unlock(&weather_mutex);
    }
}

int main() {
    srand(time(NULL));
    pthread_t players_threads[NUM_PLAYERS];
    pthread_mutex_init(&weather_mutex, NULL);

    // Initialize players
    for (int i = 0; i < NUM_PLAYERS; i++) {
        players[i].id = i + 1;
        players[i].weather_condition = rand() % MAX_WEATHER_TYPES;
    }

    // Create threads for each player
    for (int i = 0; i < NUM_PLAYERS; i++) {
        pthread_create(&players_threads[i], NULL, player_action, (void*)&players[i]);
    }

    // Start random weather change in main thread
    random_weather_change();

    // Wait for player threads to finish
    for (int i = 0; i < NUM_PLAYERS; i++) {
        pthread_join(players_threads[i], NULL);
    }

    pthread_mutex_destroy(&weather_mutex);
    return 0;
}

