#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_WORD_LENGTH 50
#define MAX_NUM_WORDS 100000

struct WordFrequency {
    char word[MAX_WORD_LENGTH];
    int frequency;
};

struct WordFrequency wordFrequencies[MAX_NUM_WORDS];
int numWords = 0;

void addWord(char* word) {
    int i;
    for (i = 0; i < numWords; i++) {
        if (strcmp(wordFrequencies[i].word, word) == 0) {
            wordFrequencies[i].frequency++;
            return;
        }
    }
    if (numWords >= MAX_NUM_WORDS) {
        printf("Error: Maximum number of words reached.\n");
        exit(1);
    }
    strcpy(wordFrequencies[numWords].word, word);
    wordFrequencies[numWords].frequency = 1;
    numWords++;
}

void printWordFrequencies() {
    int i;
    for (i = 0; i < numWords; i++) {
        printf("%s: %d\n", wordFrequencies[i].word, wordFrequencies[i].frequency);
    }
}

int main(int argc, char* argv[]) {
    char inputBuffer[100000];
    char* word;
    int i;

    if (argc < 2) {
        printf("Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    FILE* file = fopen(argv[1], "r");
    if (file == NULL) {
        printf("Error: Could not open file.\n");
        return 1;
    }

    while (fgets(inputBuffer, sizeof(inputBuffer), file)!= NULL) {
        inputBuffer[strcspn(inputBuffer, "\n")] = '\0';
        word = strtok(inputBuffer, ",.?!;:");
        while (word!= NULL) {
            addWord(word);
            word = strtok(NULL, ",.?!;:");
        }
    }

    fclose(file);

    printWordFrequencies();

    return 0;
}

