/*   
1 2 3            7 4 1
A = 4 5 6   ---> C = 8 5 2
7 8 9             9 6 3

Nhận thấy rằng hàng đã chuyển thành cột và ngược lại, ta nghĩ ngay đến 
công thức B[i][j] = A[j][i]
Nhưng đây là công thức quen thuộc của ma trận chuyển vị
kết quả khi chuyển vị như sau
1 4 7
B = 2 5 8
3 6 9

So với kết quả đích, ta thấy C chỉ khác B ở thứ tự các cột
nghĩa là cột (j) của C là cột (n - 1 - j) của B
C[i][j] = B[i][n - 1 - j] = A[n - 1 - j][i]
*/

// Xoay 270 độ thì quay 90 độ 3 lần ^^
void XoayMaTran1Goc270DoTheoChieuKimDongHo(int a[][MAX], int dong, int cot)
{
    int c[MAX][MAX];
    for(int i = 0; i < dong; i++)
    {
        for(int j = 0; j < cot; j++)
        {
            c[i][j] = a[cot - 1 - j][i];
        }
    }
    int d[MAX][MAX];
    for(int i = 0; i < dong; i++)
    {
        for(int j = 0; j < cot; j++)
        {
            d[i][j] = c[cot - 1 - j][i];
        }
    }
    int e[MAX][MAX];
    for(int i = 0; i < dong; i++)
    {
        for(int j = 0; j < cot; j++)
        {
            printf("%4d", e[i][j] = d[cot - 1 - j][i]);
        }
        printf("\n\n");
    }
}
