    rooms[i].rect.y1 = rand() % HEIGHT;
    rooms[i].rect.x2 = rooms[i].rect.x1 + rand() % (WIDTH - rooms[i].rect.x1);
    rooms[i].rect.y2 = rooms[i].rect.y1 + rand() % (HEIGHT - rooms[i].rect.y1);

    rooms[i].num_doors = rand() % 4;
    for (int j = 0; j < rooms[i].num_doors; j++) {
      rooms[i].doors[j] = rand() % 4;
    }
  }
}

void generate_map() {
  for (int i = 0; i < WIDTH; i++) {
    for (int j = 0; j < HEIGHT; j++) {
      map[i][j] = '.';
    }
  }

  for (int i = 0; i < num_rooms; i++) {
    for (int j = rooms[i].rect.x1; j < rooms[i].rect.x2; j++) {
      for (int k = rooms[i].rect.y1; k < rooms[i].rect.y2; k++) {
        map[j][k] = '#';
      }
    }
  }

  for (int i = 0; i < num_rooms; i++) {
    for (int j = 0; j < rooms[i].num_doors; j++) {
      int door = rooms[i].doors[j];
      int x, y;

      switch (door) {
        case 0: // North
          x = rooms[i].rect.x1 + rand() % (rooms[i].rect.x2 - rooms[i].rect.x1);
          y = rooms[i].rect.y1;
          map[x][y] = '+';
          break;
        case 1: // East
          x = rooms[i].rect.x2;
          y = rooms[i].rect.y1 + rand() % (rooms[i].rect.y2 - rooms[i].rect.y1);
          map[x][y] = '+';
          break;
        case 2: // South
          x = rooms[i].rect.x1 + rand() % (rooms[i].rect.x2 - rooms[i].rect.x1);
          y = rooms[i].rect.y2;
          map[x][y] = '+';
          break;
        case 3: // West
          x = rooms[i].rect.x1;
          y = rooms[i].rect.y1 + rand() % (rooms[i].rect.y2 - rooms[i].rect.y1);
          map[x][y] = '+';
          break;
      }
    }
  }
}

void print_map() {
  for (int i = 0; i < WIDTH; i++) {
    for (int j = 0; j < HEIGHT; j++) {
      printf("%c", map[i][j]);
    }
    printf("\n");
  }
}

int main() {
  srand(time(NULL));

  num_rooms = rand() % MAX_ROOMS + 1;
  generate_rooms();
  generate_map();

  print_map();

  return 0;
}

