//GPT-4o-mini DATASET v1.0 Category: Planet Gravity Simulation ; Style: multiplayer
#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <unistd.h>
#include <pthread.h>

#define G 6.67430e-11 // Gravitational constant
#define PLANET_MASS 5.972e24 // Mass of the planet (in kg)
#define PLANET_RADIUS 6371e3 // Radius of the planet (in meters)
#define NUM_PLAYERS 3 // Number of players (satellites)

typedef struct {
    double x, y; // Position of the satellite
    double vx, vy; // Velocity of the satellite
    int id; // Player ID
} Player;

Player players[NUM_PLAYERS];

void *update_position(void *arg) {
    Player *player = (Player *)arg;
    while (1) {
        double r = sqrt(player->x * player->x + player->y * player->y);
        double force = (G * PLANET_MASS) / (r * r);

        double ax = -force * (player->x / r);
        double ay = -force * (player->y / r);

        player->vx += ax * 1; // Update velocity
        player->vy += ay * 1;

        player->x += player->vx; // Update position
        player->y += player->vy;

        if (r < PLANET_RADIUS) {
            printf("Player %d crashed into the planet!\n", player->id);
            break; // Exit on crash
        }

        usleep(100000); // Sleep for 0.1 seconds
    }
    return NULL;
}

void display_positions() {
    system("clear");
    printf("Satellite Positions:\n");
    for (int i = 0; i < NUM_PLAYERS; i++) {
        printf("Player %d - Position: (%.2f, %.2f)\n", players[i].id, players[i].x, players[i].y);
    }
    printf("\n");
}

int main() {
    pthread_t threads[NUM_PLAYERS];

    // Initialize players in orbit
    for (int i = 0; i < NUM_PLAYERS; i++) {
        players[i].id = i;
        players[i].x = (i + 1) * 1e7; // Starting x position (in meters)
        players[i].y = 0; // Starting y position
        players[i].vx = 0; // Velocity in x direction
        players[i].vy = sqrt(G * PLANET_MASS / players[i].x); // Initial velocity for orbit
    }

    // Create threads for updating each player's position
    for (int i = 0; i < NUM_PLAYERS; i++) {
        pthread_create(&threads[i], NULL, update_position, (void *)&players[i]);
    }

    // Display positions in a loop
    while (1) {
        display_positions();
        usleep(500000); // Update display every half a second
    }

    // Join threads (unreachable in this example)
    for (int i = 0; i < NUM_PLAYERS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

