#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <unistd.h>

#define LOG_FILE "system_log.txt"
#define BUFFER_SIZE 256
#define KEYWORDS_COUNT 4

const char *keywords[KEYWORDS_COUNT] = { "ERROR", "FAIL", "DENY", "ILLEGAL" };
const char *reset_color = "\033[0m";
const char *red_color = "\033[31m";
const char *green_color = "\033[32m";
const char *yellow_color = "\033[33m";

void log_alert(const char *message) {
    FILE *alert_file = fopen("alerts.txt", "a");
    if (alert_file == NULL) {
        printf("%sUnable to open alert file!%s\n", red_color, reset_color);
        return;
    }
    fprintf(alert_file, "%s\n", message);
    fclose(alert_file);
}

bool check_keywords(const char *line) {
    for (int i = 0; i < KEYWORDS_COUNT; i++) {
        if (strstr(line, keywords[i]) != NULL) {
            return true;
        }
    }
    return false;
}

void monitor_log_file() {
    FILE *log_file = fopen(LOG_FILE, "r");
    if (log_file == NULL) {
        printf("%sLog file not found!%s\n", red_color, reset_color);
        return;
    }

    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, log_file) != NULL) {
        if (check_keywords(buffer)) {
            printf("%sIntrusion detected: %s%s\n", red_color, buffer, reset_color);
            log_alert(buffer);
        } else {
            printf("%sMonitoring: %s%s", green_color, buffer, reset_color);
        }
        usleep(500000); // Sleep for half a second for visualization
    }

    fclose(log_file);
}

void create_dummy_log() {
    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        printf("%sUnable to create log file!%s\n", red_color, reset_color);
        return;
    }

    fprintf(log_file, "INFO: Server started successfully\n");
    fprintf(log_file, "ERROR: Connection failed\n");
    fprintf(log_file, "INFO: User login successful\n");
    fprintf(log_file, "DENY: Unauthorized access attempt\n");
    fprintf(log_file, "SUCCESS: File uploaded\n");

    fclose(log_file);
}

int main() {
    printf("%s*** Intrusion Detection System ***%s\n", yellow_color, reset_color);
    create_dummy_log();
    printf("%sMonitoring the log file for intrusions...%s\n", yellow_color, reset_color);
    monitor_log_file();

    return 0;
}

