    char filename[100];
    printf("Enter filename: ");
    scanf("%s", filename);

    int num_word_counts = 10;
    WordCount word_counts[num_word_counts];
    initialize(filename, word_counts, num_word_counts);

    print_word_counts(word_counts, num_word_counts);

    return 0;
}

