#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_INvaders 10
#define invaders_width 5
#define invaders_height 3

typedef struct invader {
  int x;
  int y;
  int direction;
  int speed;
} invader;

invader invaders[MAX_INvaders];

void initialize_invaders() {
  for (int i = 0; i < MAX_INvaders; i++) {
    invaders[i].x = 0;
    invaders[i].y = 0;
    invaders[i].direction = 0;
    invaders[i].speed = 1;
  }
}

void move_invaders() {
  for (int i = 0; i < MAX_INvaders; i++) {
    switch (invaders[i].direction) {
      case 0:
        invaders[i].x++;
        break;
      case 1:
        invaders[i].x--;
        break;
      case 2:
        invaders[i].y++;
        break;
      case 3:
        invaders[i].y--;
        break;
    }

    if (invaders[i].x >= invaders_width - 1) {
      invaders[i].direction = 1;
    } else if (invaders[i].x <= 0) {
      invaders[i].direction = 0;
    }

    if (invaders[i].y >= invaders_height - 1) {
      invaders[i].direction = 3;
    } else if (invaders[i].y <= 0) {
      invaders[i].direction = 2;
    }
  }
}

void draw_invaders() {
  for (int i = 0; i < MAX_INvaders; i++) {
    printf("%c ", invaders[i].x + 1);
  }
  printf("\n");
}

int main() {
  initialize_invaders();

  while (1) {
    move_invaders();
    draw_invaders();

    if (invaders[0].y >= invaders_height - 1) {
      printf("Game Over!\n");
      break;
    }
  }

  return 0;
}

