#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/ip.h>
#include <arpa/inet.h>

#define PORT_RANGE 1024-65535

// Declare global variables
int sock;
struct sockaddr_in server, client;
int client_address_len = sizeof(struct sockaddr_in);

// Define a function to handle incoming connections
void handle_connection(int client_sock) {
  char buffer[1024];
  int bytes_read;

  // Read data from the client
  bytes_read = recv(client_sock, buffer, 1024, 0);

  // Check if the client sent a valid command
  if (bytes_read > 0) {
    if (strcmp(buffer, "HELLO") == 0) {
      // Send a response back to the client
      send(client_sock, "Hello, client! How may I assist you?\n", 256, 0);
    } else if (strcmp(buffer, "GET /") == 0) {
      // Send the index.html file to the client
      send(client_sock, "HTTP/1.1 200 OK\nContent-Type: text/html\nContent-Length: 1024\n\n<html><body>Hello, world!</body></html>", 1024, 0);
    } else {
      // If the client sends an invalid command, disconnect the connection
      close(client_sock);
    }
  }
}

// Define a function to handle incoming socket connections
void listen_for_connections() {
  int client_sock;

  // Listen for incoming connections on port 8080
  listen(sock, 3);

  // Accept an incoming connection
  client_sock = accept(sock, (struct sockaddr *)&client, &client_address_len);

  // Handle the incoming connection
  handle_connection(client_sock);

  // Close the client socket when done
  close(client_sock);
}

int main() {
  // Create a socket
  sock = socket(AF_INET, SOCK_STREAM, 0);

  // Set the address and port number for the server
  server.sin_family = AF_INET;
  server.sin_addr.s_addr = INADDR_ANY;
  server.sin_port = htons(8080);

  // Bind the socket to the address and port
  bind(sock, (struct sockaddr *)&server, sizeof(server));

  // Listen for incoming connections
  listen(sock, 3);

  // Handle incoming connections forever
  while (1) {
    listen_for_connections();
  }

  return 0;
}

