#include <math.h>

#define WIDTH 800
#define HEIGHT 600
#define MAX_ITERATIONS 1000
#define ZOOM 1.5
#define COLOR_MAX 255
#define COLOR_MIN 0

// Function to generate a random color
int rand_color() {
    return rand() % (COLOR_MAX - COLOR_MIN) + COLOR_MIN;
}

// Function to generate fractal
void fractal(int x, int y, int iter) {
    if (iter == MAX_ITERATIONS) {
        printf("%d,%d:%d\n", x, y, rand_color());
        return;
    }

    double real = x / WIDTH * 4 - 2;
    double imag = y / HEIGHT * 4 - 2;

    double zx = 0, zy = 0, temp;
    for (int i = 0; i < iter; i++) {
        temp = zx * zx - zy * zy + real;
        zy = 2 * zx * zy + imag;
        zx = temp;
    }

    fractal(x, y, iter + 1);
    fractal(x + WIDTH / 2, y, iter + 1);
    fractal(x - WIDTH / 2, y, iter + 1);
    fractal(x, y + HEIGHT / 2, iter + 1);
    fractal(x, y - HEIGHT / 2, iter + 1);
}

