        0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 
        0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 
        0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070, 
        0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 
        0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3, 
        0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 
        0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2
    };

    uint32_t w[64];
    uint32_t a, b, c, d, e, f, g, h, i, j, t1, t2;

    for (i = 0; i < BLOCK_SIZE / 4; i++) {
        w[i] = ((uint32_t)ctx->buffer[i * 4 + 0] << 24) |
                ((uint32_t)ctx->buffer[i * 4 + 1] << 16) |
                ((uint32_t)ctx->buffer[i * 4 + 2] << 8) |
                ((uint32_t)ctx->buffer[i * 4 + 3]);
    }

    for (i = 16; i < 64; i++) {
        uint32_t s0 = (w[i - 15] >> 7) | (w[i - 15] << 25);
        uint32_t s1 = (w[i - 15] >> 18) | (w[i - 15] << 14);
        uint32_t s2 = (w[i - 15] >> 3);
        uint32_t s3 = (w[i - 15] << 29);

        uint32_t s4 = (w[i - 2] >> 17) | (w[i - 2] << 15);
        uint32_t s5 = (w[i - 2] >> 19) | (w[i - 2] << 13);
        uint32_t s6 = (w[i - 2] >> 10);
        uint32_t s7 = (w[i - 2] << 22);

        w[i] = w[i - 16] + s0 + s1 + s2 + s3 + w[i - 7] + s4 + s5 + s6 + s7;
    }

    a = ctx->state[0];
    b = ctx->state[1];
    c = ctx->state[2];
    d = ctx->state[3];
    e = ctx->state[4];
    f = ctx->state[5];
    g = ctx->state[6];
    h = ctx->state[7];

    for (i = 0; i < 64; i++) {
        uint32_t s0 = (a >> 2) | (a << 30);
        uint32_t s1 = (a >> 13) | (a << 19);
        uint32_t s2 = (a >> 22) | (a << 10);
        uint32_t s3 = (a & b) ^ (a & c) ^ (b & c);
        uint32_t s4 = (s0 & s1) ^ (s0 & s2) ^ (s1 & s2);
        uint32_t t3 = h + s4 + k[i] + w[i];
        uint32_t t4 = s3 + s4;

        h = g;
        g = f;
        f = e;
        e = d + t3;
        d = c;
        c = b;
        b = a;
        a = t3 + t4;
    }

    ctx->state[0] += a;
    ctx->state[1] += b;
    ctx->state[2] += c;
    ctx->state[3] += d;
    ctx->state[4] += e;
    ctx->state[5] += f;
    ctx->state[6] += g;
    ctx->state[7] += h;

    memset(ctx->buffer, 0, BLOCK_SIZE);
}

void sha256_init(sha256_ctx *ctx) {
    ctx->state[0] = 0x6a09e667;
    ctx->state[1] = 0xbb67ae85;
    ctx->state[2] = 0x3c6ef372;
    ctx->state[3] = 0xa54ff53a;
    ctx->state[4] = 0x510e527f;
    ctx->state[5] = 0x9b05688c;
    ctx->state[6] = 0x1f83d9ab;
    ctx->state[7] = 0x5be0cd19;

    ctx->size = 0;
    ctx->total_size = 0;
}

void sha256_update(sha256_ctx *ctx, const unsigned char *data, uint32_t len) {
    uint32_t i;

    for (i = 0; i < len; i++) {
        ctx->buffer[ctx->size++] = data[i];

        if (ctx->size == BLOCK_SIZE) {
            sha256_transform(ctx);
            ctx->total_size += BLOCK_SIZE;
            ctx->size = 0;
        }
    }
}

void sha256_final(sha256_ctx *ctx, unsigned char *hash) {
    uint32_t i;

    i = ctx->size;

    // Pad whatever data is left in the block.
    if (ctx->size < BLOCK_SIZE - 8) {
        ctx->buffer[i++] = 0x80;

        while (i < BLOCK_SIZE - 8) {
            ctx->buffer[i++] = 0x00;
        }
    } else {
        ctx->buffer[i++] = 0x80;

        while (i < BLOCK_SIZE) {
            ctx->buffer[i++] = 0x00;
        }

        sha256_transform(ctx);
        memset(ctx->buffer, 0, BLOCK_SIZE - 8);
    }

    // Append total message size as 64-bit big-endian integer.
    ctx->total_size += ctx->size * 8;
    memset(&ctx->buffer[BLOCK_SIZE - 8], 0, 8);
    ctx->buffer[BLOCK_SIZE - 8] = (ctx->total_size >> 56) & 0xff;
    ctx->buffer[BLOCK_SIZE - 7] = (ctx->total_size >> 48) & 0xff;
    ctx->buffer[BLOCK_SIZE - 6] = (ctx->total_size >> 40) & 0xff;
    ctx->buffer[BLOCK_SIZE - 5] = (ctx->total_size >> 32) & 0xff;
    ctx->buffer[BLOCK_SIZE - 4] = (ctx->total_size >> 24) & 0xff;
    ctx->buffer[BLOCK_SIZE - 3] = (ctx->total_size >> 16) & 0xff;
    ctx->buffer[BLOCK_SIZE - 2] = (ctx->total_size >> 8) & 0xff;
    ctx->buffer[BLOCK_SIZE - 1] = ctx->total_size & 0xff;
    sha256_transform(ctx);

    // Compose final hash.
    for (i = 0; i < HASH_SIZE; i++) {
        hash[i] = (ctx->state[i / 4] >> (24 - 8 * (i % 4))) & 0xff;
    }
}

int main() {
    sha256_ctx ctx;
    char input[512];
    printf("Enter the string to generate its hash:\n");
    fgets(input, 512, stdin);
    sha256_init(&ctx);
    sha256_update(&ctx, input, strlen(input) - 1);
    unsigned char hash[HASH_SIZE];
    sha256_final(&ctx, &hash[0]);

    printf("Hash: ");
    for (int i = 0; i < sizeof(hash); i++) {
        printf("%02x", hash[i]);
    }
    printf("\n");

    return 0;
}

