//LLAMA2-13B DATASET v1.0 Category: Game of Life ; Style: retro
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define CELL_WIDTH 10
#define CELL_HEIGHT 10
#define GENERATIONS 100

// Define the colors used in the game
#define COLOR_ALIVE 7
#define COLOR_DEAD 0

// Define the game's grid size
#define GRID_SIZE (CELL_WIDTH * CELL_HEIGHT)

// Define the game's initial state
#define INITIAL_STATE (1 << (CELL_WIDTH - 1))

// Function to draw the game's grid
void draw_grid(char *grid) {
  int i, j;

  for (i = 0; i < CELL_HEIGHT; i++) {
    for (j = 0; j < CELL_WIDTH; j++) {
      if (grid[i * CELL_WIDTH + j] == COLOR_ALIVE) {
        printf("   %c", 'O');
      } else {
        printf("   %c", ' ');
      }
    }
    printf("\n");
  }
}

// Function to apply the game of life rules
void apply_rules(char *grid) {
  int i, j, alive_neighbors = 0;

  for (i = 0; i < CELL_HEIGHT; i++) {
    for (j = 0; j < CELL_WIDTH; j++) {
      if (grid[i * CELL_WIDTH + j] == COLOR_ALIVE) {
        // Count the number of alive neighbors
        alive_neighbors += (i - 1 < 0 || grid[i * CELL_WIDTH + j - 1] != COLOR_ALIVE)
                          + (i + 1 >= CELL_HEIGHT || grid[i * CELL_WIDTH + j + 1] != COLOR_ALIVE)
                          + (j - 1 < 0 || grid[i * CELL_WIDTH + j - 1] != COLOR_ALIVE)
                          + (j + 1 >= CELL_WIDTH || grid[i * CELL_WIDTH + j + 1] != COLOR_ALIVE);

        // Apply the rules
        if (alive_neighbors < 2 || alive_neighbors > 3) {
          grid[i * CELL_WIDTH + j] = COLOR_DEAD;
        } else {
          grid[i * CELL_WIDTH + j] = COLOR_ALIVE;
        }
      }
    }
  }
}

int main() {
  // Initialize the game's grid
  char grid[GRID_SIZE];
  for (int i = 0; i < GRID_SIZE; i++) {
    grid[i] = INITIAL_STATE;
  }

  // Draw the game's grid
  draw_grid(grid);

  // Apply the game of life rules for GENERATIONS generations
  for (int generation = 0; generation < GENERATIONS; generation++) {
    apply_rules(grid);
  }

  // Draw the final state of the game
  draw_grid(grid);

  return 0;
}

//Falcon-180B DATASET v1.0 Category: Network Packet Monitoring ; Style: artistic
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pcap.h>
#include <arpa/inet.h>

#define MAX_PKT_SIZE 1024
#define MAX_PKT_COUNT 1000

typedef struct packet_info {
    u_char *data;
    int size;
} PacketInfo;

void handle_packet(u_char *args, const struct pcap_pkthdr *header, const u_char *packet) {
    PacketInfo *packet_info = (PacketInfo *) args;
    memcpy(packet_info->data, packet, header->len);
    packet_info->size = header->len;
}

int main() {
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle;
    char filter_str[] = "tcp";
    struct bpf_program filter;
    PacketInfo packet_info;

    // Open the capture device
    handle = pcap_open_live("eth0", BUFSIZ, 1, 0, errbuf);
    if (handle == NULL) {
        fprintf(stderr, "Error opening capture device: %s\n", errbuf);
        exit(1);
    }

    // Compile the filter expression
    if (pcap_compile(handle, &filter, filter_str, 0, 0)!= 0) {
        fprintf(stderr, "Error compiling filter expression: %s\n", pcap_geterr(handle));
        exit(1);
    }

    // Set the filter for the capture device
    if (pcap_setfilter(handle, &filter)!= 0) {
        fprintf(stderr, "Error setting filter: %s\n", pcap_geterr(handle));
        exit(1);
    }

    // Allocate memory for the packet info struct
    packet_info.data = (u_char *) malloc(MAX_PKT_SIZE);
    packet_info.size = 0;

    // Start the capture loop
    pcap_loop(handle, -1, handle_packet, (u_char *) &packet_info);

    // Clean up
    pcap_freecode(&filter);
    pcap_close(handle);
    free(packet_info.data);

    return 0;
}

