#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_WIDTH 50
#define MAX_HEIGHT 20

#define invader_width 3
#define invader_height 3
#define invader_speed 5

#define bullet_width 2
#define bullet_height 2
#define bullet_speed 10

#define score_width 20
#define score_height 2

typedef struct invader {
    int x;
    int y;
    int direction;
} invader_t;

typedef struct bullet {
    int x;
    int y;
    int direction;
} bullet_t;

void initialize_invaders(invader_t *invaders, int num_invaders) {
    for (int i = 0; i < num_invaders; i++) {
        invaders[i].x = i * invader_width;
        invaders[i].y = MAX_HEIGHT - 1;
        invaders[i].direction = 1;
    }
}

void move_invaders(invader_t *invaders, int num_invaders) {
    for (int i = 0; i < num_invaders; i++) {
        switch (invaders[i].direction) {
            case 1:
                invaders[i].x++;
                break;
            case -1:
                invaders[i].x--;
                break;
        }

        if (invaders[i].x >= MAX_WIDTH - invader_width || invaders[i].x <= 0) {
            invaders[i].direction *= -1;
        }
    }
}

void initialize_bullets(bullet_t *bullets, int num_bullets) {
    for (int i = 0; i < num_bullets; i++) {
        bullets[i].x = -1;
        bullets[i].y = -1;
        bullets[i].direction = 0;
    }
}

void move_bullets(bullet_t *bullets, int num_bullets) {
    for (int i = 0; i < num_bullets; i++) {
        bullets[i].x += bullets[i].direction * bullet_speed;

        if (bullets[i].x >= MAX_WIDTH || bullets[i].x <= 0) {
            bullets[i].direction *= -1;
        }
    }
}

void draw_invaders(invader_t *invaders, int num_invaders) {
    for (int i = 0; i < num_invaders; i++) {
        printf(" ");
        for (int j = 0; j < invader_height; j++) {
            printf("%c", invaders[i].x + 1 + j);
        }
        printf("\n");
    }
}

void draw_bullets(bullet_t *bullets, int num_bullets) {
    for (int i = 0; i < num_bullets; i++) {
        printf(" ");
        for (int j = 0; j < bullet_height; j++) {
            printf("%c", bullets[i].x + 1 + j);
        }
        printf("\n");
    }
}

void draw_score(int score) {
    printf("Score: %d", score);
}

int main() {
    int score = 0;
    int num_invaders = 10;
    invader_t invaders[num_invaders];
    bullet_t bullets[num_invaders];

    initialize_invaders(invaders, num_invaders);
    initialize_bullets(bullets, num_invaders);

    while (1) {
        move_invaders(invaders, num_invaders);
        move_bullets(bullets, num_invaders);

        draw_invaders(invaders, num_invaders);
        draw_bullets(bullets, num_invaders);
        draw_score(score);

        if (invaders[0].y >= MAX_HEIGHT - invader_height) {
            printf("Game Over!");
            break;
        }

        if (invaders[num_invaders - 1].x >= MAX_WIDTH - invader_width) {
            score++;
            initialize_invaders(invaders, num_invaders);
        }

        sleep(0.1);
    }

    return 0;
}

