//Falcon-180B DATASET v1.0 Category: Traffic Light Controller ; Style: synchronous
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>

#define RED_LIGHT_DURATION 10 // seconds
#define YELLOW_LIGHT_DURATION 3 // seconds
#define GREEN_LIGHT_DURATION 20 // seconds
#define TOTAL_CYCLE_DURATION (RED_LIGHT_DURATION + YELLOW_LIGHT_DURATION + GREEN_LIGHT_DURATION)
#define SECONDS_PER_MINUTE 60

enum traffic_light_state {
    RED_LIGHT,
    YELLOW_LIGHT,
    GREEN_LIGHT
};

void signal_handler(int signum) {
    if (signum == SIGALRM) {
        switch_traffic_light_state();
    }
}

void switch_traffic_light_state() {
    static enum traffic_light_state current_state = RED_LIGHT;
    static time_t last_switch_time = 0;
    time_t current_time = time(NULL);

    if (last_switch_time == 0) {
        last_switch_time = current_time;
    }

    if (current_state == RED_LIGHT) {
        if (current_time - last_switch_time >= RED_LIGHT_DURATION) {
            current_state = YELLOW_LIGHT;
            last_switch_time = current_time;
        }
    } else if (current_state == YELLOW_LIGHT) {
        if (current_time - last_switch_time >= YELLOW_LIGHT_DURATION) {
            current_state = GREEN_LIGHT;
            last_switch_time = current_time;
        }
    } else if (current_state == GREEN_LIGHT) {
        if (current_time - last_switch_time >= GREEN_LIGHT_DURATION) {
            current_state = RED_LIGHT;
            last_switch_time = current_time;
        }
    }

    printf("Current traffic light state: %s\n", current_state == RED_LIGHT? "Red" :
            current_state == YELLOW_LIGHT? "Yellow" : "Green");
}

int main() {
    signal(SIGALRM, signal_handler);
    alarm(TOTAL_CYCLE_DURATION);

    while (1) {
        sleep(SECONDS_PER_MINUTE);
    }

    return 0;
}

//FormAI DATASET v1.0 Category: Bitwise operations ; Style: artistic
#include <stdio.h>

// Function to check if a number is odd or even
int is_even(int x) {
    return !(x & 1);
}

// Function to count the number of set bits in an integer
int count_set_bits(int x) {
    int count = 0;
    while(x) {
        count += x & 1;
        x >>= 1;
    }
    return count;
}

int main() {
    printf("Enter two numbers: ");

    int a, b;
    scanf("%d %d", &a, &b);

    // Perform bitwise AND operation
    int and_result = a & b;
    printf("%d & %d = %d\n", a, b, and_result);

    // Perform bitwise OR operation
    int or_result = a | b;
    printf("%d | %d = %d\n", a, b, or_result);

    // Perform bitwise XOR operation
    int xor_result = a ^ b;
    printf("%d ^ %d = %d\n", a, b, xor_result);

    // Perform bitwise NOT operation on a
    int not_a = ~a;
    printf("~%d = %d\n", a, not_a);

    // Perform bitwise left shift operation on b
    int b_shifted = b << 2;
    printf("%d << 2 = %d\n", b, b_shifted);

    // Perform bitwise right shift operation on a
    int a_shifted = a >> 1;
    printf("%d >> 1 = %d\n", a, a_shifted);

    printf("Is %d even? %s\n", a, is_even(a) ? "Yes": "No");
    printf("Is %d even? %s\n", b, is_even(b) ? "Yes": "No");

    printf("Number of set bits in %d = %d\n", a, count_set_bits(a));
    printf("Number of set bits in %d = %d\n", b, count_set_bits(b));

    return 0;
}

