                        guest_address,
                        guest_phone,
                        room_number,
                        guest_check_in_date,
                        guest_check_out_date
                    };
                    guests[room_number - 1] = new_guest;

                    // Mark the room as unavailable
                    rooms[room_number - 1].room_availability = 0;

                    // Confirm the booking
                    printf("\nYour booking has been confirmed.\n");
                } else {
                    // Display an error message
                    printf("\nSorry, the room is not available.\n");
                }
                break;
            case 3:
                // Check out a guest
                int guest_room_number;
                printf("\nEnter the room number of the guest you want to check out: ");
                scanf("%d", &guest_room_number);

                // Find the guest by their room number
                int guest_index = -1;
                for (int i = 0; i < MAX_ROOMS; i++) {
                    if (guests[i].guest_room_number == guest_room_number) {
                        guest_index = i;
