//GEMINI-pro DATASET v1.0 Category: Public-Key Algorithm Implementation ; Style: scalable
#include <openssl/ec.h>
#include <openssl/ecdsa.h>
#include <openssl/bn.h>
#include <openssl/pem.h>
#include <openssl/err.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    EC_KEY *key;
    ECDSA_SIG *signature;
} ECDSAContext;

ECDSAContext *ecdsa_new() {
    ECDSAContext *ctx = malloc(sizeof(ECDSAContext));
    if (!ctx) {
        return NULL;
    }

    ctx->key = EC_KEY_new();
    if (!ctx->key) {
        free(ctx);
        return NULL;
    }

    if (EC_KEY_set_group(ctx->key, EC_GROUP_new_by_curve_name(NID_secp256k1)) != 1) {
        EC_KEY_free(ctx->key);
        free(ctx);
        return NULL;
    }

    if (EC_KEY_generate_key(ctx->key) != 1) {
        EC_KEY_free(ctx->key);
        free(ctx);
        return NULL;
    }

    ctx->signature = ECDSA_SIG_new();
    if (!ctx->signature) {
        EC_KEY_free(ctx->key);
        free(ctx);
        return NULL;
    }

    return ctx;
}

void ecdsa_free(ECDSAContext *ctx) {
    if (ctx) {
        EC_KEY_free(ctx->key);
        ECDSA_SIG_free(ctx->signature);
        free(ctx);
    }
}

int ecdsa_sign(ECDSAContext *ctx, const unsigned char *data, size_t data_len) {
    if (!ctx || !data) {
        return -1;
    }

    int ret = ECDSA_sign(0, data, data_len, ctx->signature, NULL, ctx->key);
    if (ret != 1) {
        return -1;
    }

    return 0;
}

int ecdsa_verify(ECDSAContext *ctx, const unsigned char *data, size_t data_len, const unsigned char *signature, size_t signature_len) {
    if (!ctx || !data || !signature) {
        return -1;
    }

    int ret = ECDSA_verify(0, data, data_len, signature, signature_len, ctx->key);
    if (ret != 1) {
        return -1;
    }

    return 0;
}

int main() {
    ECDSAContext *ctx = ecdsa_new();
    if (!ctx) {
        fprintf(stderr, "Error creating ECDSA context\n");
        return EXIT_FAILURE;
    }

    const char *data = "This is a test message";
    size_t data_len = strlen(data);

    int ret = ecdsa_sign(ctx, (const unsigned char *)data, data_len);
    if (ret != 0) {
        fprintf(stderr, "Error signing data\n");
        ecdsa_free(ctx);
        return EXIT_FAILURE;
    }

    int verified = ecdsa_verify(ctx, (const unsigned char *)data, data_len, (const unsigned char *)ctx->signature, ECDSA_size(ctx->key));
    if (verified != 1) {
        fprintf(stderr, "Error verifying signature\n");
        ecdsa_free(ctx);
        return EXIT_FAILURE;
    }

    printf("Signature verified successfully\n");

    ecdsa_free(ctx);

    return EXIT_SUCCESS;
}

