#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <math.h>

// Function to calculate the similarity between two strings
float similarity(char* str1, char* str2) {
    int len1 = strlen(str1);
    int len2 = strlen(str2);
    int i, j;
    float similarityScore = 0.0;

    // Calculate the number of matching characters
    for (i = 0; i < len1; i++) {
        for (j = 0; j < len2; j++) {
            if (tolower(str1[i]) == tolower(str2[j])) {
                similarityScore++;
            }
        }
    }

    // Normalize the similarity score
    similarityScore /= (len1 * len2);

    return similarityScore;
}

// Function to print the top 10 most similar words
void printTopSimilarWords(char* sentence, char* word, float similarityThreshold) {
    int numWords = strlen(sentence);
    char* wordList[numWords];
    float similarityScores[numWords];
    int i, j;

    for (i = 0; i < numWords; i++) {
        wordList[i] = sentence + i * 2;
        similarityScores[i] = similarity(word, wordList[i]);
    }

    // Sort the words by similarity score
    for (i = 0; i < numWords - 1; i++) {
        for (j = 0; j < numWords - i - 1; j++) {
            if (similarityScores[j] > similarityScores[j + 1]) {
                char* temp = wordList[j];
                wordList[j] = wordList[j + 1];
                wordList[j + 1] = temp;
                float tempScore = similarityScores[j];
                similarityScores[j] = similarityScores[j + 1];
                similarityScores[j + 1] = tempScore;
            }
        }
    }

    int top10Count = 0;
    int numTop10 = 0;
    char* top10List[10];
    for (i = 0; i < numWords; i++) {
        if (similarityScores[i] > similarityThreshold && top10Count < 10) {
            top10List[top10Count] = wordList[i];
            top10Count++;
        }
        if (top10Count == 10) {
            break;
        }
    }

    printf("Top 10 most similar words to '%s':\n", word);
    for (i = 0; i < top10Count; i++) {
        printf("%s (%f)\n", top10List[i], similarityScores[i]);
    }
}

int main() {
    char sentence[] = "The quick brown fox jumps over the lazy dog.";
    char word[] = "fox";
    float similarityThreshold = 0.7;

    printTopSimilarWords(sentence, word, similarityThreshold);

    return 0;
}

