#include <stdio.h>
#include <stdbool.h>
#include <string.h>

typedef struct {
    bool solved;
    int grid[9][9];
} sudoku;

bool isValid(sudoku* sudoku, int row, int col, int num) {
    int i, j;
    for (i = 0; i < 9; i++) {
        for (j = 0; j < 9; j++) {
            if (sudoku->grid[i][j] == num && (i == row || j == col)) {
                return false;
            }
        }
    }
    for (i = 0; i < 9; i++) {
        if (sudoku->grid[i][col] == num || sudoku->grid[row][i] == num) {
            return false;
        }
    }
    for (i = 0; i < 9; i++) {
        if (sudoku->grid[3 * (row / 3) + i / 3][3 * (col / 3) + i % 3] == num) {
            return false;
        }
    }
    return true;
}

void printGrid(sudoku* sudoku) {
    int i, j;
    for (i = 0; i < 9; i++) {
        for (j = 0; j < 9; j++) {
            printf("%d ", sudoku->grid[i][j]);
        }
        printf("\n");
    }
}

bool solveSudoku(sudoku* sudoku) {
    bool solved = false;
    int i, j;
    for (i = 0; i < 9; i++) {
        for (j = 0; j < 9; j++) {
            if (!sudoku->grid[i][j]) {
                for (int num = 1; num <= 9; num++) {
                    if (isValid(sudoku, i, j, num)) {
                        sudoku->grid[i][j] = num;
                        if (solveSudoku(sudoku)) {
                            solved = true;
                            break;
                        }
                        sudoku->grid[i][j] = 0;
                    }
                }
                if (solved) {
                    break;
                }
            }
        }
        if (solved) {
            break;
        }
    }
    sudoku->solved = solved;
    return solved;
}

int main() {
    sudoku sudoku;
    sudoku.solved = false;
    printGrid(&sudoku);
    solveSudoku(&sudoku);
    if (sudoku.solved) {
        printGrid(&sudoku);
    } else {
        printf("No solution exists\n");
    }
    return 0;
}

