    for (i = 0; i < MAX_VAR; i++) {
        if (expression[i] == var[i].name) {
            push(var[i].value);
            continue;
        }
    }

    for (i = 0; i < len; i++) {
        op = expression[i];

        num1 = pop();
        num2 = pop();

        switch (op) {
            case '+':
                push(num2 + num1);
                break;
            case '-':
                push(num2 - num1);
                break;
            case '*':
                push(num2 * num1);
                break;
            case '/':
                push(num2 / num1);
                break;
            case '^':
                push(pow(num2, num1));
                break;
            case 's': // sin
                push(sin(num1 * M_PI / 180));
                break;
            case 'c': // cos
                push(cos(num1 * M_PI / 180));
                break;
            case 't': // tan
                push(tan(num1 * M_PI / 180));
                break;
            case 'e': // exp
                push(exp(num1));
                break;
            case 'l': // log
                push(log(num1));
                break;
            case '=': // assign
                var[expression[i + 1] - 'A'].value = num1;
                i++;
                break;
            default:
                printf("Error: Invalid operator %c\n", op);
                exit(1);
        }
    }

    result = pop();
    return result;
}

int main() {
    char expression[MAX_SIZE];
    int i;

    init_variables();

    printf("Enter the expression: ");
    scanf("%s", expression);

    double result = eval_expression(expression);

    printf("Result: %.2lf\n", result);

    return 0;
}

