#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <string.h>
#include <ctype.h>

#define MAX_LEN 50
#define SHIFTS 16

typedef struct {
    char shape[MAX_LEN];
    float value;
    char unit[MAX_LEN];
} data_t;

void print_shape(data_t *data) {
    int i;
    for (i = 0; i < strlen(data->shape); i++)
        printf("%c", data->shape[i]);
    printf(" %s: %0.2f %s\n", data->unit, data->value, data->unit);
}

void fahrenheit_to_celsius(data_t *data) {
    data->value = (data->value - 32.0) * 5.0 / 9.0;
}

void celsius_to_fahrenheit(data_t *data) {
    data->value = data->value * 9.0 / 5.0 + 32.0;
}

void shift_shape(data_t *data, int direction) {
    int i, j, len;
    char temp;

    len = strlen(data->shape);

    if (direction > 0) {
        for (i = 0; i < len / 2; i++) {
            j = len - i - 1;
            temp = data->shape[i];
            data->shape[i] = data->shape[j];
            data->shape[j] = temp;
        }
    } else {
        for (i = len - 1; i > len / 2; i--) {
            j = i - 1;
            temp = data->shape[i];
            data->shape[i] = data->shape[j];
            data->shape[j] = temp;
        }
    }
}

int main() {
    data_t data;
    int choice, shift_dir;
    char unit[MAX_LEN] = "Fahrenheit";

    strcpy(data.shape, "   _______     ");
    strcpy(data.unit, "Fahrenheit");

    while (1) {
        print_shape(&data);
        printf("Enter temperature value: ");
        scanf("%f", &data.value);

        printf("Convert to Celsius(1) or Fahrenheit(0)? ");
        scanf("%d", &choice);

        if (choice == 1) {
            fahrenheit_to_celsius(&data);
            strcpy(unit, "Celsius");
        } else {
            celsius_to_fahrenheit(&data);
            strcpy(unit, "Fahrenheit");
        }

        printf("Press 1 to shift shape or 0 to exit: ");
        scanf("%d", &shift_dir);

        if (shift_dir == 1) {
            shift_shape(&data, 1);
        } else {
            break;
        }
    }

    return 0;
}

