#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define PORT_RANGE 1024 // range of ports to scan, starting from 1024
#define MAX_HOSTS 100 // maximum number of hosts to scan

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <host_ip>\n", argv[0]);
        return 1;
    }

    // create a socket
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket failed");
        return 1;
    }

    // set the IP address and port number
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(80); // default port 80
    inet_pton(AF_INET, argv[1], &server_addr.sin_addr);

    // set up the buffer for the port scan results
    char buffer[256];

    // scan the specified host for open ports
    for (int i = 1; i <= PORT_RANGE; i++) {
        // create a socket for the current port
        int port_sock = socket(AF_INET, SOCK_STREAM, 0);
        if (port_sock < 0) {
            perror("socket failed");
            continue;
        }

        // connect to the specified host and port
        connect(port_sock, (struct sockaddr *)&server_addr, sizeof(server_addr));

        // send a SYN packet to the server to check for open ports
        send(port_sock, "X", 1, 0);

        // receive the response from the server
        recv(port_sock, buffer, 256, 0);

        // check if the port is open or not
        if (buffer[0] == '1') {
            printf("Port %d is open on %s\n", i, argv[1]);
        }

        // close the socket
        close(port_sock);
    }

    // close the main socket
    close(sock);

    return 0;
}

