//GPT-4o-mini DATASET v1.0 Category: Graph representation ; Style: realistic
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_VERTICES 100
#define INF 99999999

typedef struct {
    int vertices;
    int adjMatrix[MAX_VERTICES][MAX_VERTICES];
    char labels[MAX_VERTICES][20];
} Graph;

void initGraph(Graph *g, int vertices) {
    g->vertices = vertices;
    for (int i = 0; i < vertices; i++) {
        for (int j = 0; j < vertices; j++) {
            if (i == j) {
                g->adjMatrix[i][j] = 0; // distance to self is 0
            } else {
                g->adjMatrix[i][j] = INF; // initially set to infinity
            }
        }
    }
}

void addVertex(Graph *g, int index, const char *label) {
    if (index < g->vertices) {
        strncpy(g->labels[index], label, 20);
    }
}

void addEdge(Graph *g, int from, int to, int weight) {
    if (from < g->vertices && to < g->vertices) {
        g->adjMatrix[from][to] = weight;
        g->adjMatrix[to][from] = weight; // for undirected graph
    }
}

void printGraph(Graph *g) {
    printf("Graph Adjacency Matrix:\n");
    for (int i = 0; i < g->vertices; i++) {
        for (int j = 0; j < g->vertices; j++) {
            if (g->adjMatrix[i][j] == INF) {
                printf("INF\t");
            } else {
                printf("%d\t", g->adjMatrix[i][j]);
            }
        }
        printf("\n");
    }
}

void dijkstra(Graph *g, int start) {
    int distance[MAX_VERTICES];
    int visited[MAX_VERTICES];

    for (int i = 0; i < g->vertices; i++) {
        distance[i] = INF;
        visited[i] = 0;
    }

    distance[start] = 0;

    for (int i = 0; i < g->vertices - 1; i++) {
        int min = INF, minIndex;

        for (int j = 0; j < g->vertices; j++) {
            if (!visited[j] && distance[j] <= min) {
                min = distance[j];
                minIndex = j;
            }
        }

        visited[minIndex] = 1;

        for (int k = 0; k < g->vertices; k++) {
            if (!visited[k] && g->adjMatrix[minIndex][k] && 
                distance[minIndex] != INF && 
                distance[minIndex] + g->adjMatrix[minIndex][k] < distance[k]) {
                distance[k] = distance[minIndex] + g->adjMatrix[minIndex][k];
            }
        }
    }

    printf("Shortest distances from vertex %d (%s):\n", start, g->labels[start]);
    for (int i = 0; i < g->vertices; i++) {
        if (distance[i] == INF) {
            printf("To vertex %d (%s): INF\n", i, g->labels[i]);
        } else {
            printf("To vertex %d (%s): %d\n", i, g->labels[i], distance[i]);
        }
    }
}

int main() {
    Graph g;
    initGraph(&g, 5);

    addVertex(&g, 0, "A");
    addVertex(&g, 1, "B");
    addVertex(&g, 2, "C");
    addVertex(&g, 3, "D");
    addVertex(&g, 4, "E");

    addEdge(&g, 0, 1, 10);
    addEdge(&g, 0, 2, 3);
    addEdge(&g, 1, 2, 1);
    addEdge(&g, 1, 3, 2);
    addEdge(&g, 2, 1, 4);
    addEdge(&g, 2, 3, 8);
    addEdge(&g, 2, 4, 2);
    addEdge(&g, 3, 4, 7);
    addEdge(&g, 4, 3, 9);

    printGraph(&g);
    dijkstra(&g, 0);

    return 0;
}

