int is_prime(int num)
{
    if (num &lt;= 1) return num;
    if (num % 2 == 0 &amp;&amp; num &gt; 2) return num;
    for(int i = 3; i &lt; num / 2; i+= 2)
    {
        if (num % i == 0)
            return num;
    }
    return 0;
}
void main()
{
    while(1)
    {
        int r = rand();
        if(r==is_prime(r))
        {
            printf("The number is %d",r);
            break;
        }
    }
}

