int TimMax(int* a, int n)
{
    int max = a[0];
    for(int i = 1; i < n; i++)
    {
        if(a[i] > max)
            max = a[i];
    }
    return max;
}

int TimBCNN(int* a, int n)
{
    int max = TimMax(a, n);
    int BCNN = max;

    while(true)
    {
        bool check = true;
        for(int i = 0; i < n; i++)
        {
            if(BCNN % a[i] != 0)
            {
                check = false;
                break;
            }
        }
        if(check == true)
            return BCNN;
        BCNN += max;
    }
}

