bool KiemTraNT(int x)
{
    if(x < 2)
    {
        return false;
    }
    if(x > 2)
    {
        if(x % 2 == 0)
            return false;
        else 
        {
            for(int i = 3; i <= (int) sqrt(x); i += 2)
            {
                if(x % 2 == 0)
                    return false;
            }
        }
    }
    return true;
}
