//Falcon-180B DATASET v1.0 Category: Password Strength Checker ; Style: future-proof
#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define PASSWORD_LENGTH 8
#define PASSWORD_MIN_LENGTH 6
#define PASSWORD_MAX_LENGTH 20
#define PASSWORD_HAS_LOWER 1
#define PASSWORD_HAS_UPPER 2
#define PASSWORD_HAS_NUMBER 4
#define PASSWORD_HAS_SPECIAL 8

#define PASSWORD_WEAK 0
#define PASSWORD_MEDIUM 1
#define PASSWORD_STRONG 2

int password_strength(char *password) {
    int length = strlen(password);
    if (length < PASSWORD_MIN_LENGTH) {
        return PASSWORD_WEAK;
    }
    if (length > PASSWORD_MAX_LENGTH) {
        return PASSWORD_WEAK;
    }
    int has_lower = 0;
    int has_upper = 0;
    int has_number = 0;
    int has_special = 0;
    for (int i = 0; i < length; i++) {
        char c = tolower(password[i]);
        if (isalpha(c)) {
            has_lower |= PASSWORD_HAS_LOWER;
            has_upper |= PASSWORD_HAS_UPPER;
        }
        if (isdigit(c)) {
            has_number |= PASSWORD_HAS_NUMBER;
        }
        if (!isalnum(c)) {
            has_special |= PASSWORD_HAS_SPECIAL;
        }
    }
    int score = 0;
    if (has_lower) {
        score += PASSWORD_HAS_LOWER;
    }
    if (has_upper) {
        score += PASSWORD_HAS_UPPER;
    }
    if (has_number) {
        score += PASSWORD_HAS_NUMBER;
    }
    if (has_special) {
        score += PASSWORD_HAS_SPECIAL;
    }
    if (score >= 3) {
        return PASSWORD_STRONG;
    }
    return PASSWORD_MEDIUM;
}

int main() {
    char password[PASSWORD_LENGTH];
    printf("Enter a password: ");
    fgets(password, PASSWORD_LENGTH, stdin);
    password[strcspn(password, "\n")] = '\0';
    int strength = password_strength(password);
    switch (strength) {
        case PASSWORD_WEAK:
            printf("Weak password\n");
            break;
        case PASSWORD_MEDIUM:
            printf("Medium password\n");
            break;
        case PASSWORD_STRONG:
            printf("Strong password\n");
            break;
    }
    return 0;
}

