{
    FILE* inFile = fopen("Data.txt", "rt");
    FILE* outFile = fopen("Result.txt", "wt");
    long Cnt[sizeBuff];
    if(inFile != NULL)
    {
        countAlphabet(inFile, Cnt);
        if(outFile != NULL)
        {
        showCounts(outFile, Cnt, sizeBuff);
        fclose(outFile);
        }
        fclose(inFile);
    }
    getch();
