#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_LINE 80
#define BUFFER_SIZE 1024

void count_words(char *line, int *word_count);
int main() {
    char line[MAX_LINE];
    char buffer[BUFFER_SIZE];
    FILE *fp;
    int word_count = 0;

    if ((fp = fopen("input.txt", "r")) == NULL) {
        perror("Error opening file");
        return 1;
    }

    while (fgets(line, sizeof(line), fp) != NULL) {
        count_words(line, &word_count);
    }

    fclose(fp);
    printf("Total number of words: %d\n", word_count);

    return 0;
}

void count_words(char *line, int *word_count) {
    int in_word = 0;
    char *token;

    token = strtok(line, " \t\n\r.,;:!?");
    while (token != NULL) {
        (*word_count)++;
        token = strtok(NULL, " \t\n\r.,;:!?");
    }

    if (strlen(line) > 0 && line[strlen(line) - 1] == ' ') {
        (*word_count)++;
    }

    if (strlen(line) > MAX_LINE) {
        char *new_line = (char *)malloc(strlen(line) + 1);
        strncpy(new_line, line, strlen(line));
        new_line[strlen(line)] = '\0';
        count_words(new_line, word_count);
        free(new_line);
    }
}

