//LLAMA2-13B DATASET v1.0 Category: Pattern printing ; Style: distributed
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_CLIENT_CONNECTIONS 5
#define MAX_MESSAGE_LENGTH 1024

int main(void) {
    int sock = 0;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);
    char buffer[MAX_MESSAGE_LENGTH];
    int num_clients = 0;

    // Create a server socket
    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("Socket creation failed");
        exit(1);
    }

    // Set up the server address
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(1234);

    // Bind the server socket to the address and port
    if (bind(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Binding failed");
        exit(1);
    }

    // Listen for incoming connections
    if (listen(sock, MAX_CLIENT_CONNECTIONS) < 0) {
        perror("Listening failed");
        exit(1);
    }

    printf("Server listening on port %d...\n", server_addr.sin_port);

    while (1) {
        // Accept an incoming connection
        client_len = sizeof(client_addr);
        client_addr = (struct sockaddr_in) {
            .sin_family = AF_INET,
            .sin_addr.s_addr = INADDR_ANY,
            .sin_port = 0
        };
        sock = accept(sock, (struct sockaddr *)&client_addr, &client_len);
        if (sock < 0) {
            perror("Accept failed");
            continue;
        }

        printf("Client connected from %s:%d...\n", inet_ntoa(client_addr.sin_addr), ntohs(client_addr.sin_port));

        // Read a message from the client
        read(sock, buffer, MAX_MESSAGE_LENGTH);
        printf("Received message from client: %s\n", buffer);

        // Print a pattern on the client's connection
        for (int i = 0; i < 10; i++) {
            printf("Hello, client %d!%c", num_clients++, ' ');
            sleep(1);
        }

        // Close the client connection
        close(sock);
    }

    return 0;
}

#include<iostream>
using namespace std;
struct node
{
    int data;
    node* left;
    node* right;
};
typedef node* NODE;
NODE get_node(int x)
{
    NODE n=new node;
    if(n==NULL)
        cout<<"Memory Full";
    n->data=x;
    n->left=NULL;
    n->right=NULL;
    return n;
}
NODE insert_node(NODE &parent,int x)
{
    if(parent==NULL)
        parent=get_node(x);
    else
    {
        if(parent->data>x)
            parent->left=insert_node(parent->left,x);
        else if(parent->data<x)
            parent->right=insert_node(parent->right,x);
    }
    return parent;
}
void preorder(NODE p)
{
    if(p!=NULL)
    {
        cout<<p->data<<"->";
        preorder(p->left);
        preorder(p->right);
    }
}
void inorder(NODE p)
{
    if(p!=NULL)
    {
        inorder(p->left);
        cout<<p->data<<"->";
        inorder(p->right);
    }
}
void postorder(NODE p)
{
    if(p!=NULL)
    {
        postorder(p->left);
        postorder(p->right);
        cout<<p->data<<"->";
    }
}
NODE search_node(NODE root,int x)
{
    if(root==NULL)
        return NULL;
    else if(root->data==x)
        return root;
    else
    {
        if(root->data>x)
            return search_node(root->left,x);
        else
            return search_node(root->right,x);
    }
}
NODE largest(NODE root)
{
    if(root==NULL)
        return root;
    else if(root->right==NULL)
        return root;
    else
        return largest(root->right);
}
NODE smallest(NODE root)
{
    if(root==NULL)
        return root;
    if(root->left==NULL)
        return root;
    else
        return smallest(root->left);
}
int no_of_leaves(NODE root,int &i)
{
    if(root==NULL)
        return i;
    else if(root->right==NULL&&root->left==NULL)
        i++;
    else
    {
        i=no_of_leaves(root->left,i);
        i=no_of_leaves(root->right,i);
    }
    return i;
}
int total_nodes(NODE root,int &i)
{
    if(root==NULL)
        return i;
    else
    {
        i=total_nodes(root->left,i);
        i++;
        i=total_nodes(root->right,i);
    }
    return i;
}
