NODE search_least_par(NODE root)
{
    if(root==NULL)
        return root;
    else if(root->left==NULL)
    {
        return root;
    }
    else if(root->left->left==NULL)
    {
        NODE temp=root->left;
        root->left=root->left->right;
        return temp;
    }
    else
        return search_least_par(root->left);
}
NODE del_recur1(NODE root,int x)
{
    if(root==NULL)
        return root;
    else if(x<root->data)
        root->left=del_recur1(root->left,x );
    else if(x>root->data)
        root->right=del_recur1(root->right,x);
    else
    {
        NODE temp;
        if(root->right==NULL)
        {
            temp=root->left;
        }
        else
        {
            temp=search_least_par(root->right);
            temp->left=root->left;
            if(root->right!=temp)
                temp->right=root->right;
        }
        return temp;
    }
    return root;
}
NODE del_node(NODE root,int x)
{
    if(root==NULL)
    {
        cout<<"Empty";
        return root;
    }
    else if(root->data==x&&root->left==NULL&&root->right==NULL)
    {
        delete root;
        return NULL;
    }
    NODE parent=NULL,cur=root,q;
    while(cur!=NULL)
    {
        if(cur->data==x)
            break;
        parent=cur;
        if(cur->data>x)
            cur=cur->left;
        else
            cur=cur->right;
    }
    if(cur==NULL)
    {
        cout<<"Not found";
        return root;
    }
    else if(cur->left==NULL||cur->right==NULL)
    {
        if(cur->right==NULL)
            q=cur->left;
        else if(cur->left==NULL)
            q=cur->right;
        if(parent==NULL)
            root=q;
        else if(parent->left==cur)
            parent->left=q;
        else if(parent->right==cur)
            parent->right=q;
        delete cur;
        return root;
    }
    else
    {
        NODE temp=cur,rp=cur->right;//s=rp->left;
        while(rp->left!=NULL)
        {
            temp=rp;
            rp=rp->left;
        }
        if(temp!=cur)
        {
            temp->left=rp->right;
            rp->right=cur->right;
        }
        rp->left=cur->left;
        if(parent==NULL)
            root=rp;
        else
        {
            if(parent->right==cur)
                parent->right=rp;
            else
                parent->left=rp;
        }
        delete cur;
        return root;
    }
}
