// Geometric algorithms example program
#include <stdio.h>
#include <stdlib.h>
#include <math.h>

// Structures to represent points and lines
typedef struct {
    double x, y;
} point_t;

typedef struct {
    point_t p1, p2;
} line_t;

// Function to calculate the distance between two points
double distance(point_t p1, point_t p2) {
    return sqrt((p1.x - p2.x) * (p1.x - p2.x) + (p1.y - p2.y) * (p1.y - p2.y));
}

// Function to calculate the length of a line segment
double line_length(line_t line) {
    return distance(line.p1, line.p2);
}

// Function to calculate the midpoint of a line segment
point_t line_midpoint(line_t line) {
    point_t midpoint;
    midpoint.x = (line.p1.x + line.p2.x) / 2;
    midpoint.y = (line.p1.y + line.p2.y) / 2;
    return midpoint;
}

// Function to calculate the slope of a line segment
double line_slope(line_t line) {
    return (line.p2.y - line.p1.y) / (line.p2.x - line.p1.x);
}

// Function to calculate the y-intercept of a line segment
double line_yintercept(line_t line) {
    return line.p1.y - line_slope(line) * line.p1.x;
}

// Function to calculate the angle between two lines
double line_angle(line_t line1, line_t line2) {
    return atan2(line_slope(line2) - line_slope(line1), distance(line1.p1, line2.p1));
}

// Function to calculate the intersection point of two lines
point_t line_intersection(line_t line1, line_t line2) {
    point_t intersection;
    intersection.x = (line_yintercept(line2) - line_yintercept(line1)) / (line_slope(line1) - line_slope(line2));
    intersection.y = line_slope(line1) * intersection.x + line_yintercept(line1);
    return intersection;
}

int main() {
    // Create two line segments
    line_t line1 = { {0, 0}, {3, 4} };
    line_t line2 = { {0, 0}, {4, 3} };

    // Calculate the length of each line segment
    double line1_length = line_length(line1);
    double line2_length = line_length(line2);

    // Calculate the midpoint of each line segment
    point_t line1_midpoint = line_midpoint(line1);
    point_t line2_midpoint = line_midpoint(line2);

    // Calculate the slope and y-intercept of each line segment
    double line1_slope = line_slope(line1);
    double line1_yintercept = line_yintercept(line1);
    double line2_slope = line_slope(line2);
    double line2_yintercept = line_yintercept(line2);

    // Calculate the angle between the two lines
    double angle = line_angle(line1, line2);

    // Calculate the intersection point of the two lines
    point_t intersection = line_intersection(line1, line2);

    // Print the results
    printf("Line 1: (%.2f, %.2f) -> (%.2f, %.2f)\n", line1.p1.x, line1.p1.y, line1.p2.x, line1.p2.y);
    printf("Line 2: (%.2f, %.2f) -> (%.2f, %.2f)\n", line2.p1.x, line2.p1.y, line2.p2.x, line2.p2.y);
    printf("Length of line 1: %.2f\n", line1_length);
    printf("Length of line 2: %.2f\n", line2_length);
    printf("Midpoint of line 1: (%.2f, %.2f)\n", line1_midpoint.x, line1_midpoint.y);
    printf("Midpoint of line 2: (%.2f, %.2f)\n", line2_midpoint.x, line2_midpoint.y);
    printf("Slope of line 1: %.2f\n", line1_slope);
    printf("Slope of line 2: %.2f\n", line2_slope);
    printf("Y-intercept of line 1: %.2f\n", line1_yintercept);
    printf("Y-intercept of line 2: %.2f\n", line2_yintercept);
    printf("Angle between lines: %.2f degrees\n", angle * 180 / M_PI);
    printf("Intersection point: (%.2f, %.2f)\n", intersection.x, intersection.y);

    return 0;
}

