#define MAX_INPUT_LEN 100
#define MAX_OUTPUT_LEN 200

// Function prototypes
void printWelcomeMessage();
void translateToCatLanguage(const char *input, char *output);
void meowify(char *word);

int main() {
    printWelcomeMessage();

    char input[MAX_INPUT_LEN];
    char output[MAX_OUTPUT_LEN];

    printf("Type a sentence in English (or 'exit' to quit): \n");

    while (1) {
        printf("> ");
        // Get the input from the user
        fgets(input, MAX_INPUT_LEN, stdin);

        // Remove the newline character at the end if present
        input[strcspn(input, "\n")] = 0;

        // Exit condition
        if (strcmp(input, "exit") == 0) {
            printf("Goodbye! Remember to purr often!\n");
            break;
        }

        // Translate to Cat Language
        translateToCatLanguage(input, output);
        printf("Cat Language: %s\n", output);
    }

    return 0;
}

void printWelcomeMessage() {
    printf("=======================================\n");
    printf(" Welcome to the Cat Language Translator!\n");
    printf("=======================================\n");
    printf("Translate your human language to Cat Language and impress your feline friends!\n");
    printf("Type 'exit' to leave at any time.\n");
    printf("=======================================\n");
}

void translateToCatLanguage(const char *input, char *output) {
    char *token;
    char temp[MAX_OUTPUT_LEN];
    temp[0] = '\0'; // Initialize temp as an empty string

    // Tokenize the input string by spaces
    token = strtok((char *)input, " ");
    while (token != NULL) {
        meowify(temp); // Make room for meow-ified word before adding a new word
        strcat(temp, " ");
        meowify((char *)token); // Convert to Cat Language
        strcat(temp, token);
        token = strtok(NULL, " ");
    }

    // Clean up output by removing potential leading spaces
    strcpy(output, temp[0] == ' ' ? temp + 1 : temp);
}

void meowify(char *word) {
    // Simple meowification rule: adding "meow" to the end of each word
    strcat(word, word);
    strcat(word, " meow");
}

