#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define PROC_STAT "/proc/stat"
#define UPDATE_INTERVAL 500
#define BUF_SIZE 128

int main() {
    long prev_total[3];
    long curr_total[3];
    int fd;
    char buf[BUF_SIZE];
    struct stat st;

    memset(prev_total, 0, sizeof(prev_total));
    memset(curr_total, 0, sizeof(curr_total));

    while (1) {
        if ((fd = open(PROC_STAT, O_RDONLY)) < 0) {
            perror("open");
            exit(EXIT_FAILURE);
        }

        if (fstat(fd, &st) < 0) {
            perror("fstat");
            exit(EXIT_FAILURE);
        }

        if (read(fd, buf, BUF_SIZE) < 0) {
            perror("read");
            exit(EXIT_FAILURE);
        }

        close(fd);

        sscanf(buf, "%*s %ld %ld %ld", &prev_total[0], &prev_total[1], &prev_total[2]);

        sleep(UPDATE_INTERVAL / 1000.0);

        if ((fd = open(PROC_STAT, O_RDONLY)) < 0) {
            perror("open");
            exit(EXIT_FAILURE);
        }

        if (fstat(fd, &st) < 0) {
            perror("fstat");
            exit(EXIT_FAILURE);
        }

        if (read(fd, buf, BUF_SIZE) < 0) {
            perror("read");
            exit(EXIT_FAILURE);
        }

        close(fd);

        sscanf(buf, "%*s %ld %ld %ld", &curr_total[0], &curr_total[1], &curr_total[2]);

        long total_diff = curr_total[0] - prev_total[0];
        float cpu_usage = ((float) total_diff * 100.0) / curr_total[0];

        printf("CPU usage: %.2f%%\n", cpu_usage);

        memset(prev_total, 0, sizeof(prev_total));
        memcpy(prev_total, curr_total, sizeof(curr_total));
    }

    return EXIT_SUCCESS;
}

