#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdbool.h>

#define MAX_SENTENCE_LENGTH 1000
#define MAX_SENTENCES 1000
#define MAX_WORDS_PER_SENTENCE 50

typedef struct {
    char* text;
    int length;
} Sentence;

typedef struct {
    Sentence* sentences;
    int numSentences;
} Document;

void initializeDocument(Document* document) {
    document->sentences = (Sentence*) malloc(MAX_SENTENCES * sizeof(Sentence));
    document->numSentences = 0;
}

void addSentence(Document* document, char* sentenceText) {
    if (document->numSentences >= MAX_SENTENCES) {
        printf("Error: Maximum number of sentences exceeded.\n");
        return;
    }

    int sentenceLength = strlen(sentenceText);
    if (sentenceLength > MAX_SENTENCE_LENGTH) {
        printf("Error: Sentence is too long.\n");
        return;
    }

    Sentence* newSentence = (Sentence*) malloc(sizeof(Sentence));
    newSentence->text = (char*) malloc((sentenceLength + 1) * sizeof(char));
    strcpy(newSentence->text, sentenceText);
    newSentence->length = sentenceLength;

    document->sentences[document->numSentences++] = *newSentence;
}

void printDocument(Document* document) {
    for (int i = 0; i < document->numSentences; i++) {
        printf("%s\n", document->sentences[i].text);
    }
}

void freeDocument(Document* document) {
    for (int i = 0; i < document->numSentences; i++) {
        free(document->sentences[i].text);
    }
    free(document->sentences);
}

void summarizeDocument(Document* document, int maxWordsPerSentence) {
    for (int i = 0; i < document->numSentences; i++) {
        Sentence* sentence = &document->sentences[i];
        int numWords = 0;

        char* token = strtok(sentence->text, " ");
        while (token!= NULL) {
            if (numWords >= maxWordsPerSentence) {
                break;
            }

            if (isalpha(token[0])) {
                numWords++;
            }

            token = strtok(NULL, " ");
        }

        sentence->length = numWords;
    }
}

int main() {
    Document document;
    initializeDocument(&document);

    addSentence(&document, "The quick brown fox jumps over the lazy dog.");
    addSentence(&document, "The lazy dog sleeps all day.");
    addSentence(&document, "The quick brown fox is very active.");

    printDocument(&document);

    summarizeDocument(&document, 5);

    printDocument(&document);

    freeDocument(&document);

    return 0;
}

