#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_QUEUE_SIZE 10

// Custom Queue structure definition
typedef struct queue {
    int items[MAX_QUEUE_SIZE];
    int front;
    int rear;
} queue;

// Custom Queue functions prototypes
void queue_init(queue *q);
void enqueue(queue *q, int item);
int dequeue(queue *q);
int is_queue_full(queue *q);
int is_queue_empty(queue *q);
void display_queue(queue *q);

// Initialize the queue
void queue_init(queue *q) {
    q->front = -1;
    q->rear = -1;
}

// Enqueue an item to the queue
void enqueue(queue *q, int item) {
    if (is_queue_full(q)) {
        printf("Queue is full!\n");
        return;
    }

    if (q->front == -1) {
        q->front = 0;
    }

    q->rear = (q->rear + 1) % MAX_QUEUE_SIZE;
    q->items[q->rear] = item;
}

// Dequeue an item from the queue
int dequeue(queue *q) {
    if (is_queue_empty(q)) {
        printf("Queue is empty!\n");
        return -1;
    }

    int item = q->items[q->front];

    if (q->front == q->rear) {
        q->front = -1;
        q->rear = -1;
    } else {
        q->front = (q->front + 1) % MAX_QUEUE_SIZE;
    }

    return item;
}

// Check if the queue is full
int is_queue_full(queue *q) {
    return ((q->rear + 1) % MAX_QUEUE_SIZE == q->front);
}

// Check if the queue is empty
int is_queue_empty(queue *q) {
    return (q->front == -1 && q->rear == -1);
}

// Display the queue items
void display_queue(queue *q) {
    if (is_queue_empty(q)) {
        printf("Queue is empty.\n");
        return;
    }

    int i = q->front;

    printf("Queue items: ");

    while (i != q->rear) {
        printf("%d ", q->items[i]);
        i = (i + 1) % MAX_QUEUE_SIZE;
    }

    printf("%d\n", q->items[i]);
}

// Main function to test the queue implementation
int main() {
    queue my_queue;
    queue_init(&my_queue);

    printf("Enqueueing items: 1, 2, 3, 4, 5\n");
    enqueue(&my_queue, 1);
    enqueue(&my_queue, 2);
    enqueue(&my_queue, 3);
    enqueue(&my_queue, 4);
    enqueue(&my_queue, 5);

    printf("Displaying the queue: ");
    display_queue(&my_queue);

    printf("Dequeueing items: ");

    while (!is_queue_empty(&my_queue)) {
        int item = dequeue(&my_queue);
        printf("%d ", item);
    }

    printf("\n");

    return 0;
}

