int kiemtrahoanthien(int n)
{
    int i = 1;
    int S = 0;
    while(i < n)
    {
        if(n % i == 0)
        {
            S = S + i;
        }
        i++;
    }
    if(S == n)
        return 1;
    else
        return 0;
}
int timvitrisohoanthiendau(int a[], int n)
