int KiemTraDang3K(int n)
{
    int flag=1;
    n = n < 0 ? -n : n;
    if(n < 2)
        return 1;

    while(n > 1)
    {
        int du = n % 3;
        if(du != 0)  // nếu dư mà khác 0. lập tức báo sai
            flag = 0;
        n /= 3;
    }
    if(flag == 1)
