	return 0;
}

//MISTRAL-7B DATASET v1.0 Category: Linked list operations ; Style: recursive
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int data;
    struct Node* next;
} Node;

Node* reverseListRecursive(Node* head) {
    if (head == NULL || head->next == NULL) {
        return head;
    }

    Node* reversedList = reverseListRecursive(head->next);
    head->next->next = head;
    head->next = NULL;

    return reversedList;
}

int main() {
    Node* head = NULL;
    Node* second = NULL;
    Node* third = NULL;
    Node* fourth = NULL;

    head = (Node*) malloc(sizeof(Node));
    second = (Node*) malloc(sizeof(Node));
    third = (Node*) malloc(sizeof(Node));
    fourth = (Node*) malloc(sizeof(Node));

    head->data = 1;
    head->next = second;

    second->data = 2;
    second->next = third;

    third->data = 3;
    third->next = fourth;

    fourth->data = 4;
    fourth->next = NULL;

    printf("Original Linked List: ");
    printList(head);

    head = reverseListRecursive(head);

    printf("\nReversed Linked List: ");
    printList(head);

    free(head);
    free(second);
    free(third);
    free(fourth);

    return 0;
}

void printList(Node* node) {
    if (node != NULL) {
        printf("%d -> ", node->data);
        printList(node->next);
    }
}

