#include <time.h>

#define MAX_CARS 10
#define ROAD_LENGTH 100

int main()
{
    int i, j, k, num_cars = 0, current_position[MAX_CARS], direction[MAX_CARS], speed[MAX_CARS];
    char road[ROAD_LENGTH];

    // Initialize the road
    for (i = 0; i < ROAD_LENGTH; i++)
    {
        road[i] = ' ';
    }

    // Create the cars
    for (i = 0; i < MAX_CARS; i++)
    {
        current_position[i] = 0;
        direction[i] = 1;
        speed[i] = rand() % 5 + 1;
    }

    // Simulate traffic flow
    time_t start_time = time(NULL);
    while (time(NULL) - start_time < 10)
    {
        // Move the cars
        for (i = 0; i < num_cars; i++)
        {
            current_position[i] += direction[i] * speed[i];

            // Check if the car has reached the end of the road
            if (current_position[i] >= ROAD_LENGTH - 1)
            {
                direction[i] = -1;
            }
            else if (current_position[i] <= 0)
            {
                direction[i] = 1;
            }

            // Update the road
            road[current_position[i]] = 'C';
        }

        // Display the road
        for (i = 0; i < ROAD_LENGTH; i++)
        {
            printf("%c ", road[i]);
        }

        printf("\n");

        // Sleep for a while
        sleep(1);
    }

    return 0;
}

