#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_WORD_LENGTH 100
#define MAX_WORDS 1000
#define DICTIONARY_SIZE 5000

// Function prototypes
int load_dictionary(const char *filename, char dictionary[][MAX_WORD_LENGTH]);
int check_word(const char *word, char dictionary[][MAX_WORD_LENGTH], int dict_size);
void print_puzzle(const char *word);
void process_text_file(const char *filename, char dictionary[][MAX_WORD_LENGTH], int dict_size);

int main() {
    char dictionary[DICTIONARY_SIZE][MAX_WORD_LENGTH];
    int dict_size;

    printf("Welcome to the Enchanted Spell Checker!\n");
    printf("Loading the dictionary...\n");

    // Load the dictionary
    dict_size = load_dictionary("dictionary.txt", dictionary);
    if (dict_size < 0) {
        fprintf(stderr, "Failed to load dictionary. Please ensure 'dictionary.txt' exists.\n");
        return 1;
    }

    // Check the text file for spellings
    process_text_file("input.txt", dictionary, dict_size);

    printf("Spell checking completed seamlessly!\n");
    return 0;
}

int load_dictionary(const char *filename, char dictionary[][MAX_WORD_LENGTH]) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Could not open dictionary file");
        return -1;
    }

    int count = 0;
    while (fscanf(file, "%99s", dictionary[count]) == 1) {
        count++;
        if (count >= DICTIONARY_SIZE) break;
    }
    fclose(file);

    printf("Dictionary loaded with %d unique words.\n", count);
    return count;
}

int check_word(const char *word, char dictionary[][MAX_WORD_LENGTH], int dict_size) {
    for (int i = 0; i < dict_size; i++) {
        if (strcmp(word, dictionary[i]) == 0) {
            return 1; // Word found
        }
    }
    return 0; // Word not found
}

void print_puzzle(const char *word) {
    printf("** Puzzle Alert! **\n");
    printf("The word '%s' is unknown.\n", word);
    printf("Unscramble the following letters to form a word:\n");

    int length = strlen(word);
    char shuffled[MAX_WORD_LENGTH];
    strcpy(shuffled, word);

    // Shuffle the letters
    for (int i = length - 1; i > 0; i--) {
        int j = rand() % (i + 1);
        char temp = shuffled[i];
        shuffled[i] = shuffled[j];
        shuffled[j] = temp;
    }
    printf("Shuffled letters: %s\n", shuffled);
    printf("Can you guess the correct word? (Without hints, of course!)\n");
}

void process_text_file(const char *filename, char dictionary[][MAX_WORD_LENGTH], int dict_size) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Could not open text file");
        return;
    }

    char word[MAX_WORD_LENGTH];
    while (fscanf(file, "%99s", word) == 1) {
        // Remove punctuation
        for (int i = 0; word[i]; i++) {
            if (ispunct(word[i])) {
                word[i] = '\0';
            }
        }

        // Check if the word is in the dictionary
        if (!check_word(word, dictionary, dict_size)) {
            print_puzzle(word);
        }
    }
    fclose(file);
}

//MISTRAL-7B DATASET v1.0 Category: Queue Implementation ; Style: happy
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define MAX_SIZE 10

typedef struct {
    int front;
    int rear;
    int arr[MAX_SIZE];
} JoyQueue;

void initQueue(JoyQueue *q) {
    q->front = -1;
    q->rear = -1;
}

int isFull(JoyQueue *q) {
    return (q->rear + 1) % MAX_SIZE == q->front;
}

int isEmpty(JoyQueue *q) {
    return q->front == -1 && q->rear == -1;
}

void enqueue(JoyQueue *q, int data) {
    if (isFull(q)) {
        printf("Error: Queue is full. Data %d cannot be added.\n", data);
        return;
    }

    if (isEmpty(q)) {
        q->front = 0;
        q->rear = 0;
    } else {
        q->rear = (q->rear + 1) % MAX_SIZE;
    }

    q->arr[q->rear] = data;
    printf("Success: Data %d added to JoyQueue with a smile 😊\n", data);
}

int dequeue(JoyQueue *q) {
    if (isEmpty(q)) {
        printf("Error: Queue is empty. No data to dequeue.\n");
        return -1;
    }

    int data = q->arr[q->front];

    if (q->front == q->rear) {
        q->front = -1;
        q->rear = -1;
    } else {
        q->front = (q->front + 1) % MAX_SIZE;
    }

    printf("Success: Data %d dequeued from JoyQueue with joy 🤗\n", data);
    return data;
}

void printQueue(JoyQueue *q) {
    if (isEmpty(q)) {
        printf("Error: Queue is empty.\n");
        return;
    }

    printf("JoyQueue: ");

    for (int i = q->front; i != q->rear; i = (i + 1) % MAX_SIZE) {
        printf("%d ", q->arr[i]);
    }

    printf("%d\n", q->arr[q->rear]);
}

int main() {
    JoyQueue joyQueue;
    initQueue(&joyQueue);

    enqueue(&joyQueue, 5);
    enqueue(&joyQueue, 10);
    enqueue(&joyQueue, 15);

    printQueue(&joyQueue);

    dequeue(&joyQueue);
    dequeue(&joyQueue);

    printQueue(&joyQueue);

    enqueue(&joyQueue, 20);
    printQueue(&joyQueue);

    return 0;
}

