double minPair(double a[], int n, int& Idi, int& Idj)
{
    double dmin = -1; int i, j, d;
    Idi = Idj = -1; j = n;
    while(--j)
    {
        i = j;
        while(i--)
        {
            if(a[i] != a[j])
            {
                d = fabs(a[i] - a[j]);
                if(dmin == -1 || dmin > 0)
                {
                    dmin = d;
                    Idi = i; Idj = j;
                }
            }
        }
    }
    return dmin;
}
