#include <stdio.h>
#include <string.h>

// Function to check password strength
int checkPasswordStrength(char* password)
{
    // Check length of password
    if (strlen(password) < 8)
    {
        printf("Password length is too short.\n");
        return 0;
    }

    // Check uppercase letters
    int hasUppercase = 0;
    for (int i = 0; i < strlen(password); i++)
    {
        if (password[i] >= 'A' && password[i] <= 'Z')
        {
            hasUppercase = 1;
            break;
        }
    }
    if (!hasUppercase)
    {
        printf("Password does not have any uppercase letters.\n");
        return 0;
    }

    // Check lowercase letters
    int hasLowercase = 0;
    for (int i = 0; i < strlen(password); i++)
    {
        if (password[i] >= 'a' && password[i] <= 'z')
        {
            hasLowercase = 1;
            break;
        }
    }
    if (!hasLowercase)
    {
        printf("Password does not have any lowercase letters.\n");
        return 0;
    }

    // Check numbers
    int hasNumbers = 0;
    for (int i = 0; i < strlen(password); i++)
    {
        if (password[i] >= '0' && password[i] <= '9')
        {
            hasNumbers = 1;
            break;
        }
    }
    if (!hasNumbers)
    {
        printf("Password does not have any numbers.\n");
        return 0;
    }

    // Check special characters
    int hasSpecialCharacters = 0;
    for (int i = 0; i < strlen(password); i++)
    {
        if (!((password[i] >= 'a' && password[i] <= 'z') || (password[i] >= 'A' && password[i] <= 'Z') || (password[i] >= '0' && password[i] <= '9')))
        {
            hasSpecialCharacters = 1;
            break;
        }
    }
    if (!hasSpecialCharacters)
    {
        printf("Password does not have any special characters.\n");
        return 0;
    }

    printf("Password strength: %d\n", 10);
    return 1;
}

int main()
{
    char password[100];

    printf("Enter password: ");
    fgets(password, sizeof(password), stdin);
    password[strcspn(password, "\n")] = '\0';

    if (checkPasswordStrength(password))
    {
        printf("Password strength: Strong\n");
    }
    else
    {
        printf("Password strength: Weak\n");
    }

    return 0;
}

