#include <time.h>

#define MAX_ROWS 20
#define MAX_COLS 20

int maze[MAX_ROWS][MAX_COLS];
int row, col;
int start_row, start_col;
int end_row, end_col;

void generate_maze() {
    srand(time(0));

    for (row = 0; row < MAX_ROWS; row++) {
        for (col = 0; col < MAX_COLS; col++) {
            maze[row][col] = 0;
        }
    }

    start_row = rand() % MAX_ROWS;
    start_col = rand() % MAX_COLS;
    end_row = rand() % MAX_ROWS;
    end_col = rand() % MAX_COLS;

    maze[start_row][start_col] = 1;
    maze[end_row][end_col] = 2;

    int num_walls = MAX_ROWS * MAX_COLS - 3;

    for (row = 0; row < MAX_ROWS; row++) {
        for (col = 0; col < MAX_COLS; col++) {
            if (maze[row][col] == 0) {
                for (int i = 0; i < 8; i++) {
                    int new_row = row + ((i & 1)? 1 : -1);
                    int new_col = col + ((i & 2)? 1 : -1);

                    if (new_row >= 0 && new_row < MAX_ROWS && new_col >= 0 && new_col < MAX_COLS) {
                        if (maze[new_row][new_col] == 0) {
                            maze[new_row][new_col] = 1;
                            num_walls--;
                            break;
                        }
                    }
                }

                if (num_walls == 0) {
                    printf("You win!\n");
                    exit(0);
                }
            }
        }
    }

    printf("You lose!\n");
    exit(0);
}

int main() {
    generate_maze();
    return 0;
}

