void init_BIT(int N)  // takes max size of BIT
{
	BIT = vector<int> (N+1,0);
	maxVal = N;
}

void update(int index,int value)
{
	while(index <= maxVal)
	{
		BIT[index] += value;
		index+=(index & -index);
	}
}
