int KiemTraHoanThien(int n)
{
    int Tong = 0;
    for(int i = 1; i < n; i++)
    {
        if(n % i == 0)
        {
            Tong += i;
        }
    }
    if(Tong == n)
    {
        return 1;
    }
    return 0;
}
int TinhTongCacSoHoanThien(int a[][MAX], int dong, int cot)
{
    int Tong = 0;
    int n = dong * cot;
    for(int i = 0; i < n; i++)
    {
        if(KiemTraHoanThien(a[i / cot][i % cot]) == 1)
        {
            Tong += a[i / cot][i % cot];
        }
    }
    return Tong;
}
