void Reverse(vector&lt;int&gt; v)
{
    vector&lt;int&gt;::iterator itr1 = v.begin();
    vector&lt;int&gt;::reverse_iterator itr2 = v.rbegin();
    while(true)
    {
        swap(*itr1,*itr2);
        itr1++;
        if(itr1 == itr2.base() - 1) break;
        itr2++;
    }
}

