#define WIDTH 80
#define HEIGHT 25

int main() {
    // Initialize the game board
    int board[WIDTH][HEIGHT];
    for (int i = 0; i < WIDTH; i++) {
        for (int j = 0; j < HEIGHT; j++) {
            board[i][j] = 0;
        }
    }

    // Seed the random number generator
    srand(time(NULL));

    // Create a random starting pattern
    for (int i = 0; i < WIDTH; i++) {
        for (int j = 0; j < HEIGHT; j++) {
            if (rand() % 100 < 20) {
                board[i][j] = 1;
            }
        }
    }

    // Run the game loop
    while (1) {
        // Display the game board
        for (int i = 0; i < WIDTH; i++) {
            for (int j = 0; j < HEIGHT; j++) {
                if (board[i][j] == 1) {
                    printf("*");
                } else {
                    printf(".");
                }
            }
            printf("\n");
        }

        // Update the game board
        for (int i = 0; i < WIDTH; i++) {
            for (int j = 0; j < HEIGHT; j++) {
                int count = 0;

                // Count the number of neighbors
                for (int k = -1; k <= 1; k++) {
                    for (int l = -1; l <= 1; l++) {
                        if (i + k >= 0 && i + k < WIDTH && j + j >= 0 && j + l < HEIGHT && !(k == 0 && l == 0)) {
                            count += board[i + k][j + l];
                        }
                    }
                }

                // Apply the rules of the game
                if (board[i][j] == 1) {
                    if (count < 2 || count > 3) {
                        board[i][j] = 0;
                    }
                } else {
                    if (count == 3) {
                        board[i][j] = 1;
                    }
                }
            }
        }
        printf("\n");
    }

    return 0;
}

