    // Find the default network interface and mask
    if (pcap_lookupnet("eth0", &net, &mask, errbuf) == -1) {
        fprintf(stderr, "Can't get default network interface: %s\n", errbuf);
        net = 0;
        mask = 0;
    }

    // Open device for sniffing
    handle = pcap_open_live("eth0", BUFSIZ, 1, 1000, errbuf);
    if (handle == NULL) {
        fprintf(stderr, "Can't open device eth0: %s\n", errbuf);
        return 1;
    }

    // Compile and apply filter
    if (pcap_compile(handle, &fp, filter_exp, 0, net) == -1) {
        fprintf(stderr, "Couldn't parse filter %s: %s\n", filter_exp, pcap_geterr(handle));
        return 1;
    }
    if (pcap_setfilter(handle, &fp) == -1) {
        fprintf(stderr, "Couldn't install filter %s: %s\n", filter_exp, pcap_geterr(handle));
        return 1;
    }

    // Loop and capture packets
    pcap_loop(handle, -1, packet_handler, NULL);

    // Cleanup
    pcap_freecode(&fp);
    pcap_close(handle);
    return 0;
}

void packet_handler(u_char *args, const struct pcap_pkthdr *header, const u_char *packet)
{
    // Print packet details
    printf("Packet capture length: %d\n", header->caplen);
    printf("Packet total length: %d\n", header->len);
}

//MISTRAL-7B DATASET v1.0 Category: Mortgage Calculator ; Style: invasive
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef struct {
    double principal;
    float interest_rate;
    int term_years;
} mortgage;

void error_handler(const char *msg) {
    printf("%s\n", msg);
    exit(EXIT_FAILURE);
}

void validate_input(mortgage *m) {
    if (m->principal <= 0.0) {
        error_handler("Invalid mortgage amount.\n");
    }

    if (m->interest_rate <= 0.0 || m->interest_rate > 1.0) {
        error_handler("Invalid interest rate.\n");
    }

    if (m->term_years <= 0) {
        error_handler("Invalid loan term.\n");
    }
}

double monthly_interest_rate(mortgage m) {
    return pow(1.0 + m.interest_rate / 100.0, 1.0 / 12.0);
}

int main() {
    mortgage user_input;

    printf("Enter mortgage amount: ");
    scanf("%lf", &user_input.principal);

    printf("Enter interest rate (%): ");
    scanf("%f", &user_input.interest_rate);

    printf("Enter loan term (years): ");
    scanf("%d", &user_input.term_years);

    validate_input(&user_input);

    mortgage calc_input = {user_input.principal, user_input.interest_rate, user_input.term_years};

    printf("\nCalculating mortgage payment...\n");

    double monthly_interest = monthly_interest_rate(calc_input);
    double monthly_payment = (calc_input.principal * monthly_interest) / (1 - pow(monthly_interest, calc_input.term_years * 12.0));

    printf("Monthly payment: $%.2f\n", monthly_payment);

    return EXIT_SUCCESS;
}

