                printf("Invalid candidate choice!\n");
            } else {
                candidates[choice - 1].votes++;
                voters[i].hasVoted = 1;
                printf("Vote casted successfully for %s.\n", candidates[choice - 1].name);
            }
            return;
        }
    }
    printf("Voter not registered. Please register first.\n");
}

