void InterchangeSort(int* a, int x, int y)
{
    for(int i = x; i < y - 1; i++)
    {
        for(int j = i + 1; j < y; j++)
        {
            if(a[i] > a[j])
                swap(a[i], a[j]);
        }
    }
}

void XuatMang(int* a, int n)
{
