{
    XuatMang(a, n);
    cout << endl;
    while(true)
    {
        bool check = false;
        for(int i = n - 1; i > 0; i--)
        {
            if(a[i - 1]  < a[i])
            {
                InterchangeSort(a, i, n );
                for(int j = i; j < n; j++)
                {
                    if(a[j] > a[i - 1])
                    {
                        swap(a[j], a[i - 1]);
                        break;
                    }
                }
                check = true;
                break;
            }
        }

        if(check == false)
            break;
        XuatMang(a, n);
        cout << endl;
    }
}
