struct knight {
    int health;
    int damage;
};

void init_knight(struct knight *knight) {
    knight->health = MAX_HEALTH;
    knight->damage = MAX_DAMAGE;
}

void take_damage(struct knight *knight, int damage) {
    knight->health -= damage;
    if (knight->health <= 0) {
        printf("Thou hast succumbed to thy injuries and hast fallen in battle.\n");
        exit(1);
    }
}

void attack(struct knight *knight) {
    int roll = rand() % 20 + 1;
    if (roll > knight->damage) {
        printf("Thy blow striketh true and dealest %d points of damage!\n", roll);
        take_damage(knight, roll);
    } else {
        printf("Thy blow misseth thy mark and thou dost suffer a glancing blow, taking only %d points of damage.\n", roll);
        take_damage(knight, roll);
    }
}

