    switch (direction) {
        case 'n':
            knight->health += 5;
            break;
        case 's':
            knight->health -= 5;
            break;
        case 'e':
            knight->damage += 10;
            break;
        case 'w':
            knight->damage -= 10;
            break;
        default:
            printf("Invalid direction! Aborting program...\n");
            exit(1);
    }
}

