/*
 * Bingo Simulator
 *
 * Generates a random bingo card and allows the user to mark numbers as they are called.
 */

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the size of the bingo card
#define CARD_SIZE 5

// Define the number of bingo calls
#define NUM_CALLS 15

// Define the range of numbers to use
#define MIN_NUM 1
#define MAX_NUM 75

// Define the bingo card
int card[CARD_SIZE][CARD_SIZE];

// Define the bingo calls
int calls[NUM_CALLS];

int main() {
  // Seed the random number generator
  srand(time(NULL));

  // Generate a random bingo card
  for (int i = 0; i < CARD_SIZE; i++) {
    for (int j = 0; j < CARD_SIZE; j++) {
      card[i][j] = rand() % (MAX_NUM - MIN_NUM + 1) + MIN_NUM;
    }
  }

  // Print the bingo card
  for (int i = 0; i < CARD_SIZE; i++) {
    for (int j = 0; j < CARD_SIZE; j++) {
      printf("%d ", card[i][j]);
    }
    printf("\n");
  }

  // Generate bingo calls
  for (int i = 0; i < NUM_CALLS; i++) {
    calls[i] = rand() % (MAX_NUM - MIN_NUM + 1) + MIN_NUM;
  }

  // Print bingo calls
  for (int i = 0; i < NUM_CALLS; i++) {
    printf("%d ", calls[i]);
  }
  printf("\n");

  // Mark numbers on the card
  for (int i = 0; i < NUM_CALLS; i++) {
    for (int j = 0; j < CARD_SIZE; j++) {
      for (int k = 0; k < CARD_SIZE; k++) {
        if (card[j][k] == calls[i]) {
          card[j][k] = -1;
        }
      }
    }
  }

  // Print the marked card
  for (int i = 0; i < CARD_SIZE; i++) {
    for (int j = 0; j < CARD_SIZE; j++) {
      printf("%d ", card[i][j]);
    }
    printf("\n");
  }

  return 0;
}

