//GPT-4o-mini DATASET v1.0 Category: Performance-Critical Component ; Style: authentic
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define ARRAY_SIZE 1000000
#define NUM_THREADS 4

int arr[ARRAY_SIZE];
long long partial_sums[NUM_THREADS];

// Structure to hold data for each thread
typedef struct {
    int thread_id;
    int start_index;
    int end_index;
} thread_data_t;

// Function to calculate the sum of the array segment
void* calculate_partial_sum(void* thread_arg) {
    thread_data_t* data = (thread_data_t*) thread_arg;
    long long sum = 0;

    for (int i = data->start_index; i < data->end_index; i++) {
        sum += arr[i];
    }

    partial_sums[data->thread_id] = sum;
    pthread_exit(NULL);
}

// Function to initialize the array with random values
void initialize_array() {
    srand(time(NULL));
    for (int i = 0; i < ARRAY_SIZE; i++) {
        arr[i] = rand() % 100;  // Random numbers between 0 and 99
    }
}

// Function to calculate the total sum using multiple threads
long long calculate_total_sum() {
    pthread_t threads[NUM_THREADS];
    thread_data_t thread_data[NUM_THREADS];
    long long total_sum = 0;

    int segment_size = ARRAY_SIZE / NUM_THREADS;

    for (int i = 0; i < NUM_THREADS; i++) {
        thread_data[i].thread_id = i;
        thread_data[i].start_index = i * segment_size;
        thread_data[i].end_index = (i + 1) * segment_size;

        if (i == NUM_THREADS - 1) {
            thread_data[i].end_index = ARRAY_SIZE;  // Make sure the last thread covers the entire range
        }
        pthread_create(&threads[i], NULL, calculate_partial_sum, (void*) &thread_data[i]);
    }

    // Join threads and accumulate partial results
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
        total_sum += partial_sums[i];
    }

    return total_sum;
}

int main() {
    initialize_array();

    clock_t start_time = clock();
    long long total_sum = calculate_total_sum();
    clock_t end_time = clock();

    double time_taken = (double)(end_time - start_time) / CLOCKS_PER_SEC;

    printf("Total sum of the array: %lld\n", total_sum);
    printf("Time taken to compute sum using %d threads: %.5f seconds\n", NUM_THREADS, time_taken);

    return 0;
}

