float fahrenheit_to_kelvin(float fahrenheit) {
    return (fahrenheit + 459.67) * 5 / 9;
}

// function to convert kelvin to fahrenheit
float kelvin_to_fahrenheit(float kelvin) {
    return (kelvin * 9 / 5) - 459.67;
