#include <stdio.h>
#include <stdlib.h>

#define MAX_ROWS 20
#define MAX_COLS 40

typedef struct invader {
  int x;
  int y;
  int direction;
} invader;

invader invaders[MAX_ROWS][MAX_COLS];

void initializeInvaders() {
  for (int r = 0; r < MAX_ROWS; r++) {
    for (int c = 0; c < MAX_COLS; c++) {
      invaders[r][c].x = -1;
      invaders[r][c].y = -1;
      invaders[r][c].direction = 0;
    }
  }
}

void moveInvaders() {
  for (int r = 0; r < MAX_ROWS; r++) {
    for (int c = 0; c < MAX_COLS; c++) {
      switch (invaders[r][c].direction) {
        case 0:
          invaders[r][c].x++;
          break;
        case 1:
          invaders[r][c].x--;
          break;
        case 2:
          invaders[r][c].y++;
          break;
        case 3:
          invaders[r][c].y--;
          break;
      }
    }
  }
}

void drawInvaders() {
  for (int r = 0; r < MAX_ROWS; r++) {
    for (int c = 0; c < MAX_COLS; c++) {
      if (invaders[r][c].x != -1 && invaders[r][c].y != -1) {
        printf("%c ", invaders[r][c].x + 1);
      } else {
        printf(" ");
      }
    }
    printf("\n");
  }
}

int main() {
  initializeInvaders();
  moveInvaders();
  drawInvaders();

  return 0;
}

