#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>

#define PORT 9000
#define MAX_CLIENTS 10

// Structure to hold client information
typedef struct {
    int sockfd;
    char name[20];
} client_t;

// Array of clients
static client_t clients[MAX_CLIENTS];

// Send a message to all clients
void broadcast(char *message) {
    for (int i = 0; i < MAX_CLIENTS; i++) {
        if (clients[i].sockfd != -1) {
            // Send the message
            send(clients[i].sockfd, message, strlen(message), 0);
        }
    }
}

// Handle a new client connection
void handle_new_client(int sockfd) {
    // Get the client's name
    char name[20];
    recv(sockfd, name, sizeof(name), 0);

    // Find an empty slot for the client
    int i;
    for (i = 0; i < MAX_CLIENTS; i++) {
        if (clients[i].sockfd == -1) {
            break;
        }
    }

    // If there is no empty slot, send an error message
    if (i == MAX_CLIENTS) {
        char message[] = "Server is full!";
        send(sockfd, message, sizeof(message), 0);
        close(sockfd);
        return;
    }

    // Add the client to the array of clients
    clients[i].sockfd = sockfd;
    strcpy(clients[i].name, name);

    // Send a welcome message to the client
    char message[] = "Welcome to the chat server!";
    send(sockfd, message, sizeof(message), 0);

    // Broadcast the new client's name to all other clients
    char broadcast_message[50];
    sprintf(broadcast_message, "%s has joined the chat!", name);
    broadcast(broadcast_message);
}

// Handle a client's message
void handle_message(int sockfd) {
    // Receive the message
    char message[256];
    recv(sockfd, message, sizeof(message), 0);

    // Broadcast the message to all other clients
    char broadcast_message[280];
    sprintf(broadcast_message, "%s: %s", clients[sockfd].name, message);
    broadcast(broadcast_message);
}

// Main function
int main() {
    // Create a socket
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd == -1) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    // Bind the socket to an address
    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_port = htons(PORT);
    addr.sin_addr.s_addr = INADDR_ANY;
    if (bind(sockfd, (struct sockaddr *)&addr, sizeof(addr)) == -1) {
        perror("bind");
        exit(EXIT_FAILURE);
    }

    // Listen for connections
    if (listen(sockfd, MAX_CLIENTS) == -1) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    // Initialize the array of clients
    for (int i = 0; i < MAX_CLIENTS; i++) {
        clients[i].sockfd = -1;
    }

    // Main loop
    while (1) {
        // Accept a new connection
        int newsockfd = accept(sockfd, NULL, NULL);
        if (newsockfd == -1) {
            perror("accept");
            continue;
        }

        // Handle the new connection
        handle_new_client(newsockfd);
    }

    // Close the socket
    close(sockfd);

    return 0;
}

