#include<stdio.h>
#include<stdlib.h>
#include<string.h>
#include<ctype.h>

/*
    This program is a unique C spell checking example program that checks the spelling
    of a word entered by the user. If the word is spelled correctly, it prints a message
    stating that the word is spelled correctly. If the word is spelled incorrectly, it prints
    a message providing suggestions for correctly spelled words based on the Levenshtein distance
    algorithm.

    The program uses a dictionary stored in a file named "dictionary.txt", which contains a list
    of correctly spelled words. The dictionary is loaded into memory upon program startup and is
    stored in a hash table for efficient searching.

    The program also includes functions for calculating the Levenshtein distance between two words
    and for generating a list of suggestions for correcting a misspelled word.
*/

#define HASH_SIZE 10000
#define MAX_WORD_LENGTH 50
#define MAX_SUGGESTIONS 10

typedef struct node {
    char* word;
    struct node* next;
} node_t;

node_t* hashtable[HASH_SIZE];
int dictionary_size = 0;

int hash_word(const char* word) {
    int hash = 0;
    for(int i = 0; i < strlen(word); i++) {
        hash = (31 * hash + tolower(word[i])) % HASH_SIZE;
    }
    return hash;
}

void add_word_to_hashtable(const char* word) {
    int hash = hash_word(word);
    node_t* head = hashtable[hash];

    while(head != NULL) {
        if(strcmp(head->word, word) == 0) {
            // word already exists in hashtable
            return;
        }
        head = head->next;
    }

    node_t* new_node = malloc(sizeof(node_t));
    new_node->word = malloc(strlen(word) + 1);
    strcpy(new_node->word, word);
    new_node->next = hashtable[hash];
    hashtable[hash] = new_node;
    dictionary_size++;
}

void load_dictionary_file(const char* filename) {
    FILE* file = fopen(filename, "r");
    char word_buffer[MAX_WORD_LENGTH];

    while(fscanf(file, "%s", word_buffer) == 1) {
        add_word_to_hashtable(word_buffer);
    }

    fclose(file);
}

int levenshtein_distance(const char* a, const char* b) {
    int distance[strlen(a) + 1][strlen(b) + 1];

    for(int i = 0; i <= strlen(a); i++) {
        distance[i][0] = i;
    }

    for(int j = 0; j <= strlen(b); j++) {
        distance[0][j] = j;
    }

    for(int j = 1; j <= strlen(b); j++) {
        for(int i = 1; i <= strlen(a); i++) {
            if(a[i - 1] == b[j - 1]) {
                distance[i][j] = distance[i - 1][j - 1];
            }
            else {
                int delete_distance = distance[i - 1][j] + 1;
                int insert_distance = distance[i][j - 1] + 1;
                int substitute_distance = distance[i - 1][j - 1] + 1;
                distance[i][j] = delete_distance < insert_distance ?
                    (delete_distance < substitute_distance ? delete_distance : substitute_distance) :
                    (insert_distance < substitute_distance ? insert_distance : substitute_distance);
            }
        }
    }

    return distance[strlen(a)][strlen(b)];
}

node_t** find_suggestions(const char* word, int* num_suggestions_out) {
    node_t* suggestions[MAX_SUGGESTIONS];
    int distances[MAX_SUGGESTIONS];
    int num_suggestions = 0;
    int max_distance = strlen(word) / 2 + 1;

    for(int i = 0; i < HASH_SIZE && num_suggestions < MAX_SUGGESTIONS; i++) {
        node_t* head = hashtable[i];
        while(head != NULL) {
            int distance = levenshtein_distance(word, head->word);
            if(distance <= max_distance) {
                suggestions[num_suggestions] = head;
                distances[num_suggestions] = distance;
                num_suggestions++;
            }
            head = head->next;
        }
    }

    // sort suggestions by distance
    for(int i = 1; i < num_suggestions; i++) {
        for(int j = i; j > 0 && distances[j - 1] > distances[j]; j--) {
            node_t* temp_node = suggestions[j];
            int temp_distance = distances[j];
            suggestions[j] = suggestions[j - 1];
            distances[j] = distances[j - 1];
            suggestions[j - 1] = temp_node;
            distances[j - 1] = temp_distance;
        }
    }

    // trim suggestions to max size
    if(num_suggestions > MAX_SUGGESTIONS) {
        num_suggestions = MAX_SUGGESTIONS;
    }

    node_t** suggestions_out = malloc(sizeof(node_t*) * num_suggestions);
    for(int i = 0; i < num_suggestions; i++) {
        suggestions_out[i] = suggestions[i];
    }

    *num_suggestions_out = num_suggestions;
    return suggestions_out;
}

int main() {
    load_dictionary_file("dictionary.txt");

    char word_buffer[MAX_WORD_LENGTH];
    printf("Enter a word to spell check: ");
    scanf("%s", word_buffer);

    int hash = hash_word(word_buffer);
    node_t* head = hashtable[hash];

    while(head != NULL) {
        if(strcmp(head->word, word_buffer) == 0) {
            printf("'%s' is spelled correctly.\n", word_buffer);
            return 0;
        }
        head = head->next;
    }

    int num_suggestions;
    node_t** suggestions = find_suggestions(word_buffer, &num_suggestions);

    printf("'%s' is spelled incorrectly. Suggestions:\n", word_buffer);
    for(int i = 0; i < num_suggestions; i++) {
        printf("  %s\n", suggestions[i]->word);
    }

    return 0;
}

#include <iostream> //needed for cout/cin
#include <time.h> //needed for time() and localtime()

using namespace std; // select std namespace

/*
This lesson will cover strutures and use functions with
pass by value and pass by address. 
Employee structures will be stored in a linked list
instead of an array. http://en.wikipedia.org/wiki/Linked_list
*/

struct Employee
{
  char name[40];
  char address[40];
  char age[5];
  char time[80];
  Employee *Next;
};

char printMenu();
void getEmployee(Employee **newEm);
void viewAll(Employee *myList);
void getTime(char * myTime);

int main()
{
  char a = '0';

  //create a pointer to an Employee struct and set the address to 0
  //this will always be the head of the list
  Employee *S_myList = 0;

  while (a != 'q'){
	a = printMenu();

	if(a == '1')
		getEmployee(&S_myList);

	else if (a == '2')
		viewAll(S_myList);

  }

  return 0;
}

//function definitions 
char printMenu()
{
  char selection;
  cout << "\nWelcome\n1. Enter new employee\n2. View all\nq. Quit" << endl;
  cin >> selection;
  return selection;
}

//getEmployee() will dynamically create an Employee struct, 
//fill in the data varables, and link the address pointer
//to the first node in the list.
//myList is a pointer to an Employee struct pointer
void getEmployee(Employee **myList)
{
  Employee *newEm;  //create struct pointer for new employee
  bool flag = false; //flag used for testing whether the list is empty

  //if myList address is still set to 0, then this is the first node in the list
  if(*myList == 0){
	//create dynamically allocated structure and
	//myList and newEm both get same address
	*myList = newEm = new Employee;
	//since this is the first node, set the next
	//address to 0
	newEm->Next = 0;
	flag = true;
  }
  else
	//else is entered if this is not the first time
	//the function is called.
	//get address of dynamically allocated struct
	newEm = new Employee;

  //prompt and fill in data.
  cout << "Enter name:" << endl;

  //because newEm is just an address, we must dereference it. 
  //the "->" is short hand for "(* )."
  cin >> (*newEm).name;
  cout << "Enter address" << endl;
  cin >> newEm->address;
  cout << "Enter age" << endl;
  cin >> newEm->age;

  //pass time variable to getTime() to be filled in
  getTime(newEm->time);

  //if this is not the first time the function is called then set the Next node pointer
  //to the head node in the list. Then set the head node pointer to our freshly
  //create Employee structure. Remember, myList is a pointer to a pointer
  if(!flag){
	newEm->Next = *myList;
	*myList = newEm;
  }

}

//viewAll() prints all nodes in the list
//remember, myList is just an address
//the last step in the loop sets myList to
//the address of the next node in the list
//the last node has a Next value of "0"
void viewAll(Employee *myList)
{
  cout << "\n\n";
  while (myList != 0){
	cout << myList->name << endl;
	cout << myList->address << endl;
	cout << myList->age << endl;
	cout << myList->time << "\n" << endl;

 	myList = myList->Next;
  }

}

void getTime(char * myTime)
{
  time_t seconds;
  tm *tmPtr; //tm is a structure for time data

  //get time in seconds, man -s3 time
  time(&seconds);
  //convert seconds to localtime, value returned is a tm structure, man -s3 localtime
  tmPtr = localtime(&seconds);

  //format tmPtr structure into a string, man -s3 strftime
  strftime(myTime, 80, "%m-%d-%Y_%H:%M:%S" ,tmPtr);

}

