    kEntity_Component_ByteSize[2]   = sizeof(Entity_Component_Speed);

    kEntity_Component_StringName[2] = "Speed";

    kEntity_Component_ByteSize[3]   = sizeof(Entity_Component_ShapeRender);

    kEntity_Component_StringName[3] = "Shape Data";

