#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <netdb.h>

#define PORT 5000

int main(int argc, char **argv) {
    int listen_socket, client_socket, n;
    struct sockaddr_in server_addr, client_addr;
    char buffer[1024];

    listen_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (listen_socket == -1) {
        fprintf(stderr, "Error creating socket\n");
        exit(1);
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    bind(listen_socket, (struct sockaddr *)&server_addr, sizeof(server_addr));
    listen(listen_socket, 5);

    while (1) {
        client_socket = accept(listen_socket, (struct sockaddr *)&client_addr, (socklen_t*)&n);
        if (client_socket == -1) {
            fprintf(stderr, "Error accepting connection\n");
            exit(1);
        }

        printf("Connected to client\n");
        while (1) {
            n = read(client_socket, buffer, sizeof(buffer));
            if (n == -1) {
                fprintf(stderr, "Error reading from client\n");
                exit(1);
            }
            buffer[n] = '\0';
            printf("%s", buffer);
        }
    }

    close(listen_socket);
    return 0;
}

