#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ITEMS 100

typedef struct Item {
    char name[50];
    int quantity;
    double price;
} Item;

Item items[MAX_ITEMS];

void initializeItems(void) {
    for (int i = 0; i < MAX_ITEMS; i++) {
        items[i].name[0] = '\0';
        items[i].quantity = 0;
        items[i].price = 0.0;
    }
}

void addItem(char* name, int quantity, double price) {
    for (int i = 0; items[i].name[0] != '\0'; i++) {
        if (strcmp(name, items[i].name) == 0) {
            items[i].quantity += quantity;
            return;
        }
    }

    Item newItem;
    strcpy(newItem.name, name);
    newItem.quantity = quantity;
    newItem.price = price;

    for (int i = 0; items[i].name[0] != '\0'; i++) {
        if (items[i].quantity == 0) {
            strcpy(items[i].name, newItem.name);
            items[i].quantity = newItem.quantity;
            items[i].price = newItem.price;
            return;
        }
    }

    printf("Error: Inventory is full.\n");
}

void printInventory(void) {
    printf("Inventory:\n");
    for (int i = 0; items[i].name[0] != '\0'; i++) {
        printf("%s: %d, $%.2lf\n", items[i].name, items[i].quantity, items[i].price);
    }
}

