#include "BinarySearch.h"
#include "Profiling.h"
#include "Random.h"
#include <algorithm>
#include <vector>


using namespace dsalgo;


void ProfileBinarySearch(int range_size, int num_runs) {
  std::vector<int> rand_elems = RandN(0, range_size, range_size);
  std::sort(rand_elems.begin(), rand_elems.end());

  int64_t start = 0;
  int64_t stop = 0;

  // profile lower bound
  start = Clock::Now();
  for (int i = 0 ; i < num_runs; ++i) {
    for (int j = 0; j < range_size; ++j) {
      LowerBound(rand_elems.begin(), rand_elems.end(), rand_elems[j]);
    }
  }
  stop = Clock::Now();
  std::cout << "dsalgo LowerBound" << std::endl;
  PrintStats(stop - start, range_size * num_runs, "\t");

  // profile last occurrence
  start = Clock::Now();
  for (int i = 0 ; i < num_runs; ++i) {
    for (int j = 0; j < range_size; ++j) {
      LastOccurrence(rand_elems.begin(), rand_elems.end(), rand_elems[j]);
    }
  }
  stop = Clock::Now();
  std::cout << "dsalgo LastOccurrence" << std::endl;
  PrintStats(stop - start, range_size * num_runs, "\t");

  // profile upper bound
  start = Clock::Now();
  for (int i = 0 ; i < num_runs; ++i) {
    for (int j = 0; j < range_size; ++j) {
      UpperBound(rand_elems.begin(), rand_elems.end(), rand_elems[j]);
    }
  }
  stop = Clock::Now();
  std::cout << "dsalgo UpperBound" << std::endl;
  PrintStats(stop - start, range_size * num_runs, "\t");

  // profile std::lower_bound
  start = Clock::Now();
  for (int i = 0 ; i < num_runs; ++i) {
    for (int j = 0; j < range_size; ++j) {
      std::lower_bound(rand_elems.begin(), rand_elems.end(), rand_elems[j]);
    }
  }
  stop = Clock::Now();
  std::cout << "std::lower_bound" << std::endl;
