// Tic Tac Toe AI in a mathematical style

#include <stdio.h>
#include <stdlib.h>

// Function to determine the best move for the AI
int determine_best_move(int board[3][3], int player) {
    // Initialize the best move as the first empty square
    int best_move = 0;
    // Initialize the best score as the lowest possible score
    int best_score = -100;

    // Iterate over all possible moves
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            // Check if the current square is empty
            if (board[i][j] == 0) {
                // Make the current move
                board[i][j] = player;
                // Calculate the score for the current move
                int score = calculate_score(board, player);
                // Check if the current score is the best
                if (score > best_score) {
                    // Update the best move and best score
                    best_move = i * 3 + j;
                    best_score = score;
                }
                // Undo the current move
                board[i][j] = 0;
            }
        }
    }

    // Return the best move
    return best_move;
}

// Function to calculate the score for a given board
int calculate_score(int board[3][3], int player) {
    // Initialize the score as 0
    int score = 0;

    // Check for horizontal wins
    for (int i = 0; i < 3; i++) {
        if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
            score += 10;
        }
    }

    // Check for vertical wins
    for (int i = 0; i < 3; i++) {
        if (board[0][i] == player && board[1][i] == player && board[2][i] == player) {
            score += 10;
        }
    }

    // Check for diagonal wins
    if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
        score += 10;
    }
    if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
        score += 10;
    }

    // Return the score
    return score;
}

// Function to print the board
void print_board(int board[3][3]) {
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            printf("%c ", board[i][j] == 1 ? 'X' : board[i][j] == -1 ? 'O' : ' ');
        }
        printf("\n");
    }
}

// Main function
int main() {
    // Initialize the board
    int board[3][3] = {
        {0, 0, 0},
        {0, 0, 0},
        {0, 0, 0}
    };

    // Print the initial board
    print_board(board);

    // Determine the best move for the AI
    int best_move = determine_best_move(board, 1);

    // Make the best move
    board[best_move / 3][best_move % 3] = 1;

    // Print the updated board
    print_board(board);

    return 0;
}

