// Matrix operations
void matrix_invasion(int **mat, int row, int col) {
  int i, j, k;
  for (i = 0; i < row; i++) {
    for (j = 0; j < col; j++) {
      // Invade the matrix with a randomly chosen value
      mat[i][j] = (i + j) % 10;

      // Invade the neighboring cells
      if (i > 0) {
        mat[i - 1][j] = mat[i][j];
      }
      if (i < row - 1) {
        mat[i + 1][j] = mat[i][j];
      }
      if (j > 0) {
        mat[i][j - 1] = mat[i][j];
      }
      if (j < col - 1) {
        mat[i][j + 1] = mat[i][j];
      }
    }
  }
}

