typedef struct {
    int id;
    char name[50];
    float gpa;
} Student;
void swap(Student* a, Student* b) {
    Student temp;
    temp = *a;
    *a = *b;
    *b = temp;
}
void selectionSort(Student arr[], int n) {
    int i, j, min_idx;
    for (i = 0; i < n-1; i++) {
        min_idx = i;
        for (j = i+1; j < n; j++) {
            if (arr[j].gpa < arr[min_idx].gpa) {
                min_idx = j;
            }
        }
        swap(&arr[i], &arr[min_idx]);
    }
}
