#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_CLIENT_LENGTH 1024
#define MAX_SERVER_LENGTH 2048

// Structure to hold client and server information
typedef struct {
    char name[MAX_CLIENT_LENGTH];
    char message[MAX_SERVER_LENGTH];
} client_server_info;

// Function to handle client connections
void handle_client(int sock);

// Function to handle server communication
void handle_server(int sock);

int main(int argc, char *argv[]) {
    // Create a socket
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Set address and port number for server
    struct sockaddr_in server_addr = {
        .sin_family = AF_INET,
        .sin_port = htons(8080),
        .sin_addr.s_addr = INADDR_ANY
    };

    // Bind the socket to the address and port
    if (bind(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("binding failed");
        exit(EXIT_FAILURE);
    }

    // Listen for incoming connections
    if (listen(sock, 3) < 0) {
        perror("listening failed");
        exit(EXIT_FAILURE);
    }

    // Accept an incoming connection
    int client_sock = accept(sock, NULL, NULL);
    if (client_sock < 0) {
        perror("accept failed");
        exit(EXIT_FAILURE);
    }

    // Handle client connections
    handle_client(client_sock);

    // Close the socket
    close(client_sock);

    return 0;
}

// Function to handle client connections
void handle_client(int sock) {
    // Receive the client's name and message
    char client_name[MAX_CLIENT_LENGTH];
    char client_message[MAX_SERVER_LENGTH];
    recv(sock, client_name, sizeof(client_name), 0);
    recv(sock, client_message, sizeof(client_message), 0);

    // Print the client's name and message
    printf("Client: %s\nMessage: %s\n", client_name, client_message);

    // Send a greeting message back to the client
    char greeting[] = "Hello, client!";
    send(sock, greeting, strlen(greeting), 0);

    // Close the socket
    close(sock);
}

// Function to handle server communication
void handle_server(int sock) {
    // Receive the server's message
    char server_message[MAX_SERVER_LENGTH];
    recv(sock, server_message, sizeof(server_message), 0);

    // Print the server's message
    printf("Server: %s\n", server_message);

    // Send a response message back to the server
    char response[] = "Hello, server!";
    send(sock, response, strlen(response), 0);

    // Close the socket
    close(sock);
}

