// Function to evaluate the expression
int evaluate() {
    int i, j;
    int sum = 0;

    // Parse the expression
    for (i = 0; i < strlen(expr); i++) {
        if (expr[i] == '+') {
            // Add the numbers
            for (j = 0; j < strlen(op); j++) {
                if (op[j] == '+') {
                    sum += atoi(expr[i + j + 1]) * atoi(expr[i + j + 2]);
                } else {
                    sum += atoi(expr[i + j + 1]);
                }
            }
        } else if (expr[i] == '-') {
            // Subtract the numbers
            for (j = 0; j < strlen(op); j++) {
                if (op[j] == '-') {
                    sum -= atoi(expr[i + j + 1]) * atoi(expr[i + j + 2]);
                } else {
                    sum -= atoi(expr[i + j + 1]);
                }
            }
        } else if (expr[i] == '*') {
            // Multiply the numbers
            for (j = 0; j < strlen(op); j++) {
                if (op[j] == '*') {
                    sum *= atoi(expr[i + j + 1]) * atoi(expr[i + j + 2]);
                } else {
                    sum *= atoi(expr[i + j + 1]);
                }
