#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define BOARD_SIZE 4

char board[BOARD_SIZE][BOARD_SIZE];

void printBoard() {
  for (int i = 0; i < BOARD_SIZE; i++) {
    for (int j = 0; j < BOARD_SIZE; j++) {
      printf(" %c ", board[i][j]);
    }
    printf("\n");
  }
}

int main() {
  // Seed the random number generator
  srand(time(NULL));

  // Initialize the board
  for (int i = 0; i < BOARD_SIZE; i++) {
    for (int j = 0; j < BOARD_SIZE; j++) {
      board[i][j] = '*';
    }
  }

  // Place the pairs of cards randomly on the board
  int pairs = BOARD_SIZE * BOARD_SIZE / 2;
  for (int i = 0; i < pairs; i++) {
    int x1, y1, x2, y2;
    do {
      x1 = rand() % BOARD_SIZE;
      y1 = rand() % BOARD_SIZE;
      x2 = rand() % BOARD_SIZE;
      y2 = rand() % BOARD_SIZE;
    } while (board[x1][y1] != '*' || board[x2][y2] != '*');
    board[x1][y1] = 'A' + i;
    board[x2][y2] = 'A' + i;
  }

  // Print the board
  printBoard();

  // Get the player's input
  int x1, y1, x2, y2;
  printf("Enter the coordinates of the first card (e.g. 1 2): ");
  scanf("%d %d", &x1, &y1);
  printf("Enter the coordinates of the second card (e.g. 3 4): ");
  scanf("%d %d", &x2, &y2);

  // Check if the cards match
  if (board[x1 - 1][y1 - 1] == board[x2 - 1][y2 - 1]) {
    printf("You found a match!\n");
  } else {
    printf("No match. Try again.\n");
  }

  // Print the board
  printBoard();

  return 0;
}

