const bool Image::SetPixel(const int &x, const int &y, const Pixel<float> &pixel)

{

    if( _pPixelData             &&

        x >= 0 && x < _width    &&

        y >= 0 && y < _height   )

    {

        _pPixelData[ (y * _width + x) ] = pixel;

        return true;

