#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <ctype.h>

#define MAX_PASSWORDS 100
#define PASSWORD_LENGTH 20
#define SALT_LENGTH 10

typedef struct {
    char username[20];
    char password[PASSWORD_LENGTH];
    char salt[SALT_LENGTH];
    time_t last_updated;
} Password;

void generate_password(char *password, int length) {
    const char *characters = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+";
    int i;
    for (i = 0; i < length; i++) {
        password[i] = characters[rand() % strlen(characters)];
    }
    password[i] = '\0';
}

int compare_passwords(const void *a, const void *b) {
    const Password *p1 = a;
    const Password *p2 = b;
    return strcmp(p1->username, p2->username);
}

Password *load_passwords() {
    FILE *file;
    Password *passwords = NULL;
    size_t capacity = 0;
    file = fopen("passwords.bin", "rb");
    if (file == NULL) {
        return passwords;
    }
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);
    passwords = malloc(file_size);
    if (passwords == NULL) {
        fclose(file);
        return NULL;
    }
    capacity = file_size / sizeof(Password);
    fread(passwords, sizeof(Password), capacity, file);
    fclose(file);
    return passwords;
}

void save_passwords(Password *passwords) {
    FILE *file;
    file = fopen("passwords.bin", "wb");
    if (file == NULL) {
        return;
    }
    fwrite(passwords, sizeof(Password), MAX_PASSWORDS, file);
    fclose(file);
}

int main() {
    Password *passwords = load_passwords();
    if (passwords == NULL) {
        printf("Error loading passwords.\n");
        return 1;
    }
    int choice;
    do {
        printf("Password Manager\n");
        printf("1. Add password\n");
        printf("2. Update password\n");
        printf("3. Delete password\n");
        printf("4. View passwords\n");
        printf("5. Exit\n");
        scanf("%d", &choice);
        switch (choice) {
            case 1:
                // Add password
                break;
            case 2:
                // Update password
                break;
            case 3:
                // Delete password
                break;
            case 4:
                // View passwords
                for (int i = 0; i < MAX_PASSWORDS; i++) {
                    if (passwords[i].username[0]!= '\0') {
                        printf("%s - %s\n", passwords[i].username, passwords[i].password);
                    }
                }
                break;
            case 5:
                save_passwords(passwords);
                free(passwords);
                return 0;
            default:
                printf("Invalid choice.\n");
        }
    } while (choice!= 5);
    return 0;
}

