#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_SPEED 10
#define MAX_ROTATION 90

typedef struct Vehicle {
    int x, y, direction, speed, rotation;
} Vehicle;

Vehicle vehicle;

void initializeVehicle() {
    vehicle.x = 0;
    vehicle.y = 0;
    vehicle.direction = 0;
    vehicle.speed = 0;
    vehicle.rotation = 0;
}

void moveVehicle() {
    switch (vehicle.direction) {
        case 0:
            vehicle.x++;
            break;
        case 1:
            vehicle.y++;
            break;
        case 2:
            vehicle.x--;
            break;
        case 3:
            vehicle.y--;
            break;
    }

    vehicle.speed++;

    if (vehicle.speed > MAX_SPEED) {
        vehicle.speed = MAX_SPEED;
    }

    if (vehicle.rotation > MAX_ROTATION) {
        vehicle.rotation = MAX_ROTATION;
    }
}

void displayVehicle() {
    printf("Position: (%d, %d)\n", vehicle.x, vehicle.y);
    printf("Direction: %d\n", vehicle.direction);
    printf("Speed: %d\n", vehicle.speed);
    printf("Rotation: %d\n", vehicle.rotation);
}

int main() {
    initializeVehicle();

    while (1) {
        moveVehicle();
        displayVehicle();

        sleep(1);
    }

    return 0;
}

