#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sqlite3.h>

// Define the database schema
#define DB_NAME "example.db"
#define TABLE_NAME "users"
#define COLUMN_ID "id"
#define COLUMN_NAME "name"
#define COLUMN_AGE "age"

// Define the filtering conditions
#define FILTER_CONDITION "WHERE age > 18"

// Define the sorting conditions
#define SORT_CONDITION "ORDER BY age DESC"

// Define the grouping conditions
#define GROUP_CONDITION "GROUP BY age"

// Define the output format
#define OUTPUT_FORMAT "%d\t%s\t%d\n"

int main() {
    // Initialize the database connection
    sqlite3 *db;
    sqlite3_open(DB_NAME, &db);

    // Prepare the query
    char *query = "SELECT id, name, age FROM " TABLE_NAME " " FILTER_CONDITION " " SORT_CONDITION " " GROUP_CONDITION;
    sqlite3_stmt *stmt;
    sqlite3_prepare_v2(db, query, -1, &stmt, NULL);

    // Execute the query
    sqlite3_step(stmt);

    // Print the results
    while (sqlite3_column_text(stmt, 0) != NULL) {
        printf(OUTPUT_FORMAT, sqlite3_column_int(stmt, 0), sqlite3_column_text(stmt, 1), sqlite3_column_int(stmt, 2));
        sqlite3_step(stmt);
    }

    // Finalize the query
    sqlite3_finalize(stmt);

    // Close the database connection
    sqlite3_close(db);

    return 0;
}

