    servaddr.sin_family = AF_INET;
    bcopy((char*)server->h_addr, (char*)&servaddr.sin_addr.s_addr, server->h_length);
    servaddr.sin_port = htons(80);

    // Establishing the Connection
    if(connect(sockfd, (struct sockaddr*)&servaddr, sizeof(servaddr)) < 0) {
        printf("Error: Could not connect to server\n");
        return 1;
    }

    // Creating the Request
    char request[BUFFER_SIZE] = {0};
    sprintf(request, "GET /%s HTTP/1.1\r\nHost: %s\r\nConnection: close\r\n\r\n", path, hostname);

    // Writing the Request to the Socket
    if(write(sockfd, request, strlen(request)) < 0) {
        printf("Error: Could not write request to socket\n");
        return 1;
    }

    // Reading the Response
    char response[BUFFER_SIZE] = {0};
    int bytes_read, total_bytes = 0;
    while((bytes_read = read(sockfd, response + total_bytes, BUFFER_SIZE)) > 0) {
        total_bytes += bytes_read;
    }

    // Printing the Response
    printf("%s\n", response);

    // Closing the Socket
    close(sockfd);

    return 0;
}

/*
Quicksort (partition-exchange sort)
----------
Advantages:
    - Fast for large data sets
Disadvantages:
    - Not stable
Time complexity:
    - worst:   O(n^2)
    - average: O(n*log(n))
    - best:    O(n*log(n))
Space complexity:
    - Ideally O(log n)
    - This implementation O(n)
*/

#include <iostream>
#include <vector>
#include <stdlib.h>
#include <time.h>

using std::cout;
using std::vector;
using std::endl;

template<typename T>
void print(vector<T> l) {
    for (int i=0; i < l.size(); i++) {
        cout << l[i] << " ";
    }
    cout << endl;
}

template<typename T>
vector<T> extend(vector<T> v, vector<T> v_prime) {
    v.reserve(v.size() + distance(v_prime.begin(), v_prime.end()));
    v.insert(v.end(), v_prime.begin(), v_prime.end());
    return v;
}

template<typename T>
vector<T> quicksort(vector<T> array) {
    if (array.size() <= 1) {
        return array;
    }
    int pivot_index = rand() % array.size();
    T pivot = array[pivot_index];
    array.erase(array.begin() + pivot_index);
    vector<T> less;
    vector<T> greater;
    for (int i = 0; i < array.size(); i++) {
        if (array[i] <= pivot) {
            less.push_back(array[i]);
        } else {
            greater.push_back(array[i]);
        }
    }
    less = quicksort(less);
    less.push_back(pivot);
    greater = quicksort(greater);
    vector<T> result = extend(less, greater);
    return result;
}

