    addEdge(edges, numEdges, 2, 4, 15);
    addEdge(edges, numEdges, 3, 4, 25);
    addEdge(edges, numEdges, 4, 5, 30);

    // Print graph
    printGraph(edges, numEdges, nodes, numNodes);

    return 0;
}

