    int index = 0;

    token = strtok(command, " \n");
    while (token != NULL) {
        arguments[index++] = token;
        token = strtok(NULL, " \n");
    }

    arguments[index] = NULL; // Null terminate the array
}

void print_prompt() {
    char cwd[MAX_COMMAND_SIZE];
    if (getcwd(cwd, sizeof(cwd)) != NULL) {
        printf("shell:%s$ ", cwd);
    } else {
        perror("getcwd() error");
    }
}

int main() {
    char command[MAX_COMMAND_SIZE];
    char *arguments[MAX_ARGUMENTS];

    printf("Welcome to the Simple Unix-like Shell!\n");
    printf("Type 'exit' to quit the shell.\n");

    while (1) {
        print_prompt();
        if (fgets(command, sizeof(command), stdin) == NULL) {
            perror("fgets failed");
            continue;
        }

        // Exit command
        if (strncmp(command, "exit", 4) == 0) {
            break;
        }

        parse_command(command, arguments);

        if (arguments[0] != NULL) {
            execute_command(arguments);
        }
    }

    printf("Exiting the Shell. Goodbye!\n");
    return 0;
}

