#define WIDTH 80
#define HEIGHT 20

#define BALL_X 10
#define BALL_Y 10

#define PADDLE_X 0
#define PADDLE_Y 0

#define COMPUTER_PADDLE_X 79
#define COMPUTER_PADDLE_Y 0

int main()
{
    int x, y, ball_x, ball_y, paddle_x, paddle_y, computer_paddle_x, computer_paddle_y;
    char board[HEIGHT][WIDTH];

    // Initialize the board
    for (x = 0; x < WIDTH; x++)
    {
        for (y = 0; y < HEIGHT; y++)
        {
            board[y][x] = ' ';
        }
    }

    // Place the ball and paddles
    board[ball_y][ball_x] = 'O';
    board[paddle_y][paddle_x] = 'P';
    board[computer_paddle_y][computer_paddle_x] = 'C';

    // Game loop
    while (!board[ball_y][ball_x] == 'G')
    {
        // Get the user's move
        printf("Enter your move (w/a/s/d): ");
        char move;
        scanf(" %c", &move);

        // Move the ball
        switch (move)
        {
            case 'w':
                ball_y--;
                break;
            case 'a':
                ball_x--;
                break;
            case 's':
                ball_y++;
                break;
            case 'd':
                ball_x++;
                break;
        }

        // Move the computer's paddle
        computer_paddle_y = ball_y - 1;
        if (board[computer_paddle_y][computer_paddle_x] != 'C')
        {
            board[computer_paddle_y][computer_paddle_x] = ' ';
            board[computer_paddle_y][computer_paddle_x] = 'C';
        }

        // Update the board
        board[ball_y][ball_x] = 'O';
        board[paddle_y][paddle_x] = 'P';
    }

