    bits.set(3-bit, (code[bit] == '1'));
  }

  value_ = bits.to_ulong();
}

Gene::Type Gene::type() const {
  if (value_ == 0) {
    return Gene::Type::NOOP;
  }

  if (value_ < 10) {
    return Gene::Type::NUMBER;
  }

  if (value_ < 14) {
    return Gene::Type::OPERATOR;
  }

  return Gene::Type::NOOP;
}

