#include <stdio.h>
#include <stdlib.h>

#define LEFT_BOUND 0
#define RIGHT_BOUND 20

int main()
{
    // Declare variables
    int x, y, score = 0, direction = 1, speed = 1, aliens_alive = 5;
    char board[20][20] = {{0}};

    // Initialize the board
    for (x = 0; x < RIGHT_BOUND; x++)
    {
        for (y = 0; y < LEFT_BOUND; y++)
        {
            board[x][y] = '#';
        }
    }

    // Place the aliens
    board[1][2] = 'A';
    board[1][3] = 'A';
    board[1][4] = 'A';
    board[2][3] = 'A';
    board[2][4] = 'A';

    // Game loop
    while (aliens_alive)
    {
        // Move the aliens
        x += direction * speed;

        // Check if the aliens have reached the edge of the board
        if (x < LEFT_BOUND || x > RIGHT_BOUND)
        {
            direction *= -1;
        }

        // Draw the board
        for (y = 0; y < LEFT_BOUND; y++)
        {
            for (x = 0; x < RIGHT_BOUND; x++)
            {
                printf("%c ", board[x][y]);
            }
            printf("\n");
        }

        // Check if the player has shot an alien
        if (board[x][y] == 'A')
        {
            board[x][y] = '#';
            aliens_alive--;
            score++;
        }

        // Sleep for a while
        sleep(1);
    }

    // Game over message
    printf("Game over! Your score is: %d", score);

    return 0;
}

