int myAtoi2(char *str)
    {
        int number = 0;
        char *ptr = str;

        if ( *ptr == '-' ) {
          number = number - ( *++ptr - '0' );
          ptr++;
        }

        while ( isdigit ( *( ptr ) ) ){
          if ( number &lt; 0 ) {
            number = number * 10 - (*ptr++ - '0');
          }
          else
            number = number * 10 + (*ptr++ - '0');
        }

       return number;
   }

