        if (mutation < MUTATION_RATE) {
            /* Randomly choose a new DNA base: A, C, T, or G */
            int base = rand() % 4;

            /* Assign the corresponding character to the sequence */
            switch (base) {
                case 0:
                    sequence[i] = 'A';
                    break;
                case 1:
                    sequence[i] = 'C';
                    break;
                case 2:
                    sequence[i] = 'T';
                    break;
                case 3:
                    sequence[i] = 'G';
                    break;
            }
        }
    }
}

