#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define MAX_TEXT_LENGTH 1024
#define PROMPT_TEXT_LENGTH 128
#define NUM_PROMPTS 5

char* prompts[NUM_PROMPTS] = {
    "In the neon-lit streets, the shadows whisper secrets.",
    "Hack the mainframe, break through the digital gates.",
    "The city never sleeps, and neither do we.",
    "Time flows differently in the dark alleys of Neo-Tokyo.",
    "With every keystroke, we rewrite destiny."
};

void display_art() {
    printf("\n");
    printf("          .--.             .-.\n");
    printf("         |o_o |           | |   .--.\n");
    printf("         |:_/ |           | |  (    )\n");
    printf("        //   \\ \\          | |   `--'\n");
    printf("       (|     |)         /   \n");
    printf("      /'\\_   _/`\\_      |     Typing Speed Test\n");
    printf("      \\___)=(___/       |    Cyberpunk Style\n");
    printf("\n");
}

void shuffle_prompts() {
    for (int i = 0; i < NUM_PROMPTS; i++) {
        int j = rand() % NUM_PROMPTS;
        char* temp = prompts[i];
        prompts[i] = prompts[j];
        prompts[j] = temp;
    }
}

void take_typing_test() {
    char input[MAX_TEXT_LENGTH];
    char *selected_prompt = prompts[rand() % NUM_PROMPTS];

    printf("\nType the following prompt:\n");
    printf("\"%s\"\n\n", selected_prompt);

    clock_t start_time = clock();

    // Getting Input
    printf("> ");

    // Using a limited buffer to prevent overflow
    fgets(input, MAX_TEXT_LENGTH, stdin);

    clock_t end_time = clock();

    // Calculate elapsed time
    double time_taken = ((double)(end_time - start_time)) / CLOCKS_PER_SEC;

    // Remove newline character from the input
    input[strcspn(input, "\n")] = 0;

    printf("\nResults:\n");
    if (strcmp(input, selected_prompt) == 0) {
        int words_count = 0;

        // Count words in the prompt
        char *token = strtok(selected_prompt, " ");
        while (token) {
            words_count++;
            token = strtok(NULL, " ");
        }

        double wpm = (words_count / time_taken) * 60; // words per minute

        printf("Congratulations! You typed it correctly.\n");
        printf("Your speed: %.2f words per minute\n", wpm);
    } else {
        printf("Oops! Your input does not match the prompt.\n");
    }
}

int main() {
    srand(time(NULL)); 
    display_art();

    char choice;
    do {
        shuffle_prompts();
        take_typing_test();

        printf("\nDo you want to try again? (y/n): ");
        choice = getchar();
        while (getchar() != '\n'); // clear input buffer

    } while (choice == 'y' || choice == 'Y');

    printf("\nThanks for participating! Stay unbreakable in the matrix.\n");
    return 0;
}

