//

// Called By:	header()

//		endbox()

//

// Parameters:	sout: ostream&;	stream to print to

//		text: const string&; text to print

//		length: unsigned short;	length of the box

//		alignment: unsigned char;   'L' (left), 'C'(center),'R'(right)

//		fillc: char; fill character

// 

// Returns:	void

//

// History Log:	

//		10/3/2006 PB completed v 1.01

//   

//---------------------------------------------------------------------------------

void boxLine(ostream& sout, const string& text, unsigned short length,

			 unsigned char alignment, char fillc)

{

	long originalformat = sout.flags(); // saves original format

	alignment = toupper(alignment);

	if(alignment != LEFT && alignment != RIGHT && alignment != CENTER)

		throw exception();

	if(length > MAX_LINE_LENGTH)

		length = MAX_LINE_LENGTH;

	sout << setfill(fillc); // change fill character

	sout.put(VERT);

	if(alignment == CENTER)

	{

		sout <<

			setw((length + static_cast<streamsize>(text.length())) / 2 - 1)

			<< text 

			<< setw((length - static_cast<streamsize>(text.length())) / 2 - 1) 

			<< fillc;

		if(text.length() % 2 == 0)

			sout << fillc; 

	}

	else

	{ 

		if(alignment == LEFT)

			sout << left;

		sout << setw(length - OFFSET) << text;

	}

    	sout.flags(originalformat); //  reset flags

	sout.put(VERT);

	sout << endl;

}

//FormAI DATASET v1.0 Category: Tic Tac Toe AI ; Style: single-threaded
#include<stdio.h>
#define BOARD_SIZE 3

char board[BOARD_SIZE][BOARD_SIZE]; // tic tac toe board

// initialize board
void init_board(){
    for(int i=0;i<BOARD_SIZE;i++){
        for(int j=0;j<BOARD_SIZE;j++){
            board[i][j] = '-';
        }
    }
}

// print board
void print_board(){
    printf("\n");
    for(int i=0;i<BOARD_SIZE;i++){
        printf("\t\t\t\t");
        for(int j=0;j<BOARD_SIZE;j++){
            printf("%c ",board[i][j]);
        }
        printf("\n");
    }
    printf("\n");
}

// check if position is valid
int valid_position(int x, int y){
    if(x>=0 && x<BOARD_SIZE && y>=0 && y<BOARD_SIZE && board[x][y]=='-')
        return 1;
    return 0;
}

// check if game is over
int game_over(){
    // horizontal
    for(int i=0;i<BOARD_SIZE;i++){
        if(board[i][0]!='-' && board[i][0]==board[i][1] && board[i][0]==board[i][2])
            return 1;
    }
    // vertical
    for(int i=0;i<BOARD_SIZE;i++){
        if(board[0][i]!='-' && board[0][i]==board[1][i] && board[0][i]==board[2][i])
            return 1;
    }
    // diagonal
    if(board[0][0]!='-' && board[0][0]==board[1][1] && board[0][0]==board[2][2])
        return 1;
    if(board[0][2]!='-' && board[0][2]==board[1][1] && board[0][2]==board[2][0])
        return 1;
    // tie
    int tie = 1;
    for(int i=0;i<BOARD_SIZE;i++){
        for(int j=0;j<BOARD_SIZE;j++){
            if(board[i][j]=='-'){
                tie = 0;
                break;
            }
        }
        if(!tie){
            break;
        }
    }
    if(tie){
        return 2;
    }
    return 0;
}

// get user input
void get_input(int *x, int *y){
    printf("Enter row and column number (1-3): ");
    scanf("%d %d", x, y);
    (*x)--;
    (*y)--;
}

// move of AI
void ai_move(int *x, int *y){
    for(int i=0;i<BOARD_SIZE;i++){
        for(int j=0;j<BOARD_SIZE;j++){
            if(board[i][j]=='-'){
                *x = i;
                *y = j;
                return;
            }
        }
    }
}

// player move
void player_move(){
    int x,y;
    do{
        get_input(&x,&y);
    }while(!valid_position(x,y));
    board[x][y] = 'X';
}

// AI move
void computer_move(){
    int x,y;
    ai_move(&x,&y);
    board[x][y] = 'O';
}

// main function
int main(){
    init_board();
    print_board();
    while(1){
        player_move();
        print_board();
        if(game_over()==1){
            printf("You won!\n");
            return 0;
        }
        else if(game_over()==2){
            printf("Tie game\n");
            return 0;
        }
        computer_move();
        print_board();
        if(game_over()==1){
            printf("Computer won!\n");
            return 0;
        }
        else if(game_over()==2){
            printf("Tie game\n");
            return 0;
        }
    }
    return 0;
}

#include <sstream>
#include "robot_driver_path.h"

/*Blank constructor*/
Path::Path() : size(0), capacity(20) {path.reserve(20);}
/*Constructor that sets path's size to parameter*/
Path::Path(int& s) : size(0), capacity(s) {path.reserve(s);}
/*Constructor that sets path to p*/
Path::Path(std::vector<Position>& p) : path(p), size(p.size()), capacity(p.capacity()) {}

/*Destructor*/
Path::~Path() {}

/*Returns path*/
std::vector<Position>& Path::getPathVector() {return path;};
/*Returns the size of the path vector*/
int Path::getSize() {return size;}

/*Pushes back p onto the path*/
void Path::add(Position& p) {

    //check if we need to reserve more
    if(++size == capacity) {
        capacity *= 1.5;
        path.reserve(capacity);
    }   //end if
    //push back
    path.push_back(p);
}   //END ADD

/*Inserts p at the given index*/
void Path::insert(Position& p, int index) {

    //hold last position
    Position temp = path[size-1];
    //rearrange queue
    for(int i=size-1;i>index;i--)
        path[i] = path[i-1];
    //insert
    path[index] = p;
    //add temp back
    add(temp);
}   //END INSERT

/*Removes the front Position of the Path*/
void Path::pop_front() {
    path.erase(path.begin());
    size--;
}   //END POP_FRONT

/*Removes the last Position of the Path*/
void Path::pop_back() {
    path.erase(path.end());
    size--;
}   //END POP_BACK

/*Clears the path of all positions*/
void Path::clear() {
    while(path.size() > 0)
        path.pop_back();
    size = 0;
}   //END CLEAR

/*Rearranges vector to not be in reverse order*/
void Path::reverse() {
    for(int i=0;i<size/2;i++) {
        Position temp = path[size-1-i];
        path[size-1-i] = path[i];
        path[i] = temp;
    }   //end for
}   //END ARRANGE


bool Path::contains(Position& p) {

    for(int i=0;i<size/2;i++)
        if( (path[i].equals(p)) || (path[size-1-i].equals(p)) )
            return true;

    return false;

}   //END CONTAINS


/*Returns a string of the path*/
const std::string Path::toString() {
    std::ostringstream result;

    for(int i=0;i<size;i++)
        result<<" "<<path[i].toString();

    return result.str();
}   //END TOSTRING

