//GPT-4o-mini DATASET v1.0 Category: Procedurally Generated Maze ; Style: minimalist
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define WIDTH 20
#define HEIGHT 10
#define WALL '#'
#define PATH ' '

char maze[HEIGHT][WIDTH];

void initializeMaze() {
    for (int y = 0; y < HEIGHT; y++) {
        for (int x = 0; x < WIDTH; x++) {
            maze[y][x] = WALL;
        }
    }
}

void carvePath(int x, int y) {
    int dx[] = {2, -2, 0, 0}; // Directions for x
    int dy[] = {0, 0, 2, -2}; // Directions for y

    maze[y][x] = PATH; // Mark as PATH

    // Shuffle directions
    for (int i = 0; i < 4; i++) {
        int j = rand() % 4;
        int tempX = dx[i];
        int tempY = dy[i];
        dx[i] = dx[j];
        dy[i] = dy[j];
        dx[j] = tempX;
        dy[j] = tempY;
    }

    for (int i = 0; i < 4; i++) {
        int newX = x + dx[i];
        int newY = y + dy[i];

        if (newX > 0 && newX < WIDTH && newY > 0 && newY < HEIGHT && maze[newY][newX] == WALL) {
            maze[y + dy[i] / 2][x + dx[i] / 2] = PATH; // Carve between
            carvePath(newX, newY);
        }
    }
}

void printMaze() {
    for (int y = 0; y < HEIGHT; y++) {
        for (int x = 0; x < WIDTH; x++) {
            putchar(maze[y][x]);
        }
        putchar('\n');
    }
}

int main() {
    srand(time(NULL));
    initializeMaze();
    carvePath(1, 1); // Start carving from (1, 1)
    printMaze();
    return 0;
}

