//GEMINI-pro DATASET v1.0 Category: Tic Tac Toe AI ; Style: realistic
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define BOARD_SIZE 3

char board[BOARD_SIZE][BOARD_SIZE];

bool is_valid_move(int row, int col) {
    return row >= 0 && row < BOARD_SIZE && col >= 0 && col < BOARD_SIZE && board[row][col] == ' ';
}

void make_move(int row, int col, char player) {
    board[row][col] = player;
}

bool is_winner(char player) {
    // Check rows
    for (int i = 0; i < BOARD_SIZE; i++) {
        if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
            return true;
        }
    }

    // Check columns
    for (int i = 0; i < BOARD_SIZE; i++) {
        if (board[0][i] == player && board[1][i] == player && board[2][i] == player) {
            return true;
        }
    }

    // Check diagonals
    if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
        return true;
    }

    if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
        return true;
    }

    return false;
}

bool is_tie() {
    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[i][j] == ' ') {
                return false;
            }
        }
    }

    return true;
}

void print_board() {
    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            printf("%c ", board[i][j]);
        }
        printf("\n");
    }
}

int minimax(char player, int depth) {
    // Check if the game is over
    if (is_winner('X')) {
        return -1;
    } else if (is_winner('O')) {
        return 1;
    } else if (is_tie()) {
        return 0;
    }

    // Maximize for X and minimize for O
    int best_score = player == 'X' ? -999 : 999;

    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (is_valid_move(i, j)) {
                // Make the move
                make_move(i, j, player);

                // Recursively call minimax to get the score of the next move
                int score = minimax(player == 'X' ? 'O' : 'X', depth + 1);

                // Update the best score
                if (player == 'X') {
                    best_score = fmax(best_score, score);
                } else {
                    best_score = fmin(best_score, score);
                }

                // Undo the move
                make_move(i, j, ' ');
            }
        }
    }

    return best_score;
}

int get_best_move(char player) {
    // Initialize the best move to -1
    int best_move = -1;

    // Initialize the best score to -999
    int best_score = -999;

    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (is_valid_move(i, j)) {
                // Make the move
                make_move(i, j, player);

                // Recursively call minimax to get the score of the next move
                int score = minimax(player == 'X' ? 'O' : 'X', 0);

                // Update the best move and score if the current move is better
                if (player == 'X') {
                    if (score > best_score) {
                        best_move = i * BOARD_SIZE + j;
                        best_score = score;
                    }
                } else {
                    if (score < best_score) {
                        best_move = i * BOARD_SIZE + j;
                        best_score = score;
                    }
                }

                // Undo the move
                make_move(i, j, ' ');
            }
        }
    }

    return best_move;
}

int main() {
    // Initialize the board
    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            board[i][j] = ' ';
        }
    }

    // Get the player's name
    char player_name[20];
    printf("Enter your name: ");
    scanf("%s", player_name);

    // Let the player choose their symbol
    char player_symbol;
    printf("Choose your symbol (X or O): ");
    scanf(" %c", &player_symbol);

    // Get the computer's symbol
    char computer_symbol = player_symbol == 'X' ? 'O' : 'X';

    // Game loop
    while (true) {
        // Print the board
        print_board();

        // Get the player's move
        int row, col;
        printf("%s's turn (row, col): ", player_name);
        scanf("%d %d", &row, &col);

        // Check if the move is valid
        while (!is_valid_move(row, col)) {
            printf("Invalid move. Try again: ");
            scanf("%d %d", &row, &col);
        }

        // Make the move
        make_move(row, col, player_symbol);

        // Check if the player has won
        if (is_winner(player_symbol)) {
            printf("%s wins!\n", player_name);
            break;
        }

        // Check if the game is a tie
        if (is_tie()) {
            printf("Tie game!\n");
            break;
        }

        // Get the computer's move
        int computer_move = get_best_move(computer_symbol);
