            else
                printf(" ");
        }
        printf("\n");
    }
    for (i = 0; i < 60; i++)
        printf("#");
    printf("\n");
}

/* update ball position */
void update_ball() {
    ball_x += ball_velocity_x;
    ball_y += ball_velocity_y;
    if (ball_x == 1 || ball_x == 58) {
        if (ball_y >= paddle1_y && ball_y <= paddle1_y + 2) {
