#define MAX_ELEMENTS 118
#define MAX_ATTEMPTS 10

struct element {
    char name[20];
    char symbol[3];
    int atomic_number;
    int group;
    int period;
};

void initialize_elements(struct element elements[]) {
    int i;
    for (i = 0; i < MAX_ELEMENTS; i++) {
        elements[i].name[0] = '\0';
        elements[i].symbol[0] = '\0';
        elements[i].atomic_number = 0;
        elements[i].group = 0;
        elements[i].period = 0;
    }
}

void read_elements(FILE *fp, struct element elements[]) {
    int i = 0;
    char line[80];
    while (fgets(line, sizeof(line), fp)!= NULL) {
        if (i >= MAX_ELEMENTS) {
            break;
        }
        sscanf(line, "%s %s %d %d %d", elements[i].name, elements[i].symbol, &elements[i].atomic_number, &elements[i].group, &elements[i].period);
        i++;
    }
}

int main() {
    struct element elements[MAX_ELEMENTS];
    initialize_elements(elements);
    FILE *fp = fopen("elements.txt", "r");
    if (fp == NULL) {
        printf("Error: Could not open elements file.\n");
        exit(1);
    }
    read_elements(fp, elements);
    fclose(fp);

    int num_attempts = 0;
    int correct_answers = 0;
    while (num_attempts < MAX_ATTEMPTS) {
        int random_index = rand() % MAX_ELEMENTS;
        struct element random_element = elements[random_index];
        printf("Question %d:\n", num_attempts + 1);
        printf("Name: %s\n", random_element.name);
        printf("Symbol: %s\n", random_element.symbol);
        printf("Atomic Number: %d\n", random_element.atomic_number);
        printf("Group: %d\n", random_element.group);
        printf("Period: %d\n", random_element.period);
