        scanf("%s", answer);
        if (strcmp(answer, random_element.name) == 0) {
            correct_answers++;
        }
        num_attempts++;
    }
    printf("You got %d out of %d correct.\n", correct_answers, MAX_ATTEMPTS);
    return 0;
}

