    if (n == 0)
        return 1;

    // No solution
    if (n < 0)
        return 0;

    // No more coins exist but sum > 0
    if (m <= 0 && n >= 1)
        return 0;

    // Count = sum of solutions when mth element is included and when it isn't
    return count(S, m-1, n) + count(S, m, n-S[m-1]);
}

