//GEMINI-pro DATASET v1.0 Category: Game of Life ; Style: automated
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Size of the game board
#define SIZE 20

// Number of generations to simulate
#define GENERATIONS 100

// Probability of a cell being alive at the start of the simulation
#define PROBABILITY 0.5

// Create the game board
int board[SIZE][SIZE];

// Initialize the game board with random values
void init_board() {
  for (int i = 0; i < SIZE; i++) {
    for (int j = 0; j < SIZE; j++) {
      board[i][j] = (rand() < RAND_MAX * PROBABILITY) ? 1 : 0;
    }
  }
}

// Print the game board
void print_board() {
  for (int i = 0; i < SIZE; i++) {
    for (int j = 0; j < SIZE; j++) {
      printf("%d ", board[i][j]);
    }
    printf("\n");
  }
}

// Count the number of living neighbors of a cell
int count_neighbors(int x, int y) {
  int count = 0;
  for (int i = x - 1; i <= x + 1; i++) {
    for (int j = y - 1; j <= y + 1; j++) {
      if (i >= 0 && i < SIZE && j >= 0 && j < SIZE && !(i == x && j == y) && board[i][j]) {
        count++;
      }
    }
  }
  return count;
}

// Update the game board based on the rules of the Game of Life
void update_board() {
  int new_board[SIZE][SIZE];
  for (int i = 0; i < SIZE; i++) {
    for (int j = 0; j < SIZE; j++) {
      int neighbors = count_neighbors(i, j);
      if (board[i][j]) {
        new_board[i][j] = (neighbors == 2 || neighbors == 3) ? 1 : 0;
      } else {
        new_board[i][j] = (neighbors == 3) ? 1 : 0;
      }
    }
  }
  for (int i = 0; i < SIZE; i++) {
    for (int j = 0; j < SIZE; j++) {
      board[i][j] = new_board[i][j];
    }
  }
}

// Main function
int main() {
  // Seed the random number generator
  srand(time(NULL));

  // Initialize the game board
  init_board();

  // Print the initial game board
  printf("Initial game board:\n");
  print_board();

  // Simulate the game of life for a number of generations
  for (int i = 0; i < GENERATIONS; i++) {
    // Update the game board
    update_board();

    // Print the updated game board
    printf("\nGeneration %d:\n", i + 1);
    print_board();
  }

  return 0;
}

//FormAI DATASET v1.0 Category: Public-Key Algorithm Implementation ; Style: grateful
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <math.h>
#include <string.h>

#define PRIME_LEN 64
#define MESSAGE_SIZE 200

typedef unsigned long long uint64_t;
typedef unsigned int uint32_t; 

uint64_t gcd(uint64_t a, uint64_t b)
{
    if(b == 0) 
        return a;
    return gcd(b, a % b); 
}

int is_prime(uint64_t n)
{
    uint64_t i;

    if(n < 2)
        return 0;

    for(i=2;i*i<=n;i++)
        if(n % i == 0)
            return 0;
    return 1;
}

uint64_t random_prime()
{
    uint64_t p;
    do
    {
        p = rand();
        p = (p << 32) | rand();
        p = (p & ~1) | 1; 
    }
    while(!is_prime(p)); 
    return p;
}

uint64_t mod_pow(uint64_t base, uint64_t exponent, uint64_t modulus)
{
    uint64_t result = 1;
    while(exponent > 0)
    {   
        if(exponent & 1)
            result = (result * base) % modulus;
        base = (base * base) % modulus;
        exponent >>= 1;
    }
    return result; 
}

int main()
{
    uint64_t p, q, n, phi, e, d, m, c;
    char message[MESSAGE_SIZE];
    printf("Enter message: ");
    fgets(message, MESSAGE_SIZE, stdin);
    printf("Message: %s\n", message);
    printf("Generating primes...\n");
    srand((unsigned int)time(NULL));
    p = random_prime();
    q = random_prime();
    printf("p = %lld, q = %lld\n", p, q);
    n = p*q;
    phi = (p - 1) * (q - 1);
    printf("n = %lld, phi = %lld\n", n, phi);
    do
        e = rand() % phi;
    while(gcd(e, phi) != 1); 
    printf("Public key: {%lld, %lld}\n", e, n);
    d = 1;
    while((d * e) % phi != 1) d++;
    printf("Private key: {%lld, %lld}\n", d, n);
    m = (uint64_t)message[0];
    printf("Message: %lld\n", m);
    c = mod_pow(m, e, n);
    printf("Encrypted message: %lld\n", c);
    m = mod_pow(c, d, n);
    printf("Decrypted message: %lld\n", m);
    printf("Decrypted message as text: %c\n", (char)m);
    return 0;
}

//GEMINI-pro DATASET v1.0 Category: Smart home automation ; Style: all-encompassing
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define MAX_DEVICES 10

typedef struct {
    char *name;
    int type; // 0: light, 1: outlet, 2: thermostat
    int state; // 0: off, 1: on
} device;

device devices[MAX_DEVICES];

int main() {
    // Initialize devices
    devices[0].name = "Living Room Light";
    devices[0].type = 0;
    devices[0].state = 0;

    devices[1].name = "Kitchen Outlet";
    devices[1].type = 1;
    devices[1].state = 1;

    devices[2].name = "Upstairs Thermostat";
    devices[2].type = 2;
    devices[2].state = 72;

    // Main loop
    while (1) {
        // Get user input
        char input[100];
        printf("> ");
        fgets(input, sizeof(input), stdin);

        // Tokenize input
        char *tokens[3];
        int num_tokens = 0;
        char *token = strtok(input, " ");
        while (token != NULL) {
            tokens[num_tokens++] = token;
            token = strtok(NULL, " ");
        }

        // Parse command
        if (strcmp(tokens[0], "on") == 0) {
            // Turn on device
            int device_index = atoi(tokens[1]);
            devices[device_index].state = 1;
            printf("%s turned on.\n", devices[device_index].name);
        } else if (strcmp(tokens[0], "off") == 0) {
            // Turn off device
            int device_index = atoi(tokens[1]);
            devices[device_index].state = 0;
            printf("%s turned off.\n", devices[device_index].name);
        } else if (strcmp(tokens[0], "status") == 0) {
            // Get device status
            int device_index = atoi(tokens[1]);
            if (devices[device_index].state == 0) {
                printf("%s is off.\n", devices[device_index].name);
            } else {
                printf("%s is on.\n", devices[device_index].name);
            }
        } else if (strcmp(tokens[0], "exit") == 0) {
            // Exit program
            break;
        } else {
            // Unknown command
            printf("Unknown command.\n");
        }
    }

    return 0;
}

//MISTRAL-7B DATASET v1.0 Category: Percolation Simulator ; Style: shocked
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <time.h>

#define WIDTH 10
#define HEIGHT 10

typedef struct {
    int x, y;
} point;

bool grid[HEIGHT][WIDTH];

void print_grid() {
    int i, j;
    printf("+----");
    for (i = 0; i < WIDTH; i++) {
        printf("--------");
    }
    printf("-\n");
    for (i = 0; i < HEIGHT; i++) {
        printf("| %2d ", i);
        for (j = 0; j < WIDTH; j++) {
            printf("%c| ", grid[i][j] ? "#" : ".");
        }
        printf("|\n");
        if (i < HEIGHT - 1) {
            printf("+----");
            for (j = 0; j < WIDTH; j++) {
                printf("--------");
            }
            printf("-\n");
        }
    }
}

void randomize_grid() {
    int i, j;
    srand(time(NULL));
    for (i = 0; i < HEIGHT; i++) {
        for (j = 0; j < WIDTH; j++) {
            grid[i][j] = rand() % 2;
        }
    }
}

void mark_cells(int x, int y) {
    if (x < 0 || x >= WIDTH || y < 0 || y >= HEIGHT) {
        return;
    }
    if (grid[y][x]) {
        return;
    }
    grid[y][x] = true;
    mark_cells(x + 1, y);
    mark_cells(x - 1, y);
    mark_cells(x, y + 1);
    mark_cells(x, y - 1);
}

int main() {
    int i, j;
    point p;
    bool percolated = false;

    randomize_grid();
    print_grid();

    for (i = 0; i < HEIGHT; i++) {
        for (j = 0; j < WIDTH; j++) {
            if (grid[i][j]) {
                p.x = j;
                p.y = i;
                mark_cells(p.x, p.y);
                percolated = true;
                break;
            }
        }
        if (percolated) {
            break;
        }
    }

    print_grid();

    return 0;
}

