                list->list[j] = list->list[j+1];
            }
            list->num_emails--;
            printf("\n%s removed from %s mailing list.", email, list->list_name);
            break;
        }
    }
    /*Email doesn't exist in the mailing list*/
    if(!found){
        printf("\n%s does not exist in %s mailing list.", email, list->list_name);
    }
}

