#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h> 
#include <sys/socket.h>
#include <netinet/in.h>

#define MAX_CLIENTS 5
#define BUFFER_SIZE 1024

int main(int argc, char *argv[]) {
    int sockfd, newsockfd, portno;
    socklen_t clilen;
    char buffer[BUFFER_SIZE];
    struct sockaddr_in serv_addr, cli_addr;
    int n, i, j;
    char * welcome_message = "Welcome to the Chat Server. Type 'QUIT' to exit.\n";
    fd_set read_fds, active_fds;
    int fdmax, listener;
    int client_fds[MAX_CLIENTS];
    char * client_names[MAX_CLIENTS];
    int num_clients = 0;

    if (argc < 2) {
        fprintf(stderr,"ERROR, no port provided\n");
        exit(1);
    }

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("ERROR opening socket");
        exit(1);
    }

    bzero((char *) &serv_addr, sizeof(serv_addr));
    portno = atoi(argv[1]);
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = htons(portno);

    if (bind(sockfd, (struct sockaddr *) &serv_addr,sizeof(serv_addr)) < 0) {
        perror("ERROR on binding");
        exit(1);
    }

    listen(sockfd, MAX_CLIENTS);

    FD_ZERO(&active_fds);
    FD_ZERO(&read_fds);
    FD_SET(sockfd, &active_fds);
    fdmax = sockfd;

    while(1) {
        read_fds = active_fds;
        if(select(fdmax + 1, &read_fds, NULL, NULL, NULL) == -1) {
            perror("ERROR selecting");
            exit(1);
        }
        for (i = 0; i <= fdmax; i++) {
            if (FD_ISSET(i, &read_fds)) {
                if (i == sockfd) {
                    clilen = sizeof(cli_addr);
                    newsockfd = accept(sockfd, (struct sockaddr *) &cli_addr, &clilen);
                    if (newsockfd < 0) {
                        perror("ERROR on accept");
                        exit(1);
                    }
                    if (num_clients >= MAX_CLIENTS) {
                        close(newsockfd);
                        continue;
                    }
                    client_fds[num_clients] = newsockfd;
                    num_clients++;
                    FD_SET(newsockfd, &active_fds);
                    if (newsockfd > fdmax) {
                        fdmax = newsockfd;
                    }
                    n = send(newsockfd, welcome_message, strlen(welcome_message), 0);
                    if (n < 0) {
                        perror("ERROR writing to socket");
                        exit(1);
                    }
                } else {
                    bzero(buffer,BUFFER_SIZE);
                    n = recv(i, buffer, BUFFER_SIZE, 0);
                    if (n <= 0) {
                        close(i);
                        FD_CLR(i, &active_fds);
                        for(j=0; j<num_clients; j++) {
                            if(client_fds[j] == i) {
                                num_clients--;
                                client_fds[j] = client_fds[num_clients];
                                client_names[j] = client_names[num_clients];
                            }
                        }
                    } else {
                        if(strncmp(buffer,"QUIT",4) == 0) {
                            close(i);
                            FD_CLR(i, &active_fds);
                            for(j=0; j<num_clients; j++) {
                                if(client_fds[j] == i) {
                                    num_clients--;
                                    client_fds[j] = client_fds[num_clients];
                                    client_names[j] = client_names[num_clients];
                                }
                            }
                        } else {
                            for(j=0; j<num_clients; j++) {
                                if(client_fds[j] != i) {
                                    char message[BUFFER_SIZE+20];
                                    bzero(message, BUFFER_SIZE+20);
                                    sprintf(message, "%s: %s\n", client_names[j], buffer);
                                    n = send(client_fds[j], message, strlen(message), 0);
                                    if (n < 0) {
                                        perror("ERROR writing to socket");
                                        exit(1);
                                    }
                                } else {
                                    if(client_names[j] == NULL) {
                                        client_names[j] = malloc(sizeof(char)*BUFFER_SIZE);
                                    }
                                    strcpy(client_names[j], buffer);
                                    char join_message[BUFFER_SIZE+20];
                                    bzero(join_message, BUFFER_SIZE+20);
                                    sprintf(join_message, "%s has joined the chat\n", client_names[j]);
                                    for(int k=0; k<num_clients; k++) {
                                        if(client_fds[k] != i) {
                                            n = send(client_fds[k], join_message, strlen(join_message), 0);
                                            if (n < 0) {
                                                perror("ERROR writing to socket");
                                                exit(1);
                                            }
                                        }
                                    }
                                }   
                            }
                        }
                    }
                }
            }
        }
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_BAGS 1000
#define MAX_WEIGHT 50
#define MAX_BELTS 10

typedef struct{
  char airline[10];
  int flight_number;
  int destination_gate;
  int num_bags;
  float total_weight;
  int bag_list[MAX_BAGS];
} Flight;

typedef struct{
  int belt_num;
  int num_bags;
  float total_weight;
  int bag_list[MAX_BAGS];
} Belt;

Flight flights[MAX_BELTS];
Belt belts[MAX_BELTS];
int lost_bag_count = 0;

void print_flight_info(int index){
  printf("Airline: %s\n", flights[index].airline);
  printf("Flight number: %d\n", flights[index].flight_number);
  printf("Destination gate: %d\n", flights[index].destination_gate);
  printf("Number of bags: %d\n", flights[index].num_bags);
  printf("Total weight: %.2f\n", flights[index].total_weight);
}

void print_belt_info(int index){
  printf("Belt number: %d\n", belts[index].belt_num);
  printf("Number of bags: %d\n", belts[index].num_bags);
  printf("Total weight: %.2f\n", belts[index].total_weight);
}

void add_bag_to_flight(int flight_index, int bag_id){
  if(flights[flight_index].num_bags == MAX_BAGS){
    printf("The flight is now full.\n");
    return;
  }

  flights[flight_index].bag_list[flights[flight_index].num_bags] = bag_id;
  flights[flight_index].num_bags++;
  printf("The bag has been added to the flight.\n");
}

void add_bag_to_belt(int belt_index, int bag_id, float bag_weight){
  if((belts[belt_index].num_bags == MAX_BAGS) || ((belts[belt_index].total_weight + bag_weight) > MAX_WEIGHT)){
    printf("The belt is now full or overweight.\n");
    return;
  }

  belts[belt_index].bag_list[belts[belt_index].num_bags] = bag_id;
  belts[belt_index].num_bags++;
  belts[belt_index].total_weight += bag_weight;
  printf("The bag has been added to the belt.\n");
}

void remove_bag_from_belt(int belt_index, int bag_index){
  if(belts[belt_index].num_bags == 0){
    printf("The belt is empty.\n");
    return;
  }

  int bag_id = belts[belt_index].bag_list[bag_index];
  float bag_weight = (float) (rand() % 50 + 1); //random bag weight between 1 to 50 pounds
  int flight_index = -1;

  for(int i = 0; i < MAX_BELTS; i++){
    for(int j = 0; j < flights[i].num_bags; j++){
      if(flights[i].bag_list[j] == bag_id){
        flight_index = i;
        break;
      }
    }
  }

  if(flight_index == -1){
    lost_bag_count++;
    printf("The bag is lost!\n");
  }
  else{
    flights[flight_index].num_bags--;
    flights[flight_index].total_weight -= bag_weight;
    printf("The bag has been loaded onto the plane.\n");
  }

  belts[belt_index].num_bags--;
  belts[belt_index].total_weight -= bag_weight;
  printf("The bag has been removed from the belt.\n");
}

void display_lost_bag_count(){
  printf("The number of lost bags is: %d\n", lost_bag_count);
}

int main(){
  //initialize belts
  for(int i = 0; i < MAX_BELTS; i++){
    belts[i].belt_num = i + 1;
    belts[i].num_bags = 0;
    belts[i].total_weight = 0;
  }

  //simulate two flights
  for(int i = 0; i < 2; i++){
    printf("Enter the airline: ");
    scanf("%s", flights[i].airline);
    printf("Enter the flight number: ");
    scanf("%d", &flights[i].flight_number);
    printf("Enter the destination gate: ");
    scanf("%d", &flights[i].destination_gate);

    printf("Enter the number of bags: ");
    scanf("%d", &flights[i].num_bags);

    for(int j = 0; j < flights[i].num_bags; j++){
      int bag_id = rand() % 1000 + 1; //random bag id between 1 to 1000
      float bag_weight = (float) (rand() % 50 + 1); //random bag weight between 1 to 50 pounds
      flights[i].bag_list[j] = bag_id;
      flights[i].total_weight += bag_weight;

      //add the bag to a random belt
      int belt_index = rand() % MAX_BELTS;
      add_bag_to_belt(belt_index, bag_id, bag_weight);
    }
  }

  //simulate belt operations
  bool running = true;
  int option, belt_index, bag_index;

  while(running){
    printf("\n\nBelt operations:\n");
    printf("-----------------\n");
    printf("1. Add bag to belt\n");
    printf("2. Remove bag from belt\n");
    printf("3. Display belt info\n");
    printf("4. Exit\n");
    printf("Choose an option: ");
    scanf("%d", &option);

    switch(option){
      case 1:
        printf("Enter the belt number: ");
        scanf("%d", &belt_index);
        printf("Enter the bag id: ");
        int bag_id;
        scanf("%d", &bag_id);
        printf("Enter the bag weight: ");
        float bag_weight;
        scanf("%f", &bag_weight);
        add_bag_to_belt(belt_index - 1, bag_id, bag_weight);
        break;
      case 2:
        printf("Enter the belt number: ");
        scanf("%d", &belt_index);
        printf("Enter the bag index: ");
        scanf("%d", &bag_index);
        remove_bag_from_belt(belt_index - 1, bag_index);
        break;
      case 3:
        printf("Enter the belt number: ");
        scanf("%d", &belt_index);
        print_belt_info(belt_index - 1);
        break;
      case 4:
        running = false;
        break;
      default:
        printf("Invalid option.\n");
        break;
    }
  }

  //display flight and lost bag info
  for(int i = 0; i < 2; i++){
    printf("\n\nFlight %d Info:\n", i+1);
    printf("-----------------\n");
    print_flight_info(i);
  }

  printf("\n\n");
  display_lost_bag_count();

  return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define BUFFER_SIZE 100

typedef enum {
    NULL_TYPE,
    BOOLEAN_TYPE,
    NUMBER_TYPE,
    STRING_TYPE,
    ARRAY_TYPE,
    OBJECT_TYPE
} json_type_t;

typedef struct jsonval {
    json_type_t type;
    union {
        int boolean_value;
        double number_value;
        char string_value[BUFFER_SIZE];
        struct jsonval* array_value;
        struct jsonpair* object_value;
    } data;
    struct jsonval* next;
} jsonval;

typedef struct jsonpair {
    char key[BUFFER_SIZE];
    struct jsonval* value;
    struct jsonpair* next;
} jsonpair;

jsonval* parse_value(const char** input);
jsonpair* parse_pair(const char** input);

jsonval* parse_array(const char** input) {
    jsonval* head = NULL;
    jsonval** tail = &head;
    (*input)++;
    while (**input != ']') {
        jsonval* val = parse_value(input);
        if (!val) {
            printf("Error: invalid array value.\n");
            return NULL;
        }
        *tail = val;
        tail = &val->next;
        if (**input == ',') {
            (*input)++;
        } else if (**input != ']') {
            printf("Error: expected ',' or ']', got '%c'\n", **input);
            return NULL;
        }
    }
    (*input)++;
    return head;
}

jsonval* parse_object(const char** input) {
    jsonpair* head = NULL;
    jsonpair** tail = &head;
    (*input)++;
    while (**input != '}') {
        jsonpair* pair = parse_pair(input);
        if (!pair) {
            printf("Error: invalid object pair.\n");
            return NULL;
        }
        *tail = pair;
        tail = &pair->next;
        if (**input == ',') {
            (*input)++;
        } else if (**input != '}') {
            printf("Error: expected ',' or '}', got '%c'\n", **input);
            return NULL;
        }
    }
    (*input)++;
    jsonval* obj = malloc(sizeof(jsonval));
    obj->type = OBJECT_TYPE;
    obj->data.object_value = head;
    return obj;
}

jsonval* parse_string(const char** input) {
    char str[BUFFER_SIZE] = "";
    (*input)++;
    char* ptr = str;
    while (**input != '"') {
        if (**input == '\\') {
            (*input)++;
            switch (**input) {
                case '\\':
                    *ptr++ = '\\';
                    break;
                case '"':
                    *ptr++ = '"';
                    break;
                case 'n':
                    *ptr++ = '\n';
                    break;
                default:
                    printf("Error: invalid escape character.\n");
                    return NULL;
            }
        } else {
            *ptr++ = **input;
        }
        (*input)++;
    }
    (*input)++;
    jsonval* str_val = malloc(sizeof(jsonval));
    str_val->type = STRING_TYPE;
    strcpy(str_val->data.string_value, str);
    return str_val;
}

jsonval* parse_number(const char** input) {
    char num[BUFFER_SIZE] = "";
    char* ptr = num;
    while (**input >= '0' && **input <= '9') {
        *ptr++ = **input;
        (*input)++;
    }
    if (**input == '.') {
        *ptr++ = '.';
        (*input)++;
        while (**input >= '0' && **input <= '9') {
            *ptr++ = **input;
            (*input)++;
        }
    }
    if (**input == 'e' || **input == 'E') {
        *ptr++ = **input;
        (*input)++;
        if (**input == '+' || **input == '-') {
            *ptr++ = **input;
            (*input)++;
        }
        while (**input >= '0' && **input <= '9') {
            *ptr++ = **input;
            (*input)++;
        }
    }
    jsonval* num_val = malloc(sizeof(jsonval));
    num_val->type = NUMBER_TYPE;
    num_val->data.number_value = strtod(num, NULL);
    return num_val;
}

jsonval* parse_boolean(const char** input) {
    jsonval* bool_val = malloc(sizeof(jsonval));
    bool_val->type = BOOLEAN_TYPE;
    if (**input == 't') {
        bool_val->data.boolean_value = 1;
        (*input) += 4;
    } else if (**input == 'f') {
        bool_val->data.boolean_value = 0;
        (*input) += 5;
    } else {
        printf("Error: invalid boolean value.\n");
        free(bool_val);
        return NULL;
    }
    return bool_val;
}

jsonval* parse_null(const char** input) {
    jsonval* null_val = malloc(sizeof(jsonval));
    null_val->type = NULL_TYPE;
    (*input) += 4;
    return null_val;
}

jsonval* parse_value(const char** input) {
    while (**input == ' ' || **input == '\t' || **input == '\n' || **input == '\r') {
        (*input)++;
    }
    switch (**input) {
        case '[':
            return parse_array(input);
        case '{':
            return parse_object(input);
        case '"':
            return parse_string(input);
        case '-':
        case '0' ... '9': // C99 feature
            return parse_number(input);
        case 't':
        case 'f':
            return parse_boolean(input);
        case 'n':
            return parse_null(input);
        default:
            printf("Error: invalid value.\n");
            return NULL;
    }
}

jsonpair* parse_pair(const char** input) {
    jsonpair* pair = malloc(sizeof(jsonpair));
    pair->value = NULL;
    (*input)++;
    char* ptr = pair->key;
    while (**input != '"') {
        *ptr++ = **input;
        (*input)++;
    }
    *ptr = '\0';
    (*input)++;
    if (**input != ':') {
        printf("Error: expected ':'.\n");
        free(pair);
        return NULL;
    }
    (*input)++;
    pair->value = parse_value(input);
    if (!pair->value) {
        free(pair);
        return NULL;
    }
    return pair;
}

void print_jsonval(jsonval* val, int depth) {
    switch (val->type) {
        case NULL_TYPE:
            printf("null");
            break;
        case BOOLEAN_TYPE:
            printf(val->data.boolean_value ? "true" : "false");
            break;
        case NUMBER_TYPE:
            printf("%f", val->data.number_value);
            break;
        case STRING_TYPE:
            printf("\"%s\"", val->data.string_value);
            break;
        case ARRAY_TYPE:
            printf("[");
            if (val->data.array_value) {
                print_jsonval(val->data.array_value, depth + 1);
                jsonval* curr = val->data.array_value->next;
                while (curr) {
                    printf(", ");
                    print_jsonval(curr, depth + 1);
                    curr = curr->next;
                }
            }
            printf("]");
            break;
        case OBJECT_TYPE:
            printf("{\n");
            if (val->data.object_value) {
                jsonpair* curr = val->data.object_value;
                while (curr) {
                    printf("%*s\"%s\": ", depth * 4, "", curr->key);
                    print_jsonval(curr->value, depth + 1);
                    if (curr->next) {
                        printf(",");
                    }
                    printf("\n");
                    curr = curr->next;
                }
            }
            printf("%*s}", (depth - 1) * 4, "");
            break;
    }
}

int main(void) {
    const char* input = "{\"name\":\"John Doe\",\"age\":42,\"is_male\":true,\"titles\":[\"Mr.\",\"Dr.\"]}";
    jsonval* root = parse_value(&input);
    if (root) {
        print_jsonval(root, 0);
        printf("\n");
    }
    return 0;
}

