// Structure to represent a point in 2D space
typedef struct Point {
    double x;
    double y;
} Point;

// Structure to represent a line segment
typedef struct LineSegment {
    Point p1;
    Point p2;
} LineSegment;

// Function to check if a point is on a line segment
int point_on_line_segment(Point p, LineSegment l) {
    return (p.x >= fmin(l.p1.x, l.p2.x) && p.x <= fmax(l.p1.x, l.p2.x) &&
            p.y >= fmin(l.p1.y, l.p2.y) && p.y <= fmax(l.p1.y, l.p2.y));
}

// Function to check if two line segments intersect
int line_segments_intersect(LineSegment l1, LineSegment l2) {
    // Check if the two line segments are parallel
    if ((l1.p1.x - l1.p2.x) * (l2.p1.y - l2.p2.y) == (l1.p1.y - l1.p2.y) * (l2.p1.x - l2.p2.x)) {
        return 0;
    }

    // Check if the two line segments intersect at a single point
    if (point_on_line_segment(l1.p1, l2) || point_on_line_segment(l1.p2, l2) ||
        point_on_line_segment(l2.p1, l1) || point_on_line_segment(l2.p2, l1)) {
        return 1;
    }

    // Check if the two line segments intersect at two points
    double x1 = l1.p1.x, y1 = l1.p1.y, x2 = l1.p2.x, y2 = l1.p2.y;
    double x3 = l2.p1.x, y3 = l2.p1.y, x4 = l2.p2.x, y4 = l2.p2.y;

    double den = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4);
    if (den == 0) {
        return 0;
    }

    double t = ((x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)) / den;
    double u = ((x2 - x1) * (y1 - y3) - (y2 - y1) * (x1 - x3)) / den;

    if (t >= 0 && t <= 1 && u >= 0 && u <= 1) {
        return 1;
    }

    return 0;
}

