            {
                temp[idx++] = a[i][j];
            }
        }
    }
    for(int i = 0; i < idx - 1; i++)
    {
        for(int j =  i + 1; j < idx; j++)
        {
            if(temp[i] > temp[j])
            {
                HoanVi(temp[i], temp[j]);
            }
        }
    }
    printf("\nXuat cac so nguyen to theo thu tu tang dan: \n");
