#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX 10

int main()
{
    char **maze = (char **)malloc(MAX * sizeof(char *));
    for (int i = 0; i < MAX; i++)
    {
        maze[i] = (char *)malloc(MAX * sizeof(char));
    }

    // Build the maze
    maze[0][0] = 'S';
    maze[0][1] = '+';
    maze[0][2] = '+';
    maze[1][0] = '+';
    maze[1][1] = '*';
    maze[1][2] = '+';
    maze[2][0] = '+';
    maze[2][1] = '+';
    maze[2][2] = 'T';

    // Find the route
    char **route = (char **)malloc(MAX * sizeof(char *));
    for (int i = 0; i < MAX; i++)
    {
        route[i] = (char *)malloc(MAX * sizeof(char));
    }

    route_finder(maze, route);

    // Print the route
    for (int i = 0; i < MAX; i++)
    {
        for (int j = 0; j < MAX; j++)
        {
            printf("%c ", route[i][j]);
        }
        printf("\n");
    }

    // Free memory
    for (int i = 0; i < MAX; i++)
    {
        free(maze[i]);
        free(route[i]);
    }
    free(maze);
    free(route);

    return 0;
}

void route_finder(char **maze, char **route)
{
    // Initialize the route
    for (int i = 0; i < MAX; i++)
    {
        for (int j = 0; j < MAX; j++)
        {
            route[i][j] = ' ';
        }
    }

    // Mark the start and end points
    route[0][0] = 'S';
    route[2][2] = 'T';

    // Create a queue
    int queue[MAX * MAX];
    int front = 0;
    int back = -1;
    queue[++back] = 0;
    queue[++back] = 0;

    // Breadth-first search
    while (front != back)
    {
        int current_x = queue[front] / MAX;
        int current_y = queue[front] % MAX;

        // Check if the cell is a wall or if the route has already been found
        if (maze[current_x][current_y] == '+' || route[current_x][current_y] != ' ')
        {
            continue;
        }

        // Mark the cell as visited
        route[current_x][current_y] = 'O';

        // Move in all directions
        for (int dx = -1; dx <= 1; dx++)
        {
            for (int dy = -1; dy <= 1; dy++)
            {
                // Check if the cell is within the bounds of the maze and if the route has not already been found
                if (current_x + dx >= 0 && current_x + dx < MAX && current_y + dy >= 0 && current_y + dy < MAX && maze[current_x + dx][current_y + dy] != '+' && route[current_x + dx][current_y + dy] == ' ')
                {
                    // Add the cell to the queue
                    queue[++back] = (current_x + dx) * MAX + (current_y + dy);
                }
            }
        }

        // Increment the front of the queue
        front++;
    }
}

