#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define LOG_FILE "log.txt"
#define MAX_LOG_SIZE 1024

typedef struct {
  char message[MAX_LOG_SIZE];
  int level;
} LogMessage;

void write_log_message(LogMessage* message) {
  FILE* file = fopen(LOG_FILE, "a");
  if (file == NULL) {
    printf("Error opening file %s\n", LOG_FILE);
    return;
  }
  fprintf(file, "%s\n", message->message);
  fclose(file);
}

void process_log_message(LogMessage* message) {
  switch (message->level) {
    case 0:
      printf("Info: %s\n", message->message);
      break;
    case 1:
      printf("Warning: %s\n", message->message);
      break;
    case 2:
      printf("Error: %s\n", message->message);
      break;
    default:
      printf("Unknown level: %d\n", message->level);
  }
}

int main() {
  LogMessage message;
  strcpy(message.message, "This is an info message");
  message.level = 0;
  write_log_message(&message);
  process_log_message(&message);

  strcpy(message.message, "This is a warning message");
  message.level = 1;
  write_log_message(&message);
  process_log_message(&message);

  strcpy(message.message, "This is an error message");
  message.level = 2;
  write_log_message(&message);
  process_log_message(&message);

  return 0;
}

