        if (strcmp(plugins[i].name, name) == 0) {
            // Free memory for the plugin
            free(plugins[i].name);
            free(plugins[i].description);

            // Shift the remaining plugins to fill the gap
            for (int j = i; j < size - 1; j++) {
                plugins[j] = plugins[j + 1];
            }
            size--;

            return size;
