#define MAX_PASSWORDS 10
#define MAX_ATTEMPTS 3

// Structure to store password information
struct password {
    char *username;
    char *password;
    int attempts;
};

// Function to generate a random password
void generate_password(struct password *password) {
    int i, j;
    char password_array[10];

    for (i = 0; i < 10; i++) {
        password_array[i] = 'a' + (rand() % 26);
    }

    password->password = malloc(10 * sizeof(char));
    strcpy(password->password, password_array);
}

// Function to check if the password is correct
int check_password(struct password *password, char *input) {
    int i, j;

    for (i = 0; i < strlen(password->password); i++) {
        if (password->password[i] != input[i]) {
            return 0;
        }
    }

    return 1;
}

// Function to store the password in the password list
void add_password(struct password **passwords, char *username, char *password) {
    struct password *new_password = malloc(sizeof(struct password));
    new_password->username = username;
    new_password->password = password;
    new_password->attempts = 0;

    // Add the new password to the end of the list
    *passwords = realloc(passwords, (sizeof(struct password) * (1 + sizeof(struct password) / sizeof(struct password))));
    passwords[sizeof(passwords) - 1] = new_password;
}

// Function to retrieve the password from the password list
struct password *get_password(struct password **passwords, char *username) {
    int i;

    for (i = 0; i < sizeof(passwords) / sizeof(struct password); i++) {
        if (strcmp(passwords[i]->username, username) == 0) {
            return passwords[i];
        }
    }

    return NULL;
}

// Function to check if the password is correct and increase the attempts
int check_and_increment_attempts(struct password **passwords, char *username, char *password) {
    struct password *password_struct = get_password(passwords, username);

    if (check_password(password_struct, password)) {
        password_struct->attempts++;
        return 1;
    } else {
        return 0;
    }
}

int main() {
    struct password *passwords[MAX_PASSWORDS];
    int i, attempts;

    // Initialize the password list
    for (i = 0; i < MAX_PASSWORDS; i++) {
        passwords[i] = NULL;
    }

    // Add some sample passwords to the list
    add_password(passwords, "user1", "password1");
    add_password(passwords, "user2", "password2");
    add_password(passwords, "user3", "password3");

    // Loop until the user enters a correct password
    while (1) {
        printf("Enter a username: ");
        char username[20];
        fgets(username, 20, stdin);

        // Check if the username is in the list
        struct password *password_struct = get_password(passwords, username);

        // If the username is in the list, check if the password is correct
        if (password_struct != NULL) {
            char password[20];
            printf("Enter a password: ");
            fgets(password, 20, stdin);

            if (check_and_increment_attempts(passwords, username, password)) {
                printf("Correct password! You have %d attempts left.\n", password_struct->attempts);
            } else {
                printf("Incorrect password. You have %d attempts left.\n", password_struct->attempts);
            }
        } else {
            printf("Username not found. Please try again.\n");
        }

        // Check if the user has exceeded the maximum number of attempts
        if (password_struct != NULL && password_struct->attempts >= MAX_ATTEMPTS) {
            printf("You have exceeded the maximum number of attempts. Please try again.");
        }
    }

    return 0;
}

