#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define NUM_CARS 100  // number of cars in simulation
#define MAX_SPEED 10  // maximum speed of cars in mph
#define MIN_SPEED 5   // minimum speed of cars in mph
#define SAFE_DISTANCE 10 // safe distance between cars in feet

typedef struct car {
  int x;  // current position of car in feet
  int v;  // current speed of car in mph
} car;

car cars[NUM_CARS];  // array of cars in simulation

void initialize_cars() {
  for (int i = 0; i < NUM_CARS; i++) {
    cars[i].x = rand() % 1000;  // initial position of car in feet
    cars[i].v = rand() % (MAX_SPEED - MIN_SPEED) + MIN_SPEED;  // initial speed of car in mph
  }
}

void update_cars() {
  for (int i = 0; i < NUM_CARS; i++) {
    // check if car is too close to car in front
    if (i > 0 && cars[i].x - cars[i - 1].x < SAFE_DISTANCE) {
      // slow down car
      cars[i].v = cars[i - 1].v;
    } else {
      // accelerate car
      cars[i].v += 1;
      if (cars[i].v > MAX_SPEED) {
        cars[i].v = MAX_SPEED;
      }
    }

    // update car's position
    cars[i].x += cars[i].v;
  }
}

void draw_cars() {
  for (int i = 0; i < NUM_CARS; i++) {
    printf("Car %d: x = %d, v = %d\n", i, cars[i].x, cars[i].v);
  }
}

int main() {
  srand(time(NULL));  // seed random number generator

  initialize_cars();

  for (int i = 0; i < 1000; i++) {
    update_cars();
    draw_cars();
  }

  return 0;
}

