#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LEN 100
#define MIN_LEN 3

// Declare a few functions
int count_words(char *str, int *count);
void print_result(int count);

int main(void) {
    // Declare a few variables
    char str[MAX_LEN + 1];
    int count = 0;

    // Get the input string from the user
    printf("Enter a string: ");
    fgets(str, MAX_LEN + 1, stdin);

    // Check if the string is valid
    if (strlen(str) < MIN_LEN) {
        printf("Invalid string. Please enter a string with at least %d characters.\n", MIN_LEN);
        return EXIT_FAILURE;
    }

    // Count the number of words in the string
    count_words(str, &count);

    // Print the result
    print_result(count);

    return EXIT_SUCCESS;
}

// Count the number of words in a string
int count_words(char *str, int *count) {
    // Initialize the word count to 0
    *count = 0;

    // Iterate over the string
    for (int i = 0; i < strlen(str); i++) {
        // If the current character is a space, increment the word count
        if (str[i] == ' ') {
            (*count)++;
        }
    }

    // Return the word count
    return *count;
}

// Print the result
void print_result(int count) {
    // Print the word count
    printf("The string contains %d words.\n", count);
}

