//GEMINI-pro DATASET v1.0 Category: Bingo Simulator ; Style: future-proof
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

// Define the bingo board size
#define BOARD_SIZE 5

// Define the number of balls to draw
#define BALLS_TO_DRAW 75

// Create a bingo board
int board[BOARD_SIZE][BOARD_SIZE];

// Create an array to store the balls drawn
int balls[BALLS_TO_DRAW];

// Create a function to initialize the bingo board
void initialize_board() {
  // Seed the random number generator
  srand(time(NULL));

  // Fill the board with random numbers
  for (int i = 0; i < BOARD_SIZE; i++) {
    for (int j = 0; j < BOARD_SIZE; j++) {
      board[i][j] = rand() % 75 + 1;
    }
  }
}

// Create a function to draw a ball
int draw_ball() {
  // Get a random number between 1 and 75
  int ball = rand() % 75 + 1;

  // Store the ball in the array of balls drawn
  balls[ball - 1] = true;

  // Return the ball
  return ball;
}

// Create a function to check if a player has won
bool check_win(int player_board[BOARD_SIZE][BOARD_SIZE]) {
  // Check for a horizontal win
  for (int i = 0; i < BOARD_SIZE; i++) {
    bool win = true;
    for (int j = 0; j < BOARD_SIZE; j++) {
      if (!player_board[i][j]) {
        win = false;
        break;
      }
    }
    if (win) {
      return true;
    }
  }

  // Check for a vertical win
  for (int i = 0; i < BOARD_SIZE; i++) {
    bool win = true;
    for (int j = 0; j < BOARD_SIZE; j++) {
      if (!player_board[j][i]) {
        win = false;
        break;
      }
    }
    if (win) {
      return true;
    }
  }

  // Check for a diagonal win
  bool win = true;
  for (int i = 0; i < BOARD_SIZE; i++) {
    if (!player_board[i][i]) {
      win = false;
      break;
    }
  }
  if (win) {
    return true;
  }

  win = true;
  for (int i = 0; i < BOARD_SIZE; i++) {
    if (!player_board[i][BOARD_SIZE - 1 - i]) {
      win = false;
      break;
    }
  }
  if (win) {
    return true;
  }

  // No win
  return false;
}

// Create a function to play a game of bingo
void play_bingo() {
  // Initialize the bingo board
  initialize_board();

  // Create a player board
  int player_board[BOARD_SIZE][BOARD_SIZE];

  // Copy the bingo board to the player board
  for (int i = 0; i < BOARD_SIZE; i++) {
    for (int j = 0; j < BOARD_SIZE; j++) {
      player_board[i][j] = false;
    }
  }

  // Draw balls until someone wins
  int ball;
  int winner = 0;
  int num_balls_drawn = 0;
  while (winner == 0 && num_balls_drawn < BALLS_TO_DRAW) {
    // Draw a ball
    ball = draw_ball();

    // Mark the ball on the player board
    for (int i = 0; i < BOARD_SIZE; i++) {
      for (int j = 0; j < BOARD_SIZE; j++) {
        if (board[i][j] == ball) {
          player_board[i][j] = true;
        }
      }
    }

    // Check if the player has won
    if (check_win(player_board)) {
      winner = 1;
    }

    num_balls_drawn++;
  }

  // Print the winning board
  if (winner == 1) {
    printf("Player has won after %d balls drawn!\n", num_balls_drawn);
    for (int i = 0; i < BOARD_SIZE; i++) {
      for (int j = 0; j < BOARD_SIZE; j++) {
        printf("%d ", player_board[i][j]);
      }
      printf("\n");
    }
  } else {
    printf("No winner after %d balls drawn!\n", num_balls_drawn);
  }
}

int main() {
  // Play a game of bingo
  play_bingo();

  return 0;
}

