// Structure for a particle
typedef struct {
    double x, y, z; // Position
    double vx, vy, vz; // Velocity
    double ax, ay, az; // Acceleration
} Particle;

// Function prototypes
void init_particles(Particle particles[]);
void update_particles(Particle particles[], double dt);
void print_particles(Particle particles[], int num_particles);

int main() {
    Particle particles[NUM_PARTICLES];
    init_particles(particles);

    double dt = 0.01; // Time step
    int num_steps = 100; // Number of simulation steps

    for (int i = 0; i < num_steps; i++) {
        update_particles(particles, dt);
        print_particles(particles, NUM_PARTICLES);
    }

    return 0;
}

// Initialize particle positions, velocities, and accelerations
void init_particles(Particle particles[]) {
    for (int i = 0; i < NUM_PARTICLES; i++) {
        particles[i].x = (double)i / NUM_PARTICLES * BOX_SIZE;
        particles[i].y = 0;
        particles[i].z = 0;

        particles[i].vx = 0;
        particles[i].vy = 0;
        particles[i].vz = 0;

        particles[i].ax = 0;
        particles[i].ay = 0;
        particles[i].az = 0;
    }
}

// Update particle positions, velocities, and accelerations
void update_particles(Particle particles[], double dt) {
    for (int i = 0; i < NUM_PARTICLES; i++) {
        // Gravity
        particles[i].ay = -9.8;

        // Damping
        particles[i].vx *= 0.9;
        particles[i].vy *= 0.9;
        particles[i].vz *= 0.9;

        // Update velocities
        particles[i].vx += particles[i].ax * dt;
        particles[i].vy += particles[i].ay * dt;
        particles[i].vz += particles[i].az * dt;

        // Update positions
        particles[i].x += particles[i].vx * dt;
        particles[i].y += particles[i].vy * dt;
        particles[i].z += particles[i].vz * dt;
    }
}

// Print particle positions
void print_particles(Particle particles[], int num_particles) {
    for (int i = 0; i < num_particles; i++) {
        printf("Particle %d: (%f, %f, %f)\n", i, particles[i].x, particles[i].y, particles[i].z);
    }
}

