#include<stdio.h>
#include<stdlib.h>
#include<string.h>
#include<ctype.h>

#define MAX_WORDS 1000
#define MAX_WORD_LENGTH 20

typedef struct {
    char english[MAX_WORD_LENGTH];
    char alien[MAX_WORD_LENGTH];
} Word;

int readWords(FILE *fp, Word words[]) {
    int count = 0;
    char line[MAX_WORD_LENGTH];

    while (fgets(line, MAX_WORD_LENGTH, fp)!= NULL) {
        if (count >= MAX_WORDS) {
            printf("Error: Too many words.\n");
            exit(1);
        }

        char *token = strtok(line, ",.?!;:");
        if (token == NULL)
            continue;

        strcpy(words[count].english, token);
        strcpy(words[count].alien, "");
        count++;
    }

    return count;
}

void translate(char english[], char alien[]) {
    int i;
    for (i = 0; english[i]!= '\0'; i++) {
        if (isalpha(english[i])) {
            alien[i] = english[i] + 5;
        } else if (isdigit(english[i])) {
            alien[i] = english[i] - 5;
        } else {
            alien[i] = english[i];
        }
    }
    alien[i] = '\0';
}

void writeWords(FILE *fp, Word words[]) {
    int i;

    for (i = 0; i < MAX_WORDS; i++) {
        if (words[i].english[0]!= '\0') {
            fprintf(fp, "%s %s\n", words[i].english, words[i].alien);
        }
    }
}

int main() {
    FILE *inputFile, *outputFile;
    Word words[MAX_WORDS];

    inputFile = fopen("input.txt", "r");
    if (inputFile == NULL) {
        printf("Error: Could not open input file.\n");
        exit(1);
    }

    int numWords = readWords(inputFile, words);

    for (int i = 0; i < numWords; i++) {
        translate(words[i].english, words[i].alien);
    }

    outputFile = fopen("output.txt", "w");
    if (outputFile == NULL) {
        printf("Error: Could not open output file.\n");
        exit(1);
    }

    writeWords(outputFile, words);

    fclose(inputFile);
    fclose(outputFile);

    return 0;
}

