    int temperature;  // Temperature in Celsius
    int humidity;    // Humidity as a percentage
} weather_t;

// Function to generate a random weather type
void generate_weather(weather_t *weather) {
    int i;
    for (i = 0; i < WEATHER_TYPES; i++) {
        weather->type[i] = "sunny";  // Initialize to sunny by default
        weather->temperature = (int)(rand() % 20) + 10;  // Generate a random temperature
        weather->humidity = (int)(rand() % 100);  // Generate a random humidity
    }
}

// Function to simulate a day
void simulate_day(weather_t *weather, int day) {
    int hour, minute;

    // Simulate the day from 6am to 10pm
    for (hour = 6; hour < 22; hour++) {
        for (minute = 0; minute < 60; minute += 15) {
            // Update the weather based on the current time
            if (hour < 12) {
                weather->temperature += (int)(rand() % 5) - 2;  // Cooler in the morning
