    }

    // display the array entered by the user
    displayArray( numbers , num );

    // call the merge sort procedure to sort the array
    doMergeSort( numbers , 0 , num - 1 );

    cout << "After Sorting ";
    // after calling merge sort display the array in sorted order
    displayArray( numbers , num );

    return 0;
}

