#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <errno.h>

#define BUFFER_SIZE 1024
#define SERVER_PORT 8080
#define SERVER_ADDR "127.0.0.1"

// Function to print error message and exit
void error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

// Function to send data to server
int send_data(int sock, const char *data) {
    return send(sock, data, strlen(data), 0);
}

// Function to receive data from server
int receive_data(int sock, char *buffer) {
    return recv(sock, buffer, BUFFER_SIZE, 0);
}

// Function to handle client requests
void handle_client(int client_sock) {
    char buffer[BUFFER_SIZE];
    while (1) {
        memset(buffer, 0, BUFFER_SIZE);
        int bytes_received = receive_data(client_sock, buffer);
        if (bytes_received <= 0) {
            break;
        }
        printf("Client message: %s\n", buffer);
        send_data(client_sock, "Server received your message!");
        memset(buffer, 0, BUFFER_SIZE);
    }
    close(client_sock);
}

int main() {
    int server_sock = socket(AF_INET, SOCK_STREAM, 0);
    if (server_sock == -1) {
        error("socket() failed");
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);
    server_addr.sin_addr.s_addr = inet_addr(SERVER_ADDR);

    if (connect(server_sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) == -1) {
        error("connect() failed");
    }

    while (1) {
        char buffer[BUFFER_SIZE];
        memset(buffer, 0, BUFFER_SIZE);
        int bytes_received = receive_data(server_sock, buffer);
        if (bytes_received <= 0) {
            break;
        }
        printf("Server message: %s\n", buffer);
        send_data(server_sock, "Client received your message!");
        memset(buffer, 0, BUFFER_SIZE);
    }

    close(server_sock);
    return 0;
}

