#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_PROCESSES 10
#define MAX_PROCESS_NAME_LENGTH 20
#define MAX_TIME_QUANTA 100

typedef struct process {
    int id;
    char name[MAX_PROCESS_NAME_LENGTH];
    int burst_time;
    int waiting_time;
    int turnaround_time;
    int remaining_burst_time;
} Process;

void initialize_processes(Process* processes, int num_processes) {
    for (int i = 0; i < num_processes; i++) {
        processes[i].id = i + 1;
        sprintf(processes[i].name, "Process %d", i + 1);
        processes[i].burst_time = rand() % MAX_TIME_QUANTA + 1;
        processes[i].waiting_time = 0;
        processes[i].turnaround_time = 0;
        processes[i].remaining_burst_time = processes[i].burst_time;
    }
}

void print_processes(Process* processes, int num_processes) {
    for (int i = 0; i < num_processes; i++) {
        printf("%d. %s: %d\n", i + 1, processes[i].name, processes[i].burst_time);
    }
}

void execute_process(Process* processes, int num_processes, int current_time) {
    int completed_processes_count = 0;
    for (int i = 0; i < num_processes; i++) {
        if (processes[i].remaining_burst_time > 0) {
            if (processes[i].remaining_burst_time <= MAX_TIME_QUANTA) {
                processes[i].remaining_burst_time = 0;
            } else {
                processes[i].remaining_burst_time -= MAX_TIME_QUANTA;
            }
            completed_processes_count++;
        }
    }
    if (completed_processes_count == 0) {
        printf("No process completed at time %d\n", current_time);
    } else {
        printf("%d process(es) completed at time %d\n", completed_processes_count, current_time);
    }
}

void schedule_processes(Process* processes, int num_processes, int quantum) {
    int current_time = 0;
    int completed_processes_count = 0;
    int total_waiting_time = 0;
    int total_turnaround_time = 0;
    while (completed_processes_count < num_processes) {
        execute_process(processes, num_processes, current_time);
        current_time += quantum;
    }
    printf("Total waiting time: %d\n", total_waiting_time);
    printf("Total turnaround time: %d\n", total_turnaround_time);
}

int main() {
    srand(time(NULL));

    Process processes[MAX_PROCESSES];
    int num_processes = 5;
    initialize_processes(processes, num_processes);
    print_processes(processes, num_processes);

    int quantum = 2;
    schedule_processes(processes, num_processes, quantum);

    return 0;
}

