#include "avl.hpp"

using namespace atod;

avl::avl() : root_ ( nullptr )
{
}

avl::~avl()
{
}

void avl::add ( int value )
{
    if ( isEmpty() )
    {
        root_ = new node ( value );
        return;
    }

    internalAdd ( root_, value );
}

void avl::internalAdd ( node* & n, int value )
{
    if ( n == nullptr )
    {
        n = new node ( value );
        return;
    }

    if ( value < n->value_ )
    {
        internalAdd ( n->left_, value );

        if ( height ( n->left_ ) - height ( n->right_ ) == 2 )
        {
            if ( value < n->left_->value_ )
            {
                node* promoted = n->left_;
                n->left_ = promoted->right_;

                promoted->right_ = n;
                n = promoted;
            }
            else
            {
                node* childL = n->left_;
                node* grandChildR = childL->right_;

                childL->right_ = grandChildR->left_;
                n->left_ = grandChildR->right_;
                grandChildR->left_ = childL;
                grandChildR->right_ = n;
                n = grandChildR;
            }
        }

    }
    else if ( value > n->value_ )
    {
        internalAdd ( n->right_, value );

        if ( height ( n->right_ ) - height ( n->left_ ) == 2 )
        {
            if ( value > n->right_->value_ )
            {
                node* promoted = n->right_;
                n->right_ = promoted->left_;

                promoted->left_ = n;
                n = promoted;
            }
            else
            {
                node* childR = n->right_;
                node* grandChildL = childR->left_;

                childR->left_ = grandChildL->right_;
                n->right_ = grandChildL->left_;
                grandChildL->left_ = n;
                grandChildL->right_ = childR;
                n = grandChildL;
            }
        }
    }

    // else the values are the same; don't add it again
}

size_t avl::height ( node* n )
{
    if ( n == nullptr )
        return 0;

    size_t left = height ( n->left_ );
    size_t right = height ( n->right_ );

    if ( left > right )
        return left + 1;
    else
        return right + 1;
}

bool avl::contains ( int value ) const
{
    node* curr = root_;

    while ( curr != nullptr )
    {
        if ( value < curr->value_ )
            curr = curr->left_;
        else if ( value > curr->value_ )
            curr = curr->right_;
        else
            return true;
    }

    return false;
}

void avl::print ( std::ostream& dest ) const
{
    internalPrint ( dest, root_, 0 );
}

void avl::internalPrint ( std::ostream& dest, const node* n, size_t depth )
{
    if ( n == nullptr )
        return;

    for ( size_t i = 0; i < depth; ++i )
        dest << " ";

    dest << n->value_ << std::endl;

    internalPrint ( dest, n->left_, depth + 1 );
    internalPrint ( dest, n->right_, depth + 1 );
}

avl::node::node ( int value ) : value_ ( value ),  left_ ( nullptr ), right_ ( nullptr )
{
}

avl::node::~node()
{
    if ( left_ != nullptr )
        delete left_;
    if ( right_ != nullptr )
        delete right_;
}

//MISTRAL-7B DATASET v1.0 Category: Text to ASCII art generator ; Style: modular
#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_LENGTH 20

void print_star(int size) {
    int i;
    for(i = 0; i < size; i++)
        putchar('*');
    putchar('\n');
}

void print_triangle(int size) {
    int i, j;
    for(i = 0; i < size; i++) {
        for(j = size - i; j > 0; j--)
            putchar(' ');
        for(j = 0; j <= i; j++)
            putchar('*');
        putchar('\n');
    }
}

void print_square(int size) {
    int i, j;
    for(i = 0; i < size; i++) {
        for(j = 0; j < size; j++)
            putchar('*');
        putchar('\n');
    }
}

void print_smile(int size) {
    int i;
    print_triangle(size / 2);
    for(i = 0; i < size; i++)
        putchar('*');
    putchar('\n');
    print_triangle(size / 2);
    putchar('O');
    putchar('\n');
    print_triangle(size / 2 - 1);
}

void text_to_ascii(char text[MAX_LENGTH]) {
    int length = strlen(text);
    if(length > MAX_LENGTH) {
        printf("Error: Text length exceeds maximum allowed length.\n");
        return;
    }

    char first_char = text[0];
    first_char = toupper(first_char);

    switch(first_char) {
        case 'S':
            print_smile(length * 2);
            break;
        case 'T':
            print_star(length * 2);
            break;
        case 'Q':
            print_square(length * 2);
            break;
        case 'P':
            print_triangle(length);
            break;
        default:
            printf("Error: Unsupported character.\n");
            return;
    }
}

int main(void) {
    char text[MAX_LENGTH];

    printf("Enter text: ");
    fgets(text, sizeof(text), stdin);
    text_to_ascii(text);

    return 0;
}

