    if (!focus)
    {
        image = _unselected_icon;
    }
    else
    {
        image = _selected_icon;
    }
    int widthOffset = image->width()/2;
    int heightOffset = image->height()/2;

    QPoint imageOrigin(x - widthOffset, y - heightOffset);
