// Function to validate if a string is a number
int is_number(char *str) {
    int len = strlen(str);
    for (int i = 0; i < len; i++) {
        if (!isdigit(str[i])) {
            return 0;
        }
    }
    return 1;
}

// Function to calculate mortgage payment
double calculate_mortgage_payment(double loan_amount, double interest_rate, int loan_term) {
    // Formula: P = L[c(1 + c)^n]/[(1 + c)^n - 1]
    // where P is the monthly payment, L is the loan amount, c is the monthly interest rate,
    // and n is the number of payments (loan term * 12)
    double monthly_interest_rate = interest_rate / 1200; // Convert annual interest rate to monthly
    int num_payments = loan_term * 12;
    double payment = loan_amount * monthly_interest_rate * pow(1 + monthly_interest_rate, num_payments) / (pow(1 + monthly_interest_rate, num_payments) - 1);
    return payment;
}

// Function to print mortgage payment details
void print_mortgage_details(double loan_amount, double interest_rate, int loan_term, double payment) {
    printf("Loan Amount: $%.2f\n", loan_amount);
    printf("Interest Rate: %.2f%%\n", interest_rate);
