// Function to send data to a socket
void send_data(int socket, char* message) {
    int bytes_sent = 0;
    while ((bytes_sent = send(socket, message, strlen(message), 0)) == -1) {
        perror("Error sending data");
    }
}

// Function to receive data from a socket
int receive_data(int socket) {
    char buffer[1024];
    int bytes_read = 0;
    while ((bytes_read = recv(socket, buffer, sizeof(buffer), 0)) == -1) {
        perror("Error receiving data");
    }
    return bytes_read;
}

int main() {
    int server_socket, client_socket, port, n;
    struct sockaddr_in server_address, client_address;
    char buffer[1024];

    // Create a server socket
    if ((server_socket = socket(AF_INET, SOCK_STREAM, 0)) == -1) {
        perror("Error creating server socket");
        return 1;
    }

    // Set up the server address
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(8080);

    // Bind the server socket to the address
    if (bind(server_socket, (struct sockaddr *)&server_address, sizeof(server_address)) == -1) {
        perror("Error binding server socket");
        return 1;
    }

    // Start listening for connections
    if (listen(server_socket, 5) == -1) {
        perror("Error listening on server socket");
        return 1;
    }

    printf("Listening for connections...\n");

    // Accept a connection from a client
    client_socket = accept(server_socket, (struct sockaddr *)&client_address, (socklen_t*)&n);

    if (client_socket == -1) {
        perror("Error accepting client connection");
        return 1;
    }

    printf("Connection accepted from %s:%d\n", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));

    // Send a message to the client
    send_data(client_socket, "Hello, client!\n");

    // Receive a message from the client
    n = receive_data(client_socket);
    printf("Received %d bytes from client: %s\n", n, buffer);

    // Close the client socket
    close(client_socket);

    // Close the server socket
    close(server_socket);

    return 0;
}

