            printf("%d ", board[x][y]);
        }
        printf("\n");
    }

    // Game loop
    while(!board[MAX_WIDTH - 1][MAX_HEIGHT - 1])
    {
        // Get the player's move
        int move = getchar();

        // Validate the move
        if(move < 1 || move > MAX_WIDTH * MAX_HEIGHT)
        {
            printf("Invalid move.\n");
            continue;
        }

        // Make the move
        int x = (move - 1) % MAX_WIDTH;
        int y = (move - 1) / MAX_WIDTH;
        board[x][y] = 1;

        // Print the updated game board
        for(int y = 0; y < MAX_HEIGHT; y++)
        {
            for(int x = 0; x < MAX_WIDTH; x++)
            {
                printf("%d ", board[x][y]);
            }
            printf("\n");
        }

        // Check if the player has won
        if(board[MAX_WIDTH - 1][MAX_HEIGHT - 1] == 1)
        {
            printf("You win!\n");
            break;
        }
    }

    // Game over
    printf("Game over.\n");

    return 0;
}

