#define MAX_LINE_LENGTH 1024
#define NUM_MONTHS 360

// Struct to store mortgage details
typedef struct mortgage {
    double principal;
    double annual_rate;
    int num_years;
} mortgage;

// Function to calculate mortgage payment using Ritschier formula
double calculate_payment(mortgage mortgage) {
    const double monthly_rate = pow(1.0 + mortgage.annual_rate / 100.0 / 12.0, -NUM_MONTHS);
    return mortgage.principal * monthly_rate * (mortgage.annual_rate / 100.0 / 12.0);
}

// Function to read mortgage details from command line arguments
mortgage read_mortgage_args(int argc, char *argv[]) {
    mortgage mortgage;

    if (argc != 4) {
        fprintf(stderr, "Usage: %s PRINCIPAL ANNUAL_RATE NUM_YEARS\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    mortgage.principal = atof(argv[1]);
    mortgage.annual_rate = atof(argv[2]);
    mortgage.num_years = atoi(argv[3]);

    return mortgage;
}

