  for (int i = 0; i < 8; i++) {
    for (int j = 0; j < 8; j++) {
      if (board[i][j] == player) {
        printf("P");
      } else if (board[i][j] == computer) {
        printf("C");
      } else {
        printf(" ");
      }
    }
    printf("\n");
  }
}

