void make_move(int x, int y) {
  board[x][y] = player;
  player = 3 - player;
  computer = 3 - computer;
  print_board();
}

// Function to check for win
int check_win() {
  for (int i = 0; i < 8; i++) {
    for (int j = 0; j < 8; j++) {
      if (board[i][j] == player) {
        return 1;
      }
    }
  }
  return 0;
}

