#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#define PI 3.1415926535897932384626433832795

typedef struct { double x, y; } point;

point midpoint(point p1, point p2) {
  point res;
  res.x = (p1.x + p2.x) / 2;
  res.y = (p1.y + p2.y) / 2;
  return res;
}

double distance(point p1, point p2) {
  double dx = p1.x - p2.x;
  double dy = p1.y - p2.y;
  return sqrt(dx * dx + dy * dy);
}

void scale(point *p, double sx, double sy) {
  p->x *= sx;
  p->y *= sy;
}

void translate(point *p, double tx, double ty) {
  p->x += tx;
  p->y += ty;
}

void rotate(point *p, double angle) {
  double rad = angle * PI / 180;
  double x = p->x;
  double y = p->y;
  p->x = x * cos(rad) - y * sin(rad);
  p->y = x * sin(rad) + y * cos(rad);
}

void draw_line(point p1, point p2, double width, int color) {
  double len = distance(p1, p2);
  double step = len / width;
  point current = p1;
  for (int i = 0; i <= width; i++) {
    printf("%d %d\n", (int)current.x, (int)current.y);
    if (i < width) {
      current.x += step * (p2.x > p1.x ? 1 : -1);
      current.y += step * (p2.y > p1.y ? 1 : -1);
      rotate(&current, 10);
      scale(&current, 1.1, 1.1);
    }
  }
}

int main() {
