#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_WORDS 1000
#define MAX_WORD_LENGTH 50

typedef struct {
    char word[MAX_WORD_LENGTH];
    int count;
} WordCount;

void read_file(FILE *fp, WordCount words[]) {
    char line[MAX_WORD_LENGTH];
    char *token;
    int i;

    while (fgets(line, MAX_WORD_LENGTH, fp)!= NULL) {
        token = strtok(line, ",.?!;:");
        while (token!= NULL) {
            for (i = 0; i < MAX_WORDS; i++) {
                if (strcmp(words[i].word, token) == 0) {
                    words[i].count++;
                    break;
                }
            }
            if (i == MAX_WORDS) {
                strcpy(words[i].word, token);
                words[i].count = 1;
            }
            token = strtok(NULL, ",.?!;:");
        }
    }
}

void print_word_counts(WordCount words[]) {
    int i;

    for (i = 0; i < MAX_WORDS; i++) {
        if (words[i].count > 0) {
            printf("%s: %d\n", words[i].word, words[i].count);
        }
    }
}

int main() {
    FILE *fp;
    WordCount words[MAX_WORDS];
    int i;

    fp = fopen("input.txt", "r");
    if (fp == NULL) {
        printf("Error: Could not open file.\n");
        exit(1);
    }

    read_file(fp, words);
    fclose(fp);

    print_word_counts(words);

    return 0;
}

