#define DIARY_MAX_ENTRIES 100
#define ENTRY_LENGTH 256

typedef struct {
    char date[20];
    char entry[ENTRY_LENGTH];
} diary_entry_t;

typedef struct {
    diary_entry_t entries[DIARY_MAX_ENTRIES];
    int current_entry;
} diary_t;

void init_diary(diary_t* diary) {
    memset(diary, 0, sizeof(diary_t));
}

void add_entry(diary_t* diary, char* date, char* entry) {
    if (diary->current_entry >= DIARY_MAX_ENTRIES) {
        printf("Diary is full, cannot add new entry\n");
        return;
    }

    strcpy(diary->entries[diary->current_entry].date, date);
    strcpy(diary->entries[diary->current_entry].entry, entry);
    diary->current_entry++;
}

void read_entry(diary_t* diary, int entry_num) {
    if (entry_num < 0 || entry_num >= DIARY_MAX_ENTRIES) {
        printf("Invalid entry number\n");
        return;
    }

    printf("Entry %d: %s\n", entry_num + 1, diary->entries[entry_num].entry);
}

void delete_entry(diary_t* diary, int entry_num) {
    if (entry_num < 0 || entry_num >= DIARY_MAX_ENTRIES) {
        printf("Invalid entry number\n");
        return;
    }

    memmove(diary->entries + entry_num, diary->entries + entry_num + 1,
             (DIARY_MAX_ENTRIES - entry_num - 1) * sizeof(diary_entry_t));
    diary->current_entry--;
}

int main() {
