//LLAMA2-13B DATASET v1.0 Category: Task Scheduler ; Style: surprised
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_TASKS 10
#define MAX_DESCRIPTION_LENGTH 256

typedef struct task {
    char name[256];
    void (*function)(void);
} task_t;

typedef struct schedule {
    task_t tasks[MAX_TASKS];
    int next_task;
} schedule_t;

void init_schedule(schedule_t *schedule) {
    int i;
    for (i = 0; i < MAX_TASKS; i++) {
        schedule->tasks[i].name[0] = '\0';
        schedule->tasks[i].function = NULL;
    }
    schedule->next_task = 0;
}

void add_task(schedule_t *schedule, char *name, void (*function)(void)) {
    int i;
    for (i = 0; i < MAX_TASKS; i++) {
        if (schedule->tasks[i].name[0] == '\0') {
            strcpy(schedule->tasks[i].name, name);
            schedule->tasks[i].function = function;
            break;
        }
    }
}

void run_schedule(schedule_t *schedule) {
    int i;
    for (i = 0; i < schedule->next_task; i++) {
        if (schedule->tasks[i].name[0] != '\0') {
            schedule->tasks[i].function();
        }
    }
    schedule->next_task = 0;
}

int main() {
    schedule_t schedule;
    init_schedule(&schedule);

    add_task(&schedule, "Task 1", printf("Task 1 finished\n"));
    add_task(&schedule, "Task 2", printf("Task 2 finished\n"));
    add_task(&schedule, "Task 3", printf("Task 3 finished\n"));

    run_schedule(&schedule);

