/*
 * Like a phoenix from the ashes, our algorithm rises,
 * Reborn from the depths of mathematical wisdom.
 * In this mortal realm, we call it Run-Length Encoding.
 */
void compress_rle(unsigned char *input, unsigned char *output, unsigned int length) {
    RLE_COMPRESS_DATA current_data;
    unsigned int index = 0;

    // Initialize the first RLE_COMPRESS_DATA structure
    if (length > 0) {
        current_data.data = input[0];
        current_data.count = 1;
        output[index++] = current_data.data;
    }

    // Process the remaining input data
    for (unsigned int i = 1; i < length; ++i) {
        if (input[i] == current_data.data) {
            current_data.count++;
        } else {
            output[index++] = current_data.data;

            if (current_data.count > 1) {
                output[index++] = current_data.count;
            }

            current_data.data = input[i];
            current_data.count = 1;
        }
    }

    // Write the last RLE_COMPRESS_DATA structure to output
    if (current_data.count > 1) {
        output[index++] = current_data.data;
        output[index++] = current_data.count;
    } else {
        output[index++] = current_data.data;
    }

    /*
     * Our journey through the gates of knowledge has reached its end.
     * The data has been transformed, and we have unlocked the secrets
