#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_OUTPUT 2048
#define MAX_NETWORKS 50
#define SSID_LENGTH 32
#define BSSID_LENGTH 18

typedef struct {
    char ssid[SSID_LENGTH];
    char bssid[BSSID_LENGTH];
    char mode[10];
    char frequency[10];
    char quality[10];
} WirelessNetwork;

void trim_whitespace(char *str) {
    char *end;

    while(isspace((unsigned char)*str)) str++;
    if(*str == 0) return;

    end = str + strlen(str) - 1;
    while(end > str && isspace((unsigned char)*end)) end--;

    *(end + 1) = 0;
}

void parse_networks(char *output, WirelessNetwork *networks, int *count) {
    char *line = strtok(output, "\n");
    while (line != NULL && *count < MAX_NETWORKS) {
        if (strstr(line, "ESSID:")) {
            trim_whitespace(line);
            sscanf(line, " ESSID:\"%[^\"]\"", networks[*count].ssid);
        } else if (strstr(line, "Address:")) {
            trim_whitespace(line);
            sscanf(line, " Address: %s", networks[*count].bssid);
        } else if (strstr(line, "Mode:")) {
            trim_whitespace(line);
            sscanf(line, " Mode:%s", networks[*count].mode);
        } else if (strstr(line, "Frequency:")) {
            trim_whitespace(line);
            sscanf(line, " Frequency:%s", networks[*count].frequency);
        } else if (strstr(line, "Quality=")) {
            trim_whitespace(line);
            sscanf(line, " Quality=%s", networks[*count].quality);
            (*count)++;
        }

        line = strtok(NULL, "\n");
    }
}

void scan_wireless_networks() {
    FILE *fp;
    char output[MAX_OUTPUT];
    WirelessNetwork networks[MAX_NETWORKS];
    int count = 0;

    // Command to get wireless networks
    fp = popen("iwlist wlan0 scan", "r");
    if (fp == NULL) {
        perror("Failed to run iwlist");
        exit(1);
    }

    // Read the output a chunk at a time
    size_t len = 0;
    while (fgets(output, sizeof(output) - 1, fp) != NULL) {
        parse_networks(output, networks, &count);
    }

    pclose(fp);

    // Display the scanned networks
    printf("Found %d wireless networks:\n", count);
    printf("%-32s %-18s %-10s %-10s %-10s\n", "SSID", "BSSID", "Mode", "Freq", "Quality");
    for (int i = 0; i < count; i++) {
        printf("%-32s %-18s %-10s %-10s %-10s\n", networks[i].ssid, networks[i].bssid,
               networks[i].mode, networks[i].frequency, networks[i].quality);
    }
}

int main() {
    scan_wireless_networks();
    return 0;
}

