const char chars[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 /.,'-";

// Function to convert text to Morse code
void textToMorse(const char *text) {
    for (size_t i = 0; i < strlen(text); i++) {
        char currentChar = toupper(text[i]);
        const char *morseChar = NULL;

        // Find corresponding Morse code for the current character
        for (size_t j = 0; j < sizeof(chars) - 1; j++) {
            if (currentChar == chars[j]) {
                morseChar = morseCode[j];
                break;
            }
        }

        // If valid Morse code found, print it
        if (morseChar) {
            printf("%s ", morseChar);
        } else {
            fprintf(stderr, "Warning: Character '%c' is not valid for Morse code conversion.\n", currentChar);
        }
    }
    printf("\n");
}

