void sapXep(int a[], int n)
{
	if(n == 1)
		return;
	for(int i = 0; i <= n - 2; i++)
	{
		if(a[i] > a[n - 1] && a[i] % 2 == 0 && a[n - 1] % 2 == 0)
		{
			int temp = a[i];
			a[i] = a[n - 1];
			a[n - 1] = temp;
		}
	}
	sapXep(a, n - 1);
}
