#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_ITEMS 100
#define MAX_BIDS 1000
#define MAX_USERS 100

typedef struct {
    int id;
    char *name;
    double balance;
} User;

typedef struct {
    int id;
    char *description;
    double starting_bid;
    double current_bid;
    int num_bids;
    bool is_sold;
} Item;

typedef struct {
    int id;
    int item_id;
    int user_id;
    double bid_amount;
} Bid;

User users[MAX_USERS];
Item items[MAX_ITEMS];
Bid bids[MAX_BIDS];

int num_users = 0;
int num_items = 0;
int num_bids = 0;

void add_user(int id, char *name, double balance) {
    users[num_users].id = id;
    users[num_users].name = name;
    users[num_users].balance = balance;
    num_users++;
}

void add_item(int id, char *description, double starting_bid) {
    items[num_items].id = id;
    items[num_items].description = description;
    items[num_items].starting_bid = starting_bid;
    items[num_items].current_bid = starting_bid;
    items[num_items].num_bids = 0;
    items[num_items].is_sold = false;
    num_items++;
}

void place_bid(int item_id, int user_id, double bid_amount) {
    for (int i = 0; i < num_users; i++) {
        if (users[i].id == user_id) {
            if (bid_amount > users[i].balance) {
                printf("Error: User %s does not have enough balance to place a bid.\n", users[i].name);
                return;
            }
        }
    }

    for (int i = 0; i < num_items; i++) {
        if (items[i].id == item_id) {
            if (bid_amount < items[i].current_bid) {
                printf("Error: Bid amount must be greater than the current bid.\n");
                return;
            }

            items[i].current_bid = bid_amount;
            items[i].num_bids++;
            break;
        }
    }

    Bid new_bid;
    new_bid.id = num_bids;
    new_bid.item_id = item_id;
    new_bid.user_id = user_id;
    new_bid.bid_amount = bid_amount;

    bids[num_bids] = new_bid;
    num_bids++;
}

void close_auction(int item_id) {
    for (int i = 0; i < num_items; i++) {
        if (items[i].id == item_id) {
            items[i].is_sold = true;

            int highest_bidder_id = -1;
            double highest_bid_amount = -1;

            for (int j = 0; j < num_bids; j++) {
                if (bids[j].item_id == item_id && bids[j].bid_amount > highest_bid_amount) {
                    highest_bidder_id = bids[j].user_id;
                    highest_bid_amount = bids[j].bid_amount;
                }
            }

            for (int k = 0; k < num_users; k++) {
                if (users[k].id == highest_bidder_id) {
                    printf("Item %s sold to %s for %f.\n", items[i].description, users[k].name, highest_bid_amount);
                    users[k].balance -= highest_bid_amount;
                    break;
                }
            }

            break;
        }
    }
}

int main() {
    // Add some users
    add_user(1, "John Doe", 1000.00);
    add_user(2, "Jane Doe", 5000.00);
    add_user(3, "Bob Smith", 2000.00);

    // Add some items
    add_item(1, "iPhone 13 Pro", 999.00);
    add_item(2, "MacBook Air M2", 1299.00);
    add_item(3, "iPad Air 5", 599.00);

    // Place some bids
    place_bid(1, 1, 1050.00);
    place_bid(2, 2, 1350.00);
    place_bid(3, 3, 650.00);

    // Close the auction
    close_auction(1);
    close_auction(2);
    close_auction(3);

    return 0;
}

