// A peaceful syntax parsing program, designed to bring a smile to your face 😊

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a struct to hold the syntax elements
typedef struct {
    char *name;    // Name of the syntax element
    char *value;   // Value of the syntax element
} SyntaxElement;

// Define a function to parse the syntax
void parseSyntax(char *str) {
    // Create a stack to hold the syntax elements
    SyntaxElement stack[50];
    int top = 0;

    // Iterate through the input string
    for (int i = 0; str[i] != '\0'; i++) {
        // Check for opening bracket
        if (str[i] == '(') {
            // Push the opening bracket onto the stack
            stack[top].name = "opening bracket";
            stack[top].value = str + i;
            top++;
        }

        // Check for closing bracket
        else if (str[i] == ')') {
            // Pop the closing bracket from the stack
            if (top > 0) {
                top--;
                SyntaxElement current = stack[top];
                printf("Popped %s with value %s\n", current.name, current.value);
            } else {
                printf("Missing opening bracket\n");
                return;
            }
        }

        // Check for identifier
        else if (isalpha(str[i])) {
            // Push the identifier onto the stack
            SyntaxElement current;
            current.name = str + i;
            current.value = "";
            top++;
        }

        // Check for string
        else if (str[i] == '\"') {
            // Push the string onto the stack
            SyntaxElement current;
            current.name = "string";
            current.value = "";
            top++;
            for (int j = i + 1; str[j] != '\"' && str[j] != '\0'; j++) {
                current.value += str[j];
            }
            top++;
        }

        // Check for number
        else if (isdigit(str[i])) {
            // Push the number onto the stack
            SyntaxElement current;
            current.name = "number";
            current.value = "";
            top++;
            for (int j = i + 1; isdigit(str[j]) && str[j] != '\0'; j++) {
                current.value += str[j];
            }
            top++;
        }
    }

    // Check for unmatched closing bracket
    if (top > 0) {
        printf("Missing opening bracket\n");
    }
}

int main() {
    char str[] = "((3 + 5) * 2)";
    parseSyntax(str);
    return 0;
}

