            printf("Green\n");
        } else if (light == YELLOW_LIGHT) {
            printf("Yellow\n");
        } else if (light == RED_LIGHT) {
            printf("Red\n");
        } else {
            printf("Invalid light status\n");
        }

        printf("Current pedestrian light status: ");
        if (pedestrianLight == GREEN_LIGHT) {
            printf("Green\n");
        } else if (pedestrianLight == RED_LIGHT) {
            printf("Red\n");
        } else {
            printf("Invalid pedestrian light status\n");
        }

        if (light == GREEN_LIGHT && pedestrianLight == RED_LIGHT) {
            printf("Pedestrians waiting to cross\n");
        } else if (light == RED_LIGHT && pedestrianLight == GREEN_LIGHT) {
            printf("Cars waiting to cross\n");
        }

