// Function to read a sector from the disk
int read_sector(int fd, void *buffer, uint32_t sector) {
    off_t offset = sector * SECTOR_SIZE;
    if (lseek(fd, offset, SEEK_SET) != offset) {
        perror("lseek");
        return -1;
    }
    if (read(fd, buffer, SECTOR_SIZE) != SECTOR_SIZE) {
        perror("read");
        return -1;
    }
    return 0;
}

// Function to write a sector to the disk
int write_sector(int fd, void *buffer, uint32_t sector) {
    off_t offset = sector * SECTOR_SIZE;
    if (lseek(fd, offset, SEEK_SET) != offset) {
        perror("lseek");
        return -1;
    }
    if (write(fd, buffer, SECTOR_SIZE) != SECTOR_SIZE) {
        perror("write");
        return -1;
    }
    return 0;
}

// Function to scan the disk for partitions
int scan_partitions(int fd) {
    // Read the master boot record (MBR)
    uint8_t mbr[SECTOR_SIZE];
    if (read_sector(fd, mbr, 0) != 0) {
        return -1;
    }

    // Check the MBR signature
    if (mbr[510] != 0x55 || mbr[511] != 0xaa) {
        fprintf(stderr, "Invalid MBR signature\n");
        return -1;
    }

    // Print the partition table
    for (int i = 0; i < 4; i++) {
        partition_entry *partition = (partition_entry *) &mbr[0x1be + i * 16];
        if (partition->boot_indicator == 0x80) {
            printf("Partition %d:\n", i + 1);
            printf("  System type: %02x\n", partition->system_type);
            printf("  Starting sector: %u\n", partition->starting_sector);
            printf("  Number of sectors: %u\n", partition->num_sectors);
        }
    }

    return 0;
}

// Function to scan the file system for files
int scan_files(int fd, uint32_t partition_start) {
    // Read the boot sector of the partition
    uint8_t boot_sector[SECTOR_SIZE];
    if (read_sector(fd, boot_sector, partition_start) != 0) {
        return -1;
    }

    // Check the boot sector signature
    if (boot_sector[0] != 0xeb || boot_sector[1] != 0x3c || boot_sector[2] != 0x90) {
        fprintf(stderr, "Invalid boot sector signature\n");
        return -1;
    }

    // Read the root directory entries
    uint32_t root_directory_start = *(uint32_t *) &boot_sector[0x1c];
    for (int i = 0; i < 512; i++) {
        file_entry *file = (file_entry *) &boot_sector[root_directory_start + i * 32];
        if (file->file_type != 0) {
            printf("File: %s.%s\n", file->filename, file->extension);
            printf("  Starting cluster: %u\n", file->starting_cluster);
            printf("  File size: %u\n", file->file_size);
        }
    }

    return 0;
}

// Function to recover a file from the disk
int recover_file(int fd, uint32_t partition_start, file_entry *file) {
    // Open the output file
    FILE *output_file = fopen(file->filename, "wb");
    if (output_file == NULL) {
        perror("fopen");
        return -1;
    }

    // Read the data clusters of the file
    uint32_t cluster = file->starting_cluster;
    while (cluster != 0xffff) {
        // Read the data sector of the cluster
        uint8_t data_sector[SECTOR_SIZE];
        if (read_sector(fd, data_sector, partition_start + cluster * 8) != 0) {
            return -1;
        }

        // Write the data sector to the output file
        if (fwrite(data_sector, 1, SECTOR_SIZE, output_file) != SECTOR_SIZE) {
            perror("fwrite");
            return -1;
        }

        // Get the next cluster number
        cluster = *(uint16_t *) &data_sector[0x0b];
    }

    // Close the output file
    fclose(output_file);

    return 0;
}

// Main function
int main(int argc, char *argv[]) {
    // Check the number of arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <disk image>\n", argv[0]);
        return 1;
    }

    // Open the disk image file
    int fd = open(argv[1], O_RDONLY);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    // Scan the disk for partitions
    if (scan_partitions(fd) != 0) {
        return 1;
    }

    // Scan the file system for files
    if (scan_files(fd, 1) != 0) {
        return 1;
    }

    // Recover a file
    file_entry file;
    strcpy(file.filename, "FILE1");
    strcpy(file.extension, "TXT");
    if (recover_file(fd, 1, &file) != 0) {
        return 1;
    }

    // Close the disk image file
    close(fd);

    return 0;
}

