void print_time_period(int year) {
  // Iterate through the time periods and find the current one
  for (int i = 0; i < NUM_PERIODS; i++) {
    if (year >= year_ranges[i][0] && year <= year_ranges[i][1]) {
      printf("You are in the %s period (%d - %d).\n", time_periods[i], year_ranges[i][0], year_ranges[i][1]);
      return;
    }
  }
}

