void simulate_time_travel(int year) {
  // Generate a random time travel option
  int option = rand() % NUM_PERIODS;
  printf("You have chosen to travel to the %s period.\n", time_travel_options[option]);

  // Iterate through the time periods and find the chosen one
  for (int i = 0; i < NUM_PERIODS; i++) {
    if (option == i) {
      // Print the current time period and year
      print_time_period(year);
      // Update the year to the new time period
      year = year_ranges[i][0];
      break;
    }
  }
