//A.1 Two Sum
vector<int> twoSum(vector<int> &numbers, int target)
{
	sort(numbers.begin(), numbers.end());
	vector<int> vec;
	int p1 = 0;
	int p2 = numbers.size() - 1;

	while(p1 < p2)
	{
		if(numbers[p1] + numbers[p2] == target)
		{
			vec.push_back(p1 + 1);
			vec.push_back(p2 + 1);
			break;
		}
		else if(numbers[p1] + numbers[p2] < target)
			p1++;
		else
			p2--;
	}

	return vec;
}

