//A.3 Longest Substring Without Repeating Characters
int lengthOfLongestSubstring(string s)
{
	if(s.size() == 0 || s.size() == 1)
		return s.size();

	set<char> checker;
	set<char>::iterator iter;
	checker.insert(s[0]);
	int max = 0;
	int beg = 0;
	int end = 1;

	while(end != s.size())
	{
		iter = checker.find(s[end]);
		if(iter == checker.end())
			checker.insert(s[end]);
		else
		{
			if(end - beg > max)
				max = end - beg;
			while(s[beg] != s[end])
			{
				checker.erase(s[beg]);
				beg++;
			}
			beg++;
		}
		end++;
	}

	if(end - beg > max)
		max = end - beg;

	return max;
}

