//A.5 Longest Palindromic Substring
string longestPalindrome(string s)
{
	if(s.size() == 0)
		return NULL;

	int len = s.size();
	bool table[1000][1000] = {false};
	int beg = -1;
	int end = -1;
	int max = 1;

	//populate table for base case 1: c[i,i] is palindrome
	for(int i = 0; i < len; i++)
		table[i][i] = true;

	//populate table for base case 2: c[i, i+1] is palindrom , if s[i] = s[i+1]
	for(int i = 0; i < len - 1; i++)
		if(s[i] == s[i + 1])
		{
			beg = i;
			end = i + 1;
			max = 2;
			table[i][i + 1] = true;
		}

	/*
	 * populate upper right table
	 * c[i, j] is true only if
	 *    1:  c[i + 1, j - 1] is true
	 *    2:  s[i] = s[j]
	 */
	for(int i = 0; i < len - 2; i++)
	{
		int x = 0;
		int y = 2 + i;
		for(int j = 0; j < len - 2 - i; j++)
		{
			if(s[x] == s[y] && table[x + 1][y - 1] == true)
			{
				table[x][y] = true;
				if( y - x + 1 > max)
				{
					beg = x;
					end = y;
					max = y - x + 1;
				}
			}
			x++;
			y++;
		}
	}

	if(beg == -1)
		return s.substr(0,1);
	else
		return s.substr(beg, end - beg + 1);
}

