string convertZigZag(string s, int nRows)
{
	int paceA = nRows*2 - 2;
	int paceB = 0;
	bool A = true;
	string ret;

	for(int i = 0; i < nRows; i++)
	{
		int current = i;
		A = true;
		while(current < s.size())
		{
			if(A)
			{
				if(paceA > 0)
					ret += s[current];
				A = false;
				current += paceA;
			}
			else
			{
				if(paceB > 0)
					ret += s[current];
				A = true;
				current += paceB;
			}
		}

		paceA -= 2;
		paceB += 2;
	}

	return ret;
}

