string multiply(string str, char x)
{
	string ret;
	int carry = 0;

	for(int i = str.size() - 1; i >= 0; i--)
	{
		int num = (x - '0')*(str[i] - '0') + carry;
		if(num > 9)
		{
			carry = num/10;
			num = num%10;
		}
		else
			carry = 0;

		ret = (char)('0' + num) + ret;
	}

	if(carry > 0)
		ret = (char)('0' + carry) + ret;

	return ret;
}

