	{
		int num;
		if(j >= 0 && i >= 0)
			num = ret[i] - '0' + s[j] - '0' + carry;
		else if(j >= 0)
			num = s[j] - '0' + carry;
		else if(i >= 0)
			num = ret[i] - '0' + carry;
		else
			num = 1;

		if(num > 9)
