vector<string> anagrams(vector<string> vec)
{
	map<string, int> mp;
	map<string, int>::iterator iter;
	for(int i = 0; i < vec.size(); i++)
	{
		string key = vec[i];
		sort(key.begin(), key.end());
		iter = mp.find(key);
		if(iter == mp.end())
			mp.insert(pair<string, int>(key, 1));
		else
			mp[key]++;
	}

	vector<string> ret;
	for(int i = 0; i < vec.size(); i++)
	{
		string key = vec[i];
		sort(key.begin(), key.end());
		if(mp[key] > 1)
			ret.push_back(vec[i]);
	}

	return ret;
}

