	for(int i = 0; i < word2.size() + 1; i++)
		table[0][i] = i;
	for(int i = 0; i < word1.size() + 1; i++)
		table[i][0] = i;

	// normal case
	for(int i = 1; i < word1.size() + 1; i++)
		for(int j = 1; j < word2.size() + 1; j++)
		{
			int x;
