//B.10 Unique Path
int uniquePaths(int m, int n)
{
	int **table = new int*[m];
	for(int i = 0; i < m; i++)
		table[i] = new int[n];

	//base case
	for(int i = 0; i < m; i++)
		table[i][n - 1] = 1;
	for(int i = 0; i < n; i++)
		table[m - 1][i] = 1;

	//normal case
	for(int i = m - 2; i >= 0; i--)
		for(int j = n - 2; j >= 0; j--)
			table[i][j] = table[i + 1][j] + table[i][j + 1];

	int paths = table[0][0];

	// delete table
	for(int i = 0; i < m; i++)
		delete[] table[i];
	delete[] table;

	return paths;
}

