//C.1 Binary Tree
vector<vector<int> > levelOrder(TreeNode *root)
{
	queue<TreeNode*> que;
	que.push(root);
	que.push(NULL);
	vector<int> vec;
	vector<vector<int> > vecs;

	while(!que.empty())
	{
		TreeNode* current = que.front();
		que.pop();
		if(current == NULL)
		{
			vecs.push_back(vec);
			vec.clear();
			if(que.empty())
				break;
			que.push(NULL);
			continue;
		}

		vec.push_back(current->val);
		if(current->left)
			que.push(current->left);
		if(current->right)
			que.push(current->right);
	}

	return vecs;
}

