//C.2 Binary Tree Zigzag Level Order Traversal
vector<vector<int> > zigzagLevelOrder(TreeNode *root)
{
	queue<TreeNode*> que;
	stack<TreeNode*> stk;
	que.push(root);
	que.push(NULL);
	bool leftToRight = true;
	vector<int> vec;
	vector<vector<int> > vecs;

	while(!que.empty())
	{
		TreeNode* current = que.front();
		que.pop();
		if(current == NULL)
		{
			while(!stk.empty())
			{
				que.push(stk.top());
				stk.pop();
			}
			leftToRight = leftToRight == true ? false : true;
			vecs.push_back(vec);
			vec.clear();
			if(que.empty())
				break;
			que.push(NULL);
			continue;
		}

		vec.push_back(current->val);

		if(leftToRight)
		{
			if(current->left)
				stk.push(current->left);
			if(current->right)
				stk.push(current->right);
		}
		else
		{
			if(current->right)
				stk.push(current->right);
			if(current->left)
				stk.push(current->left);
		}
	}

	return vecs;
}

