//C.17 Pascal's Triangle
vector<vector<int> > pascalTriangle(int numRows)
{
	vector<vector<int> > vecs;
	vector<int> vec;
	vec.push_back(1);
	vecs.push_back(vec);

	for(int i = 0; i < numRows - 1; i++)
	{
		vector<int> v;
		v.push_back(1);
		vector<int> last = vecs[vecs.size() - 1];
		for(int j = 0; j < last.size() - 1; j++)
		{
			v.push_back(last[j] + last[j + 1]);
		}
		v.push_back(1);
		vecs.push_back(v);
	}

	return vecs;
}

