//C.23 Valid Palindrome
bool isAlpha(char c)
{
	if((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
		return true;
	else
		return false;
}

bool sameAlpha(char a, char b)
{
	if(a == b || abs(a - b) == abs('A' - 'a'))
		return true;
	else
		return false;
}
bool isPalindrome(string s)
{
	if(s.size() == 0)
		return true;

	int i = 0;
	int j = s.size() - 1;

	while(i < j)
	{
		while(!isAlpha(s[i]))
			i++;
		while(!isAlpha(s[j]))
			j--;
		if(!sameAlpha(s[i], s[j]))
			return false;
		i++;
		j--;
	}

	return true;
}

