//D.1 Longest Increasing Subsequence
int longestIncreaseSub(vector<int> vec)
{
	vector<int> ref;
	ref.push_back(1);
	int maxmium = 1;

	for(int i = 1; i < vec.size(); i++)
	{
		int max = 0;
		for(int j = 0; j < i; j++)
		{
			if(vec[j] < vec[i] && ref[j] > max)
				max = ref[j];
		}
		ref.push_back(max + 1);
		if(max + 1 > maxmium)
			maxmium = max + 1;
	}

	return maxmium;
}

