//D.2 max non-adjecent subsequence
int maxSubsequence(vector<int> vec)
{
	int exPrev = vec[0];
	int inPrev  = vec[1];
	for(int i = 2; i < vec.size(); i++)
	{
		int newExPrev = max(exPrev, inPrev);
		int newInPrev = vec[i] + exPrev;
		exPrev = newExPrev;
		inPrev = newInPrev;
	}

	return max(inPrev, exPrev);
}

