int CMyCircleList::Delete(int i)
{
	Node *p = rear;
	int j = 0;
	while (j != i-1 && p->next != rear)
	{
		p = p->next;
		j++;
	}
	if (j == i - 1)
	{
		Node* q = p->next;
		p->next = q->next;
		int x = q->data;
		delete q;
		return x;
	}
	else throw "wrong";
}

void CMyCircleList::Reverse()
{
	Node *p = rear;
	Node *q = rear->next;
	while (q != rear)
	{
		Node *t = q->next;
		q->next = p;
		p = q;
		q = t;
	}
	q->next = p;
}

