/*
 * Unique C Checksum Calculator Example Program in a Portable Style
 *
 * This program calculates the checksum of a given file using a portable style.
 *
 * Usage:
 *  ./checksum <filename>
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>

#define BUF_SIZE 1024

int main(int argc, char *argv[]) {
    // Check if the number of arguments is correct
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    // Open the file and get its size
    FILE *file = fopen(argv[1], "rb");
    if (!file) {
        fprintf(stderr, "Error: Could not open file %s\n", argv[1]);
        return 1;
    }
    struct stat file_stat;
    if (fstat(fileno(file), &file_stat) < 0) {
        fprintf(stderr, "Error: Could not get file size\n");
        fclose(file);
        return 1;
    }

    // Allocate a buffer for the file content
    char *buf = malloc(file_stat.st_size);
    if (!buf) {
        fprintf(stderr, "Error: Could not allocate memory\n");
        fclose(file);
        return 1;
    }

    // Read the file content into the buffer
    size_t bytes_read = fread(buf, 1, file_stat.st_size, file);
    if (bytes_read < file_stat.st_size) {
        fprintf(stderr, "Error: Could not read file\n");
        free(buf);
        fclose(file);
        return 1;
    }

    // Calculate the checksum
    unsigned int checksum = 0;
    for (size_t i = 0; i < bytes_read; i++) {
        checksum += buf[i];
    }

    // Print the checksum
    printf("Checksum: %u\n", checksum);

    // Free the buffer and close the file
    free(buf);
    fclose(file);

    return 0;
}

