//GPT-4o-mini DATASET v1.0 Category: System event logger ; Style: asynchronous
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define LOG_FILE "event_log.txt"
#define BUFFER_SIZE 256
#define MAX_EVENTS 100

typedef enum {
    INFO,
    WARNING,
    ERROR
} LogLevel;

typedef struct {
    LogLevel level;
    char message[BUFFER_SIZE];
    time_t timestamp;
} LogEvent;

typedef struct {
    LogEvent events[MAX_EVENTS];
    int count;
    pthread_mutex_t lock;
    int stop;
} Logger;

void *log_thread(void *arg) {
    Logger *logger = (Logger *)arg;
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return NULL;
    }

    while (!logger->stop || logger->count > 0) {
        pthread_mutex_lock(&logger->lock);

        while (logger->count > 0) {
            LogEvent event = logger->events[--logger->count];
            char *levelStr;
            switch (event.level) {
                case INFO:    levelStr = "INFO"; break;
                case WARNING: levelStr = "WARNING"; break;
                case ERROR:   levelStr = "ERROR"; break;
            }
            fprintf(file, "%s [%ld]: %s\n", levelStr, event.timestamp, event.message);
            fflush(file);
        }

        pthread_mutex_unlock(&logger->lock);
        usleep(100000); // Sleep for 100 milliseconds
    }

    fclose(file);
    return NULL;
}

void log_event(Logger *logger, LogLevel level, const char *message) {
    pthread_mutex_lock(&logger->lock);
    if (logger->count < MAX_EVENTS) {
        logger->events[logger->count].level = level;
        strncpy(logger->events[logger->count].message, message, BUFFER_SIZE - 1);
        logger->events[logger->count].message[BUFFER_SIZE - 1] = '\0'; // Ensure null-termination
        logger->events[logger->count].timestamp = time(NULL);
        logger->count++;
    }
    pthread_mutex_unlock(&logger->lock);
}

void init_logger(Logger *logger) {
    logger->count = 0;
    logger->stop = 0;
    pthread_mutex_init(&logger->lock, NULL);
}

void destroy_logger(Logger *logger) {
    logger->stop = 1;
    pthread_mutex_destroy(&logger->lock);
}

int main() {
    Logger logger;
    init_logger(&logger);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, log_thread, &logger)) {
        perror("Failed to create logging thread");
        return 1;
    }

    // Simulate events
    log_event(&logger, INFO, "Application started.");
    sleep(1);
    log_event(&logger, WARNING, "Low disk space warning.");
    sleep(1);
    log_event(&logger, ERROR, "Failed to open configuration file.");
    sleep(1);
    log_event(&logger, INFO, "Configuration loaded.");

    // Simulate more events
    for (int i = 0; i < 5; ++i) {
        char msg[BUFFER_SIZE];
        snprintf(msg, BUFFER_SIZE, "Processing item %d.", i);
        log_event(&logger, INFO, msg);
        sleep(1);
    }

    // Clean up
    destroy_logger(&logger);
    pthread_join(thread_id, NULL);

    return 0;
}

