//LLAMA2-13B DATASET v1.0 Category: Encryption ; Style: relaxed
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>

#define KEY_SIZE 16
#define MAX_MESSAGE_LENGTH 1024

// Define a structure to hold the message and key
typedef struct {
    char message[MAX_MESSAGE_LENGTH];
    char key[KEY_SIZE];
} message_t;

// Function to encrypt the message
void encrypt(message_t *message) {
    // Generate a random key
    srand(time(NULL));
    for (int i = 0; i < KEY_SIZE; i++) {
        message->key[i] = (char)rand() % 26 + 'a';
    }

    // Encrypt the message
    for (int i = 0; i < strlen(message->message); i++) {
        int index = message->key[i % KEY_SIZE] - 'a';
        message->message[i] = (char)(index + 'a');
    }
}

// Function to decrypt the message
void decrypt(message_t *message) {
    // Reverse the encryption process
    for (int i = 0; i < strlen(message->message); i++) {
        int index = message->message[i] - 'a';
        message->message[i] = (char)(index - 'a');
    }
}

int main() {
    // Create a message and key
    message_t message = {
        "Hello, World!",
        "abcdefghijklmnopqrstuvwxyz"
    };

    // Encrypt the message
    encrypt(&message);

    // Print the encrypted message
    printf("Encrypted message: %s\n", message.message);

    // Decrypt the message
    decrypt(&message);

    // Print the decrypted message
    printf("Decrypted message: %s\n", message.message);

    return 0;
}

