void toggle_device(int index) {
    devices[index].status =!devices[index].status;
    printf("Device %s status toggled.\n", devices[index].name);
}

// Function to turn on/off all devices
void turn_all_devices(int status) {
    int i;
    for (i = 0; i < MAX_DEVICES; i++) {
        devices[i].status = status;
        printf("Device %s turned %s.\n", devices[i].name, status? "on" : "off");
    }
}

