void process_command(char *command) {
    int index;
    char action[20];
    strcpy(action, "");
    char *token = strtok(command, " ");
    while (token!= NULL) {
        strcat(action, token);
        strcat(action, " ");
        token = strtok(NULL, " ");
    }
    strcat(action, "\0");
    if (strcmp(action, "toggle") == 0) {
        index = atoi(strtok(command, " "));
        toggle_device(index);
    } else if (strcmp(action, "turn") == 0) {
        index = atoi(strtok(command, " "));
        int status = atoi(strtok(NULL, " "));
        turn_all_devices(status);
    } else {
        printf("Invalid command.\n");
    }
}

// Main function
