    init_devices();
    int i;
    for (i = 0; i < MAX_DEVICES; i++) {
        printf("%s: %d\n", devices[i].name, devices[i].status);
    }
    char command[MAX_COMMAND_LENGTH];
    while (1) {
        printf("Enter command: ");
        fgets(command, MAX_COMMAND_LENGTH, stdin);
