// Function declarations
int callback(void *NotUsed, int argc, char **argv, char **azColName);
void perform_query(sqlite3 *db, const char *sql);

// Main function - where all the fun begins!
int main() {
    sqlite3 *db;
    char *err_msg = 0;

    // Opening the database - or is it an animal house?
    int rc = sqlite3_open("funny_animal.db", &db);

    if (rc) {
        fprintf(stderr, "Can't open database: %s\n", sqlite3_errmsg(db));
        return 1;
    } else {
        fprintf(stderr, "Opened database successfully! Let's pet some animals!\n");
    }

    // Create a table, because where else would the animals live?
    const char *create_table_sql = "CREATE TABLE IF NOT EXISTS Animals ("
                                    "ID INTEGER PRIMARY KEY, "
                                    "Name TEXT NOT NULL, "
                                    "Type TEXT NOT NULL, "
                                    "FunnyLevel INTEGER NOT NULL);";

    perform_query(db, create_table_sql);

    // Insert some funny animals into the world
    const char *insert_sql = "INSERT INTO Animals (Name, Type, FunnyLevel) VALUES "
                             "('Dancing Dog', 'Dog', 10), "
                             "('Parrot that Cracks Jokes', 'Parrot', 8), "
                             "('Silly Cat', 'Cat', 7), "
                             "('Rubber Chicken', 'Chicken', 9);";

    perform_query(db, insert_sql);

    // Now let's query the animals - time to take roll call!
    const char *query_sql = "SELECT * FROM Animals;";
    perform_query(db, query_sql);

    // Closing the database because animals need their sleep too!
    sqlite3_close(db);
    return 0;
}

// Callback function - it's like a stand-up comedian for the database!
int callback(void *NotUsed, int argc, char **argv, char **azColName) {
    for (int i=0; i<argc; i++) {
        printf("%s: %s ", azColName[i], argv[i] ? argv[i] : "NULL");
    }
    printf("\n");
    return 0;
}

// Perform a database query
void perform_query(sqlite3 *db, const char *sql) {
    char *err_msg = 0;
    int rc = sqlite3_exec(db, sql, callback, 0, &err_msg);

    if (rc != SQLITE_OK ) {
        fprintf(stderr, "SQL error: %s\n", err_msg);
        sqlite3_free(err_msg);
    } else {
        fprintf(stdout, "Query executed successfully!\n");
    }
}

