    printf("Enter the number of elements to sort: ");
    scanf("%d", &n);

    int arr[n];
    printf("Enter the elements to sort:\n");
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }

    srand(time(NULL));
    bubble_sort(arr, n);

    if (is_sorted(arr, n)) {
        printf("The array is sorted.\n");
    } else {
        printf("The array is not sorted.\n");
    }

    return 0;
}

