//GEMINI-pro DATASET v1.0 Category: Image to ASCII art converter ; Style: dynamic
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

// Define the maximum image size
#define MAX_WIDTH  1024
#define MAX_HEIGHT 1024

// Define the maximum number of ASCII characters
#define MAX_CHARS 256

// Define the ASCII character set
char *ascii_chars = " .,-~:;!\"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";

// Define the image structure
typedef struct {
    int width;
    int height;
    unsigned char *data;
} Image;

// Read an image from a file
Image *read_image(char *filename) {
    FILE *fp = fopen(filename, "rb");
    if (!fp) {
        perror("fopen");
        return NULL;
    }

    // Read the image header
    unsigned char header[18];
    if (fread(header, 1, 18, fp) != 18) {
        perror("fread");
        fclose(fp);
        return NULL;
    }

    // Check if the image is a BMP file
    if (header[0] != 'B' || header[1] != 'M') {
        fprintf(stderr, "Error: not a BMP file\n");
        fclose(fp);
        return NULL;
    }

    // Read the image dimensions
    int width = *(int *)&header[18];
    int height = *(int *)&header[22];

    // Read the image data
    unsigned char *data = malloc(width * height * 3);
    if (!data) {
        perror("malloc");
        fclose(fp);
        return NULL;
    }

    if (fread(data, 1, width * height * 3, fp) != width * height * 3) {
        perror("fread");
        free(data);
        fclose(fp);
        return NULL;
    }

    fclose(fp);

    // Create an image structure
    Image *image = malloc(sizeof(Image));
    if (!image) {
        perror("malloc");
        free(data);
        return NULL;
    }

    image->width = width;
    image->height = height;
    image->data = data;

    return image;
}

// Convert an image to ASCII art
char *image_to_ascii(Image *image) {
    // Calculate the average luminance of each pixel
    unsigned char *luminance = malloc(image->width * image->height);
    if (!luminance) {
        perror("malloc");
        return NULL;
    }

    for (int i = 0; i < image->width * image->height; i++) {
        luminance[i] = (image->data[i * 3] + image->data[i * 3 + 1] + image->data[i * 3 + 2]) / 3;
    }

    // Map the average luminance to an ASCII character
    char *ascii_art = malloc(image->width * image->height + 1);
    if (!ascii_art) {
        perror("malloc");
        free(luminance);
        return NULL;
    }

    for (int i = 0; i < image->width * image->height; i++) {
        ascii_art[i] = ascii_chars[(int)(luminance[i] / 255.0 * (MAX_CHARS - 1))];
    }

    ascii_art[image->width * image->height] = '\0';

    free(luminance);

    return ascii_art;
}

// Print an ASCII art image to the console
void print_ascii_art(char *ascii_art, int width, int height) {
    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            printf("%c", ascii_art[i * width + j]);
        }
        printf("\n");
    }
}

// Free the memory allocated for an image
void free_image(Image *image) {
    free(image->data);
    free(image);
}

// Main function
int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <image.bmp>\n", argv[0]);
        return 1;
    }

    // Read the image from a file
    Image *image = read_image(argv[1]);
    if (!image) {
        return 1;
    }

    // Convert the image to ASCII art
    char *ascii_art = image_to_ascii(image);
    if (!ascii_art) {
        free_image(image);
        return 1;
    }

    // Print the ASCII art image to the console
    print_ascii_art(ascii_art, image->width, image->height);

    // Free the memory allocated for the image and the ASCII art
    free_image(image);
    free(ascii_art);

    return 0;
}

