#include <stdio.h>
#include <stdlib.h>
#include <ncurses.h>
#include <unistd.h>

#define WIDTH 20
#define HEIGHT 10
#define PACMAN 'P'
#define DOT '.'
#define WALL '#'
#define SPACE ' '

typedef struct {
    int x, y;
} Position;

void initialize_environment(char environment[HEIGHT][WIDTH]) {
    for (int y = 0; y < HEIGHT; y++) {
        for (int x = 0; x < WIDTH; x++) {
            if (y == 0 || y == HEIGHT - 1 || x == 0 || x == WIDTH - 1) {
                environment[y][x] = WALL;
            } else if (x % 2 == 0 && y % 2 == 0) {
                environment[y][x] = WALL;
            } else {
                environment[y][x] = DOT;
            }
        }
    }
}

void draw_environment(char environment[HEIGHT][WIDTH], Position pacman_pos) {
    clear();
    for (int y = 0; y < HEIGHT; y++) {
        for (int x = 0; x < WIDTH; x++) {
            if (y == pacman_pos.y && x == pacman_pos.x) {
                mvaddch(y, x, PACMAN);
            } else {
                mvaddch(y, x, environment[y][x]);
            }
        }
    }
    refresh();
}

int main() {
    initscr();              // Start curses mode
    cbreak();               // Disable line buffering
    noecho();               // Don't echo pressed keys
    keypad(stdscr, TRUE);   // Enable special keys
    curs_set(0);           // Hide cursor

    char environment[HEIGHT][WIDTH];
    initialize_environment(environment);

    Position pacman_pos = {1, 1}; // Initial position of Pac-Man
    environment[pacman_pos.y][pacman_pos.x] = SPACE; // Clear dot under Pac-Man

    int ch;
    while (1) {
        draw_environment(environment, pacman_pos);

        ch = getch(); // Get user input

        Position new_pos = pacman_pos;
        // Update position based on input
        switch (ch) {
            case KEY_UP:
                new_pos.y--;
                break;
            case KEY_DOWN:
                new_pos.y++;
                break;
            case KEY_LEFT:
                new_pos.x--;
                break;
            case KEY_RIGHT:
                new_pos.x++;
                break;
            case 'q': // Quit
                endwin();
                return 0;
            default:
                continue;
        }

        // Check for wall collision
        if (environment[new_pos.y][new_pos.x] != WALL) {
            pacman_pos = new_pos;
            if (environment[pacman_pos.y][pacman_pos.x] == DOT) {
                environment[pacman_pos.y][pacman_pos.x] = SPACE; // Eat the dot
            }
        }
    }

    endwin(); // End curses mode
    return 0;
}

