#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct account {
    char name[32];
    double balance;
} account_t;

typedef struct transaction {
    char type;
    double amount;
    char description[64];
} transaction_t;

typedef struct personal_finance_planner {
    account_t accounts[10];
    int num_accounts;
    transaction_t transactions[100];
    int num_transactions;
} personal_finance_planner_t;

void add_account(personal_finance_planner_t *pfp, char *name, double balance) {
    if (pfp->num_accounts < 10) {
        strcpy(pfp->accounts[pfp->num_accounts].name, name);
        pfp->accounts[pfp->num_accounts].balance = balance;
        pfp->num_accounts++;
    }
}

void add_transaction(personal_finance_planner_t *pfp, char type, double amount, char *description) {
    if (pfp->num_transactions < 100) {
        pfp->transactions[pfp->num_transactions].type = type;
        pfp->transactions[pfp->num_transactions].amount = amount;
        strcpy(pfp->transactions[pfp->num_transactions].description, description);
        pfp->num_transactions++;
    }
}

void print_accounts(personal_finance_planner_t *pfp) {
    for (int i = 0; i < pfp->num_accounts; i++) {
        printf("%s: %f\n", pfp->accounts[i].name, pfp->accounts[i].balance);
    }
}

void print_transactions(personal_finance_planner_t *pfp) {
    for (int i = 0; i < pfp->num_transactions; i++) {
        printf("%c: %f: %s\n", pfp->transactions[i].type, pfp->transactions[i].amount, pfp->transactions[i].description);
    }
}

int main() {
    personal_finance_planner_t pfp;
    pfp.num_accounts = 0;
    pfp.num_transactions = 0;

    add_account(&pfp, "checking", 1000);
    add_account(&pfp, "savings", 2000);

    add_transaction(&pfp, 'D', 500, "paycheck");
    add_transaction(&pfp, 'W', 200, "groceries");
    add_transaction(&pfp, 'W', 100, "gas");

    print_accounts(&pfp);
    print_transactions(&pfp);

    return 0;
}

