#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

// Function to add watermark to an image
void add_watermark(const char *image_path, const char *watermark_path, const char *output_path) {
    // Open the image and watermark files
    FILE *image_file = fopen(image_path, "rb");
    FILE *watermark_file = fopen(watermark_path, "rb");

    // Open the output file
    FILE *output_file = fopen(output_path, "wb");

    // Read the image data into a buffer
    unsigned char image_data[512];
    fread(image_data, 1, 512, image_file);

    // Read the watermark data into a buffer
    unsigned char watermark_data[512];
    fread(watermark_data, 1, 512, watermark_file);

    // Find the width and height of the image
    int width = 512;
    int height = 512;

    // Find the size of the watermark image
    int watermark_width = 64;
    int watermark_height = 64;

    // Add the watermark to the image
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            // Check if the current pixel is within the watermark area
            if (x >= (width - watermark_width) && x <= width && y >= (height - watermark_height) && y <= height) {
                // Set the pixel to the watermark color
                image_data[y * width + x] = watermark_data[y * watermark_width + x];
            } else {
                // Set the pixel to the original color
                image_data[y * width + x] = image_data[y * width + x];
            }
        }
    }

    // Write the modified image data to the output file
    fwrite(image_data, 1, 512 * height, output_file);

    // Close all files
    fclose(image_file);
    fclose(watermark_file);
    fclose(output_file);
}

// Main function
int main(int argc, char *argv[]) {
    if (argc < 4) {
        printf("Usage: %s <image_path> <watermark_path> <output_path>\n", argv[0]);
        return 1;
    }

    // Call the add_watermark function with the given arguments
    add_watermark(argv[1], argv[2], argv[3]);

    return 0;
}

