			{
				if( typeid( e ) == typeid( ICE ) )
					throw;
				cout << "error: " << e.what() << endl;
				// dump the stack trace
				if( ex )
					ex->DumpTrace( cerr );
			}
			catch( SemanticException & e )
			{
				// display an error
				emit_error( e );
			}
		}
		// end execution (shutdown)
		ex->End();
	}
	catch( ICE & e )
	{
