#include <stdio.h>
#include <stdlib.h>

#define BOARD_SIZE 8
#define EMPTY '.'
#define WHITE_PAWN 'P'
#define BLACK_PAWN 'p'
#define WHITE_KNIGHT 'N'
#define BLACK_KNIGHT 'n'

// Function prototypes
void initializeBoard(char board[BOARD_SIZE][BOARD_SIZE]);
void printBoard(char board[BOARD_SIZE][BOARD_SIZE]);
void makeMove(char board[BOARD_SIZE][BOARD_SIZE], int srcX, int srcY, int destX, int destY);
int isMoveValid(char board[BOARD_SIZE][BOARD_SIZE], int srcX, int srcY, int destX, int destY);
int evaluatePosition(char board[BOARD_SIZE][BOARD_SIZE]);
void SherlocksMove(char board[BOARD_SIZE][BOARD_SIZE]);

int main() {
    char board[BOARD_SIZE][BOARD_SIZE];
    initializeBoard(board);
    printBoard(board);

    // A simple representation of making a move
    SherlocksMove(board);

    return 0;
}

// Initializing the chess board
void initializeBoard(char board[BOARD_SIZE][BOARD_SIZE]) {
    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            board[i][j] = EMPTY;
        }
    }
    // Place pawns
    for (int j = 0; j < BOARD_SIZE; j++) {
        board[1][j] = WHITE_PAWN;
        board[6][j] = BLACK_PAWN;
    }
    // Place knights
    board[0][1] = WHITE_KNIGHT;
    board[0][6] = WHITE_KNIGHT;
    board[7][1] = BLACK_KNIGHT;
    board[7][6] = BLACK_KNIGHT;
}

// Printing the chess board
void printBoard(char board[BOARD_SIZE][BOARD_SIZE]) {
    printf("  a b c d e f g h\n");
    for (int i = 0; i < BOARD_SIZE; i++) {
        printf("%d ", 8 - i);
        for (int j = 0; j < BOARD_SIZE; j++) {
            printf("%c ", board[i][j]);
        }
        printf("\n");
    }
}

// Function to make a move
void makeMove(char board[BOARD_SIZE][BOARD_SIZE], int srcX, int srcY, int destX, int destY) {
    if (isMoveValid(board, srcX, srcY, destX, destY)) {
        board[destX][destY] = board[srcX][srcY];
        board[srcX][srcY] = EMPTY;
    } else {
        printf("Invalid move from [%d, %d] to [%d, %d]\n", srcX, srcY, destX, destY);
    }
}

// Check if a move is valid (basic version)
int isMoveValid(char board[BOARD_SIZE][BOARD_SIZE], int srcX, int srcY, int destX, int destY) {
    if (srcX < 0 || srcX >= BOARD_SIZE || srcY < 0 || srcY >= BOARD_SIZE ||
        destX < 0 || destX >= BOARD_SIZE || destY < 0 || destY >= BOARD_SIZE) {
        return 0; // Out of bounds
    }
    if (board[srcX][srcY] == EMPTY) {
        return 0; // No piece at source
    }
    // Allowing only simple orthogonal move validation for this example
    if (board[destX][destY] != EMPTY && 
        ((board[srcX][srcY] < 'a' && board[destX][destY] < 'a') || (board[srcX][srcY] > 'Z' && board[destX][destY] > 'Z'))) {
        return 0; // Can't capture your own piece
    }
    return 1;
}

// Evaluate the board position (simple version)
int evaluatePosition(char board[BOARD_SIZE][BOARD_SIZE]) {
    int score = 0;
    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[i][j] == WHITE_PAWN) score += 1; // Simple scoring
            if (board[i][j] == BLACK_PAWN) score -= 1;
        }
    }
    return score;
}

// Logic reminiscent of Sherlock Holmes making a move
void SherlocksMove(char board[BOARD_SIZE][BOARD_SIZE]) {
    printf("Sherlock Holmes examines the position...\n");
    int score = evaluatePosition(board);
    printf("Current position score: %d\n", score);

    // Let's say Sherlock decides to move a white knight from b1 to c3
    makeMove(board, 0, 1, 2, 2);

    printf("After Sherlock's deduction, the board is now:\n");
    printBoard(board);
}

