#define PHONE_BOOK_SIZE 1024
#define PHONE_ENTRY_SIZE 128

struct phone_entry {
    char name[PHONE_ENTRY_SIZE];
    char number[PHONE_ENTRY_SIZE];
};

struct phone_book {
    struct phone_entry entries[PHONE_BOOK_SIZE];
    int capacity;
    int size;
};

void init_phone_book(struct phone_book *book) {
    book->capacity = PHONE_BOOK_SIZE;
    book->size = 0;
}

void add_entry(struct phone_book *book, char *name, char *number) {
    int i;

    if (book->size == book->capacity) {
        printf("Phone book is full!\n");
        return;
    }

    for (i = 0; i < book->size; i++) {
        if (strcmp(book->entries[i].name, name) == 0) {
            printf("Entry already exists!\n");
            return;
        }
    }

    strcpy(book->entries[book->size].name, name);
    strcpy(book->entries[book->size].number, number);
    book->size++;
}

void search_entry(struct phone_book *book, char *name) {
    int i;

    for (i = 0; i < book->size; i++) {
        if (strcmp(book->entries[i].name, name) == 0) {
            printf("Found entry: %s %s\n", book->entries[i].name, book->entries[i].number);
            return;
        }
    }

    printf("Entry not found.\n");
}

void delete_entry(struct phone_book *book, char *name) {
    int i;

    for (i = 0; i < book->size; i++) {
        if (strcmp(book->entries[i].name, name) == 0) {
            memmove(book->entries + i, book->entries + i + 1, (book->size - i - 1) * sizeof(struct phone_entry));
            book->size--;
            break;
        }
    }
}

