#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define WIDTH 10
#define HEIGHT 10

typedef struct {
  int x;
  int y;
  int alive;
} Cell;

Cell grid[WIDTH][HEIGHT];

void init_grid() {
  int i, j;
  for (i = 0; i < WIDTH; i++) {
    for (j = 0; j < HEIGHT; j++) {
      grid[i][j].x = i;
      grid[i][j].y = j;
      grid[i][j].alive = 0;
    }
  }
}

void print_grid() {
  int i, j;
  for (i = 0; i < WIDTH; i++) {
    for (j = 0; j < HEIGHT; j++) {
      printf("%c ", grid[i][j].alive ? '*' : ' ');
    }
    printf("\n");
  }
}

void update_grid() {
  int i, j;
  for (i = 0; i < WIDTH; i++) {
    for (j = 0; j < HEIGHT; j++) {
      int alive_neighbors = 0;
      int x = i, y = j;
      for (int k = -1; k <= 1; k++) {
        for (int l = -1; l <= 1; l++) {
          if (x + k >= 0 && x + k < WIDTH && y + l >= 0 && y + l < HEIGHT) {
            alive_neighbors += grid[x + k][y + l].alive;
          }
        }
      }
      if (grid[i][j].alive && alive_neighbors < 2) {
        grid[i][j].alive = 0;
      } else if (grid[i][j].alive && alive_neighbors > 3) {
        grid[i][j].alive = 0;
      } else if (!grid[i][j].alive && alive_neighbors == 3) {
        grid[i][j].alive = 1;
      }
    }
  }
}

int main() {
  srand(time(NULL));
  init_grid();
  for (int i = 0; i < 100; i++) {
    update_grid();
    print_grid();
    sleep(1);
  }
  return 0;
}

