        printf("%d. %s\n", i, nodes[i].name);
    }

    printf("\nEdges:\n");
    for (int i = 0; i < num_edges; i++) {
        printf("%d -> %d\n", edges[i].src, edges[i].dest);
    }

    return 0;
}

