int isFileName( char *str)
{
    int i=0, len=0;
    int flag=0;
    char base=' ';

    len=strlen( str );
    for( i=0; i<len; i++ )
    {
        base=toupper( str[i] );
        if( base=='\r' || base=='\n')
            break;
        if( base!='A' && base!='C' && base!='G' && base!='U' && base!='T' && base!='-' )
        {
            flag=1;
            break;
        }
    }
    return flag;
}

