int obtainSequence(  char * filename, char* &bufseq )
{
    #ifdef DEBUG_DEV
        printf("obtainSequence\n");
    #endif
    int i=0, templen=0;
    char ch;
    FILE * fp=NULL;

    //----Open the search file
    fp = fopen(filename, "r");
    if( fp == NULL )
    {
        printf(" Fail to open %s\n", filename);
        return 0;
    }

    //get the size of str: len
    fseek( fp, 0, SEEK_SET);
    while ( !feof(fp) )
    {
        ch=fgetc (fp);
        if( isRNABase(ch) )
            templen++;
    }
    //allocate the memory
    bufseq= new char[templen+1];
    bufseq[templen] = '\0';
    //get the str
    fseek( fp, 0, SEEK_SET);
    while ( !feof(fp) )
    {
        ch=fgetc (fp);
        if( isRNABase(ch) )
            bufseq[i++]=ch;
    }
    if( i!=templen )
    {
        printf("There's something wrong with target file.\n");
        return 0;
    }
    fclose(fp);
    return templen;
}

//(1-h)*orgm + h*priorm
void normalizeMatrix( double orgm[5][5], double priorm[5][5], double h)
{
    int i=0, j=0;
    double sumvalue=0.0;
    double ht=0.0, hp=0.0;
    if( h>1 )
        hp=1;
    else if( h<0)
        hp=0;
    else
        hp=h;

    ht=1-hp;    
    //print the original matrix
    //printf("Orignal matrix:\n");
    //printPairEmP( orgm );

    //printf("Prior matrix:\n");
    //printPairEmP( priorm );

    for(i=0; i<5; i++ )
    {
        for(j=0; j<5; j++ )
        {
            orgm[i][j]=ht*orgm[i][j] + hp*priorm[i][j];
            sumvalue += orgm[i][j];
        }
    }

    for(i=0; i<5; i++ )
    {
        for(j=0; j<5; j++ )
        {
            orgm[i][j]=orgm[i][j]/sumvalue;
        }
    }
    //print the new matrix
    //printf("New matrix:\n");
    //printPairEmP( orgm );
    //printf("\n\n");

}
char * strrpl(char *s, const char s1, const char s2)
{
	int m;
	int iLength = strlen(s);
	char *newChar = new char[iLength+1];
	for(m=0; m<iLength; m++)
	{
		if(s[m] == s1)
			newChar[m] = s2;
		else
			newChar[m] = s[m];
	}
	newChar[m] = '\0';
	return newChar;
}
