  srand(time(NULL));

  // Generate a random star system
  StarSystem* star_system = generate_star_system();

  // Print the star system
  print_star_system(star_system);

  return 0;
}

//MISTRAL-7B DATASET v1.0 Category: Queue Implementation ; Style: grateful
#include <stdio.h>
#include <stdlib.h>
#define MAX_QUEUE_SIZE 10

typedef struct {
    int data[MAX_QUEUE_SIZE];
    int front;
    int rear;
} CircularQueue;

void initializeQueue(CircularQueue *queue) {
    queue->front = 0;
    queue->rear = -1;
}

int enqueue(CircularQueue *queue, int data) {
    if (queue->rear == MAX_QUEUE_SIZE - 1 && queue->front == 0) {
        printf("Queue is Full. Cannot add %d.\n", data);
        return -1;
    }

    if (queue->rear == MAX_QUEUE_SIZE - 1 && queue->front != 0) {
        printf("Queue is Full. Rear is at %d and Front is at %d.\n", queue->rear, queue->front);
        return -1;
    }

    if (queue->rear == MAX_QUEUE_SIZE - 1) {
        queue->rear = 0;
    } else {
        queue->rear++;
    }

    queue->data[queue->rear] = data;
    printf("Added %d to the Queue.\n", data);
    return 1;
}

int dequeue(CircularQueue *queue) {
    if (queue->front == -1 && queue->rear == -1) {
        printf("Queue is Empty.\n");
        return -1;
    }

    if (queue->front == MAX_QUEUE_SIZE - 1 && queue->rear == 0) {
        printf("Queue is Empty. Front is at %d and Rear is at %d.\n", queue->front, queue->rear);
        return -1;
    }

    if (queue->front == MAX_QUEUE_SIZE - 1) {
        queue->front = 0;
    } else {
        queue->front++;
    }

    int data = queue->data[queue->front];
    printf("Removed %d from the Queue.\n", data);
    return data;
}

void displayQueue(CircularQueue queue) {
    if (queue.front == -1 && queue.rear == -1) {
        printf("Queue is Empty.\n");
        return;
    }

    if (queue.front > queue.rear) {
        int i;
        for (i = queue.front; i <= MAX_QUEUE_SIZE - 1; i++) {
            printf("%d ", queue.data[i % MAX_QUEUE_SIZE]);
        }
        for (i = 0; i <= queue.rear; i++) {
            printf("%d ", queue.data[i]);
        }
        printf("\n");
    } else {
        int i;
        for (i = queue.front; i <= queue.rear; i++) {
            printf("%d ", queue.data[i]);
        }
        printf("\n");
    }
}

int main() {
    CircularQueue queue;
    initializeQueue(&queue);
    enqueue(&queue, 5);
    enqueue(&queue, 10);
    enqueue(&queue, 15);
    enqueue(&queue, 20);
    dequeue(&queue);
    dequeue(&queue);
    dequeue(&queue);
    enqueue(&queue, 25);
    displayQueue(queue);
    return 0;
}

