#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define WIDTH 50
#define HEIGHT 50

typedef struct {
    int x;
    int y;
    int alive;
} Cell;

typedef struct {
    Cell cells[WIDTH * HEIGHT];
} Grid;

void initGrid(Grid *grid) {
    int i, j;
    for (i = 0; i < WIDTH; i++) {
        for (j = 0; j < HEIGHT; j++) {
            grid->cells[i * HEIGHT + j].x = i;
            grid->cells[i * HEIGHT + j].y = j;
            grid->cells[i * HEIGHT + j].alive = (i % 2 == 0) && (j % 2 == 0);
        }
    }
}

