int board[BOARD_SIZE][BOARD_SIZE];

// The current player.
int current_player;

// The number of moves that have been made.
int num_moves;

// Function to initialize the board.
void initialize_board() {
  for (int i = 0; i < BOARD_SIZE; i++) {
    for (int j = 0; j < BOARD_SIZE; j++) {
      board[i][j] = 0;
    }
  }
}

// Function to print the board.
void print_board() {
  printf("\n");
  for (int i = 0; i < BOARD_SIZE; i++) {
    for (int j = 0; j < BOARD_SIZE; j++) {
      if (board[i][j] == 0) {
        printf(" ");
      } else if (board[i][j] == 1) {
        printf("X");
      } else {
        printf("O");
      }
    }
    printf("\n");
  }
}

// Function to check if the game is over.
int check_game_over() {
  // Check for a win by player 1.
  for (int i = 0; i < BOARD_SIZE; i++) {
    if (board[i][0] == 1 && board[i][1] == 1 && board[i][2] == 1) {
      return 1;
    }
  }

  // Check for a win by player 2.
  for (int i = 0; i < BOARD_SIZE; i++) {
    if (board[i][0] == 2 && board[i][1] == 2 && board[i][2] == 2) {
      return 2;
    }
  }

  // Check for a win by player 1.
  for (int j = 0; j < BOARD_SIZE; j++) {
    if (board[0][j] == 1 && board[1][j] == 1 && board[2][j] == 1) {
      return 1;
    }
  }

  // Check for a win by player 2.
  for (int j = 0; j < BOARD_SIZE; j++) {
    if (board[0][j] == 2 && board[1][j] == 2 && board[2][j] == 2) {
      return 2;
    }
  }

  // Check for a win by player 1.
  if (board[0][0] == 1 && board[1][1] == 1 && board[2][2] == 1) {
    return 1;
  }

  // Check for a win by player 2.
  if (board[0][0] == 2 && board[1][1] == 2 && board[2][2] == 2) {
    return 2;
  }

  // Check for a win by player 1.
  if (board[0][2] == 1 && board[1][1] == 1 && board[2][0] == 1) {
    return 1;
  }

  // Check for a win by player 2.
  if (board[0][2] == 2 && board[1][1] == 2 && board[2][0] == 2) {
    return 2;
  }

  // Check for a draw.
  if (num_moves == BOARD_SIZE * BOARD_SIZE) {
    return 0;
  }

  // The game is not over yet.
  return -1;
}

// Function to get the next move from the player.
int get_player_move() {
  int move;

  printf("Enter your move (1-9): ");
  scanf("%d", &move);

  // Convert the move to a 0-based index.
  move--;

  // Check if the move is valid.
  if (move < 0 || move >= BOARD_SIZE * BOARD_SIZE || board[move / BOARD_SIZE][move % BOARD_SIZE] != 0) {
    printf("Invalid move. Please try again.\n");
    return -1;
  }

  return move;
}

