#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Grid dimensions
#define WIDTH 100
#define HEIGHT 100

// Probability of a site being open
#define P 0.5

// Initialize the grid
void init_grid(int grid[WIDTH][HEIGHT]) {
  for (int i = 0; i < WIDTH; i++) {
    for (int j = 0; j < HEIGHT; j++) {
      grid[i][j] = (rand() < RAND_MAX * P) ? 1 : 0;
    }
  }
}

// Print the grid
void print_grid(int grid[WIDTH][HEIGHT]) {
  for (int i = 0; i < WIDTH; i++) {
    for (int j = 0; j < HEIGHT; j++) {
      printf("%d ", grid[i][j]);
    }
    printf("\n");
  }
}

// Check if a site is open
int is_open(int grid[WIDTH][HEIGHT], int x, int y) {
  return grid[x][y] == 1;
}

// Check if a site is on the boundary
int is_on_boundary(int x, int y) {
  return x == 0 || x == WIDTH - 1 || y == 0 || y == HEIGHT - 1;
}

// Perform a depth-first search to find all open sites connected to a given site
void dfs(int grid[WIDTH][HEIGHT], int x, int y, int *visited) {
  visited[x * HEIGHT + y] = 1;
  if (is_on_boundary(x, y)) {
    return;
  }
  if (is_open(grid, x - 1, y) && !visited[(x - 1) * HEIGHT + y]) {
    dfs(grid, x - 1, y, visited);
  }
  if (is_open(grid, x + 1, y) && !visited[(x + 1) * HEIGHT + y]) {
    dfs(grid, x + 1, y, visited);
  }
  if (is_open(grid, x, y - 1) && !visited[x * HEIGHT + (y - 1)]) {
    dfs(grid, x, y - 1, visited);
  }
  if (is_open(grid, x, y + 1) && !visited[x * HEIGHT + (y + 1)]) {
    dfs(grid, x, y + 1, visited);
  }
}

// Check if the grid percolates
int percolates(int grid[WIDTH][HEIGHT]) {
  // Initialize the visited array
  int visited[WIDTH * HEIGHT];
  for (int i = 0; i < WIDTH * HEIGHT; i++) {
    visited[i] = 0;
  }

  // Perform a depth-first search from the top row
  for (int i = 0; i < WIDTH; i++) {
    if (is_open(grid, i, 0) && !visited[i * HEIGHT]) {
      dfs(grid, i, 0, visited);
    }
  }

  // Check if any of the sites on the bottom row were visited
  for (int i = 0; i < WIDTH; i++) {
    if (visited[i * HEIGHT + (HEIGHT - 1)]) {
      return 1;
    }
  }

  return 0;
}

int main() {
  // Initialize the random number generator
  srand(time(NULL));

  // Initialize the grid
  int grid[WIDTH][HEIGHT];
  init_grid(grid);

  // Print the grid
  print_grid(grid);

  // Check if the grid percolates
  int result = percolates(grid);

  // Print the result
  printf("The grid %s percolate.\n", result ? "does" : "does not");

  return 0;
}

