#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the number of particles and the simulation time
#define N 100
#define T 1000

// Define the particle structure
typedef struct {
    double x;
    double y;
    double vx;
    double vy;
} Particle;

// Define the simulation function
void simulate(Particle *particles, int n) {
    // Update the position and velocity of each particle
    for (int i = 0; i < n; i++) {
        particles[i].x += particles[i].vx;
        particles[i].y += particles[i].vy;
        particles[i].vx += 0.1 * particles[i].x;
        particles[i].vy += 0.1 * particles[i].y;
    }
}

// Define the main function
int main() {
    // Initialize the particles
    Particle particles[N];
    for (int i = 0; i < N; i++) {
        particles[i].x = (double)i / N * 10.0;
        particles[i].y = (double)i / N * 10.0;
        particles[i].vx = 0.1;
        particles[i].vy = 0.1;
    }

    // Run the simulation for the specified time
    for (int i = 0; i < T; i++) {
        simulate(particles, N);
    }

    // Print the final positions of the particles
    for (int i = 0; i < N; i++) {
        printf("Particle %d: (%f, %f)\n", i, particles[i].x, particles[i].y);
    }

    return 0;
}

