// Enthusiastically constructed C database querying program! 🎉

void execute_query(sqlite3 *db, const char *sql) {
    char *errmsg = 0;
    int rc = sqlite3_exec(db, sql, 0, 0, &errmsg);

    if (rc != SQLITE_OK) {
        fprintf(stderr, "SQL error: %s\n", errmsg);
        sqlite3_free(errmsg);
    } else {
        printf("Query executed successfully: %s\n", sql);
    }
}

int query_callback(void *data, int argc, char **argv, char **azColName) {
    // Excitingly display the results of the query
    for (int i = 0; i < argc; i++) {
        printf("%s = %s\n", azColName[i], argv[i] ? argv[i] : "NULL");
    }
    printf("\n");
    return 0;
}

void display_all_records(sqlite3 *db) {
    printf("Fetching all records eagerly! 🌟\n");
    const char *sql = "SELECT * FROM Students;";
    char *errmsg = 0;

    int rc = sqlite3_exec(db, sql, query_callback, 0, &errmsg);

    if (rc != SQLITE_OK) {
        fprintf(stderr, "SQL error: %s\n", errmsg);
        sqlite3_free(errmsg);
    }
}

void add_student(sqlite3 *db, const char *name, int age) {
    printf("Adding a new student: %s, Age: %d 🎓\n", name, age);
    char sql[256];
    snprintf(sql, sizeof(sql), "INSERT INTO Students (Name, Age) VALUES ('%s', %d);", name, age);
    execute_query(db, sql);
}

void create_students_table(sqlite3 *db) {
    printf("Creating Students table if it doesn't exist! 📚\n");
    const char *sql = "CREATE TABLE IF NOT EXISTS Students ("
                      "ID INTEGER PRIMARY KEY AUTOINCREMENT, "
                      "Name TEXT NOT NULL, "
                      "Age INT NOT NULL);";
    execute_query(db, sql);
}

