#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ARRAY_SIZE 100

void sortC(int arr[], int low, int high);

int main() {
    int arr[MAX_ARRAY_SIZE];
    int i, j, temp;

    // Generate a random array of integers
    for (i = 0; i < MAX_ARRAY_SIZE; i++) {
        arr[i] = rand() % 100;
    }

    // Print the unsorted array
    printf("Unsorted array: \n");
    for (i = 0; i < MAX_ARRAY_SIZE; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");

    // Sort the array using the C sort function
    sortC(arr, 0, MAX_ARRAY_SIZE - 1);

    // Print the sorted array
    printf("Sorted array: \n");
    for (i = 0; i < MAX_ARRAY_SIZE; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");

    return 0;
}

void sortC(int arr[], int low, int high) {
    int i, j, temp;

    // Base case: if the length of the array is 1 or less, return
    if (low >= high) return;

    // Partition the array into two parts: low to mid and mid to high
    int mid = (low + high) / 2;
    for (i = low; i <= high; i++) {
        if (arr[i] <= arr[mid]) {
            // Element is less than or equal to the mid point, so put it in the left partition
            swap(arr[i], arr[low]);
            low++;
        } else {
            // Element is greater than the mid point, so put it in the right partition
            swap(arr[i], arr[high]);
            high--;
        }
    }

    // Recursively sort the left and right partitions
    sortC(arr, low, mid - 1);
    sortC(arr, mid + 1, high);
}

void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

