#define WIDTH 8
#define HEIGHT 8
#define WATERMARK_SIZE 4

// Function to embed the watermark into the image
void embedWatermark(unsigned char image[HEIGHT][WIDTH], unsigned char watermark[WATERMARK_SIZE][WATERMARK_SIZE]) {
    for (int i = 0; i < WATERMARK_SIZE; i++) {
        for (int j = 0; j < WATERMARK_SIZE; j++) {
            // Embed watermark into the least significant bit of the image pixels
            image[i][j] = (image[i][j] & 0xFE) | (watermark[i][j] & 0x01);
        }
    }
}

// Function to extract the watermark from the image
void extractWatermark(unsigned char image[HEIGHT][WIDTH], unsigned char watermark[WATERMARK_SIZE][WATERMARK_SIZE]) {
    for (int i = 0; i < WATERMARK_SIZE; i++) {
        for (int j = 0; j < WATERMARK_SIZE; j++) {
            // Extract the watermark from the least significant bit of the image pixels
            watermark[i][j] = image[i][j] & 0x01;
        }
    }
}

// Function to print the image
void printImage(unsigned char image[HEIGHT][WIDTH]) {
    for (int i = 0; i < HEIGHT; i++) {
        for (int j = 0; j < WIDTH; j++) {
