        { 255, 255, 255, 255, 255, 255, 255, 255 },
        { 255, 255, 255, 255, 255, 255, 255, 255 },
    };

    unsigned char watermark[WATERMARK_SIZE][WATERMARK_SIZE] = {
        { 0, 1, 1, 0 },
        { 1, 0, 0, 1 },
