void initGolfers(void) {
    int i;
    for (i = 0; i < MAX_GOLFERS; i++) {
        sprintf(golfers[i].name, "Golfer %d", i + 1);
        golfers[i].score = 0;
    }
}

// Function to add a score to a golfer
void addScore(int score) {
    int golferIndex = rand() % MAX_GOLFERS;
    golfers[golferIndex].score += score;
}

// Function to print the top 3 golfers
void printTopThree(void) {
    int i, j;
    for (i = 0; i < MAX_GOLFERS; i++) {
        for (j = 0; j < 3; j++) {
            if (golfers[i].score > golfers[i + j].score) {
                break;
            }
        }
        if (j == 3) {
            printf("%s: %d\n", golfers[i].name, golfers[i].score);
        }
    }
}

