#include <stdio.h>

void printBoard(int board[9][9]) {
    // Print the board in a readable format 
    for (int i = 0; i < 9; i++) {
        for (int j = 0; j < 9; j++) {
            printf("%d ", board[i][j]);
            if ((j + 1) % 3 == 0) {
                printf(" ");
            }
        }
        printf("\n");
        if ((i + 1) % 3 == 0) {
            printf("\n");
        }
    }
}

int checkRow(int board[9][9], int row, int num) {
    // Check if num exists in the row
    for (int i = 0; i < 9; i++) {
        if (board[row][i] == num) {
            return 1;
        }
    }
    return 0;
}

int checkCol(int board[9][9], int col, int num) {
    // Check if num exists in the column 
    for (int i = 0; i < 9; i++) {
        if (board[i][col] == num) {
            return 1;
        }
    }
    return 0;
}

int checkBox(int board[9][9], int row, int col, int num) {
    // Check if num exists in the 3x3 box 
    int boxRow = row - (row % 3);
    int boxCol = col - (col % 3);
    for (int i = boxRow; i < boxRow + 3; i++) {
        for (int j = boxCol; j < boxCol + 3; j++) {
            if (board[i][j] == num) {
                return 1;
            }
        }
    }
    return 0;
}

int solveSudoku(int board[9][9], int row, int col) {
    // Solve the Sudoku using recursion
    int nextRow = row;
    int nextCol = col + 1;
    if (nextCol >= 9) {
        nextRow++;
        nextCol = 0;
    }
    if (row >= 9) {
        return 1;
    }
    if (board[row][col] != 0) {
        return solveSudoku(board, nextRow, nextCol);
    } else {
        for (int num = 1; num <= 9; num++) {
            if (!checkRow(board, row, num) && !checkCol(board, col, num) && !checkBox(board, row, col, num)) {
                board[row][col] = num;
                if (solveSudoku(board, nextRow, nextCol)) {
                    return 1;
                }
                board[row][col] = 0;
            }
        }
        return 0;
    }
}

int main() {
    int board[9][9] = {
        {3, 0, 6, 5, 0, 8, 4, 0, 0},
        {5, 2, 0, 0, 0, 0, 0, 0, 0},
        {0, 8, 7, 0, 0, 0, 0, 3, 1},
        {0, 0, 3, 0, 0, 0, 0, 2, 0},
        {9, 0, 0, 8, 0, 0, 0, 0, 5},
        {0, 5, 0, 0, 0, 0, 6, 0, 0},
        {1, 3, 0, 0, 0, 0, 2, 5, 0},
        {0, 0, 0, 0, 0, 0, 0, 7, 4},
        {0, 0, 5, 2, 0, 6, 3, 0, 0}
    };
    printf("Sudoku before solving:\n");
    printBoard(board);
    printf("\nSudoku after solving:\n");
    if (solveSudoku(board, 0, 0)) {
        printBoard(board);
    } else {
        printf("Unable to solve the Sudoku.\n");
    }
    return 0;
}

//Falcon-180B DATASET v1.0 Category: System event logger ; Style: complex
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/stat.h>
#include <fcntl.h>

#define MAX_LOG_SIZE 1000
#define LOG_FILE "event.log"
#define LOG_PERMISSION 0644

typedef struct {
    time_t timestamp;
    char event[100];
} LogEntry;

void log_event(const char* event) {
    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        exit(1);
    }

    LogEntry entry;
    strncpy(entry.event, event, sizeof(entry.event));
    entry.timestamp = time(NULL);

    fwrite(&entry, sizeof(LogEntry), 1, log_file);

    fclose(log_file);
}

void read_log(void) {
    FILE* log_file = fopen(LOG_FILE, "r");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        exit(1);
    }

    LogEntry entry;
    while (fread(&entry, sizeof(LogEntry), 1, log_file) == 1) {
        printf("%s - %s\n", ctime(&entry.timestamp), entry.event);
    }

    fclose(log_file);
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s [event]\n", argv[0]);
        return 1;
    }

    const char* event = argv[1];
    log_event(event);
    printf("Event logged: %s\n", event);

    return 0;
}

