#include <stdio.h>
#include <stdlib.h>

#define N 20
#define SPACE ' '
#define ALIVE '*'

char grid[N][N];

void initGrid() {
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
      grid[i][j] = SPACE;
    }
  }
}

void printGrid() {
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
      printf("%c", grid[i][j]);
    }
    printf("\n");
  }
}

int countNeighbors(int x, int y) {
  int count = 0;
  for (int i = x - 1; i <= x + 1; i++) {
    for (int j = y - 1; j <= y + 1; j++) {
      if (i >= 0 && i < N && j >= 0 && j < N && (i != x || j != y) && grid[i][j] == ALIVE) {
        count++;
      }
    }
  }
  return count;
}

void updateGrid() {
  char nextGrid[N][N];
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
      int neighbors = countNeighbors(i, j);
      if (grid[i][j] == ALIVE && (neighbors == 2 || neighbors == 3)) {
        nextGrid[i][j] = ALIVE;
      } else if (grid[i][j] == SPACE && neighbors == 3) {
        nextGrid[i][j] = ALIVE;
      } else {
        nextGrid[i][j] = SPACE;
      }
    }
  }
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
      grid[i][j] = nextGrid[i][j];
    }
  }
}

int main() {
  initGrid();
  grid[10][10] = ALIVE;
  grid[10][11] = ALIVE;
  grid[10][12] = ALIVE;
  printGrid();
  for (int i = 0; i < 10; i++) {
    updateGrid();
    printGrid();
  }
  return 0;
}

