//GPT-4o-mini DATASET v1.0 Category: Wi-Fi Signal Strength Analyzer ; Style: Ken Thompson
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_NETWORKS 50
#define MAX_SSID_LEN 32
#define MAX_CMD_LEN 256

typedef struct {
    char ssid[MAX_SSID_LEN];
    int signal_strength;
} Network;

void parse_networks(Network *networks, int *count) {
    char cmd[MAX_CMD_LEN];
    FILE *fp;
    char buffer[512];

    sprintf(cmd, "sudo iwlist scan 2>/dev/null");
    fp = popen(cmd, "r");

    if (fp == NULL) {
        fprintf(stderr, "Failed to run command\n");
        exit(1);
    }

    int index = 0;
    while (fgets(buffer, sizeof(buffer), fp) != NULL) {
        if (strstr(buffer, "ESSID:") != NULL) {
            char *ssid = strstr(buffer, "\"") + 1;
            char *end = strstr(ssid, "\"");
            if (end) {
                *end = '\0';
                strncpy(networks[index].ssid, ssid, MAX_SSID_LEN);
            }
        }
        if (strstr(buffer, "Signal level=") != NULL) {
            sscanf(buffer, " Signal level=%d", &networks[index].signal_strength);
            index++;
        }
    }

    pclose(fp);
    *count = index;
}

void display_networks(const Network *networks, int count) {
    printf("%-32s  %s\n", "SSID", "Signal Strength (dBm)");
    printf("%-32s  %s\n", "-----------------------------", "------------------------");

    for (int i = 0; i < count; i++) {
        printf("%-32s  %d\n", networks[i].ssid, networks[i].signal_strength);
    }
}

void sort_networks(Network *networks, int count) {
    for (int i = 0; i < count - 1; i++) {
        for (int j = i + 1; j < count; j++) {
            if (networks[i].signal_strength < networks[j].signal_strength) {
                // Swap
                Network temp = networks[i];
                networks[i] = networks[j];
                networks[j] = temp;
            }
        }
    }
}

int main(void) {
    Network networks[MAX_NETWORKS];
    int count = 0;

    parse_networks(networks, &count);
    if (count == 0) {
        printf("No networks found.\n");
        return 0;
    }

    sort_networks(networks, count);
    display_networks(networks, count);
    return 0;
}

