#define MAX_CANDIDATES 10
#define MAX_VOTERS 1000
#define MAX_NAME_LENGTH 50
#define MAX_PASSWORD_LENGTH 20

typedef struct {
    char name[MAX_NAME_LENGTH];
    char password[MAX_PASSWORD_LENGTH];
    int voted;
} Voter;

typedef struct {
    char name[MAX_NAME_LENGTH];
    int votes;
} Candidate;

Voter voters[MAX_VOTERS];
Candidate candidates[MAX_CANDIDATES];
int num_candidates;
int num_voters;

void initialize() {
    memset(voters, 0, sizeof(voters));
    memset(candidates, 0, sizeof(candidates));
    num_candidates = 0;
    num_voters = 0;
}

void add_candidate(char* name) {
    if (num_candidates >= MAX_CANDIDATES) {
        printf("Error: Maximum number of candidates reached.\n");
        return;
    }

    strcpy(candidates[num_candidates].name, name);
    candidates[num_candidates].votes = 0;
    num_candidates++;
}

void add_voter(char* name, char* password) {
    if (num_voters >= MAX_VOTERS) {
        printf("Error: Maximum number of voters reached.\n");
        return;
    }

    strcpy(voters[num_voters].name, name);
    strcpy(voters[num_voters].password, password);
    voters[num_voters].voted = 0;
    num_voters++;
}

int authenticate_voter(char* name, char* password) {
    int i;

    for (i = 0; i < num_voters; i++) {
        if (!strcmp(voters[i].name, name) &&!strcmp(voters[i].password, password)) {
            return i;
        }
    }

    return -1;
}

void vote(int voter_id, int candidate_id) {
    if (voter_id < 0 || voter_id >= num_voters || candidate_id < 0 || candidate_id >= num_candidates) {
        printf("Error: Invalid voter or candidate ID.\n");
        return;
    }

    if (voters[voter_id].voted) {
        printf("Error: Voter has already voted.\n");
        return;
    }

    voters[voter_id].voted = 1;
    candidates[candidate_id].votes++;
}

void display_results() {
    int i;

    printf("Election Results:\n");
    for (i = 0; i < num_candidates; i++) {
        printf("%s: %d votes\n", candidates[i].name, candidates[i].votes);
    }
}

int main() {
    initialize();

    add_candidate("Alice");
    add_candidate("Bob");
    add_candidate("Charlie");

    add_voter("John", "password123");
    add_voter("Jane", "secret456");

    int voter_id = authenticate_voter("John", "password123");
    if (voter_id >= 0) {
        vote(voter_id, 0);
    }

    voter_id = authenticate_voter("Jane", "secret456");
    if (voter_id >= 0) {
        vote(voter_id, 1);
    }

    display_results();

    return 0;
}

