// Initialize the board with the starting position of pieces
void initializeChessBoard() {
    int i, j;
    // Set the pieces for white players
    chessBoard[0][0] = ROOK;
    chessBoard[0][1] = KNIGHT;
    chessBoard[0][2] = BISHOP;
