// Structs
typedef struct Room Room;
typedef struct Item Item;
struct Room {
    char* name;
    char* description;
    Item* items[MAX_ITEMS];
    int num_items;
    Room* north;
    Room* south;
    Room* east;
    Room* west;
};
struct Item {
    char* name;
