            char item_name[MAX_COMMAND_LENGTH];
            scanf("%s", item_name);
            if (!drop_item(current_room, item_name)) {
                printf("You are not carrying a %s.\n", item_name);
            }
        } else if (strcmp(command, "inventory") == 0) {
            print_inventory();
