void add_entry(char *date, char *entry) {
    // Check if the date is valid
    if (strlen(date) != 10) {
        printf("Invalid date format\n");
        return;
    }

    // Check if the entry is not too long
    if (strlen(entry) > MAX_ENTRY_LENGTH) {
        printf("Entry is too long\n");
        return;
    }

    // Find the next available slot in the diary array
    int i = 0;
    while (i < MAX_DIARY_ENTRIES && diary[i].date[0] != '\0') {
        i++;
    }

    // If no available slot found, wrap around to the beginning of the array
    if (i == MAX_DIARY_ENTRIES) {
        i = 0;
    }

    // Copy the date and entry into the diary array
    strcpy(diary[i].date, date);
    strcpy(diary[i].entry, entry);

