#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure to hold password information
struct password_info {
    char *password;
    int length;
    int has_uppercase;
    int has_lowercase;
    int has_number;
    int has_special;
};

// Function to check if a character is a letter
int is_letter(char c) {
    return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z');
}

// Function to check if a character is a number
int is_number(char c) {
    return (c >= '0' && c <= '9');
}

// Function to check if a character is a special character
int is_special(char c) {
    return !is_letter(c) && !is_number(c);
}

// Function to check the password strength
int check_password_strength(struct password_info *pwd) {
    int strength = 0;
    int length = strlen(pwd->password);
    if (length > 8) {
        strength++;
    }
    if (pwd->has_uppercase) {
        strength++;
    }
    if (pwd->has_lowercase) {
        strength++;
    }
    if (pwd->has_number) {
        strength++;
    }
    if (pwd->has_special) {
        strength++;
    }
    return strength;
}

// Function to check if a password is valid
int is_valid_password(struct password_info *pwd) {
    return check_password_strength(pwd) > 3;
}

// Function to print the password information
void print_password_info(struct password_info *pwd) {
    printf("Password: %s\n", pwd->password);
    printf("Length: %d\n", pwd->length);
    printf("Has uppercase: %s\n", pwd->has_uppercase ? "Yes" : "No");
