// Hex to Decimal conversion function
int hexToDec(char hex[]) {
    int dec = 0, base = 1, i;
    int len = strlen(hex);

    for(i = len-1; i >= 0; i--) {
        if(hex[i] >= '0' && hex[i] <= '9') {
            dec += (hex[i] - 48) * base;
            base *= 16;
        }
        else if(hex[i] >= 'A' && hex[i] <= 'F') {
            dec += (hex[i] - 55) * base;
            base *= 16;
        }
        else if(hex[i] >= 'a' && hex[i] <= 'f') {
            dec += (hex[i] - 87) * base;
            base *= 16;
        }
    }
    return dec;
}

// Decimal to Hex conversion function
void decToHex(int dec) {
    int i = 0, remainder;
    char hex[20];

    while(dec != 0) {
        remainder = dec % 16;
        if(remainder < 10)
            hex[i] = remainder + 48;
        else
            hex[i] = remainder + 55;
        i++;
        dec /= 16;
    }
    printf("Hexadecimal equivalent: ");
    for(i = i-1; i >= 0; i--)
        printf("%c", hex[i]);
}

