void writeMemory(int address, int data) {
  MemoryCell* cell = head;
  while (cell && address > cell->next) {
    cell = cell->next;
  }
  if (cell) {
    cell->data = data;
  } else {
    head = malloc(sizeof(MemoryCell));
    head->data = data;
    head->next = NULL;
  }
}

