char map[MAP_HEIGHT][MAP_WIDTH];

void initializeMap() {
    for (int i = 0; i < MAP_HEIGHT; i++) {
        for (int j = 0; j < MAP_WIDTH; j++) {
            map[i][j] = EMPTY;
        }
    }
}

void drawMap() {
    system("clear");
    for (int i = 0; i < MAP_HEIGHT; i++) {
        for (int j = 0; j < MAP_WIDTH; j++) {
            putchar(map[i][j]);
        }
        putchar('\n');
    }
