                scanf("%s", title);
                addBook(title);
                break;
            case '2':
                printf("Enter the title of the book to search: ");
                scanf("%s", title);
                if (searchBook(title)) {
                    printf("Book found!\n");
                }
                break;
            case '3':
                printf("Enter the title of the book to remove: ");
                scanf("%s", title);
                removeBook(title);
                break;
            case '4':
                quit = true;
                break;
            default:
                printf("Invalid command!\n");
        }
    }

    return 0;
}

