#define TRUE 1
#define FALSE 0

// Define the structure of a robot
typedef struct robot {
    int x;
    int y;
    int theta;
    int v;
    int w;
} Robot;

// Define the functions used in the program
void init(Robot *r);
void set_speed(Robot *r, int v, int w);
void move(Robot *r);
void turn(Robot *r, int theta);
void draw(Robot *r);

// Initialize the robot to its starting position
void init(Robot *r) {
    r->x = 0;
    r->y = 0;
    r->theta = 0;
    r->v = 0;
    r->w = 0;
}

// Set the speed of the robot
void set_speed(Robot *r, int v, int w) {
    r->v = v;
    r->w = w;
}

// Move the robot forward by a given distance
void move(Robot *r) {
    r->x += r->v * cos(r->theta);
    r->y += r->v * sin(r->theta);
}

// Turn the robot by a given angle
void turn(Robot *r, int theta) {
    r->theta += theta;
    while (r->theta < 0) {
        r->theta += 360;
    }
    while (r->theta > 360) {
        r->theta -= 360;
    }
}

// Draw the robot on the screen
void draw(Robot *r) {
    printf("The robot is at (%d, %d) facing %d degrees.\n", r->x, r->y, r->theta);
}

