    Robot r;
    init(&r);
    set_speed(&r, 10, 0);
    move(&r);
    turn(&r, 90);
    move(&r);
    turn(&r, 90);
    move(&r);
    turn(&r, 90);
    move(&r);
    turn(&r, 90);
    move(&r);
    draw(&r);
    return 0;
}

