    strcpy(string2, "Memory palaces are cool");
    *integer = 42;

    // Print allocated memory contents
    printf("String 1: %s\n", string1);
    printf("String 2: %s\n", string2);
    printf("Integer: %d\n", *integer);

    // Free allocated memory
    freeMemory(string1);
    freeMemory(string2);
    freeMemory(integer);

    return 0;
}

