// Function to add two matrices
matrix add_matrices(matrix m1, matrix m2) {
    matrix result;
    int i, j;
    for (i = 0; i < m1.rows; i++) {
        for (j = 0; j < m2.cols; j++) {
            result.data[i * result.cols + j] = m1.data[i * m1.cols + j] + m2.data[i * m2.cols + j];
