#include <stdio.h>
#include <stdbool.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX 1000001

bool is_prime[MAX];
char prime_sieve[MAX / 8];

void sieve_of_eratosthenes() {
    memset(is_prime, true, sizeof(is_prime));
    memset(prime_sieve, 0, sizeof(prime_sieve));

    int square_root_max = sqrt(MAX);

    for (int p = 2; p * p <= MAX; p++) {
        if (is_prime[p]) {
            for (int i = p * p; i <= MAX; i += p) {
                is_prime[i] = false;
                int bit_index = i / 8;
                int bit_position = i % 8;
                prime_sieve[bit_index] &= ~(1 << bit_position);
            }
        }
    }
}

void print_primes(int limit) {
    printf("Primes up to %d:\n", limit);

    for (int i = 2; i <= limit; i++) {
        if (is_prime[i]) {
            printf("%d ", i);
        }
    }
    printf("\n");
}

