    srand(time(NULL));

    sieve_of_eratosthenes();

    int limit = 100;

    while (true) {
        int guess = rand() % (MAX / 2) + (MAX / 2);
        if (is_prime[guess]) {
            print_primes(guess);
            break;
        }
        printf("Not a prime: %d\n", guess);
    }

    return 0;
}

