/* A program to convert Binary Tree to Binary Search Tree */
#include<stdio.h>
#include<stdlib.h>

/* A binary tree node structure */
struct node
{
    int val;
    struct node *left;
    struct node *right;
};

//stores inorder traversal of a tree rooted with node 
void storeInorder (struct node* node, int inorder[], int *index_ptr)
{
    // Base Case
    if (node == NULL)
        return;

    /* first store the left subtree */
    storeInorder (node->left, inorder, index_ptr);

    /* Copy the root's val */
    inorder[*index_ptr] = node->val;
    (*index_ptr)++;  // increase index for next entry

    /* finally store the right subtree */
    storeInorder (node->right, inorder, index_ptr);
}

// count nodes in a Binary Tree
int countNodes (struct node* root)
{
    if (root == NULL)
     return 0;
    return countNodes (root->left) +
           countNodes (root->right) + 1;
}

// Following function is needed for library function qsort()
int compare (const void * a, const void * b)
{
    return ( *(int*)a - *(int*)b );
}

/* A helper function that copies contents of arr[] to Binary Tree. 
   This functon basically does Inorder traversal of Binary Tree and 
   one by one copy arr[] elements to Binary Tree nodes */
void arrayToBST (int *arr, struct node* root, int *index_ptr)
{
    // Base Case
    if (root == NULL)
      return;

    /* first update the left subtree */
    arrayToBST (arr, root->left, index_ptr);

    /* Now update root's val and increment index */
    root->val = arr[*index_ptr];
    (*index_ptr)++;

    /* finally update the right subtree */
    arrayToBST (arr, root->right, index_ptr);
}

// This function converts a given Binary Tree to BST
void binaryTreeToBST (struct node *root)
{
    // base case: tree is empty
    if(root == NULL)
       return;

    /* Count the number of nodes in Binary Tree so that
       we know the size of temporary array to be created */
    int n = countNodes (root);

    // Create a temp array arr[] and store inorder traversal of tree in arr[]
    int *arr = new int[n];
    int i = 0;
    storeInorder (root, arr, &i);

    // Sort the array using library function for quick sort
    qsort (arr, n, sizeof(arr[0]), compare);

    // Copy array elements back to Binary Tree
    i = 0;
    arrayToBST (arr, root, &i);

    // delete dynamically allocated memory to avoid meory leak
    delete [] arr;
}

/* Utility function to create a new Binary Tree node */
struct node* newNode (int val)
{
    struct node *temp = new struct node;
    temp->val = val;
    temp->left = NULL;
    temp->right = NULL;
    return temp;
}

/* Utility function to print inorder traversal of Binary Tree */
void printInorder (struct node* node)
{
    if (node == NULL)
        return;

    /* first recur on left child */
    printInorder (node->left);

    /* then print the val of node */
    printf("%d ", node->val);

    /* now recur on right child */
    printInorder (node->right);
}

/* Driver function to test above functions */
int main()
{
    struct node *root = NULL;

    /* Constructing tree given in the above figure
          1
         /  \
        2    4
       /      \
      3       5   */
    root = newNode(1);
    root->left = newNode(2);
    root->right = newNode(3);
    root->left->left = newNode(4);
    root->right->right = newNode(5);

    // convert Binary Tree to BST
    binaryTreeToBST (root);

    printf("Inorder Traversal of the converted BST: \n");
    printInorder (root);

    return 0;
}

//GPT-4o-mini DATASET v1.0 Category: Remote control Vehicle Simulation ; Style: all-encompassing
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define GRID_SIZE 10

typedef struct {
    int x, y; // Position of the vehicle
    char direction; // Direction the vehicle is facing: N, S, E, W
} Vehicle;

void initializeVehicle(Vehicle *v) {
    v->x = GRID_SIZE / 2;
    v->y = GRID_SIZE / 2;
    v->direction = 'N'; // Start facing North
}

void printGrid(const Vehicle *v) {
    printf("\nVehicle Position: (%d, %d) Facing %c\n", v->x, v->y, v->direction);
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < GRID_SIZE; j++) {
            if (i == v->y && j == v->x) {
                printf("[V] ");
            } else {
                printf("[ ] ");
            }
        }
        printf("\n");
    }
}

void moveForward(Vehicle *v) {
    switch (v->direction) {
        case 'N':
            if (v->y > 0) v->y--;
            break;
        case 'S':
            if (v->y < GRID_SIZE - 1) v->y++;
            break;
        case 'E':
            if (v->x < GRID_SIZE - 1) v->x++;
            break;
        case 'W':
            if (v->x > 0) v->x--;
            break;
    }
}

void moveBackward(Vehicle *v) {
    switch (v->direction) {
        case 'N':
            if (v->y < GRID_SIZE - 1) v->y++;
            break;
        case 'S':
            if (v->y > 0) v->y--;
            break;
        case 'E':
            if (v->x > 0) v->x--;
            break;
        case 'W':
            if (v->x < GRID_SIZE - 1) v->x++;
            break;
    }
}

void turnLeft(Vehicle *v) {
    switch (v->direction) {
        case 'N':
            v->direction = 'W';
            break;
        case 'S':
            v->direction = 'E';
            break;
        case 'E':
            v->direction = 'N';
            break;
        case 'W':
            v->direction = 'S';
            break;
    }
}

void turnRight(Vehicle *v) {
    switch (v->direction) {
        case 'N':
            v->direction = 'E';
            break;
        case 'S':
            v->direction = 'W';
            break;
        case 'E':
            v->direction = 'S';
            break;
        case 'W':
            v->direction = 'N';
            break;
    }
}

void printHelp() {
    printf("Commands:\n");
    printf("  W - Move Forward\n");
    printf("  S - Move Backward\n");
    printf("  A - Turn Left\n");
    printf("  D - Turn Right\n");
    printf("  P - Print Status\n");
    printf("  Q - Quit\n");
}

int main() {
    Vehicle vehicle;
    char command;

    initializeVehicle(&vehicle);
    printHelp();

    do {
        printGrid(&vehicle);
        printf("Enter command: ");
        scanf(" %c", &command);

        switch (command) {
            case 'W':
            case 'w':
                moveForward(&vehicle);
                break;
            case 'S':
            case 's':
                moveBackward(&vehicle);
                break;
            case 'A':
            case 'a':
                turnLeft(&vehicle);
                break;
            case 'D':
            case 'd':
                turnRight(&vehicle);
                break;
            case 'P':
            case 'p':
                printGrid(&vehicle);
                break;
            case 'H':
            case 'h':
                printHelp();
                break;
            case 'Q':
            case 'q':
                printf("Exiting the simulation...\n");
                break;
            default:
                printf("Unknown command!\n");
                break;
        }
    } while (command != 'Q' && command != 'q');

    return 0;
}

