bool user_db_editor::DbContain(std::string tablename, std::string col, std::string target, sqlite3 * db ) {
    char **pResult=NULL;

    char* errmsg;
    int nRow;
    int nCol;
    std::stringstream sqlss;
    sqlss<<"SELECT * from "<<tablename<<" WHERE "<<col<<" Like '"<<target<<"';";
