// Function to calculate the complexity of a sentence
int calculate_complexity(char *sentence) {
    int length = strlen(sentence);
    int complexity = 0;

    // Check for the presence of special characters
    if (strchr(sentence, '!') || strchr(sentence, '@') || strchr(sentence, '#')) {
        complexity++;
    }

    // Check for the presence of digits
    if (strchr(sentence, '0') || strchr(sentence, '1') || strchr(sentence, '2') || strchr(sentence, '3') || strchr(sentence, '4') || strchr(sentence, '5') || strchr(sentence, '6') || strchr(sentence, '7') || strchr(sentence, '8') || strchr(sentence, '9')) {
        complexity++;
    }

    // Check for the presence of uppercase letters
    if (strchr(sentence, 'A') || strchr(sentence, 'B') || strchr(sentence, 'C') || strchr(sentence, 'D') || strchr(sentence, 'E') || strchr(sentence, 'F')) {
        complexity++;
    }

    // Calculate the complexity based on the length of the sentence
    complexity += length;

    return complexity;
}

