int LeftChildPosition(int i) {
    return 2*i+1;
}

int RightChildPosition(int i) {
    return 2*i+2;
}
void SwapElement(int* array,int i,int j) {
    int temp=array[i];
    array[i]=array[j];
    array[j]=temp;
}
//T(n)=O(log(n))
void MaxHeapify(int* array,int i,int length) {
    int l=LeftChildPosition(i);
    int r=RightChildPosition(i);
    int largest=i;
    if(l<length && array[l]>array[i])
        largest=l;
    if(r<length && array[r]>array[largest])
        largest=r;
    if(largest!=i) {
        SwapElement(array,i,largest);
        MaxHeapify(array,largest,length);
    }
}
//T(n)=O(n)
void BuildMaxHeap(int* array,int length) {
    for(int i=length/2-1; i>=0; i--) {
        MaxHeapify(array,i,length);
    }
}

// by increasement order,T(n)=O(nlog(n))
void HeapSort(int* array,int length) {
    BuildMaxHeap(array,length);
    cout<<endl;
    int heap_size=length;
    for(int i=length; i>=2; i--) {
        SwapElement(array,0,i-1);
        heap_size--;
        MaxHeapify(array,0,heap_size);
    }
}

int main() {
    int array[]= {1,2,3,4,8,7,6,5};
    HeapSort(array,sizeof(array)/sizeof(int));
    printArray(array,sizeof(array)/sizeof(int));
    return 0;
}

/**
  *	Dynamic programming - fastest way algorithm implementation from "Introduction to Algorithms"
  *
  */

#include <iostream>

using namespace std;

void fastest_way(int a[][6],int t[][5],int e[],int x[],int n)
{
	int f1[6];
	int f2[6];
	int l1[6],l2[6];

	// Calculate the first entry and station cost for both the lines
	f1[0] = e[0]+a[0][0];
	f2[0] = e[1]+a[1][0];

	for(int j = 1; j < n; j++)
	{
		if( ( f1[j-1]+a[0][j] ) <= ( f2[j-1]+t[1][j-1]+a[0][j] ) )
		{
			f1[j] = f1[j-1]+a[0][j];
			l1[j] = 0;
		}
		else
		{
			f1[j] = f2[j-1]+t[1][j-1]+a[0][j];
			l1[j] = 1;
		}

		if( (f2[j-1] + a[1][j] ) <= (f1[j-1] + t[0][j-1]+a[1][j]) )
		{
			f2[j] = f2[j-1] + a[1][j];
			l2[j] = 1;
		}
		else
		{
			f2[j] = f1[j-1] + t[0][j-1] + a[1][j];
			l2[j] = 0;
		}

	}


	int fastest;
	int lane;
	if (f1[n-1]+x[0] <= f2[n-1]+x[1])
	{
		fastest = f1[n-1]+x[0];
		lane = 0;
	}
	else 
	{
		fastest = f2[n-1]+x[1];
		lane = 1;
	}

	cout << "Fastest time " << fastest << endl;
}


int main(int argc,char **argv)
{
	int e[2] = {2,4};
	int a[2][6] = {{7,9,3,4,8,4},
				   {8,5,6,4,5,7}};

	int t[2][5] = {{2,4,1,3,4},
				   {2,1,2,2,1}};

	int x[2] = {3,2};

	fastest_way(a,t,e,x,6);
	return 0;
}

