//PRE=('p'=0/1)
int scambia (int p)
{
	//Inverto il giocatore, se prima era 0 ora sarà 1, se prima era 1 ora sarà 0...!
	if (p==0)
		p=1;
	else
		p=0;

	return p;

	//L'intero corpo della funzione può essere ugualmente scritto in modo equivalente, ma più compatto, così:  -->  'return !p;'
}
