// Function to calculate the probability of an alien invasion
double calculateProbability(int planetSize, int numMoons, int sunStrength, int ageOfUniverse) {
    // Calculate the distance from the sun to the planet
    double distance = ((double)planetSize / (double)numMoons) * PI;

    // Calculate the probability based on the distance, sun strength, and age of the universe
