#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// A namespace for the artistic expressions we will parse
#define MAX_EXPR 256
#define MAX_TOKENS 10
#define TOKEN_LENGTH 20

// Structure to hold tokens extracted from the expression
typedef struct {
    char tokens[MAX_TOKENS][TOKEN_LENGTH];
    int count;
} Expression;

// Function declarations
void displayTitle();
void parseExpression(const char *expression, Expression *expr);
void displayTokens(const Expression *expr);
int isKeyword(const char *token);
void toLowerCase(char *str);

int main() {
    displayTitle();

    char artisticExpression[MAX_EXPR];
    Expression parsedExpr;

    // Input an artistic expression from the user
    printf("Enter your artistic expression: ");
    fgets(artisticExpression, MAX_EXPR, stdin);

    // Removing the newline character if present
    artisticExpression[strcspn(artisticExpression, "\n")] = 0;

    // Parse the expression
    parseExpression(artisticExpression, &parsedExpr);

    // Display the parsed tokens
    displayTokens(&parsedExpr);

    return 0;
}

// Function to display the title of the program
void displayTitle() {
    printf("*************************************************\n");
    printf("          Artistic Expression Syntax Parser     \n");
    printf("*************************************************\n");
}

// Function to parse the artistic expression into tokens
void parseExpression(const char *expression, Expression *expr) {
    char *token;
    char *expr_copy = strdup(expression);
    expr->count = 0;

    token = strtok(expr_copy, " ");
    while (token != NULL && expr->count < MAX_TOKENS) {
        toLowerCase(token); // Normalize the token to lowercase
        strcpy(expr->tokens[expr->count], token);
        expr->count++;

        token = strtok(NULL, " ");
    }

    free(expr_copy);
}

// Function to display parsed tokens
void displayTokens(const Expression *expr) {
    printf("Parsed Tokens:\n");

    for (int i = 0; i < expr->count; i++) {
        printf("Token %d: %s ", i + 1, expr->tokens[i]);

        // Highlighting keywords
        if (isKeyword(expr->tokens[i])) {
            printf("(keyword)\n");
        } else {
            printf("\n");
        }
    }
}

// Function to check if a token is a keyword
int isKeyword(const char *token) {
    const char *keywords[] = {"if", "else", "while", "return", "for", "void", "int", "char", NULL};
    for (int i = 0; keywords[i] != NULL; i++) {
        if (strcmp(token, keywords[i]) == 0) {
            return 1; // Token is a keyword
        }
    }
    return 0; // Token is not a keyword
}

// Function to convert a string to lowercase
void toLowerCase(char *str) {
    for (int i = 0; str[i]; i++) {
        str[i] = tolower((unsigned char) str[i]);
    }
}

