#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#define WINDOW_WIDTH 80
#define WINDOW_HEIGHT 25
#define ROWS 5
#define COLS 10
#define MAX_SCORE 100

// Structure to store the game state
typedef struct {
    int rows[ROWS];
    int cols[COLS];
    int score;
    int turn;
} game_state_t;

// Function to initialize the game state
void init_game_state(game_state_t *state) {
    int i, j;

    // Initialize game state
    for (i = 0; i < ROWS; i++) {
        state->rows[i] = 0;
        for (j = 0; j < COLS; j++) {
            state->cols[j] = 0;
        }
    }

    // Set the turn to 1
    state->turn = 1;

    // Set the score to 0
    state->score = 0;
}

// Function to draw the game board
void draw_board(game_state_t *state) {
    int i, j;

    // Print the game board
    for (i = 0; i < ROWS; i++) {
        for (j = 0; j < COLS; j++) {
            if (state->rows[i] & (1 << j)) {
                printf("X");
            } else {
                printf(" ");
            }
        }
        printf("\n");
    }
}

// Function to check if a move is valid
int is_move_valid(game_state_t *state, int row, int col) {
    int i, j;

    // Check if the move is within the bounds of the game board
    if (row < 0 || row >= ROWS || col < 0 || col >= COLS) {
        return 0;
    }

    // Check if the move would place a piece on a square that is already occupied
    for (i = 0; i < ROWS; i++) {
        for (j = 0; j < COLS; j++) {
            if (state->rows[i] & (1 << j)) {
                if (i == row && j == col) {
                    return 0;
                }
            }
        }
    }

    return 1;
}

// Function to make a move
void make_move(game_state_t *state, int row, int col) {
    int i, j;

    // Check if the move is valid
    if (!is_move_valid(state, row, col)) {
        printf("Invalid move! Try again.\n");
        return;
    }

    // Set the piece on the game board
    state->rows[row] |= (1 << col);

    // Update the score
    state->score++;

    // Switch turns
    state->turn = state->turn == 1 ? 2 : 1;

    // Redraw the game board
    draw_board(state);
}

// Main game loop
int main() {
    game_state_t state;

    // Initialize the game state
    init_game_state(&state);

    // Draw the game board
    draw_board(&state);

    // Game loop
    while (1) {
        // Print the current state of the game
        printf("Your turn, O player! Where will you place your piece? ");

        // Read the user's move
        int row, col;
        scanf("%d%d", &row, &col);

        // Make the move
        make_move(&state, row, col);
    }

    return 0;
}

