//GEMINI-pro DATASET v1.0 Category: Wireless Network Scanner ; Style: careful
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include <sys/types.h>
#include <sys/socket.h>
#include <sys/ioctl.h>
#include <net/if.h>
#include <netinet/in.h>

#include <arpa/inet.h>

// Define the maximum number of interfaces to scan.
#define MAX_INTERFACES 10

// Define the maximum length of an interface name.
#define MAX_INTERFACE_NAME_LEN 20

// Define the maximum length of an IP address.
#define MAX_IP_ADDR_LEN 20

// Define the maximum length of a MAC address.
#define MAX_MAC_ADDR_LEN 20

// Structure to store the information about each interface.
struct interface_info {
    char name[MAX_INTERFACE_NAME_LEN];
    char ip_addr[MAX_IP_ADDR_LEN];
    char mac_addr[MAX_MAC_ADDR_LEN];
};

// Function to get the list of network interfaces.
int get_network_interfaces(struct interface_info *interfaces) {
    int sock_fd;
    struct ifreq ifr;
    int num_interfaces = 0;

    // Create a socket to get the list of network interfaces.
    sock_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock_fd < 0) {
        perror("socket");
        return -1;
    }

    // Get the list of network interfaces.
    for (int i = 0; i < MAX_INTERFACES; i++) {
        snprintf(ifr.ifr_name, sizeof(ifr.ifr_name), "eth%d", i);
        if (ioctl(sock_fd, SIOCGIFFLAGS, &ifr) < 0) {
            perror("ioctl");
            break;
        }

        // Only include active interfaces.
        if (ifr.ifr_flags & IFF_UP) {
            strncpy(interfaces[num_interfaces].name, ifr.ifr_name, sizeof(interfaces[num_interfaces].name));

            // Get the IP address of the interface.
            if (ioctl(sock_fd, SIOCGIFADDR, &ifr) < 0) {
                perror("ioctl");
                break;
            }

            struct sockaddr_in *addr = (struct sockaddr_in *)&ifr.ifr_addr;
            strncpy(interfaces[num_interfaces].ip_addr, inet_ntoa(addr->sin_addr), sizeof(interfaces[num_interfaces].ip_addr));

            // Get the MAC address of the interface.
            if (ioctl(sock_fd, SIOCGIFHWADDR, &ifr) < 0) {
                perror("ioctl");
                break;
            }

            struct sockaddr *hwaddr = (struct sockaddr *)&ifr.ifr_hwaddr;
            snprintf(interfaces[num_interfaces].mac_addr, sizeof(interfaces[num_interfaces].mac_addr), "%02x:%02x:%02x:%02x:%02x:%02x",
                     hwaddr->sa_data[0], hwaddr->sa_data[1], hwaddr->sa_data[2],
                     hwaddr->sa_data[3], hwaddr->sa_data[4], hwaddr->sa_data[5]);

            num_interfaces++;
        }
    }

    // Close the socket.
    close(sock_fd);

    return num_interfaces;
}

// Function to print the list of network interfaces.
void print_network_interfaces(struct interface_info *interfaces, int num_interfaces) {
    printf("Network Interfaces:\n");
    for (int i = 0; i < num_interfaces; i++) {
        printf("%s: %s (%s)\n", interfaces[i].name, interfaces[i].ip_addr, interfaces[i].mac_addr);
    }
}

// Main function.
int main() {
    struct interface_info interfaces[MAX_INTERFACES];
    int num_interfaces;

    // Get the list of network interfaces.
    num_interfaces = get_network_interfaces(interfaces);

    // Print the list of network interfaces.
    print_network_interfaces(interfaces, num_interfaces);

    return 0;
}

