    printf("Items in thy inventory:\n");
    for (int i = 0; i < count; i++) {
        printf("%s - %d gold coins (%d)\n", items[i].name, items[i].cost, items[i].quantity);
    }
}

void remove_item(struct item items[], int count, char name[]) {
    int found = 0;
    for (int i = 0; i < count; i++) {
