#include <stdlib.h>
#include <time.h>

#define MAX 10

int main() {
    int n, m, x, y, i, j, r, c;
    int **maze;
    time_t t;

    // Allocate memory for the maze
    maze = (int **)malloc(MAX * sizeof(int *));
    for (i = 0; i < MAX; i++) {
        maze[i] = (int *)malloc(MAX * sizeof(int));
    }

    // Generate the maze
    t = time(NULL);
    srand(t);
    for (i = 0; i < MAX; i++) {
        for (j = 0; j < MAX; j++) {
            maze[i][j] = rand() % 2;
        }
    }

    // Find the route
    n = rand() % MAX;
    m = rand() % MAX;
    x = n;
    y = m;
    r = 0;
    c = 0;
    while (x != n || y != m) {
        // Move randomly
        r = rand() % 4;
        switch (r) {
            case 0:
                y--;
                break;
            case 1:
                x++;
                break;
            case 2:
                y++;
                break;
            case 3:
                x--;
                break;
        }

        // Check if the cell is free
        if (maze[x][y] == 0) {
            // Mark the cell as visited
            maze[x][y] = 1;

            // Increment the distance
            c++;

            // Update the position
            x = x;
            y = y;
        }
    }

    // Print the route
    printf("The route is:");
    for (i = 0; i < MAX; i++) {
        for (j = 0; j < MAX; j++) {
            printf("%d ", maze[i][j]);
        }
        printf("\n");
    }

    // Free the memory
    for (i = 0; i < MAX; i++) {
        free(maze[i]);
    }
    free(maze);

    return 0;
}

