// C Benchmarking Example

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Function prototypes
double f(double x);
double g(double x);
double h(double x);

// Main function
int main() {
  // Initialize variables
  int n = 1000000;
  double x, y;
  double startTime, endTime;
  double elapsedTime;

  // Time f()
  startTime = clock();
  for (int i = 0; i < n; i++) {
    x = i / 10000.0;
    y = f(x);
  }
  endTime = clock();
  elapsedTime = (endTime - startTime) / CLOCKS_PER_SEC;
  printf("Time for f(): %f seconds\n", elapsedTime);

  // Time g()
  startTime = clock();
  for (int i = 0; i < n; i++) {
    x = i / 10000.0;
    y = g(x);
  }
  endTime = clock();
  elapsedTime = (endTime - startTime) / CLOCKS_PER_SEC;
  printf("Time for g(): %f seconds\n", elapsedTime);

  // Time h()
  startTime = clock();
  for (int i = 0; i < n; i++) {
    x = i / 10000.0;
    y = h(x);
  }
  endTime = clock();
  elapsedTime = (endTime - startTime) / CLOCKS_PER_SEC;
  printf("Time for h(): %f seconds\n", elapsedTime);

  return 0;
}

// Function definitions
double f(double x) {
  return x * x + 1;
}

double g(double x) {
  return x * x * x - 1;
}

double h(double x) {
  return x * x * x * x + 1;
}

