#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>

// Constants
#define PI 3.14159265358979323846
#define E 2.71828182845904523536
#define INF 1e9
#define EPS 1e-9

// Macros
#define SQR(x) ((x) * (x))
#define ABS(x) (((x) < 0) ? -(x) : (x))
#define MIN(a, b) (((a) < (b)) ? (a) : (b))
#define MAX(a, b) (((a) > (b)) ? (a) : (b))
#define CLAMP(x, a, b) (((x) < (a)) ? (a) : (((x) > (b)) ? (b) : (x)))

// Data structures
typedef struct {
    int x;
    int y;
} Point;

typedef struct {
    Point p1;
    Point p2;
} Line;

typedef struct {
    Point center;
    double radius;
} Circle;

// Function prototypes
Point point_create(int x, int y);
Line line_create(Point p1, Point p2);
Circle circle_create(Point center, double radius);

double distance_between_points(Point p1, Point p2);
double distance_from_point_to_line(Point p, Line l);
double distance_from_point_to_circle(Point p, Circle c);

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Create some random points, lines, and circles
    Point p1 = point_create(rand() % 100, rand() % 100);
    Point p2 = point_create(rand() % 100, rand() % 100);
    Line l = line_create(p1, p2);
    Circle c = circle_create(point_create(rand() % 100, rand() % 100), rand() % 100);

    // Print the points, lines, and circles
    printf("Point p1: (%d, %d)\n", p1.x, p1.y);
    printf("Point p2: (%d, %d)\n", p2.x, p2.y);
    printf("Line l: ((%d, %d), (%d, %d))\n", l.p1.x, l.p1.y, l.p2.x, l.p2.y);
    printf("Circle c: (center: (%d, %d), radius: %f)\n", c.center.x, c.center.y, c.radius);

    // Calculate the distances between the points, lines, and circles
    double distance_p1_p2 = distance_between_points(p1, p2);
    double distance_p1_l = distance_from_point_to_line(p1, l);
    double distance_p1_c = distance_from_point_to_circle(p1, c);

    // Print the distances
    printf("Distance between points p1 and p2: %f\n", distance_p1_p2);
    printf("Distance from point p1 to line l: %f\n", distance_p1_l);
    printf("Distance from point p1 to circle c: %f\n", distance_p1_c);

    return 0;
}

// Function definitions
Point point_create(int x, int y) {
    Point p = {x, y};
    return p;
}

Line line_create(Point p1, Point p2) {
    Line l = {p1, p2};
    return l;
}

Circle circle_create(Point center, double radius) {
    Circle c = {center, radius};
    return c;
}

double distance_between_points(Point p1, Point p2) {
    return sqrt(SQR(p1.x - p2.x) + SQR(p1.y - p2.y));
}

double distance_from_point_to_line(Point p, Line l) {
    double dx = l.p2.x - l.p1.x;
    double dy = l.p2.y - l.p1.y;
    double d = sqrt(SQR(dx) + SQR(dy));
    return ABS(
        (dx * (p.x - l.p1.x) + dy * (p.y - l.p1.y)) / d
    );
}

double distance_from_point_to_circle(Point p, Circle c) {
    return sqrt(SQR(p.x - c.center.x) + SQR(p.y - c.center.y)) - c.radius;
}

