        // Prepare the message data
        msg.msg_type = MSG_TYPE;
        snprintf(msg.msg_text, MSG_SIZE, "Message %d from Producer", count++);

        // Send message to the queue
        if (msgsnd(msgid, &msg, sizeof(msg.msg_text), 0) == -1) {
            perror("Producer: Message send failed");
            exit(EXIT_FAILURE);
        }

        printf("Producer: Sent: %s\n", msg.msg_text);
        sleep(1);  // simulate work
    }
}

void consumer(int msgid) {
    struct message msg;

    while (1) {
        // Receive messages from the queue
        if (msgrcv(msgid, &msg, sizeof(msg.msg_text), MSG_TYPE, 0) == -1) {
            perror("Consumer: Message receive failed");
            exit(EXIT_FAILURE);
        }

        printf("Consumer: Received: %s\n", msg.msg_text);
        sleep(2);  // process the message
    }
}

int main() {
    signal(SIGINT, handle_exit);  // Handle Ctrl+C

    // Create a message queue
    int msgid = msgget(IPC_PRIVATE, 0666 | IPC_CREAT);
    if (msgid == -1) {
        perror("Main: Failed to create message queue");
        exit(EXIT_FAILURE);
    }

    // Fork the process
    pid_t pid = fork();
    if (pid < 0) {
        perror("Main: Fork failed");
        exit(EXIT_FAILURE);
    }

    // In the child process
    if (pid == 0) {
        consumer(msgid);
    } 
    // In the parent process
    else {
        producer(msgid);
    }

    // Cleanup: Will never reach here due to infinite loop
    // But this is good practice
    if (msgctl(msgid, IPC_RMID, NULL) == -1) {
        perror("Main: Failed to remove message queue");
        exit(EXIT_FAILURE);
    }

    return 0;
}

