#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Recursive function to encrypt a message using a Caesar cipher
char *encrypt(char *message, int key, int index) {
    // Base case: reached the end of the message
    if (index == strlen(message)) {
        return message;
    }

    // Encrypt the current character
    char encrypted_character = message[index] + key;

    // Recursively encrypt the rest of the message
    char *encrypted_message = encrypt(message, key, index + 1);

    // Replace the current character with the encrypted character
    encrypted_message[index] = encrypted_character;

    return encrypted_message;
}

// Recursive function to decrypt a message using a Caesar cipher
char *decrypt(char *message, int key, int index) {
    // Base case: reached the end of the message
    if (index == strlen(message)) {
        return message;
    }

    // Decrypt the current character
    char decrypted_character = message[index] - key;

    // Recursively decrypt the rest of the message
    char *decrypted_message = decrypt(message, key, index + 1);

    // Replace the current character with the decrypted character
    decrypted_message[index] = decrypted_character;

    return decrypted_message;
}

int main() {
    // Input message
    char message[] = "Hello, world!";

    // Encryption key
    int key = 3;

    // Encrypt the message
    char *encrypted_message = encrypt(message, key, 0);

    // Print the encrypted message
    printf("Encrypted message: %s\n", encrypted_message);

    // Decrypt the message
    char *decrypted_message = decrypt(encrypted_message, key, 0);

    // Print the decrypted message
    printf("Decrypted message: %s\n", decrypted_message);

    return 0;
}

