#include <string.h>
#include <time.h>
#include <math.h>

#define MAX_NO_OF_ELEMENTS 100000
#define MAX_DEPTH 5

// Structure to represent a node in the tree
typedef struct node {
    int element; // Element stored in the node
    struct node *left; // Left child node
    struct node *right; // Right child node
    int frequency; // Frequency of the element
} node;

// Function to create a new node
node* newNode(int element, int frequency) {
    node* newNode = (node*) malloc(sizeof(struct node));
    newNode->element = element;
    newNode->frequency = frequency;
    newNode->left = NULL;
    newNode->right = NULL;
    return newNode;
}

// Function to insert an element into the tree
void insert(node** root, int element, int frequency) {
    if (*root == NULL) {
        *root = newNode(element, frequency);
        return;
    }

    // Recursive insertion
    if (element < (*root)->element) {
        insert(&(*root)->left, element, frequency);
    } else {
        insert(&(*root)->right, element, frequency);
    }
}

// Function to find the maximum frequency element in the tree
int maxFrequency(node* root) {
    int maxFrequency = 0;

    // Traverse the tree from the root
    traverse(root);

    return maxFrequency;
}

// Function to traverse the tree
void traverse(node* root) {
    if (root != NULL) {
        traverse(root->left);
        printf("%d -> %d\n", root->element, root->frequency);
        traverse(root->right);
    }
}

// Function to build the tree from a list of elements and their frequencies
void buildTree(int* elements, int* frequencies) {
    node* root = NULL;

    // Iterate over the list of elements and their frequencies
    for (int i = 0; i < MAX_NO_OF_ELEMENTS; i++) {
        insert(&root, elements[i], frequencies[i]);
    }

    // Print the maximum frequency element in the tree
    printf("Maximum frequency element: %d\n", maxFrequency(root));
}

int main() {
    // List of elements and their frequencies
    int elements[MAX_NO_OF_ELEMENTS] = {1, 2, 3, 4, 5};
    int frequencies[MAX_NO_OF_ELEMENTS] = {3, 2, 1, 4, 5};

    // Build the tree
    buildTree(elements, frequencies);

    return 0;
}

