    int i,j;
    ImageBool.resize(N);
    for(i=0;i<N;i++){
        ImageBool[i].resize(M);
        for(j=0;j<M;j++){
            ImageBool[i][j]=Image[i][j];
        }
    }
    goButton->setEnabled(true);
}

void RenyiCalculator::calculate()
{
    vector <double> XCoord,YCoord;
    int t;
    int dx, dy;
    int NumPoints;
    double Np[NumBoxes];
    int N=ImageBool.size();
    int M=ImageBool[0].size();
    int i,j,k;
    int x0, y0,x,y;
    XCoord.resize(NumBoxes);
    YCoord.resize(NumBoxes);
    for(k=0; k<NumBoxes;k++){
        if(OffSetComboBox->currentIndex()==1){
            x0=rand()%varOff;
            y0=rand()%varOff;
        } else {
            x0=xOff; y0=yOff;
        }
        t=boxes[k];
        while(t<x0) x0-=t;
        while(t<y0) y0-=t;
        Np[k]=0;
        for(i=-1; i<=(N-x0)/t;i++){
            for(j=-1; j<=(M-y0)/t;j++){
                NumPoints=0;
                for(dx=0; dx<t; dx++){
                    for(dy=0; dy<t; dy++){
                        x=x0+i*t+dx;
                        y=y0+j*t+dy;
                        if(x>=0 && x<N && y>=0 && y<M){
                            if(ImageBool[x][y]==true) NumPoints++;
                        }
                    }
                }
                Np[k]+=pow(NumPoints,Renyi_q);
            }
        }        
        XCoord[k]=log(static_cast<double>(t));
        YCoord[k]=log(static_cast<double>(Np[k]))/(Renyi_q-1);
    }
    plotter->setData(XCoord,YCoord);
    plotter->setType("X-Y");
    plotter->linearFit();
    plotter->makePlot();
    plotter->show();
}

/* This algorithm works better with matrices.
 * Here, vector has been made use of instead of arrays
 */
#include <vector>
#include <iostream>
#include <climits>

using std::vector;

typedef vector<vector<int> > GraphMatrix;

GraphMatrix floyd (const GraphMatrix& g)
{
  GraphMatrix shortestDistances = g;
  int nPoints = shortestDistances.size();

  /* Set points that are not directly reachable to INT_MAX */
  for (int i = 0; i < nPoints; i++)
  {
    for (int j = 0; j < nPoints; j++)
      if (shortestDistances[i][j] == 0 && i != j)
        shortestDistances[i][j] = INT_MAX;
  }
  for (int k = 0; k < nPoints; k++)
  {
    for (int i = 0; i < nPoints; i++)
    {
      for (int j = 0; j < nPoints; j++)
      {
        /* If either of i->k or k->j is infinity (or INT_MAX), then continue to other i,j */
        if (shortestDistances[i][k] == INT_MAX || shortestDistances[k][j] == INT_MAX)
          continue;

        int throughK = shortestDistances[i][k] + shortestDistances[k][j];
        shortestDistances[i][j] = std::min (throughK, shortestDistances[i][j]);
      }
    }
  }

  return shortestDistances;
}

int main(void)
{
  int nPoints;
  /* Read the number of points */
  std::cin >> nPoints;

  GraphMatrix g(nPoints, vector<int>(nPoints));

  int nEdges;
  /* Read the number of edges */
  std::cin >> nEdges;

  /* Read the edges and the weight */
  int v1, v2, weight;
  while (nEdges--)
  {
    std::cin >> v1 >> v2 >> weight;
    g[v1 - 1][v2 - 1] = weight;
  }

  GraphMatrix shortestPaths = floyd(g);

  for (int i = 0; i < nPoints; i++)
  {
    for (int j = 0; j < nPoints; j++)
    {
      std::cout << shortestPaths[i][j] << "\t";
    }
    std::cout << std::endl;
  }
  return 0;
}

