//GEMINI-pro DATASET v1.0 Category: Building a CSV Reader ; Style: complete
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char **fields;
    int num_fields;
    int max_fields;
} CSVRow;

typedef struct {
    CSVRow **rows;
    int num_rows;
    int max_rows;
} CSVTable;

CSVTable *csv_table_create() {
    CSVTable *table = malloc(sizeof(CSVTable));
    if (!table) {
        return NULL;
    }

    table->rows = NULL;
    table->num_rows = 0;
    table->max_rows = 0;

    return table;
}

void csv_table_destroy(CSVTable *table) {
    for (int i = 0; i < table->num_rows; i++) {
        csv_row_destroy(table->rows[i]);
    }
    free(table->rows);
    free(table);
}

CSVRow *csv_row_create() {
    CSVRow *row = malloc(sizeof(CSVRow));
    if (!row) {
        return NULL;
    }

    row->fields = NULL;
    row->num_fields = 0;
    row->max_fields = 0;

    return row;
}

void csv_row_destroy(CSVRow *row) {
    for (int i = 0; i < row->num_fields; i++) {
        free(row->fields[i]);
    }
    free(row->fields);
    free(row);
}

int csv_table_add_row(CSVTable *table, CSVRow *row) {
    if (!table || !row) {
        return -1;
    }

    if (table->num_rows >= table->max_rows) {
        table->max_rows *= 2;
        table->rows = realloc(table->rows, table->max_rows * sizeof(CSVRow *));
        if (!table->rows) {
            return -1;
        }
    }

    table->rows[table->num_rows++] = row;

    return 0;
}

int csv_row_add_field(CSVRow *row, char *field) {
    if (!row || !field) {
        return -1;
    }

    if (row->num_fields >= row->max_fields) {
        row->max_fields *= 2;
        row->fields = realloc(row->fields, row->max_fields * sizeof(char *));
        if (!row->fields) {
            return -1;
        }
    }

    row->fields[row->num_fields++] = field;

    return 0;
}

CSVTable *csv_parse(char *data, char delimiter) {
    CSVTable *table = csv_table_create();
    if (!table) {
        return NULL;
    }

    char *end = data + strlen(data);
    char *line_start = data;
    char *line_end;
    char *field_start;
    char *field_end;

    while ((line_end = memchr(line_start, '\n', end - line_start)) != NULL) {
        CSVRow *row = csv_row_create();
        if (!row) {
            csv_table_destroy(table);
            return NULL;
        }

        field_start = line_start;
        while ((field_end = memchr(field_start, delimiter, line_end - field_start)) != NULL) {
            char *field = strndup(field_start, field_end - field_start);
            if (!field) {
                csv_row_destroy(row);
                csv_table_destroy(table);
                return NULL;
            }

            if (csv_row_add_field(row, field) != 0) {
                csv_row_destroy(row);
                csv_table_destroy(table);
                return NULL;
            }

            field_start = field_end + 1;
        }

        if (line_end - field_start > 0) {
            char *field = strndup(field_start, line_end - field_start);
            if (!field) {
                csv_row_destroy(row);
                csv_table_destroy(table);
                return NULL;
            }

            if (csv_row_add_field(row, field) != 0) {
                csv_row_destroy(row);
                csv_table_destroy(table);
                return NULL;
            }
        }

        if (csv_table_add_row(table, row) != 0) {
            csv_row_destroy(row);
            csv_table_destroy(table);
            return NULL;
        }

        line_start = line_end + 1;
    }

    return table;
}

void csv_print(CSVTable *table) {
    for (int i = 0; i < table->num_rows; i++) {
        CSVRow *row = table->rows[i];
        for (int j = 0; j < row->num_fields; j++) {
            printf("%s", row->fields[j]);
            if (j + 1 < row->num_fields) {
                printf(",");
            }
        }
        printf("\n");
    }
}

int main() {
    char *data = "name,age,gender\nJohn,30,male\nJane,25,female";
    CSVTable *table = csv_parse(data, ',');
    if (!table) {
        return -1;
    }

    csv_print(table);

    csv_table_destroy(table);

    return 0;
}

