#include <stdio.h>
#include <stdlib.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <string.h>
#include <unistd.h>

// Define the port number
#define PORT 8080

int main(int argc, char const *argv[]) {
    // Create a socket
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd == -1) {
        printf("Could not create socket\n");
        exit(1);
    }

    // Define the server address
    struct sockaddr_in servaddr;
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_addr.s_addr = htonl(INADDR_ANY);
    servaddr.sin_port = htons(PORT);

    // Bind the socket to the server address
    if (bind(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) == -1) {
        printf("Could not bind socket\n");
        exit(1);
    }

    // Listen for connections
    if (listen(sockfd, 5) == -1) {
        printf("Could not listen for connections\n");
        exit(1);
    }

    // Accept a connection
    int connfd = accept(sockfd, (struct sockaddr *)NULL, NULL);
    if (connfd == -1) {
        printf("Could not accept connection\n");
        exit(1);
    }

    // Read the message from the client
    char buffer[1024];
    int n;
    n = read(connfd, buffer, 1024);
    if (n == -1) {
        printf("Could not read message from client\n");
        exit(1);
    }

    // Process the message
    int number = atoi(buffer);
    int factorial = 1;
    for (int i = 1; i <= number; i++) {
        factorial *= i;
    }

    // Send the response to the client
    char response[1024];
    sprintf(response, "%d! = %d", number, factorial);
    n = write(connfd, response, strlen(response));
    if (n == -1) {
        printf("Could not write response to client\n");
        exit(1);
    }

    // Close the connection
    close(connfd);
    close(sockfd);

    return 0;
}

