// Function to initialize the game board
void initializeBoard(char board[][BOARD_SIZE]) {

    for (int i = 0; i < BOARD_SIZE; i++) {

        board[1][i] = 'P';
        board[6][i] = 'p';

        switch (i) {
            case 0:
            case 7:
