            case 1:
            case 6:
                board[0][i] = 'N';
                board[7][i] = 'n';
                break;
            case 2:
            case 5:
                board[0][i] = 'B';
                board[7][i] = 'b';
                break;
            case 3:
                board[0][i] = 'Q';
                board[7][i] = 'q';
                break;
            case 4:
                board[0][i] = 'K';
                board[7][i] = 'k';
                break;
        }
