        } else if (abs(dy) > 1 || abs(dx) != 1) {
            printf("\nInvalid move! Exiting...\n");
            exit(0);
        } else if (board[x2][y2] == ' ') {
            printf("\nInvalid move! Exiting...\n");
            exit(0);
        }
