        if (x1 != x2 && y1 != y2) {
            printf("\nInvalid move! Exiting...\n");
            exit(0);
        }

        if (x1 == x2) {
            int start = y1 < y2 ? y1 : y2;
            int end = y1 < y2 ? y2 : y1;

            for (int i = start + 1; i < end; i++) {
                if (board[x1][i] != ' ') {
                    printf("\nInvalid move! Exiting...\n");
                    exit(0);
