            for (int i = start + 1; i < end; i++) {
                if (board[i][y1] != ' ') {
                    printf("\nInvalid move! Exiting...\n");
                    exit(0);
                }
            }
        }
    }

    // Checking if the piece being moved is a knight
    if (piece == 'N' || piece == 'n') {

        int dx = abs(x1 - x2);
        int dy = abs(y1 - y2);

        if (!((dx == 1 && dy == 2) || (dx == 2 && dy == 1))) {
            printf("\nInvalid move! Exiting...\n");
            exit(0);
        }
    }

    // Checking if the piece being moved is a bishop
    if (piece == 'B' || piece == 'b') {

