        if (abs(dx) != abs(dy)) {
            printf("\nInvalid move! Exiting...\n");
            exit(0);
        }

        int i = x1 < x2 ? x1 + 1 : x2 + 1;
        int j = y1 < y2 ? y1 + 1 : y2 + 1;

