#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define PI 3.14159265358979323846

typedef struct {
    double x, y, theta;
} Point;

void move(double dx, double dy, Point* p) {
    double r = sqrt(pow(dx, 2) + pow(dy, 2));
    p->theta += atan2(dy, dx);
    p->x += r * cos(p->theta);
    p->y += r * sin(p->theta);
}

void turn(double dtheta, Point* p) {
    p->theta += dtheta;
}

void draw(Point p, int size) {
    printf("O");
    for (int i = 0; i < size; i++) {
        double r = i / (double)size * 2.0;
        double x = p.x + r * cos(p.theta - PI / 2);
        double y = p.y + r * sin(p.theta - PI / 2);
        printf(".");
        printf("%.2f %.2f\n", x, y);
    }
}

int main() {
    Point robot = {0, 0, 0};
    int size = 10;

    while (1) {
        system("clear");
        printf("Robot at (%.2f, %.2f)\n", robot.x, robot.y);
        draw(robot, size);

        char command[100];
        scanf("%s", command);

        if (strcmp(command, "forward") == 0) {
            double distance;
            scanf("%lf", &distance);
            move(distance, 0, &robot);
        } else if (strcmp(command, "turn") == 0) {
            double angle;
            scanf("%lf", &angle);
            turn(angle, &robot);
        } else if (strcmp(command, "stop") == 0) {
            break;
        } else {
            printf("Invalid command\n");
        }
    }

    return 0;
}

