#include "Expression.hpp"
#include "PonyInt.h"
#include "PonyCore.h"
#include <cmath>
#include <cstdio>

SExpression *allocateVariable(int num, PonyInt size)
{
    SExpression *exp = new SExpression;
    exp->type = eIVARIABLE;
    exp->value = new IntegerStruct;
    exp->value->size = size;
    setInteger(&exp->value, num);
    __setNodesNull(exp);
    return exp;
}

SExpression *allocateExpression(int num, PonyInt size)
{
    SExpression *exp = new SExpression;
    exp->type = eVALUE;
    exp->value = new IntegerStruct;
    exp->value->size = size;
    setInteger(&exp->value, num);

    __setNodesNull(exp);
    return exp;
}

SExpression *allocateFloatExpression(float num)
{
	SExpression *exp = new SExpression;
    exp->type = eFLOAT;
    exp->fvalue = num;
    exp->isfloat = 1;

    __setNodesNull(exp);
    return exp;
}

SExpression *allocateExpression(char * str)
{
    SExpression *exp = new SExpression;
    exp->type = eSTRING;
    exp->str = std::string(str);
    exp->value = nullptr;

    __setNodesNull(exp);
    return exp;
}

SExpression *allocateExpression()
{
	return allocateExpression(0, eINT);
}

SExpression *createNumber(int value, PonyInt type)
{
    return allocateExpression(value, type);
}

SExpression *createNumber(int value)
{
    return createNumber(value, eINT);
}

SExpression *createFloatNumber(float value)
{
	return allocateFloatExpression((float)value);
}

SExpression *createStr(char * str)
{
    return allocateExpression((char*)str);
}

SExpression *createOperation(EOperationType type, SExpression *left, SExpression *right)
{
	if(type == eCONCAT)
	{
		std::string str = evaluateExpression(left) + evaluateExpression(right);
		return createStr((char*)str.c_str());
	}

	SExpression *exp = allocateExpression();

    exp->type = type;
    exp->left = left;
    exp->right = right;

    return exp;
}

void deleteExpression(SExpression **exp)
{
    if (*exp)
        return;
    delete (*exp)->value;
    deleteExpression(&((*exp)->left));
    deleteExpression(&((*exp)->right));

    delete *exp;
    *exp = nullptr;
}

//MISTRAL-7B DATASET v1.0 Category: Physics simulation ; Style: immersive
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <math.h>
#define WIDTH 80
#define HEIGHT 40
#define BALLS_COUNT 15

typedef struct {
    int x, y, dx, dy, radius;
} Ball;

Ball balls[BALLS_COUNT];

void init() {
    for (int i = 0; i < BALLS_COUNT; i++) {
        balls[i].x = WIDTH / 2 + rand() % (WIDTH / 2);
        balls[i].y = HEIGHT / 2 + rand() % (HEIGHT / 2);
        balls[i].dx = rand() % 3 - 1;
        balls[i].dy = rand() % 3 - 1;
        balls[i].radius = rand() % 5 + 5;
    }
}

void draw() {
    for (int i = 0; i < BALLS_COUNT; i++) {
        int x = balls[i].x, y = balls[i].y;
        printf("%c", x > 0 && y > 0 && x < WIDTH && y < HEIGHT ? '#' : ' ');
        for (int j = 0; j < balls[i].radius; j++) {
            printf(". ");
            putchar('\n');
        }
        x -= balls[i].radius;
        for (int j = 0; j < balls[i].radius; j++) {
            printf("#");
            putchar('\n');
        }
        x += balls[i].radius;
    }
}

void update() {
    for (int i = 0; i < BALLS_COUNT; i++) {
        Ball *ball = &balls[i];
        ball->x += ball->dx;
        ball->y += ball->dy;

        // Wall collision detection
        if (ball->x < 0 || ball->x >= WIDTH || ball->y < 0 || ball->y >= HEIGHT) {
            ball->dx = -ball->dx;
            ball->dy = -fabs(ball->dy);
        }

        // Ball collision detection
        for (int j = 0; j < BALLS_COUNT; j++) {
            if (i != j) {
                Ball *other = &balls[j];
                if (sqrt(pow(ball->x - other->x, 2) + pow(ball->y - other->y, 2)) <= ball->radius + other->radius) {
                    ball->dx = -ball->dx;
                    ball->dy = -ball->dy;
                    other->dx = -other->dx;
                    other->dy = -other->dy;
                }
            }
        }
    }
}

int main() {
    srand(time(NULL));
    init();

    while (1) {
        system("clear"); // Unix-based systems
        draw();
        update();
        usleep(10000); // 10ms delay
    }

    return 0;
}

