#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <netdb.h>
#include <unistd.h>

#define MAX_BUFFER_SIZE 4096

void proxy(int clientfd, int serverfd)
{
    char buffer[MAX_BUFFER_SIZE];

    // Loop to read data from client and write to server
    while (1)
    {
        int bytesRead = read(clientfd, buffer, MAX_BUFFER_SIZE);

        if (bytesRead > 0)
        {
            write(serverfd, buffer, bytesRead);
        }
        else if (bytesRead == 0)
        {
            close(clientfd);
            close(serverfd);
            break;
        }
        else
        {
            perror("Error reading from client");
            close(clientfd);
            close(serverfd);
            break;
        }
    }
}

int main()
{
    int clientfd, serverfd;
    struct sockaddr_in clientSock, serverSock;

    // Create a socket for the proxy
    serverfd = socket(AF_INET, SOCK_STREAM, htons(8080));

    // Bind the socket to a port
    bind(serverfd, (struct sockaddr *)&serverSock, sizeof(serverSock));

    // Listen for clients
    while (1)
    {
        // Accept a client connection
        clientfd = accept(serverfd, (struct sockaddr *)&clientSock, NULL);

        // Create a new thread for the client connection
        proxy(clientfd, serverfd);
    }

    return 0;
}

