    for(int i=0;i<8;i++)
    {
        for(int j=0;j<8;j++)
        {
            switch(board[i][j])
            {
                case 'P': score += 10;
                    break;
                case 'p': score -= 10;
                    break;
                case 'N': score += 30;
                    break;
                case 'n': score -= 30;
                    break;
                case 'B': score += 30;
                    break;
                case 'b': score -= 30;
                    break;
                case 'R': score += 50;
                    break;
                case 'r': score -= 50;
                    break;
                case 'Q': score += 90;
                    break;
                case 'q': score -= 90;
                    break;
            }
        }
    }
    return score;
}

int min(int a,int b)
{
    return a<b?a:b;
}

int max(int a,int b)
{
    return a>b?a:b;
}

int alpha_beta_prune(char board[][8],int depth,int alpha,int beta,bool player)
{
    if(depth==0)
    {
        return eval(board);
    }
    if(player)
    {
        int score = -INFINITY;
        for(int i=0;i<8;i++)
