                        for(int m=0;m<8;m++)
                        {
                            if(board[p][m]==' ')
                            {
                                board[p][m] = o;
                                int temp = alpha_beta_prune(board,depth-1,alpha,beta,false);
                                board[p][m] = ' ';
                                score = max(score,temp);
                                alpha = max(alpha,score);
                                if(beta<=alpha)
                                {
                                    return score;
                                }
                            }
                        }
                    }
                    board[i][j] = o;
                }
            }
        }
        return score;
    }
    else
    {
        int score = INFINITY;
