                            {
                                board[p][m] = o;
                                int temp = alpha_beta_prune(board,depth-1,alpha,beta,true);
                                board[p][m] = ' ';
                                score = min(score,temp);
                                beta = min(beta,score);
                                if(beta<=alpha)
                                {
                                    return score;
                                }
                            }
                        }
                    }
                    board[i][j] = o;
                }
            }
        }
        return score;
    }
}

