#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define TABLE_SIZE 10
#define PIECES_PER_PLAYER 5
#define GAME_OVER_THRESHOLD 3

typedef struct {
    int x;
    int y;
} Piece;

typedef struct {
    Piece pieces[TABLE_SIZE][PIECES_PER_PLAYER];
    int player;
} Game;

void init_game(Game *game) {
    for (int i = 0; i < TABLE_SIZE; i++) {
        for (int j = 0; j < PIECES_PER_PLAYER; j++) {
            game->pieces[i][j].x = i * 10 + j * 2;
            game->pieces[i][j].y = i * 10 + j * 2;
        }
    }
    game->player = 0;
}

void move_piece(Game *game, int x, int y) {
    for (int i = 0; i < TABLE_SIZE; i++) {
        for (int j = 0; j < PIECES_PER_PLAYER; j++) {
            if (game->pieces[i][j].x == x && game->pieces[i][j].y == y) {
                game->pieces[i][j].x += 2;
                if (game->pieces[i][j].x >= 10) {
                    game->pieces[i][j].x = 0;
                }
                return;
            }
        }
    }
}

void game_over(Game *game) {
    int pieces_left = 0;
    for (int i = 0; i < TABLE_SIZE; i++) {
        for (int j = 0; j < PIECES_PER_PLAYER; j++) {
            if (game->pieces[i][j].x != 0) {
                pieces_left++;
            }
        }
    }
    if (pieces_left <= GAME_OVER_THRESHOLD) {
        printf("Game Over! Player %d wins!\n", game->player);
    } else {
        printf("Game Over! No one wins!\n");
    }
}

int main() {
    srand(time(NULL));
    Game game;
    init_game(&game);

    for (int i = 0; i < 100; i++) {
        int x = rand() % 10;
        int y = rand() % 10;
        move_piece(&game, x, y);
        game_over(&game);
    }

    return 0;
}

