//Gemma-7B DATASET v1.0 Category: Interprocess communication ; Style: safe
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ipc.h>
#include <sys/msg.h>

#define IPC_KEY 1234
#define MSG_SIZE 1024

struct msg_st {
    long m_type;
    char m_mtext[MSG_SIZE];
};

int main()
{
    int msg_id;
    struct msg_st msg;

    // Create a message queue
    msg_id = msgget(IPC_KEY, IPC_CREAT);
    if (msg_id == -1)
    {
        perror("Error creating message queue");
        exit(1);
    }

    // Prepare the message
    msg.m_type = 1;
    strcpy(msg.m_mtext, "Hello, world!");

    // Send the message
    if (msgsnd(msg_id, &msg, sizeof(msg), 0) == -1)
    {
        perror("Error sending message");
        exit(1);
    }

    // Receive the message
    if (msgrcv(msg_id, &msg, sizeof(msg), 0, 0) == -1)
    {
        perror("Error receiving message");
        exit(1);
    }

    // Display the message
    printf("Received message: %s\n", msg.m_mtext);

    // Destroy the message queue
    msgctl(msg_id, IPC_RMID, NULL);

    return 0;
}

