#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <pthread.h>

#define MAX 100
#define PORT 8080

int sockfd, newsockfd, clilen, addrlen;
struct sockaddr_in serv_addr, cli_addr;
int opt = 1;
char buffer[1024];
pthread_t thread_id;

void *thread_function(void *arg) {
    while(1) {
        recv(newsockfd, buffer, sizeof(buffer), 0);
        printf("Received message: %s\n", buffer);
    }
}

int main() {
    int i, valread, sd;
    char *message = "Welcome to the Classical Circuit Simulator!";

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt));

    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = htons(PORT);

    if (bind(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    listen(sockfd, 5);
    clilen = sizeof(cli_addr);
    puts("Waiting for connections...");

    while(1) {
        newsockfd = accept(sockfd, (struct sockaddr *)&cli_addr, &clilen);
        if (newsockfd < 0) {
            perror("accept failed");
            exit(EXIT_FAILURE);
        }

        printf("New connection from: %s:%d\n", inet_ntoa(cli_addr.sin_addr), ntohs(cli_addr.sin_port));

        pthread_create(&thread_id, NULL, thread_function, (void *)newsockfd);
    }

    return 0;
}

