                Mc = 999;
            }
            else if (checkFibonacci(i + 1) == 1)
            {
                int h1 = FormulaB(i + 1, r);
                int h2 = FormulaB(array[i], r);
                if (h1 < h2)
                {
                    cout << -1;
                    return;
                }
                else if (h1 >= h2)
                {
                    HPc = HPmax;
                    Mc = 999;
                }
            }
            else
            {
                cout << -1;
                return;
            }
        }
