#define MAX_BUFFER 1024
#define PORT 8080

// Structure to hold Quality of Service (QoS) metrics
typedef struct {
    float latency;
    float packet_loss;
    float jitter;
} QoS_Metrics;

// Function declarations
void initialize_socket(int *sockfd);
void calculate_qos(QoS_Metrics *qos);
void report_qos(const QoS_Metrics *qos);
void simulate_data_transfer(int sockfd, struct sockaddr_in *server_addr);
void print_delim_line(void);
void get_current_time(char *buffer, size_t size);

int main() {
    int sockfd;
    QoS_Metrics qos;

    printf("Welcome to the Network Quality of Service (QoS) Monitor!\n");
    print_delim_line();

    // Initialize socket
    initialize_socket(&sockfd);

    // Set server address details
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    server_addr.sin_addr.s_addr = inet_addr("127.0.0.1");

    // Simulate data transfer and calculate QoS
    simulate_data_transfer(sockfd, &server_addr);
    calculate_qos(&qos);

    // Report QoS metrics
    report_qos(&qos);

    // Close the socket
    close(sockfd);
    return 0;
}

void initialize_socket(int *sockfd) {
    *sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (*sockfd < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }
    printf("Socket created successfully.\n");
}

void calculate_qos(QoS_Metrics *qos) {
    srand(time(NULL));
    qos->latency = (rand() % 100) + 1;         // Simulate latency in ms
    qos->packet_loss = (rand() % 10) * 10;    // Simulate packet loss in percentage
    qos->jitter = (rand() % 30) + 1;           // Simulate jitter in ms
}

void report_qos(const QoS_Metrics *qos) {
    char time_buffer[20];
    get_current_time(time_buffer, sizeof(time_buffer));

    printf("QoS Report at %s:\n", time_buffer);
    print_delim_line();
    printf("Latency: %.2f ms\n", qos->latency);
    printf("Packet Loss: %.2f %%\n", qos->packet_loss);
    printf("Jitter: %.2f ms\n", qos->jitter);
    print_delim_line();
}

void simulate_data_transfer(int sockfd, struct sockaddr_in *server_addr) {
    char buffer[MAX_BUFFER];
    snprintf(buffer, sizeof(buffer), "Hello Server!");
    sendto(sockfd, buffer, strlen(buffer), 0, (struct sockaddr *)server_addr, sizeof(*server_addr));
    printf("Data sent to server.\n");
}

void print_delim_line(void) {
    printf("-----------------------------------------\n");
}

void get_current_time(char *buffer, size_t size) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    strftime(buffer, size, "%Y-%m-%d %H:%M:%S", t);
}

