    srand(time(NULL));

    // Set up the game parameters
    int paddle_x = 50;
    int paddle_y = 25;
    int ball_x = 75;
    int ball_y = 50;
    int ball_dx = -1;
    int ball_dy = 1;
    int score = 0;

    // Loop until one player reaches a score of 10
    while (score < 10)
    {
        // Get the player's input
        char input = getchar();

        // Move the paddle
        switch (input)
        {
            case 'w':
                paddle_y--;
                break;
            case 's':
                paddle_y++;
                break;
        }

        // Update the ball's position
