#define MAX_LENGTH 100

// Function prototypes
void sanitize_input(const char *input, char *output);
void print_welcome_message();
void print_exit_message();

int main() {
    char raw_input[MAX_LENGTH];
    char sanitized_output[MAX_LENGTH];

    print_welcome_message();

    while (1) {
        printf("\nEnter a string to be sanitized (or type 'exit' to quit): ");
        fgets(raw_input, sizeof(raw_input), stdin);

        // Remove newline character if present
        raw_input[strcspn(raw_input, "\n")] = 0;

        // Check for exit condition
        if (strcmp(raw_input, "exit") == 0) {
            print_exit_message();
            break;
        }

        // Sanitize the input
        sanitize_input(raw_input, sanitized_output);

        // Display the sanitized result
        printf("\nSanitized Output: %s\n", sanitized_output);
    }

    return 0;
}

// Function to sanitize user input
void sanitize_input(const char *input, char *output) {
    int index = 0;
    for (int i = 0; i < strlen(input); i++) {
        // Allow only alphabetic characters, numbers, white spaces, and some punctuation
        if (isalnum(input[i]) || isspace(input[i]) || input[i] == '.' || input[i] == ',' || input[i] == '-') {
            output[index++] = input[i];
        }
    }
    output[index] = '\0'; // Null-terminate the output string
}

// Function to print a welcome message
void print_welcome_message() {
    printf("***********************************\n");
    printf("! Welcome to the Input Sanitizer !\n");
    printf("***********************************\n");
    printf("We transform your input into a safe format.\n");
    printf("Type 'exit' anytime to leave the program.\n");
}

// Function to print an exit message
void print_exit_message() {
    printf("\nThank you for using the Input Sanitizer! 🎉\n");
    printf("Goodbye! Have a great day! 😊\n");
}

#ifndef GAME_TILESET_CPP

