        verts[i].b = 0.5f;
        verts[i].x *= size.x; verts[i].y *= size.y; verts[i].z *= size.z;
    }

    ind[ 0] = 0; ind[ 1] = 1; ind[ 2] = 3; ind[ 3] = 2;
    ind[ 4] = 4; ind[ 5] = 6; ind[ 6] = 7; ind[ 7] = 5;
