//LLAMA2-13B DATASET v1.0 Category: System event logger ; Style: recursive
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>

#define MAX_MSG_LEN 1024
#define MAX_LOG_LEVEL 8

struct log_record {
    int level;
    char message[MAX_MSG_LEN];
    struct timespec timestamp;
};

void log_record_init(struct log_record *record, int level, const char *message) {
    record->level = level;
    strncpy(record->message, message, MAX_MSG_LEN);
    clock_gettime(CLOCK_MONOTONIC, &record->timestamp);
}

void log_record_print(struct log_record *record) {
    switch (record->level) {
        case LOG_EMERG:
            printf("EMERGENCY: %s\n", record->message);
            break;
        case LOG_ALERT:
            printf("ALERT: %s\n", record->message);
            break;
        case LOG_CRIT:
            printf("CRITICAL: %s\n", record->message);
            break;
        case LOG_ERR:
            printf("ERROR: %s\n", record->message);
            break;
        case LOG_WARNING:
            printf("WARNING: %s\n", record->message);
            break;
        case LOG_NOTICE:
            printf("NOTICE: %s\n", record->message);
            break;
        case LOG_INFO:
            printf("INFO: %s\n", record->message);
            break;
        case LOG_DEBUG:
            printf("DEBUG: %s\n", record->message);
            break;
        default:
            printf("UNKNOWN (%d): %s\n", record->level, record->message);
            break;
    }
}

void log_recursive(int level, const char *message) {
    struct log_record record;
    log_record_init(&record, level, message);
    log_record_print(&record);
    if (level > 0) {
        log_recursive(level - 1, message);
    }
}

int main() {
    log_recursive(LOG_INFO, "Starting up");
    log_recursive(LOG_DEBUG, "Initializing");
    log_recursive(LOG_INFO, "Ready");
    return 0;
}

