//GPT-4o-mini DATASET v1.0 Category: GPS Navigation Simulation ; Style: ultraprecise
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LOCATIONS 10
#define MAX_NAME_LENGTH 50

typedef struct {
    char name[MAX_NAME_LENGTH];
    float latitude;
    float longitude;
} Location;

typedef struct {
    Location locations[MAX_LOCATIONS];
    int count;
} LocationManager;

void initialize(LocationManager *manager) {
    manager->count = 0;
}

void add_location(LocationManager *manager, const char *name, float latitude, float longitude) {
    if (manager->count < MAX_LOCATIONS) {
        strncpy(manager->locations[manager->count].name, name, MAX_NAME_LENGTH);
        manager->locations[manager->count].latitude = latitude;
        manager->locations[manager->count].longitude = longitude;
        manager->count++;
    } else {
        printf("Location limit reached! Cannot add more locations.\n");
    }
}

void list_locations(LocationManager *manager) {
    printf("Available Locations:\n");
    for (int i = 0; i < manager->count; i++) {
        printf("%d: %s (Lat: %.6f, Lon: %.6f)\n", i + 1, manager->locations[i].name, manager->locations[i].latitude, manager->locations[i].longitude);
    }
}

void simulate_route(Location *start, Location *end) {
    printf("Navigating from %s to %s...\n", start->name, end->name);
    printf("Starting at: %.6f, %.6f\n", start->latitude, start->longitude);
    printf("Moving towards: %.6f, %.6f\n", end->latitude, end->longitude);

    for (int i = 1; i <= 5; i++) { // Simulate 5 steps towards the destination
        printf("Step %d: Approaching towards %s...\n", i, end->name);
    }

    printf("Arrival at %s! Enjoy your destination!\n", end->name);
}

int main() {
    LocationManager manager;
    initialize(&manager);

    // Add some predefined locations
    add_location(&manager, "Home", 40.712776, -74.005974); // New York
    add_location(&manager, "Office", 37.774929, -122.419418); // San Francisco
    add_location(&manager, "Airport", 41.974162, -87.907321); // Chicago O'Hare
    add_location(&manager, "Cafe", 34.052235, -118.243683); // Los Angeles

    while (1) {
        printf("\nGPS Navigation System\n");
        printf("1. List Locations\n");
        printf("2. Set Destination\n");
        printf("3. Exit\n");

        int choice;
        printf("Enter your choice: ");
        if (scanf("%d", &choice) != 1) {
            printf("Invalid input. Please enter a number.\n");
            while(getchar() != '\n'); // clear invalid input
            continue;
        }

        switch (choice) {
            case 1:
                list_locations(&manager);
                break;
            case 2: {
                int start_idx, end_idx;
                printf("Select Start Location (1 to %d): ", manager.count);
                scanf("%d", &start_idx);
                printf("Select End Location (1 to %d): ", manager.count);
                scanf("%d", &end_idx);

                if (start_idx > 0 && start_idx <= manager.count && end_idx > 0 && end_idx <= manager.count) {
                    simulate_route(&manager.locations[start_idx - 1], &manager.locations[end_idx - 1]);
                } else {
                    printf("Invalid selection. Please choose a valid location index.\n");
                }
                break;
            }
            case 3:
                printf("Exiting GPS Navigation System. Safe travels!\n");
                exit(0);
            default:
                printf("Invalid choice. Please try again.\n");
        }
    }
    return 0;
}

