void placeOrder(int customerId, int itemId, int quantity) {
    Order newOrder;
    newOrder.customerId = customerId;
    newOrder.itemId = itemId;
    newOrder.quantity = quantity;
    newOrder.totalPrice = items[itemId].price * quantity;

    for (int i = 0; i < numOrders; i++) {
        if (orders[i].customerId == customerId && orders[i].itemId == itemId) {
            orders[i].quantity += quantity;
            orders[i].totalPrice += newOrder.totalPrice;
            return;
        }
    }

    orders[numOrders] = newOrder;
    numOrders++;
}

void printCustomerOrders(int customerId) {
    for (int i = 0; i < numOrders; i++) {
        if (orders[i].customerId == customerId) {
            printf("Order %d: %s - %d units - $%.2f\n", i+1, items[orders[i].itemId].name, orders[i].quantity, orders[i].totalPrice);
        }
    }
}

