// Function to convert English character to Alien character
char to_alien_language(char ch) {
    // Mapping of ASCII A-Z to Alien A-Z (shifting by 3)
    if (ch >= 'A' && ch <= 'Z') {
        return 'A' + (ch - 'A' + 3) % ALIEN_LANGUAGE_SIZE;
    }
    if (ch >= 'a' && ch <= 'z') {
        return 'a' + (ch - 'a' + 3) % ALIEN_LANGUAGE_SIZE;
    }
    return ch; // Non-alphabet characters are unchanged
}

