#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#define MAX_WORDS 1000
#define WORD_LENGTH 50
typedef struct {
    char word[WORD_LENGTH];
    int count;
} WordStats;
void process_line(char *line, WordStats words[]) {
    char *token = strtok(line, " \t\n\r,;.:!?(){}[]");
    int index = 0;
    while (token != NULL) {
        if (index < MAX_WORDS) {
            strcpy(words[index].word, token);
            words[index].count = 1;
            index++;
        } else {
            printf("Error: too many words in line.\n");
            exit(EXIT_FAILURE);
        }
        token = strtok(NULL, " \t\n\r,;.:!?(){}[]");
    }
}
int main(int argc, char *argv[]) {
    FILE *file;
    char line[1024];
    WordStats words[MAX_WORDS];
    int num_words = 0;
    if (argc != 2) {
        printf("Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }
    file = fopen(argv[1], "r");
    if (file == NULL) {
        printf("Error: could not open file %s\n", argv[1]);
        return EXIT_FAILURE;
    }
    while (fgets(line, sizeof(line), file) != NULL) {
        process_line(line, words);
        num_words += MAX_WORDS;
    }
    fclose(file);
    printf("File '%s' contains the following %d unique words:\n", argv[1], num_words);
    for (int i = 0; i < num_words; i++) {
        printf("%s: %d\n", words[i].word, words[i].count);
    }
    return EXIT_SUCCESS;
}

