#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the maximum number of files and blocks
#define MAX_FILES 10
#define MAX_BLOCKS 100

// Define the file system structure
typedef struct {
  char name[32];
  int size;
  int blocks[MAX_BLOCKS];
} file_t;

// Define the block structure
typedef struct {
  int used;
  char data[512];
} block_t;

// Define the file system
file_t files[MAX_FILES];
block_t blocks[MAX_BLOCKS];

// Initialize the file system
void init_fs() {
  for (int i = 0; i < MAX_FILES; i++) {
    strcpy(files[i].name, "");
    files[i].size = 0;
    for (int j = 0; j < MAX_BLOCKS; j++) {
      files[i].blocks[j] = -1;
    }
  }

  for (int i = 0; i < MAX_BLOCKS; i++) {
    blocks[i].used = 0;
    memset(blocks[i].data, 0, 512);
  }
}

// Create a new file
int create_file(char *name) {
  for (int i = 0; i < MAX_FILES; i++) {
    if (strcmp(files[i].name, "") == 0) {
      strcpy(files[i].name, name);
      files[i].size = 0;
      return i;
    }
  }

  return -1;
}

// Delete a file
int delete_file(char *name) {
  for (int i = 0; i < MAX_FILES; i++) {
    if (strcmp(files[i].name, name) == 0) {
      strcpy(files[i].name, "");
      files[i].size = 0;
      for (int j = 0; j < MAX_BLOCKS; j++) {
        files[i].blocks[j] = -1;
      }

      return 0;
    }
  }

  return -1;
}

// Write data to a file
int write_file(char *name, char *data, int size) {
  int file_index = -1;

  for (int i = 0; i < MAX_FILES; i++) {
    if (strcmp(files[i].name, name) == 0) {
      file_index = i;
      break;
    }
  }

  if (file_index == -1) {
    return -1;
  }

  int blocks_needed = (size + 511) / 512;
  int blocks_allocated = 0;

  for (int i = 0; i < MAX_BLOCKS; i++) {
    if (blocks[i].used == 0) {
      blocks[i].used = 1;
      files[file_index].blocks[blocks_allocated] = i;
      blocks_allocated++;

      if (blocks_allocated == blocks_needed) {
        break;
      }
    }
  }

  if (blocks_allocated != blocks_needed) {
    return -1;
  }

  int block_index = 0;
  int offset = 0;

  while (size > 0) {
    int bytes_to_copy = size < 512 ? size : 512;

    memcpy(blocks[files[file_index].blocks[block_index]].data + offset, data, bytes_to_copy);

    offset += bytes_to_copy;
    size -= bytes_to_copy;
    data += bytes_to_copy;
    block_index++;
  }

  files[file_index].size = size;

  return 0;
}

// Read data from a file
int read_file(char *name, char *data, int size) {
  int file_index = -1;

  for (int i = 0; i < MAX_FILES; i++) {
    if (strcmp(files[i].name, name) == 0) {
      file_index = i;
      break;
    }
  }

  if (file_index == -1) {
    return -1;
  }

  int blocks_needed = (size + 511) / 512;
  int blocks_allocated = files[file_index].size / 512;

  if (blocks_allocated < blocks_needed) {
    return -1;
  }

  int block_index = 0;
  int offset = 0;

  while (size > 0) {
    int bytes_to_copy = size < 512 ? size : 512;

    memcpy(data, blocks[files[file_index].blocks[block_index]].data + offset, bytes_to_copy);

    offset += bytes_to_copy;
    size -= bytes_to_copy;
    data += bytes_to_copy;
    block_index++;
  }

  return 0;
}

// List all files in the file system
void list_files() {
  for (int i = 0; i < MAX_FILES; i++) {
    if (strcmp(files[i].name, "") != 0) {
      printf("%s\n", files[i].name);
    }
  }
}

// Main function
int main() {
  // Initialize the file system
  init_fs();

  // Create some files
  create_file("file1");
  create_file("file2");
  create_file("file3");

  // Write some data to the files
  write_file("file1", "Hello world!", strlen("Hello world!"));
  write_file("file2", "This is a test", strlen("This is a test"));
  write_file("file3", "This is another test", strlen("This is another test"));

  // Read some data from the files
  char data[512];
  read_file("file1", data, 512);
  printf("%s\n", data);

  read_file("file2", data, 512);
  printf("%s\n", data);

  read_file("file3", data, 512);
  printf("%s\n", data);

  // List all files in the file system
  list_files();

  return 0;
}

