#define BOARD_SIZE 3

typedef struct Node {
  int x, y;
  struct Node* next;
} Node;

Node* createNode(int x, int y) {
  Node* node = (Node*)malloc(sizeof(Node));
  node->x = x;
  node->y = y;
  node->next = NULL;
  return node;
}

int isBoardFull(Node* head) {
  while (head) {
    if (head->x == BOARD_SIZE - 1) {
      return 1;
    }
    head = head->next;
  }
  return 0;
}

