  head = createNode(ai_x, ai_y);

  // Check if the board is full
  if (isBoardFull(head)) {
    printf("Board is full!\n");
  } else {
    printf("Move: (%d, %d) - AI's move: (%d, %d)\n", move_x, move_y, ai_x, ai_y);
