}

int partition(node** start, int pivot, int length)
{
  if((*start) == NULL)
    {
      return BAD;
    }
  else
    {
      int npivot = getelement(start,pivot);
      int ppivot = pivot;
      int i =0;
      while ( i < length)
	{
	  int temp = getelement(start,i);
	  if((temp > npivot) && (i < pivot))
	    {
	      remove(start,i);
	      pivot = pivot - 1;
	      insert(start,temp,pivot+1);
	    }
	  else if((temp <= npivot) && (i > pivot))
	    {
	      remove(start,i);
	      if(pivot == 0)
		{
		  insert(start,temp,0);
		}
	      else
		{
		  insert(start,temp,pivot-1);
		}
	      pivot = pivot + 1;
	    }
	  else
	    {
	      i++;
	    }
	}
      return pivot;
    }
}

