      return;
    }
  else
    {
      int lent = length;
      if (lent == 1 || lent == 0)
	{
	  return;
	}
      else
	{
	  int pivot = rand()%lent;
	  pivot = partition(start,pivot,length);
	  int lent1 = length - pivot -1;
	  node* temp = getptr(start,pivot);
	  node* temp1 = getptr1(start,pivot);
	  sortll(start,pivot);
	  sortll(&temp,lent1);
	  temp1->next = temp;
	}
    }
}

