#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define N 100000
#define L 100

typedef struct {
    char seq[L];
    int index;
} Sequence;

void random_sequence(Sequence *seq) {
    int i;
    for (i = 0; i < L; i++) {
        seq->seq[i] = rand() % 4 + 'A';
    }
    seq->index = rand() % (N + 1);
}

void read_file(FILE *fp, Sequence *seqs, int *count) {
    char line[L + 1];
    int i;
    Sequence seq;
    *count = 0;
    while (fgets(line, sizeof(line), fp)) {
        sscanf(line, "%s%n", seq.seq, &i);
        seq.seq[i - 1] = '\0';
        random_index(&seq.index);
        seqs[*count] = seq;
        (*count)++;
    }
}

void random_index(int *index) {
    *index = rand() % (N + 1);
}

void print_sequences(Sequence *seqs, int count) {
    int i;
    for (i = 0; i < count; i++) {
        printf("Sequence %d: %s\n", seqs[i].index, seqs[i].seq);
    }
}

int main() {
    Sequence seqs[N];
    int count = 0;
    FILE *fp = fopen("sequences.txt", "r");
    if (!fp) {
        printf("Error: Could not open file.\n");
        return 1;
    }

    srand(time(NULL));
    read_file(fp, seqs, &count);
    for (int i = 0; i < count; i++) {
        random_sequence(&seqs[i]);
    }
    print_sequences(seqs, count);

    fclose(fp);
    return 0;
}

