#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MIN_WORD_LENGTH 5
#define MAX_WORD_LENGTH 30
#define NUM_WORDS 10
#define LINE_LENGTH (MAX_WORD_LENGTH * 2 + 1)

typedef struct Word {
    char *word;
    int length;
} Word;

Word *generateWords(int numWords) {
    Word *words = (Word *) malloc(numWords * sizeof(Word));
    for (int i = 0; i < numWords; ++i) {
        size_t len = rand() % (MAX_WORD_LENGTH - MIN_WORD_LENGTH + 1) + MIN_WORD_LENGTH;
        char *word = (char *) malloc(len * sizeof(char));
        for (size_t j = 0; j < len; ++j) {
            word[j] = (char) ('a' + rand() % 26);
        }
        words[i].length = len;
        words[i].word = word;
    }
    return words;
}

void printWord(const Word *word) {
    printf("%.*s", word->length, word->word);
}

void freeWords(Word *words, int numWords) {
    for (int i = 0; i < numWords; ++i) {
        free(words[i].word);
    }
    free(words);
}

void testTypingSpeed(const Word *words, int numWords) {
    char input[LINE_LENGTH];
    clock_t start = clock();
    int numCorrect = 0;
    for (int i = 0; i < numWords; ++i) {
        printf("%s: ", words[i].word);
        scanf("%s", input);
        if (strcmp(words[i].word, input) == 0) {
            ++numCorrect;
        }
    }
    clock_t end = clock();
    double timeTaken = (double) (end - start) / CLOCKS_PER_SEC;
    printf("\nYou typed %d words correctly in %.2fs.\n", numCorrect, timeTaken);
}

int main() {
    srand(time(NULL));
    Word *words = generateWords(NUM_WORDS);
    testTypingSpeed(words, NUM_WORDS);
    freeWords(words, NUM_WORDS);
    return 0;
}

#include "MoveAction.h"

MoveAction::MoveAction(ComponentContext &_context, const EntityComponent::EntityId & _entityId, Position::Direction _direction)
:context(_context),
entityId(_entityId),
direction(_direction){	
}

bool MoveAction::process(){
	SystemComponent<MovableComponent>::Components::iterator it = context.movables.components.find(entityId);

	if(it == context.movables.components.end()){
		return true;
	}

	MovableComponent *render = it->second;

	render->setOrientation(direction);
	render->getPosition().move(direction, render->getSpeed() / context.getSpeed());

	//Need to know if it and / or it_render are removed in a collision and update iterator

	for(SystemComponent<RenderComponent>::Components::iterator it_render = context.collisionables.components.begin();
		it_render != context.collisionables.components.end();
		++it_render){	

		//Hack 1st part
		SystemComponent<RenderComponent>::Components::iterator it_render_next = ++it_render;
		--it_render;

		if(it->second != it_render->second &&
			render->overlap(*context.render_components.components[it_render->first]) &&
			!context.collider.processCollision(*context.components.components[it->first], *context.components.components[it_render->first])){

			if(!context.componentExist(entityId)){
				return true;
			}

			render->getPosition() = render->getLastPosition();

			return true;
		}

		if(!context.componentExist(entityId)){
			return true;
		}

		//Hack 2nd part
		if(!context.componentExist(it_render->first)){
			it_render = it_render_next;
			if(it_render != context.collisionables.components.begin()){
				--it_render;
			}
		}
	}	

	render->getLastPosition() = render->getPosition();

	return true;
}

