#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define NUM_THREADS 10

struct thread_data {
    int thread_id;
    char *query;
};

void *run_query(void *arg) {
    struct thread_data *data = arg;
    int thread_id = data->thread_id;
    char *query = data->query;

    // Execute database query
    printf("Thread %d executing query: %s\n", thread_id, query);

    // Simulate some processing time
    sleep(1);

    // Print query results
    printf("Thread %d finished executing query\n", thread_id);

    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];
    struct thread_data data[NUM_THREADS];

    // Initialize thread data
    for (int i = 0; i < NUM_THREADS; i++) {
        data[i].thread_id = i + 1;
        asprintf(&data[i].query, "SELECT * FROM my_table WHERE id = %d", i + 1);
    }

    // Create threads
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_create(&threads[i], NULL, run_query, &data[i]);
    }

    // Join threads
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

