#include <stdio.h>
#include <string.h>
#include <time.h>
#include <crypt.h>

#define KEY_SIZE 16
#define MESSAGE_SIZE 256

// Define the key and message
char key[KEY_SIZE] = "0123456789abcdef";
char message[MESSAGE_SIZE] = "The quick brown fox jumps over the lazy dog";

// Function to encrypt the message
void encrypt(char *message) {
  int i, j, k;
  char temp;
  char encrypted_message[MESSAGE_SIZE];

  // Initialize the encryption key
  for (i = 0; i < KEY_SIZE; i++) {
    key[i] = (i % 2 == 0) ? key[i] : (key[i] + 1);
  }

  // Encrypt the message
  for (i = 0; i < MESSAGE_SIZE; i++) {
    temp = message[i];
    for (j = 0; j < KEY_SIZE; j++) {
      if (temp == key[j]) {
        encrypted_message[i] = (char)((temp - 'a') + 'z' - 'a');
        break;
      }
    }
  }

  // Swap the first and last characters of the encrypted message
  temp = encrypted_message[0];
  encrypted_message[0] = encrypted_message[MESSAGE_SIZE - 1];
  encrypted_message[MESSAGE_SIZE - 1] = temp;

  // Print the encrypted message
  printf("Encrypted message: %s\n", encrypted_message);
}

int main() {
  srand(time(NULL));

  // Encrypt the message
  encrypt(message);

  return 0;
}

