typedef struct {
    unsigned char *buf;
    size_t size, cap;
} bitbuf_t;

static void bitbuf_init(bitbuf_t *buf) {
    buf->size = 0;
    buf->cap = 1024;
    buf->buf = malloc(buf->cap);
}

static void bitbuf_free(bitbuf_t *buf) {
    free(buf->buf);
}

static void bitbuf_write_bit(bitbuf_t *buf, int bit) {
    if (buf->size >= buf->cap) {
        buf->cap *= 2;
        buf->buf = realloc(buf->buf, buf->cap);
    }
    if (bit)
        buf->buf[buf->size / 8] |= 1 << (7 - buf->size % 8);
    buf->size++;
}

static unsigned char *bitbuf_finish(bitbuf_t *buf) {
    unsigned char *ret = malloc(buf->size / 8 + !!(buf->size % 8));
    memcpy(ret, buf->buf, buf->size / 8 + !!(buf->size % 8));
    bitbuf_free(buf);
    return ret;
}

static void bitbuf_write_byte(bitbuf_t *buf, unsigned char byte) {
    for (int i = 0; i < 8; i++)
        bitbuf_write_bit(buf, byte & (1 << (7 - i)));
}

static void bitbuf_write_uint16(bitbuf_t *buf, unsigned short num) {
    for (int i = 0; i < 16; i++)
        bitbuf_write_bit(buf, num & (1 << (15 - i)));
}

static void bitbuf_write_uint32(bitbuf_t *buf, unsigned int num) {
    for (int i = 0; i < 32; i++)
        bitbuf_write_bit(buf, num & (1 << (31 - i)));
}

static void compress(unsigned char *in, size_t in_size, unsigned char **out, size_t *out_size) {
    bitbuf_t buf;
    bitbuf_init(&buf);
    bitbuf_write_uint32(&buf, (unsigned int)in_size);
    int prev = -1;
    for (size_t i = 0; i < in_size; i++) {
        if (in[i] == prev) {
            bitbuf_write_bit(&buf, 0);
        } else {
            bitbuf_write_bit(&buf, 1);
            bitbuf_write_byte(&buf, in[i]);
        }
        prev = in[i];
    }
    *out = bitbuf_finish(&buf);
    *out_size = buf.size / 8 + !!(buf.size % 8);
}

static void decompress(unsigned char *in, size_t in_size, unsigned char **out, size_t *out_size) {
    size_t i = 0, j = 0;
    unsigned int size = 0;
    for (; i < in_size * 8; i += 32) {
        size |= (in[i / 8] >> (i % 8)) & 1 << (31 - (i % 32));
    }
    *out = malloc(size);
    *out_size = size;
    int prev = -1;
    for (i = 32; i < in_size * 8; i++) {
        if ((in[i / 8] >> (i % 8)) & 1) {
            prev = in[j++];
        }
        (*out)[j++] = prev;
    }
}

int main() {
    unsigned char *in = "Lorem ipsum dolor sit amet, consectetur adipiscing elit. Donec vitae orci ornare, vehicula felis sed, sollicitudin nisl. Phasellus mollis tincidunt dapibus.", *out;
    size_t in_size = strlen(in), out_size;
    compress(in, in_size, &out, &out_size);
    decompress(out, out_size, &in, &in_size);
    printf("Original: %s\nCompressed: %s\nDecompressed: %s\n", in, out, in);
    free(out);
    free(in);
    return 0;
}

