#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_PIXELS 1000

// Struct to represent a pixel
typedef struct {
    int x, y;
    char color;
} Pixel;

// Struct to represent a pixel art
typedef struct {
    Pixel pixels[MAX_PIXELS];
    int num_pixels;
} PixelArt;

// Function to generate a random color
char random_color() {
    return (char)(rand() % 256);
}

// Function to generate a random pixel
Pixel random_pixel() {
    Pixel pixel;
    pixel.x = rand() % 100;
    pixel.y = rand() % 100;
    pixel.color = random_color();
    return pixel;
}

// Function to generate a random pixel art
PixelArt random_pixel_art() {
    PixelArt pixel_art;
    for (int i = 0; i < MAX_PIXELS; i++) {
        pixel_art.pixels[i] = random_pixel();
    }
    pixel_art.num_pixels = MAX_PIXELS;
    return pixel_art;
}

// Function to print a pixel art
void print_pixel_art(PixelArt pixel_art) {
    for (int i = 0; i < pixel_art.num_pixels; i++) {
        printf("%c ", pixel_art.pixels[i].color);
    }
    printf("\n");
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Generate a random pixel art
    PixelArt pixel_art = random_pixel_art();

    // Print the pixel art
    print_pixel_art(pixel_art);

    return 0;
}

