#define SEQUENCE_LENGTH 50
#define NUM_OF_SEQUENCES 10
#define ALPHABET "ACGT"

// Function prototypes
void generate_random_sequence(char *sequence, int length);
void mutate_sequence(char *sequence, int position);
void print_sequences(char sequences[NUM_OF_SEQUENCES][SEQUENCE_LENGTH]);
void compare_sequences(char sequences[NUM_OF_SEQUENCES][SEQUENCE_LENGTH]);

int main() {
    srand(time(NULL));

    char sequences[NUM_OF_SEQUENCES][SEQUENCE_LENGTH];

    // Generate random sequences
    for (int i = 0; i < NUM_OF_SEQUENCES; i++) {
        generate_random_sequence(sequences[i], SEQUENCE_LENGTH);
    }

    // Print generated sequences
    printf("Generated Genome Sequences:\n");
    print_sequences(sequences);

    // Mutate a random position in each sequence
    for (int i = 0; i < NUM_OF_SEQUENCES; i++) {
        int position = rand() % SEQUENCE_LENGTH;
        mutate_sequence(sequences[i], position);
    }

    // Print mutated sequences
    printf("\nMutated Genome Sequences:\n");
    print_sequences(sequences);

    // Compare sequences
    printf("\nComparing Sequences:\n");
    compare_sequences(sequences);

    return 0;
}

// Function to generate a random DNA sequence
void generate_random_sequence(char *sequence, int length) {
    for (int i = 0; i < length; i++) {
        sequence[i] = ALPHABET[rand() % 4];
    }
    sequence[length] = '\0'; // Null-terminate the string
}

// Function to mutate a sequence at a specified position
void mutate_sequence(char *sequence, int position) {
    char original = sequence[position];
    char new_char;

    do {
        new_char = ALPHABET[rand() % 4];
    } while (new_char == original); // Ensure new char is different from original

    sequence[position] = new_char;
}

// Function to print all sequences
void print_sequences(char sequences[NUM_OF_SEQUENCES][SEQUENCE_LENGTH]) {
    for (int i = 0; i < NUM_OF_SEQUENCES; i++) {
        printf("Sequence %02d: %s\n", i + 1, sequences[i]);
    }
}

// Function to compare sequences and print similarities
void compare_sequences(char sequences[NUM_OF_SEQUENCES][SEQUENCE_LENGTH]) {
    for (int i = 0; i < NUM_OF_SEQUENCES; i++) {
        for (int j = i + 1; j < NUM_OF_SEQUENCES; j++) {
            int similarities = 0;
            for (int k = 0; k < SEQUENCE_LENGTH; k++) {
                if (sequences[i][k] == sequences[j][k]) {
                    similarities++;
                }
            }
            printf("Comparison between Sequence %02d and Sequence %02d: %d identical nucleotides.\n", i + 1, j + 1, similarities);
        }
    }
}

//GEMINI-pro DATASET v1.0 Category: Queue Implementation ; Style: future-proof
#include <stdbool.h>
#include <stdlib.h>
#include <assert.h>

struct node {
    void *data;
    struct node *next;
};

struct queue {
    struct node *head;
    struct node *tail;
    size_t count;
};

struct queue *queue_create() {
    struct queue *queue = malloc(sizeof(struct queue));
    assert(queue != NULL);
    queue->head = NULL;
    queue->tail = NULL;
    queue->count = 0;
    return queue;
}

bool queue_is_empty(struct queue *queue) {
    return queue->count == 0;
}

void queue_enqueue(struct queue *queue, void *data) {
    struct node *new_node = malloc(sizeof(struct node));
    assert(new_node != NULL);
    new_node->data = data;
    new_node->next = NULL;
    if (queue->count == 0) {
        queue->head = new_node;
        queue->tail = new_node;
    } else {
        queue->tail->next = new_node;
        queue->tail = new_node;
    }
    queue->count++;
}

void *queue_dequeue(struct queue *queue) {
    assert(!queue_is_empty(queue));
    void *data = queue->head->data;
    struct node *old_head = queue->head;
    queue->head = queue->head->next;
    if (queue->head == NULL) {
        queue->tail = NULL;
    }
    free(old_head);
    queue->count--;
    return data;
}

void queue_destroy(struct queue *queue) {
    while (!queue_is_empty(queue)) {
        free(queue->head);
        queue->head = queue->head->next;
    }
    free(queue);
}

int main() {
    struct queue *queue = queue_create();

    // Enqueue some data
    for (int i = 0; i < 10; i++) {
        queue_enqueue(queue, (void *)i);
    }

    // Dequeue some data
    for (int i = 0; i < 5; i++) {
        int *data = queue_dequeue(queue);
        printf("%d\n", *data);
    }

    // Destroy the queue
    queue_destroy(queue);

    return 0;
}

