    }

    for(i=0; i<n; i++) {
        free(A[i]);
    }
    free(A);

    for(i=0; i<n; i++) {
        free(B[i]);
    }
    free(B);

    for(i=0; i<n; i++) {
        free(C[i]);
    }
    free(C);

    return 0;
}

