    return 0;
}

//GPT-4o-mini DATASET v1.0 Category: Rogue-like Game with Procedural Generation ; Style: post-apocalyptic
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

#define MAX_MAP_SIZE 20
#define NUM_ENEMIES 5
#define NUM_ITEMS 3

typedef struct {
    int x, y;
    char symbol;
} Entity;

typedef struct {
    char map[MAX_MAP_SIZE][MAX_MAP_SIZE];
    Entity player;
    Entity enemies[NUM_ENEMIES];
    Entity items[NUM_ITEMS];
} Game;

void initialize_map(Game* game);
void spawn_entities(Game* game);
void display_map(Game* game);
void move_player(Game* game, char input);
int check_collision(Game* game, int new_x, int new_y);

int main() {
    Game game;
    char input;

    srand(time(NULL));

    initialize_map(&game);
    spawn_entities(&game);

    while (1) {
        system("clear");
        display_map(&game);
        printf("Move (W/A/S/D): ");
        input = getchar();
        getchar();  // Clear the newline character
        move_player(&game, input);
    }

    return 0;
}

void initialize_map(Game* game) {
    for (int i = 0; i < MAX_MAP_SIZE; i++) {
        for (int j = 0; j < MAX_MAP_SIZE; j++) {
            game->map[i][j] = '.';
        }
    }
    game->player.x = MAX_MAP_SIZE / 2;
    game->player.y = MAX_MAP_SIZE / 2;
    game->player.symbol = '@';
    game->map[game->player.x][game->player.y] = game->player.symbol;
}

void spawn_entities(Game* game) {
    for (int i = 0; i < NUM_ENEMIES; i++) {
        int x = rand() % MAX_MAP_SIZE;
        int y = rand() % MAX_MAP_SIZE;
        while (game->map[x][y] != '.') {
            x = rand() % MAX_MAP_SIZE;
            y = rand() % MAX_MAP_SIZE;
        }
        game->enemies[i].x = x;
        game->enemies[i].y = y;
        game->enemies[i].symbol = 'E';
        game->map[x][y] = game->enemies[i].symbol;
    }

    for (int i = 0; i < NUM_ITEMS; i++) {
        int x = rand() % MAX_MAP_SIZE;
        int y = rand() % MAX_MAP_SIZE;
        while (game->map[x][y] != '.') {
            x = rand() % MAX_MAP_SIZE;
            y = rand() % MAX_MAP_SIZE;
        }
        game->items[i].x = x;
        game->items[i].y = y;
        game->items[i].symbol = '!';
        game->map[x][y] = game->items[i].symbol;
    }
}

void display_map(Game* game) {
    for (int i = 0; i < MAX_MAP_SIZE; i++) {
        for (int j = 0; j < MAX_MAP_SIZE; j++) {
            putchar(game->map[i][j]);
        }
        putchar('\n');
    }
    printf("Player position: (%d, %d)\n", game->player.x, game->player.y);
}

void move_player(Game* game, char input) {
    int new_x = game->player.x;
    int new_y = game->player.y;

    switch (input) {
        case 'W': case 'w':
            new_x--;
            break;
        case 'A': case 'a':
            new_y--;
            break;
        case 'S': case 's':
            new_x++;
            break;
        case 'D': case 'd':
            new_y++;
            break;
        default:
            printf("Invalid move!\n");
            return;
    }

    if (!check_collision(game, new_x, new_y)) {
        game->map[game->player.x][game->player.y] = '.';
        game->player.x = new_x;
        game->player.y = new_y;
        game->map[game->player.x][game->player.y] = game->player.symbol;
    } else {
        printf("You can't move there!\n");
    }
}

int check_collision(Game* game, int new_x, int new_y) {
    // Check bounds
    if (new_x < 0 || new_x >= MAX_MAP_SIZE || new_y < 0 || new_y >= MAX_MAP_SIZE) {
        return 1;
    }
    // Check for enemy collision
    for (int i = 0; i < NUM_ENEMIES; i++) {
        if (game->enemies[i].x == new_x && game->enemies[i].y == new_y) {
            return 1;  // Collision with enemy
        }
    }
    // Check for item collision
    for (int i = 0; i < NUM_ITEMS; i++) {
        if (game->items[i].x == new_x && game->items[i].y == new_y) {
            printf("You found an item!\n");
            return 1;  // Collision with item
        }
    }
    return 0; // No collisions
}

