#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024
#define MAX_NUM_FIELDS 10

typedef struct {
    char *fields[MAX_NUM_FIELDS];
    int num_fields;
} CSVRow;

CSVRow *csv_read_row(FILE *fp) {
    char line[MAX_LINE_LENGTH];
    char *field;
    CSVRow *row = malloc(sizeof(CSVRow));

    if (!row) {
        return NULL;
    }

    row->num_fields = 0;

    if (fgets(line, MAX_LINE_LENGTH, fp) == NULL) {
        free(row);
        return NULL;
    }

    field = strtok(line, ",");
    while (field) {
        row->fields[row->num_fields++] = strdup(field);
        field = strtok(NULL, ",");
    }

    return row;
}

void csv_free_row(CSVRow *row) {
    for (int i = 0; i < row->num_fields; i++) {
        free(row->fields[i]);
    }

    free(row);
}

int main(int argc, char *argv[]) {
    FILE *fp;
    CSVRow *row;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    fp = fopen(argv[1], "r");
    if (!fp) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    while ((row = csv_read_row(fp))) {
        for (int i = 0; i < row->num_fields; i++) {
            printf("%s,", row->fields[i]);
        }

        printf("\n");

        csv_free_row(row);
    }

    fclose(fp);

    return EXIT_SUCCESS;
}

