#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/sysinfo.h>
#include <pthread.h>
#include <time.h>

#define MAX_CPUS 256
#define BUFFER_SIZE 256

typedef struct {
    int cpu_id;
    float usage;
} CPUInfo;

CPUInfo cpu_info[MAX_CPUS];
int cpu_count;

void* monitor_cpu_usage(void* arg) {
    while (1) {
        FILE *fp = fopen("/proc/stat", "r");
        char buffer[BUFFER_SIZE];
        if (!fp) {
            fprintf(stderr, "Error opening /proc/stat\n");
            pthread_exit(NULL);
        }

        // Read CPU info
        int index = 0;
        while (fgets(buffer, sizeof(buffer), fp)) {
            if (strncmp(buffer, "cpu", 3) == 0 && isdigit(buffer[3])) {
                int user, nice, system, idle, iowait, irq, softirq, steal;
                sscanf(buffer, "cpu%d %d %d %d %d %d %d %d %d", &index, &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal);
                int total = user + nice + system + idle + iowait + irq + softirq + steal;
                float usage = 100.0 * (total - idle) / total;
                cpu_info[index].cpu_id = index;
                cpu_info[index].usage = usage;
                index++;
            }
            if (index >= MAX_CPUS) break; // Limit to maximum CPUs
        }
        fclose(fp);

        // Sleep for a second
        sleep(1);
    }
    return NULL;
}

void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("\nCPU Usage Monitor stopped. Exiting...\n");
        exit(0);
    }
}

void print_cpu_usage() {
    printf("\033[0;33m");
    printf("+---------------------+\n");
    printf("|   CPU ID   | Usage  |\n");
    printf("+---------------------+\n");
    for (int i = 0; i < cpu_count; i++) {
        printf("| CPU %3d   | %.2f%%  |\n", cpu_info[i].cpu_id, cpu_info[i].usage);
    }
    printf("+---------------------+\033[0m\n");
}

int main() {
    // Handle Ctrl+C
    signal(SIGINT, signal_handler);

    // Get the number of CPUs
    cpu_count = sysconf(_SC_NPROCESSORS_ONLN);

    // Initialize CPU info
    for (int i = 0; i < cpu_count; i++) {
        cpu_info[i].cpu_id = i;
        cpu_info[i].usage = 0.0;
    }

    // Create a thread for monitoring CPU usage
    pthread_t monitor_thread;
    if (pthread_create(&monitor_thread, NULL, monitor_cpu_usage, NULL) != 0) {
        fprintf(stderr, "Error creating monitor thread\n");
        return EXIT_FAILURE;
    }

    // Infinite loop to print CPU usage
    while (1) {
        print_cpu_usage();
        sleep(2); // Update every 2 seconds
    }

    // Clean up
    pthread_join(monitor_thread, NULL);
    return 0;
}

