#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

// Function to calculate the complexity of a sentence
int sentence_complexity(char* sentence) {
    int len = strlen(sentence);
    int complexity = 0;

    for (int i = 0; i < len; i++) {
        if (sentence[i] == ' ' || sentence[i] == '.') {
            complexity++;
        } else if (sentence[i] == ',' || sentence[i] == '!' || sentence[i] == '?') {
            complexity += 2;
        } else if (sentence[i] == '(' || sentence[i] == ')') {
            complexity += 3;
        }
    }

    return complexity;
}

// Function to calculate the readability of a sentence
int sentence_readability(char* sentence) {
    int complexity = sentence_complexity(sentence);
    int readability = 0;

    if (complexity < 5) {
        readability = 100;
    } else if (complexity < 10) {
        readability = 75;
    } else if (complexity < 15) {
        readability = 50;
    } else {
        readability = 25;
    }

    return readability;
}

int main() {
    char sentence[100];
    printf("Enter a sentence: ");
    fgets(sentence, 100, stdin);

    int complexity = sentence_complexity(sentence);
    int readability = sentence_readability(sentence);

    printf("The complexity of the sentence is %d\n", complexity);
    printf("The readability of the sentence is %d\n", readability);

    return 0;
}

