    int i;
    for (i = 0; i < sizeof(inventory) / sizeof(inventory[0]); i++) {
        if (strcmp(inventory[i].name, name) == 0) {
            inventory[i].quantity += quantity;
            inventory[i].cost += (quantity * cost);
            break;
