    // Open the device file
    int fd = open("/dev/sda1", O_RDONLY);
    if (fd == -1) {
        printf("Error: Opening device file failed\n");
        return 2;
    }

    // Get the device size
    struct stat stat_buf;
    fstat(fd, &stat_buf);
    uint64_t device_size = stat_buf.st_size;

    // Calculate the number of sectors
    uint32_t sector_count = device_size / 512;

    // Allocate memory for the sector buffer
    struct sector_info *sector_buffer = calloc(sector_count, sizeof(struct sector_info));
    if (!sector_buffer) {
        printf("Error: Memory allocation failed\n");
        return 3;
    }

    // Read the device sector by sector
    for (uint32_t i = 0; i < sector_count; i++) {
        // Calculate the current sector number and size
