void Solve(const vector<int> &buckets, vector<int> &ret, int n, int bucket) {
  if (buckets.size() != ret.size())
    return;
  if (n < 0)
    return;
  else if (n == 0) {
    copy(ret.begin(), ret.end(), ostream_iterator<int>(cout, ""));
    cout << endl;
  } else {
    for (int i = bucket; i < buckets.size(); i++) {
      if (ret[i] < buckets[i]) {
        ret[i]++;
        Solve(buckets, ret, n - 1, i);
        ret[i]--;
      }
    }
  }
}


