#include <stdio.h>

void convertToHex(int num) {
    char hex[20];
    int index = 0;

    while(num != 0) {
        int temp = num % 16;

        if (temp < 10) {
            hex[index] = temp + '0';
        } else {
            hex[index] = temp - 10 + 'A';
        }

        num /= 16;
        index++;
    }

    printf("The hexadecimal representation is: ");
    for (index--; index >= 0; index--) {
        putchar(hex[index]);
    }
    printf("\n");
}

