#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>

#define HASH_SIZE 32

typedef struct {
    char *message;
    unsigned char hash[HASH_SIZE];
} hash_t;

void hash_init(hash_t *hash) {
    hash->message = NULL;
    memset(hash->hash, 0, HASH_SIZE);
}

void hash_update(hash_t *hash, const char *data, size_t len) {
    if (hash->message == NULL) {
        hash->message = malloc(len + 1);
        memcpy(hash->message, data, len);
        hash->message[len] = '\0';
    } else {
        hash->message = realloc(hash->message, strlen(hash->message) + len + 1);
        strcat(hash->message, data);
    }
}

void hash_final(hash_t *hash, unsigned char *digest) {
    size_t len = strlen(hash->message);
    unsigned char *message = malloc(len + 1);
    memcpy(message, hash->message, len);
    message[len] = '\0';

    char *hex_message = malloc(2 * len + 1);
    for (int i = 0; i < len; i++) {
        sprintf(&hex_message[i * 2], "%02x", message[i]);
    }
    hex_message[len * 2] = '\0';

    hash_t temp_hash;
    hash_init(&temp_hash);
    hash_update(&temp_hash, hex_message, strlen(hex_message));
    hash_final(&temp_hash, digest);

    free(message);
    free(hex_message);
}

void hash_print(const hash_t *hash) {
    for (int i = 0; i < HASH_SIZE; i++) {
        printf("%02x", hash->hash[i]);
    }
    printf("\n");
}

int main() {
    hash_t hash;
    hash_init(&hash);

    hash_update(&hash, "The quick brown fox jumps over the lazy dog.", strlen("The quick brown fox jumps over the lazy dog."));
    hash_print(&hash);

    unsigned char digest[HASH_SIZE];
    hash_final(&hash, digest);

    printf("Digest: ");
    for (int i = 0; i < HASH_SIZE; i++) {
        printf("%02x", digest[i]);
    }
    printf("\n");

    return 0;
}

