    if (strlen(word) > 3 &&!strncasecmp(word, "happy", 4)) {
        return true;
    }
    return false;
}

bool is_negative_word(char *word) {
    // Check if the word is a negative word (e.g., sad, terrible)
    if (strlen(word) > 3 &&!strncasecmp(word, "sad", 3)) {
        return true;
    }
    return false;
}

