#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define G 6.67408e-11 // Gravitational constant (m^3 kg^-1 s^-2)
#define NUM_BODIES 100 // Number of bodies in the simulation
#define DELTA_T 0.001 // Time step (s)

// Structure to represent a body in the simulation
typedef struct {
    double mass; // Mass of the body (kg)
    double x; // X-coordinate of the body (m)
    double y; // Y-coordinate of the body (m)
    double z; // Z-coordinate of the body (m)
    double vx; // X-component of the body's velocity (m/s)
    double vy; // Y-component of the body's velocity (m/s)
    double vz; // Z-component of the body's velocity (m/s)
} Body;

// Function to calculate the gravitational force between two bodies
void calculate_force(Body *body1, Body *body2, double *fx, double *fy, double *fz) {
    double dx = body2->x - body1->x;
    double dy = body2->y - body1->y;
    double dz = body2->z - body1->z;
    double r = sqrt(dx * dx + dy * dy + dz * dz);
    double f = G * body1->mass * body2->mass / (r * r);
    *fx = f * dx / r;
    *fy = f * dy / r;
    *fz = f * dz / r;
}

// Function to update the velocity and position of a body based on the gravitational force
void update_body(Body *body, double fx, double fy, double fz) {
    body->vx += fx * DELTA_T / body->mass;
    body->vy += fy * DELTA_T / body->mass;
    body->vz += fz * DELTA_T / body->mass;
    body->x += body->vx * DELTA_T;
    body->y += body->vy * DELTA_T;
    body->z += body->vz * DELTA_T;
}

int main() {
    // Initialize the bodies in the simulation
    Body bodies[NUM_BODIES];
    for (int i = 0; i < NUM_BODIES; i++) {
        bodies[i].mass = 1000.0; // Mass of each body (kg)
        bodies[i].x = rand() % 100000; // Random X-coordinate (m)
        bodies[i].y = rand() % 100000; // Random Y-coordinate (m)
        bodies[i].z = rand() % 100000; // Random Z-coordinate (m)
        bodies[i].vx = 0.0; // Initial X-component of velocity (m/s)
        bodies[i].vy = 0.0; // Initial Y-component of velocity (m/s)
        bodies[i].vz = 0.0; // Initial Z-component of velocity (m/s)
    }

    // Run the simulation for a number of time steps
    for (int i = 0; i < 10000; i++) {
        // Calculate the gravitational force between each pair of bodies
        for (int j = 0; j < NUM_BODIES; j++) {
            for (int k = j + 1; k < NUM_BODIES; k++) {
                double fx, fy, fz;
                calculate_force(&bodies[j], &bodies[k], &fx, &fy, &fz);
                update_body(&bodies[j], fx, fy, fz);
                update_body(&bodies[k], -fx, -fy, -fz);
            }
        }
    }

    // Print the final positions of the bodies
    for (int i = 0; i < NUM_BODIES; i++) {
        printf("Body %d: (%f, %f, %f)\n", i, bodies[i].x, bodies[i].y, bodies[i].z);
    }

    return 0;
}

