/* f(x) = x^{20} - 1 */
/* f'(x) = 20x^{19} */
/* zero at x = 1 or -1 */

double func1(double x) {
    return pow(x, 20.0) - 1;
}

/* f(x) = sqrt(abs(x))*sgn(x) */
/* f'(x) = 1 / sqrt(abs(x) */
/* zero at x = 0 */
double func2(double x) {
    double delta;

    if (x > 0)
        delta = 1.0;
    else if (x < 0)
        delta = -1.0;
    else
        delta = 0.0;

    return sqrt(fabs(x)) * delta;
}

/* f(x) = x^2 - 1e-8 */
/* f'(x) = 2x */
/* zero at x = sqrt(1e-8) or -sqrt(1e-8) */
double func3(double x) {
    return pow(x, 2.0) - 1e-8;
}

/* f(x) = x exp(-x) */
/* f'(x) = exp(-x) - x exp(-x) */
/* zero at x = 0 */
double func4(double x) {
    return x * exp(-x);
}


/* f(x) = 1/(1+exp(x)) */
/* f'(x) = -exp(x) / (1 + exp(x))^2 */
/* no roots! */
double func5(double x, void *p) {
