#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define QR_VERSION 1
#define QR_SIZE 21

#define QR_MODE_NUMERIC 1
#define QR_MODE_ALPHA_NUMERIC 2
#define QR_MODE_BYTE 4
#define QR_MODE_KANJI 8

#define QR_ERROR_CORRECTION_LEVEL_L 1
#define QR_ERROR_CORRECTION_LEVEL_M 0
#define QR_ERROR_CORRECTION_LEVEL_Q 3
#define QR_ERROR_CORRECTION_LEVEL_H 2

typedef struct {
  int version;
  int size;
  int mode;
  int error_correction_level;
  char *data;
  int data_length;
} qr_code_t;

static int qr_code_generate_matrix(qr_code_t *qr_code, int *matrix) {
  int i, j;

  for (i = 0; i < qr_code->size; i++) {
    for (j = 0; j < qr_code->size; j++) {
      matrix[i * qr_code->size + j] = (i + j) % 2;
    }
  }

  return 0;
}

static int qr_code_print_matrix(qr_code_t *qr_code, int *matrix) {
  int i, j;

  for (i = 0; i < qr_code->size; i++) {
    for (j = 0; j < qr_code->size; j++) {
      printf("%d", matrix[i * qr_code->size + j]);
    }
    printf("\n");
  }

  return 0;
}

int main(int argc, char **argv) {
  qr_code_t qr_code;
  int matrix[QR_SIZE * QR_SIZE];

  qr_code.version = QR_VERSION;
  qr_code.size = QR_SIZE;
  qr_code.mode = QR_MODE_NUMERIC;
  qr_code.error_correction_level = QR_ERROR_CORRECTION_LEVEL_L;
  qr_code.data = "0123456789";
  qr_code.data_length = strlen(qr_code.data);

  qr_code_generate_matrix(&qr_code, matrix);
  qr_code_print_matrix(&qr_code, matrix);

  return 0;
}

