bool Room::overlaps(Room& b, float padding)
{
	auto a = this;
	return !((b.getLeft(padding)) >= a->getRight(padding) ||
		b.getRight(padding) <= (a->getLeft(padding)) ||
		b.getTop(padding) <= (a->getBottom(padding)) ||
		(b.getBottom(padding)) >= a->getTop(padding));

