// Romantic CPU Scheduling Algorithm Example Program

#include <stdio.h>
#include <stdlib.h>

struct Process {
  int pid;
  int arrival_time;
  int burst_time;
  int priority;
  int waiting_time;
  int turnaround_time;
};

void print_process(struct Process p) {
  printf("Process %d: ", p.pid);
  printf("Arrival time: %d, ", p.arrival_time);
  printf("Burst time: %d, ", p.burst_time);
  printf("Priority: %d, ", p.priority);
  printf("Waiting time: %d, ", p.waiting_time);
  printf("Turnaround time: %d\n", p.turnaround_time);
}

void calculate_waiting_time(struct Process *p, int time) {
  p->waiting_time = time - p->arrival_time;
}

void calculate_turnaround_time(struct Process *p, int time) {
  p->turnaround_time = time - p->arrival_time + p->burst_time;
}

void sort_by_arrival_time(struct Process *processes, int n) {
  for (int i = 0; i < n - 1; i++) {
    for (int j = i + 1; j < n; j++) {
      if (processes[i].arrival_time > processes[j].arrival_time) {
        struct Process temp = processes[i];
        processes[i] = processes[j];
        processes[j] = temp;
      }
    }
  }
}

void sort_by_priority(struct Process *processes, int n) {
  for (int i = 0; i < n - 1; i++) {
    for (int j = i + 1; j < n; j++) {
      if (processes[i].priority > processes[j].priority) {
        struct Process temp = processes[i];
        processes[i] = processes[j];
        processes[j] = temp;
      }
    }
  }
}

void romantic_scheduling(struct Process *processes, int n) {
  int time = 0;
  int burst_time = 0;
  int waiting_time = 0;
  int turnaround_time = 0;
  for (int i = 0; i < n; i++) {
    time = processes[i].arrival_time;
    burst_time = processes[i].burst_time;
    waiting_time = time - processes[i].arrival_time;
    turnaround_time = time - processes[i].arrival_time + burst_time;
    processes[i].waiting_time = waiting_time;
    processes[i].turnaround_time = turnaround_time;
  }
  sort_by_arrival_time(processes, n);
  sort_by_priority(processes, n);
}

int main() {
  struct Process processes[] = {
    {1, 0, 10, 3},
    {2, 1, 5, 4},
    {3, 2, 8, 2},
    {4, 3, 15, 1}
  };
  int n = sizeof(processes) / sizeof(processes[0]);
  romantic_scheduling(processes, n);
  for (int i = 0; i < n; i++) {
    print_process(processes[i]);
  }
  return 0;
}

