 * Time complexity
 * O(1): push_back, front, back, pop_back
 * O(n): insert(given iterator), erase(given iterator)
 * */

int main(){
    map<int, float> m;
    int num = 5, i;
    for(i = 0;i < num; i++){
        m.insert( pair<int, float> (i, (float)i));
        printMap(m);
    }

    for(i = 0;i < num; i++){
        m.insert( pair<int, float> (i + num, (float)i + num));
        printMap(m);
    }

    for(i = 0; i< num + 2; i++){
        if(i < m.size()){
            eraseKey(m,i);
            printMap(m);
        }
    }

