#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_KEY_SIZE 100
#define MAX_VALUE_SIZE 1000
#define MAX_NUM_KEYS 1000

typedef struct {
    char key[MAX_KEY_SIZE];
    char value[MAX_VALUE_SIZE];
} Record;

typedef struct {
    Record records[MAX_NUM_KEYS];
    int num_keys;
} Database;

void init_database(Database *db) {
    db->num_keys = 0;
}

int add_record(Database *db, char *key, char *value) {
    if (db->num_keys >= MAX_NUM_KEYS) {
        return -1;
    }

    strncpy(db->records[db->num_keys].key, key, MAX_KEY_SIZE);
    strncpy(db->records[db->num_keys].value, value, MAX_VALUE_SIZE);

    db->num_keys++;

    return 0;
}

int search_record(Database *db, char *key) {
    int i;

    for (i = 0; i < db->num_keys; i++) {
        if (strcmp(db->records[i].key, key) == 0) {
            return i;
        }
    }

    return -1;
}

