#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define BLOCK_SIZE 512
#define MAX_FILE_SIZE 1024 * 1024 * 10 // 10 MB

typedef struct {
    int magic_number;
    int file_size;
    char filename[256];
} file_header;

int main(int argc, char *argv[]) {
    FILE *input_file, *output_file;
    char buffer[BLOCK_SIZE];
    file_header header;
    int bytes_read, bytes_written, i;

    if (argc != 2) {
        printf("Usage: %s <corrupted_file>\n", argv[0]);
        return 1;
    }

    input_file = fopen(argv[1], "rb");
    if (!input_file) {
        perror("Error opening file");
        return 1;
    }

    output_file = fopen("recovered_file.bin", "wb");
    if (!output_file) {
        perror("Error creating output file");
        fclose(input_file);
        return 1;
    }

    if (fread(&header, sizeof(file_header), 1, input_file) != 1) {
        perror("Error reading file header");
        fclose(input_file);
        fclose(output_file);
        return 1;
    }

    if (header.magic_number != 0x12345678) {
        printf("Invalid file header\n");
        fclose(input_file);
        fclose(output_file);
        return 1;
    }

    if (header.file_size > MAX_FILE_SIZE) {
        printf("File size too large\n");
        fclose(input_file);
        fclose(output_file);
        return 1;
    }

    printf("Recovering file: %s\n", header.filename);

    fseek(input_file, header.file_size, SEEK_SET);

    while (ftell(input_file) < MAX_FILE_SIZE && (bytes_read = fread(buffer, 1, BLOCK_SIZE, input_file)) > 0) {
        bytes_written = fwrite(buffer, bytes_read, 1, output_file);
        if (bytes_written != 1) {
            perror("Error writing to output file");
            fclose(input_file);
            fclose(output_file);
            return 1;
        }
    }

    fclose(input_file);
    fclose(output_file);

    printf("File recovery completed.\n");

    for (i = 0; i < strlen(header.filename) + 1; i++) {
        if (header.filename[i] == '\0') {
            header.filename[i] = '\0';
            break;
        }
        if (header.filename[i] == '/' || header.filename[i] == '\\') {
            header.filename[i] = '\0';
            int j = i;
            for (; j < strlen(header.filename) + 1; j++) {
                header.filename[j] = header.filename[j + 1];
            }
            i--;
        }
    }

    printf("Original file name: %s\n", header.filename);

    return 0;
}

