#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure to represent a job
typedef struct Job {
    char id[10];     // Job ID
    int deadline;    // Deadline of the job
    int profit;     // Profit of the job
} Job;

// Function to compare jobs based on their profits
int compareJobs(const void *a, const void *b) {
    const Job *job1 = (const Job *)a;
    const Job *job2 = (const Job *)b;
    return job2->profit - job1->profit;
}

// Function to find the maximum profit from a set of jobs
int findMaxProfit(Job jobs[], int n) {
    // Sort jobs in descending order of profits
    qsort(jobs, n, sizeof(Job), compareJobs);

    // Create an array to store the selected jobs
    int selectedJobs[n];
    memset(selectedJobs, 0, sizeof(selectedJobs));

    // Initialize the current time to 0
    int currentTime = 0;

    // Iterate through the jobs and select the most profitable job that can be completed by the current time
    int maxProfit = 0;
    for (int i = 0; i < n; i++) {
        if (currentTime + jobs[i].deadline <= jobs[i].deadline) {
            selectedJobs[i] = 1;
            currentTime += jobs[i].deadline;
            maxProfit += jobs[i].profit;
        }
    }

    // Print the selected jobs
    printf("Selected jobs:\n");
    for (int i = 0; i < n; i++) {
        if (selectedJobs[i]) {
            printf("%s ", jobs[i].id);
        }
    }

    // Return the maximum profit
    return maxProfit;
}

// Main function
int main() {
    // Create a set of jobs
    Job jobs[] = {
        {"J1", 2, 60},
        {"J2", 1, 100},
        {"J3", 3, 20},
        {"J4", 2, 40},
        {"J5", 1, 30}
    };

    // Find the maximum profit from the set of jobs
    int n = sizeof(jobs) / sizeof(jobs[0]);
    int maxProfit = findMaxProfit(jobs, n);

    // Print the maximum profit
    printf("Maximum profit: %d\n", maxProfit);

    return 0;
}

