    printf("|------------------------------|--------------------|----------|----------|\n");
    int i, found = 0;
    for (i = 0; i < numItems; i++) {
        if (strcmp(items[i].category, category) == 0) {
            printf("|%-30s|%-20s|%10d|%10.2f|\n", items[i].name, items[i].category, items[i].quantity, items[i].price);
            found = 1;
        }
