#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int id;
    float x, y;
    int speed;
    int direction;
} Vehicle;

#define MAX_VEHICLES 10

void set_speed(Vehicle* vehicle, int speed) {
    vehicle->speed = speed;
}

void set_direction(Vehicle* vehicle, int direction) {
    vehicle->direction = direction;
}

void move(Vehicle* vehicle) {
    switch (vehicle->direction) {
        case 0:
            vehicle->y += vehicle->speed;
            break;
        case 1:
            vehicle->x += vehicle->speed;
            break;
        case 2:
            vehicle->y -= vehicle->speed;
            break;
        case 3:
            vehicle->x -= vehicle->speed;
            break;
        default:
            printf("Invalid direction\n");
            break;
    }
}

Vehicle vehicles[MAX_VEHICLES];

void init_vehicles() {
    for (int i = 0; i < MAX_VEHICLES; i++) {
        vehicles[i].id = i + 1;
        vehicles[i].x = 0;
        vehicles[i].y = 0;
        vehicles[i].speed = 0;
        vehicles[i].direction = 0;
    }
}

