#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/evp.h>

#define KEY_LENGTH 32
#define DATA_LENGTH 100

int main() {
    char key[KEY_LENGTH];
    char plaintext[DATA_LENGTH];
    char ciphertext[DATA_LENGTH];
    char decrypted_text[DATA_LENGTH];

    // Generate a random key
    for (int i = 0; i < KEY_LENGTH; ++i) {
        key[i] = rand() % 256;
    }

    // Prepare some plaintext
    strcpy(plaintext, "This is a secret message.");

    // Initialize AES encryption algorithm
    EVP_CIPHER_CTX *ctx;
    ctx = EVP_CIPHER_CTX_new();

    const EVP_CIPHER *cipher = EVP_aes_128_cbc();
    EVP_EncryptInit_ex(ctx, cipher, NULL, key, NULL);

    // Encrypt plaintext and store result in ciphertext
    int ciphertext_len = DATA_LENGTH;
    EVP_EncryptUpdate(ctx, ciphertext, &ciphertext_len, plaintext, strlen(plaintext));
    EVP_EncryptFinal_ex(ctx, ciphertext + ciphertext_len, &ciphertext_len);

    // Print ciphertext
    printf("Encrypted: ");
    for (int i = 0; i < DATA_LENGTH; ++i) {
        printf("%.2X ", ciphertext[i]);
    }
    printf("\n");

    // Initialize AES decryption algorithm
    EVP_DecryptInit_ex(ctx, cipher, NULL, key, NULL);

    // Decrypt ciphertext and store result in decrypted_text
    int decrypted_len = DATA_LENGTH;
    EVP_DecryptUpdate(ctx, decrypted_text, &decrypted_len, ciphertext, DATA_LENGTH);
    EVP_DecryptFinal_ex(ctx, decrypted_text + decrypted_len, &decrypted_len);

    // Print decrypted text
    printf("Decrypted: %s\n", decrypted_text);

    // Clean up
    EVP_CIPHER_CTX_free(ctx);

    return 0;
}

