void Game::processCommand(vector <string> command)
{
	string first = command.front();

	// INVALID COMMAND
	if(!isCommandValid(first))
	{
		o->print("invalid");
		return; 
	}
	// HELP
	if(first=="help")
	{
		o->print("help");
	}
	// QUIT, EXIT (NOW)
