    int value;
} variable;

int main() {
    FILE *fp;
    char line[MAX_LINE_LENGTH];
    char *token;
    int num_variables = 0;
    variable vars[MAX_NUM_VARIABLES];

    // Open the input file
    fp = fopen("input.txt", "r");
    if (fp == NULL) {
        printf("Error: Could not open input file.\n");
        exit(1);
    }

    // Read in the variables from the input file
    while (fgets(line, MAX_LINE_LENGTH, fp)!= NULL) {
        token = strtok(line, " ");
        while (token!= NULL) {
            if (num_variables >= MAX_NUM_VARIABLES) {
                printf("Error: Too many variables.\n");
                exit(1);
            }
            strcpy(vars[num_variables].name, token);
            num_variables++;
            token = strtok(NULL, " ");
        }
    }
    fclose(fp);

    // Initialize the variables to zero
    for (int i = 0; i < num_variables; i++) {
        vars[i].value = 0;
    }

    // Read in the expressions from the input file
    fp = fopen("input.txt", "r");
    if (fp == NULL) {
        printf("Error: Could not open input file.\n");
        exit(1);
    }

    // Evaluate the expressions and print the results
    while (fgets(line, MAX_LINE_LENGTH, fp)!= NULL) {
        token = strtok(line, " ");
        while (token!= NULL) {
            int found = 0;
            for (int i = 0; i < num_variables; i++) {
                if (strcmp(vars[i].name, token) == 0) {
                    vars[i].value = atoi(strtok(NULL, " "));
                    found = 1;
                    break;
                }
            }
            if (!found) {
                printf("Error: Variable not found.\n");
                exit(1);
            }
            token = strtok(NULL, " ");
        }
    }
    fclose(fp);

    // Print the final values of the variables
    for (int i = 0; i < num_variables; i++) {
        printf("%s = %d\n", vars[i].name, vars[i].value);
    }

    return 0;
}

