#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_WORDS 100
#define MAX_LINE_LEN 100
#define MAX_FILE_LEN 10000

void parse_file(const char* filename);
void parse_line(const char* line);
int is_spam(const char* line);

int main(int argc, char* argv[]) {
    if (argc!= 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    parse_file(argv[1]);
    return 0;
}

void parse_file(const char* filename) {
    FILE* fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening file %s\n", filename);
        return;
    }

    char line[MAX_LINE_LEN + 1];
    while (fgets(line, sizeof(line), fp)!= NULL) {
        parse_line(line);
    }

    fclose(fp);
}

void parse_line(const char* line) {
    char* word = strtok(line, " \t");
    while (word!= NULL) {
        int len = strlen(word);
        if (len > MAX_WORDS) {
            fprintf(stderr, "Error: word '%s' is too long\n", word);
            continue;
        }
        if (is_spam(word)) {
            printf("Found spam: '%s'\n", word);
        }
        word = strtok(NULL, " \t");
    }
}

int is_spam(const char* word) {
    int len = strlen(word);
    if (len > MAX_WORDS) {
        return 0;
    }
    if (len == 0) {
        return 0;
    }
    if (strstr(word, "buy")!= NULL) {
        return 1;
    }
    if (strstr(word, "free")!= NULL) {
        return 1;
    }
    if (strstr(word, "click")!= NULL) {
        return 1;
    }
    return 0;
}

