      return CMD_EXEC_ERROR;

   int m;
   if (!myStr2Int(token, m) || (m <= 0))
      return CmdExec::errorOption(CMD_OPT_ILLEGAL, token);

   if (ModNum::getModulus() != m) {
      ModNum::setModulus(m);
