//597 Tính số thứ tự ngày trong năm
int TinhSoThuTuNgayTrongNam(NGAY a)
{
    /*
int n[12] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (KiemTraNamNhuan(a))
        n[1] = 29;
