//MISTRAL-7B DATASET v1.0 Category: Word Count Tool ; Style: modular
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_LINE_LENGTH 1024

void count_words(char *line) {
    int num_words = 0;
    int in_word = 0;
    char current_char;

    for (int i = 0; i < strlen(line) && line[i] != '\0'; ++i) {
        current_char = line[i];
        if (isspace(current_char)) {
            if (in_word) {
                ++num_words;
                in_word = 0;
            }
        } else {
            in_word = 1;
        }
    }

    if (in_word) {
        ++num_words;
    }

    printf("Number of words in line: %d\n", num_words);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <file>\n", argv[0]);
        return 1;
    }

    FILE *fp = fopen(argv[1], "r");

    if (fp == NULL) {
        perror("Error opening file");
        return 1;
    }

    char line[MAX_LINE_LENGTH];
    int num_words = 0;

    while (fgets(line, sizeof(line), fp) != NULL) {
        count_words(line);
        num_words += strlen(line) / MAX_LINE_LENGTH + 1;
    }

    printf("Total number of words in file: %d\n", num_words);

    fclose(fp);
    return 0;
}

