int ATOI(char s[])
{
    int tong = 0;
    int length = STRLEN(s);
    int temp = length;
    // Xác định temp để biết phạm vi mình sẽ duyệt
    for(int i = 0; i < length; i++)
    {
        if(s[i] < '0' || s[i] > '9') // Không phãi là số
        {
            temp = i;
            break;
        }
    }
    // Tính ra kết quã
    int tam = temp;
    for(int i = 0; i < temp; i++)
    {
        tong +=(s[i] - 48) * pow(10.0, --tam); // đổi ký tự sang số rồi nhân cho 10 mũ ...
    }
    return tong;
}

