//设置迷宫地图
void Maze::setMap(int _row, int _column, bool *_map)
{
	map.set(_row, _column);
	map.set(_map);
	//设置地图标记的大小为地图大小
	mark.set(_row, _column);
	//设置地图标记位都为0
