	return true;
}

PNode findRearNode_Link(LinkList llist) //查找llist的尾节点地址
{
	PNode r = llist;
	while (r->link != NULL)
	{
		r = r->link;
	}
	return r;
}

DataType findMin_Link(LinkList llist) //找出表中最小的值
{
	PNode p = llist->link;
	DataType temp = p->info;
	while (p->link != NULL)
	{
		p = p->link;
		if (temp > p->info)
			temp = p->info;
	}
	return temp;
}

DataType findMax_Link(LinkList llist) //找出表中最大的值
{
	PNode p = llist->link;
	DataType temp = p->info;
	while (p->link != NULL)
	{
		p = p->link;
		if (temp < p->info)
			temp = p->info;
	}
	return temp;
}

