// Function prototypes
void parse_html(char *html);
void print_html(char *html);

int main(void)
{
    char html[1000];

    // Read HTML from stdin
    fgets(html, sizeof(html), stdin);

    // Parse HTML
    parse_html(html);

    // Print HTML
    print_html(html);

    return 0;
}

void parse_html(char *html)
{
    char *tag;
    char *end_tag;
    int tag_length;

    // Parse HTML tags
    tag = strstr(html, "<");
    while (tag != NULL)
    {
        // Get end tag
        end_tag = strstr(tag, ">");
        if (end_tag == NULL)
            break;

        // Get tag length
        tag_length = end_tag - tag;

        // Remove tag
        memmove(tag, end_tag + 1, strlen(end_tag + 1) + 1);

        // Move pointer to next tag
        tag = strstr(tag, "<");
    }
}

void print_html(char *html)
{
    printf("%s", html);
}

