// Function to calculate the factorial of a number
int factorial(int n) {
    if (n == 0) {
        return 1;
    } else {
        return n * factorial(n - 1);
    }
}

// Function to calculate the power of a number
double power(double x, int n) {
    if (n == 0) {
        return 1;
    } else if (n < 0) {
        return 1 / power(x, -n);
    } else {
        return x * power(x, n - 1);
    }
}

// Function to calculate the logarithm of a number
double logarithm(double x, double base) {
    if (x <= 0 || base <= 0 || base == 1) {
        printf("Error: Invalid input for logarithm function.\n");
        exit(1);
    }
    return log10(x) / log10(base);
}

// Function to calculate the trigonometric sine of an angle
double sine(double angle) {
    return sin(angle * M_PI / 180);
}

// Function to calculate the trigonometric cosine of an angle
double cosine(double angle) {
    return cos(angle * M_PI / 180);
}

// Function to calculate the trigonometric tangent of an angle
double tangent(double angle) {
    return tan(angle * M_PI / 180);
}

// Function to calculate the inverse trigonometric sine of a value
double arcsine(double x) {
    if (x < -1 || x > 1) {
        printf("Error: Invalid input for arcsine function.\n");
        exit(1);
    }
    return asin(x) * 180 / M_PI;
}

// Function to calculate the inverse trigonometric cosine of a value
double arccosine(double x) {
    if (x < -1 || x > 1) {
        printf("Error: Invalid input for arccosine function.\n");
        exit(1);
    }
    return acos(x) * 180 / M_PI;
}

// Function to calculate the inverse trigonometric tangent of a value
double arctangent(double x) {
    return atan(x) * 180 / M_PI;
}

