//GPT-4o-mini DATASET v1.0 Category: Robot movement control ; Style: puzzling
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

#define GRID_SIZE 5
#define EMPTY ' '
#define ROBOT 'R'
#define TARGET 'T'
#define OBSTACLE 'X'

typedef struct {
    int x;
    int y;
} Position;

void initializeGrid(char grid[GRID_SIZE][GRID_SIZE], Position *robot, Position *target) {
    // Clear the grid and place the robot and target at random positions
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < GRID_SIZE; j++) {
            grid[i][j] = EMPTY;
        }
    }

    robot->x = rand() % GRID_SIZE;
    robot->y = rand() % GRID_SIZE;
    target->x = rand() % GRID_SIZE;
    target->y = rand() % GRID_SIZE;

    // Randomly place obstacles
    for (int i = 0; i < 5; i++) {
        int obs_x = rand() % GRID_SIZE;
        int obs_y = rand() % GRID_SIZE;
        if ((obs_x != robot->x || obs_y != robot->y) && 
            (obs_x != target->x || obs_y != target->y)) {
            grid[obs_x][obs_y] = OBSTACLE;
        }
    }

    grid[robot->x][robot->y] = ROBOT;
    grid[target->x][target->y] = TARGET;
}

void printGrid(char grid[GRID_SIZE][GRID_SIZE]) {
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < GRID_SIZE; j++) {
            printf("%c ", grid[i][j]);
        }
        printf("\n");
    }
    printf("\n");
}

int isValidMove(char grid[GRID_SIZE][GRID_SIZE], Position pos) {
    return (pos.x >= 0 && pos.x < GRID_SIZE && 
            pos.y >= 0 && pos.y < GRID_SIZE && 
            grid[pos.x][pos.y] != OBSTACLE);
}

void moveRobot(char grid[GRID_SIZE][GRID_SIZE], Position *robot, int dx, int dy) {
    Position new_pos = {robot->x + dx, robot->y + dy};
    if (isValidMove(grid, new_pos)) {
        grid[robot->x][robot->y] = EMPTY; // Clear old position
        robot->x += dx;
        robot->y += dy;
        grid[robot->x][robot->y] = ROBOT; // Update new position
    }
}

void findTarget(char grid[GRID_SIZE][GRID_SIZE], Position *robot, Position target) {
    while (robot->x != target.x || robot->y != target.y) {
        printGrid(grid);
        sleep(1); // Simulate movement delay

        if (robot->x < target.x) {
            moveRobot(grid, robot, 1, 0);
        } else if (robot->x > target.x) {
            moveRobot(grid, robot, -1, 0);
        }

        if (robot->y < target.y) {
            moveRobot(grid, robot, 0, 1);
        } else if (robot->y > target.y) {
            moveRobot(grid, robot, 0, -1);
        }
    }
    printf("Target reached at (%d, %d)!\n", robot->x, robot->y);
}

int main() {
    char grid[GRID_SIZE][GRID_SIZE];
    Position robot, target;

    srand(time(0)); // Seed random number generator
    initializeGrid(grid, &robot, &target);

    printf("Initial Robot Position: (%d, %d)\n", robot.x, robot.y);
    printf("Target Position: (%d, %d)\n\n", target.x, target.y);

    findTarget(grid, &robot, target);

    return 0;
}

