#include <stdio.h>
#include <stdlib.h>

#define N 3
#define M 3

typedef struct {
    float a[N][M];
    float b[N][M];
    float c[N][M];
} matrix;

matrix add(matrix a, matrix b) {
    matrix result;

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            result.a[i][j] = a.a[i][j] + b.a[i][j];
            result.b[i][j] = a.b[i][j] + b.b[i][j];
            result.c[i][j] = a.c[i][j] + b.c[i][j];
        }
    }

    return result;
}

void print_matrix(matrix m) {
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            printf("%.2f ", m.a[i][j]);
        }
        printf("\n");

        for (int j = 0; j < M; j++) {
            printf("%.2f ", m.b[i][j]);
        }
        printf("\n");

        for (int j = 0; j < M; j++) {
            printf("%.2f ", m.c[i][j]);
        }
        printf("\n\n");
    }
}

int main() {
    matrix a, b, c, result;

    printf("Enter elements of matrix A:\n");
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            scanf("%f", &a.a[i][j]);
            scanf("%f", &a.b[i][j]);
            scanf("%f", &a.c[i][j]);
        }
    }

    printf("Enter elements of matrix B:\n");
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            scanf("%f", &b.a[i][j]);
            scanf("%f", &b.b[i][j]);
            scanf("%f", &b.c[i][j]);
        }
    }

    result = add(a, b);
    printf("Matrix A:\n");
    print_matrix(a);

    printf("Matrix B:\n");
    print_matrix(b);

    printf("Sum of Matrix A and Matrix B:\n");
    print_matrix(result);

    return 0;
}

//LLAMA2-13B DATASET v1.0 Category: Sorting ; Style: random
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define ARRAY_SIZE 10

// Structure to hold an integer and its index in the array
typedef struct {
    int value;
    int index;
} int_index_t;

// Function to generate a random integer and its index in the array
int generate_random_index(int array_size) {
    int i = (int)random() % array_size;
    return i;
}

// Function to swap two elements in the array
void swap(int *arr, int i, int j) {
    int temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

// Function to sort the array using selection sort
void sort(int arr[ARRAY_SIZE]) {
    int i, j, min_index;

    // Select the first element as the smallest
    min_index = 0;
    for (i = 1; i < ARRAY_SIZE; i++) {
        if (arr[i] < arr[min_index]) {
            min_index = i;
        }
    }

    // Swap the smallest element with the first element
    swap(arr, min_index, 0);

    // Repeat the selection process until the end of the array
    for (j = 1; j < ARRAY_SIZE - 1; j++) {
        // Select the next smallest element
        min_index = j + 1;
        for (i = j + 1; i < ARRAY_SIZE; i++) {
            if (arr[i] < arr[min_index]) {
                min_index = i;
            }
        }

        // Swap the smallest element with the current first element
        swap(arr, min_index, j);
    }
}

int main() {
    int arr[ARRAY_SIZE] = {65, 23, 98, 42, 17, 76, 35, 21, 58};
    int i, j;

    // Generate a random index and swap the element at that index with the first element
    int random_index = generate_random_index(ARRAY_SIZE);
    swap(arr, random_index, 0);

    // Sort the array using selection sort
    sort(arr);

    // Print the sorted array
    for (i = 0; i < ARRAY_SIZE; i++) {
        printf("%d ", arr[i]);
    }

    return 0;
}

