#include<stdio.h>
#include<conio.h>
#include<math.h>
#define MAX 100

void nhap (int a[], int &n)
{
    do
    {
        printf("\nNhap so phan tu: ");
        scanf("%d", &n);
        if(n <= 0 || n > MAX)
        {
            printf("\nSo phan tu khong hop le. Xin kiem tra lai !");
        }
    }while(n <= 0 || n > MAX);
    for(int i = 0; i < n; i++)
    {
        printf("\nNhap a[%d]: ", i);
        scanf("%d", &a[i]);
    }
}

void xuat(int a[], int n)
{
    for(int i = 0; i < n; i++)
    {
        printf("%4d", a[i]);
    }
}

int KiemTraMangACoPhaiLaMangConCuaMangB(int a[], int b[], int na, int nb)
{
    int i, j, Check = 0;
    for(i = 0; i < nb; i++)            // Duyệt mảng b coi
    {
        if(b[i] == a[0])        // Nếu mà thấy bất kỳ phần tử nào của mảng b
        {                       // mà bằng phần tử đầu tiên của mảng a
            int Start = i;      // bắt đầu đếm tại vị trí đó
            Check = 1;
            for(j = 0; j < na; j++)
            {
                if(a[j] != b[Start++])      // Kiểm tra coi có cái nào khác không ?
                {
                    Check = 0;               // Nếu có thì biến
                    break;
                }
            }
            if(Check == 1)      // đi hết vòng lặp nếu mà không có cái nào khác
            {
                return Check; // Mảng a là mảng con của b
            }
        }
    }
    return Check;
}
int main()
{
    int na, nb;
    int a[MAX], b[MAX];

    nhap(a, na);
    xuat(a, na);

    nhap(b, nb);
    xuat(b, nb);

    int Check = KiemTraMangACoPhaiLaMangConCuaMangB(a, b, na, nb);
    if(Check != 1)
    {
        printf("\nMang a khong la mang con cua b!");
    }
    else
    {
        printf("\nMang a la mang con cua b");
    }
    getch();
    return 0;
}

//GEMINI-pro DATASET v1.0 Category: Electronic Voting System ; Style: distributed
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_VOTES 100
#define MAX_CANDIDATES 10

typedef struct {
  int id;
  char name[100];
  int votes;
} Candidate;

Candidate candidates[MAX_CANDIDATES];
int num_candidates = 0;

int server_socket;

void *handle_client(void *arg) {
  int client_socket = *((int *)arg);
  free(arg);

  // Receive the candidate ID from the client
  int candidate_id;
  recv(client_socket, &candidate_id, sizeof(int), 0);

  // Increment the vote count for the candidate
  candidates[candidate_id - 1].votes++;

  // Send the updated vote count back to the client
  send(client_socket, &candidates[candidate_id - 1].votes, sizeof(int), 0);

  // Close the client socket
  close(client_socket);

  return NULL;
}

int main() {
  // Set up the server socket
  server_socket = socket(AF_INET, SOCK_STREAM, 0);
  if (server_socket == -1) {
    perror("socket");
    return 1;
  }

  struct sockaddr_in server_address;
  memset(&server_address, 0, sizeof(server_address));
  server_address.sin_family = AF_INET;
  server_address.sin_port = htons(8080);
  server_address.sin_addr.s_addr = htonl(INADDR_ANY);

  if (bind(server_socket, (struct sockaddr *)&server_address, sizeof(server_address)) == -1) {
    perror("bind");
    return 1;
  }

  if (listen(server_socket, 5) == -1) {
    perror("listen");
    return 1;
  }

  // Set up the candidates
  strcpy(candidates[0].name, "John Smith");
  strcpy(candidates[1].name, "Jane Doe");
  strcpy(candidates[2].name, "Bob Jones");

  // Main loop
  while (1) {
    // Accept a client connection
    int client_socket = accept(server_socket, NULL, NULL);
    if (client_socket == -1) {
      perror("accept");
      continue;
    }

    // Create a thread to handle the client
    pthread_t thread;
    int *arg = malloc(sizeof(int));
    *arg = client_socket;
    if (pthread_create(&thread, NULL, handle_client, arg) != 0) {
      perror("pthread_create");
      close(client_socket);
      continue;
    }
  }

  // Close the server socket
  close(server_socket);

  return 0;
}

