#define TIME_INTERVAL 10

int main(int argc, char *argv[]) {
  float temperature;
  int count = 0;
  time_t start_time;
  time_t current_time;

  // Initialize the temperature variable
  temperature = 20.0;

  // Get the current time
  start_time = time(NULL);

  while (1) {
    // Get the current temperature
    temperature = 20.0 + (rand() % 10);

    // Print the temperature and time
    printf("Temperature: %f\n", temperature);
    printf("Time: %s\n", asctime(localtime(&current_time)));

    // Wait for 10 seconds
    sleep(TIME_INTERVAL);

    // Increment the count
    count++;

    // Check if the count is greater than 10
    if (count > 10) {
      // Calculate the average temperature
      float average_temperature = temperature / count;

      // Print the average temperature
      printf("Average temperature: %f\n", average_temperature);

      // Exit the program
      break;
    }
  }

  return 0;
}

