#include <stdio.h>
#include <stdlib.h>
#include <math.h>

typedef struct {
    double x, y;
} Point;

Point vector_add(Point a, Point b) {
    Point c;
    c.x = a.x + b.x;
    c.y = a.y + b.y;
    return c;
}

Point scale_vector(Point v, double s) {
    Point w;
    w.x = v.x * s;
    w.y = v.y * s;
    return w;
}

double distance_point_point(Point a, Point b) {
    Point c = vector_add(a, b);
    double d = sqrt(pow(c.x, 2) + pow(c.y, 2));
    return d;
}

Point normalize_vector(Point v) {
    double mag = sqrt(pow(v.x, 2) + pow(v.y, 2));
    v.x /= mag;
    v.y /= mag;
    return v;
}

Point triple_scalar_product(Point a, Point b, Point c) {
    double d;
    d = (a.x * (b.y * c.x - b.x * c.y) +
         a.y * (b.x * c.y - b.y * c.x));
    Point e;
    e.x = d * normalize_vector(vector_add(a, b)).x;
    e.y = d * normalize_vector(vector_add(a, b)).y;
    return e;
}

double triangle_area(Point a, Point b, Point c) {
    Point s = {0, 0};
    s.x = (a.x * (b.y - c.y) +
           b.x * (c.x - a.x) +
           c.x * (a.y - b.y));
    s.y = (a.y * (b.x - c.x) +
           b.y * (c.y - a.y) +
           c.y * (a.x - b.x));
    double area = fabs(0.5 * sqrt(pow(s.x, 2) + pow(s.y, 2)));
    return area;
}

int main() {
    Point a = {1, 2};
    Point b = {3, 4};
    Point c = {5, 6};

    Point d = vector_add(a, b);
    double e = distance_point_point(a, b);
    Point f = normalize_vector(d);
    Point g = triple_scalar_product(a, b, c);
    double h = triangle_area(a, b, c);

    printf("Vector d: (%lf, %lf)\n", d.x, d.y);
    printf("Distance e: %lf\n", e);
    printf("Normal vector f: (%lf, %lf)\n", f.x, f.y);
    printf("Triple scalar product g: (%lf, %lf)\n", g.x, g.y);
    printf("Triangle area h: %lf\n", h);

    return 0;
}

