void ThaySoGanNhat(float &n)
{
    int phannguyen = (int)(n);
    float phanle = n - phannguyen;
    // làm tròn
    if(phanle <= 0.5)      
    {
        n = (float)phannguyen;
    }
    else
    {
        n = (float)phannguyen + 1;
    }
}
