/*
- Kiểm tra phần tử đó có lớn nhất trên dòng nó đang đứng hay không ?
- Kiểm tra phần tử đó có lớn nhất trên cột nó đang đứng hay không ?
- Kiểm tra phần tử đó có lớn nhất trên 2 đường chéo hay không (Đây là hàm khá phức tạp). Trường hợp này mình sẽ cho duyệt theo 4 hướng (4 while):
+ từ vị trí phần tử hiện tại, i--, j-- (giảm qua trái)
+ từ vị trí phần tử hiện tại i--,j++ (giảm phải)
+ // i++,j++ (tăng phải)
+ // i++,j-- (tăng trái)

Sau khi thực hiện 3 hàm trên, duyệt ma trận sẽ tìm được phần tử "Hoàng Hậu"
*/
bool KiemTraCoPhaiPhanTuHoangHau(int a[][MAX], int vtdong, int vtcot, int dong, int cot)
{
    int x = a[vtdong][vtcot];

    // kiểm tra dòng
    for(int i = 0; i < cot; i++)
    {
        if(a[vtdong][i] > x)
        {
            return false;
        }
    }
    // kiểm tra cột
    for(int j = 0; j < dong; j++)
    {
        if(a[j][vtcot] > x)
        {
            return false;
        }
    }
    //ktra duong cheo thu nhat
    int vtdong1 = vtdong + 1;
    int vtcot1 = vtcot + 1;
    while (vtcot1 + 1 < cot && vtdong1 < vtdong)
    {
        if (a[vtcot1][vtdong1] > x)
            return false;
        // tăng phải
        vtcot1++;
        vtdong1++;
    }
    vtdong1 = vtdong - 1;
    vtcot1 = vtcot - 1;
    while (vtcot1 - 1 >= 0 && vtdong1 >= 0)
    {
        if (a[vtcot1][vtdong1] > x)
            return false;
        //giảm qua trái
        vtcot1--;
        vtdong1--;
    }
    // duong cheo thu 2
    vtdong1 = vtdong + 1;
    vtcot1 = vtcot - 1;
    while (vtcot1 - 1 >= 0 && vtdong1 < dong)
    {
        if (a[vtcot1][vtdong1] > x)
            return false;
        // tăng trái
        vtdong1++;
        vtcot1--;
    }
    vtdong1 = vtdong - 1;
    vtcot1 = vtcot + 1;

    while (vtdong1 - 1 >= 0 && vtcot1 < cot)
    {
        if (a[vtcot1][vtdong1] > x)
            return false;
        // giảm phải
        vtdong1--;
        vtcot1++;
    }
    return true;
}

int DemSoLuongPhanTuHoangHau(int a[][MAX], int dong, int cot)
{
    int dem = 0;
    for(int i = 0; i < dong; i++)
    {
        for(int j = 0; j < cot; j++)
        {
            if(KiemTraCoPhaiPhanTuHoangHau(a, i, j, dong, cot) == true)
            {
                dem++;
            }
        }
    }
    return dem;
}
int main()
{
    int a[MAX][MAX], dong, cot;
    NhapMang(a, dong, cot);
    XuatMang(a, dong, cot);

    int dem = DemSoLuongPhanTuHoangHau(a, dong, cot);
    printf("\nSo luong phan tu hoang hau = %d", dem);
    getch();
    return 0;
}

//LLAMA2-13B DATASET v1.0 Category: Game of Life ; Style: mathematical
#include <stdio.h>
#include <stdlib.h>

#define CELL_SIZE 10
#define GRID_SIZE 100

typedef struct cell {
    int alive;
    int neighbors_alive;
} cell_t;

cell_t** create_grid(void) {
    cell_t** grid = calloc(GRID_SIZE, sizeof(cell_t*));
    for (int i = 0; i < GRID_SIZE; i++) {
        grid[i] = calloc(CELL_SIZE, sizeof(cell_t));
        for (int j = 0; j < CELL_SIZE; j++) {
            grid[i][j].alive = rand() % 2;
            grid[i][j].neighbors_alive = 0;
        }
    }
    return grid;
}

void update_grid(cell_t** grid) {
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < CELL_SIZE; j++) {
            int alive_neighbors = 0;
            for (int k = -1; k <= 1; k++) {
                for (int l = -1; l <= 1; l++) {
                    if (k == 0 || l == 0) continue;
                    if (grid[i + k][j + l].alive) alive_neighbors++;
                }
            }
            grid[i][j].neighbors_alive = alive_neighbors;
            if (grid[i][j].alive && grid[i][j].neighbors_alive < 2) {
                grid[i][j].alive = 0;
            } else if (!grid[i][j].alive && grid[i][j].neighbors_alive == 3) {
                grid[i][j].alive = 1;
            }
        }
    }
}

void print_grid(cell_t** grid) {
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < CELL_SIZE; j++) {
            if (grid[i][j].alive) printf("1 ");
            else printf("0 ");
        }
