//GPT-4o-mini DATASET v1.0 Category: Spam Detection System ; Style: unmistakable
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAX_MESSAGES 100
#define MAX_LENGTH 256

typedef struct {
    char messages[MAX_MESSAGES][MAX_LENGTH];
    int count;
} SpamDatabase;

void initializeDatabase(SpamDatabase *db) {
    db->count = 0;
}

void addSpamMessage(SpamDatabase *db, const char *message) {
    if (db->count < MAX_MESSAGES) {
        strncpy(db->messages[db->count], message, MAX_LENGTH);
        db->messages[db->count][MAX_LENGTH - 1] = '\0'; // Ensure null termination
        db->count++;
    } else {
        printf("Spam database is full. Can't add new message.\n");
    }
}

bool isSpamMessage(SpamDatabase *db, const char *message) {
    for (int i = 0; i < db->count; i++) {
        if (strstr(message, db->messages[i]) != NULL) {
            return true; // Spam detected!
        }
    }
    return false; // No spam found
}

void displaySpamDatabase(SpamDatabase *db) {
    printf("Current Spam Database:\n");
    for (int i = 0; i < db->count; i++) {
        printf("%d: %s\n", i + 1, db->messages[i]);
    }
}

void logMessage(const char *message, const char *type) {
    FILE *logfile = fopen("spam_log.txt", "a");
    if (logfile != NULL) {
        fprintf(logfile, "%s: %s\n", type, message);
        fclose(logfile);
    } else {
        printf("Error opening log file.\n");
    }
}

void processMessages(SpamDatabase *db) {
    char inputMessage[MAX_LENGTH];
    printf("Enter messages to check for spam (type 'exit' to stop):\n");

    while (true) {
        printf("> ");
        fgets(inputMessage, MAX_LENGTH, stdin);
        inputMessage[strcspn(inputMessage, "\n")] = '\0'; // Remove newline

        if (strcmp(inputMessage, "exit") == 0) {
            break;
        }

        if (isSpamMessage(db, inputMessage)) {
            printf("Spam detected: %s\n", inputMessage);
            logMessage(inputMessage, "SPAM");
        } else {
            printf("No spam detected: %s\n", inputMessage);
            logMessage(inputMessage, "NOT SPAM");
        }
    }
}

int main() {
    SpamDatabase db;
    initializeDatabase(&db);

    // Sample spam messages (can be expanded as per requirement)
    addSpamMessage(&db, "Congratulations, you won a prize!");
    addSpamMessage(&db, "Click here to claim your reward!");
    addSpamMessage(&db, "FREE money waiting for you!");
    addSpamMessage(&db, "Get rich quick!");
    addSpamMessage(&db, "You have been selected!");

    displaySpamDatabase(&db);
    processMessages(&db);

    return 0;
}

