/*
* C Network Topology Mapper Example Program
*
* This program maps a network topology by tracing the paths
* between all the devices in the network.
*/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_DEVICES 100
#define MAX_PATHS 1000

typedef struct {
    int id;
    char name[100];
    char type[100];
    int connected_devices[MAX_DEVICES];
    int num_connected_devices;
} Device;

typedef struct {
    int id;
    int source_device;
    int dest_device;
    char path[100];
} Path;

void map_network_topology(Device *devices, int num_devices) {
    int i, j, k;
    Path paths[MAX_PATHS];
    int num_paths = 0;

    // Initialize all paths as unvisited
    for (i = 0; i < MAX_PATHS; i++) {
        paths[i].id = -1;
    }

    // Find all paths between devices
    for (i = 0; i < num_devices; i++) {
        for (j = 0; j < devices[i].num_connected_devices; j++) {
            for (k = 0; k < devices[devices[i].connected_devices[j]].num_connected_devices; k++) {
                if (devices[devices[i].connected_devices[j]].connected_devices[k] == devices[i].id) {
                    continue;
                }
                Path path;
                path.id = num_paths++;
                path.source_device = devices[i].id;
                path.dest_device = devices[devices[i].connected_devices[j]].connected_devices[k];
                strcpy(path.path, devices[i].name);
                strcat(path.path, " -> ");
                strcat(path.path, devices[devices[i].connected_devices[j]].name);
                strcat(path.path, " -> ");
                strcat(path.path, devices[devices[devices[i].connected_devices[j]].connected_devices[k]].name);
                paths[path.id] = path;
            }
        }
    }

    // Print all paths
    for (i = 0; i < num_paths; i++) {
        printf("%s\n", paths[i].path);
    }
}

int main() {
    Device devices[] = {
        {1, "Device 1", "Switch", {2, 3, -1}, 2},
        {2, "Device 2", "Router", {1, 4, -1}, 2},
        {3, "Device 3", "Hub", {1, -1}, 1},
        {4, "Device 4", "Switch", {2, 5, -1}, 2},
        {5, "Device 5", "Server", {4, -1}, 1},
    };
    int num_devices = sizeof(devices) / sizeof(devices[0]);
    map_network_topology(devices, num_devices);
    return 0;
}

