  int numRooms = rand() % MAX_NUM_ROOMS + 1;
  for (int i = 0; i < numRooms; i++) {
    rooms[i] = createRoom(rand() % MAZE_WIDTH, rand() % MAZE_HEIGHT);
  }

  for (int i = 0; i < numRooms; i++) {
    if (i > 0) {
      rooms[i]->next = rooms[rand() % i];
    }
  }
}

