#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define SIZE 50
#define NEIGHBOURS 8
#define ALIVE 1
#define DEAD 0

int board[SIZE][SIZE];
int count;

void initBoard() {
    srand(time(NULL));
    for (int i = 0; i < SIZE; i++) {
        for (int j = 0; j < SIZE; j++) {
            board[i][j] = rand() % 2;
        }
    }
    count = 0;
}

void printBoard() {
    for (int i = 0; i < SIZE; i++) {
        for (int j = 0; j < SIZE; j++) {
            if (board[i][j] == ALIVE) {
                printf("*");
            } else {
                printf(".");
            }
        }
        printf("\n");
    }
}

void nextGeneration() {
    int newBoard[SIZE][SIZE];
    for (int i = 0; i < SIZE; i++) {
        for (int j = 0; j < SIZE; j++) {
            int aliveNeighbours = 0;
            for (int k = -1; k <= 1; k++) {
                for (int l = -1; l <= 1; l++) {
                    if (board[(i+k+SIZE)%SIZE][(j+l+SIZE)%SIZE] == ALIVE) {
                        aliveNeighbours++;
                    }
                }
            }
            if (board[i][j] == ALIVE) {
                if (aliveNeighbours < 2 || aliveNeighbours > 3) {
                    newBoard[i][j] = DEAD;
                } else {
                    newBoard[i][j] = ALIVE;
                }
            } else {
                if (aliveNeighbours == 3) {
                    newBoard[i][j] = ALIVE;
                } else {
                    newBoard[i][j] = DEAD;
                }
            }
        }
    }
    for (int i = 0; i < SIZE; i++) {
        for (int j = 0; j < SIZE; j++) {
            board[i][j] = newBoard[i][j];
        }
    }
    count++;
}

int main() {
    initBoard();
    while (1) {
        printBoard();
        nextGeneration();
        if (count == 500) {
            break;
        }
    }
    return 0;
}

