#include <stdio.h>
  #include <stdlib.h>
  #include <time.h>

  // Define constants
  #define WIDTH 800
  #define HEIGHT 600
  #define BALL_RADIUS 10
  #define PADDLE_WIDTH 100
  #define PADDLE_HEIGHT 20
  #define BALL_SPEED 10
  #define PADDLE_SPEED 5

  // Define structs
  typedef struct {
    int x;
    int y;
  } Point;

  typedef struct {
    Point pos;
    Point vel;
  } Ball;

  typedef struct {
    Point pos;
    Point vel;
  } Paddle;

  // Function prototypes
  void initBall(Ball *ball);
  void initPaddle(Paddle *paddle);
  void moveBall(Ball *ball, Paddle *paddle);
  void movePaddle(Paddle *paddle);
  void drawBall(Ball *ball);
  void drawPaddle(Paddle *paddle);

  // Main function
  int main() {
    // Initialize game
    srand(time(NULL));
    Ball ball;
    initBall(&ball);
    Paddle paddle;
    initPaddle(&paddle);

    // Game loop
    while (1) {
      // Update game state
      moveBall(&ball, &paddle);
      movePaddle(&paddle);

      // Draw game state
      drawBall(&ball);
      drawPaddle(&paddle);

      // Check for collisions
      if (ball.pos.x + BALL_RADIUS > WIDTH || ball.pos.x - BALL_RADIUS < 0) {
        ball.vel.x = -ball.vel.x;
      }
      if (ball.pos.y + BALL_RADIUS > HEIGHT || ball.pos.y - BALL_RADIUS < 0) {
        ball.vel.y = -ball.vel.y;
      }
      if (ball.pos.x + BALL_RADIUS > paddle.pos.x &&
          ball.pos.x - BALL_RADIUS < paddle.pos.x + PADDLE_WIDTH &&
          ball.pos.y + BALL_RADIUS > paddle.pos.y &&
          ball.pos.y - BALL_RADIUS < paddle.pos.y + PADDLE_HEIGHT) {
        ball.vel.x = -ball.vel.x;
      }

      // Check for win
      if (ball.pos.x + BALL_RADIUS > WIDTH) {
        break;
      }
    }

    return 0;
  }

  // Function definitions
  void initBall(Ball *ball) {
    ball->pos.x = WIDTH / 2;
    ball->pos.y = HEIGHT / 2;
    ball->vel.x = BALL_SPEED;
    ball->vel.y = BALL_SPEED;
  }

  void initPaddle(Paddle *paddle) {
    paddle->pos.x = WIDTH / 2 - PADDLE_WIDTH / 2;
    paddle->pos.y = HEIGHT - PADDLE_HEIGHT;
    paddle->vel.x = PADDLE_SPEED;
    paddle->vel.y = 0;
  }

  void moveBall(Ball *ball, Paddle *paddle) {
    ball->pos.x += ball->vel.x;
    ball->pos.y += ball->vel.y;
  }

  void movePaddle(Paddle *paddle) {
    paddle->pos.x += paddle->vel.x;
  }

  void drawBall(Ball *ball) {
    printf("Ball: (%d, %d)\n", ball->pos.x, ball->pos.y);
  }

  void drawPaddle(Paddle *paddle) {
    printf("Paddle: (%d, %d)\n", paddle->pos.x, paddle->pos.y);
  }

