  {
    std::atomic_ulong value {};
    TESTING_EQUAL(0, value)
    value = 1;
    TESTING_EQUAL(1, value)
    value = 0xFFFFFFFF;
    TESTING_EQUAL(0xFFFFFFFF, value)
  }
