#include <string.h>
#include <ctype.h>
#include <stdbool.h>

#define MAX_LENGTH 256
#define WORD_DELIMITER " \t\n\r,\\;:\"'`()[]{}<>"

// Function to reverse a string in place
void reverse_string(char *str, int start, int end) {
    char temp;
    while (start < end) {
        temp = str[start];
        str[start] = str[end];
        str[end] = temp;
        start++;
        end--;
    }
}

// Function to find the end of the next word in a given string
int find_next_word_end(const char *str, int current_pos, int *word_length) {
    int i = 0;
    for (; str[current_pos + i] != '\0'; i++) {
        if (strchr(WORD_DELIMITER, str[current_pos + i])) {
            *word_length = i + 1;
            return current_pos + i + 1;
        }
    }
    *word_length = i + 1;
    return -1;
}

// Function to reverse the order of the words in a given string
void reverse_word_order(char *str) {
    int len = strlen(str), start = 0, end = 0, word_length = 0;
    bool in_word = false;

    for (int i = 0; i < len; i++) {
        if (strchr(WORD_DELIMITER, str[i])) {
            if (in_word) {
                reverse_string(str, start, end);
                start = i + 1;
                in_word = false;
            }
            continue;
        }
        if (!in_word) {
            end = i;
            in_word = true;
        }
    }

    reverse_string(str, start, end);
}

int main() {
    char line[MAX_LENGTH];

    printf("Enter a line: ");
    fgets(line, sizeof(line), stdin);

    // Remove newline character from fgets input
    int newline_index = strlen(line) - 1;
    if (newline_index >= 0 && line[newline_index] == '\n') {
        line[newline_index] = '\0';
    }

    reverse_word_order(line);

    printf("Reversed word order: ");
    puts(line);

    return 0;
}

