#include <math.h>
#include <time.h>

#define MAX_STARS 1000000
#define ALIEN_RADIUS 10.0
#define EARTH_RADIUS 6371.0
#define LIGHT_SPEED 299792.458
#define PROBABILITY_THRESHOLD 0.01

typedef struct {
    double x, y, z;
} Star;

Star generate_star(void) {
    Star star;

    star.x = (double) rand() / RAND_MAX * MAX_STARS;
    star.y = (double) rand() / RAND_MAX * MAX_STARS;
    star.z = (double) rand() / RAND_MAX * MAX_STARS;

    return star;
}

double distance(Star a, Star b) {
    double dx = a.x - b.x, dy = a.y - b.y, dz = a.z - b.z;
    return sqrt(dx * dx + dy * dy + dz * dz);
}

double calculate_probability(void) {
    Star earth, stars[MAX_STARS];
    int i, total = 0;
    double probability = 0.0;

    earth.x = 0.0, earth.y = 0.0, earth.z = 0.0;

    srand(time(NULL));

    for (i = 0; i < MAX_STARS; i++) {
        stars[i] = generate_star();
    }

    for (i = 0; i < MAX_STARS; i++) {
        if (i == MAX_STARS - 1) {
            break;
        }

        double dist = distance(earth, stars[i]);

        if (dist < (ALIEN_RADIUS + EARTH_RADIUS)) {
            total++;
        }
    }

    probability = (double) total / MAX_STARS;

    return probability;
}

int main(void) {
    double probability;

    printf("Calculating Alien Invasion Probability...\n");
    probability = calculate_probability();
    printf("Alien Invasion Probability: %.10f\n", probability);

