#ifndef _CHECK_SPELL_H_
#define _CHECK_SPELL_H_

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdbool.h>

#define TABLE_SIZE 10001

typedef struct {
    char word[20];
    int is_valid;
} HashNode;

void create_hash_table(HashNode table[]);
bool is_valid_word(char word[], HashNode table[]);
void load_dictionary(HashNode table[]);

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    HashNode table[TABLE_SIZE];
    create_hash_table(table);
    load_dictionary(table);

    FILE *file = fopen(argv[1], "r");
    if (!file) {
        perror("Error opening file");
        return 1;
    }

    char word[20];
    int num_errors = 0;
    while (fscanf(file, "%s", word) != EOF) {
        if (!is_valid_word(word, table)) {
            printf("Error: %s is not a valid word.\n", word);
            num_errors++;
        }
    }

    fclose(file);
    printf("Check completed. %d errors found.\n", num_errors);

    return 0;
}

void create_hash_table(HashNode table[]) {
    for (int i = 0; i < TABLE_SIZE; i++) {
        table[i].is_valid = 1;
    }
}

bool is_valid_word(char word[], HashNode table[]) {
    int hash = hash_function(word);

    for (int i = hash; i < TABLE_SIZE; i = (i + 1) % TABLE_SIZE) {
        if (strcmp(table[i].word, word) == 0) {
            table[i].is_valid = 1;
            return true;
        }

        if (table[i].is_valid == 0) {
            continue;
        }

        strcpy(table[i].word, word);
        table[i].is_valid = 1;
        return true;
    }

    return false;
}

int hash_function(char word[]) {
    int hash = 0;
    for (int i = 0; i < strlen(word); i++) {
        hash += tolower(word[i]);
    }
    hash %= TABLE_SIZE;
    return hash;
}

void load_dictionary(HashNode table[]) {
    FILE *dictionary = fopen("dictionary.txt", "r");
    if (!dictionary) {
        perror("Error opening dictionary file");
        exit(1);
    }

    char word[20];
    while (fscanf(dictionary, "%s", word) != EOF) {
        if (is_valid_word(word, table)) {
            printf("Error: Duplicate word in dictionary: %s\n", word);
        }
    }

    fclose(dictionary);
}
