#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SIZE 1000

// Function to convert decimal to binary
void decimal_to_binary(int decimal, char* binary) {
    int i = 0;
    int remainder;
    while (decimal > 0) {
        remainder = decimal % 2;
        binary[i] = remainder + '0';
        decimal = decimal / 2;
        i++;
    }
    binary[i] = '\0';
    reverse(binary);
}

// Function to reverse a string
void reverse(char* str) {
    int i = 0;
    int j = strlen(str) - 1;
    while (i < j) {
        char temp = str[i];
        str[i] = str[j];
        str[j] = temp;
        i++;
        j--;
    }
}

// Function to convert binary to decimal
int binary_to_decimal(char* binary) {
    int decimal = 0;
    int power = 0;
    int i = strlen(binary) - 1;
    while (i >= 0) {
        if (binary[i] == '1') {
            decimal += pow(2, power);
        }
        power++;
        i--;
    }
    return decimal;
}

