        scanf("%d", &choice);
        switch (choice) {
            case 1:
                printf("Enter a decimal number: ");
                scanf("%d", &decimal);
                decimal_to_binary(decimal, binary);
                printf("Binary equivalent: %s\n", binary);
                break;
            case 2:
                printf("Enter a binary number: ");
                scanf("%s", binary);
                int decimal_result = binary_to_decimal(binary);
