// Loan calculation functions
double calculateMonthlyPayment(double loanAmount, double annualInterestRate, int loanTerm);
double calculateTotalInterestPaid(double loanAmount, double annualInterestRate, int loanTerm);
double calculateTotalLoanCost(double loanAmount, double totalInterestPaid);

// Main function
int main() {
  // Declare variables for user input and loan calculations
  double loanAmount, monthlyPayment, totalInterestPaid, totalLoanCost;
  int loanTerm;

  // Get user input for loan amount and loan term
  printf("Welcome to the Mortgage Calculator!\n");
  printf("Enter the loan amount: $");
  scanf("%lf", &loanAmount);
  printf("Enter the loan term in years (15, 20, or 30): ");
  scanf("%d", &loanTerm);

  // Calculate the monthly payment, total interest paid, and total loan cost
  monthlyPayment = calculateMonthlyPayment(loanAmount, ANNUAL_INTEREST_RATE, loanTerm);
  totalInterestPaid = calculateTotalInterestPaid(loanAmount, ANNUAL_INTEREST_RATE, loanTerm);
  totalLoanCost = calculateTotalLoanCost(loanAmount, totalInterestPaid);

  // Print the loan calculations
  printf("\nLoan Calculations:\n");
  printf("Monthly Payment: $%.2f\n", monthlyPayment);
  printf("Total Interest Paid: $%.2f\n", totalInterestPaid);
  printf("Total Loan Cost: $%.2f\n", totalLoanCost);

  return 0;
}

// Function to calculate the monthly payment
double calculateMonthlyPayment(double loanAmount, double annualInterestRate, int loanTerm) {
  double monthlyInterestRate = annualInterestRate / 12;
  double exponent = pow(1 + monthlyInterestRate, loanTerm * 12);
  return (loanAmount * monthlyInterestRate * exponent) / (exponent - 1);
}

// Function to calculate the total interest paid
double calculateTotalInterestPaid(double loanAmount, double annualInterestRate, int loanTerm) {
  double monthlyPayment = calculateMonthlyPayment(loanAmount, annualInterestRate, loanTerm);
  return (monthlyPayment * loanTerm * 12) - loanAmount;
}

// Function to calculate the total loan cost
double calculateTotalLoanCost(double loanAmount, double totalInterestPaid) {
  return loanAmount + totalInterestPaid;
}

