#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define G 6.674e-11
#define DELTAT 1000. // in seconds

typedef struct {
    double mass;
    double pos[3];
    double vel[3];
    double force[3];
} Body;

Body bodies[1000];
int numBodies = 0;

void addBody(double mass, double pos[], double vel[]) {
    // add a new body to the simulation
    bodies[numBodies].mass = mass;
    for (int i = 0; i < 3; i++) {
        bodies[numBodies].pos[i] = pos[i];
        bodies[numBodies].vel[i] = vel[i];
        bodies[numBodies].force[i] = 0.;
    }
    numBodies++;
}

void calculateForces() {
    // calculate the gravitational force on each body
    for (int i = 0; i < numBodies; i++) {
        for (int j = i + 1; j < numBodies; j++) {
            // calculate the force on body i due to body j
            double dx = bodies[i].pos[0] - bodies[j].pos[0];
            double dy = bodies[i].pos[1] - bodies[j].pos[1];
            double dz = bodies[i].pos[2] - bodies[j].pos[2];
            double r = sqrt(dx*dx + dy*dy + dz*dz);
            double f = G * bodies[i].mass * bodies[j].mass / (r*r);
            bodies[i].force[0] -= f * dx / r;
            bodies[i].force[1] -= f * dy / r;
            bodies[i].force[2] -= f * dz / r;

            // calculate the force on body j due to body i
            bodies[j].force[0] += f * dx / r;
            bodies[j].force[1] += f * dy / r;
            bodies[j].force[2] += f * dz / r;
        }
    }
}

void updatePositions() {
    // update the positions and velocities of each body
    for (int i = 0; i < numBodies; i++) {
        for (int j = 0; j < 3; j++) {
            bodies[i].pos[j] += bodies[i].vel[j] * DELTAT;
            bodies[i].vel[j] += bodies[i].force[j] / bodies[i].mass * DELTAT;
        }
    }
}

void printBodies() {
    // print the positions and velocities of each body
    for (int i = 0; i < numBodies; i++) {
        printf("Body %d: ", i);
        for (int j = 0; j < 3; j++) {
            printf("pos[%d] = %f, ", j, bodies[i].pos[j]);
            printf("vel[%d] = %f, ", j, bodies[i].vel[j]);
        }
        printf("\n");
    }
}

int main() {
    // add some bodies to the simulation
    addBody(1e24, (double[]){0., 0., 0.}, (double[]){0., 0., 0.});
    addBody(1e24, (double[]){1e11, 0., 0.}, (double[]){0., 0., 0.});

    // run the simulation for some time
    for (int i = 0; i < 10000; i++) {
        calculateForces();
        updatePositions();
    }

    // print the final positions and velocities of each body
    printBodies();

    return 0;
}

