struct node
{
    int data;
    node* left;
    node* right;
};
typedef node* NODE;
NODE get_node(int x)
{
    NODE n=new node;
    if(n==NULL)
        cout<<"Memory Full";
    n->data=x;
    n->left=NULL;
    n->right=NULL;
    return n;
}
NODE insert_node(NODE &parent,int x)
{
    char ch;
    cin>>ch;
    //if()
            //cout<<"No Possible";
    if(ch=='q'||ch=='Q'||parent==NULL)
    {
        if(parent==NULL)
            parent=get_node(x);
        else
            cout<<"Not empty";
    }
    else
    {

        if(ch=='l'||ch=='L')
            parent->left=insert_node(parent->left,x);
        else if(ch=='r'||ch=='R')
            parent->right=insert_node(parent->right,x);
    }
    return parent;
}
void preorder(NODE p)
{
    if(p!=NULL)
    {
        cout<<p->data<<"->";
        preorder(p->left);
        preorder(p->right);
    }
}
void inorder(NODE p)
{
    if(p!=NULL)
    {
        inorder(p->left);
        cout<<p->data<<"->";
        inorder(p->right);
    }
}
void postorder(NODE p)
{
    if(p!=NULL)
    {
        postorder(p->left);
        postorder(p->right);
        cout<<p->data<<"->";
    }
}
