float sigmoid(float x)
{
    return 1 / (1 + exp(-x));
}

float relu(float x)
{
    if (x < 0) {
        return 0;
    } else {
        return x;
    }
}

float activation_function(float x, char *activation)
{
    if (strcmp(activation, "sigmoid") == 0) {
