#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void compress(char *input, char *output) {
    int len = strlen(input);
    int count, i;

    for (i = 0; i < len; i++) {
        count = 1;

        // Count occurrence of the same character
        while (i < len - 1 && input[i] == input[i + 1]) {
            count++;
            i++;
        }

        // Store character and frequency in output
        sprintf(output + strlen(output), "%d%c", count, input[i]);
    }
}

void decompress(char *input, char *output) {
    int i = 0, index = 0, count;

    while (input[i]) {
        // Parse the number
        count = 0;
        while (input[i] >= '0' && input[i] <= '9') {
            count = count * 10 + (input[i] - '0');
            i++;
        }

        // Next character is the one to repeat
        char ch = input[i++];

        // Unpack into output
        for (int j = 0; j < count; j++) {
            output[index++] = ch;
        }
    }
    output[index] = '\0';  // Null terminate the output
}

int main() {
    // Input string to be compressed
    char inputString[1000];

    printf("Enter a string to compress: ");
    fgets(inputString, sizeof(inputString), stdin);

    // Remove newline character from inputString if present
    size_t len = strlen(inputString);
    if (len > 0 && inputString[len - 1] == '\n') {
        inputString[len - 1] = '\0';
    }

    // Prepare buffers for compressed and decompressed strings
    char compressedString[2000] = "";
    char decompressedString[1000] = "";

    // Compress the input string
    compress(inputString, compressedString);
    printf("Compressed string: %s\n", compressedString);

    // Decompress it back
    decompress(compressedString, decompressedString);
    printf("Decompressed string: %s\n", decompressedString);

    // Check if the original string is equal to the decompressed string
    if (strcmp(inputString, decompressedString) == 0) {
        printf("Success! The decompressed string matches the original string.\n");
    } else {
        printf("Oops! There was an error in decompression.\n");
    }

    return 0;
}

#include <iostream>
#include <fstream>
#include <vector>
#include <stack>

using namespace std;

vector<vector<int> > adj;
vector<vector<int> > trans;
vector<bool> visitato;
stack<int> s;
int counter;

void dfs(int partenza) {
    visitato[partenza] = true;

    for (int j=0; j<adj[partenza].size(); j++) {
        int vicino = adj[partenza][j];
        if (!visitato[vicino]) {
            dfs(vicino);
        }
    }

    s.push(partenza);
}


void dfs_trans(int partenza) {
    visitato[partenza] = true;
    counter++;

    for (int j=0; j<trans[partenza].size(); j++) {
        int vicino = trans[partenza][j];
        if (!visitato[vicino]) {
            dfs_trans(vicino);
        }
    }
}


int main() {
    ifstream in("input.txt");
    int N, M;
    in >> N >> M;
    adj.resize(N);
    trans.resize(N);
    visitato.resize(N);

    for (int i=0; i<M; i++) {
        int from, to;
        in >> from >> to;
        adj[from].push_back(to);
        trans[to].push_back(from);  // Grafo trasposto
    }
    in.close();

    for (int i=0; i<N; i++) {
        visitato[i] = false;
    }

    // Ordinamento topologico
    for (int i=0; i<N; i++) {
        if (!visitato[i]) {
            dfs(i);
        }
    }

    int max;

    // resetto visitato
    for (int i=0; i<N; i++) {
        visitato[i] = false;
    }

    // Visito di nuovo, pero' trasposto
    while (!s.empty()) {
        int top = s.top();
        s.pop();
        counter = 0;

        if (!visitato[top]) {
            dfs_trans(top);

            if (counter > max) {
                max = counter;
            }
        }
    }

    ofstream out("output.txt");
    out << max << endl;
    out.close();

    return 0;
}

