#include <ctype.h>

#define MAX_PASSWORD_LENGTH 100

// Function to check password strength
const char* check_password_strength(const char* password) {
    int length = strlen(password);
    int has_upper = 0, has_lower = 0, has_digit = 0, has_special = 0;

    // Check the password for various criteria
    for (int i = 0; i < length; i++) {
        if (isupper(password[i])) {
            has_upper = 1;
        } else if (islower(password[i])) {
            has_lower = 1;
        } else if (isdigit(password[i])) {
            has_digit = 1;
        } else if (ispunct(password[i])) {
            has_special = 1;
        }
    }

    // Evaluate password strength
    if (length < 8) {
        return "Weak: Password must be at least 8 characters long.";
    } else if (!has_upper || !has_lower || !has_digit || !has_special) {
        return "Moderate: Include uppercase, lowercase, digits, and special characters.";
    } else if (length >= 12 && has_upper && has_lower && has_digit && has_special) {
        return "Strong: Excellent password!";
    } else {
        return "Moderate: Good effort, but can be improved.";
    }
}

