#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Protected sorting function
void sortArray(int arr[], int n) {
    int i, j, min, temp;

    // Check for null or empty array
    if (arr == NULL || n == 0) {
        printf("Error: Null or empty array\n");
        return;
    }

    // Check for invalid array size
    if (n < 1 || n > 1000) {
        printf("Error: Invalid array size\n");
        return;
    }

    // Sort the array using a recursive divide and conquer approach
    for (i = 0; i < n - 1; i++) {
        min = i;
        for (j = i + 1; j < n; j++) {
            if (arr[j] < arr[min]) {
                min = j;
            }
        }
        temp = arr[i];
        arr[i] = arr[min];
        arr[min] = temp;
    }
}

int main() {
    int arr[10] = {3, 1, 2, 6, 4, 8, 7, 5, 9};
    int n = sizeof(arr) / sizeof(arr[0]);

    // Sort the array
    sortArray(arr, n);

    // Print the sorted array
    printf("Sorted array: ");
    for (int i = 0; i < n; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");

    return 0;
}

