    MemoryBlock mb;
    initMemoryBlock(&mb);

    // Allocate memory
    char *str1 = (char *)allocateMemory(&mb, 16);
    strcpy(str1, "Hello, world! ");

    int *arr1 = (int *)allocateMemory(&mb, 32);
    for (int i = 0; i < 10; i++) {
        arr1[i] = i * 2;
    }

    // Free memory
    freeMemory(&mb, str1);
    freeMemory(&mb, arr1);

    return 0;
}

