#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <time.h>

#define MAX_LINE 1024
#define PORT 8080

int is_spam(const char *email) {
    int i, score = 0;
    for (i = 0; email[i] != '\0'; i++) {
        switch (email[i]) {
            case 'a': case 'e': case 'i': case 'o': case 'u':
                score += 1;
                break;
            case '_': case '.':
                score += 1;
                break;
            case '+': case '-':
                score -= 1;
                break;
            default:
                score -= 2;
                break;
        }
    }
    if (score > 0) return 1;
    return 0;
}

int main() {
    int sockfd, newsockfd, portno, clilen;
    struct sockaddr_in serv_addr, cli_addr;
    char buffer[MAX_LINE];
    char *email, *token;

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    bzero((char *) &serv_addr, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = htons(PORT);

    bind(sockfd, (struct sockaddr *) &serv_addr, sizeof(serv_addr));

    listen(sockfd, 5);
    clilen = sizeof(cli_addr);

    while (1) {
        newsockfd = accept(sockfd, (struct sockaddr *) &cli_addr, (socklen_t*) &clilen);
        bzero(buffer, MAX_LINE);

        read(newsockfd, buffer, MAX_LINE);

        email = strtok(buffer, ": ");
        if (email != NULL) {
            token = strtok(NULL, ": ");
            if (token != NULL && is_spam(email)) {
                write(newsockfd, "SPAM\n", 5);
            } else {
                write(newsockfd, "HAM\n", 4);
            }
        }

        close(newsockfd);
    }

    close(sockfd);
    return 0;
}

