{
    float input, output;
    int fromUnit, toUnit;

    printf("Welcome to the Temperature Converter\nPlease enter the input value: ");
    scanf("%f", &input);
    printf("Please select the input unit:\n1.Celsius\n2.Fahrenheit\n3.Kelvin\n");
    scanf("%d", &fromUnit);
