        case 1: //already in Celsius
            break;

        case 2: //Fahrenheit to Celsius
            input = (input - 32) * 5/9;
            break;

        case 3: //Kelvin to Celsius
            input -= 273.15;
            break;

        default:
            printf("Invalid input unit! Please try again\n");
            temperatureConverter();
            return;
