#include <string.h>

void generate_qrcode(char* data)
{
    int i, j, k, l, size = 256;
    int** mat = (int**)malloc(size * sizeof(int*));
    for(i = 0; i < size; i++)
    {
        mat[i] = (int*)malloc(size * sizeof(int));
    }

    // Data encoding
    for(i = 0; data[i] != '\0'; i++)
    {
        int bit_count = 0;
        int n = data[i] - 32;
        for(j = 0; j < 6; j++)
        {
            mat[n][j] = 1;
            bit_count++;
        }
        if(bit_count % 2 == 1)
        {
            mat[n][6] = 1;
        }
    }

    // Error correction
    for(i = 0; i < size; i++)
    {
        for(j = 0; j < size; j++)
        {
            int count = 0;
            for(k = 0; k < size; k++)
            {
                if(mat[k][j] == 1)
                {
                    count++;
                }
            }
            if(count < 3)
            {
                mat[i][j] = 1;
            }
        }
    }

    // Module placement
    for(i = 0; i < size; i++)
    {
        for(j = 0; j < size; j++)
        {
            if(mat[i][j] == 1)
            {
                printf("X ");
            }
            else
            {
                printf(". ");
            }
        }
        printf("\n");
    }

    // Free memory
    for(i = 0; i < size; i++)
    {
        free(mat[i]);
    }
    free(mat);
}

