#include <time.h>
#include <unistd.h>

// Define the game's constants
#define GAME_NAME "Guess My Number"
#define MAX_TRIES 10
#define MIN_NUM 1
#define MAX_NUM 100

// Define the game's functions
void game_start();
void game_end();
void game_play();
void game_play_again();

// Define the game's variables
int number;
int tries = 0;

// Start the game
int main() {
    game_start();
    return 0;
}

// Start the game
void game_start() {
    printf("Welcome to %s!\n", GAME_NAME);
    printf("I'm thinking of a number between %d and %d.\n", MIN_NUM, MAX_NUM);
    printf("You have %d tries to guess it.\n", MAX_TRIES);
    game_play();
}

// Play the game
void game_play() {
    int guess;
    while (tries < MAX_TRIES) {
        printf("Guess a number: ");
        scanf("%d", &guess);
        if (guess < number) {
            printf("Too low! Try again.\n");
        } else if (guess > number) {
            printf("Too high! Try again.\n");
        } else {
            printf("You got it right! The number was %d.\n", number);
            game_end();
            break;
        }
        tries++;
    }
    if (tries == MAX_TRIES) {
        printf("You ran out of tries. The number was %d.\n", number);
        game_end();
    }
}

// End the game
void game_end() {
    printf("Do you want to play again? (y/n): ");
    char answer;
    scanf("%c", &answer);
    if (answer == 'y') {
        number = rand() % (MAX_NUM - MIN_NUM + 1) + MIN_NUM;
        tries = 0;
        game_play();
    } else {
        printf("Goodbye!\n");
        exit(0);
    }
}

