#include <stdio.h>
#include <stdlib.h>

#define BOARD_SIZE 100
#define ALIVE 1
#define DEAD 0

typedef struct {
    int cells[BOARD_SIZE][BOARD_SIZE];
} board;

void print_board(board *b) {
    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (b->cells[i][j])
                printf("%d ", 1);
            else
                printf("  ");
        }
        printf("\n");
    }
    printf("\n");
}

void set_cell(board *b, int i, int j, int state) {
    b->cells[i][j] = state;
}

int is_alive(board *b, int i, int j) {
    return b->cells[i][j];
}

void next_generation(board *b) {
    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            int neighbors = 0;
            if (i > 0)
                neighbors += is_alive(b, i - 1, j);
            if (i < BOARD_SIZE - 1)
                neighbors += is_alive(b, i + 1, j);
            if (j > 0)
                neighbors += is_alive(b, i, j - 1);
            if (j < BOARD_SIZE - 1)
                neighbors += is_alive(b, i, j + 1);
            if (neighbors == 2 || neighbors == 3) {
                set_cell(b, i, j, ALIVE);
            } else {
                set_cell(b, i, j, DEAD);
            }
        }
    }
}

int main() {
    board b;
    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            set_cell(&b, i, j, DEAD);
        }
    }
    print_board(&b);
    next_generation(&b);
    print_board(&b);
    return 0;
}

