#define HAND_SIZE 5
#define POT_SIZE 0

// Global variables
int deck[DECK_SIZE];
int hand[HAND_SIZE];
int pot;
int player_turn;
int winner;

// Function to shuffle the deck
void shuffle_deck() {
  int i, j, temp;
  for (i = 0; i < DECK_SIZE; i++) {
    for (j = i + 1; j < DECK_SIZE; j++) {
      temp = deck[i];
      deck[i] = deck[j];
      deck[j] = temp;
    }
  }
}

// Function to deal cards
void deal_cards() {
  int i, j;
  for (i = 0; i < HAND_SIZE; i++) {
    for (j = 0; j < DECK_SIZE; j++) {
      if (deck[j] != 0) {
        hand[i] = deck[j];
        deck[j] = 0;
        break;
      }
    }
  }
}

// Function to evaluate hands
int evaluate_hands() {
  int i, j;
  for (i = 0; i < HAND_SIZE; i++) {
    for (j = 0; j < HAND_SIZE; j++) {
      if (hand[i] == hand[j]) {
        return -1;
      }
    }
  }
  return 0;
}

// Function to determine the winner
int determine_winner() {
  int i, j;
  for (i = 0; i < HAND_SIZE; i++) {
    for (j = 0; j < HAND_SIZE; j++) {
      if (hand[i] > hand[j]) {
        return i;
      }
    }
  }
  return -1;
}

// Main game loop
int main() {
  srand(time(NULL));
  shuffle_deck();
  deal_cards();
  pot = 0;
  player_turn = 0;
  winner = -1;

  while (1) {
    if (player_turn == HAND_SIZE) {
      player_turn = 0;
