float TinhTongCacSoDuong(float a[][MAX], int dong, int cot)
{
    float tong = 0;

    int n = dong * cot; // Tổng số lượng phần tử của mảng
    for(int i = 0; i < n; i++)
    {
        if(a[i / cot][i % cot] > 0)
        {
            tong += a[i / cot][i % cot];
        }
    }
    return tong;
}
