void insertionSort(int table[], int size) {
    int key, j;
    for (int i = 1; i < size; i++) {
        key = table[i];
        j = i - 1;
        while (j >= 0 && table[j] > key) {
            table[j + 1] = table[j];
            j--;
        }
        table[j + 1] = key;
    }
}

