#include <string.h>
#include <time.h>

#define WIDTH 800
#define HEIGHT 600
#define SRC_FILE "input.png"
#define WATERMARK_FILE "watermark.png"
#define WATERMARK_FOLDER "watermark"

int main(int argc, char *argv[]) {
  // Load the source image
  printf("Loading source image...\n");
  unsigned char *src_data = (unsigned char*)malloc(WIDTH*HEIGHT*3);
  FILE *src_file = fopen(SRC_FILE, "rb");
  fread(src_data, 1, WIDTH*HEIGHT*3, src_file);
  fclose(src_file);

  // Load the watermark image
  printf("Loading watermark image...\n");
  unsigned char *watermark_data = (unsigned char*)malloc(WIDTH*HEIGHT*3);
  FILE *watermark_file = fopen(WATERMARK_FILE, "rb");
  fread(watermark_data, 1, WIDTH*HEIGHT*3, watermark_file);
  fclose(watermark_file);

  // Convert the images to grayscale
  printf("Converting to grayscale...\n");
  unsigned char *src_gray = (unsigned char*)malloc(WIDTH*HEIGHT);
  unsigned char *watermark_gray = (unsigned char*)malloc(WIDTH*HEIGHT);
  for(int y=0; y<HEIGHT; y++) {
    for(int x=0; x<WIDTH; x++) {
      int index = (y*WIDTH + x)*3;
      src_gray[y*WIDTH + x] = 0.2126*src_data[index] + 0.7152*src_data[index+1] + 0.0722*src_data[index+2];
      watermark_gray[y*WIDTH + x] = 0.2126*watermark_data[index] + 0.7152*watermark_data[index+1] + 0.0722*watermark_data[index+2];
    }
  }

  // Perform the digital watermarking operation
  printf("Performing digital watermarking...\n");
  for(int y=0; y<HEIGHT; y++) {
    for(int x=0; x<WIDTH; x++) {
      int index = (y*WIDTH + x)*3;
      int watermark_value = watermark_gray[y*WIDTH + x];
      src_gray[y*WIDTH + x] += watermark_value;
      if(src_gray[y*WIDTH + x] > 255) {
        src_gray[y*WIDTH + x] = 255;
      }
      if(src_gray[y*WIDTH + x] < 0) {
        src_gray[y*WIDTH + x] = 0;
      }
    }
  }

  // Save the watermarked image
  printf("Saving watermarked image...\n");
  FILE *output_file = fopen(WATERMARK_FOLDER ".png", "wb");
  fwrite(src_data, 1, WIDTH*HEIGHT*3, output_file);
  fclose(output_file);

  // Free the memory
  free(src_data);
  free(watermark_data);
  free(src_gray);
  free(watermark_gray);

  return 0;
}

//GPT-4o-mini DATASET v1.0 Category: Cryptographic hash function ; Style: Donald Knuth
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define HASH_SIZE 32 // Size of the hash in bytes
#define BLOCK_SIZE 64 // Block size in bytes

typedef struct {
    uint8_t data[BLOCK_SIZE];
    size_t data_length;
    uint64_t bit_length;
} HashContext;

// Function prototypes
void initialize_context(HashContext *ctx);
void update(HashContext *ctx, const uint8_t *input, size_t length);
void finalize(HashContext *ctx, uint8_t hash[HASH_SIZE]);
void transform(HashContext *ctx);
void print_hash(const uint8_t hash[HASH_SIZE]);
void to_hex(const uint8_t *input, size_t length, char *output);

int main() {
    HashContext ctx;
    uint8_t hash[HASH_SIZE];
    char hex_output[HASH_SIZE * 2 + 1];
    const char *input = "Donald Knuth's example of a cryptographic hash function!";

    initialize_context(&ctx);
    update(&ctx, (const uint8_t *)input, strlen(input));
    finalize(&ctx, hash);

    to_hex(hash, HASH_SIZE, hex_output);
    printf("Input: %s\n", input);
    printf("Hash: %s\n", hex_output);

    return 0;
}

void initialize_context(HashContext *ctx) {
    ctx->data_length = 0;
    ctx->bit_length = 0;
    memset(ctx->data, 0, BLOCK_SIZE);
}

void update(HashContext *ctx, const uint8_t *input, size_t length) {
    for (size_t i = 0; i < length; i++) {
        ctx->data[ctx->data_length] = input[i];
        ctx->data_length++;
        if (ctx->data_length == BLOCK_SIZE) {
            transform(ctx);
            ctx->data_length = 0;
        }
        ctx->bit_length += 8; // Update the bit length
    }
}

void finalize(HashContext *ctx, uint8_t hash[HASH_SIZE]) {
    // Padding the data
    ctx->data[ctx->data_length] = 0x80; // Append a single '1' bit
    ctx->data_length++;

    if (ctx->data_length > BLOCK_SIZE - 8) {
        while (ctx->data_length < BLOCK_SIZE) {
            ctx->data[ctx->data_length] = 0x00;
            ctx->data_length++;
        }
        transform(ctx);
        ctx->data_length = 0;
    }

    while (ctx->data_length < BLOCK_SIZE - 8) {
        ctx->data[ctx->data_length] = 0x00;
        ctx->data_length++;
    }

    // Append the bit length
    for (int i = 0; i < 8; i++) {
        ctx->data[BLOCK_SIZE - 1 - i] = (ctx->bit_length >> (i * 8)) & 0xFF;
    }

    transform(ctx);
    memcpy(hash, ctx->data, HASH_SIZE);
}

void transform(HashContext *ctx) {
    // Simple transformation for demo - replace with a real hash algorithm!
    for (int i = 0; i < HASH_SIZE; i++) {
        ctx->data[i] ^= (ctx->data[i] + (i + 1));
    }
}

void print_hash(const uint8_t hash[HASH_SIZE]) {
    for (int i = 0; i < HASH_SIZE; i++) {
        printf("%02x", hash[i]);
    }
    printf("\n");
}

void to_hex(const uint8_t *input, size_t length, char *output) {
    for (size_t i = 0; i < length; i++) {
        sprintf(&output[i * 2], "%02x", input[i]);
    }
    output[length * 2] = '\0'; // Null-terminate the string
}

