#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <ctype.h>
#include <time.h>
#define MAX_LINE_LENGTH 1024
#define MAX_ERROR_COUNT 100

typedef enum {
    ERROR,
    WARNING,
    INFORMATION
} log_level_t;

struct log_entry {
    log_level_t level;
    char timestamp[20];
    char message[MAX_LINE_LENGTH];
};

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <log_file>\n", argv[0]);
        return 1;
    }

    FILE *log_file = fopen(argv[1], "r");
    if (!log_file) {
        perror("Failed to open log file");
        return 2;
    }

    struct log_entry log_entries[MAX_ERROR_COUNT];
    int error_count = 0;
    int warning_count = 0;
    int information_count = 0;

    while (fgets(log_entries[error_count].message, MAX_LINE_LENGTH, log_file) != NULL) {
        log_entries[error_count].level = ERROR;
        error_count++;

        if (strstr(log_entries[error_count].message, "Warning:")) {
            log_entries[error_count].level = WARNING;
        } else if (strstr(log_entries[error_count].message, "Information:")) {
            log_entries[error_count].level = INFORMATION;
        }

        if (error_count >= MAX_ERROR_COUNT) {
            break;
        }
    }

    int i;
    for (i = 0; i < error_count; i++) {
        if (strcmp(log_entries[i].message, "Error:") == 0) {
            error_count++;
        }
    }

    for (i = 0; i < warning_count; i++) {
        if (strcmp(log_entries[i].message, "Warning:") == 0) {
            warning_count++;
        }
    }

    for (i = 0; i < information_count; i++) {
        if (strcmp(log_entries[i].message, "Information:") == 0) {
            information_count++;
        }
    }

    printf("Log Analysis Report\n");
    printf("------------------------\n");
    printf("Error Count: %d\n", error_count);
    printf("Warning Count: %d\n", warning_count);
    printf("Information Count: %d\n", information_count);

    for (i = 0; i < error_count; i++) {
        printf("Error %d: %s\n", i + 1, log_entries[i].message);
    }

    for (i = 0; i < warning_count; i++) {
        printf("Warning %d: %s\n", i + 1, log_entries[i].message);
    }

    for (i = 0; i < information_count; i++) {
        printf("Information %d: %s\n", i + 1, log_entries[i].message);
    }

    fclose(log_file);
    return 0;
}

#include <iostream>
using namespace std;
// by increasement order, T(n)=O(n^2)
void insertionSort(int* array, int length) {
	for (int j = 1; j < length; j++) {
		int key = array[j];
		int i = j - 1;
		while (i >= 0 && array[i] > key) {
			array[i + 1] = array[i];
			i--;
		}
		array[i + 1] = key;
	}
}
void printArray(int* array, int length) {
	for (int i = 0; i < length; i++) {
		cout << array[i] << " ";
	}
}

int main() {
	int array[] = { 3, 2, 1, 4, 6, 5 };
	insertionSort(array, sizeof(array) / sizeof(int));
	printArray(array, sizeof(array) / sizeof(int));
	return 0;
}

