#define MaxQueue 1000



struct Queue {

    int First;

    int Last;

    int Element[MaxQueue];

};





void Create(Queue& Q)

{

    Q.First = 0;

    Q.Last = -1;

}



bool Empty(Queue Q)

{

    return Q.First > Q.Last;

}



void Add(Queue& Q, int x)

{

    if (Q.Last == MaxQueue - 1)

        return;

    else {

        Q.Last++;

        Q.Element[Q.Last] = x;

    }

}



void Remove(Queue& Q)

{

    if (Empty(Q))

        return;

    Q.Element[Q.First] = false;

    Q.First++;

}



int Front(Queue& Q)

{

	return Q.Element[Q.First];

}



int Back(Queue& Q)

{

	return Q.Element[Q.Last];

}

