// Enthusiastic function name for our prime number generator!
bool is_prime(unsigned int num) {
    if (num <= 1) {
        return false;
    }
    for (unsigned int i = 2; i <= sqrt(num); i++) {
        if (num % i == 0) {
            return false;
        }
    }
    return true;
}

// Enthusiastic function name for our prime number sieve!
void sieve_of_eratosthenes(unsigned int limit, unsigned int *primes) {
    if (limit <= 2) {
        primes[0] = 2;
        return;
    }
    for (unsigned int i = 0; i < limit; i++) {
        primes[i] = i;
    }
    unsigned int n = 2;
    while (n * 2 < limit) {
        if (is_prime(n)) {
            for (unsigned int i = n * n; i < limit; i += n) {
                primes[i] = 0;
            }
        }
        n++;
    }
}

// Enthusiastic function name for our prime number finder using the sieve!
unsigned int find_nth_prime(unsigned int n) {
    unsigned int primes[10000];
    sieve_of_eratosthenes(10000, primes);
    unsigned int result = 0;
    for (unsigned int i = 0; i < 10000; i++) {
        if (primes[i] != 0 && n-- == 0) {
            result = primes[i];
            break;
        }
    }
    return result;
}

