    for(int i = 0;i < n; i++) {
        int command;
                int X;
                std::cin >> command >>X;
                if( command ==  1 ) {
                        root = Insert(root, X, 0);
                } else if (command == 2){
                        root = Remove(root, X + 1);
                } else break;
        }

        Delete(root);

        return 0;
}

