#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netinet/in.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <pthread.h>
#include <signal.h>

#define PORT 8080
#define MAX_CLIENTS 10
#define BUFFER_SIZE 1024

volatile sig_atomic_t running = 1;

void handle_signal(int signal) {
    running = 0;
}

void *client_handler(void *arg) {
    int client_socket = *(int *)arg;
    char buffer[BUFFER_SIZE];
    int bytes_read;

    // Block suspicious requests
    const char *block_keywords[] = {"malicious", "attack", "exploit", NULL};
    while ((bytes_read = read(client_socket, buffer, sizeof(buffer) - 1)) > 0) {
        buffer[bytes_read] = '\0'; // Null-terminate buffer
        printf("Received message: %s\n", buffer);

        // Check for blocked keywords
        for (int i = 0; block_keywords[i] != NULL; i++) {
            if (strstr(buffer, block_keywords[i]) != NULL) {
                printf("Blocked message containing: %s\n", block_keywords[i]);
                send(client_socket, "Message blocked due to security policy.\n", 40, 0);
                close(client_socket);
                return NULL;
            }
        }

        // Echo back the message for demonstration
        send(client_socket, buffer, bytes_read, 0);
    }

    close(client_socket);
    return NULL;
}

int main() {
    signal(SIGINT, handle_signal);

    int server_socket, client_socket;
    struct sockaddr_in server_addr, client_addr;
    socklen_t addr_len = sizeof(client_addr);
    pthread_t thread_id;

    // Create TCP socket
    if ((server_socket = socket(AF_INET, SOCK_STREAM, 0)) == -1) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Initialize socket structure
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    // Bind the socket
    if (bind(server_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) == -1) {
        perror("Bind failed");
        close(server_socket);
        exit(EXIT_FAILURE);
    }

    // Listen for incoming connections
    if (listen(server_socket, MAX_CLIENTS) == -1) {
        perror("Listen failed");
        close(server_socket);
        exit(EXIT_FAILURE);
    }

    printf("Firewall listening on port %d...\n", PORT);

    // Main loop to accept clients
    while (running) {
        client_socket = accept(server_socket, (struct sockaddr *)&client_addr, &addr_len);
        if (client_socket < 0) {
            if (running) {
                perror("Accept failed");
            }
            continue;
        }

        printf("Accepted a new client\n");

        // Create a new thread for the client
        if (pthread_create(&thread_id, NULL, client_handler, &client_socket) != 0) {
            perror("Thread creation failed");
            close(client_socket);
        }

        // Detach thread so that it cleans up when finished
        pthread_detach(thread_id);
    }

    // Clean up
    close(server_socket);
    printf("Shutting down the firewall.\n");
    return 0;
}

