#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_RECORDS 100
#define MAX_KEY_SIZE 20
#define MAX_VALUE_SIZE 100

typedef struct {
    char key[MAX_KEY_SIZE];
    char value[MAX_VALUE_SIZE];
} Record;

void add_record(Record *records, int *num_records, char *key, char *value) {
    if (*num_records >= MAX_RECORDS) {
        printf("Error: Too many records\n");
        return;
    }
    strcpy(records[*num_records].key, key);
    strcpy(records[*num_records].value, value);
    *num_records += 1;
}

void delete_record(Record *records, int *num_records, char *key) {
    int i;
    for (i = 0; i < *num_records; i++) {
        if (strcmp(records[i].key, key) == 0) {
            memcpy(&records[i], &records[i + 1], sizeof(Record) * (*num_records - i - 1));
            *num_records -= 1;
            break;
        }
    }
}

void update_record(Record *records, int *num_records, char *key, char *value) {
    int i;
    for (i = 0; i < *num_records; i++) {
        if (strcmp(records[i].key, key) == 0) {
            strcpy(records[i].value, value);
            break;
        }
    }
}

void search_record(Record *records, int num_records, char *key) {
    int i;
    for (i = 0; i < num_records; i++) {
        if (strcmp(records[i].key, key) == 0) {
            printf("Found record: %s %s\n", records[i].key, records[i].value);
            break;
        }
    }
    if (i == num_records) {
        printf("Record not found\n");
    }
}

int main() {
    Record records[MAX_RECORDS];
    int num_records = 0;

    add_record(records, &num_records, "name", "John");
    add_record(records, &num_records, "age", "25");
    add_record(records, &num_records, "city", "New York");

    search_record(records, num_records, "name");
    search_record(records, num_records, "age");
    search_record(records, num_records, "city");

    delete_record(records, &num_records, "name");

    search_record(records, num_records, "name");

    update_record(records, &num_records, "age", "30");

    search_record(records, num_records, "age");

    return 0;
}

