/* CPU Scheduling Algorithm: Synchronous
 *
 * This program demonstrates a synchronous CPU scheduling algorithm, which assigns
 * tasks to processors in a serial manner, without any preemption.
 */
#include <stdio.h>

// Define the number of processors and tasks
#define NUM_PROCS 4
#define NUM_TASKS 10

// Define the processor and task structs
typedef struct {
  int pid;
  int time;
} task_t;

typedef struct {
  int id;
  int busy;
} proc_t;

// Define the task and processor arrays
task_t tasks[NUM_TASKS];
proc_t procs[NUM_PROCS];

// Define the function to schedule a task
void schedule_task(task_t task, proc_t proc) {
  // Print the task and processor information
  printf("Scheduling task %d on processor %d\n", task.pid, proc.id);

  // Update the task and processor information
  task.time -= 1;
  proc.busy = 1;

  // If the task is done, update the processor information
  if (task.time == 0) {
    printf("Task %d finished\n", task.pid);
    proc.busy = 0;
  }
}

int main() {
  // Initialize the tasks and processors
  for (int i = 0; i < NUM_TASKS; i++) {
    tasks[i].pid = i;
    tasks[i].time = 10;
  }
  for (int i = 0; i < NUM_PROCS; i++) {
    procs[i].id = i;
    procs[i].busy = 0;
  }

  // Schedule the tasks
  for (int i = 0; i < NUM_TASKS; i++) {
    for (int j = 0; j < NUM_PROCS; j++) {
      if (procs[j].busy == 0) {
        schedule_task(tasks[i], procs[j]);
        break;
      }
    }
  }

  return 0;
}

