//GPT-4o-mini DATASET v1.0 Category: Building a SMTP Client ; Style: distributed
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define SMTP_HOST "smtp.example.com"
#define SMTP_PORT 587
#define USERNAME "your-email@example.com"
#define PASSWORD "your-email-password"

void check_response(int sockfd, const char *message) {
    char buffer[1024];
    read(sockfd, buffer, sizeof(buffer));
    printf("%s: %s", message, buffer);
}

void send_email(int sockfd, const char *from, const char *to, const char *subject, const char *body) {
    char command[1024];

    // HELO command
    sprintf(command, "HELO localhost\r\n");
    write(sockfd, command, strlen(command));
    check_response(sockfd, "HELO response");

    // AUTH LOGIN
    sprintf(command, "AUTH LOGIN\r\n");
    write(sockfd, command, strlen(command));
    check_response(sockfd, "AUTH LOGIN response");

    // Send Username
    sprintf(command, "%s\r\n", USERNAME);
    write(sockfd, command, strlen(command));
    check_response(sockfd, "Username response");

    // Send Password
    sprintf(command, "%s\r\n", PASSWORD);
    write(sockfd, command, strlen(command));
    check_response(sockfd, "Password response");

    // MAIL FROM
    sprintf(command, "MAIL FROM:<%s>\r\n", from);
    write(sockfd, command, strlen(command));
    check_response(sockfd, "MAIL FROM response");

    // RCPT TO
    sprintf(command, "RCPT TO:<%s>\r\n", to);
    write(sockfd, command, strlen(command));
    check_response(sockfd, "RCPT TO response");

    // DATA
    sprintf(command, "DATA\r\n");
    write(sockfd, command, strlen(command));
    check_response(sockfd, "DATA response");

    // Email Body
    sprintf(command, "Subject: %s\r\n\r\n%s\r\n.\r\n", subject, body);
    write(sockfd, command, strlen(command));
    check_response(sockfd, "Email send response");

    // QUIT command
    sprintf(command, "QUIT\r\n");
    write(sockfd, command, strlen(command));
    check_response(sockfd, "QUIT response");
}

int main() {
    struct sockaddr_in server_addr;
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SMTP_PORT);
    inet_pton(AF_INET, SMTP_HOST, &server_addr.sin_addr);

    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Connection to the SMTP server failed");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    // Sending an email
    send_email(sockfd, "your-email@example.com", "recipient@example.com", "Test Subject", "Hello, this is a test email!");

    close(sockfd);
    return 0;
}

