/*
Tìm BCNN  1 2 3 
vị trí i  0 1 2 
Khởi tạo BCNN = 3
i = 0: 3 % 1 == 0 -> BCNN = 3
i = 1: 3 % 2 != 0 -> BCNN = 3 + 3 = 6, i = -1

sau khi i++
i lúc này lại reset lại từ 0 và BCNN là 6
BCNN = 6
i = 0: 6 % 1 == 0 -> BCNN = 6
i = 1: 6 % 2 == 0 -> BCNN = 6
i = 2: 6 % 3 == 0 -> BCNN = 6

*/
int TimBoiChungNhoNhat(int a[], int n)
{
    int BoiSo = TimSoLonNhat(a, n); 
    for(int i = 0; i < n; i++)
    {
        if(BoiSo % a[i] != 0)
        {
            BoiSo += TimSoLonNhat(a, n);
            i = -1;     // reset lại i
        } 
    }
    return BoiSo;
}
int main()
{
    int n;
    int a[MAX];

    nhap(a, n);
    xuat(a, n);

    int Kq = TimBoiChungNhoNhat(a, n);
