#include "file.h"

File::File() {
	_path = "";
	_truncate = false;
	_append = false;
}

File::~File() {
	_file.flush();
	_file.close();
}

bool File::Initialize(string path) {
	return Initialize(path, FILE_OPEN_MODE_READ);
}

bool File::Initialize(string path, FILE_OPEN_MODE mode) {
	_path = path;
	ios_base::openmode openMode = ios_base::binary;
	switch (mode) {
		case FILE_OPEN_MODE_READ:
		{
			openMode |= ios_base::in;
			break;
		}
		case FILE_OPEN_MODE_TRUNCATE:
		{
			openMode |= ios_base::in;
			openMode |= ios_base::out;
			openMode |= ios_base::trunc;
			break;
		}
		case FILE_OPEN_MODE_APPEND:
		{
			openMode |= ios_base::in;
			openMode |= ios_base::out;
			if (fileExists(_path))
				openMode |= ios_base::app;
			else
				openMode |= ios_base::trunc;
			break;
		}
		default:
		{
			return false;
		}
	}

	_file.open(STR(_path), openMode);
	if (_file.fail()) {
		return false;
	}

	if (!SeekEnd())
		return false;

	_size = _file.tellg();

	if (!SeekBegin())
		return false;

	return true;
}

void File::Close() {
	_file.flush();
	_file.close();
}

uint64_t File::Size() {
	return _size;
}

uint64_t File::Cursor() {
	return (uint64_t) _file.tellg();
}

bool File::IsEOF() {
	return _file.eof();
}

string File::GetPath() {
	return _path;
}

bool File::Failed() {
	return _file.fail();
}

bool File::IsOpen() {
	return _file.is_open();
}

bool File::SeekBegin() {
	_file.seekg(0, ios_base::beg);
	if (_file.fail()) {
		return false;
	}
	return true;
}

bool File::SeekEnd() {
	_file.seekg(0, ios_base::end);
	if (_file.fail()) {
		return false;
	}
	return true;
}

bool File::SeekAhead(int64_t count) {
	if (count < 0) {
		return false;
	}

	if (count + Cursor() > _size) {
		return false;
	}

	_file.seekg(count, ios_base::cur);
	if (_file.fail()) {
		return false;
	}
	return true;
}

bool File::SeekBehind(int64_t count) {
	if (count < 0) {
		return false;
	}

	if (Cursor() < (uint64_t) count) {
		return false;
	}

	_file.seekg((-1) * count, ios_base::cur);
	if (_file.fail()) {
		return false;
	}
	return true;
}

bool File::SeekTo(uint64_t position) {
	if (_size < position) {
		return false;
	}

	_file.seekg(position, ios_base::beg);
	if (_file.fail()) {
		return false;
	}

	return true;
}

