//MISTRAL-7B DATASET v1.0 Category: Text processing ; Style: real-life
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdbool.h>

#define MAX_LINE_LENGTH 1024
#define NUM_STOP_WORDS 13

char *stop_words[NUM_STOP_WORDS] = {
    "a", "an", "and", "are", "as", "at", "be", "but", "by", "for", "from", "how", "in",
    "is", "it", "its", "of", "on", "or", "such", "that", "the", "their", "this", "to", "was",
    "were", "what", "when", "where", "which", "who", "whom", "why", "will", "with"
};

bool is_stop_word(const char *word) {
    for (int i = 0; i < NUM_STOP_WORDS; ++i) {
        size_t len = strlen(stop_words[i]);
        if (len > strlen(word)) continue;
        if (strncmp(word, stop_words[i], len) == 0 && isalpha(word[len])) {
            return true;
        }
    }
    return false;
}

void process_line(char *line) {
    char *token = strtok(line, " ");
    FILE *output_file = fopen("output.txt", "a");

    while (token != NULL) {
        if (!is_stop_word(token)) {
            fprintf(output_file, "%s ", token);
        }
        token = strtok(NULL, " ");
    }

    fputs("\n", output_file);
    fclose(output_file);
}

int main() {
    FILE *input_file = fopen("input.txt", "r");

    if (input_file == NULL) {
        perror("Error opening input file");
        return 1;
    }

    char line[MAX_LINE_LENGTH];

    while (fgets(line, MAX_LINE_LENGTH, input_file) != NULL) {
        process_line(line);
    }

    fclose(input_file);

    return 0;
}

