#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1000
#define MAX_WORDS 1000

typedef struct {
    char* word;
    int frequency;
} WordFrequency;

int compareWords(const void* a, const void* b) {
    WordFrequency* wordA = (WordFrequency*)a;
    WordFrequency* wordB = (WordFrequency*)b;

    return strcmp(wordA->word, wordB->word);
}

int main() {
    FILE* inputFile;
    char line[MAX_LINE_LENGTH];
    char* words[MAX_WORDS];
    int numWords;
    WordFrequency* wordFrequencies;
    int i;

    inputFile = fopen("input.txt", "r");
    if (inputFile == NULL) {
        printf("Error: Could not open input file.\n");
        exit(1);
    }

    wordFrequencies = calloc(MAX_WORDS, sizeof(WordFrequency));

    while (fgets(line, MAX_LINE_LENGTH, inputFile)!= NULL) {
        numWords = 0;
        words[numWords] = strtok(line, " ");
        while (words[numWords]!= NULL) {
            numWords++;
            words[numWords] = strtok(NULL, " ");
        }

        // Sort the words alphabetically
        qsort(words, numWords, sizeof(char*), compareWords);

        // Update the word frequencies
        for (i = 0; i < numWords; i++) {
            WordFrequency* word = wordFrequencies + i;

            while (word->word!= NULL) {
                if (strcmp(word->word, words[i]) == 0) {
                    word->frequency++;
                    break;
                }
                word++;
            }
        }
    }

    fclose(inputFile);

    // Sort the word frequencies by frequency
    qsort(wordFrequencies, MAX_WORDS, sizeof(WordFrequency), compareWords);

    // Print the word frequencies
    for (i = 0; i < MAX_WORDS; i++) {
        if (wordFrequencies[i].word!= NULL) {
            printf("%s: %d\n", wordFrequencies[i].word, wordFrequencies[i].frequency);
        }
    }

    return 0;
}

