    printf("Connected to %s\n", hostname);

    while (1)
    {
        if (recvfrom(sockfd, buffer, BUF_SIZE, 0, NULL, NULL) < 0)
        {
            perror("recvfrom");
            break;
        }

        printf("Received: %s\n", buffer);
    }

    return 0;
}

//GPT-4o-mini DATASET v1.0 Category: HTML beautifier ; Style: unmistakable
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024
#define MAX_STACK_SIZE 100

typedef struct {
    char *items[MAX_STACK_SIZE];
    int top;
} Stack;

void initStack(Stack *s) {
    s->top = -1;
}

int isFull(Stack *s) {
    return s->top == MAX_STACK_SIZE - 1;
}

int isEmpty(Stack *s) {
    return s->top == -1;
}

void push(Stack *s, char *item) {
    if (!isFull(s)) {
        s->items[++(s->top)] = item;
    }
}

char *pop(Stack *s) {
    if (!isEmpty(s)) {
        return s->items[(s->top)--];
    }
    return NULL;
}

char *peek(Stack *s) {
    if (!isEmpty(s)) {
        return s->items[s->top];
    }
    return NULL;
}

int isEndTag(char *tag) {
    return tag[0] == '/';
}

int isSelfClosingTag(char *tag) {
    return strcmp(tag, "br") == 0 || strcmp(tag, "img") == 0 || 
           strcmp(tag, "hr") == 0 || strcmp(tag, "input") == 0 || 
           strcmp(tag, "meta") == 0 || strcmp(tag, "link") == 0;
}

void formatLine(char *line, Stack *stack, FILE *output) {
    char *pos = line;
    int indentLevel = 0;

    while (*pos != '\0') {
        char *start = strchr(pos, '<');
        if (start == NULL) {
            fputs(pos, output);
            break;
        }

        // Print text content before the tag
        if (start > pos) {
            for (int i = 0; i < indentLevel; i++) fputc('\t', output);
            fwrite(pos, 1, start - pos, output);
        }

        char *end = strchr(start, '>');
        if (end == NULL) break;

        *end = '\0';
        pos = end + 1;

        // Print the tag
        if (isEndTag(start + 1)) {
            indentLevel--;
            if (indentLevel < 0) indentLevel = 0; // Prevent negative indent level
        } else {
            for (int i = 0; i < indentLevel; i++) fputc('\t', output);
            fputs(start, output);
            if (!isSelfClosingTag(start + 1)) {
                push(stack, start + 1);
                indentLevel++;
            }
        }

        fputc('\n', output);
    }
}

void beautifyHTML(const char *inputFile, const char *outputFile) {
    FILE *input = fopen(inputFile, "r");
    if (input == NULL) {
        fprintf(stderr, "Could not open file %s for reading\n", inputFile);
        return;
    }

    FILE *output = fopen(outputFile, "w");
    if (output == NULL) {
        fprintf(stderr, "Could not open file %s for writing\n", outputFile);
        fclose(input);
        return;
    }

    Stack stack;
    initStack(&stack);
    char line[MAX_LINE_LENGTH];

    while (fgets(line, sizeof(line), input)) {
        formatLine(line, &stack, output);
    }

    fclose(input);
    fclose(output);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input HTML file> <output HTML file>\n", argv[0]);
        return 1;
    }

    beautifyHTML(argv[1], argv[2]);
    printf("HTML beautification complete. Output written to %s\n", argv[2]);

    return 0;
}

