		}
	}

	// Finds the largest vertical product:
	for (int row=0; row <= (N-n); row++){
		for (int col=0; col <= (N-1); col++){
			int temp = 1;
			for (int i=row, count=0; count<n; i++, count++){
				temp = temp * arr[i][col];
			}
			if (temp > product){
				product = temp;
			}
		}
	}
