#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure to store data points
typedef struct {
    int id;
    char name[30];
    int age;
    char gender;
} Person;

// Function to print the data points
void print_data(Person *data, int n) {
    for (int i = 0; i < n; i++) {
        printf("ID: %d\tName: %s\tAge: %d\tGender: %c\n", data[i].id, data[i].name, data[i].age, data[i].gender);
    }
}

// Function to find the mean of the age of the data points
double find_mean(Person *data, int n) {
    double sum = 0;
    for (int i = 0; i < n; i++) {
        sum += data[i].age;
    }
    return sum / n;
}

// Function to find the standard deviation of the age of the data points
double find_std_dev(Person *data, int n) {
    double mean = find_mean(data, n);
    double sum = 0;
    for (int i = 0; i < n; i++) {
        sum += (data[i].age - mean) * (data[i].age - mean);
    }
    return sqrt(sum / (n - 1));
}

// Function to find the correlation between the age and gender of the data points
double find_correlation(Person *data, int n) {
    double age_mean = find_mean(data, n);
    double gender_mean = find_mean(data, n);
    double age_std_dev = find_std_dev(data, n);
    double gender_std_dev = find_std_dev(data, n);
    double covariance = 0;
    for (int i = 0; i < n; i++) {
        covariance += (data[i].age - age_mean) * (data[i].gender - gender_mean);
    }
    return covariance / (age_std_dev * gender_std_dev);
}

int main() {
    // Declare the data points
    Person data[5] = {
        {1, "John", 25, 'M'},
        {2, "Jane", 30, 'F'},
        {3, "Bob", 35, 'M'},
        {4, "Alice", 28, 'F'},
        {5, "Eve", 40, 'F'}
    };

    // Print the data points
    print_data(data, 5);

    // Find the mean of the age
    double mean = find_mean(data, 5);
    printf("Mean of age: %lf\n", mean);

    // Find the standard deviation of the age
    double std_dev = find_std_dev(data, 5);
    printf("Standard deviation of age: %lf\n", std_dev);

    // Find the correlation between the age and gender
    double correlation = find_correlation(data, 5);
    printf("Correlation between age and gender: %lf\n", correlation);

    return 0;
}

