}

/**
 * Moves the player one step in the specified direction.
 * @param current the player's current position
 * @param direction the direction to move in
 * @return the player's new position after the move
 */
Position move(Position current, int direction) {
    switch (direction) {
    case 0: // Up
        current.y--;
        break;
    case 1: // Down
        current.y++;
        break;
    case 2: // Left
        current.x--;
        break;
    case 3: // Right
        current.x++;
        break;
    default: // Should never happen
        exit(1);
    }
    return current;
}

/**
 * Determines whether the specified move is valid or not.
 * @param current the player's current position
 * @param direction the direction to move in
 * @return 1 if the move is valid, 0 otherwise
 */
int is_valid_move(Position current, int direction) {
    switch (direction) {
    case 0: // Up
        return current.y > 0;
    case 1: // Down
        return current.y < GRID_SIZE - 1;
    case 2: // Left
        return current.x > 0;
    case 3: // Right
        return current.x < GRID_SIZE - 1;
    default: // Should never happen
        return 0;
    }
}

/**
 * Returns a random direction to move in.
 * @return a random direction (0 = up, 1 = down, 2 = left, 3 = right)
 */
int get_random_direction(void) {
    return rand() % 4;
}

//MISTRAL-7B DATASET v1.0 Category: Hexadecimal Converter ; Style: scalable
#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <string.h>

#define MAX_LENGTH 50

void hex_to_bin(unsigned char hex, char bin[3]) {
    unsigned char mask = 0x80;
    int i;

    for (i = 0; i < 3; i++) {
        bin[i] = '0';
        if (hex & mask)
            bin[i] = '1';
        mask >>= 1;
    }
}

void hex_to_decimal(unsigned char hex, unsigned char *decimal) {
    *decimal = hex & 0x0F;
    if (*decimal > 9)
        *decimal += 0x30;
    hex >>= 4;
    *decimal <<= 4;
    *decimal += hex & 0x0F;
    if (*decimal > 9)
        *decimal += 0x30;
}

void bin_to_hex(char bin[3], unsigned char *hex) {
    unsigned char nibble1, nibble2;

    sscanf(bin, "%1s%1s", &bin[0], &bin[1]);

    nibble1 = bin[0] == '1' ? 0x01 : bin[0] == '0' ? 0x00 : bin[0] - 'A' + 0x0A;
    nibble2 = bin[1] == '1' ? 0x01 : bin[1] == '0' ? 0x00 : bin[1] - 'A' + 0x0A;

    *hex = (nibble1 << 4) | nibble2;
}

void print_hex(unsigned char hex) {
    char bin[3];
    unsigned char dec;

    hex_to_bin(hex, bin);
    printf("%s ", bin);

    hex_to_decimal(hex, &dec);
    printf("%X ", hex);
    printf("%d ", dec);
    printf("\n");
}

int main(int argc, char **argv) {
    unsigned char hex_input;
    int i;

    if (argc != 2) {
        printf("Usage: %s <hexadecimal number>\n", argv[0]);
        return 1;
    }

    for (i = 0; i < strlen(argv[1]); i++) {
        if (isxdigit(argv[1][i])) {
            hex_input = strtol(argv[1], NULL, 16);
            break;
        }
    }

    if (i != strlen(argv[1])) {
        printf("Invalid hexadecimal number.\n");
        return 1;
    }

    print_hex(hex_input);

    return 0;
}

