//FormAI DATASET v1.0 Category: Huffman Coding Implementation ; Style: light-weight
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAX_TREE_HT 100

typedef struct MinHeapNode {
    char data;
    unsigned freq;
    struct MinHeapNode *left, *right;
} MinHeapNode;

typedef struct MinHeap {
    unsigned size;
    unsigned capacity;
    MinHeapNode **array;
} MinHeap;

typedef struct HuffmanTree {
    char data;
    unsigned freq;
    struct HuffmanTree *left, *right;
} HuffmanTree;

MinHeapNode *newMinHeapNode(char data, unsigned freq) {
    MinHeapNode *newnode = (MinHeapNode *)malloc(sizeof(MinHeapNode));
    newnode->left = newnode->right = NULL;
    newnode->data = data;
    newnode->freq = freq;
    return newnode;
}

MinHeap *createMinHeap(unsigned capacity) {
    MinHeap *heap = (MinHeap *)malloc(sizeof(MinHeap));
    heap->size = 0;
    heap->capacity = capacity;
    heap->array = (MinHeapNode **)malloc(heap->capacity * sizeof(MinHeapNode *));
    return heap;
}

void swapMinHeapNodes(MinHeapNode **a, MinHeapNode **b) {
    MinHeapNode *temp = *a;
    *a = *b;
    *b = temp;
}

void minHeapify(MinHeap *heap, int idx) {
    int smallest = idx;
    int left = 2 * idx + 1;
    int right = 2 * idx + 2;
    if (left < heap->size && heap->array[left]->freq < heap->array[smallest]->freq)
        smallest = left;
    if (right < heap->size && heap->array[right]->freq < heap->array[smallest]->freq)
        smallest = right;
    if (smallest != idx) {
        swapMinHeapNodes(&heap->array[smallest], &heap->array[idx]);
        minHeapify(heap, smallest);
    }
}

bool isSizeOne(struct MinHeap *heap) {
    return heap->size == 1;
}

MinHeapNode *extractMin(MinHeap *heap) {
    MinHeapNode *temp = heap->array[0];
    heap->array[0] = heap->array[heap->size - 1];
    --heap->size;
    minHeapify(heap, 0);
    return temp;
}

void insertMinHeap(MinHeap *heap, MinHeapNode *node) {
    ++heap->size;
    int i = heap->size - 1;
    while (i && node->freq < heap->array[(i - 1) / 2]->freq) {
        heap->array[i] = heap->array[(i - 1) / 2];
        i = (i - 1) / 2;
    }
    heap->array[i] = node;
}

void buildMinHeap(MinHeap *heap) {
    int n = heap->size - 1;
    int i;
    for (i = (n - 1) / 2;i >= 0;--i) {
        minHeapify(heap, i);
    }
}

void printArr(int[],int);

int isLeaf(MinHeapNode *root) {
    return !(root->left) && !(root->right);
}

MinHeap *createAndBuildMinHeap(char data[],int freq[],int size) {
    MinHeap *heap = createMinHeap(size);
    for (int i = 0;i < size;++i) {
        heap->array[i] = newMinHeapNode(data[i], freq[i]);
    }
    heap->size = size;
    buildMinHeap(heap);
    return heap;
}

HuffmanTree *buildHuffmanTree(char data[],int freq[],int size) {
    HuffmanTree *left, *right, *top;
    MinHeap *heap = createAndBuildMinHeap(data, freq, size);
    while (!isSizeOne(heap)) {
        left = extractMin(heap);
        right = extractMin(heap);
        top = (HuffmanTree *)malloc(sizeof(HuffmanTree));
        top->data = '#';
        top->freq = left->freq + right->freq;
        top->left = left;
        top->right = right;
        insertMinHeap(heap, top);
    }
    return extractMin(heap);
}

void printHuffmanCodes(HuffmanTree *root, int arr[], int top) {
    if (root->left) {
        arr[top] = 0;
        printHuffmanCodes(root->left, arr, top + 1);
    }
    if (root->right) {
        arr[top] = 1;
        printHuffmanCodes(root->right, arr, top + 1);
    }
    if (isLeaf(root)) {
        printf("%c\t\t", root->data);
        printArr(arr, top);
    }
}

void printArr(int arr[], int n) {
    for (int i = 0;i < n;++i) {
        printf("%d", arr[i]);
    }
    printf("\n");
}

void HuffmanCodes(char data[],int freq[],int size) {
    HuffmanTree *root = buildHuffmanTree(data, freq, size);
    int arr[MAX_TREE_HT],top = 0;
    printf("Huffman Codes are:\n\n");
    printf("Symbol\t\tCode\n");
    printHuffmanCodes(root,arr,top);
}

int main() {
    char arr[] = {'A','B','C','D','E','F'};
    int freq[] = {5,9,12,13,16,45};
    int size = sizeof(arr) / sizeof(arr[0]);
    HuffmanCodes(arr, freq, size);
    return 0;
}

//Falcon2-11B DATASET v1.0 Category: Simple HTTP Proxy ; Style: real-life
#include <stdio.h>
#include <stdlib.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <getopt.h>
#include <sys/types.h>
#include <string.h>

#define PORT 8080

// Function to handle incoming requests
void start_proxy(int port) {
    // Create socket to listen for incoming connections
    int sockfd;
    struct sockaddr_in server;
    server.sin_family = AF_INET;
    server.sin_port = htons(port);
    server.sin_addr.s_addr = INADDR_ANY;
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "Error creating socket\n");
        exit(EXIT_FAILURE);
    }

    // Bind socket to port
    if (bind(sockfd, (struct sockaddr *)&server, sizeof(server)) < 0) {
        fprintf(stderr, "Error binding socket to port\n");
        exit(EXIT_FAILURE);
    }

    // Start listening for incoming connections
    listen(sockfd, 5);

    // Accept incoming connections
    int client_fd;
    struct sockaddr_in client;
    socklen_t client_len = sizeof(client);
    client_fd = accept(sockfd, (struct sockaddr *)&client, &client_len);
    if (client_fd < 0) {
        fprintf(stderr, "Error accepting connection\n");
        exit(EXIT_FAILURE);
    }

    // Spawn a new process for each connection
    pid_t pid;
    pid = fork();
    if (pid < 0) {
        fprintf(stderr, "Error forking process\n");
        exit(EXIT_FAILURE);
    }
    if (pid == 0) {
        // Close the parent socket
        close(sockfd);

        // Handle the proxy server logic for this connection
        char buffer[1024];
        int read_size = recv(client_fd, buffer, sizeof(buffer), 0);
        if (read_size < 0) {
            fprintf(stderr, "Error reading from client\n");
            exit(EXIT_FAILURE);
        }
        buffer[read_size] = '\0';
        printf("Client request: %s\n", buffer);

        // Connect to the server
        int server_fd;
        server_fd = socket(AF_INET, SOCK_STREAM, 0);
        if (server_fd < 0) {
            fprintf(stderr, "Error creating socket for server\n");
            exit(EXIT_FAILURE);
        }
        struct sockaddr_in server_addr;
        server_addr.sin_family = AF_INET;
        server_addr.sin_port = htons(8080);
        server_addr.sin_addr.s_addr = inet_addr("127.0.0.1");
        if (connect(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
            fprintf(stderr, "Error connecting to server\n");
            exit(EXIT_FAILURE);
        }

        // Forward the client request to the server
        int send_size = send(server_fd, buffer, read_size, 0);
        if (send_size < 0) {
            fprintf(stderr, "Error sending to server\n");
            exit(EXIT_FAILURE);
        }

        // Read the server response
        char server_response[1024];
        read_size = recv(server_fd, server_response, sizeof(server_response), 0);
        if (read_size < 0) {
            fprintf(stderr, "Error reading from server\n");
            exit(EXIT_FAILURE);
        }
        server_response[read_size] = '\0';
        printf("Server response: %s\n", server_response);

        // Send the server response back to the client
        send_size = send(client_fd, server_response, read_size, 0);
        if (send_size < 0) {
            fprintf(stderr, "Error sending to client\n");
            exit(EXIT_FAILURE);
        }

        // Close the client socket
        close(client_fd);
        exit(EXIT_SUCCESS);
    }

    // Close the parent socket
    close(sockfd);
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[]) {
    int port = PORT;
    static struct option long_options[] = {
        {"port", required_argument, NULL, 'p'},
        {NULL, 0, NULL, 0}
    };
    int option_index = 0;
    while (1) {
        int c = getopt_long(argc, argv, "p:", long_options, &option_index);
        if (c == -1) {
            break;
        }
        switch (c) {
            case 'p':
                port = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s -p <port>\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    start_proxy(port);

    return 0;
}

