vector <int> get_first_n_fibs( const int& N )
{
    vector <int> list_fibs;
    list_fibs.push_back( 1 );
    list_fibs.push_back( 1 );

    int two_behind = 1, one_behind = 1;

    for( int i = 2; i < N; i++ )
    {
        int tmp = one_behind;
        one_behind += two_behind;
        two_behind = tmp;

        list_fibs.push_back( one_behind );
    }

    return list_fibs;
}

