#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define WIDTH 640
#define HEIGHT 480

typedef struct {
    int x;
    int y;
    int color;
} Pixel;

typedef struct {
    Pixel pixels[WIDTH * HEIGHT];
} Image;

void load_image(Image *image, char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Error: Could not open file %s\n", filename);
        return;
    }

    int pixels_read = fread(image->pixels, sizeof(Pixel), WIDTH * HEIGHT, file);
    if (pixels_read != WIDTH * HEIGHT) {
        printf("Error: Could not read entire image\n");
        return;
    }

    fclose(file);
}

void draw_line(Image *image, int x1, int y1, int x2, int y2, int color) {
    int x = x1;
    int y = y1;
    while (x <= x2) {
        image->pixels[y * WIDTH + x].color = color;
        x++;
    }
}

void draw_circle(Image *image, int x, int y, int radius, int color) {
    int x1 = x - radius;
    int y1 = y - radius;
    int x2 = x + radius;
    int y2 = y + radius;

    for (int i = x1; i <= x2; i++) {
        for (int j = y1; j <= y2; j++) {
            image->pixels[j * WIDTH + i].color = color;
        }
    }
}

void draw_fill(Image *image, int x, int y, int width, int height, int color) {
    for (int i = x; i <= x + width; i++) {
        for (int j = y; j <= y + height; j++) {
            image->pixels[j * WIDTH + i].color = color;
        }
    }
}

void save_image(Image *image, char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        printf("Error: Could not open file %s\n", filename);
        return;
    }

    fwrite(image->pixels, sizeof(Pixel), WIDTH * HEIGHT, file);
    fclose(file);
}

int main() {
    Image image;
    load_image(&image, "example.bmp");

    // Draw some shapes
    draw_line(&image, 100, 100, 300, 300, 0x00ff0000);
    draw_circle(&image, 200, 200, 100, 0x0000ff00);
    draw_fill(&image, 300, 300, 100, 100, 0x000000ff);

    // Save the modified image
    save_image(&image, "example_modified.bmp");

    return 0;
}

//LLAMA2-13B DATASET v1.0 Category: Encryption ; Style: modular
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define BLOCK_SIZE 16
#define KEY_SIZE 128

// Structure to hold the encryption parameters
typedef struct {
    char *key;      // Encryption key (128 bits)
    int block_size; // Block size (16 bytes)
} enc_params_t;

// Function to initialize the encryption parameters
void init_enc_params(enc_params_t *params) {
    params->key = (char *)malloc(KEY_SIZE);
    params->block_size = BLOCK_SIZE;
}

// Function to free the encryption parameters
void free_enc_params(enc_params_t *params) {
    free(params->key);
}

// Function to encrypt a block of data
void encrypt_block(enc_params_t *params, char *data, int len) {
    int i, j;
    char temp[BLOCK_SIZE];

    // Create a temporary buffer to store the encrypted data
    for (i = 0; i < BLOCK_SIZE; i++) {
        temp[i] = data[i] ^ params->key[i % KEY_SIZE];
    }

    // Encrypt the data block
    for (j = 0; j < len; j += BLOCK_SIZE) {
        encrypt_block(data + j, temp, BLOCK_SIZE);
    }
}

// Function to decrypt a block of data
void decrypt_block(enc_params_t *params, char *data, int len) {
    int i, j;
    char temp[BLOCK_SIZE];

    // Create a temporary buffer to store the decrypted data
    for (i = 0; i < BLOCK_SIZE; i++) {
        temp[i] = data[i] ^ params->key[i % KEY_SIZE];
    }

    // Decrypt the data block
    for (j = 0; j < len; j += BLOCK_SIZE) {
        decrypt_block(data + j, temp, BLOCK_SIZE);
    }
}

int main() {
    // Initialize the encryption parameters
    enc_params_t params;
    init_enc_params(&params);

    // Generate a random encryption key
    for (int i = 0; i < KEY_SIZE; i++) {
        params.key[i] = rand() % 256;
    }

    // Encrypt a message
    char message[] = "Hello, world!";
    int message_len = strlen(message);
    encrypt_block(&params, message, message_len);

    // Decrypt the message
    char decrypted_message[message_len];
    decrypt_block(&params, decrypted_message, message_len);

    // Print the decrypted message
    printf("Decrypted message: %s\n", decrypted_message);

    // Free the encryption parameters
    free_enc_params(&params);

    return 0;
}

