// Structure to store planets
typedef struct planet {
    double x_pos;
    double y_pos;
    double z_pos;
    double velocity_x;
    double velocity_y;
    double velocity_z;
    double mass;
} Planet;

// Function to calculate gravitational force between two planets
double gravitational_force(double mass1, double mass2, double distance) {
    return ((mass1 * mass2) / (distance * distance));
}

// Function to calculate acceleration of a planet
double calculate_acceleration(double mass, double distance, double force) {
    return (force / mass);
}

// Function to update the position and velocity of a planet
void update_planet(Planet *p, Planet *q) {
    double distance = sqrt(pow(p->x_pos - q->x_pos, 2) + pow(p->y_pos - q->y_pos, 2) + pow(p->z_pos - q->z_pos, 2));
    double acceleration = calculate_acceleration(p->mass, distance, gravitational_force(p->mass, q->mass, distance));
    double velocity = sqrt(pow(p->velocity_x, 2) + pow(p->velocity_y, 2) + pow(p->velocity_z, 2));
    p->velocity_x += acceleration * cos(p->velocity_z) * velocity;
    p->velocity_y += acceleration * sin(p->velocity_z) * velocity;
    p->velocity_z += acceleration * sin(p->velocity_x) * velocity;
    p->x_pos += p->velocity_x * 1.0;
    p->y_pos += p->velocity_y * 1.0;
    p->z_pos += p->velocity_z * 1.0;
}

// Function to display the current positions and velocities of all planets
void display_planets(Planet *planets, int num_planets) {
    for (int i = 0; i < num_planets; i++) {
        printf("Planet %d:\n", i + 1);
