#include <stdlib.h>
#include <time.h>

#define MAX_CELLS 256

int main() {

  // Seed the random number generator
  srand(time(NULL));

  // Create a grid of cells
  int cells[MAX_CELLS] = {0};

  // Initialize the game of life
  initialize_game(cells);

  // Run the game of life for 10 generations
  for (int generation = 0; generation < 10; generation++) {
    update_game(cells);
  }

  // Print the final grid
  print_grid(cells);

  return 0;
}

void initialize_game(int *cells) {
  // Randomly activate some cells
  for (int i = 0; i < MAX_CELLS; i++) {
    cells[i] = rand() % 2;
  }
}

void update_game(int *cells) {
  // Calculate the number of neighbors for each cell
  for (int i = 0; i < MAX_CELLS; i++) {
    int num_neighbors = count_neighbors(cells, i);

    // Update the cell's state based on the number of neighbors
    if (cells[i] == 1 && num_neighbors < 2) {
      cells[i] = 0;
    } else if (cells[i] == 0 && num_neighbors == 3) {
      cells[i] = 1;
    }
  }
}

void print_grid(int *cells) {
  // Print the grid of cells
  for (int i = 0; i < MAX_CELLS; i++) {
    printf("%d ", cells[i]);
  }

  printf("\n");
}

int count_neighbors(int *cells, int index) {
  // Count the number of neighbors for a cell
  int num_neighbors = 0;

  // Iterate over the neighboring cells
  for (int i = index - 1; i <= index + 1; i++) {
    if (cells[i] == 1) {
      num_neighbors++;
    }
  }

  return num_neighbors;
}

