#include <stdio.h>
#include <stdlib.h>
#include <time.h>

int main()
{
    // Set the current time
    time_t now = time(NULL);

    // Print the current time
    printf("The current time is: %s", ctime(&now));

    // Set the time machine to go back 1 hour
    time_t then = now - 60 * 60;

    // Print the time machine settings
    printf("\nThe time machine is set to go back 1 hour.\n");

    // Go back in time
    time_travel(then);

    // Print the new current time
    printf("\nThe current time is now: %s", ctime(&now));

    return 0;
}

// Function to travel through time
void time_travel(time_t destination)
{
    // Set the time machine coordinates
    struct tm *tm = localtime(&destination);

    // Set the time machine flux capacitor
    tm->tm_year += 100;
    tm->tm_mon += 12;
    tm->tm_mday += 365;

    // Activate the time machine
    time_t result = mktime(tm);

    // Return to the present
    time_t present = time(NULL);

    // Print the time machine log
    printf("\nThe time machine has traveled to %s.\n", ctime(&result));

    // Reset the time machine
    time_t reset = present - (result - present);

    // Return to the present
    time(&present);

    // Print the time machine log
    printf("\nThe time machine has returned to the present.\n");
}

