#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_WORDS 100000
#define MAX_WORD_LENGTH 20

struct word {
    char word[MAX_WORD_LENGTH];
    int count;
};

void read_file(const char* filename, struct word* words) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: could not open file %s\n", filename);
        exit(1);
    }

    char word[MAX_WORD_LENGTH];
    char* token = strtok(NULL, " \t\n\r\f\v.,!?;:\"'()[]{}<>");
    while (token!= NULL) {
        int i = 0;
        while (isalpha(token[i]) && i < MAX_WORD_LENGTH - 1) {
            word[i] = tolower(token[i]);
            i++;
        }
        word[i] = '\0';

        struct word* match = NULL;
        for (int j = 0; j < MAX_WORDS; j++) {
            if (strcmp(words[j].word, word) == 0) {
                match = &words[j];
                break;
            }
        }

        if (match == NULL) {
            if (words->count >= MAX_WORDS) {
                printf("Error: too many unique words in file\n");
                exit(1);
            }
            strcpy(words[words->count].word, word);
            words[words->count].count = 1;
            words->count++;
        } else {
            match->count++;
        }

        token = strtok(NULL, " \t\n\r\f\v.,!?;:\"'()[]{}<>");
    }

    fclose(file);
}

void print_misspelled_words(struct word* words) {
    printf("Misspelled words:\n");
    for (int i = 0; i < MAX_WORDS; i++) {
        if (words[i].count == 0) {
            printf("%s\n", words[i].word);
        }
    }
}

int main(int argc, char* argv[]) {
    if (argc!= 2) {
        printf("Usage: %s filename\n", argv[0]);
        exit(1);
    }

    struct word words[MAX_WORDS];
    memset(words, 0, sizeof(words));

    read_file(argv[1], words);
    print_misspelled_words(words);

    return 0;
}

