//MISTRAL-7B DATASET v1.0 Category: Mortgage Calculator ; Style: modular
#include <stdio.h>
#include <stdlib.h>
#include <math.h>

typedef struct {
    double principal;
    double annual_interest_rate;
    int loan_term;
    int num_payments;
} mortgage;

void initialize_mortgage(mortgage *mortgage, double principal, double annual_interest_rate, int loan_term);
double calculate_monthly_payment(mortgage mortgage);
int total_payments(mortgage mortgage);
double remaining_balance(mortgage mortgage);

int main() {
    mortgage my_mortgage;
    double loan_amount = 250000.0;
    double interest_rate = 0.045;
    int loan_term_years = 30;

    initialize_mortgage(&my_mortgage, loan_amount, interest_rate, loan_term_years);

    printf("Monthly payment: $%.2f\n", calculate_monthly_payment(my_mortgage));
    printf("Total payments: $%.2f\n", total_payments(my_mortgage) * 12);
    printf("Remaining balance: $%.2f\n", remaining_balance(my_mortgage));

    return 0;
}

void initialize_mortgage(mortgage *mortgage, double principal, double annual_interest_rate, int loan_term) {
    mortgage->principal = principal;
    mortgage->annual_interest_rate = annual_interest_rate;
    mortgage->loan_term = loan_term;
    mortgage->num_payments = mortgage->loan_term * 12;
}

double calculate_monthly_payment(mortgage mortgage) {
    double monthly_rate = mortgage.annual_interest_rate / 12.0;
    double numerator = pow(1 + monthly_rate, mortgage.num_payments);
    double denominator = (pow(1 + monthly_rate, mortgage.num_payments) - 1) / (monthly_rate * pow(1 + monthly_rate, mortgage.num_payments));
    double monthly_payment = mortgage.principal * denominator;
    return monthly_payment;
}

int total_payments(mortgage mortgage) {
    return mortgage.num_payments;
}

double remaining_balance(mortgage mortgage) {
    double monthly_payment = calculate_monthly_payment(mortgage);
    double total_payments = mortgage.num_payments;
    double remaining_balance = mortgage.principal - (monthly_payment * total_payments);
    return remaining_balance;
}

