//GEMINI-pro DATASET v1.0 Category: Building a CSV Reader ; Style: Claude Shannon
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024

typedef struct {
  char **data;
  int num_rows;
  int num_cols;
} csv_data;

csv_data *read_csv(const char *filename) {
  FILE *fp = fopen(filename, "r");
  if (fp == NULL) {
    return NULL;
  }

  char line[MAX_LINE_LENGTH];
  int num_rows = 0;
  int num_cols = 0;
  while (fgets(line, MAX_LINE_LENGTH, fp)) {
    num_rows++;
    char *ptr = line;
    while (*ptr != '\0') {
      if (*ptr == ',') {
        num_cols++;
      }
      ptr++;
    }
  }

  fseek(fp, 0, SEEK_SET);

  csv_data *data = malloc(sizeof(csv_data));
  data->data = malloc(num_rows * num_cols * sizeof(char *));
  data->num_rows = num_rows;
  data->num_cols = num_cols;

  int row = 0;
  int col = 0;
  while (fgets(line, MAX_LINE_LENGTH, fp)) {
    char *ptr = line;
    while (*ptr != '\0') {
      if (*ptr == ',') {
        data->data[row * num_cols + col] = '\0';
        col++;
      } else {
        data->data[row * num_cols + col] = ptr;
      }
      ptr++;
    }
    data->data[row * num_cols + col] = '\0';
    row++;
    col = 0;
  }

  fclose(fp);

  return data;
}

void free_csv_data(csv_data *data) {
  free(data->data);
  free(data);
}

int main(int argc, char **argv) {
  if (argc != 2) {
    fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
    return 1;
  }

  csv_data *data = read_csv(argv[1]);
  if (data == NULL) {
    fprintf(stderr, "Error reading CSV file: %s\n", argv[1]);
    return 1;
  }

  for (int i = 0; i < data->num_rows; i++) {
    for (int j = 0; j < data->num_cols; j++) {
      printf("%s ", data->data[i * data->num_cols + j]);
    }
    printf("\n");
  }

  free_csv_data(data);

  return 0;
}

//MISTRAL-7B DATASET v1.0 Category: Sudoku solver ; Style: synchronous
#include <stdio.h>
#include <stdbool.h>
#include <stdlib.h>

#define SIZE 9

bool isValid(int board[SIZE][SIZE], int row, int col, int num) {
    for (int i = 0; i < SIZE; i++) {
        if (board[row][i] == num || board[i][col] == num)
            return false;
    }

    int startRow = row - row % 3, startCol = col - col % 3;
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            if (board[i + startRow][j + startCol] == num)
                return false;
        }
    }

    return true;
}

bool solveSudoku(int board[SIZE][SIZE], int row, int col) {
    if (row == SIZE)
        return true;

    if (col == SIZE) {
        row++;
        col = 0;
    }

    if (board[row][col] != 0) {
        return solveSudoku(board, row, col + 1);
    }

    for (int num = 1; num <= SIZE; num++) {
        if (isValid(board, row, col, num)) {
            board[row][col] = num;
            if (solveSudoku(board, row, col + 1))
                return true;
            board[row][col] = 0;
        }
    }

    return false;
}

int main() {
    int board[SIZE][SIZE] = {
        {5, 3, 0, 0, 7, 0, 0, 0, 0},
        {6, 0, 0, 1, 9, 5, 0, 0, 0},
        {0, 9, 8, 0, 0, 0, 0, 6, 0},
        {8, 0, 0, 0, 6, 0, 0, 0, 3},
        {4, 0, 0, 8, 0, 3, 0, 0, 1},
        {7, 0, 2, 0, 0, 0, 0, 0, 6},
        {0, 6, 0, 0, 2, 8, 0, 0, 0},
        {0, 0, 0, 4, 1, 9, 0, 5, 0},
        {0, 0, 5, 0, 8, 0, 0, 7, 9}
    };

    solveSudoku(board, 0, 0);

    for (int i = 0; i < SIZE; i++) {
        for (int j = 0; j < SIZE; j++) {
            printf("%d ", board[i][j]);
        }
        printf("\n");
    }

    return 0;
}

