void manipulate_string(char *str) {
    int i, j, k;
    char c, d;
    char *ptr;
    char str_copy[MAX_LENGTH];

    // Randomly shuffle the string characters
    for (i = 0; i < strlen(str); i++) {
        j = rand() % strlen(str);
        c = str[j];
        str[j] = str[i];
        str[i] = c;
    }

    // Reverse the string
    ptr = str;
    for (i = 0; i < strlen(str); i++) {
        d = *ptr;
        *ptr = *(ptr + strlen(str) - i - 1);
        *(ptr + strlen(str) - i - 1) = d;
        ptr++;
    }

    // Remove duplicates
    for (i = 0; i < strlen(str); i++) {
        if (str[i] == str[i + 1]) {
            str[i] = '\0';
            i++;
        }
    }

    // Add some random symbols
