#define MAX_NODES 50
#define NAME_LENGTH 30

typedef struct {
    char name[NAME_LENGTH];
    int alive;  // 1 if the node is functional, 0 otherwise
    int neighbors[MAX_NODES];  // Store indices of neighboring nodes
    int neighbor_count;         // Count of active neighbors
} Node;

Node network[MAX_NODES];
int node_count = 0;

void add_node(const char *name) {
    if (node_count < MAX_NODES) {
        strncpy(network[node_count].name, name, NAME_LENGTH);
        network[node_count].alive = 1;  // Node is functional
        network[node_count].neighbor_count = 0;
        node_count++;
    } else {
        printf("Network exhausted, cannot add more nodes!\n");
    }
}

void add_connection(int node1, int node2) {
    if (node1 >= 0 && node1 < node_count && 
        node2 >= 0 && node2 < node_count && 
        network[node1].alive && network[node2].alive) {

        network[node1].neighbors[network[node1].neighbor_count++] = node2;
        network[node2].neighbors[network[node2].neighbor_count++] = node1;
    }
}

void print_network() {
    printf("=== Post-Apocalyptic Network Topology ===\n");
    for (int i = 0; i < node_count; i++) {
        if (network[i].alive) {
            printf("Node: %s (Alive)\n", network[i].name);
            printf("  Connected to: ");
            for (int j = 0; j < network[i].neighbor_count; j++) {
                printf("%s ", network[network[i].neighbors[j]].name);
            }
            printf("\n");
        } else {
            printf("Node: %s (Dead)\n", network[i].name);
        }
    }
    printf("=========================================\n");
}

void take_damage(int node_index) {
    if (node_index >= 0 && node_index < node_count) {
        network[node_index].alive = 0;
    }
}

int main() {
    printf("=== Welcome to the Post-Apocalyptic Network Mapper ===\n");
    add_node("Central Command");
    add_node("Outpost Alpha");
    add_node("Outpost Beta");
    add_node("Interrogation Unit");
    add_node("Research Lab");

    add_connection(0, 1);
    add_connection(0, 2);
    add_connection(1, 3);
    add_connection(1, 4);
    add_connection(2, 4);

    // Print initial network
    print_network();

    printf("=== Taking damage in the network ===\n");
    take_damage(3);  // Interrogation Unit is now non-functional
    print_network();

    // Simulate more chaos in the network
    printf("=== More nodes fall to chaos ===\n");
    take_damage(1);  // Outpost Alpha is down
    print_network();

    printf("=== Survivors regrouping ===\n");
    take_damage(4); // Research Lab is down too
    print_network();

    printf("=== Final Network Status ===\n");
    print_network();

    printf("=== End of network analysis ===\n");
    return 0;
}

