#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the size of the hash output
#define HASH_SIZE 32 // 256 bits

// Function to perform a bitwise left rotation
unsigned int rotate_left(unsigned int value, int shift) {
    return (value << shift) | (value >> (32 - shift));
}

// A simple modular arithmetic-based hash function
void simple_hash(const char *input, unsigned char output[HASH_SIZE]) {
    unsigned int hash1 = 0x4F1D2D3B; // Initial hash value
    unsigned int hash2 = 0x8C5E19BD; // Second hash value
    int length = strlen(input);

    for (int i = 0; i < length; i++) {
        hash1 ^= (unsigned int)input[i]; // XOR with char value
        hash1 = rotate_left(hash1, 5); // Rotate left
        hash1 += hash2; // Add the second hash value

        hash2 += (hash1 * (unsigned int)input[i]); // Mix hash values
        hash2 = rotate_left(hash2, 7); // Another rotation
    }

    // Finalize the hashes into a 32-byte output
    for (int i = 0; i < HASH_SIZE; i++) {
        output[i] = (hash1 + hash2) & 0xFF; // Keep it as byte
        hash1 = rotate_left(hash1, 3); // Further mixing
        hash2 = rotate_left(hash2, 11); // Further mixing
    }
}

// Function to print hash in hexadecimal form
void print_hash(const unsigned char hash[HASH_SIZE]) {
    for (int i = 0; i < HASH_SIZE; i++) {
        printf("%02x", hash[i]);
    }
    printf("\n");
}

// Main function to demonstrate hash generation
int main() {
    char input[256];
    unsigned char hash[HASH_SIZE];

    printf("Enter a string to hash (max 255 characters): ");
    fgets(input, sizeof(input), stdin);
    input[strcspn(input, "\n")] = 0; // Remove newline if present

    simple_hash(input, hash); // Calculate the hash
    printf("Hash of the input string: ");
    print_hash(hash); // Print the generated hash

    return 0;
}

