#include <stdio.h>

typedef struct elevator {
    int floor;
    int direction;
    int door_open;
} elevator;

void initialize() {
    elevator elevator = { 0, -1, 0 };
    printf("Elevator initialized\n");
}

void move(int direction) {
    elevator elevator = { 0, 0, 0 };
    if (direction == 1) {
        elevator.direction = 1;
    } else {
        elevator.direction = -1;
    }
    elevator.floor += elevator.direction;
    printf("Moving to floor %d\n", elevator.floor);
}

void open_doors() {
    elevator elevator = { 0, 0, 0 };
    if (elevator.floor == 0 || elevator.direction == -1) {
        elevator.door_open = 1;
        printf("Opening doors\n");
    } else {
        elevator.door_open = 0;
        printf("Closing doors\n");
    }
}

void close_doors() {
    elevator elevator = { 0, 0, 0 };
    if (elevator.floor == 0 || elevator.direction == 1) {
        elevator.door_open = 0;
        printf("Closing doors\n");
    } else {
        elevator.door_open = 1;
        printf("Opening doors\n");
    }
}

void exit() {
    printf("Exiting...\n");
    exit(0);
}

int main() {
    initialize();
    int direction;
    int choice;

    do {
        printf("1. Move up\n");
        printf("2. Move down\n");
        printf("3. Open doors\n");
        printf("4. Close doors\n");
        printf("5. Stop\n");
        printf("6. Exit\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                printf("Moving up\n");
                move(1);
                break;
            case 2:
                printf("Moving down\n");
                move(-1);
                break;
            case 3:
                open_doors();
                break;
            case 4:
                close_doors();
                break;
            case 5:
                break;
            case 6:
                exit();
                break;
            default:
                printf("Invalid choice\n");
        }
    } while (choice!= 5);

    return 0;
}

//GEMINI-pro DATASET v1.0 Category: Client Server Application ; Style: romantic
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define PORT 8080

int main() {
  // Create a socket.
  int sockfd = socket(AF_INET, SOCK_STREAM, 0);
  if (sockfd < 0) {
    perror("socket");
    return EXIT_FAILURE;
  }

  // Bind the socket to the address and port.
  struct sockaddr_in servaddr;
  memset(&servaddr, 0, sizeof(servaddr));
  servaddr.sin_family = AF_INET;
  servaddr.sin_addr.s_addr = inet_addr("127.0.0.1");
  servaddr.sin_port = htons(PORT);
  if (bind(sockfd, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
    perror("bind");
    return EXIT_FAILURE;
  }

  // Listen for connections.
  if (listen(sockfd, 5) < 0) {
    perror("listen");
    return EXIT_FAILURE;
  }

  // Accept a connection.
  int connfd = accept(sockfd, NULL, NULL);
  if (connfd < 0) {
    perror("accept");
    return EXIT_FAILURE;
  }

  // Send a message to the client.
  char *message = "Hello, my love!";
  if (send(connfd, message, strlen(message), 0) < 0) {
    perror("send");
    return EXIT_FAILURE;
  }

  // Receive a message from the client.
  char buffer[1024];
  if (recv(connfd, buffer, sizeof(buffer), 0) < 0) {
    perror("recv");
    return EXIT_FAILURE;
  }

  // Print the message from the client.
  printf("My love says: %s\n", buffer);

  // Close the connection.
  close(connfd);
  close(sockfd);

  return EXIT_SUCCESS;
}

//Falcon-180B DATASET v1.0 Category: Word Count Tool ; Style: real-life
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_WORD_LENGTH 100
#define MAX_WORDS 1000

typedef struct {
    char word[MAX_WORD_LENGTH];
    int count;
} WordCount;

void readWords(char* filename, WordCount* wordCounts, int maxWords) {
    FILE* file = fopen(filename, "r");
    char word[MAX_WORD_LENGTH];
    int i = 0;

    while (fscanf(file, "%s", word)!= EOF) {
        if (i >= maxWords) {
            break;
        }

        for (int j = 0; j < strlen(word); j++) {
            if (!isalpha(word[j])) {
                word[j] = '\0';
            }
        }

        strcpy(wordCounts[i].word, word);
        wordCounts[i].count = 1;
        i++;
    }

    fclose(file);
}

void countWords(WordCount* wordCounts, int numWords) {
    for (int i = 0; i < numWords; i++) {
        for (int j = i + 1; j < numWords; j++) {
            if (strcmp(wordCounts[i].word, wordCounts[j].word) == 0) {
                wordCounts[i].count += wordCounts[j].count;
                wordCounts[j].count = 0;
            }
        }
    }
}

void printWords(WordCount* wordCounts, int numWords) {
    for (int i = 0; i < numWords; i++) {
        if (wordCounts[i].count > 0) {
            printf("%s: %d\n", wordCounts[i].word, wordCounts[i].count);
        }
    }
}

int main(int argc, char* argv[]) {
    if (argc!= 3) {
        printf("Usage: %s <filename> <max_words>\n", argv[0]);
        return 1;
    }

    char* filename = argv[1];
    int maxWords = atoi(argv[2]);

    WordCount wordCounts[MAX_WORDS];
    readWords(filename, wordCounts, maxWords);
    countWords(wordCounts, maxWords);
    printWords(wordCounts, maxWords);

    return 0;
}

