#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <portaudio.h>

// Define the sample rate and number of channels
#define SAMPLE_RATE   (44100)
#define NUM_CHANNELS  (2)

// Define the block size
#define BLOCK_SIZE    (1024)

// Define the number of seconds to record
#define NUM_SECONDS   (10)

// Define the filename to save the recording to
#define FILENAME      ("recording.wav")

// Define the callback function that will be called by PortAudio to process audio data
static int callback( const void *inputBuffer, void *outputBuffer,
                     unsigned long framesPerBuffer,
                     const PaStreamCallbackTimeInfo* timeInfo,
                     PaStreamCallbackFlags statusFlags,
                     void *userData )
{
    // Get the input buffer as a float array
    const float *inBuffer = (const float *)inputBuffer;

    // Get the output buffer as a float array
    float *outBuffer = (float *)outputBuffer;

    // Loop through the frames in the buffer
    for ( unsigned int i = 0; i < framesPerBuffer; i++ )
    {
        // Get the input sample
        float inSample = inBuffer[i * NUM_CHANNELS];

        // Apply a simple distortion effect to the sample
        float outSample = inSample * inSample * inSample;

        // Write the output sample to the output buffer
        outBuffer[i * NUM_CHANNELS] = outSample;
        outBuffer[i * NUM_CHANNELS + 1] = outSample;
    }

    // Return 0 to indicate that the callback was successful
    return 0;
}

// Define the main function
int main( void )
{
    // Initialize PortAudio
    PaError err = Pa_Initialize();
    if ( err != paNoError )
    {
        fprintf( stderr, "Error initializing PortAudio: %s\n", Pa_GetErrorText( err ) );
        return -1;
    }

    // Open a stream for recording
    PaStream *stream;
    err = Pa_OpenStream( &stream, paNoDevice, NUM_CHANNELS, paFloat32, SAMPLE_RATE, BLOCK_SIZE, callback, NULL );
    if ( err != paNoError )
    {
        fprintf( stderr, "Error opening stream: %s\n", Pa_GetErrorText( err ) );
        return -1;
    }

    // Start the stream
    err = Pa_StartStream( stream );
    if ( err != paNoError )
    {
        fprintf( stderr, "Error starting stream: %s\n", Pa_GetErrorText( err ) );
        return -1;
    }

    // Record for a number of seconds
    Pa_Sleep( NUM_SECONDS * 1000 );

    // Stop the stream
    err = Pa_StopStream( stream );
    if ( err != paNoError )
    {
        fprintf( stderr, "Error stopping stream: %s\n", Pa_GetErrorText( err ) );
        return -1;
    }

    // Close the stream
    err = Pa_CloseStream( stream );
    if ( err != paNoError )
    {
        fprintf( stderr, "Error closing stream: %s\n", Pa_GetErrorText( err ) );
        return -1;
    }

    // Terminate PortAudio
    Pa_Terminate();

    // Return 0 to indicate success
    return 0;
}

//FormAI DATASET v1.0 Category: Bucket Sort Implementation ; Style: introspective
#include <stdio.h>
#include <stdlib.h>

void bucketSort(int arr[], int n) {
    int max = arr[0], min = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
        if (arr[i] < min) {
            min = arr[i];
        }
    }

    int bucket_size = 10;
    int num_buckets = (max - min) / bucket_size + 1;
    int **buckets = (int **) malloc(sizeof(int *) * num_buckets);

    for (int i = 0; i < num_buckets; i++) {
        buckets[i] = (int *) malloc(sizeof(int) * n);
    }

    int *bucket_sizes = (int *) malloc(sizeof(int) * num_buckets);
    for (int i = 0; i < num_buckets; i++) {
        bucket_sizes[i] = 0;
    }

    for (int i = 0; i < n; i++) {
        int bucket_index = (arr[i] - min) / bucket_size;
        buckets[bucket_index][bucket_sizes[bucket_index]] = arr[i];
        bucket_sizes[bucket_index]++;
    }

    int k = 0;
    for (int i = 0; i < num_buckets; i++) {
        if (bucket_sizes[i] > 0) {
            for (int j = 0; j < bucket_sizes[i]; j++) {
                arr[k] = buckets[i][j];
                k++;
            }
        }
    }

    free(bucket_sizes);
    for (int i = 0; i < num_buckets; i++) {
        free(buckets[i]);
    }
    free(buckets);
}

int main() {
    int arr[] = {4, 2, 7, 1, 6, 9, 3, 8, 5, 0};
    int n = sizeof(arr) / sizeof(arr[0]);

    printf("Original array: ");
    for (int i = 0; i < n; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");

    bucketSort(arr, n);

    printf("Sorted array: ");
    for (int i = 0; i < n; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");

    return 0;
}

