#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_NAME_LEN 20
#define MAX_EMAIL_LEN 50
#define MAX_SUBS 1000

struct subscriber {
    char name[MAX_NAME_LEN + 1];
    char email[MAX_EMAIL_LEN + 1];
    time_t sub_time;
};

struct mailing_list {
    struct subscriber subs[MAX_SUBS];
    int num_subs;
};

void add_subscriber(struct mailing_list *list, char *name, char *email) {
    if (list->num_subs >= MAX_SUBS) {
        printf("Error: Mailing list is full.\n");
        return;
    }

    strcpy(list->subs[list->num_subs].name, name);
    strcpy(list->subs[list->num_subs].email, email);
    list->subs[list->num_subs].sub_time = time(NULL);
    list->num_subs++;
}

void print_subscribers(struct mailing_list *list) {
    int i;

    printf("Mailing list:\n");
    for (i = 0; i < list->num_subs; i++) {
        printf("%s <%s> (subscribed %s)\n", list->subs[i].name, list->subs[i].email, ctime(&list->subs[i].sub_time));
    }
}

void send_email(struct mailing_list *list, char *subject, char *body) {
    int i;

    for (i = 0; i < list->num_subs; i++) {
        printf("Sending email to %s <%s>:\n", list->subs[i].name, list->subs[i].email);
        printf("Subject: %s\n", subject);
        printf("Body: %s\n", body);
    }
}

int main(int argc, char **argv) {
    struct mailing_list list;
    int i;

    srand(time(NULL));

    memset(&list, 0, sizeof(list));

    // Add some surreal subscribers
    add_subscriber(&list, "Alice", "alice@wonderland.com");
    add_subscriber(&list, "Mad Hatter", "hatter@wonderland.com");
    add_subscriber(&list, "Cheshire Cat", "cat@wonderland.com");
    add_subscriber(&list, "White Rabbit", "rabbit@wonderland.com");
    add_subscriber(&list, "Queen of Hearts", "queen@wonderland.com");

    // Print the subscribers
    print_subscribers(&list);

    // Send an email
    send_email(&list, "Tea Party Invitation", "You're invited to a tea party at the Mad Hatter's house!");

    return 0;
}

