//LLAMA2-13B DATASET v1.0 Category: Benchmarking ; Style: mathematical
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define N 10000

int main() {
    double start, end;
    int i;

    srand(time(NULL)); // seed random number generator

    // initialize arrays
    double a[N] = {0};
    double b[N] = {0};
    double c[N] = {0};

    // generate random numbers for a, b, and c
    for (i = 0; i < N; i++) {
        a[i] = drand48() * 10 - 5;
        b[i] = drand48() * 10 - 5;
        c[i] = a[i] * b[i];
    }

    // compute the dot product
    double dot_product = 0;
    for (i = 0; i < N; i++) {
        dot_product += a[i] * b[i];
    }

    // compute the norm of a and b
    double norm_a = 0;
    double norm_b = 0;
    for (i = 0; i < N; i++) {
        norm_a += a[i] * a[i];
        norm_b += b[i] * b[i];
    }

    // compute the condition number
    double condition_number = 0;
    for (i = 0; i < N; i++) {
        condition_number += (a[i] * b[i]) / (norm_a * norm_b);
    }

    // measure the execution time
    clock_t start_time = clock();
    for (i = 0; i < 100000; i++) {
        dot_product = 0;
        for (int j = 0; j < N; j++) {
            dot_product += a[j] * b[j];
        }
    }
    clock_t end_time = clock();
    double execution_time = (double)(end_time - start_time) / CLOCKS_PER_SEC;

    // print results
    printf("Dot product: %f\n", dot_product);
    printf("Norm of a: %f\n", norm_a);
    printf("Norm of b: %f\n", norm_b);
    printf("Condition number: %f\n", condition_number);
    printf("Execution time: %f seconds\n", execution_time);

    return 0;
}

