#include <stdio.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <netdb.h>
#include <unistd.h>
#include <string.h>

int main(int argc, char *argv[]) {
    int sockfd, portno;
    struct sockaddr_in serv_addr;
    char buffer[100];
    int n;

    // Server socket
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("socket creation failed");
        exit(1);
    }

    // Set up the server address struct
    memset((char *) &serv_addr, '\0', sizeof(serv_addr));
    portno = htons(atoi(argv[1]));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = portno;

    // Bind the server socket
    if (bind(sockfd, (struct sockaddr *) &serv_addr, sizeof(serv_addr)) < 0) {
        perror("bind failed");
        exit(1);
    }

    // Listen for incoming connections
    if (listen(sockfd, 3) < 0) {
        perror("listen failed");
        exit(1);
    }

    // Accept incoming connection
    printf("Waiting for a connection...\n");
    while (1) {
        struct sockaddr_in cli_addr;
        socklen_t clilen = sizeof(cli_addr);
        int new_socket = accept(sockfd, (struct sockaddr *) &cli_addr, &clilen);
        if (new_socket < 0) {
            perror("accept failed");
            exit(1);
        }
        printf("Connection from %s:%d\n", inet_ntoa(cli_addr.sin_addr), ntohs(cli_addr.sin_port));

        // Handle the incoming connection
        int flag = 1;
        while (flag) {
            memset(buffer, '\0', sizeof(buffer));
            n = recv(new_socket, buffer, sizeof(buffer), 0);
            if (n < 0) {
                perror("recv failed");
                flag = 0;
            } else {
                printf("%s", buffer);
            }
            if (strncmp(buffer, "end", 3) == 0) {
                flag = 0;
            } else {
                n = send(new_socket, buffer, sizeof(buffer), 0);
                if (n < 0) {
                    perror("send failed");
                    flag = 0;
                }
            }
        }
        close(new_socket);
    }
    close(sockfd);
    return 0;
}

//GEMINI-pro DATASET v1.0 Category: Chess engine ; Style: multiplayer
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define BOARD_SIZE 8

typedef struct {
    int x;
    int y;
} Position;

typedef struct {
    char type;
    char color;
    Position position;
} Piece;

typedef struct {
    Piece pieces[16];
    int turn;
} Player;

typedef struct {
    Player players[2];
    Piece board[BOARD_SIZE][BOARD_SIZE];
} Game;

void initialize_game(Game *game) {
    // Initialize the players
    for (int i = 0; i < 2; i++) {
        game->players[i].turn = i;
    }

    // Initialize the pieces
    for (int i = 0; i < 16; i++) {
        // Set the type of the piece
        if (i < 8) {
            game->players[0].pieces[i].type = 'p';
        } else {
            game->players[1].pieces[i].type = 'P';
        }

        // Set the color of the piece
        if (i < 8) {
            game->players[0].pieces[i].color = 'w';
        } else {
            game->players[1].pieces[i].color = 'b';
        }

        // Set the position of the piece
        if (i < 8) {
            game->players[0].pieces[i].position.x = 1;
            game->players[0].pieces[i].position.y = i;
        } else {
            game->players[1].pieces[i].position.x = 6;
            game->players[1].pieces[i].position.y = i;
        }
    }

    // Initialize the board
    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            game->board[i][j].type = ' ';
            game->board[i][j].color = ' ';
            game->board[i][j].position.x = i;
            game->board[i][j].position.y = j;
        }
    }

    // Place the pieces on the board
    for (int i = 0; i < 16; i++) {
        game->board[game->players[0].pieces[i].position.x][game->players[0].pieces[i].position.y] = game->players[0].pieces[i];
        game->board[game->players[1].pieces[i].position.x][game->players[1].pieces[i].position.y] = game->players[1].pieces[i];
    }
}

void print_board(Game *game) {
    // Print the top border
    printf("   +---+---+---+---+---+---+---+---+\n");

    // Print the rows
    for (int i = 0; i < BOARD_SIZE; i++) {
        // Print the row number
        printf(" %d |", i + 1);

        // Print the columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            // Print the piece
            if (game->board[i][j].type == ' ') {
                printf("   |");
            } else {
                printf(" %c%c |", game->board[i][j].type, game->board[i][j].color);
            }
        }

        // Print the bottom border
        printf("\n   +---+---+---+---+---+---+---+---+\n");
    }

    // Print the bottom border
    printf("   +---+---+---+---+---+---+---+---+\n");
}

int main() {
    // Initialize the game
    Game game;
    initialize_game(&game);

    // Print the board
    print_board(&game);

    // Get the move from the player
    char move[5];
    printf("Enter your move: ");
    scanf("%s", move);

    // Parse the move
    Position from;
    Position to;
    from.x = move[0] - 'a';
    from.y = move[1] - '1';
    to.x = move[2] - 'a';
    to.y = move[3] - '1';

    // Make the move
    game.board[to.x][to.y] = game.board[from.x][from.y];
    game.board[from.x][from.y].type = ' ';
    game.board[from.x][from.y].color = ' ';

    // Print the board
    print_board(&game);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define BOARD_SIZE 8

// Constants for checkers
#define EMPTY 0
#define BLACK 1
#define WHITE -1
#define BLACK_KING 2
#define WHITE_KING -2

typedef struct Checker {
    int type;
    bool isKing;
} Checker;

void printBoard(Checker board[BOARD_SIZE][BOARD_SIZE]) {
    printf("\n  ");
    for (int i = 0; i < BOARD_SIZE; i++) {
        printf("%d ", i);
    }
    printf("\n");
    for (int i = 0; i < BOARD_SIZE; i++) {
        printf("%d ", i);
        for (int j = 0; j < BOARD_SIZE; j++) {
            printf("%c ", board[i][j].type == EMPTY ? '-' : (board[i][j].type == BLACK || board[i][j].type == BLACK_KING) ? 'B' : 'W');
        }
        printf("\n");
    }
    printf("\n");
}

bool moveIsLegal(Checker board[BOARD_SIZE][BOARD_SIZE], int row, int col, int destRow, int destCol, int currentPlayer) {
    // Check destination is on board
    if (destRow < 0 || destRow >= BOARD_SIZE || destCol < 0 || destCol >= BOARD_SIZE) {
        return false;
    }
    // Check destination is empty
    if (board[destRow][destCol].type != EMPTY) {
        return false;
    }
    // Check move is diagonal and within 2 squares
    int diffRow = abs(destRow - row);
    int diffCol = abs(destCol - col);
    if (diffRow != diffCol || diffRow > 2 || diffCol > 2) {
        return false;
    }
    // Check if moving in correct direction for player
    bool isKing = board[row][col].isKing;
    if (!isKing && ((currentPlayer == BLACK && destRow > row) || (currentPlayer == WHITE && destRow < row))) {
        return false;
    }
    // Check if jumping over checker
    if (diffRow == 2) {
        int jumpedRow = (destRow + row) / 2;
        int jumpedCol = (destCol + col) / 2;
        int jumpedChecker = board[jumpedRow][jumpedCol].type;
        if ((jumpedChecker == EMPTY) || (currentPlayer == BLACK && jumpedChecker != WHITE && jumpedChecker != WHITE_KING) || (currentPlayer == WHITE && jumpedChecker != BLACK && jumpedChecker != BLACK_KING)) {
            return false;
        }
    }
    return true;
}

bool playerHasMoves(Checker board[BOARD_SIZE][BOARD_SIZE], int currentPlayer) {
    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[i][j].type == currentPlayer || (board[i][j].type == currentPlayer * 2 && board[i][j].isKing)) {
                for (int k = -2; k <= 2; k += 4) {
                    for (int l = -2; l <= 2; l += 4) {
                        int destRow = i + currentPlayer * k;
                        int destCol = j + l;
                        if (moveIsLegal(board, i, j, destRow, destCol, currentPlayer)) {
                            return true;
                        }
                    }
                }
            }
        }
    }
    return false;
}

void makeMove(Checker board[BOARD_SIZE][BOARD_SIZE], int row, int col, int destRow, int destCol, int currentPlayer) {
    board[destRow][destCol].type = board[row][col].type;
    board[destRow][destCol].isKing = board[row][col].isKing;
    board[row][col].type = EMPTY;
    // Check if reached other side and promote to king
    if (destRow == 0 && board[destRow][destCol].type == WHITE) {
        board[destRow][destCol].type = WHITE_KING;
        board[destRow][destCol].isKing = true;
    }
    if (destRow == BOARD_SIZE - 1 && board[destRow][destCol].type == BLACK) {
        board[destRow][destCol].type = BLACK_KING;
        board[destRow][destCol].isKing = true;
    }
    // If jumped over checker, remove it
    if (abs(destRow - row) == 2) {
        int jumpedRow = (destRow + row) / 2;
        int jumpedCol = (destCol + col) / 2;
        board[jumpedRow][jumpedCol].type = EMPTY;
        board[jumpedRow][jumpedCol].isKing = false;
    }
}

int main() {
    Checker board[BOARD_SIZE][BOARD_SIZE];
    // Initialize board
    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            if ((i + j) % 2 == 0 && i < 3) {
                board[i][j].type = BLACK;
                board[i][j].isKing = false;
            } else if ((i + j) % 2 == 0 && i > BOARD_SIZE - 4) {
                board[i][j].type = WHITE;
                board[i][j].isKing = false;
            } else {
                board[i][j].type = EMPTY;
                board[i][j].isKing = false;
            }
        }
    }
    printBoard(board);
    int currentPlayer = BLACK;
    printf("Black goes first.\n");
    while (true) {
        if (!playerHasMoves(board, currentPlayer)) {
            printf("%s has no moves left and %s wins!\n", currentPlayer == BLACK ? "Black" : "White", currentPlayer == BLACK ? "White" : "Black");
            break;
        }
        printf("%s's turn.\n", currentPlayer == BLACK ? "Black" : "White");
        int row, col, destRow, destCol;
        while (true) {
            printf("Enter row and column of checker to move: ");
            scanf("%d %d", &row, &col);
            printf("Enter row and column of destination square: ");
            scanf("%d %d", &destRow, &destCol);
            if (moveIsLegal(board, row, col, destRow, destCol, currentPlayer)) {
                break;
            }
            printf("Invalid move! Please try again.\n");
        }
        makeMove(board, row, col, destRow, destCol, currentPlayer);
        printBoard(board);
        if ((destRow == BOARD_SIZE - 1 && currentPlayer == BLACK) || (destRow == 0 && currentPlayer == WHITE)) {
            printf("%s wins!\n", currentPlayer == BLACK ? "Black" : "White");
            break;
        }
        currentPlayer = -currentPlayer;
    }
    return 0;
}

