    ll n; cin >> n;
    calc();

    if (n < 3) cout << "0 0 " << n << endl;
    else {
        for (int i = 1; i < maxn; ++i) {
            for (int j = 1; j < maxn; ++j) {
                for (int k = 1; k < maxn; ++k) {
                    if (fib[i] + fib[j] + fib[k] == n) {
                        cout << fib[i] << " " << fib[j] << " " << fib[k] << endl;
                        return 0;
                    }
                }
            }
        }
    }
    return 0;
}

