#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_X 20
#define MAX_Y 20

int grid[MAX_X][MAX_Y];
int visited[MAX_X][MAX_Y];

int dx[] = {0, 1, 0, -1};
int dy[] = {1, 0, -1, 0};

int dfs(int x, int y, int start_x, int start_y) {
    visited[x][y] = 1;
    if (x == start_x && y == start_y) {
        return 1;
    }
    for (int i = 0; i < 4; i++) {
        int nx = x + dx[i];
        int ny = y + dy[i];
        if (nx >= 0 && nx < MAX_X && ny >= 0 && ny < MAX_Y &&!visited[nx][ny] && grid[nx][ny] == 1) {
            if (dfs(nx, ny, x, y)) {
                return 1;
            }
        }
    }
    return 0;
}

int main() {
    srand(time(NULL));
    for (int i = 0; i < MAX_X; i++) {
        for (int j = 0; j < MAX_Y; j++) {
            grid[i][j] = rand() % 2;
        }
    }

    int start_x, start_y;
    int i, j;
    for (i = 0; i < MAX_X; i++) {
        for (j = 0; j < MAX_Y; j++) {
            if (grid[i][j] == 1) {
                start_x = i;
                start_y = j;
                break;
            }
        }
    }

    dfs(start_x, start_y, start_x, start_y);

    for (i = 0; i < MAX_X; i++) {
        for (j = 0; j < MAX_Y; j++) {
            if (grid[i][j] == 1) {
                printf(" ");
            } else if (visited[i][j] == 1) {
                printf("#");
            } else {
                printf(" ");
            }
        }
        printf("\n");
    }

    return 0;
}

void reverse(char *s, int n) {
    char *first = &amp;s[0];
    char *last = &amp;s[n-1];
    int k = 0;

    while(first &lt; last){
        char temp = *first;
        *first++ = *last;
        *last-- = temp;  
        k++;
    }
}

