const int TetrominoSprite::TETROMINO_HEIGHT = 20;

TetrominoSprite::TetrominoSprite(TetrominoPtr shape, int boardTop, int boardLeft) : 
    tetromino(shape), boardTop(boardTop), boardLeft(boardLeft) {
}

