                sf::Sprite sprite( ResourceManager::getInstance().getTetrominoImage() );
                sprite.SetColor( ResourceManager::getInstance().getColor(shape.getShape()) );
                sprite.SetPosition( 
                    left + (col*TETROMINO_HEIGHT),
                    top + (row*TETROMINO_HEIGHT));

                target.Draw( sprite );
            }
        }
    }    
}

