{
    if(n == 1)
        return 1;

    int tich = 1;
    for(int i = 1; i <= n; i++)
    {
        tich *= i;
    }
    return deQuyPhiTuyen(n - 1) + tich;
}

int khuDeQuy(int n)
{
    int i;
    long S, P;
    S = 0;
    P = 1;
    i = 1;
    while(i <= n)
