#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define ROWS 20
#define COLS 20

char grid[ROWS][COLS];
int generations = 0;

void displayGrid() {
    printf("Generation %d\n", generations);
    for (int i = 0; i < ROWS; i++) {
        for (int j = 0; j < COLS; j++) {
            printf("%c", grid[i][j]);
        }
        printf("\n");
    }
    printf("\n");
}

void initGrid() {
    for (int i = 0; i < ROWS; i++) {
        for (int j = 0; j < COLS; j++) {
            grid[i][j] = ' ';
        }
    }
}

int countNeighbors(int row, int col) {
    int count = 0;
    for (int i = row - 1; i <= row + 1; i++) {
        for (int j = col - 1; j <= col + 1; j++) {
            if (i >= 0 && i < ROWS && j >= 0 && j < COLS && (i != row || j != col) && grid[i][j] == '*') {
                count++;
            }
        }
    }
    return count;
}

void updateGrid() {
    char nextGrid[ROWS][COLS];
    for (int i = 0; i < ROWS; i++) {
        for (int j = 0; j < COLS; j++) {
            int neighbors = countNeighbors(i, j);
            if (grid[i][j] == '*') {
                if (neighbors == 2 || neighbors == 3) {
                    nextGrid[i][j] = '*';
                } else {
                    nextGrid[i][j] = ' ';
                }
            } else {
                if (neighbors == 3) {
                    nextGrid[i][j] = '*';
                } else {
                    nextGrid[i][j] = ' ';
                }
            }
        }
    }
    memcpy(grid, nextGrid, sizeof(grid));
    generations++;
}

int main() {
    initGrid();
    grid[10][10] = '*';
    grid[10][11] = '*';
    grid[10][12] = '*';
    grid[9][11] = '*';
    grid[11][11] = '*';
    displayGrid();

    while (generations < 10) {
        updateGrid();
        displayGrid();
    }

    return 0;
}

