#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define ROWS 10
#define COLS 10
#define MAX_SCORE 100

// Structure to store game data
typedef struct {
    int score;
    int row;
    int col;
} game_data_t;

// Function to generate a random row and column for the game piece
void generate_random_position(game_data_t *data) {
    data->row = rand() % ROWS;
    data->col = rand() % COLS;
}

// Function to print the game board
void print_board(game_data_t *data) {
    printf("  1 | 2 | 3\n");
    for (int i = 0; i < ROWS; i++) {
        printf(" %d | ", i + 1);
        for (int j = 0; j < COLS; j++) {
            if (i == data->row && j == data->col) {
                printf("X");
            } else {
                printf("_");
            }
        }
        printf("\n");
    }
}

// Function to check if the game piece is on a winning row or column
int is_winning_row(game_data_t *data) {
    for (int i = 0; i < ROWS; i++) {
        if (data->row == i && data->col == 0 && data->score == COLS * i) {
            return 1;
        }
    }
    for (int i = 0; i < ROWS; i++) {
        if (data->row == 0 && data->col == i && data->score == ROWS * i) {
            return 1;
        }
    }
    return 0;
}

// Function to check if the game piece is on a winning diagonal
int is_winning_diagonal(game_data_t *data) {
    if (data->row == 0 || data->col == 0) {
        return 0;
    }
    int row = data->row - data->col;
    int col = data->col - data->row;
    if (row == 0 && col == 0) {
        return 1;
    }
    for (int i = 1; i <= ROWS; i++) {
        if (data->row - i * row < 0 || data->col + i * col < 0) {
            break;
        }
        if (data->row - i * row >= ROWS || data->col + i * col >= COLS) {
            break;
        }
        if (data->score == (i * row + col) % MAX_SCORE) {
            return 1;
        }
    }
    return 0;
}

// Function to play the game
void play_game(game_data_t *data) {
    int move = rand() % 2;
    if (move == 0) {
        // Move down
        data->row += 1;
    } else {
        // Move right
        data->col += 1;
    }
    // Check for game over
    if (is_winning_row(data) || is_winning_diagonal(data)) {
        printf("You won! Your score is %d\n", data->score);
        return;
    }
    // Print the updated board
    print_board(data);
}

int main() {
    srand(time(NULL));
    game_data_t data;
    generate_random_position(&data);
    print_board(&data);
    for (int i = 0; i < 10; i++) {
        play_game(&data);
    }
    return 0;
}

