#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <ctype.h>

#define MAX_SENTENCE_LENGTH 200

int sentiment_analysis(char *sentence)
{
    int sentiment_score = 0;
    int sentence_length = strlen(sentence);

    // Iterate over the sentence to identify positive and negative words
    for (int i = 0; i < sentence_length; i++)
    {
        char word[MAX_SENTENCE_LENGTH];
        int word_length = 0;

        // Extract words from the sentence
        while (i < sentence_length && isalpha(sentence[i]))
        {
            word[word_length] = sentence[i];
            word_length++;
            i++;
        }

        // Assign points for positive and negative words
        if (strcmp(word, "happy") == 0 || strcmp(word, "good") == 0)
        {
            sentiment_score++;
        }
        else if (strcmp(word, "sad") == 0 || strcmp(word, "bad") == 0)
        {
            sentiment_score--;
        }
    }

    // Return the sentiment score
    return sentiment_score;
}

int main()
{
    char sentence[MAX_SENTENCE_LENGTH];

    // Get the sentence from the user
    printf("Please enter a sentence: ");
    fgets(sentence, MAX_SENTENCE_LENGTH, stdin);

    // Analyze the sentiment of the sentence
    int sentiment_score = sentiment_analysis(sentence);

    // Print the sentiment score
    if (sentiment_score > 0)
    {
        printf("The sentiment of your sentence is positive.\n");
    }
    else if (sentiment_score < 0)
    {
        printf("The sentiment of your sentence is negative.\n");
    }
    else
    {
        printf("The sentiment of your sentence is neutral.\n");
    }

    return 0;
}

