#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

// Function to extract metadata from a C program
void extract_metadata(char *filename) {
    FILE *fp;
    char line[1000];
    char *token;
    int line_count = 0;
    int comment_count = 0;
    int blank_count = 0;
    int total_lines = 0;

    // Open the input file
    fp = fopen(filename, "r");

    // Check if the file was successfully opened
    if (fp == NULL) {
        printf("Error: Could not open file %s\n", filename);
        exit(1);
    }

    // Read each line of the file
    while (fgets(line, 1000, fp)!= NULL) {
        total_lines++;

        // Check if the line is a comment
        if (line[0] == '/' && line[1] == '/') {
            comment_count++;
        } else if (line[0] == '/' && line[1] == '*') {
            comment_count++;
        } else if (line[0] == '*' && line[1] == '/') {
            comment_count++;
        }

        // Check if the line is blank
        if (strlen(line) == 0) {
            blank_count++;
        }
    }

    // Compute the percentage of comments and blank lines
    float comment_percentage = (float) comment_count / total_lines * 100;
    float blank_percentage = (float) blank_count / total_lines * 100;

    // Print the metadata
    printf("Metadata for file %s:\n", filename);
    printf("Total lines: %d\n", total_lines);
    printf("Comment lines: %d (%.2f%%)\n", comment_count, comment_percentage);
    printf("Blank lines: %d (%.2f%%)\n", blank_count, blank_percentage);

    // Close the input file
    fclose(fp);
}

int main(int argc, char *argv[]) {
    // Check if the correct number of arguments were provided
    if (argc!= 2) {
        printf("Usage: %s <filename>\n", argv[0]);
        exit(1);
    }

    // Extract metadata from the input file
    extract_metadata(argv[1]);

    return 0;
}

