#include <sys/mman.h>
#include <semaphore.h>

#define WEATHER_FILE "weather.dat"
#define BUFFER_SIZE 1024

sem_t *sem;

void init_sem(void) {
    sem = sem_open("/sem", O_CREAT, 0644, 0);
    if (sem == SEM_FAILED) {
        perror("sem_open() failed");
        exit(EXIT_FAILURE);
    }
}

void cleanup_sem(void) {
    sem_close(sem);
}

void* async_read_weather(void *arg) {
    int fd = open(WEATHER_FILE, O_RDONLY);
    if (fd == -1) {
        perror("open() failed");
        exit(EXIT_FAILURE);
    }

    char buffer[BUFFER_SIZE];
    size_t bytes_read = read(fd, buffer, BUFFER_SIZE);
    if (bytes_read == -1) {
        perror("read() failed");
        exit(EXIT_FAILURE);
    }

    // simulate reading from a slow device
    usleep(100000);

    // write the buffer to the semaphore
    sem_post(sem);

    close(fd);
    return NULL;
}

void* async_update_weather(void *arg) {
    // simulate updating the weather data
    sleep(1);

    // write the updated data to the weather file
    char updated_data[] = "New weather data!";
    write(open(WEATHER_FILE, O_WRONLY), updated_data, strlen(updated_data));

    // signal the reader that new data is available
    sem_post(sem);

    return NULL;
}

int main(void) {
    init_sem();

    // create two asynchronous tasks
    pid_t task1 = fork();
    if (task1 == 0) {
        async_read_weather(NULL);
    } else {
        pid_t task2 = fork();
        if (task2 == 0) {
            async_update_weather(NULL);
        }
    }

    // wait for the tasks to finish
    wait(NULL);

    cleanup_sem();

    return 0;
}

