#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>

// Define the simulation parameters
#define GRAVITY 9.8
#define WALL_THICKNESS 0.1
#define BALL_RADIUS 0.2
#define PADDLE_WIDTH 0.5
#define PADDLE_HEIGHT 0.2
#define COURT_WIDTH 10
#define COURT_LENGTH 20

// Define the simulation structs
struct Ball {
    float x;
    float y;
    float vx;
    float vy;
};

struct Paddle {
    float x;
    float y;
    float width;
    float height;
};

struct Court {
    float walls[COURT_WIDTH][COURT_LENGTH];
};

// Define the simulation functions
void init_ball(struct Ball *ball) {
    ball->x = 5;
    ball->y = 5;
    ball->vx = 5;
    ball->vy = 5;
}

void init_paddle(struct Paddle *paddle) {
    paddle->x = 2;
    paddle->y = 5;
    paddle->width = PADDLE_WIDTH;
    paddle->height = PADDLE_HEIGHT;
}

void update_ball(struct Ball *ball) {
    ball->x += ball->vx;
    ball->y += ball->vy;
    if (ball->x < 0 || ball->x >= COURT_WIDTH - BALL_RADIUS) {
        ball->vx = -ball->vx;
    }
    if (ball->y < 0 || ball->y >= COURT_LENGTH - BALL_RADIUS) {
        ball->vy = -ball->vy;
    }
}

void update_paddle(struct Paddle *paddle) {
    if (paddle->x + paddle->width >= COURT_WIDTH) {
        paddle->x = COURT_WIDTH - paddle->width;
    }
    if (paddle->y + paddle->height >= COURT_LENGTH) {
        paddle->y = COURT_LENGTH - paddle->height;
    }
}

void simulate(struct Ball *ball, struct Paddle *paddle) {
    update_ball(ball);
    update_paddle(paddle);
}

void draw_court(struct Court *court) {
    for (int i = 0; i < COURT_WIDTH; i++) {
        for (int j = 0; j < COURT_LENGTH; j++) {
            if (court->walls[i][j] == 1) {
                printf("|");
            } else {
                printf(" ");
            }
        }
        printf("\n");
    }
}

int main() {
    struct Ball ball;
    struct Paddle paddle;
    struct Court court;

    init_ball(&ball);
    init_paddle(&paddle);
    court.walls[0][0] = 1;
    court.walls[COURT_WIDTH - 1][0] = 1;
    court.walls[0][COURT_LENGTH - 1] = 1;
    court.walls[COURT_WIDTH - 1][COURT_LENGTH - 1] = 1;

    for (int i = 0; i < 1000; i++) {
        simulate(&ball, &paddle);
        draw_court(&court);
        printf("FPS: %f\n", 1000 / (float)i);
    }

    return 0;
}

