    printf("\033[H\033[J");
    printf("Road:\n");

    for (int i = 0; i < ROAD_LENGTH; i++) {
        int found = 0;
        for (int j = 0; j < NUM_CARS; j++) {
            if (cars[j].position == i) {
                printf("C");
                found = 1;
                break;
            }
        }
        if (!found) {
            printf("-");
        }
    }
    printf("\n");
}

int main() {
    srand(time(NULL));
    pthread_t threads[NUM_CARS];

    // Initialize cars at position 0
    for (int i = 0; i < NUM_CARS; i++) {
        cars[i].id = i + 1;
        cars[i].position = 0;
    }

    // Create threads for each car
    for (int i = 0; i < NUM_CARS; i++) {
        pthread_create(&threads[i], NULL, move_car, (void*)&cars[i]);
    }

    // Main simulation loop
    while (1) {
        print_road();

        // Check if all cars have reached the end
        int all_done = 1;
        for (int i = 0; i < NUM_CARS; i++) {
            if (cars[i].position < ROAD_LENGTH) {
                all_done = 0;
                break;
            }
        }

        if (all_done) {
            break;
        }

        usleep(SLEEP_TIME); // Sleep to reduce console update frequency
    }

    // Wait for all car threads to finish
    for (int i = 0; i < NUM_CARS; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("All cars have completed the simulation!\n");
    return 0;
}

