#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <string.h>

#define MAX_WORDS 1000
#define MAX_WORD_LENGTH 50

typedef struct {
    char word[MAX_WORD_LENGTH];
    int frequency;
} WordFrequency;

void readFile(FILE *file, WordFrequency *wordFrequencies) {
    char line[MAX_WORD_LENGTH];
    while (fgets(line, MAX_WORD_LENGTH, file)!= NULL) {
        int i = 0;
        char *word = strtok(line, ",.?!;:");
        while (word!= NULL && i < MAX_WORDS) {
            int j = 0;
            while (isalpha(word[j]) && j < MAX_WORD_LENGTH) {
                wordFrequencies[i].word[j] = tolower(word[j]);
                j++;
            }
            wordFrequencies[i].word[j] = '\0';
            wordFrequencies[i].frequency++;
            i++;
            word = strtok(NULL, ",.?!;:");
        }
    }
}

void countWords(WordFrequency *wordFrequencies) {
    int i = 0;
    while (i < MAX_WORDS) {
        if (wordFrequencies[i].word[0]!= '\0') {
            printf("%s: %d\n", wordFrequencies[i].word, wordFrequencies[i].frequency);
        }
        i++;
    }
}

int main() {
    FILE *file = fopen("input.txt", "r");
    if (file == NULL) {
        printf("Error: could not open file.\n");
        return 1;
    }

    WordFrequency wordFrequencies[MAX_WORDS];
    readFile(file, wordFrequencies);
    fclose(file);

    countWords(wordFrequencies);

    return 0;
}

