    strcpy(rooms[5].name, "Treasure Room");
    strcpy(rooms[5].description, "You’ve found the treasure room! Gold coins and jewels are scattered everywhere.");

    // Linking rooms
    rooms[0].choices[0] = &rooms[1]; // Entrance Hall to Library
    rooms[0].choices[1] = &rooms[2]; // Entrance Hall to Kitchen
    rooms[0].choices[2] = &rooms[3]; // Entrance Hall to Basement
    rooms[0].num_choices = 3;

    rooms[1].choices[0] = &rooms[0]; // Library back to Entrance Hall
    rooms[1].choices[1] = &rooms[4]; // Library to Ghostly Chamber
    rooms[1].num_choices = 2;

    rooms[2].choices[0] = &rooms[0]; // Kitchen back to Entrance Hall
    rooms[2].choices[1] = &rooms[5]; // Kitchen to Treasure Room
    rooms[2].num_choices = 2;

    rooms[3].choices[0] = &rooms[0]; // Basement back to Entrance Hall
    rooms[3].choices[1] = &rooms[4]; // Basement to Ghostly Chamber
    rooms[3].num_choices = 2;

    rooms[4].choices[0] = &rooms[1]; // Ghostly Chamber back to Library
    rooms[4].choices[1] = &rooms[3]; // Ghostly Chamber to Basement
    rooms[4].num_choices = 2;

    rooms[5].choices[0] = &rooms[2]; // Treasure Room back to Kitchen
    rooms[5].num_choices = 1;
}

void exploreRoom(Room* room) {
    printf("\nYou are now in: %s\n", room->name);
    printf("%s\n", room->description);

    if(room->num_choices > 0) {
        printChoices(room);
        Room* nextRoom = getRoomChoice(room);
        if(nextRoom) {
            exploreRoom(nextRoom);
        } else {
            printf("You chose to stay here, that’s brave!\n");
            exploreRoom(room); // Stay in the same room
        }
    }
}

void printChoices(Room* room) {
    printf("Where would you like to go?\n");
    for(int i = 0; i < room->num_choices; i++) {
        printf("%d. %s\n", i + 1, room->choices[i]->name);
    }
    printf("Enter your choice (or 0 to stay here): ");
}

Room* getRoomChoice(Room* room) {
    int choice;
    scanf("%d", &choice);

    if(choice >= 1 && choice <= room->num_choices) {
        return room->choices[choice - 1];
    } else if (choice == 0) {
        return NULL; // Stay in the same room
    } else {
        printf("Invalid choice, try again!\n");
        return getRoomChoice(room); // Recurse until valid choice is made
    }
}

void playGame() {
    Room rooms[6];
    createRooms(rooms);
    exploreRoom(&rooms[0]);
    printf("Thank you for playing! Hope you made it out alive...\n");
}

