//Falcon-180B DATASET v1.0 Category: Interprocess communication ; Style: multi-threaded
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pthread.h>
#include <semaphore.h>
#include <fcntl.h>
#include <sys/shm.h>
#include <sys/ipc.h>

#define MAX_THREADS 10
#define MAX_SHARED_MEM 1024

typedef struct {
    int id;
    int shared_mem_id;
    char *name;
} thread_data_t;

sem_t mutex;
int shared_mem_id;
char shared_mem[MAX_SHARED_MEM];

void *thread_func(void *arg) {
    thread_data_t *data = (thread_data_t *) arg;
    int i;

    for (i = 0; i < 10; i++) {
        sem_wait(&mutex);
        sprintf(shared_mem + strlen(shared_mem), "Thread %d: %s\n", data->id, data->name);
        sem_post(&mutex);
        usleep(100000);
    }

    return NULL;
}

int main() {
    int i;
    pthread_t threads[MAX_THREADS];
    thread_data_t data[MAX_THREADS];

    shared_mem_id = shmget(IPC_PRIVATE, MAX_SHARED_MEM, IPC_CREAT | 0666);
    if (shared_mem_id == -1) {
        printf("Error getting shared memory\n");
        exit(1);
    }

    if (shmat(shared_mem_id, shared_mem, 0) == (void *) -1) {
        printf("Error attaching shared memory\n");
        exit(1);
    }

    sem_init(&mutex, 0, 1);

    for (i = 0; i < MAX_THREADS; i++) {
        data[i].id = i + 1;
        data[i].shared_mem_id = shared_mem_id;
        data[i].name = (char *) malloc(32);
        sprintf(data[i].name, "Thread %d", i + 1);

        pthread_create(&threads[i], NULL, thread_func, &data[i]);
    }

    for (i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&mutex);
    shmdt(shared_mem);
    shmctl(shared_mem_id, IPC_RMID, NULL);

    return 0;
}

