// Async function to shuffle fortune messages after 3 seconds
void shuffle_fortune_messages(char **messages, int size) {
    int i, j;
    char *temp;
    srand(time(NULL));
    for (i = size - 1; i > 0; i--) {
        j = rand() % (i + 1);
        // Swap messages
        temp = messages[i];
        messages[i] = messages[j];
        messages[j] = temp;
    }
}

