#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <stdlib.h>
#include <time.h>

#define KEY_SIZE 16
#define BLOCK_SIZE 16
#define MESSAGE_SIZE 32

// Function to generate a random key
void generate_key(uint8_t *key) {
    uint8_t i;
    for (i = 0; i < KEY_SIZE; i++) {
        key[i] = rand() % 256;
    }
}

// Function to encrypt a message
void encrypt(uint8_t *message, uint8_t *key) {
    uint8_t i, j;
    for (i = 0; i < MESSAGE_SIZE; i += BLOCK_SIZE) {
        for (j = 0; j < BLOCK_SIZE; j++) {
            message[i + j] = (message[i + j] + key[j]) % 256;
        }
    }
}

// Function to decrypt an encrypted message
void decrypt(uint8_t *message, uint8_t *key) {
    uint8_t i, j;
    for (i = 0; i < MESSAGE_SIZE; i += BLOCK_SIZE) {
        for (j = 0; j < BLOCK_SIZE; j++) {
            message[i + j] = (message[i + j] - key[j]) % 256;
        }
    }
}

int main() {
    uint8_t message[MESSAGE_SIZE];
    uint8_t key[KEY_SIZE];

    // Generate a random key
    generate_key(key);

    // Encrypt the message
    encrypt(message, key);

    // Print the encrypted message
    for (int i = 0; i < MESSAGE_SIZE; i++) {
        printf("%02x", message[i]);
    }

    // Decrypt the message
    decrypt(message, key);

    // Print the decrypted message
    for (int i = 0; i < MESSAGE_SIZE; i++) {
        printf("%02x", message[i]);
    }

    return 0;
}

