#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Definition of the compare function
int compare(const void *a, const void *b) {
    // Cast the pointers to integers
    int *ia = a, *ib = b;

    // Check if the first number is less than the second
    if (*ia < *ib) {
        // Return a negative value
        return -1;
    } else if (*ia > *ib) {
        // Return a positive value
        return 1;
    } else {
        // If the numbers are equal, return 0
        return 0;
    }
}

int main() {
    // Define an array of integers
    int arr[5] = {3, 1, 2, 6, 4};

    // Sort the array using the compare function
    qsort(arr, 5, sizeof(int), compare);

    // Print the sorted array
    printf("Sorted array: \n");
    for (int i = 0; i < 5; i++) {
        printf("%d ", arr[i]);
    }

    // Sort an array of strings using the compare function
    char strArr[5][10] = {
        "apple", "banana", "cherry", "date", "elephant"
    };

    qsort(strArr, 5, sizeof(char[10]), compare);

    // Print the sorted array of strings
    printf("Sorted array of strings: \n");
    for (int i = 0; i < 5; i++) {
        printf("%s ", strArr[i]);
    }

    return 0;
}

