#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define MAX_PRIME 100000
#define BUFFER_SIZE 1024
#define PRIMENAME "primes.txt"

bool is_prime(int n) {
    if (n <= 1) return false;
    for (int i = 2; i * i <= n; i++)
        if (n % i == 0) return false;
    return true;
}

void sieve_of_eratosthenes(int limit) {
    bool prime[limit + 1];
    memset(prime, true, sizeof(prime));
    for (int i = 2; i * i <= limit; i++) {
        if (prime[i]) {
            for (int j = i * i; j <= limit; j += i)
                prime[j] = false;
        }
    }
    int count = 0;
    for (int i = 2; i <= limit; i++)
        if (prime[i])
            printf("%d ", i), count++;
    printf("\nNumber of primes <= %d: %d\n", limit, count);
}

void save_primes_to_file(int limit) {
    int count = 0;
    FILE *file = fopen(PRIMENAME, "w");
    if (file) {
        for (int i = 2; i <= limit; i++)
            if (is_prime(i)) {
                fprintf(file, "%d ", i);
                count++;
                if (count % 10 == 0) fprintf(file, "\n");
            }
        fclose(file);
        printf("Primes saved to file: %s\n", PRIMENAME);
    } else {
        perror("Error opening file for writing");
    }
}

int main() {
    srand(time(NULL));

    printf("Generating random numbers and checking if they are primes...\n");

    int n, primes_found = 0;
    int *random_numbers = calloc(MAX_PRIME, sizeof(int));

    for (int i = 0; i < MAX_PRIME; i++) {
        n = rand() % MAX_PRIME;
        if (is_prime(n)) {
            printf("Found prime: %d\n", n);
            random_numbers[primes_found++] = n;
        }
    }

    printf("Found %d primes among %d random numbers.\n", primes_found, MAX_PRIME);

    printf("Using Sieve of Eratosthenes to find %d primes...\n", MAX_PRIME);
    sieve_of_eratosthenes(MAX_PRIME);

    printf("Saving %d primes to file...\n", MAX_PRIME);
    save_primes_to_file(MAX_PRIME);

    free(random_numbers);
    return 0;
}

