#define WIDTH 20
#define HEIGHT 20

typedef struct {
    unsigned char r;
    unsigned char g;
    unsigned char b;
} Pixel;

Pixel palette[16] = {
    {0, 0, 0}, {255, 0, 0}, {0, 255, 0}, {0, 0, 255},
    {255, 255, 0}, {0, 255, 255}, {255, 0, 255}, {255, 255, 255},
    {128, 128, 128}, {64, 64, 64}, {255, 128, 128}, {128, 255, 128},
    {128, 128, 255}, {255, 128, 255}, {128, 255, 255}, {255, 128, 128}
};

void generate_pixel(Pixel *pixel) {
    pixel->r = rand() % 256;
    pixel->g = rand() % 256;
    pixel->b = rand() % 256;
}

void print_pixel(Pixel pixel) {
    printf("%d %d %d", pixel.r, pixel.g, pixel.b);
}

void generate_palette(Pixel *palette) {
    for (int i = 0; i < 16; i++) {
        generate_pixel(palette + i);
    }
}

void generate_image(Pixel *image) {
    srand(time(NULL));
    generate_palette(image);

    for (int y = 0; y < HEIGHT; y++) {
        for (int x = 0; x < WIDTH; x++) {
            generate_pixel(image + (y * WIDTH + x));
        }
    }
