#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv)
{
    // Initialize the game board with random live cells
    int board[100][100] = {0};
    for (int i = 0; i < 100; i++)
        for (int j = 0; j < 100; j++)
            board[i][j] = rand() % 2 == 0;

    // Print the initial state of the game board
    for (int i = 0; i < 100; i++)
    {
        for (int j = 0; j < 100; j++)
        {
            if (board[i][j])
                printf("*");
            else
                printf(" ");
        }
        printf("\n");
    }

    // Print the rules of the game of life
    printf("The rules of the game of life are as follows:\n");
    printf("1. Any live cell with fewer than two live neighbours dies, as if caused by under-population.\n");
    printf("2. Any live cell with two or three live neighbours lives on to the next generation.\n");
    printf("3. Any live cell with more than three live neighbours dies, as if by overcrowding.\n");
    printf("4. Any dead cell with exactly three live neighbours becomes a live cell, as if by reproduction.\n");
    printf("\n");

    // Simulate the next generation of the game board
    for (int i = 0; i < 100; i++)
    {
        for (int j = 0; j < 100; j++)
        {
            int numLiveNeighbours = 0;

            // Count the number of live neighbours
            if (i > 0) numLiveNeighbours += board[i-1][j];
            if (i < 99) numLiveNeighbours += board[i+1][j];
            if (j > 0) numLiveNeighbours += board[i][j-1];
            if (j < 99) numLiveNeighbours += board[i][j+1];

            // Apply the rules of the game of life
            if (board[i][j])
            {
                if (numLiveNeighbours < 2 || numLiveNeighbours > 3)
                    board[i][j] = 0;
                else
                    board[i][j] = 1;
            }
            else
            {
                if (numLiveNeighbours == 3)
                    board[i][j] = 1;
            }
        }
    }

    // Print the next generation of the game board
    for (int i = 0; i < 100; i++)
    {
        for (int j = 0; j < 100; j++)
        {
            if (board[i][j])
                printf("*");
            else
                printf(" ");
        }
        printf("\n");
    }

    return 0;
}

