void selectionSort(int arr[], int n)
{
  int i, j;
  int min;

  for (i = 0; i < n; i++)
  {
    min = i;
    for (j = i+1; j < n; j++)
    {
      if (arr[j] < arr[min])
        min = j;
    }
    swap(arr[j],arr[min]);
  }
}


