        printf("Name: %s\n", foundRecord->name);
        printf("Age: %d\n", foundRecord->age);
        printf("City: %s\n", foundRecord->city);
    } else {
        printf("Record not found\n");
    }

    // Free the memory
    free(sys->buckets);
    free(sys);
    return 0;
}

