// Function to check if a line contains any suspicious keywords
int contains_suspicious_keyword(const char *line, const char *keywords[], int num_keywords) {
    for (int i = 0; i < num_keywords; i++) {
        if (strstr(line, keywords[i]) != NULL) {
            return 1; // Suspicious keyword found
        }
    }
    return 0; // No suspicious keywords found
}

// Function to monitor a log file for suspicious activity
void monitor_log_file(const char *log_file_path, const char *keywords[], int num_keywords) {
    FILE *file = fopen(log_file_path, "r");
    if (file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    char line[MAX_LINE_LENGTH];
    int line_number = 0;
    while (fgets(line, sizeof(line), file)) {
        line_number++;
        if (contains_suspicious_keyword(line, keywords, num_keywords)) {
            printf("Suspicious activity detected on line %d: %s", line_number, line);
        }
    }

    fclose(file);
}

// Main function
