#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_SIZE 10
#define NUM_ITERATIONS 1000

void init_grid(int grid[MAX_SIZE][MAX_SIZE]);
void print_grid(int grid[MAX_SIZE][MAX_SIZE]);
int count_neighbors(int grid[MAX_SIZE][MAX_SIZE], int x, int y);
void percolate(int grid[MAX_SIZE][MAX_SIZE]);

int main() {
    int grid[MAX_SIZE][MAX_SIZE];
    srand(time(0));
    init_grid(grid);
    percolate(grid);
    print_grid(grid);
    return 0;
}

void init_grid(int grid[MAX_SIZE][MAX_SIZE]) {
    for (int i = 0; i < MAX_SIZE; i++) {
        for (int j = 0; j < MAX_SIZE; j++) {
            grid[i][j] = rand() % 2;
        }
    }
}

void print_grid(int grid[MAX_SIZE][MAX_SIZE]) {
    for (int i = 0; i < MAX_SIZE; i++) {
        for (int j = 0; j < MAX_SIZE; j++) {
            printf("%d ", grid[i][j]);
        }
        printf("\n");
    }
}

int count_neighbors(int grid[MAX_SIZE][MAX_SIZE], int x, int y) {
    int count = 0;
    if (x > 0 && grid[x-1][y]) count++;
    if (x < MAX_SIZE - 1 && grid[x+1][y]) count++;
    if (y > 0 && grid[x][y-1]) count++;
    if (y < MAX_SIZE - 1 && grid[x][y+1]) count++;
    return count;
}

void percolate(int grid[MAX_SIZE][MAX_SIZE]) {
    for (int i = 0; i < NUM_ITERATIONS; i++) {
        for (int j = 0; j < MAX_SIZE; j++) {
            for (int k = 0; k < MAX_SIZE; k++) {
                int neighbors = count_neighbors(grid, j, k);
                if (grid[j][k] == 1 && neighbors == 0) {
                    grid[j][k] = 0;
                } else if (grid[j][k] == 0 && neighbors >= 3) {
                    grid[j][k] = 1;
                }
            }
        }
    }
}

