/*
 * Imaginary File Encryptor
 * ------------------------
 * This program takes a file as input, encrypts it using a custom algorithm,
 * and then saves the encrypted data to a new file.
 *
 * The encryption algorithm is based on the following steps:
 *
 * 1. The file is divided into chunks of 1024 bytes.
 * 2. Each chunk is encrypted using a simple XOR operation with a secret key.
 * 3. The encrypted chunks are then concatenated together to form the encrypted file.
 *
 * The program also includes a command-line interface for specifying the input and output files,
 * as well as the secret key used for encryption.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define BUFFER_SIZE 1024

// Define the secret key used for encryption
const unsigned char key[] = {0x42, 0x13, 0x37, 0x42, 0x21, 0x43, 0x57, 0x19};

int main(int argc, char *argv[]) {
    // Check for valid command-line arguments
    if (argc != 4) {
        printf("Usage: %s <input file> <output file> <secret key>\n", argv[0]);
        return 1;
    }

    // Open the input file
    FILE *input = fopen(argv[1], "rb");
    if (input == NULL) {
        perror("fopen");
        return 1;
    }

    // Open the output file
    FILE *output = fopen(argv[2], "wb");
    if (output == NULL) {
        perror("fopen");
        fclose(input);
        return 1;
    }

    // Read the input file and encrypt it using the XOR operation
    unsigned char buffer[BUFFER_SIZE];
    while (fread(buffer, 1, BUFFER_SIZE, input) > 0) {
        // Encrypt the chunk using XOR with the secret key
        for (int i = 0; i < BUFFER_SIZE; i++) {
            buffer[i] ^= key[i % sizeof(key)];
        }

        // Write the encrypted chunk to the output file
        if (fwrite(buffer, 1, BUFFER_SIZE, output) != BUFFER_SIZE) {
            perror("fwrite");
            fclose(input);
            fclose(output);
            return 1;
        }
    }

    // Close the input and output files
    fclose(input);
    fclose(output);

    return 0;
}

