        planets[i].vx += ax * dt;
        planets[i].vy += ay * dt;
        planets[i].x += planets[i].vx * dt;
        planets[i].y += planets[i].vy * dt;
    }
}

void drawPlanets(Planet* planets, int numPlanets) {
    for (int i = 0; i < numPlanets; i++) {
        printf("%.2f %.2f\n", planets[i].x, planets[i].y);
    }
}

int main() {
    Planet planets[NUM_PLANETS];
    initPlanets(planets);

    double dt = 1;
    for (int i = 0; i < NUM_STEPS; i++) {
        updatePositions(planets, NUM_PLANETS, dt);
        drawPlanets(planets, NUM_PLANETS);
    }

    return 0;
}

