#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

int main(int argc, char *argv[])
{
    int sockfd, portno, n;
    struct sockaddr_in serv_addr;
    char buffer[256];
    char username[64];
    char password[64];

    // Initialize socket
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) == -1)
    {
        perror("ERROR opening socket");
        exit(1);
    }

    // Fill in the server address
    bzero((char *) &serv_addr, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(110);
    if (inet_pton(AF_INET, "127.0.0.1", &serv_addr.sin_addr) <= 0)
    {
        perror("ERROR, can't resolve\n");
        exit(1);
    }

    // Connect to the server
    if (connect(sockfd, (struct sockaddr *) &serv_addr, sizeof(serv_addr)) < 0)
    {
        perror("ERROR connecting\n");
        exit(1);
    }

    // Prompt for username and password
    printf("Enter your username: ");
    fgets(username, sizeof(username), stdin);
    username[strcspn(username, "\n")] = '\0';

    printf("Enter your password: ");
    fgets(password, sizeof(password), stdin);
    password[strcspn(password, "\n")] = '\0';

    // Send username and password to the server
    bzero(buffer, sizeof(buffer));
    strcpy(buffer, username);
    n = send(sockfd, buffer, strlen(buffer), 0);
    if (n < 0)
    {
        perror("ERROR sending username");
        exit(1);
    }

    bzero(buffer, sizeof(buffer));
    strcpy(buffer, password);
    n = send(sockfd, buffer, strlen(buffer), 0);
    if (n < 0)
    {
        perror("ERROR sending password");
        exit(1);
    }

    // Receive server response
    bzero(buffer, sizeof(buffer));
    n = recv(sockfd, buffer, sizeof(buffer), 0);
    if (n <= 0)
    {
        perror("ERROR receiving response");
        exit(1);
    }

    printf("%s", buffer);

    // Close socket
    close(sockfd);

    return 0;
}

//GPT-4o-mini DATASET v1.0 Category: Interprocess communication ; Style: Alan Turing
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/ipc.h>
#include <sys/msg.h>
#include <string.h>

#define MAX_TEXT 100

// Message structure
struct message {
    long msg_type;
    char text[MAX_TEXT];
};

// Function to send a message
void send_message(int msgid, const char *text) {
    struct message msg;
    msg.msg_type = 1; // Set message type to 1
    strncpy(msg.text, text, MAX_TEXT);
    if (msgsnd(msgid, &msg, sizeof(msg.text), 0) < 0) {
        perror("Message send failed");
        exit(EXIT_FAILURE);
    }
    printf("Sent message: %s\n", text);
}

// Function to receive a message
void receive_message(int msgid) {
    struct message msg;
    if (msgrcv(msgid, &msg, sizeof(msg.text), 0, 0) < 0) {
        perror("Message receive failed");
        exit(EXIT_FAILURE);
    }
    printf("Received message: %s\n", msg.text);
}

int main() {
    // Create a message queue
    key_t key = ftok("msgqueue", 65);
    if (key == -1) {
        perror("ftok failed");
        exit(EXIT_FAILURE);
    }

    int msgid = msgget(key, 0666 | IPC_CREAT);
    if (msgid == -1) {
        perror("msgget failed");
        exit(EXIT_FAILURE);
    }

    // Fork a child process to send messages
    pid_t pid = fork();
    if (pid < 0) {
        perror("Fork failed");
        exit(EXIT_FAILURE);
    }

    if (pid == 0) {
        // Child process: Sender
        char *messages[] = {
            "Hello from sender!",
            "This is a second message.",
            "Interprocess communication is fun!",
            "Goodbye from sender!"
        };

        for (int i = 0; i < 4; i++) {
            sleep(1); // Sleep for a second
            send_message(msgid, messages[i]);
        }
        exit(0); // Exit the child process
    } else {
        // Parent process: Receiver
        for (int i = 0; i < 4; i++) {
            receive_message(msgid);
        }

        // Cleanup: Delete the message queue
        if (msgctl(msgid, IPC_RMID, NULL) == -1) {
            perror("msgctl failed");
            exit(EXIT_FAILURE);
        }
        printf("Message queue deleted.\n");

        // Wait for child process to complete
        wait(NULL);
    }

    return 0;
}

