#include <math.h>

#define MAX_LINE_LENGTH 1000
#define MAX_TOKEN_LENGTH 50

enum {
    CELSIUS = 0,
    FAHRENHEIT
} temperature_scale;

double convert_temperature(double temperature, int from_scale, int to_scale) {
    switch (from_scale) {
        case CELSIUS:
            switch (to_scale) {
                case CELSIUS:
                    return temperature;
                case FAHRENHEIT:
                    return temperature * 1.8 + 32;
                default:
                    return -1;
            }
        case FAHRENHEIT:
            switch (to_scale) {
                case CELSIUS:
                    return (temperature - 32) / 1.8;
                case FAHRENHEIT:
                    return temperature;
                default:
                    return -1;
            }
        default:
            return -1;
    }
}

int main(int argc, char *argv[]) {
    if (argc!= 4) {
        printf("Usage: %s <temperature> <from_scale> <to_scale>\n", argv[0]);
        return 1;
