#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LEN 1024
#define MAX_IDENTIFIERS 100

typedef struct {
    char name[MAX_IDENTIFIERS];
    int line_number;
} identifier;

void extract_metadata(char *filename) {
    FILE *file;
    char line[MAX_LINE_LEN];
    char *token;
    int identifier_count = 0;
    identifier identifiers[MAX_IDENTIFIERS];

    file = fopen(filename, "r");

    if (file == NULL) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    while (fgets(line, MAX_LINE_LEN, file)) {
        token = strtok(line, " \t\n");

        if (token && token[0] != ';' && identifier_count < MAX_IDENTIFIERS) {
            strcpy(identifiers[identifier_count].name, token);
            identifiers[identifier_count].line_number = __LINE__;
            identifier_count++;
        }
    }

    fclose(file);

    printf("Metadata extracted from %s:\n", filename);

    for (int i = 0; i < identifier_count; i++) {
        printf("%s: line %d\n", identifiers[i].name, identifiers[i].line_number);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s <filename>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    extract_metadata(argv[1]);

