typedef struct {
    uint8_t data[32];
} BitVector;

void init_bitvector(BitVector *bitvector) {
    memset(bitvector->data, 0, sizeof(bitvector->data));
}

bool get_bit(const BitVector *bitvector, size_t index) {
    return (bitvector->data[index / CHAR_BIT] & (1 << (index % CHAR_BIT))) != 0;
}

void set_bit(BitVector *bitvector, size_t index) {
    bitvector->data[index / CHAR_BIT] |= (1 << (index % CHAR_BIT));
}

void clear_bit(BitVector *bitvector, size_t index) {
    bitvector->data[index / CHAR_BIT] &= ~(1 << (index % CHAR_BIT));
}

void toggle_bit(BitVector *bitvector, size_t index) {
    bitvector->data[index / CHAR_BIT] ^= (1 << (index % CHAR_BIT));
}

void print_bitvector(const BitVector *bitvector) {
    size_t i;
    for (i = 0; i < sizeof(bitvector->data); i++) {
        printf("%02x", bitvector->data[i]);
        if (i != sizeof(bitvector->data) - 1)
            printf(" ");
    }
    printf("\n");
}

