#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

int main() {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket");
        exit(1);
    }
    struct sockaddr_in servaddr;
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(80);
    servaddr.sin_addr.s_addr = htonl(INADDR_ANY);
    if (bind(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("bind");
        exit(1);
    }
    if (listen(sockfd, 5) < 0) {
        perror("listen");
        exit(1);
    }
    while (1) {
        struct sockaddr_in cliaddr;
        socklen_t len = sizeof(cliaddr);
        int connfd = accept(sockfd, (struct sockaddr *)&cliaddr, &len);
        if (connfd < 0) {
            perror("accept");
            continue;
        }
        char buf[1024];
        int n = read(connfd, buf, sizeof(buf));
        if (n < 0) {
            perror("read");
            continue;
        }
        char *s = strstr(buf, "HTTP/1.1");
        if (!s) {
            continue;
        }
        char *t = strstr(s, "\r\n");
        if (!t) {
            continue;
        }
        *t = '\0';
        char *uri = s + 4;
        char *path = malloc(strlen(uri) + 1);
        strcpy(path, uri);
        char *q = strchr(path, '?');
        if (q) {
            *q = '\0';
        }
        FILE *fp = fopen(path, "r");
        if (!fp) {
            fprintf(connfd, "HTTP/1.1 404 Not Found\r\nContent-Type: text/html\r\n\r\n<h1>404 Not Found</h1>");
            continue;
        }
        fseek(fp, 0, SEEK_END);
        long size = ftell(fp);
        rewind(fp);
        char *mime = "text/html";
        if (strstr(path, ".css")) {
            mime = "text/css";
        } else if (strstr(path, ".js")) {
            mime = "text/javascript";
        } else if (strstr(path, ".jpg")) {
            mime = "image/jpeg";
        } else if (strstr(path, ".png")) {
            mime = "image/png";
        }
        fprintf(connfd, "HTTP/1.1 200 OK\r\nContent-Type: %s\r\nContent-Length: %ld\r\n\r\n", mime, size);
        while ((n = fread(buf, 1, sizeof(buf), fp)) > 0) {
            write(connfd, buf, n);
        }
        fclose(fp);
        free(path);
        close(connfd);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
