};

void randomize() {
    time_t t;

    time(&t);
    srand((unsigned int)t);
}

void generate_password(char* password) {
    int i, j, index1, index2;

    for (i = 0; i < PASSWORD_LENGTH; i++) {
        if (i % 2 == 0) {
            index1 = rand() % CHAR_COUNT;
            password[i] = password_chars[index1];
