#include <stdio.h>
#include <stdlib.h>

#define MAX_SIZE 1000

// structure to hold data
typedef struct {
    int data;
    int index;
} Data;

// function to allocate memory for a new data structure
Data* allocateData() {
    Data* newData = (Data*)malloc(sizeof(Data));
    if (newData == NULL) {
        printf("Error: Could not allocate memory for new data structure.\n");
        return NULL;
    }
    return newData;
}

// function to free memory for a data structure
void freeData(Data* data) {
    free(data);
}

// function to print the contents of the data structure
void printData(Data* data) {
    printf("Data: %d, Index: %d\n", data->data, data->index);
}

// function to manage memory for a list of data structures
void manageMemory(Data** list, int size) {
    // loop through the list and free memory for each data structure
    for (int i = 0; i < size; i++) {
        freeData(list[i]);
    }
    // free memory for the list itself
    free(list);
}

int main() {
    Data** list = (Data**)malloc(MAX_SIZE * sizeof(Data*));
    if (list == NULL) {
        printf("Error: Could not allocate memory for list.\n");
        return 1;
    }

    // initialize the list with NULL pointers
    for (int i = 0; i < MAX_SIZE; i++) {
        list[i] = NULL;
    }

    // allocate memory for some data structures and add them to the list
    list[0] = allocateData();
    if (list[0]!= NULL) {
        list[0]->data = 1;
        list[0]->index = 0;
    }
    list[1] = allocateData();
    if (list[1]!= NULL) {
        list[1]->data = 2;
        list[1]->index = 1;
    }

    // print the contents of the data structures in the list
    printf("List contents:\n");
    for (int i = 0; i < MAX_SIZE; i++) {
        if (list[i]!= NULL) {
            printData(list[i]);
        }
    }

    // free memory for the list and its data structures
    manageMemory(list, MAX_SIZE);

    return 0;
}

