void reshape( int w, int h )
{
    if( h == 0 )h = 1;

    glMatrixMode( GL_PROJECTION );
    glLoadIdentity();

    glOrtho( 0, (float)w, 0, (float)h, -1., 1. );
    glViewport( 0, 0, w, h );

    window_width = w;
    window_height = h;

    glutPostRedisplay();
}

