int MergeAuxSort(int a[], int temp[], int left, int right)sortAndMerge
{
  int middle;
  int count_inversion = 0;

  if (right > left)
  {
   //se imparte vectorul in 2 si se apeleaza MergeAuxSort pentru fiecare parte
    middle = (right + left)/2;

