#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAX_SIZE 1000000

// Function to perform binary search
int binary_search(int arr[], int size, int target) {
    int left = 0;
    int right = size - 1;
    int mid;

    while (left <= right) {
        mid = (left + right) / 2;

        if (arr[mid] == target) {
            return mid;
        } else if (arr[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    return -1;
}

int main() {
    int arr[MAX_SIZE];

    // Generate random array
    for (int i = 0; i < MAX_SIZE; i++) {
        arr[i] = rand() % MAX_SIZE;
    }

    // Sort array
    for (int i = 0; i < MAX_SIZE; i++) {
        for (int j = i + 1; j < MAX_SIZE; j++) {
            if (arr[i] > arr[j]) {
                int temp = arr[i];
                arr[i] = arr[j];
                arr[j] = temp;
            }
        }
    }

    // Get user input
    int target;

    printf("Enter target number: ");
    scanf("%d", &target);

    // Perform binary search
    int result = binary_search(arr, MAX_SIZE, target);

    // Print result
    if (result == -1) {
        printf("Number not found in array.\n");
    } else {
        printf("Number found at position %d.\n", result);
    }

    return 0;
}

