#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <ctype.h>

int sentiment_analysis(char *sentence)
{
  int score = 0;
  int i = 0;
  char ch;

  // Iterate over the sentence
  while (sentence[i] != '\0')
  {
    ch = sentence[i];

    // Normalize character
    ch = tolower(ch);

    // Positive words
    if (ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u')
    {
      score++;
    }

    // Negative words
    else if (ch == 'c' || ch == 'f' || ch == 'h' || ch == 'n' || ch == 'p' || ch == 'r')
    {
      score--;
    }

    // Neutral words
    else
    {
      score = score;
    }

    i++;
  }

  return score;
}

int main()
{
  char sentence[100];

  // Get the sentence from the user
  printf("Enter a sentence: ");
  fgets(sentence, 100, stdin);

  // Analyze the sentiment of the sentence
  int sentiment = sentiment_analysis(sentence);

  // Print the sentiment score
  if (sentiment > 0)
  {
    printf("The sentiment of the sentence is positive.\n");
  }
  else if (sentiment < 0)
  {
    printf("The sentiment of the sentence is negative.\n");
  }
  else
  {
    printf("The sentiment of the sentence is neutral.\n");
  }

  return 0;
}

