#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_WIDTH 50
#define MAX_HEIGHT 20

int main()
{
    // Initialize game variables
    int x = 0, y = 0, direction = 1, speed = 1, score = 0;
    char board[MAX_WIDTH][MAX_HEIGHT] = {{0}};

    // Create the invader
    board[x][y] = 'I';

    // Initialize the border
    for (int i = 0; i < MAX_WIDTH; i++)
    {
        board[0][i] = '#';
        board[MAX_HEIGHT - 1][i] = '#';
    }

    for (int i = 0; i < MAX_HEIGHT; i++)
    {
        board[i][0] = '#';
        board[i][MAX_WIDTH - 1] = '#';
    }

    // Game loop
    while (!board[y][x] && direction)
    {
        // Move the invader
        switch (direction)
        {
            case 1:
                x++;
                break;
            case 2:
                x--;
                break;
            case 3:
                y++;
                break;
            case 4:
                y--;
                break;
        }

        // Check if the invader has reached the border
        if (board[y][x] == '#')
        {
            direction = 0;
        }

        // Draw the board
        system("clear");
        for (int i = 0; i < MAX_HEIGHT; i++)
        {
            for (int j = 0; j < MAX_WIDTH; j++)
            {
                printf("%c ", board[i][j]);
            }
            printf("\n");
        }

        // Update the score
        score++;

        // Sleep for a while
        sleep(speed);
    }

    // Game over
    system("clear");
    printf("Game over! Your score is: %d", score);

    return 0;
}

