#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define BUFFER_SIZE 1024
#define CAT_LANG_WORDS 15

// Structure to hold a translation mapping from English to Cat Language
typedef struct {
    char *english;
    char *catLanguage;
} Translation;

// Cat language translations
Translation dictionary[CAT_LANG_WORDS] = {
    {"hello", "meow"},
    {"friend", "purr"},
    {"food", "mow"},
    {"play", "hiss"},
    {"sleep", "nap"},
    {"love", "nuzzle"},
    {"yes", "pounce"},
    {"no", "hiss"},
    {"bath", "scram"},
    {"mouse", "catch"},
    {"ball", "chase"},
    {"toy", "swipe"},
    {"window", "watch"},
    {"outside", "explore"},
    {"home", "cuddle"}
};

// Function to translate a single word to Cat Language
const char* translateWord(const char *word) {
    for (int i = 0; i < CAT_LANG_WORDS; i++) {
        if (strcmp(word, dictionary[i].english) == 0) {
            return dictionary[i].catLanguage;
        }
    }
    return word; // Return the original word if no translation found
}

// Function to translate a sentence to Cat Language
void translateSentence(const char *sentence, char *translated) {
    char *token;
    char sentenceCopy[BUFFER_SIZE];
    strcpy(sentenceCopy, sentence); // Make a mutable copy of the input

    // Start tokenizing the sentence
    token = strtok(sentenceCopy, " ");
    while (token != NULL) {
        // Translate the current word
        const char *translatedWord = translateWord(token);
        strcat(translated, translatedWord);
        strcat(translated, " "); // Add space between words
        token = strtok(NULL, " "); // Move to next word
    }
}

// Main function to drive the program
int main() {
    char inputSentence[BUFFER_SIZE];
    char translatedSentence[BUFFER_SIZE] = ""; // Buffer for the translated sentence

    printf("Welcome to the Cat Language Translator!\n");
    printf("Type a sentence to translate into Cat Language (type 'exit' to quit):\n");

    while (1) {
        printf("> ");
        fgets(inputSentence, BUFFER_SIZE, stdin);

        // Remove newline character at the end
        inputSentence[strcspn(inputSentence, "\n")] = 0;

        // Exit the program
        if (strcmp(inputSentence, "exit") == 0) {
            printf("Thank you for using the Cat Language Translator! Goodbye!\n");
            break;
        }

        // Translate the input sentence
        translateSentence(inputSentence, translatedSentence);

        // Output the translated sentence
        printf("In Cat Language: %s\n\n", translatedSentence);

        // Clear the translated sentence buffer for the next iteration
        memset(translatedSentence, 0, BUFFER_SIZE);
    }

    return 0;
}

