#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define KEY "my_secret_key"
#define BLOCK_SIZE 16

void encrypt(unsigned char *plaintext, unsigned char *ciphertext, int len) {
    int i, j;
    unsigned char key[BLOCK_SIZE];
    unsigned char iv[BLOCK_SIZE];

    // Initialize the key and iv
    for (i = 0; i < BLOCK_SIZE; i++) {
        key[i] = KEY[i % strlen(KEY)];
        iv[i] = 0;
    }

    // Encrypt the plaintext
    for (i = 0; i < len; i += BLOCK_SIZE) {
        for (j = 0; j < BLOCK_SIZE; j++) {
            ciphertext[i + j] = plaintext[i + j] ^ key[j] ^ iv[j];
        }

        // Update the iv
        for (j = 0; j < BLOCK_SIZE; j++) {
            iv[j] = ciphertext[i + j];
        }
    }
}

void decrypt(unsigned char *ciphertext, unsigned char *plaintext, int len) {
    int i, j;
    unsigned char key[BLOCK_SIZE];
    unsigned char iv[BLOCK_SIZE];

    // Initialize the key and iv
    for (i = 0; i < BLOCK_SIZE; i++) {
        key[i] = KEY[i % strlen(KEY)];
        iv[i] = 0;
    }

    // Decrypt the ciphertext
    for (i = 0; i < len; i += BLOCK_SIZE) {
        for (j = 0; j < BLOCK_SIZE; j++) {
            plaintext[i + j] = ciphertext[i + j] ^ key[j] ^ iv[j];
        }

        // Update the iv
        for (j = 0; j < BLOCK_SIZE; j++) {
            iv[j] = ciphertext[i + j];
        }
    }
}

int main(int argc, char *argv[]) {
    // Check the arguments
    if (argc != 3) {
        printf("Usage: %s <input file> <output file>\n", argv[0]);
        return 1;
    }

    // Read the input file
    FILE *input = fopen(argv[1], "rb");
    if (input == NULL) {
        printf("Error opening input file: %s\n", argv[1]);
        return 1;
    }

    // Get the input file size
    fseek(input, 0, SEEK_END);
    int input_size = ftell(input);
    rewind(input);

    // Allocate memory for the input and output buffers
    unsigned char *input_buffer = malloc(input_size);
    if (input_buffer == NULL) {
        printf("Error allocating memory for input buffer\n");
        fclose(input);
        return 1;
    }

    unsigned char *output_buffer = malloc(input_size);
    if (output_buffer == NULL) {
        printf("Error allocating memory for output buffer\n");
        free(input_buffer);
        fclose(input);
        return 1;
    }

    // Read the input file into the input buffer
    fread(input_buffer, 1, input_size, input);
    fclose(input);

    // Encrypt the input buffer
    encrypt(input_buffer, output_buffer, input_size);

    // Write the output buffer to the output file
    FILE *output = fopen(argv[2], "wb");
    if (output == NULL) {
        printf("Error opening output file: %s\n", argv[2]);
        free(input_buffer);
        free(output_buffer);
        return 1;
    }

    fwrite(output_buffer, 1, input_size, output);
    fclose(output);

    // Decrypt the output buffer
    decrypt(output_buffer, input_buffer, input_size);

    // Compare the input and output buffers
    if (memcmp(input_buffer, output_buffer, input_size) != 0) {
        printf("Error: the input and output buffers do not match\n");
        free(input_buffer);
        free(output_buffer);
        return 1;
    }

    // Free the input and output buffers
    free(input_buffer);
    free(output_buffer);

    return 0;
}

