/*
 * C File Synchronizer
 *
 * A program that synchronizes the contents of two files.
 *
 * Usage:
 *   ./filesync <file1> <file2>
 *
 * Example:
 *   ./filesync file1.txt file2.txt
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define BUFFER_SIZE 1024

int main(int argc, char *argv[]) {
  if (argc != 3) {
    printf("Usage: %s <file1> <file2>\n", argv[0]);
    return 1;
  }

  FILE *file1 = fopen(argv[1], "r");
  if (file1 == NULL) {
    printf("Error opening file %s\n", argv[1]);
    return 1;
  }

  FILE *file2 = fopen(argv[2], "r");
  if (file2 == NULL) {
    printf("Error opening file %s\n", argv[2]);
    fclose(file1);
    return 1;
  }

  char buffer1[BUFFER_SIZE];
  char buffer2[BUFFER_SIZE];

  while (1) {
    int read1 = fread(buffer1, 1, BUFFER_SIZE, file1);
    int read2 = fread(buffer2, 1, BUFFER_SIZE, file2);

    if (read1 != read2) {
      printf("Error: File sizes do not match\n");
      break;
    }

    if (read1 == 0) {
      break;
    }

    if (memcmp(buffer1, buffer2, read1) != 0) {
      printf("Error: Files do not match\n");
      break;
    }
  }

  fclose(file1);
  fclose(file2);

  return 0;
}

