#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Dimensions of the maze
#define WIDTH 20
#define HEIGHT 10

// Maze cell states
#define WALL '#'
#define PATH ' '
#define VISITED '.'

char maze[HEIGHT][WIDTH];

// Function prototypes
void initializeMaze();
void generateMaze(int x, int y);
void printMaze();
void clearScreen();

// Main function
int main() {
    srand(time(NULL)); // Seed for random generation
    initializeMaze();
    generateMaze(1, 1); // Start generating maze from (1,1)
    clearScreen();
    printMaze();
    return 0;
}

// Function to initialize the maze with walls
void initializeMaze() {
    for (int i = 0; i < HEIGHT; i++) {
        for (int j = 0; j < WIDTH; j++) {
            if (i % 2 == 0 || j % 2 == 0) {
                maze[i][j] = WALL; // Place walls on even indices
            } else {
                maze[i][j] = PATH; // Place path on odd indices
            }
        }
    }
}

// Function to generate the maze using recursive backtracking
void generateMaze(int x, int y) {
    // Define the direction vectors
    int directions[4][2] = {
        {2, 0},  // Down
        {0, 2},  // Right
        {-2, 0}, // Up
        {0, -2}  // Left
    };

    // Shuffle directions to create randomness
    for (int i = 0; i < 4; i++) {
        int j = rand() % 4;
        int temp[2] = { directions[i][0], directions[i][1] };
        directions[i][0] = directions[j][0];
        directions[i][1] = directions[j][1];
        directions[j][0] = temp[0];
        directions[j][1] = temp[1];
    }

    // Mark the cell as visited
    maze[y][x] = VISITED;

    // Explore each direction
    for (int i = 0; i < 4; i++) {
        int nx = x + directions[i][0];
        int ny = y + directions[i][1];

        // Check if the next cell is within bounds and a path
        if (ny > 0 && ny < HEIGHT && nx > 0 && nx < WIDTH && maze[ny][nx] == PATH) {
            // Remove wall between current cell and next cell
            maze[y + directions[i][0] / 2][x + directions[i][1] / 2] = PATH;
            generateMaze(nx, ny); // Recursively generate maze from new position
        }
    }
}

// Function to print the maze
void printMaze() {
    for (int i = 0; i < HEIGHT; i++) {
        for (int j = 0; j < WIDTH; j++) {
            putchar(maze[i][j]);
        }
        putchar('\n');
    }
}

