#include <stdio.h>
#include <stdlib.h>
#include <math.h>

// Define structure for 2D point
struct point {
    double x;
    double y;
};

// Define structure for 2D vector
struct vector {
    double x;
    double y;
};

// Define structure for 2D triangle
struct triangle {
    struct point p1;
    struct point p2;
    struct point p3;
};

// Function to calculate the area of a triangle
double triangle_area(struct triangle t) {
    struct vector v1 = {t.p2.x - t.p1.x, t.p2.y - t.p1.y};
    struct vector v2 = {t.p3.x - t.p1.x, t.p3.y - t.p1.y};
    double area = (v1.x * v2.y - v1.y * v2.x) / 2;
    return area;
}

// Function to calculate the perimeter of a triangle
double triangle_perimeter(struct triangle t) {
    double side1 = sqrt((t.p2.x - t.p1.x) * (t.p2.x - t.p1.x) + (t.p2.y - t.p1.y) * (t.p2.y - t.p1.y));
    double side2 = sqrt((t.p3.x - t.p2.x) * (t.p3.x - t.p2.x) + (t.p3.y - t.p2.y) * (t.p3.y - t.p2.y));
    double side3 = sqrt((t.p1.x - t.p3.x) * (t.p1.x - t.p3.x) + (t.p1.y - t.p3.y) * (t.p1.y - t.p3.y));
    double perimeter = side1 + side2 + side3;
    return perimeter;
}

// Function to calculate the centroid of a triangle
struct point triangle_centroid(struct triangle t) {
    struct point centroid;
    centroid.x = (t.p1.x + t.p2.x + t.p3.x) / 3;
    centroid.y = (t.p1.y + t.p2.y + t.p3.y) / 3;
    return centroid;
}

// Function to calculate the circumcenter of a triangle
struct point triangle_circumcenter(struct triangle t) {
    struct point circumcenter;
    double x1 = t.p1.x;
    double y1 = t.p1.y;
    double x2 = t.p2.x;
    double y2 = t.p2.y;
    double x3 = t.p3.x;
    double y3 = t.p3.y;
    double a = x1 * (y2 - y3) - y1 * (x2 - x3) + x2 * y3 - x3 * y2;
    double b = 2 * (x1 * (y3 - y2) - y1 * (x3 - x2) + x2 * y3 - x3 * y2);
    double c = x1 * (y2 - y3) - y1 * (x2 - x3) + x2 * y3 - x3 * y2;
    double x = (b * b - 4 * a * c) / (4 * a * a);
    double y = (2 * b * c - b * b) / (4 * a);
    circumcenter.x = x;
    circumcenter.y = y;
    return circumcenter;
}

// Function to calculate the orthocenter of a triangle
struct point triangle_orthocenter(struct triangle t) {
    struct point orthocenter;
    double x1 = t.p1.x;
    double y1 = t.p1.y;
    double x2 = t.p2.x;
    double y2 = t.p2.y;
    double x3 = t.p3.x;
    double y3 = t.p3.y;
    double a = x1 * (y2 - y3) - y1 * (x2 - x3) + x2 * y3 - x3 * y2;
    double b = 2 * (x1 * (y3 - y2) - y1 * (x3 - x2) + x2 * y3 - x3 * y2);
    double c = x1 * (y2 - y3) - y1 * (x2 - x3) + x2 * y3 - x3 * y2;
    double x = (b * b - 4 * a * c) / (4 * a * a);
    double y = (2 * b * c - b * b) / (4 * a);
    orthocenter.x = x;
    orthocenter.y = y;
    return orthocenter;
}

int main() {
    struct triangle t = {
        {1, 1},
        {2, 2},
        {3, 3}
    };

    double area = triangle_area(t);
    double perimeter = triangle_perimeter(t);
    struct point centroid = triangle_centroid(t);
    struct point circumcenter = triangle_circumcenter(t);
    struct point orthocenter = triangle_orthocenter(t);

    printf("Area: %lf\n", area);
    printf("Perimeter: %lf\n", perimeter);
    printf("Centroid: (%lf, %lf)\n", centroid.x, centroid.y);
    printf("Circumcenter: (%lf, %lf)\n", circumcenter.x, circumcenter.y);
    printf("Orthocenter: (%lf, %lf)\n", orthocenter.x, orthocenter.y);

    return 0;
}

