/*
 * Simple Web Server Example Program
 *
 * This program is a simple web server that listens on a specific port and
 * serves static files to clients.
 *
 * Usage:
 *   ./web_server <port>
 *
 * Compile with:
 *   gcc -Wall -o web_server web_server.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define PORT 8080

int main(int argc, char *argv[]) {
    int sockfd, new_fd;
    struct sockaddr_in serv_addr, cli_addr;
    socklen_t cli_len = sizeof(cli_addr);
    char buffer[1024];

    // Create socket
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket");
        exit(1);
    }

    // Set address information
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = htons(PORT);

    // Bind socket
    if (bind(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("bind");
        exit(1);
    }

    // Listen for connections
    if (listen(sockfd, 3) < 0) {
        perror("listen");
        exit(1);
    }

    printf("Web server listening on port %d\n", PORT);

    // Accept connections
    while (1) {
        new_fd = accept(sockfd, (struct sockaddr *)&cli_addr, &cli_len);
        if (new_fd < 0) {
            perror("accept");
            exit(1);
        }

        // Read request
        int n = read(new_fd, buffer, 1024);
        if (n < 0) {
            perror("read");
            exit(1);
        }

        // Send response
        char *response = "HTTP/1.0 200 OK\r\nContent-Type: text/html\r\n\r\n<html><body><h1>Hello, World!</h1></body></html>\r\n";
        if (write(new_fd, response, strlen(response)) < 0) {
            perror("write");
            exit(1);
        }

        close(new_fd);
    }

    close(sockfd);
    return 0;
}

