	for (int k = 0; k < count; k++) {
		for (int j = 0; j < count; j++) {
			if (student[k].total > student[j].total) {
				student[count + 1] = student[k];
				student[k] = student[j];
				student[j] = student[count + 1];
			}
		}
	}
}

