	vector<int> * adj = new vector<int> [n];
	int * father = new int [n];
	int * dist = new int [n];
	int border[2];
	int chuck [6];
	int join[2][2];
	int diameter, min = n, minChuck = 0;

    //popolo il grafo
    for(int i=0; i<m; i++) {
