void*  firstfit_method(size_t sz)
{
	struct block* q = nullptr;
	struct block* p = nullptr;
	size_t  k = 0;
	void*   out = nullptr;

	//A1.[Intialize]
	q = (struct block*)avail;

A2: //.[End Of List]
	p = q->link;
	if(p == nullptr)
	{
		return nullptr;
	}	

	//A3.[Is SIZE enough]
	if(p->size >= sz)
	{
		// A4:[Reserve N.]
		k = p->size - sz;
		if(k == 0)
		{
			q->link = p->link;
		}
		else
		{
			p->size = k;
		}
		out = (char*)p + k;
		return (void*)out;
	}
	else
	{
		q = p;
		goto A2;
	}

}




