    // Draw Sun
    printf("Sun\n");
    for (int i = 0; i < SUN_RADIUS; i++) {
        printf("  ");
    }
    printf("O\n");

    // Draw Planets
    for (int i = 0; i < NUM_PLANETS; i++) {
        float angle = (time / planets[i].orbit_time) * 2 * M_PI;
        int posX = (int)(planets[i].distance_from_sun * cos(angle));
        int posY = (int)(planets[i].distance_from_sun * sin(angle));

