        // Print additional spaces based on size
        for (int j = 0; j < (planets[i].size * SCALE); j++) {
            printf(" ");
        }
        printf("O\n");
    }

    // Delay for better visualization
    usleep(500000); // Sleep for 0.5 seconds
}

