#define MAX_NAME_LEN 50
#define MAX_AGE 150
#define MAX_ROWS 100

typedef struct {
    char name[MAX_NAME_LEN];
    int age;
} Person;

typedef struct {
    Person data[MAX_ROWS];
    int num_rows;
} Table;

void init_table(Table* t) {
    t->num_rows = 0;
}

int add_person(Table* t, const char* name, int age) {
    if (t->num_rows >= MAX_ROWS) {
        printf("Table is full.\n");
        return -1;
    }

    strncpy(t->data[t->num_rows].name, name, MAX_NAME_LEN);
    t->data[t->num_rows].age = age;
    t->num_rows++;

    return 0;
}

int query_by_name(Table* t, const char* name) {
    for (int i = 0; i < t->num_rows; i++) {
        if (strcmp(t->data[i].name, name) == 0) {
            printf("Name: %s\nAge: %d\n", t->data[i].name, t->data[i].age);
            return 0;
        }
    }

    printf("No results found.\n");
    return -1;
}

int query_by_age(Table* t, int age) {
    for (int i = 0; i < t->num_rows; i++) {
        if (t->data[i].age == age) {
            printf("Name: %s\nAge: %d\n", t->data[i].name, t->data[i].age);
            return 0;
        }
    }

    printf("No results found.\n");
    return -1;
}

