#define MAX 100

void nhap (int a[], int &n)
{
    do
    {
        printf("\nNhap so phan tu: ");
        scanf("%d", &n);
        if(n <= 0 || n > MAX)
        {
            printf("\nSo phan tu khong hop le. Xin kiem tra lai !");
        }
    }while(n <= 0 || n > MAX);
    for(int i = 0; i < n; i++)
    {
        printf("\nNhap a[%d]: ", i);
        scanf("%d", &a[i]);
    }
}

void xuat(int a[], int n)
{
    for(int i = 0; i < n; i++)
    {
            printf("%4d", a[i]);
    }
}

void TimMinMax(int a[], int n, int &max, int &min)
{
    max = a[0];
    min = a[0];
    for(int i = 1; i < n; i++)
    {
        max = (a[i] > max) ? a[i] : max;
        min = (a[i] < min) ? a[i] : min;
    }
}

void DoiMaxBangMinVaNguocLai(int a[], int n, int max, int min)
{
    for(int i = 0; i < n; i++)
    {
        if(a[i] == max)
        {
            a[i] = min;
        }
        else if(a[i] == min)
        {
            a[i] = max;
        }
    }
}
int main()
{
    int n, min, max;
    int a[MAX];

    nhap(a, n);
    xuat(a, n);
    TimMinMax(a, n, max, min);
    printf("\nDao nguoc min bang max va nguoc lai: ");
    DoiMaxBangMinVaNguocLai(a, n, max, min);
    xuat(a, n);


    getch();
    return 0;
}

//FormAI DATASET v1.0 Category: Email Client ; Style: recursive
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct email {
    char *from;
    char *to;
    char *subject;
    char *message;
    struct email *next;
};

struct email *createEmail(char *from, char *to, char *subject, char *message) {
    struct email *newemail = malloc(sizeof(struct email));
    newemail->from = strdup(from);
    newemail->to = strdup(to);
    newemail->subject = strdup(subject);
    newemail->message = strdup(message);
    newemail->next = NULL;

    return newemail;
}

struct email *addEmail(struct email *head, char *from, char *to, char *subject, char *message) {
    if (head == NULL) {
        return createEmail(from, to, subject, message);
    }

    head->next = addEmail(head->next, from, to, subject, message);

    return head;
}

void printEmail(struct email *email) {
    printf("From: %s\nTo: %s\nSubject: %s\nMessage: %s\n", email->from, email->to, email->subject, email->message);
}

void printAllEmails(struct email *head) {
    if (head == NULL) {
        printf("No emails found.\n");
        return;
    }

    printEmail(head);
    printf("\n");

    printAllEmails(head->next);
}

void deleteEmail(struct email *head, char *search) {
    if (head == NULL) {
        printf("Email not found.\n");
        return;
    }

    if (strcmp(head->subject, search) == 0) {
        struct email *temp = head;
        head = head->next;
        free(temp);
        printf("Email deleted.\n");
        return;
    }

    deleteEmail(head->next, search);
}

int main() {
    struct email *head = NULL;

    head = addEmail(head, "user1@example.com", "user2@example.com", "Meeting Recap", "Hello, here is the summary of our meeting:\n- Discussed project timeline\n- Assigned tasks for next week\n\nBest,\nUser1");
    head = addEmail(head, "user2@example.com", "user1@example.com", "Project Update", "Hey User1,\nJust wanted to update you on the project status. We are making good progress and should have everything done on time.\n\nThanks,\nUser2");
    head = addEmail(head, "user3@example.com", "user1@example.com", "Question about project", "Hi User1,\nI had a question about the project. Are we planning on using the new API for this?\n\nThanks,\nUser3");

    printf("All Emails:\n");
    printAllEmails(head);

    deleteEmail(head, "Project Update");

    printf("\nUpdated Emails:\n");
    printAllEmails(head);

    return 0;
}

//LLAMA2-13B DATASET v1.0 Category: Hotel Management System ; Style: brave
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_GUESTS 100
#define MAX_ROOMS 20

struct guest {
    char name[50];
    char email[50];
    int checkin;
    int checkout;
    int room_id;
};

struct room {
    char name[50];
    int capacity;
    int available;
    struct guest *guests;
};

struct hotel {
    char name[50];
    int num_rooms;
    struct room rooms[MAX_ROOMS];
};

void init_hotel(struct hotel *hotel) {
    int i;
    for (i = 0; i < MAX_ROOMS; i++) {
        hotel->rooms[i].available = hotel->rooms[i].capacity;
    }
}

void add_guest(struct hotel *hotel, struct guest *guest) {
    int i;
    for (i = 0; i < MAX_ROOMS; i++) {
        if (hotel->rooms[i].available > 0) {
            guest->room_id = i;
            hotel->rooms[i].available--;
            break;
        }
    }
}

void check_in(struct hotel *hotel, struct guest *guest) {
    guest->checkin = clock();
}

void check_out(struct hotel *hotel, struct guest *guest) {
    guest->checkout = clock();
    if (guest->checkout > guest->checkin) {
        int days = (guest->checkout - guest->checkin) / (60 * 60 * 24);
        printf("Guest %s stayed for %d days\n", guest->name, days);
    }
}

void display_guests(struct hotel *hotel) {
    int i;
    for (i = 0; i < MAX_ROOMS; i++) {
        if (hotel->rooms[i].available > 0) {
            printf("Room %d: %d available\n", i, hotel->rooms[i].available);
        }
    }
}

int main() {
    struct hotel hotel;
    struct guest guest;

    init_hotel(&hotel);

    guest.name[0] = 'J';
    guest.email[0] = 'j';
    guest.checkin = clock();
    add_guest(&hotel, &guest);

    guest.name[0] = 'S';
    guest.email[0] = 's';
    guest.checkin = clock();
    add_guest(&hotel, &guest);

    display_guests(&hotel);

    return 0;
}

#include &lt;iostream&gt;
#include &lt;string&gt;
#include &lt;fstream&gt;
using namespace std;
template &lt;class T&gt;
struct TreeNode{
  string value;
  T key;
  TreeNode&lt;T&gt; *Parent;
  TreeNode&lt;T&gt; *LeftChild;
  TreeNode&lt;T&gt; *RightChild;
  TreeNode (T k,string Val)
  {
    this-&gt;value=Val;
    this-&gt;key=k;
    this-&gt;Parent=NULL;
    this-&gt;LeftChild=NULL;
    this-&gt;RightChild=NULL;
  }
};

template &lt;class T&gt;
class BinaryTree{
  private:
    TreeNode&lt;T&gt; *Root;
  public: 
       BinaryTree();
       void LoadTree(const char file[]);
       ~BinaryTree();
       void insertNode(T Key,string Val);
       void deleteNode(T Key);
       string searchNode(T Key);
       void UpdateKey(T newkey,T oldkey);
       int Height(TreeNode&lt;T&gt; *node);
       int height();
};

template &lt;class T&gt;
BinaryTree&lt;T&gt;::BinaryTree() 
{
   Root=NULL;                       
}

template &lt;class T&gt;
void BinaryTree&lt;T&gt;::insertNode(T Key,string Val)
{
   TreeNode&lt;T&gt; **temp=&amp;Root;
   TreeNode&lt;T&gt; *temp1=NULL;
   if (*temp==NULL)
   {
     Root=new TreeNode&lt;T&gt;(Key,Val);
     return;
   }
   else
   {            
     while (*temp!=NULL)
     {
       temp1=*temp;
       if (temp1-&gt;key&gt;Key)
       {
           temp=&amp;(*temp)-&gt;LeftChild;
       }
       else if (temp1-&gt;key&lt;Key)
       {
            temp=&amp;(*temp)-&gt;RightChild;
       }
     }
   }
   *temp=new TreeNode&lt;T&gt;(Key,Val);              
   (*temp)-&gt;Parent=temp1;
}

template &lt;class T&gt;
void BinaryTree&lt;T&gt;::LoadTree(const char *file)
{
  ifstream fin;
  fin.open(file);
  string buffer;
  T buff;
  while (!fin.eof())
  {
      getline(fin,buffer,'~');
      fin&gt;&gt;buff;
      if (!buff)
      continue; 
      insertNode(buff,buffer);
  }          
  fin.close();
}  

void BinaryTree&lt;T&gt;::deleteNode(T Key)
{
  TreeNode&lt;T&gt; *temp=Root;
  TreeNode&lt;T&gt; *temp1=temp;
  while (temp!=NULL)
  {
       if (temp-&gt;key==Key)
       {
           temp1=temp;               
           if (temp==Root)
           {
               TreeNode&lt;T&gt; *temp2=Root;
               temp2=temp2-&gt;RightChild;
               while (temp2-&gt;LeftChild!=NULL)
               {
                     temp2=temp2-&gt;LeftChild;
               }
               temp-&gt;key=temp2-&gt;key;
               temp-&gt;value=temp2-&gt;value;
               delete temp2;            
           } 
           else if (temp-&gt;RightChild==NULL)
           {
                TreeNode&lt;T&gt; *temp2=temp;
                temp2=temp-&gt;Parent;
                if (temp2-&gt;RightChild==temp)
                {
                    temp2-&gt;RightChild=temp-&gt;LeftChild;
                    (temp-&gt;LeftChild)-&gt;Parent=temp2;
                }
                else if (temp2-&gt;LeftChild==temp)
                {
                    temp2-&gt;LeftChild=temp-&gt;LeftChild;
                    (temp-&gt;LeftChild)-&gt;Parent=temp2;
                }

                delete temp1;
                delete temp;
                return;
           }
           else if (temp-&gt;LeftChild==NULL)
           {
                TreeNode&lt;T&gt; *temp2=temp;
                temp2=temp-&gt;Parent;
                if (temp2-&gt;RightChild==temp)
                {
                    temp2-&gt;RightChild=temp-&gt;RightChild;
                    (temp-&gt;RightChild)-&gt;Parent=temp2;
                }
                else if (temp2-&gt;LeftChild==temp)
                {
                    temp2-&gt;LeftChild=temp-&gt;RightChild;
                    (temp-&gt;RightChild)-&gt;Parent=temp2;
                }
                delete temp1;
                delete temp;
                return;
           }
           else if (temp-&gt;RightChild!=NULL)
           {
               TreeNode&lt;T&gt; *tmp=temp; 
               temp=temp-&gt;RightChild;
               if (temp-&gt;LeftChild!=NULL)
               {
                   while (temp-&gt;LeftChild!=NULL)
                   {
                       tmp=temp;  
                       temp=temp-&gt;LeftChild;
                   }      
               }
               if (tmp!=temp1)
               tmp-&gt;LeftChild==NULL;
               else
               temp1-&gt;RightChild==NULL;

               temp1-&gt;key=temp-&gt;key;
               temp1-&gt;value=temp-&gt;value;
               delete temp;
               return;
           }
       }
       if (temp-&gt;key&gt;Key)
       {
           temp=temp-&gt;LeftChild;
       }
       else if (temp-&gt;key&lt;Key)
       {
            temp=temp-&gt;RightChild;
       }
 }                            
 return;
}

#include "BinarySearch.h"
