#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure to hold a word and its translation
typedef struct {
    char word[50];
    char translation[50];
} Word;

// Function to get input from the user
void getInput(Word *word) {
    printf("Enter a word: ");
    scanf("%s", word->word);
    printf("Enter its translation: ");
    scanf("%s", word->translation);
}

// Function to print the word and its translation
void printWord(Word *word) {
    printf("%s: %s\n", word->word, word->translation);
}

// Function to translate a sentence
void translateSentence(char *sentence) {
    // Split the sentence into words
    char *words[50];
    int numWords = 0;
    char *token = strtok(sentence, " ");
    while (token != NULL) {
        words[numWords] = token;
        numWords++;
        token = strtok(NULL, " ");
    }

    // Translate each word
    for (int i = 0; i < numWords; i++) {
        Word word;
        strcpy(word.word, words[i]);
        getInput(&word);
        printWord(&word);
    }
}

int main() {
    // Get input from the user
    char sentence[100];
    printf("Enter a sentence: ");
    fgets(sentence, 100, stdin);

    // Translate the sentence
    translateSentence(sentence);

    return 0;
}

