#include <stdlib.h>
#include <time.h>

#define MAX_CARS 10
#define MAX_LANE 3

typedef struct Car {
  int x, y, direction, speed;
} Car;

Car cars[MAX_CARS];

void simulateTrafficFlow() {
  // Randomly generate car positions and directions
  for (int i = 0; i < MAX_CARS; i++) {
    cars[i].x = rand() % MAX_LANE;
    cars[i].y = rand() % MAX_LANE;
    cars[i].direction = rand() % 2;
    cars[i].speed = rand() % 3;
  }

  // Simulate traffic flow
  for (int t = 0; t < 1000; t++) {
    // Update car positions
    for (int i = 0; i < MAX_CARS; i++) {
      switch (cars[i].direction) {
        case 0:
          cars[i].x++;
          break;
        case 1:
          cars[i].x--;
          break;
        case 2:
          cars[i].y++;
          break;
        case 3:
          cars[i].y--;
          break;
      }

      // Limit car movement within the lane
      if (cars[i].x < 0 || cars[i].x >= MAX_LANE) {
        cars[i].direction *= -1;
      }
      if (cars[i].y < 0 || cars[i].y >= MAX_LANE) {
        cars[i].direction *= -1;
      }
    }

    // Print car positions
    for (int i = 0; i < MAX_CARS; i++) {
      printf("Car %d: (%d, %d)\n", i, cars[i].x, cars[i].y);
    }

    // Pause for a while
    sleep(1);
  }
}

int main() {
  simulateTrafficFlow();

  return 0;
}

