void update_grid() {
    for (int i = 0; i < WIDTH; i++) {
        for (int j = 0; j < HEIGHT; j++) {
            // Check the eight neighbors of the current cell
            int alive_neighbors = 0;
            for (int k = -1; k <= 1; k++) {
                for (int l = -1; l <= 1; l++) {
                    if (k == 0 || l == 0) {
                        continue; // Skip diagonals
                    }
                    if (grid[i + k][j + l].state) {
                        alive_neighbors++;
                    }
                }
            }
            // Apply the game of life rules
            if (alive_neighbors < 2 && grid[i][j].state) {
                grid[i][j].state = 0; // If there are fewer than two alive neighbors, the cell dies
            } else if (alive_neighbors > 3) {
                grid[i][j].state = 0; // If there are more than three alive neighbors, the cell dies
            } else if (alive_neighbors == 2 && grid[i][j].state) {
                grid[i][j].state = 1; // If there are two alive neighbors and the current cell is alive, the cell stays alive
            } else {
                grid[i][j].state = 0; // Otherwise, the cell dies
            }
        }
    }
}

int main() {
    srand(time(NULL)); // Initialize the random number generator
    init_grid();
    draw_grid();
    update_grid();
    while (1) {
        update_grid();
        draw_grid();
        sleep(1); // Update and draw the grid every second
    }
    return 0;
}

