/*
 * Building a POP3 Client in C
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <netinet/in.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <sys/types.h>
#include <sys/time.h>
#include <unistd.h>
#include <fcntl.h>

#define POP3_PORT 110
#define POP3_TIMEOUT 60

int main(int argc, char **argv) {
    int sock, n;
    char buf[1024];
    struct sockaddr_in server;
    struct timeval tv;
    fd_set readfds;

    /* Create a socket */
    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket");
        exit(1);
    }

    /* Initialize the server address */
    memset(&server, 0, sizeof(server));
    server.sin_family = AF_INET;
    server.sin_port = htons(POP3_PORT);
    server.sin_addr.s_addr = inet_addr("127.0.0.1");

    /* Connect to the server */
    n = connect(sock, (struct sockaddr *)&server, sizeof(server));
    if (n < 0) {
        perror("connect");
        exit(1);
    }

    /* Set a timeout for the read operation */
    tv.tv_sec = POP3_TIMEOUT;
    tv.tv_usec = 0;
    setsockopt(sock, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));

    /* Read the greeting from the server */
    n = read(sock, buf, sizeof(buf));
    if (n < 0) {
        perror("read");
        exit(1);
    }

    /* Print the greeting */
    printf("Greeting: %s\n", buf);

    /* Read the message from the server */
    n = read(sock, buf, sizeof(buf));
    if (n < 0) {
        perror("read");
        exit(1);
    }

    /* Print the message */
    printf("Message: %s\n", buf);

    /* Close the socket */
    close(sock);

    return 0;
}

