#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure to represent a node in the Huffman tree
typedef struct node {
    int value;
    struct node* left;
    struct node* right;
} node_t;

// Function to create a new node
node_t* create_node(int value) {
    node_t* node = (node_t*)malloc(sizeof(node_t));
    node->value = value;
    node->left = NULL;
    node->right = NULL;
    return node;
}

// Function to build the Huffman tree
node_t* build_huffman_tree(int* freqs, int size) {
    // Create a priority queue to store the nodes
    node_t* queue[size];

    // Initialize the queue with the leaf nodes
    for (int i = 0; i < size; i++) {
        queue[i] = create_node(freqs[i]);
    }

    // Build the Huffman tree
    while (size > 1) {
        // Find the two nodes with the minimum frequency
        int min1 = 0, min2 = 0;
        for (int i = 0; i < size; i++) {
            if (queue[i]->value < queue[min1]->value) {
                min1 = i;
            }
        }
        for (int i = 0; i < size; i++) {
            if (queue[i]->value < queue[min2]->value && i != min1) {
                min2 = i;
            }
        }

        // Create a new node with the minimum frequency and add it to the queue
        node_t* node = create_node(queue[min1]->value + queue[min2]->value);
        node->left = queue[min1];
        node->right = queue[min2];
        queue[min1] = node;
        queue[min2] = NULL;

        // Update the size of the queue
        size--;
    }

    // Return the root node of the Huffman tree
    return queue[0];
}

// Function to encode a string using Huffman coding
char* huffman_encode(char* str, node_t* root) {
    // Initialize the encoded string
    char* encoded = (char*)malloc(sizeof(char) * (strlen(str) + 1));
    encoded[0] = '\0';

    // Traverse the Huffman tree
    node_t* node = root;
    for (int i = 0; i < strlen(str); i++) {
        if (str[i] == '0') {
            node = node->left;
        } else {
            node = node->right;
        }

        // If the node is a leaf node, add the character to the encoded string
        if (node->left == NULL && node->right == NULL) {
            encoded[strlen(encoded)] = node->value;
            encoded[strlen(encoded) + 1] = '\0';
        }
    }

    // Return the encoded string
    return encoded;
}

// Function to decode a string using Huffman coding
char* huffman_decode(char* encoded, node_t* root) {
    // Initialize the decoded string
    char* decoded = (char*)malloc(sizeof(char) * (strlen(encoded) + 1));
    decoded[0] = '\0';

    // Traverse the Huffman tree
    node_t* node = root;
    for (int i = 0; i < strlen(encoded); i++) {
        if (encoded[i] == '0') {
            node = node->left;
        } else {
            node = node->right;
        }

        // If the node is a leaf node, add the character to the decoded string
        if (node->left == NULL && node->right == NULL) {
            decoded[strlen(decoded)] = node->value;
            decoded[strlen(decoded) + 1] = '\0';
        }
    }

    // Return the decoded string
    return decoded;
}

int main() {
    // Test the Huffman coding implementation
    char* str = "hello world";
    int freqs[128];
    for (int i = 0; i < 128; i++) {
        freqs[i] = 0;
    }
    for (int i = 0; i < strlen(str); i++) {
        freqs[str[i]]++;
    }
    node_t* root = build_huffman_tree(freqs, 128);
    char* encoded = huffman_encode(str, root);
    char* decoded = huffman_decode(encoded, root);
    printf("Encoded string: %s\n", encoded);
    printf("Decoded string: %s\n", decoded);
    return 0;
}

