            memset(buffer, 0, sizeof(buffer));
            if (recv(client_socket, buffer, sizeof(buffer), 0) <= 0) {
                break;
            }

            printf("Received message: %s\n", buffer);

            if (send(client_socket, buffer, strlen(buffer), 0) <= 0) {
                break;
            }
        }

        close(client_socket);
    }

    return 0;
}

