/*
 * Image to ASCII art converter
 *
 * This program converts an image file to ASCII art.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define WIDTH 80
#define HEIGHT 25
#define MAX_CHAR 95

// Function to convert a pixel to an ASCII character
char pixel_to_char(int pixel) {
    return (char) (pixel * MAX_CHAR / 255);
}

// Function to convert an image to ASCII art
void image_to_ascii(const char *image_file) {
    // Open the image file
    FILE *fp = fopen(image_file, "rb");
    if (!fp) {
        printf("Error: Unable to open image file.\n");
        return;
    }

    // Read the image data
    unsigned char image[WIDTH * HEIGHT * 3];
    fread(image, sizeof(unsigned char), WIDTH * HEIGHT * 3, fp);

    // Close the image file
    fclose(fp);

    // Convert the image to ASCII art
    char ascii_art[HEIGHT][WIDTH + 1];
    for (int y = 0; y < HEIGHT; y++) {
        for (int x = 0; x < WIDTH; x++) {
            int pixel = (image[(y * WIDTH + x) * 3] + image[(y * WIDTH + x) * 3 + 1] + image[(y * WIDTH + x) * 3 + 2]) / 3;
            ascii_art[y][x] = pixel_to_char(pixel);
        }
        ascii_art[y][WIDTH] = '\0';
    }

    // Print the ASCII art
    for (int y = 0; y < HEIGHT; y++) {
        printf("%s\n", ascii_art[y]);
    }
}

// Main function
int main(int argc, char *argv[]) {
    // Check for correct usage
    if (argc != 2) {
        printf("Usage: %s <image_file>\n", argv[0]);
        return 1;
    }

    // Convert the image to ASCII art
    image_to_ascii(argv[1]);

    return 0;
}

