#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <math.h>
#include <time.h>

#define NUM_PARTICLES 1000
#define NUM_THREADS 4

typedef struct {
    int id;
    double x, y, z;
    double vx, vy, vz;
    double ax, ay, az;
} Particle;

void *update_particle(void *arg) {
    int thread_id = *(int *) arg;
    Particle *particles = (Particle *) malloc(NUM_PARTICLES * sizeof(Particle));

    for (int i = thread_id * NUM_PARTICLES / NUM_THREADS; i < (thread_id + 1) * NUM_PARTICLES / NUM_THREADS; i++) {
        particles[i].x += particles[i].vx;
        particles[i].y += particles[i].vy;
        particles[i].z += particles[i].vz;

        particles[i].vx += particles[i].ax;
        particles[i].vy += particles[i].ay;
        particles[i].vz += particles[i].az;

        particles[i].ax = 0;
        particles[i].ay = 0;
        particles[i].az = 0;
    }

    free(particles);
    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];
    int rc;
    srand(time(NULL));

    Particle particles[NUM_PARTICLES];

    for (int i = 0; i < NUM_PARTICLES; i++) {
        particles[i].id = i;
        particles[i].x = rand() % 100;
        particles[i].y = rand() % 100;
        particles[i].z = rand() % 100;

        particles[i].vx = (rand() % 201 - 100) / 100.0;
        particles[i].vy = (rand() % 201 - 100) / 100.0;
        particles[i].vz = (rand() % 201 - 100) / 100.0;

        particles[i].ax = 0;
        particles[i].ay = 0;
        particles[i].az = 0;
    }

    for (int i = 0; i < NUM_THREADS; i++) {
        rc = pthread_create(&threads[i], NULL, update_particle, (void *) &i);
        if (rc) {
            printf("Error: unable to create thread, %d\n", rc);
            exit(-1);
        }
    }

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

