using namespace RuGKinectInterfaceServer;



Player::Player(std::string const &fileName, bool loop)

: ServerThread(), m_sFileName( fileName ), m_bLoop( loop ), m_pLatestSkeleton( NULL )

{}



Player::~Player()

{

	delete m_pLatestSkeleton;

}



unsigned Player::getClockInMs()

{

	return  ((float) clock() / CLOCKS_PER_SEC) * 1000;

}



void Player::run()

{

	m_pFilestream = new ifstream( m_sFileName.c_str(), ios::in | ios::binary );

	if ( !m_pFilestream )

	{

		cerr << "\n### Could not open " << m_sFileName << " for reading. ###\n";

		throw INVALID_FILE;

	}



	std::cout << " * Playing back Kinect data from " << m_sFileName << "\n";



	unsigned loopTime = 0;

	char buffer[sizeof(Skeleton)];

	while ( m_bContinueThread )

	{

		if ( !m_pFilestream->read( buffer, sizeof(Skeleton) ) )

		{

			if ( !m_bLoop || !m_pFilestream->eof())

				break;



			//std::cout << " * All data from " << m_sFileName << " has been replayed: looping\n";

			m_pFilestream->clear();

			m_pFilestream->seekg(0, ios::beg);

			loopTime = getClockInMs();

			if ( !m_pFilestream->read( buffer, sizeof(Skeleton) ) )

				break;

		}



		m_ghSkeletonMutex.lock();



		delete m_pLatestSkeleton;

		m_pLatestSkeleton = NULL;

		m_pLatestSkeleton = new Skeleton( *reinterpret_cast<Skeleton const *>(buffer) );

		Skeleton transformedSkeleton(*m_pLatestSkeleton);

		transformedSkeleton.transform( Server::instance()->getCalibration() );



		m_ghSkeletonMutex.unlock();



		while ( m_pLatestSkeleton->getTime() > static_cast<unsigned long>(getClockInMs() - loopTime) ) 

#ifdef WIN32

			Sleep(1);

#else

			usleep(1);

#endif



		Server::instance()->signalNewSkeletonDataAvailable();

	}



	if ( !m_bContinueThread )

		std::cout << " * Stopping Kinect data playback\n";

	else if ( m_pFilestream->eof() )

		std::cout << " * All data from " << m_sFileName << " has been replayed\n\n";

	else

		cerr << "\n### Kinect data playback stopped for unknown reason ###\n";

}



Skeleton Player::getLatestSkeleton()

{ 

	m_ghSkeletonMutex.lock();



	Skeleton returnValue(*m_pLatestSkeleton);



	m_ghSkeletonMutex.unlock();



	return returnValue;

}

//GEMINI-pro DATASET v1.0 Category: Percolation Simulator ; Style: intelligent
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Grid size
#define SIZE 100

// Probability of a site being open
#define P 0.5

// Initialize the grid with closed sites
void init_grid(int grid[SIZE][SIZE]) {
  for (int i = 0; i < SIZE; i++) {
    for (int j = 0; j < SIZE; j++) {
      grid[i][j] = 0;
    }
  }
}

// Open a site with probability P
void open_site(int grid[SIZE][SIZE], int i, int j) {
  if (rand() < (P * RAND_MAX)) {
    grid[i][j] = 1;
  }
}

// Print the grid
void print_grid(int grid[SIZE][SIZE]) {
  for (int i = 0; i < SIZE; i++) {
    for (int j = 0; j < SIZE; j++) {
      printf("%d ", grid[i][j]);
    }
    printf("\n");
  }
}

// Check if a site is open
int is_open(int grid[SIZE][SIZE], int i, int j) {
  return grid[i][j] == 1;
}

// Check if a site is closed
int is_closed(int grid[SIZE][SIZE], int i, int j) {
  return grid[i][j] == 0;
}

// Check if a site is on the top of the grid
int is_top(int i) {
  return i == 0;
}

// Check if a site is on the bottom of the grid
int is_bottom(int i) {
  return i == SIZE - 1;
}

// Check if a site is on the left of the grid
int is_left(int j) {
  return j == 0;
}

// Check if a site is on the right of the grid
int is_right(int j) {
  return j == SIZE - 1;
}

// Get the number of open neighbors of a site
int num_open_neighbors(int grid[SIZE][SIZE], int i, int j) {
  int count = 0;
  if (is_open(grid, i - 1, j)) {
    count++;
  }
  if (is_open(grid, i + 1, j)) {
    count++;
  }
  if (is_open(grid, i, j - 1)) {
    count++;
  }
  if (is_open(grid, i, j + 1)) {
    count++;
  }
  return count;
}

// Check if a site is percolating
int is_percolating(int grid[SIZE][SIZE], int i, int j) {
  // Check if the site is open
  if (!is_open(grid, i, j)) {
    return 0;
  }

  // Check if the site is on the top or bottom of the grid
  if (is_top(i) || is_bottom(i)) {
    return 1;
  }

  // Check if the site has at least one open neighbor
  if (num_open_neighbors(grid, i, j) > 0) {
    return 1;
  }

  // Check if the site is percolating through its neighbors
  if (is_percolating(grid, i - 1, j) || is_percolating(grid, i + 1, j) ||
      is_percolating(grid, i, j - 1) || is_percolating(grid, i, j + 1)) {
    return 1;
  }

  // The site is not percolating
  return 0;
}

// Perform the percolation simulation
void percolation_simulation(int grid[SIZE][SIZE]) {
  // Initialize the grid
  init_grid(grid);

  // Open sites with probability P
  for (int i = 0; i < SIZE; i++) {
    for (int j = 0; j < SIZE; j++) {
      open_site(grid, i, j);
    }
  }

  // Print the grid
  print_grid(grid);

  // Check if the grid is percolating
  int percolating = 0;
  for (int i = 0; i < SIZE; i++) {
    for (int j = 0; j < SIZE; j++) {
      if (is_percolating(grid, i, j)) {
        percolating = 1;
        break;
      }
    }
  }

  // Print the result
  if (percolating) {
    printf("The grid is percolating.\n");
  } else {
    printf("The grid is not percolating.\n");
  }
}

int main() {
  // Initialize the random number generator
  srand(time(NULL));

  // Perform the percolation simulation
  int grid[SIZE][SIZE];
  percolation_simulation(grid);

  return 0;
}

