// Function to sort an array of integers using recursive sorting
void sortArray(int arr[], int low, int high) {
  // Base case: if the length of the array is 1 or less, return
  if (low >= high) return;

  // Find the middle index of the array
  int mid = (low + high) / 2;

  // Recursively sort the left and right sides of the array
  sortArray(arr, low, mid);
  sortArray(arr, mid + 1, high);

  // Merge the sorted left and right sides of the array
  merge(arr, low, mid, high);
}

// Function to merge two sorted arrays
void merge(int arr[], int low, int mid, int high) {
  int left[mid - low + 1], right[high - mid];
  int i, j, k;

  // Initialize left and right arrays with elements from the original array
  for (i = low; i <= mid; i++) {
    left[i - low] = arr[i];
  }
  for (j = mid + 1; j <= high; j++) {
    right[j - mid] = arr[j];
  }

  // Merge the two arrays into a single sorted array
  i = low;
  j = 0;
  k = low;
  while (i <= mid && j <= high) {
    if (left[i - low] <= right[j - mid]) {
      arr[k] = left[i - low];
      i++;
    } else {
      arr[k] = right[j - mid];
      j++;
    }
    k++;
  }
  while (i <= mid) {
    arr[k] = left[i - low];
    i++;
    k++;
  }
  while (j <= high) {
    arr[k] = right[j - mid];
    j++;
    k++;
  }
}

int main() {
  int arr[10] = {3, 2, 1, 4, 5, 6, 8, 7, 9};
  int low = 0;
  int high = sizeof(arr) / sizeof(arr[0]) - 1;

  // Recursively sort the array
  sortArray(arr, low, high);

  // Print the sorted array
  for (int i = low; i <= high; i++) {
    printf("%d ", arr[i]);
  }
  printf("\n");

  return 0;
}

/**
 * Quicksort algorithm
 */
template <typename Comparable>
void quicksort(vector<Comparable> & a)
{
	quicksort(a, 0, a.size() - 1);
}

/**
 * Return median of left, center and right.
 * Order these and hide the pivot
 */
template <typename Comparable>
const Comparable & median3(vector<Comparable> & a, int left, int right)
{
	int center = (left + right) / 2;
	if(a[center] < a[left])
		swap(a[left], a[center]);
	if(a[right] < a[left])
		swap(a[left], a[right]);
	if(a[right] < a[center])
		swap(a[center], a[right]);

	// place pivot at position right - 1
	swap(a[center], a[right - 1]);
	return a[right - 1];
}

/**
 * Internal quicksort method that makes recursive calls.
 * Uses median-of-three partitioning and a cutoff of 10.
 * a is an array of Comparable items.
 * left is the left-most index of the subarray.
 * right is the right-most index of the subarray.
 */
template <typename Comparable>
void quicksort(vector<Comparable> & a, int left, int right)
{
	// calculate the number of elements, for array that has the number
	// less than 10, insertion sort is better than quicksort(recurse)
	if(left + 10 <= right)
	{
		Comparable pivot = median3(a, left, right);

		// begin partitioning 
		int i = left, j = right - 1;
		for(;;)
		{
			while(a[++i] < pivot){}
			while(pivot < a[--j]){}
			if(i < j)
				swap(a[i], a[j]);
			else
				break;
		}

		swap(a[i], a[right - 1]); // restore pivot

		quicksort(a, left, i - 1); // sort small elements
		quicksort(a, i + 1, right); // sort large elements
	}
	else 
		// use insertionsort on the subarray
		insertionSort(a, left, right);
}

