        error("ERROR on binding");
    if (listen(sockfd, 10) < 0)
        error("ERROR on listening");

    return sockfd;
}

void handle_client(int client_sockfd) {
    char buffer[256];
    int message_len;
    client_data client;

    client.sockfd = client_sockfd;

    read(client.sockfd, buffer, 255);
    printf("Received message: %s\n", buffer);

    message_len = strlen(buffer);

    if (strstr(buffer, "recursive") != NULL) {
        printf("Client asked for recursion, handling it recursively...\n");

        client_data new_client;
        int new_client_sockfd = create_socket(1234);

        handle_client(new_client_sockfd);

        send(client.sockfd, "Sending recursive response\n", 23, 0);
        close(new_client_sockfd);
    } else {
        send(client.sockfd, "Hello, this is a simple chat server!\n", 29, 0);
    }

    close(client.sockfd);
}

int main() {
    int server_sockfd, client_sockfd;

    server_sockfd = create_socket(1234);

    while (1) {
        client_sockfd = accept(server_sockfd, NULL, NULL);
        handle_client(client_sockfd);
    }

    close(server_sockfd);
    return 0;
}

