    float item_price[MAX];
    int item_quantity[MAX];
};

struct Warehouse W;

// Function to add items to the warehouse
void add_items(int size)
{
    int i;
    for(i=0; i < size; i++)
    {
        printf("\nEnter Item %d Details: \n", i+1);
        printf("Item Code: ");
