        //yValue = ((double) rand()/RAND_MAX)*2-1;

        xValue = ((double) rand()/RAND_MAX);
        yValue = ((double) rand()/RAND_MAX);

        functionValue = (xValue * xValue) + (yValue * yValue);

        functionValue = sqrt(functionValue);
        if(functionValue <= 1) {
            pointsIn++;
        }
    }

