        }
        if(choice != 5) {
            printf("Max pixel value: %d\n", find_max(*image->pixels, image->width * image->height));
            printf("Min pixel value: %d\n", find_min(*image->pixels, image->width * image->height));
        }
    } while(choice != 5);

    free_image(image);
    return 0;
}

