    //Nhập số dòng
    do
    {
        printf("\nNhap vao so dong: ");
        // Cách tà đạo: scanf("dong =%d",&dong);  // Lúc nhập phải viết thêm  chữ ( dong =  ) ở khung console
        scanf("%d",&dong);

        if(dong < 1 || dong > MAX)
        {
            printf("\nSo dong khong hop le. Xin kiem tra lai!");
        }

    }while(dong < 1 || dong > MAX);

    //Nhập số cột
    do
    {
        printf("\nNhap vao so cot: ");
        scanf("%d",&cot);

        if(cot < 1 || cot > MAX)
        {
            printf("\nSo cot khong hop le. Xin kiem tra lai!");

        }

    }while(cot < 1 || cot > MAX);
    for(int i = 0; i < dong; i++)
    {
        for(int j = 0; j < cot; j++)
        {
            float temp;
            printf("\nNhap a[%d][%d] = ", i, j);
            scanf("%f", &temp);
            a[i][j] = temp;
        }
    }
}

void XuatMang(float a[][MAX], int dong, int cot)
{
    for(int i = 0; i < dong; i++)
    {
        for(int j = 0; j < cot; j++)
        {
            printf("%8.3f", a[i][j]);
        }
        printf("\n\n");
    }
}

int DemSoLuongCacGiaTriPhanBiet(float a[][MAX], int dong, int cot)
{
    int n = dong * cot;
    int dem = 0, flag;
    for(int i = 0; i < n; i++)
    {
        flag = 1;
        for(int j = i + 1; j < n; j++)
        {
            if(a[j / cot][j % cot] == a[i / cot][i % cot])
            {
                flag = 0;
                break;
            }
        }
        if(flag == 1)
        {
            dem++;
        }
    }
    return dem;
}
int main()
{
    float a[MAX][MAX];
    int dong, cot;
    NhapMang(a, dong, cot);
    XuatMang(a, dong, cot);

    int dem = DemSoLuongCacGiaTriPhanBiet(a, dong, cot);
    printf("\nSo phan tu phan biet trong ma tran = %d", dem);

    getch();
    return 0;
}

