#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_BLOCK_SIZE 4096
#define MAX_FILE_NAME 16
#define MAX_FILES 64

typedef struct block
{
    int block_num;
    char data[MAX_BLOCK_SIZE];
    struct block *next;
} Block;

typedef struct file
{
    char name[MAX_FILE_NAME];
    int size;
    Block *head;
} File;

typedef struct directory
{
    int num_files;
    File files[MAX_FILES];
} Directory;

Directory *create_directory()
{
    Directory *dir = malloc(sizeof(Directory));
    dir -> num_files = 0;
    return dir;
}

Block *create_block(int num)
{
    Block *block = malloc(sizeof(Block));
    block -> block_num = num;
    block -> next = NULL;
    return block;
}

File *create_file(char *name)
{
    File *file = malloc(sizeof(File));
    strcpy(file -> name, name);
    file -> size = 0;
    file -> head = NULL;
    return file;
}

int add_file(Directory *dir, char *name)
{
    if(dir -> num_files == MAX_FILES)
    {
        printf("Maximum number of files reached\n");
        return -1;
    }

    for(int i=0; i<dir -> num_files; i++)
    {
        if(strcmp(dir -> files[i].name, name) == 0)
        {
            printf("File with name '%s' already exists\n", name);
            return -1;
        }
    }

    File *file = create_file(name);
    dir -> files[dir -> num_files] = *file;
    dir -> num_files++;
    printf("File '%s' created\n", name);
    return 0;
}

int delete_file(Directory *dir, char *name)
{
    for(int i=0; i<dir -> num_files; i++)
    {
        if(strcmp(dir -> files[i].name, name) == 0)
        {
            File file = dir -> files[i];
            while(file.head != NULL)
            {
                Block *temp = file.head;
                file.head = file.head -> next;
                free(temp);
            }
            dir -> num_files--;
            for(int j=i; j<dir -> num_files; j++)
            {
                dir -> files[j] = dir -> files[j+1];
            }
            printf("File '%s' deleted\n", name);
            return 0;
        }
    }
    printf("File with name '%s' does not exist\n", name);
    return -1;
}

int add_data(Directory *dir, char *name, char *data)
{
    for(int i=0; i<dir -> num_files; i++)
    {
        if(strcmp(dir -> files[i].name, name) == 0)
        {
            File *file = &dir -> files[i];
            int data_size = strlen(data);
            int num_blocks = data_size % MAX_BLOCK_SIZE == 0 ? data_size / MAX_BLOCK_SIZE : data_size / MAX_BLOCK_SIZE + 1;
            for(int i=0; i<num_blocks; i++)
            {
                Block *block = create_block(file -> size + i);
                int j = 0;
                while(j < MAX_BLOCK_SIZE && (i*MAX_BLOCK_SIZE+j) < data_size)
                {
                    block -> data[j] = data[i*MAX_BLOCK_SIZE+j];
                    j++;
                }
                block -> data[j] = '\0';
                if(file -> head == NULL)
                {
                    file -> head = block;
                }
                else
                {
                    Block *temp = file -> head;
                    while(temp -> next != NULL)
                    {
                        temp = temp -> next;
                    }
                    temp -> next = block;
                }
            }
            file -> size = data_size;
            printf("Data added to file '%s'\n", name);
            return 0;
        }
    }
    printf("File with name '%s' does not exist\n", name);
    return -1;
}

int delete_data(Directory *dir, char *name)
{
    for(int i=0; i<dir -> num_files; i++)
    {
        if(strcmp(dir -> files[i].name, name) == 0)
        {
            File *file = &dir -> files[i];
            file -> size = 0;
            while(file -> head != NULL)
            {
                Block *temp = file -> head;
                file -> head = file -> head -> next;
                free(temp);
            }
            printf("Data deleted from file '%s'\n", name);
            return 0;
        }
    }
    printf("File with name '%s' does not exist\n", name);
    return -1;
}

void print_directory(Directory *dir)
{
    printf("Directory Contents:\n");
    printf("===================\n");
    if(dir -> num_files == 0)
    {
        printf("Directory is empty\n");
        return;
    }

    for(int i=0; i<dir -> num_files; i++)
    {
        File file = dir -> files[i];
        printf("File Name: %s\n", file.name);
        printf("File Size: %d bytes\n", file.size);
        if(file.head != NULL)
        {
            printf("File Data: \n");
            Block *temp = file.head;
            while(temp != NULL)
            {
                printf("%s", temp -> data);
                temp = temp -> next;
            }
            printf("\n");
        }
        else
        {
            printf("File is Empty\n");
        }
    }
}

int main()
{
    Directory *dir = create_directory();
    add_file(dir, "file1");
    add_file(dir, "file2");
    print_directory(dir);
    add_data(dir, "file1", "Hello World!");
    print_directory(dir);
    add_data(dir, "file2", "This is a sample file.");
    print_directory(dir);
    delete_data(dir, "file1");
    delete_file(dir, "file2");
    print_directory(dir);
    return 0;
}

//Code Llama-13B DATASET v1.0 Category: Basic Image Processing: Simple tasks like flipping an image, changing brightness/contrast ; Style: high level of detail
#include <stdio.h>
    #include <stdlib.h>
    #include <string.h>
    #include <math.h>

    // Struct to represent an image
    typedef struct {
        int width;
        int height;
        int channels;
        unsigned char *data;
    } Image;

    // Function to flip an image horizontally
    void flip_horizontally(Image *img) {
        int width = img->width;
        int height = img->height;
        int channels = img->channels;
        unsigned char *data = img->data;

        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width / 2; x++) {
                for (int c = 0; c < channels; c++) {
                    int index = (y * width * channels) + (x * channels) + c;
                    int mirror_index = (y * width * channels) + ((width - 1 - x) * channels) + c;
                    unsigned char temp = data[index];
                    data[index] = data[mirror_index];
                    data[mirror_index] = temp;
                }
            }
        }
    }

    // Function to change brightness/contrast of an image
    void change_brightness_contrast(Image *img, int brightness, int contrast) {
        int width = img->width;
        int height = img->height;
        int channels = img->channels;
        unsigned char *data = img->data;

        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                for (int c = 0; c < channels; c++) {
                    int index = (y * width * channels) + (x * channels) + c;
                    data[index] = (data[index] + brightness) * (contrast / 100.0);
                }
            }
        }
    }

    // Main function
    int main() {
        // Load image
        Image img;
        img.width = 512;
        img.height = 512;
        img.channels = 3;
        img.data = (unsigned char *)malloc(img.width * img.height * img.channels * sizeof(unsigned char));
        // ...

        // Flip image horizontally
        flip_horizontally(&img);

        // Change brightness/contrast of image
        change_brightness_contrast(&img, 50, 200);

        // ...

        // Free memory
        free(img.data);

        return 0;
    }

//LLAMA2-13B DATASET v1.0 Category: Arithmetic ; Style: statistical
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_NUM 1000
#define MIN_NUM 1

int main() {
    srand(time(NULL));
    int num1, num2, sum, diff, mult, div, mod;
    char op;

    printf("Welcome to the Arithmetic Game!\n");

    do {
        printf("Please enter a number: ");
        scanf("%d", &num1);

        if (num1 < MIN_NUM || num1 > MAX_NUM) {
            printf("Invalid input! Please try again.\n");
            continue;
        }

        printf("Now, please enter an operation (+, -, *, /, %): ");
        scanf(" %c", &op);

        if (op == '+') {
            num2 = rand() % MAX_NUM;
            sum = num1 + num2;
            printf("The sum of %d and %d is %d\n", num1, num2, sum);
        } else if (op == '-') {
            num2 = rand() % MAX_NUM;
            diff = num1 - num2;
            printf("The difference of %d and %d is %d\n", num1, num2, diff);
        } else if (op == '*') {
            num2 = rand() % MAX_NUM;
            mult = num1 * num2;
            printf("The product of %d and %d is %d\n", num1, num2, mult);
        } else if (op == '/') {
            num2 = rand() % MAX_NUM;
            if (num2 == 0) {
                printf("Division by zero! Please try again.\n");
                continue;
            }
            div = num1 / num2;
            printf("The quotient of %d and %d is %d\n", num1, num2, div);
        } else if (op == '%') {
            num2 = rand() % MAX_NUM;
            mod = num1 % num2;
            printf("The remainder of %d and %d is %d\n", num1, num2, mod);
        } else {
            printf("Invalid operation! Please try again.\n");
            continue;
        }
    } while (1);

    return 0;
}

