float deQuy(int n) // đệ quy
{
    if(n == 1)
        return 0.5;
    return deQuy(n - 1) + 1.0 / (2 * n);
}

float deQuyDuoi(int n, float x = 0.5)  // đệ quy đuôi
{
    if(n == 1)
        return x;
    return deQuyDuoi(n - 1, x +  1.0 / (2 * n));
}

float khuDeQuy(int n) // khử đệ quy
{
    float S = 0;

    for(int i = 1; i <= n; i++)
    {
        S = S + 1.0 / (2 * i);
    }
    return S;
}
