 *
 * This program controls the traffic lights at an intersection.
 * It uses a set of LEDs to indicate the current state of the traffic lights.
 */

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>

#define LED_RED 1
#define LED_YELLOW 2
#define LED_GREEN 3

void set_led(int led, int state) {
  if (state == 0) {
    printf("LED %d turned off\n", led);
  } else {
    printf("LED %d turned on\n", led);
  }
}

void traffic_light_controller(void) {
  int current_state = LED_GREEN;
  int next_state = LED_RED;
  int delay = 5; // 5 seconds

  while (1) {
    // Turn off all LEDs
    set_led(LED_RED, 0);
    set_led(LED_YELLOW, 0);
    set_led(LED_GREEN, 0);

    // Set the next LED to on
    set_led(next_state, 1);

    // Wait for the delay period
    sleep(delay);

    // Update the current state
    current_state = next_state;

    // Determine the next state
    if (current_state == LED_RED) {
      next_state = LED_YELLOW;
    } else if (current_state == LED_YELLOW) {
      next_state = LED_GREEN;
    } else if (current_state == LED_GREEN) {
      next_state = LED_RED;
    }
  }
}

