// Function to get input from the user with size limit
void getInput(char *str, int maxSize) {
    fgets(str, maxSize, stdin);
    size_t len = strlen(str);
    if (len > 0 && str[len - 1] == '\n') {
        str[len - 1] = '\0';  // Remove trailing newline
    }
}

// Function to reverse a string in place
void reverseString(char *str) {
    size_t len = strlen(str);
    for (size_t i = 0; i < len / 2; i++) {
        char temp = str[i];
        str[i] = str[len - i - 1];
        str[len - i - 1] = temp;
    }
}

// Function to count the number of vowels in a string
int countVowels(const char *str) {
    int count = 0;
    while (*str) {
        if (strchr("AEIOUaeiou", *str)) {
            count++;
        }
        str++;
    }
    return count;
}

// Function to convert a string to uppercase
void convertToUpper(char *str) {
    while (*str) {
        if (*str >= 'a' && *str <= 'z') {
            *str = *str - ('a' - 'A');
        }
        str++;
    }
}

// Function to print detailed string info
void printStringInfo(const char *str) {
    printf("String Length: %zu\n", strlen(str));
    printf("String Capacity: %zu\n", sizeof(str));

    printf("Characters in String:\n");
    for(size_t i = 0; i < strlen(str); i++) {
        printf("%c: %d\n", str[i], str[i]);
    }
}

