void checkIn(Room *rooms, int totalRooms) {
    int roomNumber, i, flag = 0;
    char guestName[50], guestContact[20];

    printf("Enter Room Number: ");
    scanf("%d", &roomNumber);

    for(i=0; i<totalRooms; i++) {
