#define CHESSBOARD_SIZE 8

int board[CHESSBOARD_SIZE][CHESSBOARD_SIZE];
int player;

int abs(int n)
{
    return (n < 0) ? -n : n;
}

void display_board()
{
    int i, j;
    for(i=0; i<CHESSBOARD_SIZE; i++)
    {
        for(j=0; j<CHESSBOARD_SIZE; j++)
        {
