#include<stdio.h>
#include<stdlib.h>
#include<time.h>

#define WIDTH 10
#define HEIGHT 10

int maze[HEIGHT][WIDTH];

void generateMaze() {
    int x, y, direction;
    srand(time(NULL));

    for (y = 0; y < HEIGHT; y++) {
        for (x = 0; x < WIDTH; x++) {
            maze[y][x] = 1;
        }
    }

    x = rand() % WIDTH;
    y = rand() % HEIGHT;
    direction = rand() % 4;

    while (1) {
        maze[y][x] = 0;

        switch (direction) {
            case 0: // North
                if (y > 0 && maze[y - 1][x] == 1) {
                    y--;
                } else {
                    direction = rand() % 4;
                }
                break;
            case 1: // East
                if (x < WIDTH - 1 && maze[y][x + 1] == 1) {
                    x++;
                } else {
                    direction = rand() % 4;
                }
                break;
            case 2: // South
                if (y < HEIGHT - 1 && maze[y + 1][x] == 1) {
                    y++;
                } else {
                    direction = rand() % 4;
                }
                break;
            case 3: // West
                if (x > 0 && maze[y][x - 1] == 1) {
                    x--;
                } else {
                    direction = rand() % 4;
                }
                break;
        }

        if (x == 0 && y == 0) {
            break;
        }
    }
}

void printMaze() {
    int x, y;

    for (y = 0; y < HEIGHT; y++) {
        for (x = 0; x < WIDTH; x++) {
            printf("%c", maze[y][x] == 1 ? '#' : ' ');
        }
        printf("\n");
    }
}

int main() {
    generateMaze();
    printMaze();

    return 0;
}

