/*
 * Network Topology Mapper
 *
 * This program maps the network topology of a given network,
 * using a simple algorithm that involves sending a request
 * message to each node in the network and recording the
 * response messages received from each node.
 *
 * The program outputs a graphical representation of the
 * network topology, showing the connections between
 * nodes and their neighbors.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>

#define MAX_NODES 100
#define MAX_CONNECTIONS 100

// Define a structure to store information about a node
struct node {
    char name[20];
    char ip_addr[20];
    int connections[MAX_CONNECTIONS];
    int num_connections;
};

// Define a structure to store information about the network
struct network {
    struct node nodes[MAX_NODES];
    int num_nodes;
};

// Function to send a request message to a node
int send_request(int sock, char *ip_addr, int port) {
    struct sockaddr_in server;
    server.sin_family = AF_INET;
    server.sin_port = htons(port);
    server.sin_addr.s_addr = inet_addr(ip_addr);

    if (connect(sock, (struct sockaddr *)&server, sizeof(server)) < 0) {
        perror("connect() failed");
        return -1;
    }

    char request[20];
    sprintf(request, "Request from %s", ip_addr);

    send(sock, request, strlen(request), 0);

    close(sock);

    return 0;
}

// Function to receive a response message from a node
int receive_response(int sock, char *ip_addr, int port) {
    struct sockaddr_in server;
    server.sin_family = AF_INET;
    server.sin_port = htons(port);
    server.sin_addr.s_addr = inet_addr(ip_addr);

    if (connect(sock, (struct sockaddr *)&server, sizeof(server)) < 0) {
        perror("connect() failed");
        return -1;
    }

    char response[20];
    recv(sock, response, sizeof(response), 0);

    close(sock);

    return 0;
}

// Function to map the network topology
void map_network(struct network *net) {
    int i, j, sock;

    // Iterate over all nodes in the network
    for (i = 0; i < net->num_nodes; i++) {
        // Send a request message to each node
        sock = socket(AF_INET, SOCK_STREAM, 0);
        send_request(sock, net->nodes[i].ip_addr, 8080);

        // Receive response messages from all nodes
        for (j = 0; j < net->num_nodes; j++) {
            if (i != j) {
                sock = socket(AF_INET, SOCK_STREAM, 0);
                receive_response(sock, net->nodes[j].ip_addr, 8080);
            }
        }

        // Add connections to the current node
        net->nodes[i].connections[net->nodes[i].num_connections++] = i;
    }
}

// Function to print the network topology
void print_network(struct network *net) {
    int i, j;

    // Iterate over all nodes in the network
    for (i = 0; i < net->num_nodes; i++) {
        printf("%s (%s) connections: ", net->nodes[i].name, net->nodes[i].ip_addr);

        // Print the connections for each node
        for (j = 0; j < net->nodes[i].num_connections; j++) {
            printf("%s ", net->nodes[net->nodes[i].connections[j]].name);
        }

        printf("\n");
    }
}

int main() {
    // Initialize the network
    struct network net;
    net.num_nodes = 3;
    strcpy(net.nodes[0].name, "Node1");
    strcpy(net.nodes[0].ip_addr, "192.168.1.1");
    strcpy(net.nodes[1].name, "Node2");
    strcpy(net.nodes[1].ip_addr, "192.168.1.2");
    strcpy(net.nodes[2].name, "Node3");
    strcpy(net.nodes[2].ip_addr, "192.168.1.3");

    // Map the network topology
    map_network(&net);

    // Print the network topology
    print_network(&net);

    return 0;
}

