#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// A jolly good function to compress a string
char *compress(char *str) {
    // Let's get to work, shall we?
    int len = strlen(str);
    char *compressed = malloc(len);
    int i, j, count;

    // Time to dance through the string
    for (i = 0, j = 0; i < len; i++) {
        // Let's count the jolly characters
        count = 0;
        while (str[i] == str[i + 1]) {
            count++;
            i++;
        }
        // Time to write the character and its count
        compressed[j++] = str[i];
        compressed[j++] = count + 1;
    }
    // Let's add a jolly ending
    compressed[j] = '\0';

    // Return the compressed string with a smile
    return compressed;
}

// A jolly good function to decompress a string
char *decompress(char *compressed) {
    // Let's get to work, shall we?
    int len = strlen(compressed);
    char *decompressed = malloc(len * 2);
    int i, j;

    // Time to bring back the original string
    for (i = 0, j = 0; i < len;) {
        // Copy the character and repeat it
        char ch = compressed[i++];
        int count = compressed[i++];
        for (int k = 0; k < count; k++) {
            decompressed[j++] = ch;
        }
    }
    // Let's add a jolly ending
    decompressed[j] = '\0';

    // Return the decompressed string with a smile
    return decompressed;
}

// Let's put on a jolly good show!
int main() {
    // A jolly good string to play with
    char str[] = "AAABBBCCCDDDDEEEFFF";

    // Let's compress it with a smile
    char *compressed = compress(str);

    // Let's show off the compressed string
    printf("Jolly compressed string: %s\n", compressed);

    // Let's bring it back to life
    char *decompressed = decompress(compressed);

    // Let's show off the decompressed string
    printf("Jolly decompressed string: %s\n", decompressed);

    // Time to bid farewell with a smile
    free(compressed);
    free(decompressed);
    return 0;
}

