//MISTRAL-7B DATASET v1.0 Category: Searching algorithm ; Style: invasive
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define SIZE 10

typedef struct {
    int value;
    int index;
} element;

void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

int invasive_search(int arr[], int size, int target) {
    element stack[SIZE];
    int top = -1;
    int i = 0;

    stack[++top] = (element) { arr[0], 0 };

    while (top >= 0) {
        element current = stack[top--];

        if (current.value == target)
            return current.index;

        if (current.index + 1 < size) {
            if (arr[current.index + 1] < target) {
                continue;
            }

            swap(&arr[current.index + 1], &arr[current.index]);
            stack[++top] = (element) { arr[current.index], current.index + 1 };
        }

        for (i = current.index - 1; i >= 0 && arr[i] > target; i--) {
            swap(&arr[i + 1], &arr[i]);
            stack[++top] = (element) { arr[i], i };
        }
    }

    return -1;
}

int main() {
    int arr[SIZE] = { 5, 3, 8, 1, 9, 6, 4, 7, 2, 0 };
    int target = 9;
    int index;

    index = invasive_search(arr, SIZE, target);

    if (index >= 0)
        printf("Found %d at index %d\n", target, index);
    else
        printf("%d not found\n", target);

    return 0;
}

