//Falcon-180B DATASET v1.0 Category: Queue Implementation ; Style: complex
#include <stdio.h>
#include <stdlib.h>

#define MAX 100

typedef struct node {
    int data;
    struct node* next;
} Node;

typedef struct {
    Node* front;
    Node* rear;
} Queue;

Queue* createQueue() {
    Queue* q = (Queue*) malloc(sizeof(Queue));
    if (q == NULL) {
        printf("Memory error\n");
        exit(0);
    }
    q->front = q->rear = NULL;
    return q;
}

void enqueue(Queue* q, int data) {
    Node* temp = (Node*) malloc(sizeof(Node));
    if (temp == NULL) {
        printf("Memory error\n");
        exit(0);
    }
    temp->data = data;
    temp->next = NULL;
    if (q->front == NULL) {
        q->front = temp;
        q->rear = temp;
    } else {
        q->rear->next = temp;
        q->rear = temp;
    }
}

int dequeue(Queue* q) {
    int data = -1;
    if (q->front == NULL) {
        printf("Queue is empty\n");
        return data;
    }
    Node* temp = q->front;
    data = temp->data;
    q->front = temp->next;
    free(temp);
    if (q->front == NULL) {
        q->rear = NULL;
    }
    return data;
}

void display(Queue* q) {
    if (q->front == NULL) {
        printf("Queue is empty\n");
        return;
    }
    Node* temp = q->front;
    printf("Queue elements are: ");
    while (temp!= NULL) {
        printf("%d ", temp->data);
        temp = temp->next;
    }
    printf("\n");
}

int main() {
    Queue* q = createQueue();
    enqueue(q, 1);
    enqueue(q, 2);
    enqueue(q, 3);
    display(q);
    dequeue(q);
    display(q);
    dequeue(q);
    display(q);
    dequeue(q);
    display(q);
    dequeue(q);
    display(q);
    return 0;
}

//Falcon-180B DATASET v1.0 Category: Text processing ; Style: irregular
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <time.h>
#include <math.h>

#define MAX_WORDS 100000
#define MAX_WORD_LENGTH 1000

typedef struct {
    char word[MAX_WORD_LENGTH];
    int count;
} Word;

int compareWords(const void* a, const void* b) {
    Word* wordA = (Word*)a;
    Word* wordB = (Word*)b;
    return strcmp(wordA->word, wordB->word);
}

int main() {
    FILE* file = fopen("text.txt", "r");
    if (file == NULL) {
        printf("Error opening file.\n");
        return 1;
    }

    char line[MAX_WORD_LENGTH];
    Word words[MAX_WORDS];
    int numWords = 0;

    while (fgets(line, MAX_WORD_LENGTH, file)!= NULL) {
        char* word = strtok(line, " ");
        while (word!= NULL) {
            if (numWords >= MAX_WORDS) {
                printf("Error: Too many words.\n");
                return 1;
            }
            strcpy(words[numWords].word, word);
            words[numWords].count = 1;
            numWords++;
            word = strtok(NULL, " ");
        }
    }

    qsort(words, numWords, sizeof(Word), compareWords);

    for (int i = 0; i < numWords; i++) {
        printf("%s %d\n", words[i].word, words[i].count);
    }

    fclose(file);
    return 0;
}

//FormAI DATASET v1.0 Category: Bingo Simulator ; Style: multivariable
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_NUMS 75
#define GRID_ROWS 5
#define GRID_COLS 15

int main()
{
    int grid[GRID_ROWS][GRID_COLS] = {0};
    int nums[MAX_NUMS] = {0};
    int num_index = 0;
    int i, j;
    srand(time(NULL));

    // generate the numbers
    for(i = 0; i < MAX_NUMS; i++)
    {
        nums[i] = i+1;
    }
    // shuffle the numbers
    for(i = 0; i < MAX_NUMS-1; i++)
    {
        j = i + rand() / (RAND_MAX / (MAX_NUMS - i) + 1);
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }

    // fill the grid
    for(i = 0; i < GRID_ROWS; i++)
    {
        for(j = 0; j < GRID_COLS; j++)
        {
            // center spot is free
            if(i == 2 && j == 6)
            {
                grid[i][j] = -1;
            }
            else
            {
                grid[i][j] = nums[num_index++];
            }
        }
    }

    // print the grid
    printf("\n\n\t\tBINGO SIMULATOR\n\n");
    for(i = 0; i < GRID_ROWS; i++)
    {
        for(j = 0; j < GRID_COLS; j++)
        {
            if(grid[i][j] == -1)
            {
                printf("|  FREE  ");
            }
            else
            {
                printf("|  %2d   ", grid[i][j]);
            }
        }
        printf("|\n");
    }
    printf("\n\n");

    return 0;
}

