//Falcon-180B DATASET v1.0 Category: Word Frequency Counter ; Style: dynamic
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdbool.h>

#define MAX_WORD_LENGTH 100
#define MAX_WORD_COUNT 100000

typedef struct {
    char word[MAX_WORD_LENGTH];
    int count;
} WordFrequency;

bool is_word_character(char c) {
    return isalnum(c) || c == '-';
}

void read_file(const char* filename, WordFrequency* word_frequency_table, int* word_count) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        fprintf(stderr, "Error opening file: %s\n", filename);
        exit(1);
    }

    char line[MAX_WORD_LENGTH + 1];
    while (fgets(line, MAX_WORD_LENGTH, file)!= NULL) {
        char* word = strtok(line, " \t\n\r\f\v");
        while (word!= NULL) {
            if (strlen(word) > MAX_WORD_LENGTH) {
                fprintf(stderr, "Word is too long: %s\n", word);
                exit(1);
            }

            int i = 0;
            while (is_word_character(word[i])) {
                word[i] = tolower(word[i]);
                i++;
            }

            word[i] = '\0';

            WordFrequency* entry = word_frequency_table;
            while (entry->count >= *word_count) {
                entry++;
            }

            if (entry->count == 0) {
                strcpy(entry->word, word);
            }

            entry->count++;
            word_count++;

            word = strtok(NULL, " \t\n\r\f\v");
        }
    }

    fclose(file);
}

void print_word_frequency_table(WordFrequency* word_frequency_table, int word_count) {
    printf("Word\tFrequency\n");
    for (int i = 0; i < word_count; i++) {
        printf("%s\t%d\n", word_frequency_table[i].word, word_frequency_table[i].count);
    }
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        printf("Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    WordFrequency word_frequency_table[MAX_WORD_COUNT];
    int word_count = 0;

    read_file(argv[1], word_frequency_table, &word_count);

    print_word_frequency_table(word_frequency_table, word_count);

    return 0;
