#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <complex.h>

typedef struct {
    double real;
    double imag;
} complex_t;

complex_t complex_add(complex_t a, complex_t b) {
    complex_t result;
    result.real = a.real + b.real;
    result.imag = a.imag + b.imag;
    return result;
}

complex_t complex_sub(complex_t a, complex_t b) {
    complex_t result;
    result.real = a.real - b.real;
    result.imag = a.imag - b.imag;
    return result;
}

complex_t complex_mul(complex_t a, complex_t b) {
    complex_t result;
    double real_part = (a.real * b.real) - (a.imag * b.imag);
    double imag_part = (a.real * b.imag) + (a.imag * b.real);
    result.real = real_part;
    result.imag = imag_part;
    return result;
}

complex_t complex_div(complex_t a, complex_t b) {
    complex_t result;
    double denominator = pow(b.real, 2) + pow(b.imag, 2);
    double real_part = ((a.real * b.real) + (a.imag * b.imag)) / denominator;
    double imag_part = ((a.imag * b.real) - (a.real * b.imag)) / denominator;
    result.real = real_part;
    result.imag = imag_part;
    return result;
}

complex_t complex_sqrt(complex_t num) {
    complex_t z = {0.0, num.imag};
    complex_t h = {1.0, 0.0};
    int i = 0;
    while (i < 100) {
        complex_t t = complex_mul(h, complex_sub(z, complex_div(num, z)));
        z = complex_add(z, t);
        i++;
    }
    return z;
}

complex_t complex_pow(complex_t base, int exponent) {
    complex_t result = {1.0, 0.0};
    for (int i = 0; i < exponent; i++) {
        result = complex_mul(result, base);
    }
    return result;
}

complex_t complex_input() {
    char str[100];
    complex_t num;
    printf("Enter complex number in the format: real part + imag part * i\n");
    fgets(str, sizeof(str), stdin);
    sscanf(str, "%lf%c%lf%c", &num.real, &str[0], &num.imag, &str[1]);
    return num;
}

void print_complex(complex_t num) {
    if (num.imag >= 0) {
        printf("%.2f + %.2fi\n", num.real, num.imag);
    } else {
        printf("%.2f - %.2fi\n", num.real, -num.imag);
    }
}

int main() {
    complex_t num1, num2, result;

    num1 = complex_input();
    num2 = complex_input();

    result = complex_add(num1, num2);
    printf("Sum:\n");
    print_complex(result);

    result = complex_sub(num1, num2);
    printf("Difference:\n");
    print_complex(result);

    result = complex_mul(num1, num2);
    printf("Product:\n");
    print_complex(result);

    result = complex_div(num1, num2);
    printf("Quotient:\n");
    print_complex(result);

    result = complex_sqrt(complex_mul(num1, num1));
    printf("Square Root:\n");
    print_complex(result);

    result = complex_pow(num1, 3);
    printf("Cube Root:\n");
    print_complex(result);

