typedef struct {
    int data;
    size_t size;
} DataElement;

void write_binary_file(const char *filename, DataElement *data, size_t num_elements) {
    FILE *file = fopen(filename, "wb");

    if (file == NULL) {
        perror("Error opening file for writing");
        exit(EXIT_FAILURE);
    }

    size_t size = sizeof(DataElement) * num_elements;
    fwrite(data, size, 1, file);
    fclose(file);
}

void read_binary_file(const char *filename, DataElement *data, size_t num_elements) {
    FILE *file = fopen(filename, "rb");

    if (file == NULL) {
        perror("Error opening file for reading");
        exit(EXIT_FAILURE);
    }

    size_t size = sizeof(DataElement) * num_elements;
    fread(data, size, 1, file);
    fclose(file);
}

int main() {
