    // Initialize data array with some values
    for (size_t i = 0; i < NUM_ELEMENTS; ++i) {
        data[i].data = i * 2;
        data[i].size = sizeof(int);
    }

    // Write data to binary file
    write_binary_file(FILE_NAME, data, NUM_ELEMENTS);

    // Read data from binary file
    DataElement read_data[NUM_ELEMENTS];
    read_binary_file(FILE_NAME, read_data, NUM_ELEMENTS);

    // Compare read data with original data
    for (size_t i = 0; i < NUM_ELEMENTS; ++i) {
