// Function to generate a timestamp in the format "YYYY-MM-DD HH:MM:SS"
void generate_timestamp(char *timestamp) {
    time_t now;
    struct tm *time_info;

    time(&now);
    time_info = localtime(&now);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);
