  {81, 82, 83, 84, 85, 86, 87, 88, 89, 90},
  {91, 92, 93, 94, 95, 96, 97, 98, 99, 100}
};

// Define the start and end points
int start_x = 1, start_y = 1;
int end_x = 1, end_y = 1;

// Define the visited matrix
int visited[GRID_SIZE][GRID_SIZE] = {0};

// Define the path matrix
int path[GRID_SIZE][GRID_SIZE] = {0};

// Define the algorithm
void unique_c_pathfinding_algorithm() {
  // Initialize the starting point
  visited[start_x][start_y] = 1;
  path[start_x][start_y] = 1;

  // Loop through the grid
  for (int i = 0; i < GRID_SIZE; i++) {
    for (int j = 0; j < GRID_SIZE; j++) {
      // If the current point is the end point
      if (i == end_x && j == end_y) {
        // Print the path
        printf("Path: ");
        for (int k = 0; k < GRID_SIZE; k++) {
          for (int l = 0; l < GRID_SIZE; l++) {
            if (path[k][l] == 1) {
              printf("(%d, %d) ", k, l);
            }
          }
        }
        printf("\n");
        return;
      }

      // If the current point is not visited
      if (visited[i][j] == 0) {
        // Mark the current point as visited
        visited[i][j] = 1;

        // Check if the current point is a valid neighbor
        if (i > 0 && visited[i - 1][j] == 0) {
          // Mark the neighbor as visited
          visited[i - 1][j] = 1;
          // Update the path
          path[i - 1][j] = 1;
        }
        if (i < GRID_SIZE - 1 && visited[i + 1][j] == 0) {
          // Mark the neighbor as visited
          visited[i + 1][j] = 1;
          // Update the path
          path[i + 1][j] = 1;
        }
        if (j > 0 && visited[i][j - 1] == 0) {
          // Mark the neighbor as visited
          visited[i][j - 1] = 1;
          // Update the path
          path[i][j - 1] = 1;
        }
        if (j < GRID_SIZE - 1 && visited[i][j + 1] == 0) {
          // Mark the neighbor as visited
          visited[i][j + 1] = 1;
          // Update the path
          path[i][j + 1] = 1;
        }
      }
    }
  }
}

// Main function
int main() {
  // Call the algorithm
  unique_c_pathfinding_algorithm();
  return 0;
}

