#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>

#define HTTP_PORT 80
#define HTTP_GET "GET / HTTP/1.1\r\nHost: %s\r\nConnection: close\r\n\r\n"

int main(int argc, char **argv) {
  if (argc != 2) {
    fprintf(stderr, "Usage: %s <hostname>\n", argv[0]);
    return EXIT_FAILURE;
  }

  int sockfd = socket(AF_INET, SOCK_STREAM, 0);
  if (sockfd < 0) {
    perror("socket");
    return EXIT_FAILURE;
  }

  struct sockaddr_in servaddr;
  memset(&servaddr, 0, sizeof(servaddr));
  servaddr.sin_family = AF_INET;
  servaddr.sin_port = htons(HTTP_PORT);
  if (inet_pton(AF_INET, argv[1], &servaddr.sin_addr) <= 0) {
    perror("inet_pton");
    close(sockfd);
    return EXIT_FAILURE;
  }

  if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
    perror("connect");
    close(sockfd);
    return EXIT_FAILURE;
  }

  char request[1024];
  snprintf(request, sizeof(request), HTTP_GET, argv[1]);
  if (send(sockfd, request, strlen(request), 0) < 0) {
    perror("send");
    close(sockfd);
    return EXIT_FAILURE;
  }

  char response[4096];
  int n;
  while ((n = recv(sockfd, response, sizeof(response), 0)) > 0) {
    fwrite(response, 1, n, stdout);
  }
  if (n < 0) {
    perror("recv");
  }

  close(sockfd);
  return EXIT_SUCCESS;
}

