void DichXuongXoayVongCacHangTrongMaTran(int a[][MAX], int dong, int cot)
{
    // Dùng mảng phụ lưu lại hàng cuối
    int temp[MAX];
    for(int i = 0; i < dong; i++)
    {
        temp[i] = a[cot - 1][i];
    }
    // Gán từ cuối lên
    for(int i = cot - 1; i >= 1; i--)
    {
        for(int j = 0; j < dong; j++)
        {
            a[i][j] = a[i - 1][j];
        }
    }
    // Gán mảng phụ vào hàng đầu
    for(int i = 0; i < dong; i++)
    {
        a[0][i] = temp[i];
    }
}

