#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <math.h>

#define WIDTH 10
#define HEIGHT 10
#define MAX_NODES WIDTH * HEIGHT

typedef struct {
    int x, y;
} Node;

typedef struct {
    Node nodes[MAX_NODES];
    int count;
} NodeList;

typedef struct {
    Node node;
    float gCost; // Cost from start
    float hCost; // Heuristic cost to end
    float fCost; // Total cost (g + h)
    Node* parent;
} AStarNode;

AStarNode grid[WIDTH][HEIGHT];
NodeList openList, closedList;

// Function prototypes
void initGrid();
float heuristic(Node a, Node b);
bool isNodeInList(NodeList* list, Node node);
void addNodeToList(NodeList* list, Node node);
void removeNodeFromList(NodeList* list, Node node);
Node getLowestFCostNode();
bool isValid(Node node);
void reconstructPath(Node* currentNode);
void aStarPathfinding(Node start, Node end);

int main() {
    initGrid();
    Node start = {0, 0};
    Node end = {9, 9};

    aStarPathfinding(start, end);

    return 0;
}

void initGrid() {
    for (int y = 0; y < HEIGHT; y++) {
        for (int x = 0; x < WIDTH; x++) {
            grid[x][y] = (AStarNode){{x, y}, INFINITY, INFINITY, INFINITY, NULL};
        }
    }
}

float heuristic(Node a, Node b) {
    return fabs(a.x - b.x) + fabs(a.y - b.y);
}

bool isNodeInList(NodeList* list, Node node) {
    for (int i = 0; i < list->count; i++) {
        if (list->nodes[i].x == node.x && list->nodes[i].y == node.y) {
            return true;
        }
    }
    return false;
}

void addNodeToList(NodeList* list, Node node) {
    if (!isNodeInList(list, node)) {
        list->nodes[list->count++] = node;
    }
}

void removeNodeFromList(NodeList* list, Node node) {
    for (int i = 0; i < list->count; i++) {
        if (list->nodes[i].x == node.x && list->nodes[i].y == node.y) {
            list->nodes[i] = list->nodes[--list->count];
            return;
        }
    }
}

Node getLowestFCostNode() {
    float lowestFCost = INFINITY;
    Node lowestNode = {0, 0};

    for (int i = 0; i < openList.count; i++) {
        Node currentNode = openList.nodes[i];
        AStarNode* astarNode = &grid[currentNode.x][currentNode.y];

        if (astarNode->fCost < lowestFCost) {
            lowestFCost = astarNode->fCost;
            lowestNode = currentNode;
        }
    }
    return lowestNode;
}

bool isValid(Node node) {
    return (node.x >= 0 && node.x < WIDTH && node.y >= 0 && node.y < HEIGHT);
}

void reconstructPath(Node* currentNode) {
    while (currentNode != NULL) {
        printf("(%d, %d) ", currentNode->x, currentNode->y);
        currentNode = grid[currentNode->x][currentNode->y].parent;
    }
    printf("\n");
}

void aStarPathfinding(Node start, Node end) {
    openList.count = 0;
    closedList.count = 0;

    grid[start.x][start.y].gCost = 0;
    grid[start.x][start.y].hCost = heuristic(start, end);
    grid[start.x][start.y].fCost = grid[start.x][start.y].hCost;
    grid[start.x][start.y].parent = NULL;

    addNodeToList(&openList, start);

    while (openList.count > 0) {
        Node currentNode = getLowestFCostNode();

        // If reached the end
        if (currentNode.x == end.x && currentNode.y == end.y) {
            printf("Path found: ");
            reconstructPath(&currentNode);
            return;
        }

        removeNodeFromList(&openList, currentNode);
        addNodeToList(&closedList, currentNode);

        // Check all neighbors
        Node neighbors[4] = {
            {currentNode.x - 1, currentNode.y}, // Left
            {currentNode.x + 1, currentNode.y}, // Right
            {currentNode.x, currentNode.y - 1}, // Up
            {currentNode.x, currentNode.y + 1}, // Down
        };

        for (int i = 0; i < 4; i++) {
            Node neighbor = neighbors[i];
            if (!isValid(neighbor) || isNodeInList(&closedList, neighbor)) {
                continue; // Ignore invalid or closed nodes
            }

            AStarNode* neighborNode = &grid[neighbor.x][neighbor.y];
            float tentativeGCost = grid[currentNode.x][currentNode.y].gCost + 1; // Assume cost of movement is 1

            if (!isNodeInList(&openList, neighbor)) {
                addNodeToList(&openList, neighbor);
            } else if (tentativeGCost >= neighborNode->gCost) {
                continue; // Not a better path
            }

            neighborNode->parent = &grid[currentNode.x][currentNode.y];
            neighborNode->gCost = tentativeGCost;
            neighborNode->hCost = heuristic(neighbor, end);
            neighborNode->fCost = neighborNode->gCost + neighborNode->hCost;
        }
    }

    printf("No path found!\n");
}

