/* Warehouse Management System Example Program
 *
 * This program is a basic example of a warehouse management system.
 * It allows users to create, update, and delete products, as well as
 * view a list of all products in the warehouse.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PRODUCTS 100

// Define a structure to represent a product
typedef struct {
  char name[50];
  int quantity;
} Product;

// Define an array to store products
Product products[MAX_PRODUCTS];

// Define a function to add a product to the warehouse
void addProduct(char* name, int quantity) {
  for (int i = 0; i < MAX_PRODUCTS; i++) {
    if (products[i].quantity == 0) {
      strcpy(products[i].name, name);
      products[i].quantity = quantity;
      break;
    }
  }
}

// Define a function to update a product in the warehouse
void updateProduct(char* name, int quantity) {
  for (int i = 0; i < MAX_PRODUCTS; i++) {
    if (strcmp(products[i].name, name) == 0) {
      products[i].quantity += quantity;
      break;
    }
  }
}

// Define a function to delete a product from the warehouse
void deleteProduct(char* name) {
  for (int i = 0; i < MAX_PRODUCTS; i++) {
    if (strcmp(products[i].name, name) == 0) {
      products[i].quantity = 0;
      break;
    }
  }
}

// Define a function to print a list of all products in the warehouse
void printProducts() {
  for (int i = 0; i < MAX_PRODUCTS; i++) {
    if (products[i].quantity > 0) {
      printf("%s: %d\n", products[i].name, products[i].quantity);
    }
  }
}

int main() {
  // Add some products to the warehouse
  addProduct("Apples", 10);
  addProduct("Bananas", 5);
  addProduct("Oranges", 20);

  // Update the quantity of a product
  updateProduct("Apples", 5);

  // Delete a product from the warehouse
  deleteProduct("Bananas");

  // Print a list of all products in the warehouse
  printProducts();

  return 0;
}

