#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <complex.h>

typedef struct {
    int real;
    int imag;
} surreal_number;

void surreal_add(surreal_number a, surreal_number b, surreal_number *result) {
    result->real = a.real + b.real;
    result->imag = a.imag + b.imag;
}

void surreal_subtract(surreal_number a, surreal_number b, surreal_number *result) {
    result->real = a.real - b.real;
    result->imag = a.imag - b.imag;
}

void surreal_multiply(surreal_number a, surreal_number b, surreal_number *result) {
    result->real = a.real * b.real - a.imag * b.imag;
    result->imag = a.real * b.imag + a.imag * b.real;
}

void surreal_divide(surreal_number a, surreal_number b, surreal_number *result) {
    double denominator = sqrt(pow(b.real, 2) + pow(b.imag, 2));
    result->real = (a.real * b.real + a.imag * b.imag) / denominator;
    result->imag = (a.imag * b.real - a.real * b.imag) / denominator;
}

int main() {
    surreal_number a = {1, 2};
    surreal_number b = {3, 4};
    surreal_number result;

    printf("Before operation:\n");
    printf("a = %d + %di\n", a.real, a.imag);
    printf("b = %d + %di\n", b.real, b.imag);

    surreal_add(a, b, &result);
    printf("After addition:\n");
    printf("result = %d + %di\n", result.real, result.imag);

    surreal_subtract(a, b, &result);
    printf("After subtraction:\n");
    printf("result = %d + %di\n", result.real, result.imag);

    surreal_multiply(a, b, &result);
    printf("After multiplication:\n");
    printf("result = %d + %di\n", result.real, result.imag);

    surreal_divide(a, b, &result);
    printf("After division:\n");
    printf("result = %d + %di\n", result.real, result.imag);

    return 0;
}

