	unsigned int uindex = index;
	if(index > getTotal()) {
		return NULL;
	} else {
		if(uindex < ani->size()) {
			return static_cast<Creature *>(ani->at(index));
		} else if(uindex < npc->size()) {
			unsigned int npcindex = index - ani->size();
