#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define WIDTH 80
#define HEIGHT 20

int main()
{
    int x_pos = WIDTH / 2;
    int y_pos = HEIGHT - 1;
    int ball_x = WIDTH / 2;
    int ball_y = HEIGHT / 2;
    int direction = 1;
    int score = 0;

    char board[HEIGHT][WIDTH];
    for (int y = 0; y < HEIGHT; y++)
    {
        for (int x = 0; x < WIDTH; x++)
        {
            board[y][x] = '-';
        }
    }

    board[y_pos][x_pos] = 'O';
    board[ball_y][ball_x] = 'B';

    FILE *fp = fopen("sounds.wav", "rb");
    if (fp == NULL)
    {
        printf("Error opening sound file.\n");
        return 1;
    }

    time_t start_time = time(NULL);
    while (!score)
    {
        sleep(0.05);

        int move = rand() % 2;
        switch (move)
        {
            case 0:
                direction = -1;
                break;
            case 1:
                direction = 1;
                break;
        }

        ball_x += direction * 5;

        if (ball_x >= WIDTH || ball_x < 0)
        {
            direction *= -1;
        }

        board[ball_y][ball_x] = 'B';
        board[y_pos][x_pos] = 'O';

        printf("\033[2J");
        for (int y = 0; y < HEIGHT; y++)
        {
            for (int x = 0; x < WIDTH; x++)
            {
                printf("%c ", board[y][x]);
            }
            printf("\n");
        }

        if (ball_y == y_pos)
        {
            score = 1;
            fclose(fp);
            printf("You win!");
        }
    }

    fclose(fp);
    return 0;
}

