    light->state = OFF;
}

void set_brightness(light_t *light, int brightness) {
    light->brightness = brightness;
}

void set_color(light_t *light, int color) {
    light->color = color;
}

void set_pattern(light_t *light, int pattern) {
    light->pattern = pattern;
}

void set_duration(light_t *light, int duration) {
    light->duration = duration;
}

