#include <arpa/inet.h>
#include <netinet/tcp.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <unistd.h>

#define PORT 8080
#define MAX_CLIENTS 10
#define BUFFER_SIZE 1024

int main() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    char buffer[BUFFER_SIZE] = {0};
    int client_count = 0;

    // Create socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    // Set up the address structure
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Bind the socket to the address and port
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    // Listen for incoming connections
    if (listen(server_fd, MAX_CLIENTS) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    printf("Server started on port %d\n", PORT);

    while (1) {
        // Accept a new connection
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address,
                                 (socklen_t *)&addrlen)) < 0) {
            perror("accept");
            exit(EXIT_FAILURE);
        }

        // Increment the client count
        client_count++;
        printf("New client connected: %s:%d\n",
               inet_ntoa(address.sin_addr), ntohs(address.sin_port));

        // Send a personalized greeting message to the client
        char greeting[BUFFER_SIZE] = {0};
        snprintf(greeting, sizeof(greeting), "Welcome to our server, client %d!",
                 client_count);
        send(new_socket, greeting, strlen(greeting), 0);

        // Receive data from the client and send it back
        while (1) {
            memset(buffer, 0, BUFFER_SIZE);
            int read_size = recv(new_socket, buffer, BUFFER_SIZE, 0);
            if (read_size <= 0) {
                break;
            }

            printf("Client %d sent: %s\n", client_count, buffer);
            send(new_socket, buffer, read_size, 0);
        }

        // Close the connection and decrement the client count
        close(new_socket);
        client_count--;
        printf("Client %d disconnected\n", client_count);
    }

    return 0;
}

