// TaskScheduler.c

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/time.h>

#define MAX_TASKS 100

// Task structure
typedef struct {
  int pid;
  char *command;
  int priority;
} Task;

// Global variables
Task tasks[MAX_TASKS];
int num_tasks = 0;

// Function to create a new task
void create_task(char *command, int priority) {
  tasks[num_tasks].pid = fork();
  tasks[num_tasks].command = command;
  tasks[num_tasks].priority = priority;
  num_tasks++;
}

// Function to execute a task
void execute_task(int index) {
  system(tasks[index].command);
  waitpid(tasks[index].pid, NULL, 0);
}

// Function to sort tasks by priority
void sort_tasks() {
  int i, j;
  Task temp;
  for (i = 0; i < num_tasks - 1; i++) {
    for (j = i + 1; j < num_tasks; j++) {
      if (tasks[i].priority < tasks[j].priority) {
        temp = tasks[i];
        tasks[i] = tasks[j];
        tasks[j] = temp;
      }
    }
  }
}

// Function to execute tasks in order of priority
void execute_tasks() {
  int i;
  for (i = 0; i < num_tasks; i++) {
    execute_task(i);
  }
}

// Main function
int main() {
  // Create some tasks
  create_task("ls -l", 1);
  create_task("ps -ef", 2);
  create_task("top", 3);
  create_task("free", 4);
  create_task("df -h", 5);

  // Sort tasks by priority
  sort_tasks();

  // Execute tasks in order of priority
  execute_tasks();

  return 0;
}

