    int board[6] = {0, 0, 0, 0, 0, 0};

    // Initialize the game pieces' positions
    board[0] = 1;
    board[2] = 2;
    board[4] = 3;

    // Create a loop to handle the game turns
    while (board[0] != 3 || board[2] != 3 || board[4] != 3)
    {
        // Get the player's move
        int move = getMove();

        // Validate the move
        if (validMove(move, board) == 0)
        {
            // Invalid move, prompt the player to try again
            printf("Invalid move. Please try again.\n");
            continue;
        }

        // Make the move
        makeMove(move, board);

        // Print the updated board
        printBoard(board);
    }

    // Game over, print the winner
    printf("Congratulations! You won the game!");

    return 0;
}

// Get the player's move
int getMove()
{
    int move;

    printf("Enter your move (1-6): ");
    scanf("%d", &move);

    return move;
}

// Validate the move
int validMove(int move, int board[])
{
    if (move < 1 || move > 6)
    {
        return 0;
    }

    if (board[move] != 0)
    {
        return 0;
    }

    return 1;
}

// Make the move
void makeMove(int move, int board[])
{
    board[move] = 1;
}

// Print the board
