// Function for checking if a number is prime
int isPrime(int num) {
    int i;
    for(i=2; i<=(int)sqrt(num); i++) {
        if(num%i == 0) {
            return 0;
        }
    }
    return 1;
}

// Function for generating a random prime number
int generatePrime() {
    int num = rand() % 100 + 1;
    while(!isPrime(num)) {
        num = rand() % 100 + 1;
    }
    return num;
}

// Function for finding the greatest common divisor of two numbers
int gcd(int a, int b) {
    if(b == 0) {
        return a;
    }
    return gcd(b, a%b);
}

// Function for finding the private key given a public key and the two prime numbers used to generate it
int findPrivateKey(int pubKey, int prime1, int prime2) {
    int n = (prime1-1) * (prime2-1);
    int i;
    for(i=2; i<n; i++) {
        if(gcd(i, n) == 1 && ((i*pubKey) % n) == 1) {
            return i; 
        }
    }
}

int main() {
    // Generate two prime numbers
    srand(time(NULL));
    int prime1 = generatePrime();
    int prime2 = generatePrime();

    // Calculate n and phi(n)
    int n = prime1 * prime2;
    int phi = (prime1-1) * (prime2-1);

    // Generate public key e
    int e = rand() % ((phi-1) - 2 + 1) + 2;
    while(gcd(e, phi) != 1) {
        e = rand() % ((phi-1) - 2 + 1) + 2;
    }

    // Calculate private key d
    int d = findPrivateKey(e, prime1, prime2);

    // Print out the public and private keys along with the prime numbers used to generate them
    printf("Public Key (e): %d\nPrivate Key (d): %d\nPrime Number 1: %d\nPrime Number 2: %d\n", e, d, prime1, prime2);

    // Get a message to encrypt
    printf("Enter a message to encrypt: ");
    char message[100];
    fgets(message, 100, stdin);

    // Encrypt the message
    int i;
    int encrypted[100];
    int decrypted[100];
    for(i=0; i<strlen(message); i++) {
        if(message[i] == ' ') {
            encrypted[i] = (int)' ';
            decrypted[i] = (int)' ';
            continue;
        }
        int num = ((int)message[i] - 96); // Convert the letter to a number (a=1, b=2, etc.)
        encrypted[i] = (int)pow(num, e) % n; // Apply the public key to the number
        decrypted[i] = (int)pow(encrypted[i], d) % n; // Apply the private key to the encrypted number
    }
    printf("Encrypted Message: ");
    for(i=0; i<strlen(message); i++) {
        printf("%d ", encrypted[i]);
    }
    printf("\nDecrypted Message: ");
    for(i=0; i<strlen(message); i++) {
        if(encrypted[i] == (int)' ') {
            printf("%c", (char)encrypted[i]);
            continue;
        }
        int num = (int)sqrt(decrypted[i]) + 96; // Reverse the number to its corresponding letter
        printf("%c", (char)num);
    }
    printf("\n");

    return 0;
}

#include<bits/stdc++.h>
using namespace std;


void construct_tree(int arr[],int segtree[],int low,int high,int pos)
{

	if(low==high)
	{
		segtree[pos]=arr[low];
		return;
	}
	int mid=(low+high)/2;
	construct_tree(arr,segtree,low,mid,(2*pos)+1);
	construct_tree(arr,segtree,mid+1,high,(2*pos)+2);
	segtree[pos]=min(segtree[(2*pos)+1],segtree[(2*pos)+2]);

}

// Below function computes minimum in a range
int range_query(int arr[],int segtree[],int qlow,int qhigh,int low,int high,int pos){

	if(qlow<=low && qhigh >=high)  //total overlap
	{
		return segtree[pos];
	}

	if(qlow>high || low>qhigh)    // No Overlap
	{
		return 10000;
	}
	int mid=(low+high)>>1;

	return min(range_query(arr,segtree,qlow,qhigh,low,mid,2*pos+1),range_query(arr,segtree,qlow,qhigh,mid+1,high,2*pos+2));

}



int main()
{
	int n;
	cin>>n;
	int arr[n];
	int segtree[4*n];
	for(int i=0;i<n;i++)
	{
		cin>>arr[i];
	}
	construct_tree(arr,segtree,0,n-1,0);
	int t;
	cin>>t;
	while(t--)
	{
		int qlow,qhigh;
		cin>>qlow>>qhigh;
		cout<<range_query(arr,segtree,qlow,qhigh,0,n-1,0)<<endl;
	}
	return 0;

}

// finding number of occurrences of numbers appearing more than once in an array

#include<iostream>
#include<stdlib.h>

using namespace std;

#define MAX 8

void display(int* a){

	int i = 0;

	cout << endl;
	while(i < MAX){

		cout << a[i] << "  ";
		i++;

	}

	cout << endl;

}

void finddups(int* a){

	int dups[MAX/2];	// array to maintain numbers appearing more than once
	int  dupfound, dupcount, dupindex;

	// index of dups array which increments every time when a number found is occurring more
	// than once and is not in dups array.
	dupcount = 0;
	// last index of number in original array which has more than one occurrence in original array
	dupindex = 0;

	for(int i = 0; i < MAX; i++){

		dupfound = 0;

		// checking is number is there in dups array
		for (int p = 0; p < MAX/2; p++){

			if(a[i] == dups[p])
				dupfound = 1;

		}

		if(dupfound == 0){

			int count = 0; // number of occurrences of a number
			for(int j = 0; j < MAX; j++){

				if (a[i] == a[j]){

					count++;
					dupindex = i;

				}

			}

			if (count != 1){

				// saving number appearing more than once in dups array
				dups[dupcount] = a[dupindex];
				dupcount++;
				cout << endl << a[i] << " occurs " << count << " times" << endl;

			}

		}

	}

}

int main(){

	int arr1[MAX] = {9,4,22,6,22,9,89,22};

	display(arr1);
	finddups(arr1);

	return 0;

}

