#include <string.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netdb.h>

int main() {
    struct sockaddr_in serverAddr;
    struct sockaddr_in clientAddr;
    int serverSockfd, clientSockfd, portNum;
    char buffer[1024];

    memset((char *) &serverAddr, 0, sizeof(serverAddr));
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_port = htons(8080);
    serverAddr.sin_addr.s_addr = inet_addr("127.0.0.1");

    if ((serverSockfd = socket(AF_INET, SOCK_STREAM, 0)) == -1) {
        printf("Error opening socket\n");
        return 1;
    }

    if (bind(serverSockfd, (struct sockaddr *) &serverAddr, sizeof(serverAddr)) == -1) {
        printf("Error binding socket\n");
        return 1;
    }

    if (listen(serverSockfd, 5) == -1) {
        printf("Error listening on socket\n");
        return 1;
    }

    while (1) {
        printf("Waiting for client connection...\n");
        if ((clientSockfd = accept(serverSockfd, (struct sockaddr *) &clientAddr, (socklen_t *) &portNum)) == -1) {
            printf("Error accepting connection\n");
            return 1;
        }

        printf("Connected to client with IP: %s and port: %d\n", inet_ntoa(clientAddr.sin_addr), ntohs(clientAddr.sin_port));

        while (1) {
            memset(buffer, 0, sizeof(buffer));
            if ((recv(clientSockfd, buffer, sizeof(buffer), 0)) < 0) {
                printf("Error receiving from client\n");
                return 1;
            }

            printf("Received data from client: %s\n", buffer);

            memset(buffer, 0, sizeof(buffer));
            if ((send(clientSockfd, "HTTP/1.1 200 OK\r\n\r\n", strlen("HTTP/1.1 200 OK\r\n\r\n"), 0)) < 0) {
                printf("Error sending data to client\n");
                return 1;
            }

            memset(buffer, 0, sizeof(buffer));
            if ((recv(serverSockfd, buffer, sizeof(buffer), 0)) < 0) {
                printf("Error receiving from server\n");
                return 1;
            }

            printf("Received data from server: %s\n", buffer);

            memset(buffer, 0, sizeof(buffer));
            if ((send(clientSockfd, buffer, strlen(buffer), 0)) < 0) {
                printf("Error sending data to client\n");
                return 1;
            }

            memset(buffer, 0, sizeof(buffer));
            if ((recv(serverSockfd, buffer, sizeof(buffer), 0)) < 0) {
                printf("Error receiving from server\n");
                return 1;
            }

            printf("Received data from server: %s\n", buffer);
        }

        close(clientSockfd);
    }

    close(serverSockfd);
    return 0;
}

