#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <unistd.h>

#define PORT_MIN 1
#define PORT_MAX 65535
#define IP_ADDRESS "127.0.0.1" // Replace with the target IP address
#define BUFFER_SIZE 1024

bool is_port_open(int port) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return false;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);
    inet_pton(AF_INET, IP_ADDRESS, &server_addr.sin_addr);

    int connection_status = connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr));

    if (connection_status < 0) {
        perror("connect");
        close(sockfd);
        return false;
    }

    close(sockfd);
    return true;
}

void print_port_status(int port) {
    if (is_port_open(port)) {
        printf("%d: OPEN\n", port);
    } else {
        printf("%d: CLOSED\n", port);
    }
}

int main() {
    printf("Scanning ports from %d to %d on %s...\n", PORT_MIN, PORT_MAX, IP_ADDRESS);

    for (int port = PORT_MIN; port <= PORT_MAX; ++port) {
        print_port_status(port);
        usleep(100000); // Sleep for 100ms to avoid overwhelming the target system
    }

    return 0;
}

