#define MAX_STACK_SIZE 100
#define PI 3.14159265358979323846

// Global stack variables
double stack[MAX_STACK_SIZE];
int top = -1;

// Stack functions
void push(double x) {
    if (top == MAX_STACK_SIZE - 1) {
        printf("Stack Overflow\n");
        exit(EXIT_FAILURE);
    }
    else {
        stack[++top] = x;
    }
}

double pop() {
    if (top == -1) {
        printf("Stack Underflow\n");
        exit(EXIT_FAILURE);
    }
    else {
        return stack[top--];
    }
}

