#define ARRAY_SIZE 100

// Structure to hold the array of integers and the current position
typedef struct {
    int arr[ARRAY_SIZE];
    int position;
} search_t;

// Function to initialize the search array and position
void init_search(search_t *s) {
    int i;
    for (i = 0; i < ARRAY_SIZE; i++) {
        s->arr[i] = i * 2;
    }
    s->position = 0;
}

// Function to perform the search
int search(search_t *s, int target) {
    int low = 0, high = ARRAY_SIZE - 1;

    // Use a randomized search strategy
    if (rand() % 2 == 0) {
        low = (high - low) / 2 + low;
    } else {
        high = (high - low) / 2 + low;
    }

    while (low <= high) {
        if (s->arr[low] == target) {
            return low;
        }
        if (s->arr[low] > target) {
            high = low - 1;
        } else {
            low = low + 1;
        }
    }
    return -1;
}

int main() {
    search_t s;
    init_search(&s);

    int target = 42;
    int result = search(&s, target);

    if (result != -1) {
        printf("Found %d at position %d\n", target, result);
    } else {
        printf("Not found\n");
    }

    return 0;
}

