void* move_robot(void* arg) {
    Robot* robot = (Robot*)arg;
    int moves_count = 0;

    while(1) {
        pthread_mutex_lock(&robot->lock);

        int direction = rand() % NUM_MOVES;  // Pick a random move
        int new_x = robot->x + directions[direction].dx;
        int new_y = robot->y + directions[direction].dy;

        // Check boundaries first
        if (new_x >= 0 && new_x < GRID_SIZE && new_y >= 0 && new_y < GRID_SIZE) {
            // Simulate paranoia: ensure the new position is not under "surveillance"
            if (!is_under_surveillance(new_x, new_y)) {
                robot->x = new_x;
                robot->y = new_y;
                moves_count++;
                printf("Robot moved to (%d, %d)\n", robot->x, robot->y);
            } else {
                printf("Movement to (%d, %d) blocked due to paranoia!\n", new_x, new_y);
            }
        }
        pthread_mutex_unlock(&robot->lock);
        usleep(100000); // Wait for 0.1 seconds before moving again
    }
    return NULL;
}

int is_under_surveillance(int x, int y) {
