#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define BLOCK_SIZE 64

// Function to encrypt the plaintext using a given key
void encrypt(char* plaintext, char* key, char* ciphertext) {
    // Convert key to a byte array
    unsigned char keyBytes[strlen(key)];
    for (int i = 0; i < strlen(key); i++) {
        keyBytes[i] = (unsigned char) key[i];
    }

    // Convert plaintext to a byte array
    unsigned char plaintextBytes[strlen(plaintext)];
    for (int i = 0; i < strlen(plaintext); i++) {
        plaintextBytes[i] = (unsigned char) plaintext[i];
    }

    // Create a byte array for the ciphertext
    unsigned char ciphertextBytes[strlen(plaintext) + 1];

    // Perform encryption using XOR operation
    for (int i = 0; i < strlen(plaintext); i++) {
        ciphertextBytes[i] = plaintextBytes[i] ^ keyBytes[i % strlen(key)];
    }
    ciphertextBytes[strlen(plaintext)] = '\0';

    // Convert ciphertext bytes to a string
    strcpy(ciphertext, (char*) ciphertextBytes);
}

// Function to decrypt the ciphertext using a given key
void decrypt(char* ciphertext, char* key, char* plaintext) {
    // Convert key to a byte array
    unsigned char keyBytes[strlen(key)];
    for (int i = 0; i < strlen(key); i++) {
        keyBytes[i] = (unsigned char) key[i];
    }

    // Convert ciphertext to a byte array
    unsigned char ciphertextBytes[strlen(ciphertext)];
    for (int i = 0; i < strlen(ciphertext); i++) {
        ciphertextBytes[i] = (unsigned char) ciphertext[i];
    }

    // Create a byte array for the plaintext
    unsigned char plaintextBytes[strlen(ciphertext) + 1];

    // Perform decryption using XOR operation
    for (int i = 0; i < strlen(ciphertext); i++) {
        plaintextBytes[i] = ciphertextBytes[i] ^ keyBytes[i % strlen(key)];
    }
    plaintextBytes[strlen(ciphertext)] = '\0';

    // Convert plaintext bytes to a string
    strcpy(plaintext, (char*) plaintextBytes);
}

int main() {
    // Input plaintext and key
    char plaintext[] = "Hello, world!";
    char key[] = "secret";

    // Encrypt the plaintext
    char ciphertext[strlen(plaintext) + 1];
    encrypt(plaintext, key, ciphertext);

    // Decrypt the ciphertext
    char plaintext2[strlen(plaintext) + 1];
    decrypt(ciphertext, key, plaintext2);

    // Output the results
    printf("Plaintext: %s\n", plaintext);
    printf("Ciphertext: %s\n", ciphertext);
    printf("Decrypted plaintext: %s\n", plaintext2);

    return 0;
}

