    int y;
} Point;

int main() {
    // Initialize the game board
    int board[MAX_ROWS][MAX_COLS] = {0};
    Point player_position = {0, 0};
    Point enemy_position = {MAX_ROWS-1, MAX_COLS-1};

    // Start the game
    printf("Welcome to the game of C!n");
    printf("You are a brave knight on a quest to save your kingdom from evil forces.\n");
    printf("Your enemy, the Dark Lord, is hiding in one of the cells of the game board.\n");
    printf("Use your wit and strategy to find him and defeat him!\n\n");

    // Game loop
    while (1) {
        // Print the current state of the game board
        printf("Current board:\n");
        for (int i = 0; i < MAX_ROWS; i++) {
            for (int j = 0; j < MAX_COLS; j++) {
                if (board[i][j] == 1) {
                    printf("E");
                } else if (board[i][j] == 2) {
                    printf("P");
                } else {
                    printf(" ");
                }
            }
            printf("\n");
        }

        // Check for victory conditions
        if (player_position.x == enemy_position.x && player_position.y == enemy_position.y) {
            printf("Congratulations! You have defeated the Dark Lord!\n");
            break;
        } else if (player_position.x == -1 || player_position.y == -1) {
            printf("Game over. You have lost to the Dark Lord.\n");
            break;
        }

        // Move player or enemy
        if (rand() % 2 == 0) {
            Point new_player_position = {player_position.x, player_position.y};
            if (board[new_player_position.x][new_player_position.y] == 2) {
                new_player_position.x += 1;
                if (new_player_position.x == MAX_ROWS) {
                    new_player_position.x = 0;
                }
            } else if (board[new_player_position.x][new_player_position.y] == 1) {
                new_player_position.y += 1;
                if (new_player_position.y == MAX_COLS) {
                    new_player_position.y = 0;
                }
            }
            player_position = new_player_position;
        } else {
            Point new_enemy_position = {enemy_position.x, enemy_position.y};
            if (board[new_enemy_position.x][new_enemy_position.y] == 1) {
                new_enemy_position.x -= 1;
                if (new_enemy_position.x == -1) {
                    new_enemy_position.x = MAX_ROWS;
                }
            } else if (board[new_enemy_position.x][new_enemy_position.y] == 2) {
                new_enemy_position.y -= 1;
                if (new_enemy_position.y == -1) {
                    new_enemy_position.y = MAX_COLS;
                }
            }
            enemy_position = new_enemy_position;
        }

        // Update game board
        board[player_position.x][player_position.y] = 1;
        board[enemy_position.x][enemy_position.y] = 2;
    }

    return 0;
}

