#define MAX_DATA_SIZE 1024
#define SERVER_PORT 8080
#define SERVER_ADDRESS "localhost"

int main(int argc, char *argv[])
{
    int sockfd, n;
    struct sockaddr_in server_addr;
    char send_data[MAX_DATA_SIZE], recv_data[MAX_DATA_SIZE];

    sockfd = socket(AF_INET, SOCK_STREAM, 0);

    if (sockfd == -1)
    {
        printf("Error: could not create socket\n");
        exit(1);
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);
    inet_pton(AF_INET, SERVER_ADDRESS, &server_addr.sin_addr);

    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) == -1)
    {
        printf("Error: could not connect to server\n");
        exit(1);
    }

    printf("Connected to server\n");

    while (1)
    {
        memset(send_data, 0, MAX_DATA_SIZE);
        memset(recv_data, 0, MAX_DATA_SIZE);

        if (send(sockfd, send_data, strlen(send_data), 0) == -1)
        {
            printf("Error: could not send data\n");
            exit(1);
        }

        if ((n = recv(sockfd, recv_data, MAX_DATA_SIZE, 0)) == -1)
        {
            printf("Error: could not receive data\n");
            exit(1);
        }

        printf("Received data: %s\n", recv_data);
    }

    close(sockfd);

    return 0;
}

