#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_ARRAY_SIZE 100

// Function to swap two elements in an array
void swap(int arr[], int i, int j) {
    int temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

// Function to sort the array using bubble sort
void bubble_sort(int arr[], int n) {
    int i, j;

    // Loop until the array is sorted
    for (i = 0; i < n - 1; i++) {
        // Find the largest element in the unsorted portion
        j = i;
        while (j < n - 1 && arr[j] > arr[j + 1]) {
            j++;
        }

        // Swap the largest element with the first element of the unsorted portion
        swap(arr, i, j);

        // Advance the sorted portion
        i++;
    }
}

int main() {
    // Generate a random array of integers
    int arr[MAX_ARRAY_SIZE];
    for (int i = 0; i < MAX_ARRAY_SIZE; i++) {
        arr[i] = rand() % 100;
    }

    // Print the random array
    printf("Random array: ");
    for (int i = 0; i < MAX_ARRAY_SIZE; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");

    // Sort the array using bubble sort
    bubble_sort(arr, MAX_ARRAY_SIZE);

    // Print the sorted array
    printf("Sorted array: ");
    for (int i = 0; i < MAX_ARRAY_SIZE; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");

    return 0;
}

