int main() {
    // Initialize game state
    int state[100][100] = {0};
    int new_state[100][100] = {0};
    int i, j;

    // Print initial state
    for (i = 0; i < 100; i++) {
        for (j = 0; j < 100; j++) {
            printf("%d ", state[i][j]);
        }
        printf("\n");
    }

    // Iterate game
    for (int step = 0; step < 100; step++) {
        // Update new state
        for (i = 0; i < 100; i++) {
            for (j = 0; j < 100; j++) {
                int live_neighbors = 0;
                for (int x = -1; x <= 1; x++) {
                    for (int y = -1; y <= 1; y++) {
                        if (x == 0 && y == 0) continue;
                        if (state[(i+x)%100][(j+y)%100] == 1) {
                            live_neighbors++;
                        }
                    }
                }
                if (live_neighbors == 3) {
                    new_state[i][j] = 1;
                } else if (live_neighbors == 2 && state[i][j] == 1) {
                    new_state[i][j] = 1;
                } else {
                    new_state[i][j] = 0;
                }
            }
        }

        // Print new state
        for (i = 0; i < 100; i++) {
            for (j = 0; j < 100; j++) {
                printf("%d ", new_state[i][j]);
            }
            printf("\n");
        }

        // Update state
        for (i = 0; i < 100; i++) {
            for (j = 0; j < 100; j++) {
                state[i][j] = new_state[i][j];
            }
        }
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

void merge(vector<int> &arr,int left,int mid,int right)
{
  std::vector<int> c(arr.size());
  int l = left;
  int r = mid+1;
  int k=left;
  while(l <= mid && r <= right)
  {
    if(arr[l]<arr[r]){
      c[k]=arr[l]; 
      l++;
      k++;
    }
    else{
      c[k]=arr[r];
      r++;
      k++;
    }
  }
  if(r > right){
    while(l <= mid){
        c[k]=arr[l]; 
        l++;
        k++;
    }
  }
  else{
    while(r <= right){
      c[k]=arr[r];
      r++;
      k++;
    }
  }

  for(int i=left;i<=right;i++)  
    arr[i]=c[i];
}

void mergeSort(vector<int> &arr,int left,int right)
{
  if(left < right)
  {
    int mid = (left+right)/2;
    mergeSort(arr,left,mid);
    mergeSort(arr,mid+1,right);
    merge(arr,left,mid,right);
  }
}
int main()
{
  std::vector<int> arr;
  for(int i=0;i<10;i++)
  {
    arr.push_back(10-i);
  }
  mergeSort(arr,0,arr.size()-1);
  for(int i=0;i<arr.size();i++)
    cout<<arr[i]<<" ";
  cout<<endl;

}

