    //padding plaintext if len is not multiple of 16
    int padding=0;
    if(len%16!=0)
        padding = 16-(len%16); 
    char *input_buffer=(char*)calloc(len+padding+1,sizeof(char));
    strcpy(input_buffer,pt); // copy pt to buffer
    for(int i=0;i<padding;i++){
        strcat(input_buffer,"0"); //pad 0
    }
    int n = strlen(input_buffer)/16;
    printf("Number of 16-byte blocks: %d\n",n);
    printf("Padding is: %d\n",padding);
    for(int i=0;i<n;i++){
        // take plain in parts of 16bytes
        Block b;
        memset(b.b,0,sizeof(b.b));
        memcpy(b.b,input_buffer+(i*16),16);
        if(i==0){
