}

//Shift Rows and SubBytes transformation on block
Block sub_bytes_shift_rows(Block b){
    Block c;
    for(int i=0;i<16;i++){
        c.b[i]=s[b.b[i]]; //substitute using s-box
    }
    // shift rows
    c.b[1]=b.b[5];
    c.b[5]=b.b[9];
    c.b[9]=b.b[13];
    c.b[13]=b.b[1];
    c.b[2]=b.b[10];
    c.b[6]=b.b[14];
    c.b[10]=b.b[2];
    c.b[14]=b.b[6];
    c.b[3]=b.b[15];
    c.b[7]=b.b[3];
    c.b[11]=b.b[7];
    c.b[15]=b.b[11];
    // XOR with key
    for(int i=0;i<16;i++){
        c.b[i]^=k[1].k[i];
    }
    return c;
}

// Inv Shift Rows and Inv_SubBytes transformation on block
Block inv_sub_bytes_shift_rows(Block b){
    Block c;
    // Inv Shift Rows
    c.b[1]=b.b[13];
    c.b[5]=b.b[1];
    c.b[9]=b.b[5];
    c.b[13]=b.b[9];
    c.b[2]=b.b[10];
    c.b[6]=b.b[14];
    c.b[10]=b.b[2];
    c.b[14]=b.b[6];
    c.b[3]=b.b[7];
    c.b[7]=b.b[11];
    c.b[11]=b.b[15];
    c.b[15]=b.b[3];
    // Inv_SubBytes
    for(int i=0;i<16;i++){
        c.b[i]=inv_s[b.b[i]]; 
    }
    // XOR with key
    for(int i=0;i<16;i++){
        c.b[i]^=k[1].k[i];
    }
    return c;
}

// Key Expansion of given key
Key key_expansion(Key k, int round){
    Key t;
    // copy contents of k into t
    memcpy(t.k, k.k, sizeof(t.k));
    //  rotate the word
    unsigned char temp = t.k[0];
    t.k[0] = t.k[1];
    t.k[1] = t.k[2];
    t.k[2] = t.k[3];
    t.k[3] = temp;
    // Byte Substition
    for(int i=0;i<4;i++){
        t.k[i] = s[t.k[i]];
    }
    // XOR with Rcon
    t.k[0] ^= Rcon[round-1];
    // XOR with hi
    for(int i=0;i<4;i++){
        t.k[i] ^= hi.k[i];
    }
    // Update hi with last 4 bytes of t
    memcpy(hi.k, t.k+12, sizeof(unsigned char)*4);
    return t;
}

