#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>

#define MAX_POINTS 100
#define MAX_CLUSTERS 5
#define DIMENSIONS 2
#define MAX_ITERATIONS 100

typedef struct {
    double coords[DIMENSIONS];
} Point;

typedef struct {
    Point centroid;
    Point points[MAX_POINTS];
    int point_count;
} Cluster;

// Function for generating a random point
Point generateRandomPoint() {
    Point p;
    for (int i = 0; i < DIMENSIONS; i++) {
        p.coords[i] = ((double) rand() / RAND_MAX) * 100; // random values between 0 and 100
    }
    return p;
}

// Function to calculate the Euclidean distance between two points
double euclideanDistance(Point a, Point b) {
    double sum = 0.0;
    for (int i = 0; i < DIMENSIONS; i++) {
        sum += pow(a.coords[i] - b.coords[i], 2);
    }
    return sqrt(sum);
}

// Function to initialize clusters with random points
void initializeClusters(Cluster clusters[], int k, Point points[], int num_points) {
    for (int i = 0; i < k; i++) {
        clusters[i].centroid = points[rand() % num_points];
        clusters[i].point_count = 0;
    }
}

// Function to assign points to the nearest cluster
void assignPointsToClusters(Cluster clusters[], int k, Point points[], int num_points) {
    for (int i = 0; i < k; i++) {
        clusters[i].point_count = 0; // Reset count for new assignment
    }

    for (int i = 0; i < num_points; i++) {
        double min_distance = INFINITY;
        int cluster_index = -1;

        for (int j = 0; j < k; j++) {
            double distance = euclideanDistance(points[i], clusters[j].centroid);
            if (distance < min_distance) {
                min_distance = distance;
                cluster_index = j;
            }
        }
        clusters[cluster_index].points[clusters[cluster_index].point_count++] = points[i];
    }
}

// Function to update centroids of clusters
void updateCentroids(Cluster clusters[], int k) {
    for (int i = 0; i < k; i++) {
        if (clusters[i].point_count > 0) {
            for (int j = 0; j < DIMENSIONS; j++) {
                double sum = 0.0;
                for (int l = 0; l < clusters[i].point_count; l++) {
                    sum += clusters[i].points[l].coords[j];
                }
                clusters[i].centroid.coords[j] = sum / clusters[i].point_count;
            }
        }
    }
}

// Function to print clusters
void printClusters(Cluster clusters[], int k) {
    for (int i = 0; i < k; i++) {
        printf("Cluster %d:\n", i + 1);
        printf("Centroid: (");
        for (int j = 0; j < DIMENSIONS; j++) {
            printf("%f", clusters[i].centroid.coords[j]);
            if (j < DIMENSIONS - 1) printf(", ");
        }
        printf(")\nPoints:\n");
        for (int j = 0; j < clusters[i].point_count; j++) {
            printf("  (");
            for (int d = 0; d < DIMENSIONS; d++) {
                printf("%f", clusters[i].points[j].coords[d]);
                if (d < DIMENSIONS - 1) printf(", ");
            }
            printf(")\n");
        }
        printf("\n");
    }
}

int main() {
    srand(time(0)); // Seed random number generator
    int num_points = MAX_POINTS;
    Point points[MAX_POINTS];

    // Generate random points
    for (int i = 0; i < num_points; i++) {
        points[i] = generateRandomPoint();
    }

    int k = 3; // Number of clusters
    Cluster clusters[MAX_CLUSTERS];

    initializeClusters(clusters, k, points, num_points);

    for (int i = 0; i < MAX_ITERATIONS; i++) {
        assignPointsToClusters(clusters, k, points, num_points);
        updateCentroids(clusters, k);
    }

    printClusters(clusters, k);
    return 0;
}

