                        sum += /*inBuff[(col+ c) * channels+ (row + r)  * width* channels + ch];*/inBuff[((col+c) * channels)+ ((row+r) * width * channels)+ ch] * gaussianKernel[(r+offset)*KernelSize+(c+offset)];
