void createDirectory(Directory *dir, const char* name) {
    if (dir->fileCount < MAX_FILES) {
        File newDir;
        strncpy(newDir.name, name, MAX_NAME_LENGTH - 1);
        newDir.isDir = 1;
        dir->files[dir->fileCount++] = newDir;
        printf("Directory '%s' created in '%s' successfully!\n", name, dir->name);
    } else {
        printf("Error: Cannot create more directories in '%s'. Limit reached!\n", dir->name);
    }
}

void createFile(Directory *dir, const char* name) {
    if (dir->fileCount < MAX_FILES) {
        File newFile;
        strncpy(newFile.name, name, MAX_NAME_LENGTH - 1);
        newFile.isDir = 0;
        dir->files[dir->fileCount++] = newFile;
        printf("File '%s' created in '%s' successfully!\n", name, dir->name);
    } else {
        printf("Error: Cannot create more files in '%s'. Limit reached!\n", dir->name);
    }
}

void listContents(Directory *dir) {
    printf("\nContents of directory '%s':\n", dir->name);
    for (int i = 0; i < dir->fileCount; i++) {
        if (dir->files[i].isDir) {
            printf("[Dir]  %s\n", dir->files[i].name);
        } else {
            printf("[File] %s\n", dir->files[i].name);
        }
    }
}

void deleteFile(Directory *dir, const char* name) {
    for (int i = 0; i < dir->fileCount; i++) {
        if (strcmp(dir->files[i].name, name) == 0 && !dir->files[i].isDir) {
            printf("File '%s' deleted from '%s' successfully!\n", name, dir->name);
            for (int j = i; j < dir->fileCount - 1; j++) {
                dir->files[j] = dir->files[j + 1];
            }
            dir->fileCount--;
            return;
        }
    }
    printf("Error: File '%s' not found in '%s'.\n", name, dir->name);
}

void deleteDirectory(Directory *dir, const char* name) {
    for (int i = 0; i < dir->fileCount; i++) {
        if (strcmp(dir->files[i].name, name) == 0 && dir->files[i].isDir) {
            printf("Directory '%s' deleted from '%s' successfully!\n", name, dir->name);
            for (int j = i; j < dir->fileCount - 1; j++) {
                dir->files[j] = dir->files[j + 1];
            }
            dir->fileCount--;
            return;
        }
    }
    printf("Error: Directory '%s' not found in '%s'.\n", name, dir->name);
}

int main() {
    Directory rootDirectory;
    strncpy(rootDirectory.name, "Root", MAX_NAME_LENGTH - 1);
    rootDirectory.fileCount = 0;

    printf("Welcome to the Grateful File System Simulation!\n");

    createDirectory(&rootDirectory, "Documents");
    createDirectory(&rootDirectory, "Pictures");
    createFile(&rootDirectory, "README.txt");
    createFile(&rootDirectory, "hello.txt");

    listContents(&rootDirectory);

    deleteFile(&rootDirectory, "README.txt");
    createDirectory(&rootDirectory, "Videos");
    listContents(&rootDirectory);

    deleteDirectory(&rootDirectory, "Pictures");
    listContents(&rootDirectory);

    return 0;
}

