#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_PAGE_SIZE 1000

typedef struct {
    int page_number;
    char page_content[MAX_PAGE_SIZE];
} Page;

Page pages[1000];
int current_page = 0;
int total_pages = 0;

void load_book(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: Could not open file '%s'\n", filename);
        exit(1);
    }

    char line[MAX_PAGE_SIZE];
    int page_number = 0;
    bool is_new_page = true;

    while (fgets(line, MAX_PAGE_SIZE, file)) {
        if (is_new_page) {
            strcpy(pages[page_number].page_content, line);
            page_number++;
            is_new_page = false;
            if (++total_pages >= 1000) {
                printf("Error: Book file too large\n");
                exit(1);
            }
        } else {
            strcat(pages[page_number].page_content, line);
        }

        if (strlen(line) > MAX_PAGE_SIZE - 1) {
            printf("Warning: Page '%d' is too long\n", page_number);
        }
    }

    if (!is_new_page) {
        pages[page_number].page_number = page_number;
    }

    fclose(file);
}

void print_page(int page_number) {
    if (page_number < 0 || page_number >= total_pages) {
        printf("Error: Invalid page number\n");
        return;
    }

    printf("\nPage %d:\n%s", page_number + 1, pages[page_number].page_content);
}

void next_page() {
    if (current_page >= total_pages - 1) {
        printf("Error: Last page reached\n");
        return;
    }
    current_page++;
}

void prev_page() {
    if (current_page <= 0) {
        printf("Error: First page reached\n");
        return;
    }
    current_page--;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s <book.txt>\n", argv[0]);
        return 1;
    }

    load_book(argv[1]);

    while (true) {
        print_page(current_page);
        char command[10];
        scanf("%s", command);

        if (strcmp(command, "next") == 0) {
            next_page();
        } else if (strcmp(command, "prev") == 0) {
            prev_page();
        } else if (strcmp(command, "exit") == 0) {
            break;
        } else {
            printf("Error: Unknown command\n");
        }
    }

    return 0;
}

