//Falcon2-11B DATASET v1.0 Category: Traffic Flow Simulation ; Style: protected
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_NUM_CARS 100
#define MAX_TIME_STEPS 1000

typedef struct {
    int id;
    double x;
    double y;
    double speed;
    double direction;
    int lane;
    int status;
} Car;

int main() {
    srand(time(NULL)); // Seed random number generator

    Car cars[MAX_NUM_CARS]; // Array of cars
    int num_cars = 0; // Number of cars

    for (int i = 0; i < MAX_NUM_CARS; i++) {
        cars[i].id = i;
        cars[i].x = rand() % 100 - 50; // Random x-coordinate between -50 and 50
        cars[i].y = rand() % 100 - 50; // Random y-coordinate between -50 and 50
        cars[i].speed = 5.0 + (rand() % 10) - 5; // Random speed between 5 and 10
        cars[i].direction = rand() % 4; // Random direction (0: north, 1: east, 2: south, 3: west)
        cars[i].lane = rand() % 4; // Random lane (0: left, 1: middle, 2: right)
        cars[i].status = 1; // All cars start in the "moving" status

        if (num_cars == 0) {
            printf("Car %d is moving from (%d, %d) to (%d, %d) with speed %f and direction %d\n", i, cars[i].x, cars[i].y, cars[i].x + cars[i].speed * cars[i].direction, cars[i].y + cars[i].speed * cars[i].direction, cars[i].speed, cars[i].direction);
        } else {
            printf("Car %d is moving from (%d, %d) to (%d, %d) with speed %f and direction %d\n", i, cars[i].x, cars[i].y, cars[i].x + cars[i].speed * cars[i].direction, cars[i].y + cars[i].speed * cars[i].direction, cars[i].speed, cars[i].direction);
        }

        num_cars++;
    }

    printf("Initial positions of cars:\n");
    for (int i = 0; i < MAX_NUM_CARS; i++) {
        printf("Car %d: (%d, %d)\n", i, cars[i].x, cars[i].y);
    }

    // Traffic flow simulation loop
    for (int time_step = 0; time_step < MAX_TIME_STEPS; time_step++) {
        int num_moving_cars = 0; // Number of cars in the "moving" status
        int num_stopped_cars = 0; // Number of cars in the "stopped" status

        for (int i = 0; i < num_cars; i++) {
            if (cars[i].status == 1) {
                int next_x = cars[i].x + cars[i].speed * cars[i].direction;
                int next_y = cars[i].y + cars[i].speed * cars[i].direction;

                if (next_x < 0 || next_x >= 100 || next_y < 0 || next_y >= 100) {
                    cars[i].status = 0; // Car has reached the end of the road
                    num_stopped_cars++;
                } else {
                    cars[i].x = next_x;
                    cars[i].y = next_y;
                    num_moving_cars++;
                }
            } else if (cars[i].status == 0) {
                int next_x = cars[i].x + cars[i].speed * cars[i].direction;
                int next_y = cars[i].y + cars[i].speed * cars[i].direction;

                if (next_x >= 0 && next_x < 100 && next_y >= 0 && next_y < 100) {
                    cars[i].status = 1; // Car has entered the road
                    num_moving_cars++;
                }
            }
        }

        printf("Time step %d:\n", time_step + 1);
        printf("- %d moving cars\n", num_moving_cars);
        printf("- %d stopped cars\n", num_stopped_cars);
    }

    return 0;
}

//FormAI DATASET v1.0 Category: Periodic Table Quiz ; Style: scalable
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char symbol[3];
    char name[20];
    int atomicNumber;
    char category[20];
} element;

int main() {

    element periodicTable[118];     // array of elements
    FILE * fptr;                    // file pointer
    int i = 0;                      // index variable for array
    char buffer[100];               // buffer to store current line from file

    // open file in read-only mode
    if ((fptr = fopen("periodic_table.csv", "r")) == NULL) {
        printf("Error opening file. Exiting program.\n");
        return 1;
    }

    // read each line from file and parse data into array of elements
    while (fgets(buffer, 100, fptr) != NULL) {
        sscanf(buffer, "%[A-Za-z],%[A-Za-z],%d,%[A-Za-z ]", periodicTable[i].symbol, periodicTable[i].name, &periodicTable[i].atomicNumber, periodicTable[i].category);
        i++;
    }

    // close file
    fclose(fptr);

    // quiz app to guess element based on atomic number
    int score = 0;              // number of correct guesses
    int totalQuestions = 0;     // total number of questions asked
    char userInput[10];         // buffer to store user input
    int guesses = 0;            // number of guesses for current question
    int numQuestions;           // number of questions user wants to answer
    int randomNumber;           // randomly generated atomic number
    int index;                  // index of corresponding element in periodicTable array

    printf("Welcome to the Periodic Table Quiz!\n");
    printf("How many questions do you want to attempt? Enter a number: ");
    scanf("%d", &numQuestions);

    // loop through the number of quiz questions
    for (int q = 0; q < numQuestions; q++) {
        guesses = 0;
        totalQuestions++;

        // generate random atomic number for current question
        randomNumber = (rand() % 118) + 1;

        // find the corresponding element in the array
        for (int j = 0; j < i; j++) {
            if (periodicTable[j].atomicNumber == randomNumber) {
                index = j;
                break;
            }
        }

        // loop through guesses for current question
        while (guesses < 3) {
            printf("Question %d\n", totalQuestions);
            printf("What element has an atomic number of %d?\n", randomNumber);
            printf("Guess %d: ", guesses+1);
            scanf("%s", userInput);

            // check if user input matches element symbol or element name
            if (strcmp(userInput, periodicTable[index].symbol) == 0 || strcmp(userInput, periodicTable[index].name) == 0) {
                printf("Correct!\n");
                score++;
                break;
            } else {
                printf("Incorrect. Please try again.\n");
                guesses++;
            }
        }

        // if user runs out of guesses for current question
        if (guesses == 3) {
            printf("Sorry, you ran out of guesses. The answer was %s.\n", periodicTable[index].name);
        }
    }

    // display final score
    printf("Quiz complete! You scored %d out of %d. Thanks for playing!\n", score, totalQuestions);

    return 0;
}

//FormAI DATASET v1.0 Category: File Synchronizer ; Style: brave
#include<stdio.h>
#include<stdlib.h>
#include<string.h>
#include<dirent.h>
#include<sys/types.h>
#include<sys/stat.h>
#include<unistd.h>

void sync_files(char *source_dir, char *dest_dir){
	struct dirent *entry;
	DIR *dir = opendir(source_dir);
	if (!dir) {
		return;
	}

	/*Create destination directory if not exists*/
	mkdir(dest_dir, 0777); 

	while ((entry = readdir(dir)) != NULL) {
		char path[1024];
		snprintf(path, sizeof(path), "%s/%s", source_dir, entry->d_name);

		struct stat statbuf;
		stat(path, &statbuf);

		if (S_ISDIR(statbuf.st_mode)) {
			if (strcmp(".", entry->d_name) == 0 || strcmp("..", entry->d_name) == 0) {
				continue;
			}
			char dest_path[1024];
			snprintf(dest_path, sizeof(dest_path), "%s/%s", dest_dir, entry->d_name);
			sync_files(path, dest_path); /*Recursive sync for sub-directories*/
		} else {
			char dest_path[1024];
			snprintf(dest_path, sizeof(dest_path), "%s/%s", dest_dir, entry->d_name);
			FILE *source_file, *dest_file;
			source_file = fopen(path, "rb");
			if(source_file) { /*check if source file exists*/
				dest_file = fopen(dest_path, "wb");
				if(dest_file) { /*open destination file for writing*/
					char buffer[1024];
					size_t size;
					while ((size = fread(buffer, 1, sizeof(buffer), source_file)) > 0) {
						fwrite(buffer, 1, size, dest_file);
					}
					/*Close the files*/
					fclose(source_file);
					fclose(dest_file);
					printf("%s %s\n", path, dest_path);
				}
			}
		}
	}

	closedir(dir);
}

int main(){
	char source_path[]="/home/user/source_directory";
	char dest_path[]="/home/user/destination_directory";	
	sync_files(source_path, dest_path);
	return 0;
}

