/*
 * Airport Baggage Handling Simulation
 *
 * This program simulates the baggage handling process at an airport. It allows users
 * to configure the number of baggage handling systems, the number of bags to be
 * processed, and the number of passengers. The program then generates a report
 * showing the time it takes for each bag to be processed, the total time taken
 * for all bags to be processed, and the average time per bag.
 *
 * The program also allows users to specify a time delay for the baggage handling
 * system, which can be used to simulate the time it takes for the system to
 * process a bag.
 */

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define constants
#define MAX_BAGS 1000
#define MAX_SYSTEMS 10
#define MIN_DELAY 1
#define MAX_DELAY 5

// Define data structures
typedef struct {
    int num_bags;
    int num_systems;
    int delay;
} Config;

typedef struct {
    int bag_id;
    int system_id;
    int time_taken;
} Bag;

// Define functions
void generate_config(Config *config);
void generate_bags(Bag *bags, int num_bags, int num_systems);
void process_bags(Bag *bags, int num_bags, int num_systems, int delay);
void print_report(Bag *bags, int num_bags);

int main() {
    // Initialize configuration
    Config config;
    generate_config(&config);

    // Generate bags
    Bag bags[config.num_bags];
    generate_bags(bags, config.num_bags, config.num_systems);

    // Process bags
    process_bags(bags, config.num_bags, config.num_systems, config.delay);

    // Print report
    print_report(bags, config.num_bags);

    return 0;
}

// Generate a configuration for the simulation
void generate_config(Config *config) {
    config->num_bags = rand() % MAX_BAGS + 1;
    config->num_systems = rand() % MAX_SYSTEMS + 1;
    config->delay = rand() % (MAX_DELAY - MIN_DELAY) + MIN_DELAY;
}

// Generate a set of bags to be processed
void generate_bags(Bag *bags, int num_bags, int num_systems) {
    for (int i = 0; i < num_bags; i++) {
        bags[i].bag_id = i + 1;
        bags[i].system_id = rand() % num_systems + 1;
        bags[i].time_taken = 0;
    }
}

// Process a set of bags
void process_bags(Bag *bags, int num_bags, int num_systems, int delay) {
    for (int i = 0; i < num_bags; i++) {
        int system_id = bags[i].system_id;
        int bag_id = bags[i].bag_id;

        // Simulate time delay
        int time_taken = delay * (rand() % (MAX_DELAY - MIN_DELAY) + MIN_DELAY);

        // Print message
        printf("Bag %d handled by system %d, time taken: %d\n", bag_id, system_id, time_taken);

        // Update time taken
        bags[i].time_taken += time_taken;
    }
}

// Print a report of the simulation
void print_report(Bag *bags, int num_bags) {
    int total_time_taken = 0;

    // Calculate total time taken
    for (int i = 0; i < num_bags; i++) {
        total_time_taken += bags[i].time_taken;
    }

    // Calculate average time taken
    int average_time_taken = total_time_taken / num_bags;

    // Print report
    printf("Total time taken: %d\n", total_time_taken);
    printf("Average time taken: %d\n", average_time_taken);
}

