#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define PI 3.14159265358979323846

typedef struct {
    double voltage;
    double capacitance;
    double resistance;
    double time_constant;
} RC_filter;

void rc_filter_init(RC_filter* filter, double capacitance, double resistance) {
    filter->capacitance = capacitance;
    filter->resistance = resistance;
    filter->time_constant = capacitance * resistance;
    filter->voltage = 0.0;
}

void rc_filter_update(RC_filter* filter, double input_voltage, double dt) {
    double charging_current = (input_voltage - filter->voltage) / filter->time_constant;
    filter->voltage += charging_current * dt;
}

int main() {
    double input_frequency = 1.0; // Hz
    double input_amplitude = 1.0;
    double capacitance = 1.0e-6; // Farads
    double resistance = 1.0e3; // Ohms
    double dt = 1.0e-6; // Seconds
    double time = 0.0;

    RC_filter rc_filter;

    rc_filter_init(&rc_filter, capacitance, resistance);

    printf("RC Low-Pass Filter Simulation\n");
    printf("-----------------------------\n");

    for (int i = 0; i < 100000; i++) {
        double input_voltage = input_amplitude * sin(2 * PI * input_frequency * time);
        rc_filter_update(&rc_filter, input_voltage, dt);

        double output_voltage = rc_filter.voltage;

        printf("%.6f\t%.6f\t%.6f\n", time, input_voltage, output_voltage);

        time += dt;
    }

    return 0;
}

