#include <arpa/inet.h>

#define PORT 8080

struct server_context {
    int sock;
    socklen_t client_len;
    char client_addr[INET_ADDRSTRLEN];
};

void handle_request(int sock, struct server_context *sc) {
    char buffer[1024];
    int bytes_read;

    printf("Received request from %s\n", sc->client_addr);

    // Read request data
    bytes_read = recv(sock, buffer, 1024, 0);
    if (bytes_read <= 0) {
        printf("Error reading request data\n");
        close(sock);
        return;
    }

    // Process request data
    if (strcmp(buffer, "/hello") == 0) {
        char *message = "Hello, world!";
        send(sock, message, strlen(message), 0);
    } else if (strcmp(buffer, "/404") == 0) {
        char *message = "Not found";
        send(sock, message, strlen(message), 0);
    } else {
        printf("Unsupported request\n");
        close(sock);
        return;
    }
}

int main(int argc, char *argv[]) {
    int sock;
    struct server_context sc;

    // Create socket
    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket");
        exit(1);
    }

    // Set address and port
    sc.sock = sock;
    sc.client_len = sizeof(sc.client_addr);
    inet_pton(AF_INET, "127.0.0.1", &sc.client_addr);
    sc.client_addr[INET_ADDRSTRLEN - 1] = '\0';

    // Bind socket
    if (bind(sock, (struct sockaddr *)&sc.client_addr, sizeof(sc.client_addr)) < 0) {
        perror("bind");
        exit(1);
    }

    // Listen for incoming connections
    if (listen(sock, 3) < 0) {
        perror("listen");
        exit(1);
    }

    printf("Server listening on port %d...\n", PORT);

    while (1) {
        // Accept incoming connection
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_sock = accept(sock, (struct sockaddr *)&client_addr, &client_len);
        if (client_sock < 0) {
            perror("accept");
            exit(1);
        }

        // Handle request
        handle_request(client_sock, &sc);

        // Close connection
        close(client_sock);
    }

    return 0;
}

