#define WIDTH 21
#define HEIGHT 21
#define MARGIN 1

int maze[HEIGHT][WIDTH];
bool visited[HEIGHT][WIDTH];
int dx[4] = {-1, 1, 1, -1};
int dy[4] = {-1, -1, 1, 1};

void print_maze() {
    for (int i = 0; i < HEIGHT; ++i) {
        for (int j = 0; j < WIDTH; ++j) {
            printf(maze[i][j] ? "  " : "##");
        }
        printf("\n");
    }
}

bool is_valid(int x, int y) {
    return x >= 0 && x < HEIGHT && y >= 0 && y < WIDTH;
}

bool dfs(int x, int y) {
    visited[x][y] = true;

    printf("(%d, %d) ", x, y);
    fflush(stdout);

    for (int i = 0; i < 4; ++i) {
        int nx = x + dx[i];
        int ny = y + dy[i];

        if (is_valid(nx, ny) && !visited[nx][ny] && maze[nx][ny]) {
            if (dfs(nx, ny))
                return true;
        }
    }

    visited[x][y] = false;
    return false;
}

