#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX 255

void qr_code_generate(char *data)
{
    int i, j, k, l, m, n, size = 0;
    char **matrix = NULL;

    // Calculate the size of the QR code based on the length of the data
    n = (int)ceil((double)strlen(data) / 8);
    size = n * n;

    // Allocate memory for the matrix
    matrix = (char **)malloc(size * sizeof(char *));
    for (i = 0; i < size; i++)
    {
        matrix[i] = (char *)malloc(size * sizeof(char));
    }

    // Create the QR code
    for (i = 0; i < size; i++)
    {
        for (j = 0; j < size; j++)
        {
            matrix[i][j] = 0;
        }
    }

    // Encode the data into the QR code
    k = 0;
    for (i = 0; i < n; i++)
    {
        for (j = 0; j < n; j++)
        {
            for (l = 0; l < 8; l++)
            {
                if (k < strlen(data) && data[k] == '1')
                {
                    matrix[i][j] = 1;
                }
                k++;
            }
        }
    }

    // Print the QR code
    for (i = 0; i < size; i++)
    {
        for (j = 0; j < size; j++)
        {
            printf("%c ", matrix[i][j]);
        }
        printf("\n");
    }

    // Free the memory
    for (i = 0; i < size; i++)
    {
        free(matrix[i]);
    }
    free(matrix);
}

int main()
{
    char data[] = "Hello, world!";

    qr_code_generate(data);

    return 0;
}

