{
    printf("\n%s Array: ", s);
    for (int i = 0; i < n; i++)
        printf("%d ", arr[i]);
}

// Function to perform bubble sort
void bubbleSort(int arr[], int n)
{
    int temp;
    for (int i = 0; i < n-1; i++)
        for (int j = 0; j < n-i-1; j++)
            if (arr[j] > arr[j+1])
            {
                temp = arr[j];
                arr[j] = arr[j+1];
                arr[j+1] = temp;
            }
}

