// Struct to hold sentiment score and corresponding word
typedef struct {
    int score;
    char word[50];
} SentimentWord;

#define NUM_WORDS 1000
SentimentWord words[NUM_WORDS];

// Initialize sentiment scores for words
void initialize_scores() {
    int i;
    for (i = 0; i < NUM_WORDS; i++) {
        words[i].score = 0;
    }
    // Seed some words with sentiment scores
    strcpy(words[0].word, "happy");
    words[0].score = 5;
    strcpy(words[1].word, "sad");
    words[1].score = -5;
    strcpy(words[2].word, "love");
    words[2].score = 3;
    strcpy(words[3].word, "hate");
    words[3].score = -3;
    strcpy(words[4].word, "joy");
    words[4].score = 4;
    strcpy(words[5].word, "anger");
    words[5].score = -4;
    strcpy(words[6].word, "excited");
    words[6].score = 2;
    strcpy(words[7].word, "depressed");
    words[7].score = -2;
    strcpy(words[8].word, "amazing");
    words[8].score = 6;
    strcpy(words[9].word, "terrible");
    words[9].score = -6;
}

// Function to find sentiment score of given text
int calculate_sentiment(char *text) {
    int i, length, score = 0;
    length = strlen(text);

    for (i = 0; i < length; i++) {
        text[i] = tolower(text[i]);
    }

    for (i = 0; i < NUM_WORDS; i++) {
        if (strcmp(text, words[i].word) == 0) {
            score += words[i].score;
            break;
        }
    }

    // Add sentiment scores of individual words
    for (i = 0; i < length; i++) {
        switch (text[i]) {
            case 'a':
            case 'e':
            case 'i':
            case 'o':
            case 'u':
                score += 1;
                break;
            case ' ':
                // Add sentiment score of preceding word
                score += words[i - 1].score;
                break;
            default:
                break;
        }
    }

    return score;
}

// Function to print sentiment score and corresponding words
void print_sentiment(char *text, int score) {
    int i;
    printf("Text: %s\n", text);
    printf("Sentiment Score: %d\n", score);

    // Print sentiment words and their scores
    for (i = 0; i < NUM_WORDS && score > words[i].score; i++) {
        if (score >= words[i].score) {
            printf("%s: %d\n", words[i].word, words[i].score);
        }
    }
}

int main() {
    char text[100];
    int score;

    initialize_scores(); // Initialize sentiment scores

    printf("Enter text:\n");
    scanf("%s", text);

    score = calculate_sentiment(text); // Calculate sentiment score

    print_sentiment(text, score); // Print sentiment score and corresponding words

    return 0;
}

