    {
        return x;
    }
    return deQuy(x, n - 1) + pow(x, n);
}

float deQuyDuoi(float x, int n, float y = 0)
{
    if(n == 0)
        return y;
    return deQuyDuoi(x, n - 1, y + pow(x, n));
